import { useCallback, useState } from "react"

import {
  INITIAL_FILE_BATCH_SIZE,
  type DiffStyle,
  type DiffThemeMode,
} from "@/features/review/model/diff/viewer-utils"

export function useMergeRequestDiffUiState() {
  const [diffThemeMode, setDiffThemeMode] = useState<DiffThemeMode>("system")
  const [collapsedFileKeys, setCollapsedFileKeys] = useState<Set<string>>(new Set())

  const [filenameFilter, setFilenameFilter] = useState("")
  const [diffStyle, setDiffStyle] = useState<DiffStyle>("split")
  const [wrapLines, setWrapLines] = useState(false)
  const [showLineNumbers, setShowLineNumbers] = useState(true)
  const [visibleResetToken, setVisibleResetToken] = useState(0)
  const [visibleWindow, setVisibleWindow] = useState<{
    key: string
    count: number
  }>({
    key: "",
    count: INITIAL_FILE_BATCH_SIZE,
  })

  const resetVisibleFileCount = useCallback(() => {
    setVisibleResetToken((current) => current + 1)
  }, [])

  const cycleDiffThemeMode = useCallback(() => {
    setDiffThemeMode((current) => {
      if (current === "system") {
        return "light"
      }
      if (current === "light") {
        return "dark"
      }
      return "system"
    })
  }, [])

  return {
    diffThemeMode,
    setDiffThemeMode,
    collapsedFileKeys,
    setCollapsedFileKeys,
    filenameFilter,
    setFilenameFilter,
    diffStyle,
    setDiffStyle,
    wrapLines,
    setWrapLines,
    showLineNumbers,
    setShowLineNumbers,
    visibleResetToken,
    visibleWindow,
    setVisibleWindow,
    resetVisibleFileCount,
    cycleDiffThemeMode,
  }
}

import { isIP } from "node:net"

const allowPrivateHosts = process.env.GITLAB_ALLOW_PRIVATE_HOSTS === "1"

const isPrivateIpv4 = (hostname: string) => {
  const parts = hostname.split(".").map((part) => Number.parseInt(part, 10))
  if (parts.length !== 4 || parts.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) {
    return true
  }

  const [first, second] = parts
  if (
    first === 10 ||
    first === 127 ||
    first === 0 ||
    (first === 169 && second === 254) ||
    (first === 172 && second >= 16 && second <= 31) ||
    (first === 192 && second === 168) ||
    (first === 100 && second >= 64 && second <= 127) ||
    (first === 198 && (second === 18 || second === 19)) ||
    first >= 224
  ) {
    return true
  }

  return false
}

const isPrivateIpv6 = (hostname: string) => {
  const normalized = hostname.toLowerCase()
  if (normalized === "::" || normalized === "::1") {
    return true
  }

  if (
    normalized.startsWith("fc") ||
    normalized.startsWith("fd") ||
    normalized.startsWith("fe8") ||
    normalized.startsWith("fe9") ||
    normalized.startsWith("fea") ||
    normalized.startsWith("feb") ||
    normalized.startsWith("2001:db8:")
  ) {
    return true
  }

  if (normalized.startsWith("::ffff:")) {
    return isPrivateIpv4(normalized.slice("::ffff:".length))
  }

  return false
}

const isPrivateHostname = (hostname: string) =>
  hostname === "localhost" ||
  hostname.endsWith(".localhost") ||
  hostname.endsWith(".local")

const isPrivateTarget = (hostname: string) => {
  const normalized = hostname.trim().toLowerCase()
  if (!normalized) {
    return true
  }

  const ipKind = isIP(normalized)
  if (ipKind === 4) {
    return isPrivateIpv4(normalized)
  }
  if (ipKind === 6) {
    return isPrivateIpv6(normalized)
  }

  return isPrivateHostname(normalized)
}

export const normalizeGitLabInstanceUrl = (input: string) => {
  const trimmed = input.trim()
  if (!trimmed) {
    throw new Error("GitLab instance URL is required.")
  }

  const withProtocol = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`

  let parsed: URL
  try {
    parsed = new URL(withProtocol)
  } catch {
    throw new Error("GitLab instance URL is invalid.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("GitLab instance URL must use http or https.")
  }
  if (!parsed.hostname.trim()) {
    throw new Error("GitLab instance URL is invalid.")
  }
  if (parsed.username || parsed.password) {
    throw new Error("GitLab instance URL must not include credentials.")
  }
  if (!allowPrivateHosts && isPrivateTarget(parsed.hostname)) {
    throw new Error(
      "GitLab instance URL must use a public host. Set GITLAB_ALLOW_PRIVATE_HOSTS=1 to allow private hosts.",
    )
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  return pathname ? `${parsed.origin}${pathname}` : parsed.origin
}

export const REVIEW_GATE_THRESHOLDS: Record<
  ReviewGateStrictness,
  Record<ReviewFindingLike["severity"], number>
> = {
  quiet: {
    high: 0.88,
    med: 0.92,
    low: 0.96,
  },
  balanced: {
    high: 0.8,
    med: 0.88,
    low: 0.93,
  },
  thorough: {
    high: 0.72,
    med: 0.82,
    low: 0.89,
  },
}

const INVALID_EVIDENCE_VALUES = new Set(["n/a", "none", "unknown"])

export const normalizeReviewGateStrictness = (value: unknown): ReviewGateStrictness => {
  if (value === "quiet" || value === "balanced" || value === "thorough") {
    return value
  }
  return REVIEW_GATE_DEFAULTS.strictness
}

export const normalizeReviewGateSettings = (value: unknown): ReviewGateSettings => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return { ...REVIEW_GATE_DEFAULTS }
  }

  const candidate = value as Record<string, unknown>
  return {
    personaMode: normalizeReviewPersonaMode(candidate.personaMode),
    persona: normalizeReviewPersona(candidate.persona),
    personaTemplates: normalizeReviewPersonaTemplateOverrides(candidate.personaTemplates),
    strictness: normalizeReviewGateStrictness(candidate.strictness),
    requireEvidence: candidate.requireEvidence === true,
    securityBoost: candidate.securityBoost === true,
  }
}

export const getReviewPersonaPasses = (settings: ReviewGateSettings) => {
  if (settings.personaMode === "disabled") {
    return [] as ReviewPersona[]
  }

  if (settings.personaMode === "multi") {
    return [...REVIEW_PERSONA_VALUES]
  }

  return [normalizeReviewPersona(settings.persona)]
}

export const normalizeEvidence = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

export const hasStructuredEvidence = (value: unknown) => {
  const normalized = normalizeEvidence(value).toLowerCase()
  if (!normalized) {
    return false
  }
  return !INVALID_EVIDENCE_VALUES.has(normalized)
}

const getConfidenceThreshold = ({
  severity,
  settings,
}: {
  severity: ReviewFindingLike["severity"]
  settings: ReviewGateSettings
}) => {
  const baseThreshold = REVIEW_GATE_THRESHOLDS[settings.strictness][severity]
  if (settings.securityBoost && severity === "high") {
    return Math.max(0, baseThreshold - 0.05)
  }
  return baseThreshold
}

const normalizeConfidence = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return 0
  }
  return Math.max(0, Math.min(1, value))
}

export const dedupeReviewFindingsByConfidence = <T extends ReviewFindingLike>(findings: T[]) => {
  const deduped = new Map<string, T>()

  for (const finding of findings) {
    const key = buildReviewCommentFeedbackKey({
      file: finding.file,
      side: finding.side,
      line: finding.line,
      title: finding.title,
    })

    const current = deduped.get(key)
    if (!current) {
      deduped.set(key, finding)
      continue
    }

    const currentConfidence = normalizeConfidence(current.confidence)
    const nextConfidence = normalizeConfidence(finding.confidence)
    if (nextConfidence > currentConfidence) {
      deduped.set(key, finding)
      continue
    }

    if (nextConfidence === currentConfidence) {
      const currentEvidenceLength = normalizeEvidence(current.evidence).length
      const nextEvidenceLength = normalizeEvidence(finding.evidence).length
      if (nextEvidenceLength > currentEvidenceLength) {
        deduped.set(key, finding)
      }
    }
  }

  return Array.from(deduped.values())
}

export const applyReviewGate = <T extends ReviewFindingLike>({
  findings,
  settings,
}: {
  findings: T[]
  settings: ReviewGateSettings
}): ApplyReviewGateResult<T> => {
  const suppressedByReason: ReviewGateSuppressedByReason = {
    lowConfidence: 0,
    missingEvidence: 0,
  }

  const kept: T[] = []
  let suppressedFindingsCount = 0

  for (const finding of findings) {
    const threshold = getConfidenceThreshold({
      severity: finding.severity,
      settings,
    })

    const hasConfidence = normalizeConfidence(finding.confidence) >= threshold
    if (!hasConfidence) {
      suppressedByReason.lowConfidence += 1
    }

    const hasEvidence = !settings.requireEvidence || hasStructuredEvidence(finding.evidence)
    if (!hasEvidence) {
      suppressedByReason.missingEvidence += 1
    }

    if (hasConfidence && hasEvidence) {
      kept.push(finding)
    } else {
      suppressedFindingsCount += 1
    }
  }

  const filteredFindings = dedupeReviewFindingsByConfidence(kept)

  return {
    filteredFindings,
    suppressedFindingsCount,
    suppressedByReason,
  }
}

const extractErrorMessage = (payload: unknown, fallback: string) => {
  if (
    payload &&
    typeof payload === "object" &&
    "error" in payload &&
    typeof (payload as { error?: unknown }).error === "string"
  ) {
    return (payload as { error: string }).error
  }
  return fallback
}

export function RepoProjectTabs({
  integrationId,
  repoRouteId,
  instanceUrl,
  projectId,
  projectName,
  projectPath,
  integrationStatus,
  integrationStatusLabel,
  integrationStatusVariant,
  lastWebhookReceivedAt,
  lastHookSyncAt,
  lastError,
}: RepoProjectTabsProps) {
  const pathname = usePathname()
  const router = useRouter()
  const searchParams = useSearchParams()
  const reviewDataPrewarmExpiryRef = useRef<Map<string, number>>(new Map())
  const reviewDataPrewarmInFlightRef = useRef<Set<string>>(new Set())
  const tabParam = searchParams.get("tab")
  const activeTab = isRepoProjectTabValue(tabParam) ? tabParam : DEFAULT_REPO_PROJECT_TAB
  const graphTraceBranch = searchParams.get("graphTraceBranch")?.trim() || undefined

const loadMergeRequests = useCallback(async () => {
  const response = await fetch("/api/gitlab", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      action: "merge-requests",
      instanceUrl,
      integrationId,
      projectId,
      perPage: MAX_MR_ROWS,
    }),
  })
  const parsedPayload = await parseJsonResponse(response)
  const payload = parsedPayload.ok ? parsedPayload.value : null
  if (!response.ok) {
    throw new Error(extractErrorMessage(payload, "Failed to load merge requests."))
  }

  const data =
    payload &&
    typeof payload === "object" &&
    "data" in payload &&
    Array.isArray((payload as { data?: unknown }).data)
      ? ((payload as { data: unknown[] }).data as MergeRequest[])
      : []

  return data
}, [instanceUrl, integrationId, projectId])

const loadIndexing = useCallback(async () => {
  const response = await fetch(
    `/api/gitlab/integrations/${integrationId}/index/runs?page=1&limit=${MAX_RUN_ROWS}`,
    {
      method: "GET",
      headers: { "content-type": "application/json" },
    },
  )
  const parsedPayload = await parseJsonResponse(response)
  const payload = parsedPayload.ok ? parsedPayload.value : null
  if (!response.ok) {
    throw new Error(extractErrorMessage(payload, "Failed to load indexing summary."))
  }

  const typedPayload = payload as IndexRunsPayload
  return typedPayload.queue ?? null
}, [integrationId])

const handleRefresh = useCallback(() => {
  void Promise.all([
    refetchMergeRequests(),
    refetchIndexing(),
  ])
}, [refetchIndexing, refetchMergeRequests])

const prewarmReviewData = useCallback((mergeRequestIid: string) => {
  const normalizedMergeRequestIid = mergeRequestIid.trim()
  if (!normalizedMergeRequestIid) {
    return
  }

  const now = Date.now()
  const cachedUntil = reviewDataPrewarmExpiryRef.current.get(normalizedMergeRequestIid) ?? 0
  if (cachedUntil > now || reviewDataPrewarmInFlightRef.current.has(normalizedMergeRequestIid)) {
    return
  }

  reviewDataPrewarmInFlightRef.current.add(normalizedMergeRequestIid)
  const payload = {
    instanceUrl,
    integrationId,
    projectId,
    mergeRequestIid: normalizedMergeRequestIid,
  }

  void Promise.allSettled([
    fetch("/api/gitlab", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        action: "merge-request",
        ...payload,
      }),
    }).then((response) => response.ok),
    fetch("/api/gitlab/diff/manifest", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(payload),
    }).then((response) => response.ok),
  ])
    .then((results) => {
      const succeeded = results.some(
        (result) => result.status === "fulfilled" && result.value,
      )
      reviewDataPrewarmExpiryRef.current.set(
        normalizedMergeRequestIid,
        Date.now() + (succeeded ? REVIEW_DATA_PREWARM_TTL_MS : 10_000),
      )
    })
    .catch(() => {
      reviewDataPrewarmExpiryRef.current.set(normalizedMergeRequestIid, Date.now() + 10_000)
    })
    .finally(() => {
      reviewDataPrewarmInFlightRef.current.delete(normalizedMergeRequestIid)
    })
}, [instanceUrl, integrationId, projectId])

const webhookAt = lastWebhookReceivedAt ? new Date(lastWebhookReceivedAt) : null
const syncAt = lastHookSyncAt ? new Date(lastHookSyncAt) : null

const handleTabChange = useCallback(
  (nextValue: string) => {
    if (!isRepoProjectTabValue(nextValue)) {
      return
    }

    const nextParams = new URLSearchParams(searchParams.toString())
    if (nextValue === DEFAULT_REPO_PROJECT_TAB) {
      nextParams.delete("tab")
    } else {
      nextParams.set("tab", nextValue)
    }

    const query = nextParams.toString()
    router.replace(query ? `${pathname}?${query}` : pathname, { scroll: false })
  },
  [pathname, router, searchParams],
)

return (
  <Tabs value={activeTab} onValueChange={handleTabChange} className="w-full">
    <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">

