    {
      id: "user-1",
      name: "Admin",
      email: "admin@example.com",
      emailVerified: true,
      isAdmin: true,
      isAdminPersisted: true,
      isAdminManagedByAllowlist: false,
      createdAt: "2026-01-01T00:00:00.000Z",
      updatedAt: "2026-01-01T00:00:00.000Z",
    },
  ])

const updateUserAdminPersistedFlag = mock(async ({ userId, isAdmin }: { userId: string; isAdmin: boolean }) => ({
  id: userId,
  name: "Target",
  email: "target@example.com",
  emailVerified: true,
  isAdmin,
  isAdminPersisted: isAdmin,
  isAdminManagedByAllowlist: false,
  createdAt: "2026-01-01T00:00:00.000Z",
  updatedAt: "2026-01-02T00:00:00.000Z",
