}))
mock.module("@/lib/admin-access", () => ({
  ADMIN_ACCESS_DENIED_MESSAGE: "Admin permissions are required.",
  getSessionAdminAccess: async () => {
    const userId = options?.userId === undefined ? "admin-1" : options.userId
    return {
