describe("admin users route", () => {
  test("GET returns 401 for unauthenticated users", async () => {
    const { GET, listAdminManagedUsers } = await loadRouteModule({ userId: null })

    const response = await GET(new Request("http://localhost/api/admin/users"))
    const body = await response.json()

    expect(response.status).toBe(401)
    expect(body).toEqual({ error: "Unauthorized" })
    expect(listAdminManagedUsers).toHaveBeenCalledTimes(0)
  })

  test("GET returns 403 for non-admin users", async () => {
    const { GET, listAdminManagedUsers } = await loadRouteModule({ isAdmin: false })

    const response = await GET(new Request("http://localhost/api/admin/users"))
    const body = await response.json()

    expect(response.status).toBe(403)
    expect(body).toEqual({ error: "Admin permissions are required." })
    expect(listAdminManagedUsers).toHaveBeenCalledTimes(0)
  })

test("GET returns managed users for admins", async () => {
  const { GET, listAdminManagedUsers } = await loadRouteModule()

  const response = await GET(new Request("http://localhost/api/admin/users"))
  const body = await response.json()

  expect(response.status).toBe(200)
  expect(body.data.users).toHaveLength(1)
  expect(listAdminManagedUsers).toHaveBeenCalledTimes(1)
})

test("PATCH blocks self-demotion", async () => {
  const { PATCH, updateUserAdminPersistedFlag } = await loadRouteModule({ userId: "admin-1" })

  const response = await PATCH(
    new Request("http://localhost/api/admin/users", {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ userId: "admin-1", isAdmin: false }),
    }),
  )
  const body = await response.json()

  expect(response.status).toBe(400)
  expect(body).toEqual({ error: "You cannot remove your own admin access." })
  expect(updateUserAdminPersistedFlag).toHaveBeenCalledTimes(0)
})

  test("PATCH updates user admin role", async () => {
    const { PATCH, updateUserAdminPersistedFlag } = await loadRouteModule({ userId: "admin-1" })

    const response = await PATCH(
      new Request("http://localhost/api/admin/users", {
        method: "PATCH",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ userId: "target-user", isAdmin: true }),
      }),
    )
    const body = await response.json()

    expect(response.status).toBe(200)
    expect(body.data.user.id).toBe("target-user")
    expect(body.data.user.isAdmin).toBe(true)
    expect(updateUserAdminPersistedFlag).toHaveBeenCalledWith({
      userId: "target-user",
      isAdmin: true,
    })
  })
})

