import { describe, expect, test } from "bun:test"

import { computeImpactLevel, computeImpactScore } from "./impact-score"

describe("impact score", () => {
  test("returns bounded score from graph counts", () => {
    const score = computeImpactScore({
      callersCount: 10,
      dependentsCount: 10,
      calleesCount: 10,
      dependenciesCount: 10,
      affectedFilesCount: 10,
    })

    expect(score).toBeGreaterThan(0)
    expect(score).toBeLessThanOrEqual(100)
  })

  test("computes high/med/low levels", () => {
    expect(computeImpactLevel(10)).toBe("low")
    expect(computeImpactLevel(40)).toBe("med")
    expect(computeImpactLevel(80)).toBe("high")
  })

  test("is monotonic as counts increase", () => {
    const low = computeImpactScore({
      callersCount: 1,
      dependentsCount: 0,
      calleesCount: 0,
      dependenciesCount: 0,
      affectedFilesCount: 1,
    })
    const high = computeImpactScore({
      callersCount: 20,
      dependentsCount: 20,
      calleesCount: 20,
      dependenciesCount: 20,
      affectedFilesCount: 20,
    })

    expect(high).toBeGreaterThan(low)
  })
})

export const formatPendingPruneEta = (pendingPruneAt: string | null, nowMs: number) => {
  const pruneStartMs = parseTimestampMs(pendingPruneAt)
  if (pruneStartMs === null) {
    return null
  }

  const graceMs = Math.max(
    60_000,
    Number.parseInt(process.env.NEXT_PUBLIC_INDEXER_BRANCH_PRUNE_GRACE_MS ?? "", 10) || 86_400_000,
  )
  const remainingMs = pruneStartMs + graceMs - nowMs
  if (remainingMs <= 0) {
    return "eligible now"
  }

  const totalMinutes = Math.ceil(remainingMs / 60_000)
  const days = Math.floor(totalMinutes / (24 * 60))
  const hours = Math.floor((totalMinutes % (24 * 60)) / 60)
  const minutes = totalMinutes % 60

  if (days > 0) {
    return `${days}d ${hours}h`
  }
  if (hours > 0) {
    return `${hours}h ${minutes}m`
  }
  return `${minutes}m`
}

