export const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

export const parseSseRecord = (raw: string): Record<string, unknown> | null => {
  try {
    return asRecord(JSON.parse(raw))
  } catch {
    return null
  }
}

export const normalizeRunError = (value: unknown): string | null => {
  if (typeof value === "string" && value.trim().length > 0) {
    return value
  }

  if (value && typeof value === "object" && !Array.isArray(value)) {
    const message = asString((value as { message?: unknown }).message)
    if (message) {
      return message
    }

    const code = asString((value as { code?: unknown }).code)
    if (code) {
      return `Error code: ${code}`
    }

    try {
      return JSON.stringify(value)
    } catch {
      return "Unexpected run error."
    }
  }

  return null
}

export const extractErrorMessage = (payload: unknown, fallback: string) => {
  if (
    payload &&
    typeof payload === "object" &&
    "error" in payload &&
    typeof (payload as { error?: unknown }).error === "string"
  ) {
    return (payload as { error: string }).error
  }
  return fallback
}

export const formatDateTime = (value: string | null | undefined) => {
  if (!value) {
    return "Never"
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "Unknown"
  }
  return parsed.toLocaleString()
}

export const shortSha = (value: string | null | undefined) => {
  if (!value) {
    return "n/a"
  }
  return value.slice(0, 12)
}

export const parseTimestampMs = (value: string | null | undefined) => {
  if (!value) {
    return null
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return null
  }
  return parsed.getTime()
}

export const asString = (value: unknown) =>
  typeof value === "string" && value.trim().length > 0 ? value : null

export const truncateText = (value: string, max = 160) =>
  value.length > max ? `${value.slice(0, Math.max(0, max - 3))}...` : value

export const normalizeWhitespace = (value: string) => value.replace(/\s+/g, " ").trim()

export const describeRunError = (value: string): { summary: string; hint: string | null } => {
  const normalized = normalizeWhitespace(value)
  const embeddingFailureMatch = normalized.match(/^Embedding failed for ([^:]+):\s*(.+)$/i)
  const summary = embeddingFailureMatch
    ? `${embeddingFailureMatch[2]} (${embeddingFailureMatch[1]})`
    : normalized
  const lower = normalized.toLowerCase()

  if (lower.includes("missing embedding api key")) {
    return {
      summary: truncateText(summary, 220),
      hint: "Set INDEXER_EMBEDDING_API_KEY, OPENAI_API_KEY, or AI_API_TOKEN, then retry.",
    }
  }

  if (lower.includes("econnrefused")) {
    return {
      summary: truncateText(summary, 220),
      hint: "Connection refused by a dependency. Check DATABASE_URL, GitLab host, and embedding provider base URL/network reachability.",
    }
  }

  return {
    summary: truncateText(summary, 220),
    hint: null,
  }
}

export const formatAge = (ageMs: number | null) => {
  if (ageMs === null || ageMs < 0) {
    return "unknown"
  }

  const minutes = Math.floor(ageMs / 60_000)
  if (minutes < 1) {
    return "under 1m"
  }
  return `${minutes}m`
}

export type WorkerHealth = {
  level: "offline" | "healthy" | "busy" | "unknown"
  label: string
  message: string
}

export const deriveWorkerHealth = ({
  queueSummary,
  workerTelemetry,
  nowMs = Date.now(),
}: {
  queueSummary: IndexRunsPayload["queue"] | null
  workerTelemetry: IndexRunsPayload["worker"] | null
  nowMs?: number
}): WorkerHealth => {

if (workerTelemetry) {
  const heartbeatAgeMs = workerTelemetry.heartbeatAgeMs
  if (workerTelemetry.lastHeartbeatAt === null) {
    return {
      level: "offline",
      label: "offline",
      message: "No worker heartbeat has been recorded yet.",
    }
  }

  if (!workerTelemetry.isOnline) {
    return {
      level: "offline",
      label: "offline",
      message: `Last heartbeat ${formatAge(heartbeatAgeMs)} ago.`,
    }
  }

  return {
    level: "healthy",
    label: "online",
    message: `Last heartbeat ${formatAge(heartbeatAgeMs)} ago.`,
  }
}

if (!queueSummary) {
  return {
    level: "unknown",
    label: "unknown",
    message: "No queue telemetry yet.",
  }
}

const pending = queueSummary.pending
const processing = queueSummary.processing
const hasBacklog = pending + processing > 0
const oldestPendingAgeMs = (() => {
  const ts = parseTimestampMs(queueSummary.oldestPendingAt)
  return ts === null ? null : nowMs - ts
})()
const lastProcessedAgeMs = (() => {
  const ts = parseTimestampMs(queueSummary.lastProcessedAt)
  return ts === null ? null : nowMs - ts
})()
const hasRecentActivity = (
  lastProcessedAgeMs !== null &&
  lastProcessedAgeMs <= WORKER_RECENT_ACTIVITY_MS
)

if (
  pending > 0 &&
  oldestPendingAgeMs !== null &&
  oldestPendingAgeMs >= WORKER_PENDING_STALE_MS &&
  !hasRecentActivity
) {
  return {
    level: "offline",
    label: "likely offline",
    message: `Pending jobs oldest age: ${formatAge(oldestPendingAgeMs)}.`,
  }
}

  if (hasBacklog) {
    return {
      level: "busy",
      label: "active",
      message: `Queue backlog: pending ${pending}, processing ${processing}.`,
    }
  }

  if (hasRecentActivity) {
    return {
      level: "healthy",
      label: "healthy",
      message: `Last processed ${formatAge(lastProcessedAgeMs)} ago.`,
    }
  }

  return {
    level: "unknown",
    label: "unknown",
    message: "No recent processed jobs and no backlog.",
  }
}

export const buildBranchKey = (branch: string, configHash: string) =>
  `${branch}\u0000${configHash}`

export const isPipelineActiveStatus = (status: string | null | undefined) =>
  Boolean(status && PIPELINE_ACTIVE_STATUSES.has(status))

export const resolveRunGraphBuildStatus = (run: BranchLastRun | null): string | null => {
  const runStats = asRecord(run?.stats)
  const graphStats = asRecord(runStats?.graph)
  const graphStatus = asString(graphStats?.status)
  return graphStatus?.toLowerCase() ?? null
}

export const resolveBranchGraphStatus = (branch: IndexBranch): BranchGraphStatus => {
  if (branch.lastReadyRunId) {
    const snapshotStatus = asString(branch.lastReadyGraphSnapshotStatus)?.toLowerCase()
    if (snapshotStatus === "ready") {
      return "ready"
    }
    if (snapshotStatus === "graph_build_failed") {
      return "failed"
    }
    if (snapshotStatus === "graph_build_skipped" || snapshotStatus === "missing_artifacts") {
      return "missing"
    }

    const readyRun = branch.lastReadyRun
    if (!readyRun || readyRun.status !== "ready") {
      return "failed"
    }

    const readyRunGraphStatus = resolveRunGraphBuildStatus(readyRun)
    if (readyRunGraphStatus && GRAPH_SUCCESS_STATUSES.has(readyRunGraphStatus)) {
      return "ready"
    }
    if (readyRunGraphStatus && GRAPH_ACTIVE_STATUSES.has(readyRunGraphStatus)) {
      return "indexing"
    }
    if (readyRunGraphStatus && GRAPH_FAILURE_STATUSES.has(readyRunGraphStatus)) {
      return "failed"
    }
    if (readyRunGraphStatus === "skipped" || readyRunGraphStatus === "missing") {
      return "missing"
    }
    return "missing"
  }

  if (isPipelineActiveStatus(branch.lastRun?.status)) {
    return "indexing"
  }

  if (branch.lastRun?.status && RUN_FAILURE_STATUSES.has(branch.lastRun.status)) {
    return "failed"
  }

  return "missing"
}

export const buildPipelineStages = (status: string | null): PipelineStage[] => {
  const stages: PipelineStage[] = [
    {
      key: "planned",
      label: "Queued",
      description: "Plan job accepted and waiting for worker execution.",
      state: "pending",
    },
    {
      key: "ingesting",
      label: "Ingesting",
      description: "Repository content is fetched and file changes are prepared.",
      state: "pending",
    },
    {
      key: "indexing",
      label: "Indexing",
      description: "Files are chunked, embedded, and upserted into vector storage.",
      state: "pending",
    },
    {
      key: "complete",
      label: "Complete",
      description: "Run finalized and branch state updated for serving.",
      state: "pending",
    },
  ]

  if (!status) {
    return stages
  }

  if (status === "planned") {
    stages[0].state = "active"
    return stages
  }

  if (status === "ingesting") {
    stages[0].state = "done"
    stages[1].state = "active"
    return stages
  }

  if (status === "indexing") {
    stages[0].state = "done"
    stages[1].state = "done"
    stages[2].state = "active"
    return stages
  }

  stages[0].state = "done"
  stages[1].state = "done"
  stages[2].state = "done"
  stages[3].state = status === "ready" ? "done" : "failed"
  return stages
}

export const formatStatusLabel = (status: string) =>
  status
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (char) => char.toUpperCase())

export const parseLiveLog = (value: unknown): LiveIndexerLog | null => {
  const row = asRecord(value)
  if (!row) {
    return null
  }

  if (
    typeof row.id !== "string" ||
    typeof row.level !== "string" ||
    typeof row.event !== "string" ||
    typeof row.service !== "string"
  ) {
    return null
  }

  const level = row.level as LiveIndexerLogLevel
  if (level !== "info" && level !== "warn" && level !== "error" && level !== "debug") {
    return null
  }

  return {
    id: row.id,
    timestamp: typeof row.timestamp === "string" ? row.timestamp : null,
    createdAt: typeof row.createdAt === "string" ? row.createdAt : null,
    level,
    event: row.event,
    service: row.service,
    requestId: typeof row.requestId === "string" ? row.requestId : null,
    path: typeof row.path === "string" ? row.path : null,
    status: typeof row.status === "number" ? row.status : null,
    durationMs: typeof row.durationMs === "number" ? row.durationMs : null,
    payload: asRecord(row.payload) ?? {},
  }
}

export const parseLiveLogs = (value: unknown): LiveIndexerLog[] => {
  if (!Array.isArray(value)) {
    return []
  }

  return value.flatMap((entry) => {
    const parsed = parseLiveLog(entry)
    return parsed ? [parsed] : []
  })
}

export const normalizeIndexRun = (value: unknown): IndexRun | null => {
  const row = asRecord(value)
  if (!row) {
    return null
  }

  if (
    typeof row.id !== "string" ||
    typeof row.branchStateId !== "string" ||
    typeof row.branch !== "string" ||
    typeof row.configHash !== "string" ||
    typeof row.headSha !== "string" ||
    typeof row.mode !== "string" ||
    typeof row.status !== "string" ||
    typeof row.createdAt !== "string" ||
    typeof row.updatedAt !== "string"
  ) {
    return null
  }

  return {
    id: row.id,
    branchStateId: row.branchStateId,
    branch: row.branch,
    configHash: row.configHash,
    headSha: row.headSha,
    baseSha: typeof row.baseSha === "string" ? row.baseSha : null,
    mode: row.mode,
    status: row.status,
    stats: asRecord(row.stats),
    error: normalizeRunError(row.error),
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  }
}

export const asNumber = (value: unknown): number | null =>
  typeof value === "number" && Number.isFinite(value) ? value : null

export const asInteger = (value: unknown): number | null => {
  const parsed = asNumber(value)
  return parsed === null ? null : Math.max(0, Math.floor(parsed))
}

export const asUsd = (value: unknown): number | null => {
  const parsed = asNumber(value)
  if (parsed === null || parsed < 0) {
    return null
  }
  return Number(parsed.toFixed(6))
}

export const toShortId = (value: unknown) => {
  const text = asString(value)
  if (!text) {
    return null
  }
  return text.slice(0, 8)
}

export const formatCount = (value: number | null) => {
  if (value === null) {
    return "n/a"
  }
  return value.toLocaleString()
}

export const formatTokenCount = (value: number | null) => {
  if (value === null) {
    return "n/a"
  }
  return `${value.toLocaleString()} tok`
}

export const formatUsd = (value: number | null) => {
  if (value === null) {
    return "n/a"
  }
  return `$${value.toFixed(4)}`
}

export const formatDuration = (durationMs: number | null) => {
  if (durationMs === null || durationMs < 0) {
    return "n/a"
  }

  const seconds = Math.floor(durationMs / 1000)
  if (seconds < 60) {
    return `${seconds}s`
  }

  const minutes = Math.floor(seconds / 60)
  const remainderSeconds = seconds % 60
  return `${minutes}m ${remainderSeconds}s`
}

export const joinParts = (parts: Array<string | null | undefined>) =>
  parts.filter((part) => typeof part === "string" && part.trim().length > 0).join(" · ")

export const describeIndexingMetrics = (value: unknown) => {
  const metrics = asRecord(value)
  if (!metrics) {
    return null
  }

  const filesProcessed = asInteger(metrics.filesProcessed)
  const failures = asInteger(metrics.failures)
  const embeddingApiCalls = asInteger(metrics.embeddingApiCalls)
  const embeddingTotalTokens = asInteger(metrics.embeddingTotalTokens)
  const embeddingCostUsd = asUsd(metrics.embeddingCostUsd)
  const durationMs = asInteger(metrics.durationMs)

  const summary = joinParts([
    filesProcessed !== null ? `${filesProcessed} file(s)` : null,
    embeddingApiCalls !== null ? `${embeddingApiCalls} embedding call(s)` : null,
    embeddingTotalTokens !== null ? `${embeddingTotalTokens} tok` : null,
    failures !== null ? `${failures} failure(s)` : null,
    embeddingCostUsd !== null ? `$${embeddingCostUsd.toFixed(4)}` : null,
    durationMs !== null ? `${formatDuration(durationMs)}` : null,
  ])

  return summary.length > 0 ? summary : null
}

export const readRunStats = (run: IndexRun | null) => {
  const stats = run?.stats ?? null
  return {
    filesProcessed: asInteger(stats?.filesProcessed),
    filesScanned: asInteger(stats?.filesScanned),
    filesFetched: asInteger(stats?.filesFetched),
    chunksUpserted: asInteger(stats?.chunksUpserted),
    embeddingApiCalls: asInteger(stats?.embeddingApiCalls),
    embeddingPromptTokens: asInteger(stats?.embeddingPromptTokens),
    embeddingTotalTokens: asInteger(stats?.embeddingTotalTokens),
    embeddingCostUsd: asUsd(stats?.embeddingCostUsd),
    modeFallback: asString(stats?.modeFallback),
    modeFallbackReason: asString(stats?.modeFallbackReason),
  }
}

export const deriveSuggestedRunTarget = ({
  branches,
  runs,
}: {
  branches: IndexBranch[]
  runs: IndexRun[]
}): ProgressTarget => {
  const preferredMain = branches.find((branch) => branch.branch === "main")
  if (preferredMain) {
    return {
      branch: preferredMain.branch,
      configHash: preferredMain.configHash,
    }
  }

  const firstBranch = branches[0]
  if (firstBranch) {
    return {
      branch: firstBranch.branch,
      configHash: firstBranch.configHash,
    }
  }

  const firstRun = runs[0]
  if (firstRun) {
    return {
      branch: firstRun.branch,
      configHash: firstRun.configHash,
    }
  }

  return {
    branch: "main",
    configHash: "",
  }
}

export type RecentlyQueuedRun = {
  key: string
  requestedAtMs: number
  runId: string | null
}

export type BranchRowState = {
  rowKey: string
  isStale: boolean
  isPendingPrune: boolean
  pendingPruneEta: string | null
  pendingPruneIdentifier: string | null
  pendingPruneReason: string | null
  graphStatus: BranchGraphStatus
  isQueuedPending: boolean
  isPipelineActive: boolean
  lastRunError: { summary: string; hint: string | null } | null
}

export const deriveBranchRowState = ({
  branch,
  recentlyQueuedRun,
  nowMs,
}: {
  branch: IndexBranch
  recentlyQueuedRun: RecentlyQueuedRun | null
  nowMs: number
}): BranchRowState => {

export const selectProgressRun = ({
  progressTarget,
  recentlyQueuedRun,
  progressBranchLastRunId,
  runs,
}: {
  progressTarget: ProgressTarget | null
  recentlyQueuedRun: RecentlyQueuedRun | null
  progressBranchLastRunId: string | null
  runs: IndexRun[]
}): IndexRun | null => {
  if (!progressTarget) {
    return null
  }

  const queuedRunForTarget = (
    recentlyQueuedRun &&
    buildBranchKey(progressTarget.branch, progressTarget.configHash) === recentlyQueuedRun.key
  )
    ? recentlyQueuedRun
    : null

  if (queuedRunForTarget?.runId) {
    const byQueuedRunId = runs.find((run) => run.id === queuedRunForTarget.runId)
    if (byQueuedRunId) {
      return byQueuedRunId
    }
  }

  if (progressBranchLastRunId) {
    const byId = runs.find((run) => run.id === progressBranchLastRunId)
    if (byId) {
      return byId
    }
  }

  return (
    runs.find(
      (run) =>
        run.branch === progressTarget.branch &&
        run.configHash === progressTarget.configHash,
    ) ?? null
  )
}

export const isQueuedProgressPending = ({
  queuedProgressRequest,
  progressRun,
}: {
  queuedProgressRequest: RecentlyQueuedRun | null
  progressRun: IndexRun | null
}) => {
  if (!queuedProgressRequest) {
    return false
  }

  const progressRunTimestampMs =
    parseTimestampMs(progressRun?.updatedAt) ??
    parseTimestampMs(progressRun?.createdAt)

  return progressRunTimestampMs === null || progressRunTimestampMs < queuedProgressRequest.requestedAtMs - 1_000
}

export type LatestProgressSnapshot = {
  timestamp: string | null
  stage: string | null
  step: string | null
  message: string | null
  filePath: string | null
  stats: Record<string, unknown> | null
}

export const buildProgressLogs = ({
  liveLogs,
  progressTarget,
  progressRunId,
  queuedProgressPending,
  queuedProgressRequestedAtMs,
}: {
  liveLogs: LiveIndexerLog[]
  progressTarget: ProgressTarget | null
  progressRunId: string | null
  queuedProgressPending: boolean
  queuedProgressRequestedAtMs: number | null
}): LiveIndexerLog[] => {
  if (!progressTarget) {
    return []
  }

  const filtered = liveLogs.filter((entry) => {
    const payload = asRecord(entry.payload)
    if (!payload) {
      return false
    }

    if (queuedProgressPending && queuedProgressRequestedAtMs !== null && progressRunId === null) {
      const logTimestampMs = parseTimestampMs(entry.timestamp)
      if (logTimestampMs !== null && logTimestampMs < queuedProgressRequestedAtMs - 1_000) {
        return false
      }
    }

    const payloadRunId = asString(payload.runId)
    if (progressRunId && payloadRunId === progressRunId) {
      return true
    }

    const payloadBranch = asString(payload.branch)
    if (payloadBranch !== progressTarget.branch) {
      return false
    }

    const payloadConfigHash = asString(payload.configHash)
    if (payloadConfigHash && payloadConfigHash !== progressTarget.configHash) {
      return false
    }

    return true
  })

  return filtered.slice(-PROGRESS_LOG_VIEW_LIMIT).reverse()
}

export const deriveLatestProgressSnapshot = (
  progressLogs: LiveIndexerLog[],
): LatestProgressSnapshot | null => {
  for (const entry of progressLogs) {
    const payload = asRecord(entry.payload)
    if (!payload) {
      continue
    }

    if (asString(payload.outcome) !== "progress") {
      continue
    }

    return {
      timestamp: entry.timestamp,
      stage: asString(payload.stage),
      step: asString(payload.step),
      message: asString(payload.stepMessage),
      filePath: asString(payload.filePath),
      stats: asRecord(payload.progressStats),
    }
  }

  return null
}

export const resolveProgressFilesProcessed = (
  progressFilesFromRun: number | null,
  snapshotStats: Record<string, unknown> | null | undefined,
) => {
  if (progressFilesFromRun !== null) {
    return progressFilesFromRun
  }
  return (
    asInteger(snapshotStats?.filesProcessed) ??
    asInteger(snapshotStats?.filesScanned) ??
    asInteger(snapshotStats?.filesFetched)
  )
}

export const resolveProgressChunksUpserted = (
  chunksUpsertedFromRun: number | null,
  snapshotStats: Record<string, unknown> | null | undefined,
) => {
  if (chunksUpsertedFromRun !== null) {
    return chunksUpsertedFromRun
  }
  return asInteger(snapshotStats?.chunksUpserted)
}

export const liveLogContext = (entry: LiveIndexerLog) => {
  const payload = asRecord(entry.payload)
  if (!payload) {
    return "—"
  }

  const context = joinParts([
    toShortId(payload.runId) ? `run ${toShortId(payload.runId)}` : null,
    toShortId(payload.jobId) ? `job ${toShortId(payload.jobId)}` : null,
    toShortId(payload.batchId) ? `batch ${toShortId(payload.batchId)}` : null,
    asString(payload.stage) ? `stage=${asString(payload.stage)}` : null,
    asString(payload.branch),
    asString(payload.filePath),
  ])
  return context || "—"
}

export const liveLogMessage = (entry: LiveIndexerLog) => {
  const payload = asRecord(entry.payload)
  if (!payload) {
    return ""
  }

  if (typeof payload.errorMessage === "string" && payload.errorMessage.trim().length > 0) {
    return payload.errorMessage
  }

  if (entry.event === "indexer.job.processing") {
    return joinParts([
      asString(payload.jobType) ? `${asString(payload.jobType)} job` : "job",
      asString(payload.outcome) ? `outcome=${asString(payload.outcome)}` : null,
      asString(payload.runMode) ? `mode=${asString(payload.runMode)}` : null,
      asInteger(payload.attempts) !== null ? `attempt=${asInteger(payload.attempts)}` : null,
      asString(payload.duration),
    ])
  }

if (entry.event === "indexer.run.processing") {
  const outcome = asString(payload.outcome)
  if (outcome === "progress") {
    const progressStats = describeIndexingMetrics(payload.progressStats)
    return joinParts([
      asString(payload.stepMessage),
      asString(payload.step) ? `step=${asString(payload.step)}` : null,
      progressStats,
    ])
  }

  return joinParts([
    outcome ? `outcome=${outcome}` : null,
    asString(payload.statusTransitionFrom) && asString(payload.statusTransitionTo)
      ? `transition=${asString(payload.statusTransitionFrom)}→${asString(payload.statusTransitionTo)}`
      : null,
    asString(payload.ingestMode) ? `mode=${asString(payload.ingestMode)}` : null,
    asString(payload.modeFallback)
      ? `fallback=${asString(payload.modeFallback)}${asString(payload.modeFallbackReason) ? `(${asString(payload.modeFallbackReason)})` : ""}`
      : null,
    asString(payload.gcStatus) ? `gc=${asString(payload.gcStatus)}` : null,
    describeIndexingMetrics(payload.indexingMetrics),
  ])
}

  if (entry.event === "indexer.batch.processing") {
    const summary = asRecord(payload.summary)
    const queueDepthAfter = asRecord(summary?.queueDepthAfter)
    return joinParts([
      asString(payload.outcome) ? `outcome=${asString(payload.outcome)}` : null,
      asInteger(summary?.claimed) !== null ? `runsClaimed=${asInteger(summary?.claimed)}` : null,
      asInteger(summary?.ready) !== null ? `ready=${asInteger(summary?.ready)}` : null,
      asInteger(summary?.failed) !== null ? `failed=${asInteger(summary?.failed)}` : null,
      asInteger(summary?.filesProcessed) !== null ? `files=${asInteger(summary?.filesProcessed)}` : null,
      asInteger(queueDepthAfter?.jobsPending) !== null
        ? `queuePending=${asInteger(queueDepthAfter?.jobsPending)}`
        : null,
      asInteger(queueDepthAfter?.jobsProcessing) !== null
        ? `queueProcessing=${asInteger(queueDepthAfter?.jobsProcessing)}`
        : null,
    ])
  }

  if (typeof payload.outcome === "string" && payload.outcome.trim().length > 0) {
    return `outcome=${payload.outcome}`
  }

  if (typeof payload.errorCode === "string" && payload.errorCode.trim().length > 0) {
    return `errorCode=${payload.errorCode}`
  }

  return ""
}

export const branchNeedsReconcile = (branch: IndexBranch) => {
  if (branch.reconcile?.wasEnqueued) {
    return true
  }
  if (branch.reconcile?.headSha) {
    return branch.reconcile.headSha !== (branch.lastReadySha ?? null)
  }
  return false
}

export function SectionCards({ cards = DEFAULT_CARDS }: SectionCardsProps) {
  return (
