import { describe, expect, test } from "bun:test"

import { resolveMergeRequestBridgeIntegration } from "@/lib/gitlab/mr-bridge"

describe("mr-bridge", () => {
  const integrations = [
    {
      id: "int-1",
      instanceUrl: "https://gitlab.global.lmco.com",
      projectPath: "group/project",
      projectId: "101",
      status: "active",
    },
    {
      id: "int-2",
      instanceUrl: "https://gitlab.us.lmco.com",
      projectPath: "group/project",
      projectId: "102",
      status: "degraded",
    },
    {
      id: "int-3",
      instanceUrl: "https://gitlab.com",
      projectPath: "other/repo",
      projectId: "103",
      status: "active",
    },
  ] as const

  test("matches by project path and instance", () => {
    const match = resolveMergeRequestBridgeIntegration({
      integrations,
      projectPath: "/group/project/",
      instanceUrl: "gitlab.us.lmco.com/",
    })

    expect(match?.id).toBe("int-2")
  })

  test("prefers a single active integration when project path is duplicated", () => {
    const match = resolveMergeRequestBridgeIntegration({
      integrations,
      projectPath: "GROUP/PROJECT",
    })

    expect(match?.id).toBe("int-1")
  })

  test("returns undefined when project path is ambiguous and no active winner", () => {
    const ambiguous = [
      {
        id: "int-a",
        instanceUrl: "https://gitlab.one.example",
        projectPath: "group/project",
        status: "degraded",
      },
      {
        id: "int-b",
        instanceUrl: "https://gitlab.two.example",
        projectPath: "group/project",
        status: "degraded",
      },
    ] as const

    const match = resolveMergeRequestBridgeIntegration({
      integrations: ambiguous,
      projectPath: "group/project",
    })

    expect(match).toBeUndefined()
  })

  test("returns undefined when no integration matches the requested instance", () => {
    const match = resolveMergeRequestBridgeIntegration({
      integrations,
      projectPath: "group/project",
      instanceUrl: "https://gitlab.missing.example",
    })

    expect(match).toBeUndefined()
  })

  test("throws when requested instance URL is invalid", () => {
    expect(() => resolveMergeRequestBridgeIntegration({
      integrations,
      projectPath: "group/project",
      instanceUrl: "https://",
    })).toThrow("GitLab instance URL is invalid.")
  })
})

type PendingNavigationSample = {
  route: string
  source: string
  startedAtMs: number
  prefetchHit: boolean
}

const PREFETCHED_ROUTES_STORAGE_KEY = "__argus_prefetched_routes"
const PENDING_NAVIGATION_STORAGE_KEY = "__argus_pending_navigation"
const PREFETCH_HIT_WINDOW_MS = 30_000

type NavigationWindowStore = typeof window & {
  [PREFETCHED_ROUTES_STORAGE_KEY]?: Map<string, number>
  [PENDING_NAVIGATION_STORAGE_KEY]?: Map<string, PendingNavigationSample>
}

const getNavigationWindowStore = () => {
  if (typeof window === "undefined") {
    throw new Error("perf-navigation store can only be used in the browser")
  }

  return window as NavigationWindowStore
}

const getNavigationOrigin = () => (typeof window === "undefined" ? "https://argus.local" : window.location.origin)

const normalizeRoute = (href: string) => {
  if (typeof href !== "string") {
    return null
  }

  const trimmedHref = href.trim()
  if (trimmedHref.length === 0) {
    return null
  }

  try {
    const origin = getNavigationOrigin()
    const parsed = new URL(trimmedHref, origin)
    if (parsed.origin !== origin) {
      return null
    }
    return parsed.pathname
  } catch {
    return null
  }
}

const getPrefetchedRoutes = () => {
  const root = getNavigationWindowStore()
  if (!root[PREFETCHED_ROUTES_STORAGE_KEY]) {
    root[PREFETCHED_ROUTES_STORAGE_KEY] = new Map<string, number>()
  }
  return root[PREFETCHED_ROUTES_STORAGE_KEY]
}

const getPendingNavigationStore = () => {
  const root = getNavigationWindowStore()
  if (!root[PENDING_NAVIGATION_STORAGE_KEY]) {
    root[PENDING_NAVIGATION_STORAGE_KEY] = new Map<string, PendingNavigationSample>()
  }
  return root[PENDING_NAVIGATION_STORAGE_KEY]
}

export const prefetchRouteOnce = ({
  href,
  prefetchedHrefs,
  prefetch,
}: {
  href: string
  prefetchedHrefs: Set<string>
  prefetch: (href: string) => void
}) => {
  const trimmedHref = href.trim()
  if (!trimmedHref || prefetchedHrefs.has(trimmedHref)) {
    return false
  }

  if (!normalizeRoute(trimmedHref)) {
    return false
  }

  prefetchedHrefs.add(trimmedHref)
  prefetch(trimmedHref)
  markRoutePrefetched(trimmedHref)
  return true
}

export const markRoutePrefetched = (href: string) => {
  if (typeof window === "undefined") {
    return false
  }

  const route = normalizeRoute(href)
  if (!route) {
    return false
  }

  const prefetchedRoutes = getPrefetchedRoutes()
  prefetchedRoutes.set(route, performance.now())
  return true
}

export const markRouteNavigationStart = ({
  href,
  source,
}: {
  href: string
  source: string
}) => {
  if (typeof window === "undefined") {
    return null
  }

  const route = normalizeRoute(href)
  const normalizedSource = source.trim()
  if (!route || normalizedSource.length === 0) {
    return null
  }

  const prefetchedRoutes = getPrefetchedRoutes()
  const startedAtMs = performance.now()
  const prefetchedAtMs = prefetchedRoutes.get(route)
  const prefetchHit = typeof prefetchedAtMs === "number" &&
    startedAtMs - prefetchedAtMs <= PREFETCH_HIT_WINDOW_MS
  if (!prefetchHit && typeof prefetchedAtMs === "number") {
    prefetchedRoutes.delete(route)
  }

  // Store pending samples on window so multiple components can mark start/consume
  // without passing state through props/context.
  const pendingStore = getPendingNavigationStore()
  const sample: PendingNavigationSample = {
    route,
    source: normalizedSource,
    startedAtMs,
    prefetchHit,
  }
  pendingStore.set(route, sample)
  return sample
}

export const consumeRouteNavigationSample = (route: string) => {
  if (!route || typeof window === "undefined") {
    return null
  }

  const normalizedRoute = normalizeRoute(route)
  if (!normalizedRoute) {
    return null
  }
  const pendingStore = getPendingNavigationStore()
  const sample = pendingStore.get(normalizedRoute)
  if (!sample) {
    return null
  }

  pendingStore.delete(normalizedRoute)
  return {
    ...sample,
    navDurationMs: Math.max(0, Math.round(performance.now() - sample.startedAtMs)),
  }
}

const getReferenceDate = (
  data: Array<{
    date: string
    desktop: number
    mobile: number
  }>,
) => {
  let latest: Date | null = null

  for (const item of data) {
    const parsed = asDate(item.date)
    if (!parsed) {
      continue
    }
    if (!latest || parsed.getTime() > latest.getTime()) {
      latest = parsed
    }
  }

  return latest ?? chartReferenceDate
}

