type StepStatus = "pending" | "current" | "complete" | "error"

const TIMELINE_STEPS: TimelineStep[] = [
  {
    key: "queued",
    label: "Queued",
    description: "Review run queued for background worker execution.",
  },
  {
    key: "analyzing",
    label: "Analyze Changes",
    description: "Run AI over each batch of files.",
  },
  {
    key: "mapping",
    label: "Map Findings",
    description: "Attach findings to files and line ranges.",
  },
  {
    key: "saving",
    label: "Save Review",
    description: "Persist final findings and summary.",
  },
  {
    key: "done",
    label: "Complete",
    description: "Summarize output and severity counts.",
  },
]

const STAGE_ORDER: ReviewRunStage[] = [
  "idle",
  "queued",
  "chunking",
  "analyzing",
  "mapping",
  "saving",
  "done",
  "failed",
]

/* ─── helpers ─── */

const stageRank = (stage: ReviewRunStage) => STAGE_ORDER.indexOf(stage)

const getStepStatus = ({
  step,
  stage,
  hasError,
}: {
  step: TimelineStep["key"]
  stage: ReviewRunStage
  hasError: boolean
}): StepStatus => {
  if (hasError || stage === "failed") {
    if (step === "analyzing") return "error"
    if (step === "queued" && stageRank(stage) > stageRank("queued")) return "complete"
    return "pending"
  }
  if (step === "done" && stage === "done") return "complete"
  if (stage === step) return "current"
  if (stageRank(stage) > stageRank(step)) return "complete"
  return "pending"
}

const stepIcon = (status: StepStatus) => {
  if (status === "error") return <AlertTriangle className="size-3.5" aria-hidden="true" />
  if (status === "complete") return <CheckCircle2 className="size-3.5" aria-hidden="true" />
  if (status === "current") return <LoaderCircle className="size-3.5 animate-spin" aria-hidden="true" />
  return <Circle className="size-3.5" aria-hidden="true" />
}

const stepIconColor = (status: StepStatus) => {
  if (status === "error") return "text-red-500 dark:text-red-400"
  if (status === "complete") return "text-emerald-500 dark:text-emerald-400"
  if (status === "current") return "text-blue-500 dark:text-blue-400"
  return "text-muted-foreground/40"
}

const stepLineColor = (status: StepStatus) => {
  if (status === "complete") return "bg-emerald-500/30 dark:bg-emerald-400/20"
  if (status === "error") return "bg-red-500/30 dark:bg-red-400/20"
  return "bg-border/60"
}

/** Group events by the step they belong to. */
const eventsByStep = (events: ReviewRunEvent[]) => {
  const map: Record<string, ReviewRunEvent[]> = {}
  for (const event of events) {
    const key =
      event.stage === "failed"
        ? "analyzing"
        : event.stage === "chunking"
          ? "queued"
          : event.stage
    if (!map[key]) map[key] = []
    map[key].push(event)
  }
  return map
}

/** Build a short context string for the currently active step. */

const getStepDetail = (
  step: TimelineStep["key"],
  reviewRun: ReviewRunState,
  reviewError: string,
): string | null => {
  if (step === "queued" && reviewRun.totalBatches > 0) {
    return `${reviewRun.totalBatches} ${reviewRun.totalBatches === 1 ? "batch" : "batches"} queued`
  }
  if (step === "analyzing") {
    if (reviewRun.stage === "failed" || reviewError) {
      return reviewError || "Review failed"
    }
    if (reviewRun.totalBatches > 0) {
      return `Batch ${Math.min(reviewRun.currentBatchIndex, reviewRun.totalBatches)}/${reviewRun.totalBatches}`
    }
  }
  return null
}

/** Format file list for the analyzing step. */
const formatBatchFiles = (files: string[]) => {
  if (files.length === 0) return null
  if (files.length <= 3) return files.join(", ")
  return `${files.slice(0, 3).join(", ")} +${files.length - 3} more`
}

const formatPersonaModeLabel = (mode: ReviewPersonaMode) => {
  if (mode === "multi") {
    return "All personas"
  }
  if (mode === "disabled") {
    return "Disabled"
  }
  return "Single persona"
}

/* ─── header status helpers ─── */

const headerStatusIcon = (stage: ReviewRunStage, isReviewing: boolean) => {
  if (stage === "failed") return <AlertTriangle className="size-3.5" aria-hidden="true" />
  if (stage === "done") return <CheckCircle2 className="size-3.5" aria-hidden="true" />
  if (isReviewing) return <LoaderCircle className="size-3.5 animate-spin" aria-hidden="true" />
  return <Sparkles className="size-3.5" aria-hidden="true" />
}

const [isManuallyOpen, setIsManuallyOpen] = useState(false)
const [pendingFeedbackAction, setPendingFeedbackAction] = useState<ReviewFeedback | null>(null)
const isOpen = isReviewing || isManuallyOpen

const handleReviewFeedbackSubmit = (action: ReviewFeedback) => {
  setPendingFeedbackAction(action)
  onSubmitReviewFeedback(reviewFeedback === action ? null : action)
}

if (!hasStarted) return null

const groupedEvents = eventsByStep(reviewRun.events)
const personaModeLabel = formatPersonaModeLabel(reviewPersonaMode)
const isSinglePersonaMode = reviewPersonaMode === "single"
const personaStatus =
  reviewPersonaMode === "multi"
    ? `${reviewPersonaPasses.length} passes · ${reviewPersonaExecutionStrategy}`
    : reviewPersonaExecutionStrategy

return (
  <Collapsible
    open={isOpen}
    onOpenChange={(open) => {
      if (!isReviewing) {
        setIsManuallyOpen(open)
      }
    }}
  >
    {/* ── collapsed header row ── */}
    <CollapsibleTrigger
      className={cn(
        "group flex w-full items-center gap-2.5 rounded-lg border border-border/50 px-3 py-2 mb-2",
        "bg-card/50 backdrop-blur-sm",
        "transition-all duration-150 hover:bg-accent/50",
        "cursor-pointer select-none",
      )}
    >
      <span className={cn("shrink-0", headerStatusColor(reviewRun.stage, isReviewing))}>
        {headerStatusIcon(reviewRun.stage, isReviewing)}
      </span>

      <span className="text-[13px] font-medium text-foreground">AI Review</span>

{reviewTraceId ? (
  <span className="text-[10px] font-mono text-muted-foreground">
    trace: {reviewTraceId.slice(0, 8)}
  </span>
) : null}
{/* severity pills — visible for quick scanning */}

{hasFindings ? (
  <div className="flex items-center gap-1">
    {reviewSeverityCounts.high > 0 ? (
      <span className="inline-flex items-center rounded-md px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-red-700 bg-red-500/10 ring-1 ring-inset ring-red-500/20 dark:text-red-300 dark:bg-red-500/10 dark:ring-red-500/20">
        {reviewSeverityCounts.high} High
      </span>
    ) : null}
    {reviewSeverityCounts.med > 0 ? (
      <span className="inline-flex items-center rounded-md px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-amber-700 bg-amber-500/10 ring-1 ring-inset ring-amber-500/20 dark:text-amber-300 dark:bg-amber-500/10 dark:ring-amber-500/20">
