use std::fs;
use std::path::PathBuf;

use super::engine::ScipError;
use super::engine::{ScipArtifacts, ScipIndexOptions, ScipProvider};

#[derive(Debug, Clone)]
pub struct ScipJsonProvider {
  path: PathBuf,
}

impl ScipJsonProvider {
  pub fn new(path: impl Into<PathBuf>) -> Self {
    Self { path: path.into() }
  }

  pub fn load(&self) -> Result<ScipArtifacts, ScipError> {
    let content = fs::read_to_string(&self.path)?;
    let artifacts: ScipArtifacts = serde_json::from_str(&content)
      .map_err(|err| ScipError::Provider(format!("failed to parse scip json: {err}")))?;
    Ok(artifacts)
  }
}

impl ScipProvider for ScipJsonProvider {
  fn index(&self, _options: &ScipIndexOptions) -> Result<ScipArtifacts, ScipError> {
    self.load()
  }
}

#[cfg(test)]
mod tests {
  use super::*;

  #[test]
  fn loads_fixture() -> Result<(), Box<dyn std::error::Error>> {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let fixture = root.join("fixtures/scip/semantic.json");
    let provider = ScipJsonProvider::new(fixture);
    let artifacts = provider.load()?;
    assert_eq!(artifacts.nodes.len(), 2);
    assert_eq!(artifacts.edges.len(), 1);
    Ok(())
  }
}

