export const updateUserAdminPersistedFlag = async (args: {
  userId: string
  isAdmin: boolean
}): Promise<AdminManagedUser | null> => {
  const rows = await db
    .update(user)
    .set({
      isAdmin: args.isAdmin,
      updatedAt: new Date(),
    })
    .where(eq(user.id, args.userId))
    .returning({
      id: user.id,
      name: user.name,
      email: user.email,
      emailVerified: user.emailVerified,
      isAdmin: user.isAdmin,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    })

  const row = rows[0]
  return row ? toAdminManagedUser(row as UserRow) : null
}

