import { inArray, sql } from 'drizzle-orm'
import {
  createEmbedderCore,
  type EmbeddingTelemetry,
} from '@argus/shared-runtime/indexing-embedder-core'

import { db } from '@/lib/db'
import { indexEmbeddingCache } from '@/lib/db/schema'
import { INDEX_VECTOR_DIMENSION } from '@argus/contracts-indexing'
import { estimateEmbeddingCostUsd } from '@/lib/indexing/embedding-cost'
import type { VectorChunkRecord } from '@argus/contracts-indexing'
import { sha256Hex } from '@/lib/utils/hash'

const loadCache = async (chunkIds: string[]) => {
  if (chunkIds.length === 0) {
    return new Map<string, { model: string; embedding: number[] }>()
  }

  const rows = await db
    .select({
      chunkId: indexEmbeddingCache.chunkId,
      model: indexEmbeddingCache.model,
      embedding: indexEmbeddingCache.embedding,
    })
    .from(indexEmbeddingCache)
    .where(inArray(indexEmbeddingCache.chunkId, chunkIds))

  return new Map(rows.map((row) => [row.chunkId, { model: row.model, embedding: row.embedding }]))
}

const upsertCache = async (
  items: Array<{ chunkId: string; embedding: number[] }>,
  model: string,
): Promise<void> => {
  if (items.length === 0) {
    return
  }

  const now = new Date()

  await db
    .insert(indexEmbeddingCache)
    .values(
      items.map((item) => ({
        chunkId: item.chunkId,
        model,
        embedding: item.embedding,
        createdAt: now,
        updatedAt: now,
      })),
    )
    .onConflictDoUpdate({
      target: indexEmbeddingCache.chunkId,
      set: {
        model,
        embedding: sql`excluded.embedding`,
        updatedAt: now,
      },
    })
}

const core = createEmbedderCore<VectorChunkRecord>({
  indexVectorDimension: INDEX_VECTOR_DIMENSION,
  estimateEmbeddingCostUsd,
  sha256Hex,
  loadCache,
  upsertCache,
})

export const embedQueryText = core.embedQueryText
export const embedVectorChunks = core.embedVectorChunks
export const __testables = core.__testables
export type { EmbeddingTelemetry }

#!/bin/sh
set -eu

ROOT_DIR="$(cd "$(dirname "$0")/.." && pwd)"

pkg_version() {
  node -p "require('$ROOT_DIR/package.json').version"
}

cargo_version() {
  awk -F '\"' '/^version =/ { print $2; exit }' "$ROOT_DIR/Cargo.toml"
}

pyproject_version() {
  awk -F '\"' '/^version =/ { print $2; exit }' "$ROOT_DIR/pyproject.toml"
}

changelog_version() {
  awk '/^## / { print $2; exit }' "$ROOT_DIR/CHANGELOG.md"
}

VERSION_PKG="$(pkg_version)"
VERSION_CARGO="$(cargo_version)"
VERSION_PYPROJECT="$(pyproject_version)"
VERSION_CHANGELOG="$(changelog_version)"

echo "package.json: $VERSION_PKG"
echo "Cargo.toml: $VERSION_CARGO"
echo "pyproject.toml: $VERSION_PYPROJECT"
echo "CHANGELOG.md: $VERSION_CHANGELOG"

if [ "$VERSION_PKG" != "$VERSION_CARGO" ] || [ "$VERSION_PKG" != "$VERSION_PYPROJECT" ] || [ "$VERSION_PKG" != "$VERSION_CHANGELOG" ]; then
  echo "Version mismatch detected."
  exit 1
fi

  gitlabInstance,
  customInstance,
  instanceTokens,
  token,
  projects,
  selectedProjectId,
  mergeRequests,
  selectedMergeRequestId,
  webhookSetupFeedback,
  setGitlabInstance,
  setCustomInstance,
  setInstanceTokens,
  setToken,
  setProjects,
  setSelectedProjectId,
  setMergeRequests,
  setSelectedMergeRequestId,
  setWebhookSetupFeedback,
  tokenTestResultCacheRef,
}: UseOnboardingPersistenceOptions) {
  const [isHydrated, setIsHydrated] = useState(false)
  const persistedStateSnapshotRef = useRef("")
  const persistenceTimeoutRef = useRef<number | null>(null)

  useEffect(() => {
    const persistedSnapshot = window.sessionStorage.getItem(ONBOARDING_STORAGE_KEY)
    if (persistedSnapshot) {
      persistedStateSnapshotRef.current = persistedSnapshot
    }

    const persisted = readPersistedState()
    const persistedGitlabInstance =
      persisted.gitlabInstance && isInstanceKey(persisted.gitlabInstance)
        ? persisted.gitlabInstance
        : INSTANCE_PRESETS[0].key
    const nextInstanceTokens = {
      ...buildEmptyInstanceTokens(),
      ...(persisted.instanceTokens && isStringRecord(persisted.instanceTokens)
        ? persisted.instanceTokens
        : {}),
    }

    setGitlabInstance(persistedGitlabInstance)
    if (isNonEmptyString(persisted.customInstance)) {
      setCustomInstance(persisted.customInstance)
    }
    if (
      isNonEmptyString(persisted.token) &&
      persisted.gitlabInstance &&
      isInstanceKey(persisted.gitlabInstance)
    ) {
      nextInstanceTokens[persisted.gitlabInstance] = persisted.token
    }

setInstanceTokens(nextInstanceTokens)
setToken(nextInstanceTokens[persistedGitlabInstance] ?? "")
if (Array.isArray(persisted.projects)) {
  setProjects(persisted.projects as Project[])
}
if (isNonEmptyString(persisted.selectedProjectId)) {
  setSelectedProjectId(persisted.selectedProjectId)
}
if (Array.isArray(persisted.mergeRequests)) {
  setMergeRequests(persisted.mergeRequests as MergeRequest[])
}
if (isNonEmptyString(persisted.selectedMergeRequestId)) {
  setSelectedMergeRequestId(persisted.selectedMergeRequestId)
}
if (
  persisted.webhookSetupFeedback &&
  typeof persisted.webhookSetupFeedback === "object" &&
  (persisted.webhookSetupFeedback.kind === "success" ||
    persisted.webhookSetupFeedback.kind === "warning") &&
  typeof persisted.webhookSetupFeedback.message === "string"
) {
  setWebhookSetupFeedback({
    kind: persisted.webhookSetupFeedback.kind,
    message: persisted.webhookSetupFeedback.message,
  })
}

const loadedTokenTestCache = loadTokenTestCache()
pruneTokenTestCache(loadedTokenTestCache, Date.now())
tokenTestResultCacheRef.current = loadedTokenTestCache
persistTokenTestCache(loadedTokenTestCache)

const hydrationTimer = window.setTimeout(() => {
  setIsHydrated(true)
}, 0)

return () => {
  window.clearTimeout(hydrationTimer)
}

  useEffect(() => {
    if (!isHydrated) {
      return
    }

    if (persistenceTimeoutRef.current !== null) {
      window.clearTimeout(persistenceTimeoutRef.current)
    }

    persistenceTimeoutRef.current = window.setTimeout(() => {
      const persistedState = {
        gitlabInstance,
        customInstance,
        instanceTokens,
        token,
        projects: projects.slice(0, RECENT_PROJECTS_LIMIT),
        selectedProjectId,
        mergeRequests: mergeRequests.slice(0, MERGE_REQUESTS_PRELOAD_LIMIT),
        selectedMergeRequestId,
        webhookSetupFeedback,
      } satisfies OnboardingSessionState
      const serializedState = JSON.stringify(persistedState)
      if (serializedState === persistedStateSnapshotRef.current) {
        persistenceTimeoutRef.current = null
        return
      }

      window.sessionStorage.setItem(ONBOARDING_STORAGE_KEY, serializedState)
      persistedStateSnapshotRef.current = serializedState
      persistenceTimeoutRef.current = null
    }, 200)

    return () => {
      if (persistenceTimeoutRef.current !== null) {
        window.clearTimeout(persistenceTimeoutRef.current)
        persistenceTimeoutRef.current = null
      }
    }
  }, [
    isHydrated,
    gitlabInstance,
    customInstance,
    instanceTokens,
    token,
    projects,
    selectedProjectId,
    mergeRequests,
    selectedMergeRequestId,
    webhookSetupFeedback,
  ])

  return { isHydrated }
}

