import { afterEach, describe, expect, mock, test } from "bun:test"
import * as actualReact from "react"
import { mergeModuleWithOverrides } from "@/test-utils/module-mock"

const originalFetch = globalThis.fetch

afterEach(() => {
  globalThis.fetch = originalFetch
  mock.restore()
})

const loadModule = async () => {
  mock.module("react", () =>
    mergeModuleWithOverrides<typeof import("react")>(actualReact, {
      useCallback: <T,>(fn: T) => fn,
      useEffect: () => {},
      useRef: <T,>(value: T) => ({ current: value }),
    }),
  )

  return import(
    `@/features/onboarding/hooks/use-data.ts?cacheBust=${Math.random()
      .toString(36)
      .slice(2)}`,
  )
}

const noop = () => {}

describe("use-data", () => {
  test("preloads projects/mrs routes once and skips duplicate bootstrap prefetch when fresh", async () => {
    const mod = await loadModule()
    const routePrefetchProjects = mock(() => {})
    const routePrefetchMrs = mock(() => {})
    const stateByKey = new Map<string, { fetchStatus: string; dataUpdatedAt: number }>()
    const keyFor = (value: unknown) => JSON.stringify(value)

  expect(queryClient.prefetchQuery).toHaveBeenCalledTimes(2)
  for (const [call] of queryClient.prefetchQuery.mock.calls) {
    expect(call.retry).toBe(false)
  }
})

test("backs off recent merge request bootstrap prefetch after failure", async () => {
  const mod = await loadModule()
  const keyFor = (value: unknown) => JSON.stringify(value)
  const stateByKey = new Map<string, { fetchStatus: string; dataUpdatedAt: number }>()
