        throw new Error("timeout")
      }
      stateByKey.set(key, {
        fetchStatus: "idle",
        dataUpdatedAt: Date.now(),
      })
      return undefined
    }),
    fetchQuery: mock(async () => []),
    invalidateQueries: mock(async () => undefined),
    removeQueries: mock(async () => undefined),
  }

    pendingFetch.resolve(
      new Response(
