        }),
        {
          status: 200,
          headers: { "content-type": "application/json" },
        },
      ),
    )

    await Promise.resolve()
    await Promise.resolve()

    expect(routePushProjects).toHaveBeenCalledTimes(1)
  })
})

import { GraphCanvas } from "reagraph"
import { memo } from "react"

import { type GraphViewportProps } from "./types"

export const GraphViewport = memo(function GraphViewport({
  graphRef,
  nodes,
  edges,
  theme,
  layoutType,
  labelType,
  clusterAttribute,
  layoutOverrides,
  animated,
  draggable,
  selectedNodeIds,
  activeIds,
  onNodeClick,
  onNodePointerOver,
  onNodePointerOut,
  onCanvasClick,
}: GraphViewportProps) {
  if (nodes.length === 0) {
    return null
  }

  return (
    <div className="h-full w-full">
      <GraphCanvas
        ref={graphRef}
        nodes={nodes}
        edges={edges}
        theme={theme}
        layoutType={layoutType}
        labelType={labelType}
        animated={animated}
        draggable={draggable}
        edgeArrowPosition="none"
        layoutOverrides={layoutOverrides}
        cameraMode="pan"
        clusterAttribute={clusterAttribute}
        selections={selectedNodeIds}
        actives={activeIds}
        onNodeClick={(node) => onNodeClick(node.id)}
        onNodePointerOver={(node) => onNodePointerOver(node.id)}
        onNodePointerOut={(node) => onNodePointerOut(node.id)}
        onCanvasClick={onCanvasClick}
      />
    </div>
  )
})

use std::path::{Path, PathBuf};

use pyo3::exceptions::PyValueError;
use pyo3::prelude::*;

use crate::path_policy::resolve_store_path_within_root;

pub(crate) const DEFAULT_STORE_RELATIVE_PATH: &str = ".argus-search/index.kite";

pub(crate) fn resolve_root_path(root: Option<String>) -> PyResult<PathBuf> {
  match root {
    Some(root) => {
      if root.trim().is_empty() {
        Err(PyValueError::new_err("root cannot be empty"))
      } else {
        Ok(PathBuf::from(root))
      }
    }
    None => std::env::current_dir()
      .map_err(|err| PyValueError::new_err(format!("failed to resolve current directory: {err}"))),
  }
}

pub(crate) fn default_store_path(root: &Path) -> PathBuf {
  root.join(DEFAULT_STORE_RELATIVE_PATH)
}

pub(crate) fn resolve_project_path(project_root: &Path, candidate: PathBuf) -> PathBuf {
  if candidate.is_relative() {
    project_root.join(candidate)
  } else {
    candidate
  }
}

pub(crate) fn resolve_store_path(project_root: &Path, candidate: PathBuf) -> PyResult<PathBuf> {
  resolve_store_path_within_root(project_root, candidate, "store path")
    .map_err(PyValueError::new_err)
}

pub(crate) fn read_text_file(path: PathBuf) -> PyResult<String> {
  std::fs::read_to_string(&path)
    .map_err(|err| PyValueError::new_err(format!("failed to read {}: {err}", path.display())))
}

