mod tests {
  use super::*;
  use serde::Deserialize;

struct TestSink {
  batches: usize,
  total_chunks: usize,
}

impl ParseSink for TestSink {
  fn on_parse_batch_ref(&mut self, batch: &[CodeChunk]) {
    self.batches += 1;
    self.total_chunks += batch.len();
  }
}

#[test]
fn parse_batches_chunks() {
  let temp = tempfile::tempdir().expect("tempdir");
  let file_path = temp.path().join("sample.js");
  std::fs::write(&file_path, "function foo() {}\nfunction bar() {}\n").expect("write file");

  let mut sink = TestSink {
    batches: 0,
    total_chunks: 0,
  };
  let options = ParseOptions {
    project_root: temp.path().to_path_buf(),
    inputs: ParseInputs {
      paths: vec![temp.path().to_path_buf()],
      include: vec!["*.js".to_string()],
      exclude: Vec::new(),
      respect_gitignore: true,
    },
    batch_size: 1,
  };

  let (_files, stats) = run_parse(
    &options,
    &CancelToken::new(),
    None,
    ParseCachePolicy::default(),
    &mut sink,
    None,
  )
  .expect("parse");

  assert!(stats.files_parsed >= 1);
  assert!(sink.batches >= 1);
  assert!(sink.total_chunks >= 1);
}

#[test]

fn cache_skips_unchanged_files() -> Result<(), Box<dyn std::error::Error>> {
  let temp = tempfile::tempdir()?;
  let file_path = temp.path().join("sample.js");
  std::fs::write(&file_path, "function foo() {}\n")?;

  let options = ParseOptions {
    project_root: temp.path().to_path_buf(),
    inputs: ParseInputs {
      paths: vec![temp.path().to_path_buf()],
      include: vec!["*.js".to_string()],
      exclude: Vec::new(),
      respect_gitignore: true,
    },
    batch_size: 256,
  };

  let cache_path = temp.path().join("cache.json");
  let mut cache = CacheState::load(cache_path.clone());
  let policy = ParseCachePolicy {
    allow_skip: true,
    force: false,
  };

  let (_files, stats) =
    collect_parsed_files(&options, &CancelToken::new(), Some(&mut cache), policy)?;
  cache.save()?;
  assert!(stats.files_parsed >= 1);
  assert_eq!(stats.files_skipped, 0);

  let mut cache = CacheState::load(cache_path);
  let (_files, stats) =
    collect_parsed_files(&options, &CancelToken::new(), Some(&mut cache), policy)?;
  assert!(stats.files_skipped >= 1);

  Ok(())
}

