fn matches_ts_chunk_fixture() {
  let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
    .join("fixtures")
    .join("mini");
  let expected_path = root.join("expected").join("chunks.json");
  let expected_raw = std::fs::read_to_string(expected_path).expect("read expected");
  let mut expected: Vec<ExpectedParsedFile> =
    serde_json::from_str(&expected_raw).expect("parse expected");

  let options = ParseOptions {
    project_root: root.clone(),
    inputs: ParseInputs {
      paths: vec![root.join("src")],
      include: vec!["*.ts".to_string()],
      exclude: Vec::new(),
      respect_gitignore: true,
    },
    batch_size: 256,
  };

  let (parsed_files, _) = collect_parsed_files(
    &options,
    &CancelToken::new(),
    None,
    ParseCachePolicy::default(),
  )
  .expect("parse files");
  let mut actual: Vec<ExpectedParsedFile> = parsed_files
    .into_iter()
    .map(|file| ExpectedParsedFile {
      file_path: file.file_path,
      chunks: file.chunks,
    })
    .collect();

  sort_parsed_files(&mut expected);
  sort_parsed_files(&mut actual);

  let actual_value = serde_json::to_value(actual).expect("serialize actual");
  let expected_value = serde_json::to_value(expected).expect("serialize expected");
  assert_eq!(actual_value, expected_value);
}

  fn sort_parsed_files(files: &mut [ExpectedParsedFile]) {
    for file in files.iter_mut() {
      file
        .chunks
        .sort_by(|a, b| a.id.cmp(&b.id).then(a.kind.cmp(&b.kind)));
    }
    files.sort_by(|a, b| a.file_path.cmp(&b.file_path));
  }
}

