use std::sync::Arc;
use std::thread;

use serde::Serialize;

use crate::core::cancel::CancelToken;
use crate::core::index_pack::writer::IndexPackWriter;
use crate::core::parse::types::ParsedFile;

use super::provider::{EmbeddingError, EmbeddingsProvider};
use super::types::{VectorBatch, VectorRecord};

#[derive(Debug, Clone)]
pub struct VectorOptions {
  pub batch_size: usize,
  pub concurrency: usize,
  pub include_chunk: bool,
}

impl Default for VectorOptions {
  fn default() -> Self {
    Self {
      batch_size: 256,
      concurrency: 4,
      include_chunk: false,
    }
  }
}

#[derive(Debug, Default, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct VectorStats {
  pub vectors_emitted: u64,
}

#[derive(Debug)]
pub enum VectorError {
  Embed(EmbeddingError),
  Io(std::io::Error),
  ThreadPanic,
  Cancelled,
}

impl std::fmt::Display for VectorError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      VectorError::Embed(err) => write!(f, "{err}"),
      VectorError::Io(err) => write!(f, "vector io error: {err}"),
      VectorError::ThreadPanic => write!(f, "vector worker thread panicked"),
      VectorError::Cancelled => write!(f, "cancelled"),
    }
  }
}

impl std::error::Error for VectorError {}

impl From<EmbeddingError> for VectorError {
  fn from(err: EmbeddingError) -> Self {
    VectorError::Embed(err)
  }
}

impl From<std::io::Error> for VectorError {
  fn from(err: std::io::Error) -> Self {
    VectorError::Io(err)
  }
}

pub trait VectorSink {
  fn on_vector_batch(&mut self, _batch: VectorBatch) {}
}

pub fn run_vector(
  files: &[ParsedFile],
  options: &VectorOptions,
  provider: Arc<dyn EmbeddingsProvider>,
  cancel: &CancelToken,
  sink: &mut dyn VectorSink,
  index_pack: Option<&mut IndexPackWriter>,
) -> Result<VectorStats, VectorError> {
  cancel.check().map_err(|_| VectorError::Cancelled)?;

  let total_chunks = files.iter().map(|file| file.chunks.len()).sum::<usize>();
  if total_chunks == 0 {
    return Ok(VectorStats::default());
  }

  let expected_dimension = provider.dimension();
  let record_metadata = provider
    .model_id()
    .map(|model_id| serde_json::json!({ "modelId": model_id }));

  let batch_size = if options.batch_size == 0 {
    total_chunks.max(1)
  } else {
    options.batch_size
  };
  let concurrency = options.concurrency.max(1);
  let include_chunk = options.include_chunk;

  let mut stats = VectorStats::default();
  let mut writer = index_pack;

  let group_capacity = batch_size.saturating_mul(concurrency).max(1);
  let mut group: Vec<&crate::core::parse::types::CodeChunk> = Vec::with_capacity(group_capacity);

let mut process_group =
  |group: &[&crate::core::parse::types::CodeChunk]| -> Result<(), VectorError> {
    cancel.check().map_err(|_| VectorError::Cancelled)?;
    thread::scope(|scope| -> Result<(), VectorError> {
      let mut handles = Vec::with_capacity(concurrency);
      for batch in group.chunks(batch_size) {
        cancel.check().map_err(|_| VectorError::Cancelled)?;
        let provider = Arc::clone(&provider);
        handles.push((
          batch,
          scope.spawn(move || {
            let texts = batch
              .iter()
              .map(|chunk| chunk.content.as_deref().unwrap_or(""))
              .collect::<Vec<_>>();
            provider.embed_texts(&texts)
          }),
        ));
      }

      for (batch, handle) in handles {
        cancel.check().map_err(|_| VectorError::Cancelled)?;
        let embeddings = handle.join().map_err(|_| VectorError::ThreadPanic)??;
        validate_embeddings(&embeddings, batch.len(), expected_dimension)?;

        let records = build_records(batch, embeddings, record_metadata.as_ref(), include_chunk);
        if let Some(writer) = writer.as_deref_mut() {
          for record in &records {
            write_index_pack_vector(writer, record)?;
          }
        }
        stats.vectors_emitted += records.len() as u64;
        sink.on_vector_batch(records);
      }

      Ok(())
    })
  };

  for file in files {
    for chunk in &file.chunks {
      cancel.check().map_err(|_| VectorError::Cancelled)?;
      group.push(chunk);
      if group.len() >= group_capacity {
        process_group(&group)?;
        group.clear();
      }
    }
  }

  if !group.is_empty() {
    process_group(&group)?;
  }

  Ok(stats)
}

fn validate_embeddings(
  embeddings: &[Vec<f32>],
  expected_count: usize,
  expected_dimension: Option<usize>,
) -> Result<(), VectorError> {
  if embeddings.len() != expected_count {
    return Err(VectorError::Embed(EmbeddingError::UnexpectedResponse(
      "embedding count mismatch".to_string(),
    )));
  }
  if let Some(expected) = expected_dimension {
    for (idx, embedding) in embeddings.iter().enumerate() {
      let actual = embedding.len();
      if actual != expected {
        return Err(VectorError::Embed(EmbeddingError::UnexpectedResponse(
          format!(
            "embedding dimension mismatch for item {idx} (expected {expected}, got {actual})"
          ),
        )));
      }
    }
  }
  Ok(())
}

fn build_records(
  batch: &[&crate::core::parse::types::CodeChunk],
  embeddings: Vec<Vec<f32>>,
  metadata: Option<&serde_json::Value>,
  include_chunk: bool,
) -> VectorBatch {
  batch
    .iter()
    .zip(embeddings)
    .map(|(chunk, embedding)| VectorRecord {
      chunk_id: chunk.id.clone(),
      file_path: chunk.file_path.clone(),
      embedding,
      metadata: metadata.cloned(),
      chunk: if include_chunk {
        Some((*chunk).clone())
      } else {
        None
      },
    })
    .collect()
}

#[derive(Serialize)]

#[serde(rename_all = "camelCase")]
struct IndexPackVectorRecord<'a> {
  chunk_id: &'a str,
  file_path: &'a str,
  embedding: &'a [f32],
  #[serde(skip_serializing_if = "Option::is_none")]
  metadata: Option<&'a serde_json::Value>,
}

fn write_index_pack_vector(
  writer: &mut IndexPackWriter,
  record: &VectorRecord,
) -> Result<(), VectorError> {
  let projection = IndexPackVectorRecord {
    chunk_id: &record.chunk_id,
    file_path: &record.file_path,
    embedding: &record.embedding,
    metadata: record.metadata.as_ref(),
  };
  writer.write_vector(&projection)?;
  Ok(())
}

