  struct TestSink {
    batches: usize,
    total: usize,
    saw_metadata: bool,
  }

  impl VectorSink for TestSink {
    fn on_vector_batch(&mut self, batch: VectorBatch) {
      self.batches += 1;
      self.total += batch.len();
      self.saw_metadata |= batch.iter().any(|record| record.metadata.is_some());
    }
  }

