          .iter()
          .map(|_| vec![0.1_f32, 0.2_f32, 0.3_f32])
          .collect(),
      )
    }

    fn dimension(&self) -> Option<usize> {
      Some(3)
    }

    fn model_id(&self) -> Option<&str> {
      Some("fake-model")
    }
  }

