fn emits_batches_and_writes_vectors() -> Result<(), Box<dyn std::error::Error>> {
  let files = vec![ParsedFile {
    file_path: "src/example.ts".to_string(),
    chunks: vec![
      CodeChunk {
        id: "ts:function:src/example.ts:foo:0".to_string(),
        kind: "function".to_string(),
        language: "typescript".to_string(),
        file_path: "src/example.ts".to_string(),
        name: Some("foo".to_string()),
        range: Range {
          start: Position { row: 0, column: 0 },
          end: Position { row: 1, column: 0 },
        },
        content: Some("function foo() {}".to_string()),
        metadata: None,
      },
      CodeChunk {
        id: "ts:function:src/example.ts:bar:0".to_string(),
        kind: "function".to_string(),
        language: "typescript".to_string(),
        file_path: "src/example.ts".to_string(),
        name: Some("bar".to_string()),
        range: Range {
          start: Position { row: 2, column: 0 },
          end: Position { row: 3, column: 0 },
        },
        content: Some("function bar() {}".to_string()),
        metadata: None,
      },
    ],
    skipped: false,
  }];

  let temp = tempfile::tempdir()?;
  let out_dir = temp.path().join("index-pack");
  let options = IndexPackWriterOptions::new(&out_dir, "1.0.0", "run-1", temp.path());
  let mut writer = IndexPackWriter::new(options)?;

  let provider = Arc::new(FakeProvider);
  let mut sink = TestSink {
    batches: 0,
    total: 0,
    saw_metadata: false,
  };

  let stats = run_vector(
    &files,
    &VectorOptions {
      batch_size: 1,
      concurrency: 1,
      include_chunk: false,
    },
    provider,
    &CancelToken::new(),
    &mut sink,
    Some(&mut writer),
  )?;

  assert_eq!(stats.vectors_emitted, 2);
  assert_eq!(sink.total, 2);
  assert!(sink.saw_metadata);
  assert!(out_dir.join("vectors.jsonl").exists());

  Ok(())
}

