import { NextResponse } from "next/server"
import { z } from "zod"

import { requireJsonBodyOrEmpty } from "@/lib/http/request-json"
import {
  loadSnapshotGraphData,
  resolveSnapshotGraphScope,
  sampleSnapshotGraphForVisualization,
} from "@/lib/review/snapshot-graph-query"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const payloadSchema = z.object({
  maxNodes: z.number().int().positive().max(2_000).optional(),
  maxEdges: z.number().int().positive().max(10_000).optional(),
  edgeTypes: z.array(z.string().trim().min(1).max(100)).max(20).optional(),
  integrationId: z.string().trim().min(1).max(200).optional(),
  sourceBranch: z.string().trim().min(1).max(300).optional(),
})

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/graph/visualization",
    event: "api.code.graph.visualization",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBodyOrEmpty(request, "Invalid graph visualization payload."),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const parsed = payloadSchema.safeParse(body.value)

if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid graph visualization payload." }, { status: 400 }),
  }
}

try {
  const resolution = await resolveSnapshotGraphScope({
    integrationId: parsed.data.integrationId,
    sourceBranch: parsed.data.sourceBranch,
  })

  if (resolution.status === "pending_graph") {
    logger.set({
      graphPendingReason: resolution.reason,
    })
    return {
      status: 409,
      outcome: "graph_pending",
      response: NextResponse.json({ error: resolution.message }, { status: 409 }),
    }
  }

  if (resolution.status === "error") {
    logger.set({
      graphErrorCode: "snapshot_error",
      graphErrorDetails: { message: resolution.error },
    })
    return {
      status: 502,
      outcome: "graph_failed",
      response: NextResponse.json({ error: resolution.error }, { status: 502 }),
    }
  }

  const graphData = await loadSnapshotGraphData({
    snapshot: resolution.snapshot,
    artifactStore: resolution.artifactStore,
  })
  const graph = sampleSnapshotGraphForVisualization({
    data: graphData,
    maxNodes: parsed.data.maxNodes,
    maxEdges: parsed.data.maxEdges,
    edgeTypes: parsed.data.edgeTypes,
  })

        logger.set({
          indexRunId: graph.indexRunId,
          nodeCount: graph.nodes.length,
          edgeCount: graph.edges.length,
          appliedEdgeTypes: graph.appliedEdgeTypes,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: graph }),
        }
      } catch {
        logger.set({ graphErrorCode: "unknown" })
        return {
          status: 500,
          outcome: "graph_failed",
          response: NextResponse.json({ error: "Failed to generate graph visualization payload." }, { status: 500 }),
        }
      }
    },
  })
}

