import test from 'ava'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..')

function parseSseJson(text: string) {
  const line = text
    .split('\n')
    .map((l) => l.trimEnd())
    .find((l) => l.startsWith('data: '))
  if (!line) throw new Error('no data line found')
  return JSON.parse(line.slice('data: '.length))
}

async function postRpc(url: string, payload: unknown) {
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream' },
    body: JSON.stringify(payload),
  })
  const text = await res.text()
  return { res, json: parseSseJson(text) as any }
}

function loadMcpWithMockAgent(mockCreateArgusSearch: any) {
  const mcpPath = path.join(packageRoot, 'js', 'mcp.js')
  const requireFromMcp = createRequire(mcpPath)

  const agentResolved = requireFromMcp.resolve('./agent.js')
  const mcpResolved = requireFromMcp.resolve('./mcp.js')

  const prevAgent = requireFromMcp.cache[agentResolved]
  const prevMcp = requireFromMcp.cache[mcpResolved]

  requireFromMcp.cache[agentResolved] = {
    id: agentResolved,
    filename: agentResolved,
    loaded: true,
    exports: { createArgusSearch: mockCreateArgusSearch },
  } as any
  delete requireFromMcp.cache[mcpResolved]

  const mod = requireFromMcp('./mcp.js') as any
  const restore = () => {
    if (prevAgent) requireFromMcp.cache[agentResolved] = prevAgent
    else delete requireFromMcp.cache[agentResolved]
    if (prevMcp) requireFromMcp.cache[mcpResolved] = prevMcp
    else delete requireFromMcp.cache[mcpResolved]
  }

  return { mod, restore }
}

