  EnsureMergeRequestSourceBranchIndexingArgs,
  EnsureMergeRequestSourceBranchIndexingDeps,
  EnsureMergeRequestSourceBranchIndexingResult,
} from '@/lib/indexing/mr-auto-index-types'
import { isActivePlanJobStatus, resolveBranchScope } from '@/lib/indexing/mr-auto-index-utils'
import { toNonEmptyString } from '@/lib/indexing/string-utils'

export const ensureMergeRequestSourceBranchIndexing = async (
  args: EnsureMergeRequestSourceBranchIndexingArgs,
  deps: EnsureMergeRequestSourceBranchIndexingDeps,
): Promise<EnsureMergeRequestSourceBranchIndexingResult> => {
  if (!deps.isTriggerEnabled(args.trigger)) {
    return {
      decision: 'skipped',
      reason: 'trigger_disabled',
      branch: null,
      headSha: null,
    }
  }

  try {
    const integration = await deps.loadIntegration(args.integrationId)
    if (!integration) {
      return {
        decision: 'error',
        reason: 'integration_not_found',
        branch: null,
        headSha: null,
      }
    }

    const scope = await resolveBranchScope({
      args,
      deps,
      integration,
    })

    const branch = toNonEmptyString(scope.branch)
    const headSha = toNonEmptyString(scope.headSha)

    if (!branch) {
      return {
        decision: 'skipped',
        reason: 'missing_source_branch',
        branch: null,
        headSha: null,
      }
    }

    if (!headSha) {
      return {
        decision: 'skipped',
        reason: 'missing_source_head_sha',
        branch,
        headSha: null,
      }
    }

const configHash = toNonEmptyString(args.configHash) ?? DEFAULT_INDEX_CONFIG_HASH
