if (headAlreadyIndexed) {
  const graphReady = await deps.isBranchGraphReady({
    integrationId: args.integrationId,
    branch,
  })
  if (graphReady) {
    return {
      decision: 'already_ready',
      reason: 'head_already_indexed',
      branch,
      headSha,
    }
  }
  requiresGraphReplan = true
}

