  integrationId: args.integrationId,
  branch,
  configHash,
})
if (inFlightPlanJob) {
  return {
    decision: 'already_pending',
    reason: 'plan_job_in_flight',
    branch,
    headSha,
    job: {
      id: inFlightPlanJob.id,
      debounceKey: inFlightPlanJob.debounceKey,
      status: inFlightPlanJob.status,
    },
  }
}

