import { useEffect, useRef } from "react"
import { toast } from "sonner"

const COPY_ERROR_SUCCESS_MESSAGE = "Error details copied."
const COPY_ERROR_FAILURE_MESSAGE = "Could not copy error details."

export const copyErrorToClipboard = async (message: string) => {
  if (
    typeof navigator === "undefined" ||
    !navigator.clipboard ||
    typeof navigator.clipboard.writeText !== "function"
  ) {
    throw new Error("Clipboard API is unavailable.")
  }

  await navigator.clipboard.writeText(message)
}

export const useCopyableErrorToast = (
  message: string,
  options?: {
    title?: string
    action?: {
      label: string
      onClick: (message: string) => void | Promise<void>
    }
  },
) => {
  const lastToastSignature = useRef("")

  useEffect(() => {
    const trimmedMessage = message.trim()
    if (!trimmedMessage) {
      return
    }

    const title = options?.title?.trim() || "Request failed"
    const signature = `${title}::${trimmedMessage}`
    if (signature === lastToastSignature.current) {
      return
    }
    lastToastSignature.current = signature

    toast.error(title, {
      description: trimmedMessage,
      duration: 10_000,
      action: options?.action
        ? {
            label: options.action.label,
            onClick: () => {
              void options.action?.onClick(trimmedMessage)
            },
          }
        : {
            label: "Copy",
            onClick: () => {
              void copyErrorToClipboard(trimmedMessage)
                .then(() => {
                  toast.success(COPY_ERROR_SUCCESS_MESSAGE)
                })
                .catch(() => {
                  toast.error(COPY_ERROR_FAILURE_MESSAGE)
                })
            },
          },
    })
  }, [message, options?.action, options?.title])
}

