import path from 'node:path'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

import test from 'ava'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..')

function loadAgentWithMockStream(mockIndexStream: any) {
  const agentPath = path.join(packageRoot, 'js', 'agent.js')
  const requireFromAgent = createRequire(agentPath)

  const streamResolved = requireFromAgent.resolve('./stream.js')
  const agentResolved = requireFromAgent.resolve('./agent.js')

  const prevStream = requireFromAgent.cache[streamResolved]
  const prevAgent = requireFromAgent.cache[agentResolved]

  requireFromAgent.cache[streamResolved] = {
    id: streamResolved,
    filename: streamResolved,
    loaded: true,
    exports: { indexStream: mockIndexStream },
  } as any
  delete requireFromAgent.cache[agentResolved]

  const mod = requireFromAgent('./agent.js') as any
  const restore = () => {
    if (prevStream) requireFromAgent.cache[streamResolved] = prevStream
    else delete requireFromAgent.cache[streamResolved]
    if (prevAgent) requireFromAgent.cache[agentResolved] = prevAgent
    else delete requireFromAgent.cache[agentResolved]
  }

  return { mod, restore }
}

test.serial('InMemoryVectorStore: upsertBatch validates records and normalizes by default', (t) => {
  const { mod, restore } = loadAgentWithMockStream(() => {
    throw new Error('unexpected indexStream call')
  })
  t.teardown(restore)

  const store = new mod.InMemoryVectorStore()
  store.upsertBatch([
    null,
    { chunkId: '', filePath: 'x', embedding: [1, 0] },
    { chunkId: 'c1', filePath: '', embedding: [1, 0] },
    { chunkId: 'c2', filePath: 'a.ts', embedding: [3, 4], chunk: { id: 'c2', content: 'hi' } },
  ])

  t.is(store.size(), 1)
  const matches = store.searchByEmbedding([6, 8], { topK: 5 })
  t.is(matches.length, 1)
  t.true(Math.abs(matches[0].score - 1) < 1e-6)
})

test.serial('InMemoryVectorStore: supports filters and clamps topK', (t) => {
  const { mod, restore } = loadAgentWithMockStream(() => {
    throw new Error('unexpected indexStream call')
  })
  t.teardown(restore)

  const store = new mod.InMemoryVectorStore()
  store.upsertBatch([
    { chunkId: 'c1', filePath: 'a.ts', embedding: [1, 0] },
    { chunkId: 'c2', filePath: 'b.ts', embedding: [0, 1] },
  ])

  const filtered = store.searchByEmbedding([1, 0], { topK: 0, filter: (r: any) => r.filePath === 'b.ts' })
  t.is(filtered.length, 1)
  t.is(filtered[0].record.chunkId, 'c2')

  const clamped = store.searchByEmbedding([1, 0], { topK: 999 })
  t.is(clamped.length, 2)
})

test.serial('InMemoryVectorStore: can skip normalization', (t) => {
  const { mod, restore } = loadAgentWithMockStream(() => {
    throw new Error('unexpected indexStream call')
  })
  t.teardown(restore)

  const store = new mod.InMemoryVectorStore({ normalize: false })
  store.upsertBatch([{ chunkId: 'c1', filePath: 'a.ts', embedding: [1, 0] }])
  const matches = store.searchByEmbedding([2, 0], { topK: 5 })
  t.is(matches.length, 1)
  t.is(matches[0].score, 2)
})

test.serial('InMemoryVectorStore: upsertBatch replaces existing chunk ids', (t) => {
  const { mod, restore } = loadAgentWithMockStream(() => {
    throw new Error('unexpected indexStream call')
  })
  t.teardown(restore)

  const store = new mod.InMemoryVectorStore({ normalize: false })
  store.upsertBatch([{ chunkId: 'c1', filePath: 'a.ts', embedding: [1, 0] }])
  store.upsertBatch([{ chunkId: 'c1', filePath: 'a.ts', embedding: [0, 2] }])

  t.is(store.size(), 1)
  const matches = store.searchByEmbedding([0, 1], { topK: 5 })
  t.is(matches.length, 1)
  t.is(matches[0].score, 2)
})

test.serial('createVectorRetriever: validates deps and maps matches', async (t) => {
  const { mod, restore } = loadAgentWithMockStream(() => {
    throw new Error('unexpected indexStream call')
  })
  t.teardown(restore)

  t.throws(() => mod.createVectorRetriever({ store: null, embedder: null }), { message: /store is required/ })
  t.throws(() => mod.createVectorRetriever({ store: {}, embedder: {} }), { message: /embedder\.embedQuery required/ })

  const calls: any[] = []
  const retriever = mod.createVectorRetriever({
    embedder: {
      async embedQuery(text: string) {
        calls.push(['embedQuery', text])
        return [1, 0]
      },
    },
    store: {
      searchByEmbedding(embedding: any, { topK, filter }: any) {
        calls.push(['searchByEmbedding', embedding, topK, Boolean(filter)])
        return [
          {
            score: 0.5,
            record: { chunkId: 'c1', filePath: 'a.ts', chunk: { id: 'c1', content: 'x' }, metadata: { lang: 'ts' } },
          },
        ]
      },
    },
  })

  const out = await retriever.search({ query: 'hi', topK: 3, filter: () => true })
  t.deepEqual(out, [
    { score: 0.5, chunkId: 'c1', filePath: 'a.ts', chunk: { id: 'c1', content: 'x' }, metadata: { lang: 'ts' } },
  ])
  t.deepEqual(calls[0], ['embedQuery', 'hi'])
})

test.serial('createVectorRetriever: enforces query and result contract', async (t) => {
  const { mod, restore } = loadAgentWithMockStream(() => {
    throw new Error('unexpected indexStream call')
  })
  t.teardown(restore)

  const retriever = mod.createVectorRetriever({
    embedder: {
      async embedQuery() {
        return [1, 0]
      },
    },
    store: {
      searchByEmbedding() {
        return [{ score: '0.9', chunk_id: 'c2', file_path: 'b.ts', metadata: { x: 1 } }]
      },
    },
  })

  const out = await retriever.search({ query: '  hello  ', topK: 2 })
  t.deepEqual(out, [{ score: 0.9, chunkId: 'c2', filePath: 'b.ts', chunk: null, metadata: { x: 1 } }])

