              state.lastReadyRunId && lastReadyGraphSnapshotStatusById.has(state.lastReadyRunId)
                ? (lastReadyGraphSnapshotStatusById.get(state.lastReadyRunId) ?? null)
                : null,
            reconcile: latestReconcile
              ? (() => {
                  const check = reconcileChecksByBranch.get(
                    buildBranchConfigKey(state.branch, state.configHash),
                  )
                  return {
                    jobId: latestReconcile.id,
                    status: latestReconcile.status,
                    checkedAt: latestReconcile.finishedAt ?? latestReconcile.updatedAt,
                    wasChecked: check !== undefined,
                    wasEnqueued: check?.enqueued ?? false,
                    headSha: check?.headSha ?? null,
                    lastReadySha: check?.lastReadySha ?? null,
                    missing: check?.missing ?? false,
                    pendingPruneAt: check?.pendingPruneAt ?? null,
                    pruned: check?.pruned ?? false,
                    errorCode: check?.errorCode ?? null,
                  }
                })()
              : null,
          })),
          reconcile: latestReconcile,
        }),
      }
    },
  })
}

