export const toSafeJsonObject = (value: unknown): Record<string, unknown> => {
  try {
    if (value && typeof value === "object") {
      return JSON.parse(JSON.stringify(value)) as Record<string, unknown>
    }
  } catch {
    return { serializationError: true }
  }
  return {}
}

export const extractLogEventName = (input: unknown) => {
  if (!input || typeof input !== "object") {
    return "log.unknown"
  }

  const event = input as { event?: unknown; tag?: unknown; path?: unknown }

  if (typeof event.event === "string" && event.event.trim()) {
    return event.event.trim()
  }
  if (typeof event.tag === "string" && event.tag.trim()) {
    return `log.${event.tag.trim()}`
  }
  if (typeof event.path === "string" && event.path.trim()) {
    return `request.${event.path.trim()}`
  }
  return "log.unknown"
}

