    )}/discussions/${encodeURIComponent(discussionId)}/notes/${encodeURIComponent(noteId)}`,
    {
      method: "DELETE",
    },
  )

import { and, eq } from "drizzle-orm"

import { db } from "@/lib/db"
import {
  aiReviewGateGlobalSettings,
  aiReviewGateProjectOverrides,
  gitlabIntegrationMemberships,
  gitlabIntegrations,
} from "@/lib/db/schema"
import { eqGitLabMembershipUserId } from "@/lib/gitlab/membership"
import {
  REVIEW_GATE_DEFAULTS,
  normalizeReviewGateSettings,
  type ReviewGateEffectiveSettings,
  type ReviewGateSettings,
} from "@/lib/review/gate"

export type ReviewGateScope = {
  instanceUrl: string
  projectId: string
}

export type ResolvedReviewGatePreferences = {
  globalSettings: ReviewGateSettings
  projectOverride: ReviewGateSettings | null
  effectiveSettings: ReviewGateEffectiveSettings
}

const normalizeScopeValue = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

export const normalizeReviewGateScope = (value: {
  instanceUrl?: unknown
  projectId?: unknown
}): ReviewGateScope | null => {
  const instanceUrl = normalizeScopeValue(value.instanceUrl).replace(/\/+$/, "")
  const projectId = normalizeScopeValue(value.projectId)

  if (!instanceUrl || !projectId) {
    return null
  }

  return {
    instanceUrl,
    projectId,
  }
}

const toSettings = (value: {
  persona: string
  personaMode: string
  personaTemplates: unknown
  strictness: string
  requireEvidence: boolean
  securityBoost: boolean
} | null): ReviewGateSettings => {
  if (!value) {
    return { ...REVIEW_GATE_DEFAULTS }
  }

  return normalizeReviewGateSettings(value)
}

export const resolveReviewGatePreferences = async ({

  userId,
  scope,
}: {
  userId: string
  scope: ReviewGateScope | null
}): Promise<ResolvedReviewGatePreferences> => {
  const globalRows = await db
    .select({
      persona: aiReviewGateGlobalSettings.persona,
      personaMode: aiReviewGateGlobalSettings.personaMode,
      personaTemplates: aiReviewGateGlobalSettings.personaTemplates,
      strictness: aiReviewGateGlobalSettings.strictness,
      requireEvidence: aiReviewGateGlobalSettings.requireEvidence,
      securityBoost: aiReviewGateGlobalSettings.securityBoost,
    })
    .from(aiReviewGateGlobalSettings)
    .where(eq(aiReviewGateGlobalSettings.userId, userId))
    .limit(1)

  const globalSettings = toSettings(globalRows[0] ?? null)

  let projectOverride: ReviewGateSettings | null = null

}

export const upsertReviewGateGlobalSettings = async ({
  userId,
  settings,
}: {
  userId: string
  settings: ReviewGateSettings
}) => {
  const now = new Date()

  await db
    .insert(aiReviewGateGlobalSettings)
    .values({
      userId,
      persona: settings.persona,
      personaMode: settings.personaMode,
      personaTemplates: settings.personaTemplates,
      strictness: settings.strictness,
      requireEvidence: settings.requireEvidence,
      securityBoost: settings.securityBoost,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [aiReviewGateGlobalSettings.userId],
      set: {
        persona: settings.persona,
        personaMode: settings.personaMode,
        personaTemplates: settings.personaTemplates,
        strictness: settings.strictness,
        requireEvidence: settings.requireEvidence,
        securityBoost: settings.securityBoost,
        updatedAt: now,
      },
    })
}

export const upsertReviewGateProjectOverride = async ({
  userId,
  scope,
  settings,
}: {
  userId: string
  scope: ReviewGateScope
  settings: ReviewGateSettings
}) => {
  const now = new Date()

  await db
    .insert(aiReviewGateProjectOverrides)
    .values({
      userId,
      instanceUrl: scope.instanceUrl,
      projectId: scope.projectId,
      persona: settings.persona,
      personaMode: settings.personaMode,
      personaTemplates: settings.personaTemplates,
      strictness: settings.strictness,
      requireEvidence: settings.requireEvidence,
      securityBoost: settings.securityBoost,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [
        aiReviewGateProjectOverrides.userId,
        aiReviewGateProjectOverrides.instanceUrl,
        aiReviewGateProjectOverrides.projectId,
      ],
      set: {
        persona: settings.persona,
        personaMode: settings.personaMode,
        personaTemplates: settings.personaTemplates,
        strictness: settings.strictness,
        requireEvidence: settings.requireEvidence,
        securityBoost: settings.securityBoost,
        updatedAt: now,
      },
    })
}

export const deleteReviewGateProjectOverride = async ({
  userId,
  scope,
}: {
  userId: string
  scope: ReviewGateScope
}) => {
  await db
    .delete(aiReviewGateProjectOverrides)
    .where(
      and(
        eq(aiReviewGateProjectOverrides.userId, userId),
        eq(aiReviewGateProjectOverrides.instanceUrl, scope.instanceUrl),
        eq(aiReviewGateProjectOverrides.projectId, scope.projectId),
      ),
    )
}

export const canUserManageProjectScope = async ({
  userId,
  scope,
}: {
  userId: string
  scope: ReviewGateScope
}) => {
  const rows = await db
    .select({
      integrationId: gitlabIntegrations.id,
    })
    .from(gitlabIntegrations)
    .innerJoin(
      gitlabIntegrationMemberships,
      and(
        eq(gitlabIntegrationMemberships.integrationId, gitlabIntegrations.id),
        eqGitLabMembershipUserId(userId),
      ),
    )
    .where(
      and(
        eq(gitlabIntegrations.instanceUrl, scope.instanceUrl),
        eq(gitlabIntegrations.projectId, scope.projectId),
      ),
    )
    .limit(1)

  return Boolean(rows[0])
}

