function formatListItem(c, text, { indent = 2, bullet = true } = {}) {
  const f = fmt(c)
  const padding = ' '.repeat(indent)
  const prefix = bullet ? `${f.symbols.bullet} ` : ''
  return `${padding}${prefix}${text}`
}

/**
 * Format a status line (for doctor, etc.)
 */

function formatBox(c, lines, { title = '', padding = 1, borderColor = c.dim } = {}) {
  const linesArray = Array.isArray(lines) ? lines : lines.split('\n')
  const maxLen = Math.max(...linesArray.map((l) => stripAnsi(l).length), stripAnsi(title).length + 2)
  const width = maxLen + padding * 2

  const top = title
    ? `${borderColor}┌─${c.reset}${c.bold} ${title} ${c.reset}${borderColor}${'─'.repeat(width - stripAnsi(title).length - 3)}┐${c.reset}`
    : `${borderColor}┌${'─'.repeat(width)}┐${c.reset}`
  const bottom = `${borderColor}└${'─'.repeat(width)}┘${c.reset}`
  const pad = ' '.repeat(padding)

  const content = linesArray.map((line) => {
    const stripped = stripAnsi(line)
    const rightPad = ' '.repeat(Math.max(0, maxLen - stripped.length))
    return `${borderColor}│${c.reset}${pad}${line}${rightPad}${pad}${borderColor}│${c.reset}`
  })

  return [top, ...content, bottom].join('\n')
}

/**
 * Strip ANSI escape codes from a string
 * Removes sequences like ESC[...m used for colors/styles
 */

function stripAnsi(str) {
  // ESC character (0x1B = 27) followed by [ then optional numbers/semicolons then m
  const esc = String.fromCharCode(27)
  const escBracket = `${esc}[`
  let result = String(str)
  let i = result.indexOf(escBracket)
  while (i !== -1) {
    let j = i + 2
    while (j < result.length && ((result[j] >= '0' && result[j] <= '9') || result[j] === ';')) {
      j++
    }
    if (j < result.length && result[j] === 'm') {
      result = result.slice(0, i) + result.slice(j + 1)
    } else {
      i++
    }
    i = result.indexOf(escBracket, i)
  }
  return result
}

/**
 * Format a table
 */

function formatTable(c, rows, { headers = [], columnWidths = [] } = {}) {
  if (!rows.length) return ''

  // Calculate column widths if not provided
  const allRows = headers.length ? [headers, ...rows] : rows
  const widths =
    columnWidths.length > 0
      ? columnWidths
      : allRows[0].map((_, colIdx) => Math.max(...allRows.map((row) => stripAnsi(String(row[colIdx] ?? '')).length)))

  const formatRow = (row, isHeader = false) => {
    return row
      .map((cell, idx) => {
        const text = String(cell ?? '')
        const stripped = stripAnsi(text)
        const pad = ' '.repeat(Math.max(0, widths[idx] - stripped.length))
        return isHeader ? `${c.bold}${text}${c.reset}${pad}` : `${text}${pad}`
      })
      .join('  ')
  }

  const output = []
  if (headers.length) {
    output.push(formatRow(headers, true))
    output.push(c.dim + widths.map((w) => '─'.repeat(w)).join('──') + c.reset)
  }
  for (const row of rows) {
    output.push(formatRow(row))
  }
  return output.join('\n')
}

// ============================================================================
// Help text formatting
// ============================================================================

/**
 * Format the main usage text with colors
 */

function formatUsage(c, { version = '', commands = [], options = [] } = {}) {
  const f = fmt(c)
  const lines = []

  lines.push(`${formatMiniLogo(c)} ${c.dim}v${version}${c.reset}`)
  lines.push('')
  lines.push(`${c.bold}USAGE${c.reset}`)
  lines.push(`  ${f.command('argus-search')} ${c.dim}<command>${c.reset} ${c.dim}[options]${c.reset}`)
  lines.push('')

  if (commands.length) {
    lines.push(`${c.bold}COMMANDS${c.reset}`)
    for (const cmd of commands) {
      lines.push(`  ${f.command(cmd.name.padEnd(16))} ${c.dim}${cmd.description}${c.reset}`)
    }
    lines.push('')
  }

  if (options.length) {
    lines.push(`${c.bold}OPTIONS${c.reset}`)
    for (const opt of options) {
      const flags = opt.short
        ? `${f.option(`-${opt.short}`)}, ${f.option(`--${opt.name}`)}`
        : `    ${f.option(`--${opt.name}`)}`
      lines.push(`  ${flags.padEnd(30)} ${c.dim}${opt.description}${c.reset}`)
    }
    lines.push('')
  }

  lines.push(`${c.dim}Run ${f.command('argus-search help <command>')} for command-specific help${c.reset}`)
  return lines.join('\n')
}

/**
 * Format command-specific help
 */

function formatCommandHelp(c, { command = '', usage = '', options = [], examples = [] } = {}) {
  const f = fmt(c)
  const lines = []

  lines.push(`${c.bold}${command.toUpperCase()}${c.reset}`)
  lines.push('')
  lines.push(`${c.bold}USAGE${c.reset}`)
  lines.push(`  ${usage}`)
  lines.push('')

  if (options.length) {
    lines.push(`${c.bold}OPTIONS${c.reset}`)
    for (const opt of options) {
      const name = opt.name.padEnd(24)
      lines.push(`  ${f.option(`--${name}`)} ${c.dim}${opt.description}${c.reset}`)
    }
    lines.push('')
  }

  if (examples.length) {
    lines.push(`${c.bold}EXAMPLES${c.reset}`)
    for (const ex of examples) {
      lines.push(`  ${c.dim}$${c.reset} ${f.command(ex)}`)
    }
    lines.push('')
  }

  return lines.join('\n')
}

// ============================================================================
// Exports
// ============================================================================

module.exports = {
  ANSI,
  NO_COLOR,
  resolveColorEnabled,
  createColors,
  getColors,
  setColorMode,
  fmt,
  formatBanner,
  formatMiniLogo,
  formatSection,
  formatKeyValue,
  formatListItem,
  formatStatus,
  formatEvent,
  formatBox,
  formatTable,
  formatUsage,
  formatCommandHelp,
  stripAnsi,
}

