import { useCallback, useEffect, useState } from "react"

import { useTheme } from "next-themes"

import {
  SETTINGS_AUTOSAVE_DEBOUNCE_MS,
  THEME_SETTINGS_STORAGE_KEY,
  getActualThemeMode,
  readThemeModeFromStorage,
  type ThemeMode,
} from "../model/settings.shared"
import { useDebouncedAutosave } from "./use-debounced-autosave"

const clearStatusLater = (setStatus: (value: string) => void) => {
  window.setTimeout(() => {
    setStatus("")
  }, 2000)
}

export function useThemeSettings() {
  const { setTheme } = useTheme()
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => readThemeModeFromStorage())
  const [themeStatus, setThemeStatus] = useState("")

  useEffect(() => {
    setTheme(getActualThemeMode(themeMode))
  }, [setTheme, themeMode])

  const handleThemeModeChange = useCallback((value: ThemeMode) => {
    setThemeMode(value)
  }, [])

  const saveThemeMode = useCallback((value: ThemeMode) => {
    if (typeof window !== "undefined") {
      window.localStorage.setItem(THEME_SETTINGS_STORAGE_KEY, value)
      setThemeStatus("Theme preference auto-saved.")
      clearStatusLater(setThemeStatus)
    }
  }, [])

  useDebouncedAutosave(themeMode, saveThemeMode, SETTINGS_AUTOSAVE_DEBOUNCE_MS)

  useEffect(() => {
    if (themeMode !== "argus") {
      return
    }

    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)")
    const handleSystemThemeChange = () => {
      setTheme(getActualThemeMode("argus"))
    }
    mediaQuery.addEventListener("change", handleSystemThemeChange)

    return () => {
      mediaQuery.removeEventListener("change", handleSystemThemeChange)
    }
  }, [themeMode, setTheme])

  return {
    themeMode,
    themeStatus,
    handleThemeModeChange,
  }
}

