import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const reviewIdSchema = z.string().trim().min(1)
const postPayloadSchema = z.object({
  reviewId: reviewIdSchema,
  force: z.boolean().optional(),
})

const parseReviewId = (value: unknown) => {
  const parsed = reviewIdSchema.safeParse(value)
  if (!parsed.success) {
    return null
  }
  return parsed.data
}

const summarizeImpactDebug = (impactByKey: Record<string, ReviewFindingImpactResult>) => {
  let succeeded = 0
  let failed = 0
  let pending = 0
  let fileScopeSucceeded = 0
  let zeroImpactSucceeded = 0
  const sample: Array<{
    commentKey: string
    status: "pending" | "succeeded" | "failed"
    scope: "symbol" | "file" | null
    sourceNodeId: string | null
    sourceFile: string | null
    sourceLine: number | null
    callersCount: number
    dependentsCount: number
    affectedFilesCount: number
    error: string | null
  }> = []

for (const [commentKey, impact] of Object.entries(impactByKey)) {
  if (impact.status === "succeeded") {
    succeeded += 1
    if (impact.scope === "file") {
      fileScopeSucceeded += 1
    }
    if (
      impact.callersCount === 0 &&
      impact.dependentsCount === 0 &&
      impact.affectedFilesCount === 0
    ) {
      zeroImpactSucceeded += 1
    }
  } else if (impact.status === "failed") {
    failed += 1
  } else {
    pending += 1
  }

  const suspicious =
    impact.status === "failed" ||
    (impact.status === "succeeded" && impact.scope === "file") ||
    (impact.status === "succeeded" &&
      impact.callersCount === 0 &&
      impact.dependentsCount === 0 &&
      impact.affectedFilesCount === 0)
  if (suspicious && sample.length < 6) {
    sample.push({
      commentKey,
      status: impact.status,
      scope: impact.scope,
      sourceNodeId: impact.sourceNodeId ?? null,
      sourceFile: impact.sourceFile ?? null,
      sourceLine: Number.isFinite(impact.sourceLine) ? (impact.sourceLine ?? null) : null,
      callersCount: impact.callersCount,
      dependentsCount: impact.dependentsCount,
      affectedFilesCount: impact.affectedFilesCount,
      error: impact.error,
    })
  }
}

return {
  total: Object.keys(impactByKey).length,
  succeeded,
  failed,
  pending,
  fileScopeSucceeded,
  zeroImpactSucceeded,
  sample,
}

}

const buildIndexingContext = (data: {
  pendingReason?: string | null
  telemetry?: {
    graphResolutionStatus?: "ready" | "pending_graph" | "error" | "not_checked" | null
    graphPendingReason?: string | null
    branch?: string | null
    integrationId?: string | null
  }
}) => ({
  graphResolutionStatus: data.telemetry?.graphResolutionStatus ?? "not_checked",
  graphPendingReason:
    data.telemetry?.graphPendingReason ?? data.pendingReason ?? null,
  branch: data.telemetry?.branch ?? null,
  integrationId: data.telemetry?.integrationId ?? null,
})

const withoutTelemetry = <T extends { telemetry?: unknown }>(
  value: T,
): Omit<T, "telemetry"> => {
  const next = { ...value } as T & { telemetry?: unknown }
  Reflect.deleteProperty(next, "telemetry")
  return next as Omit<T, "telemetry">
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/impact",
    event: "api.review.impact.get",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const reviewId = parseReviewId(new URL(request.url).searchParams.get("reviewId"))
      if (!reviewId) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "reviewId is required." }, { status: 400 }),
        }
      }

      let data

      try {
        data = await loadPersistedReviewImpacts({ userId, reviewId })
      } catch (error) {
        if (error instanceof ReviewImpactServiceError && error.code === "not_found") {
          return {
            status: 404,
            outcome: "not_found",
            response: NextResponse.json({ error: "Review not found." }, { status: 404 }),
          }
        }
        throw error
      }
      logger.set({
        graphBackend: data.telemetry?.graphBackend ?? null,
        graphResolutionStatus: data.telemetry?.graphResolutionStatus ?? null,
        graphPendingReason: data.telemetry?.graphPendingReason ?? null,
        branch: data.telemetry?.branch ?? null,
        integrationId: data.telemetry?.integrationId ?? null,
        impactDebug: summarizeImpactDebug(data.impactByKey),
      })
      const responseData = withoutTelemetry(data)
      const indexing = buildIndexingContext(data)
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: { ...responseData, indexing } }),
      }
    },
  })
}

