import { pathToFileURL } from "node:url"

export type WorkerRunner = () => Promise<void>

type WorkerModule = {
  runReviewWorker?: WorkerRunner
}

const DEFAULT_RUNTIME_MODULE = "./worker-runtime"

export const workerModuleId =
  process.env.REVIEW_WORKER_RUNTIME_MODULE?.trim() || DEFAULT_RUNTIME_MODULE

export const loadWorkerRunner = async ({
  moduleId = workerModuleId,
  importModule = (importId: string) => import(importId),
}: {
  moduleId?: string
  importModule?: (moduleId: string) => Promise<unknown>
} = {}): Promise<WorkerRunner> => {
  const workerModule = (await importModule(moduleId)) as WorkerModule
  const runReviewWorker = workerModule.runReviewWorker
  if (typeof runReviewWorker !== "function") {
    throw new Error(
      `[service-review-worker] worker module did not export runReviewWorker: ${moduleId}`,
    )
  }
  return runReviewWorker
}

export const runReviewWorkerService = async ({
  loadRunner = loadWorkerRunner,
}: {
  loadRunner?: () => Promise<WorkerRunner>
} = {}) => {
  const runWorker = await loadRunner()
  await runWorker()
}

export const runReviewWorkerServiceCli = async ({
  runService = () => runReviewWorkerService(),
  logError = (...args: unknown[]) => {
    console.error(...args)
  },
  exit = (code: number) => {
    process.exit(code)
  },
}: {
  runService?: () => Promise<void>
  logError?: (...args: unknown[]) => void
  exit?: (code: number) => void
} = {}) => {
  try {
    await runService()
  } catch (error) {
    logError("[service-review-worker] execution failed:", error)
    exit(1)
  }
}

const isDirectExecution = (() => {
  const argvEntry = process.argv[1]
  if (!argvEntry) {
    return false
  }
  return pathToFileURL(argvEntry).href === import.meta.url
})()

if (isDirectExecution) {
  void runReviewWorkerServiceCli()
}

const log2p = (value: number) => Math.log2(1 + Math.max(0, value))

export const computeImpactScore = (input: {
  callersCount: number
  dependentsCount: number
  calleesCount: number
  dependenciesCount: number
  affectedFilesCount: number
}) => {
  const raw =
    20 * log2p(input.callersCount) +
    18 * log2p(input.dependentsCount) +
    12 * log2p(input.calleesCount) +
    10 * log2p(input.dependenciesCount) +
    8 * log2p(input.affectedFilesCount)

  return Math.max(0, Math.min(100, Math.round(raw)))
}

export const computeImpactLevel = (score: number): "low" | "med" | "high" => {
  if (score >= 70) {
    return "high"
  }
  if (score >= 35) {
    return "med"
  }
  return "low"
}

import { NextResponse } from "next/server"

import {
  buildLlmMetrics,
  resolveLlmProviderLabel,
} from "@/lib/observability/metrics"
import {
  buildDefaultTokenUsageLimitMessage,
  consumeDefaultTokenUsage,
  ensureDefaultTokenUsageAvailable,
} from "@/lib/ai/default-token-usage"
import { requireJsonBody } from "@/lib/http/request-json"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

import { MAX_PATCH_CHARS } from "./constants"
import { classifyDescriptionError } from "./error-classification"
import {
  requestDescription,
  requestDescriptionStream,
} from "./llm-client"
import {
  loadLatestPersistedDescription,
  persistDescription,
  streamWithPersistence,
} from "./persistence"
import {
  resolveDescriptionRequestInput,
  resolveDescriptionScope,
  resolveDescriptionScopeFromSearchParams,
} from "./request-input"
import {
  type DescriptionScope,
  type ReviewDescriptionRequestPayload,
  type RouteLogger,
} from "./types"

const buildUnauthorizedResponse = () => ({
  status: 401,
  outcome: "unauthorized",
  response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
})

const buildDescriptionUpstreamErrorResponse = (
  logger: RouteLogger,
  error: unknown,
) => {
  const failure = classifyDescriptionError(error)
  logger.set({
    errorCode: failure.code,
    errorCategory: failure.category,
    providerStatus: failure.providerStatus,
    retryable: failure.retryable,
  })
  return {
    status: 502,
    outcome: "upstream_error",
    response: NextResponse.json(
      {
        error: failure.message,
        code: failure.code,
        category: failure.category,
        providerStatus: failure.providerStatus,
        retryable: failure.retryable,
      },
      { status: 502 },
    ),
  }
}

const handleDescriptionGeneration = async ({
  userId,
  patch,
  apiUrl,
  model,
  token,
  stream,
  usesServerToken,
  scope,
  provider,
  logger,
}: {
  userId: string
  patch: string
  apiUrl: string
  model: string
  token: string
  stream: boolean
  usesServerToken: boolean
  scope: DescriptionScope | null
  provider: string
  logger: RouteLogger
}) => {
  try {
    if (stream) {
      const trialConsumption = await consumeDefaultTokenUsage({
        userId,
        usesServerToken,
        requestType: "description",
      })
      if (trialConsumption.limited && trialConsumption.summary) {
        return {
          status: 403,
          outcome: "trial_limit_reached",
          response: NextResponse.json(
            { error: buildDefaultTokenUsageLimitMessage(trialConsumption.summary.limit) },
            { status: 403 },
          ),
        }
      }

const markdownStream = await requestDescriptionStream({
  patch,
  apiUrl,
  model,
  token,
})
const persistedStream = streamWithPersistence({
  stream: markdownStream,
  onComplete: async (markdown) => {
    await persistDescription({
      userId,
      scope,
      model,
      patch,
      markdown,
    })
  },
})

logger.set({
  model,
  patchLength: patch.length,
  stream: true,
  labels: {
    provider,
    model,
  },
  llmMetrics: buildLlmMetrics({
    provider,
    model,
    promptTokens: 0,
    completionTokens: 0,
    totalTokens: 0,
    latencyMs: null,
    requestCount: 1,
  }),
  persisted: scope !== null,
  instanceUrl: scope?.instanceUrl ?? null,
  projectId: scope?.projectId ?? null,
  mergeRequestIid: scope?.mergeRequestIid ?? null,
  defaultTokenUsageLimit: trialConsumption.summary?.limit ?? null,
  defaultTokenUsageCount: trialConsumption.summary?.used ?? null,
  defaultTokenUsageRemaining: trialConsumption.summary?.remaining ?? null,
})

return {
  status: 200,
  outcome: "success",
  response: new Response(persistedStream, {
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "cache-control": "no-store",
      "x-accel-buffering": "no",
    },
  }),
}

}

const trialConsumption = await consumeDefaultTokenUsage({
  userId,
  usesServerToken,
  requestType: "description",
})
if (trialConsumption.limited && trialConsumption.summary) {
  return {
    status: 403,
    outcome: "trial_limit_reached",
    response: NextResponse.json(
      { error: buildDefaultTokenUsageLimitMessage(trialConsumption.summary.limit) },
      { status: 403 },
    ),
  }
}

const descriptionResult = await requestDescription({
  patch,
  apiUrl,
  model,
  token,
})
const markdown = descriptionResult.markdown

if (!markdown) {
  throw new Error("AI did not return an MR description.")
}
const descriptionId = await persistDescription({
  userId,
  scope,
  model,
  patch,
  markdown,
})

logger.set({
  model,
  patchLength: patch.length,
  markdownLength: markdown.length,
  stream: false,
  labels: {
    provider,
    model,
  },
  llmMetrics: descriptionResult.llmMetrics,
  descriptionId,
  persisted: scope !== null,
  instanceUrl: scope?.instanceUrl ?? null,
  projectId: scope?.projectId ?? null,
  mergeRequestIid: scope?.mergeRequestIid ?? null,
  defaultTokenUsageLimit: trialConsumption.summary?.limit ?? null,
  defaultTokenUsageCount: trialConsumption.summary?.used ?? null,
  defaultTokenUsageRemaining: trialConsumption.summary?.remaining ?? null,
})

    return {
      status: 200,
      outcome: "success",
      response: NextResponse.json({ data: { markdown } }),
    }
  } catch (error) {
    return buildDescriptionUpstreamErrorResponse(logger, error)
  }
}

const handlePostRequest = async ({
  userId,
  payload,
  logger,
}: {
  userId: string
  payload: ReviewDescriptionRequestPayload | null
  logger: RouteLogger
}) => {
  let resolved: ReturnType<typeof resolveDescriptionRequestInput>
  try {
    resolved = resolveDescriptionRequestInput(payload)
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "AI provider URL is invalid."
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json({ error: message }, { status: 400 }),
    }
  }

  const { patch, apiUrl, model, token, stream, usesServerToken } = resolved
  const provider = resolveLlmProviderLabel(apiUrl)
  const scope = resolveDescriptionScope(payload)

  if (!patch) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json({ error: "Patch is required." }, { status: 400 }),
    }
  }
  if (!apiUrl || !model || !token) {
    return {
      status: 400,
      outcome: "missing_config",
      response: NextResponse.json(
        { error: "AI token missing. Set AI_API_TOKEN or OPENAI_API_KEY on the server." },
        { status: 400 },
      ),
    }
  }

if (patch.length > MAX_PATCH_CHARS) {
  return {
    status: 413,
    outcome: "payload_too_large",
    response: NextResponse.json(
      {
        error: `Diff too large for AI MR description. Limit is ${MAX_PATCH_CHARS.toLocaleString()} characters.`,
      },
      { status: 413 },
    ),
  }
}

const trialAvailability = await ensureDefaultTokenUsageAvailable({
  userId,
  usesServerToken,
})
if (trialAvailability.limited) {
  logger.set({
    defaultTokenUsageLimit: trialAvailability.summary.limit,
    defaultTokenUsageCount: trialAvailability.summary.used,
    defaultTokenUsageRemaining: trialAvailability.summary.remaining,
  })
  return {
    status: 403,
    outcome: "trial_limit_reached",
    response: NextResponse.json(
      { error: buildDefaultTokenUsageLimitMessage(trialAvailability.summary.limit) },
      { status: 403 },
    ),
  }
}

return handleDescriptionGeneration({
  userId,
  patch,
  apiUrl,
  model,
  token,
  stream,
  usesServerToken,
  scope,
  provider,
  logger,
})

}

const handleGetRequest = async ({
  request,
  userId,
  logger,
}: {
  request: Request
  userId: string
  logger: RouteLogger
}) => {
  const scope = resolveDescriptionScopeFromSearchParams(new URL(request.url).searchParams)
  if (!scope) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        { error: "instanceUrl, projectId, and mergeRequestIid are required." },
        { status: 400 },
      ),
    }
  }

  const description = await loadLatestPersistedDescription({ userId, scope })
  logger.set({
    descriptionFound: Boolean(description),
    descriptionId: description?.id ?? null,
  })

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({ data: { description } }),
  }
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/description",
    event: "api.review.description",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "Invalid description payload."),
      ])
      if (!userId) {
        return buildUnauthorizedResponse()
      }

      if (!body.ok) return body.result

      const payload = body.value as ReviewDescriptionRequestPayload | null
      return handlePostRequest({ userId, payload, logger })
    },
  })
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/description",
    event: "api.review.description.latest",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return buildUnauthorizedResponse()
      }

      return handleGetRequest({ request, userId, logger })
    },
  })
}

export {
  resolveDescriptionRequestInput,
  resolveServerApiUrl,
} from "./request-input"
export type {
  ReviewDescriptionRequestPayload,
} from "./types"

