const isDenseGraph = allNodes.length > 900 || allEdges.length > 3_200;
const denseOverviewNodes = useMemo(
	() => sampleArray(allNodes, DENSE_OVERVIEW_NODE_LIMIT),
	[allNodes],
);
const renderedNodeIdSet = useMemo(() => {
	if (!isDenseGraph) {
		return nodeIdSet;
	}

	const out = new Set<string>();
	if (selectedNodeId) {
		out.add(selectedNodeId);
		for (const entity of selectedConnectedEntities) {
			if (out.size >= DENSE_FOCUS_NODE_LIMIT) {
				break;
			}
			out.add(entity.node.id);
		}
	}

	for (const node of denseOverviewNodes) {
		if (out.size >= DENSE_FOCUS_NODE_LIMIT && selectedNodeId) {
			break;
		}
		out.add(node.id);
		if (!selectedNodeId && out.size >= DENSE_OVERVIEW_NODE_LIMIT) {
			break;
		}
	}
	return out;
}, [
	denseOverviewNodes,
	isDenseGraph,
	nodeIdSet,
	selectedConnectedEntities,
	selectedNodeId,
]);

const visibleNodes = useMemo(() => {
	if (!isDenseGraph) {
		return allNodes;
	}
	return allNodes.filter((node) => renderedNodeIdSet.has(node.id));
}, [allNodes, isDenseGraph, renderedNodeIdSet]);

const graphLayoutType: GraphLayoutType = isDenseGraph
	? "nooverlap"
	: "forceDirected2d";
const graphLabelType: GraphLabelType = isDenseGraph
	? "none"
	: allEdges.length > 2_200
		? "nodes"
		: "auto";
const showNodeLabels = graphLabelType !== "none";
const showEdgeLabels = graphLabelType === "auto";
const graphClusterAttribute = isDenseGraph ? undefined : "package";
const graphAnimated = !isDenseGraph;
const graphDraggable = !isDenseGraph;
const graphLayoutOverrides = useMemo(() => {
	if (!isDenseGraph) {
		return undefined;
	}
	return toDenseLayoutOverrides();
}, [isDenseGraph]);

const degreeByNodeId = useMemo(() => {
	const degree = new Map<string, number>();
	for (const edge of allEdges) {
		degree.set(edge.sourceId, (degree.get(edge.sourceId) ?? 0) + 1);
		degree.set(edge.targetId, (degree.get(edge.targetId) ?? 0) + 1);
	}
	return degree;
}, [allEdges]);

const edgeColorMap = useMemo(
	() => buildEdgeColorMap(allEdges, graph?.availableEdgeTypes),
	[allEdges, graph?.availableEdgeTypes],
);

const edgeBudget = isDenseGraph
	? selectedNodeId
		? DENSE_FOCUS_EDGE_LIMIT
		: DENSE_OVERVIEW_EDGE_LIMIT
	: allEdges.length;

const candidateVisibleEdges = useMemo(() => {
	if (!isDenseGraph) {
		return allEdges;
	}

	const out: GraphEdge[] = [];
	for (const edge of allEdges) {
		if (
			renderedNodeIdSet.has(edge.sourceId) &&
			renderedNodeIdSet.has(edge.targetId)
		) {
			out.push(edge);
		}
	}
	return out;
}, [allEdges, isDenseGraph, renderedNodeIdSet]);
const renderEdges = useMemo(
	() => pickRenderableEdges(candidateVisibleEdges, edgeBudget, selectedNodeId),
	[candidateVisibleEdges, edgeBudget, selectedNodeId],
);
const highlightedNodeIds = useMemo(() => {
	if (!selectedNodeId) {
		return EMPTY_IDS;
	}

	const ids = new Set<string>([selectedNodeId]);
	for (const edge of renderEdges) {
		if (edge.sourceId === selectedNodeId) {
			ids.add(edge.targetId);
		}
		if (edge.targetId === selectedNodeId) {
			ids.add(edge.sourceId);
		}
	}
	return [...ids];
}, [renderEdges, selectedNodeId]);

const reagraphNodes = useMemo(() => {
	return visibleNodes.map((node) => {
		const degree = degreeByNodeId.get(node.id) ?? 0;
		return {
			id: node.id,
			label: showNodeLabels ? (node.name ?? shortId(node.id)) : undefined,
			fill: nodeColor(node.kind, isDark),
			size: Math.max(5, Math.min(12, 5 + degree * 0.25)),
			data: {
				kind: node.kind,
				filePath: node.filePath,
				package: packageKeyFromNode(node),
			},
		};
	});
}, [degreeByNodeId, isDark, showNodeLabels, visibleNodes]);

const reagraphEdges = useMemo(() => {
	const out: Array<{
		id: string;
		source: string;
		target: string;
		label?: string;
		fill: string;
		data: { type: string };
	}> = [];

	let index = 0;
	for (const edge of renderEdges) {
		out.push({
			id: `${edge.sourceId}-${edge.targetId}-${edge.type}-${index}`,
			source: edge.sourceId,
			target: edge.targetId,
			label: showEdgeLabels ? edge.type : undefined,
			fill: edgeColorMap.get(edge.type) ?? "#94a3b8",
			data: {
				type: edge.type,
			},
		});
		index += 1;
	}
	return out;
}, [edgeColorMap, renderEdges, showEdgeLabels]);

const activeGraphIds = useMemo(() => {
	if (!selectedNodeId) {
		return EMPTY_IDS;
	}
	const ids = new Set<string>(highlightedNodeIds);
	for (const edge of reagraphEdges) {
		if (edge.source === selectedNodeId || edge.target === selectedNodeId) {
			ids.add(edge.id);
		}
	}
	return [...ids];
}, [highlightedNodeIds, reagraphEdges, selectedNodeId]);
const graphSelectionIds = selectedNodeIds;
const graphActiveIds = activeGraphIds;

const searchableNodes = useMemo(
	() =>
		allNodes.map((node) => ({
			node,
			searchValue: `${node.name ?? ""} ${node.id} ${node.filePath ?? ""}`
				.toLowerCase()
				.trim(),
		})),
	[allNodes],
);

const searchResults = useMemo(() => {
	const term = deferredSearchText.trim().toLowerCase();
	if (!term) return EMPTY_NODES;

	const out: GraphNode[] = [];
	for (const entry of searchableNodes) {
		if (entry.searchValue.includes(term)) {
			out.push(entry.node);
		}
		if (out.length >= MAX_SEARCH_RESULTS) {
			break;
		}
	}
	return out;
}, [deferredSearchText, searchableNodes]);

const findFirstSearchMatch = useCallback(
	(rawTerm: string) => {
		const term = rawTerm.trim().toLowerCase();
		if (!term) {
			return null;
		}

		for (const entry of searchableNodes) {
			if (entry.searchValue.includes(term)) {
				return entry.node;
			}
		}
		return null;
	},
	[searchableNodes],
);

/* ---- data fetching ---- */

const runVisualization = useCallback(async () => {
	setIsLoading(true);
	setErrorMessage(null);

	try {
		if (shouldLoadTraceGraph) {
			const { graph: traceGraphPayload, targetId } =
				await fetchTraceGraphPayload({
					traceMode,
					traceNodeId,
					traceSymbol,
					traceBranch,
					traceIntegrationId,
					traceDepth,
					traceLimit,
					shouldLoadTraceGraph,
				});

			startTransition(() => {
				setGraph(traceGraphPayload);
				setSelectedNodeId(targetId);
			});
		} else {
			const normalizedGraph = await fetchOverviewGraphPayload({
				graphRequestLimits,
				traceIntegrationId,
				traceBranch,
			});
			startTransition(() => {
				setGraph(normalizedGraph);
				const firstNodeId = normalizedGraph.nodes[0]?.id ?? null;
				setSelectedNodeId((prev) => prev ?? firstNodeId);
			});
		}
	} catch (error) {
		setErrorMessage(
			error instanceof Error ? error.message : "Failed to load graph.",
		);
	} finally {
		setIsLoading(false);
	}
}, [
	graphRequestLimits,
	shouldLoadTraceGraph,
	traceBranch,
	traceDepth,
	traceIntegrationId,
	traceLimit,
	traceMode,
	traceNodeId,
	traceSymbol,
]);

/* ---- node interaction ---- */
const focusNode = useCallback((nodeId: string | null) => {
	if (!nodeId || !graphRef.current) return;
	graphRef.current.centerGraph([nodeId]);
}, []);

const selectNode = useCallback(
	(nodeId: string, focus = false) => {
		setSelectedNodeId(nodeId);
		setIsInspectorCollapsed(false);
		if (focus) focusNode(nodeId);
	},
	[focusNode],
);

const handleGraphNodeClick = useCallback((nodeId: string) => {
	setSelectedNodeId(nodeId);
	setIsInspectorCollapsed(false);
}, []);
const handleGraphNodePointerOver = useCallback((nodeId: string) => {
	setHoveredNodeId(nodeId);
}, []);
const handleGraphNodePointerOut = useCallback((nodeId: string) => {
	setHoveredNodeId((current) => (current === nodeId ? null : current));
}, []);

const handleGraphCanvasClick = useCallback(() => {
	setSelectedNodeId(null);
}, []);

/* ---- keyboard shortcut: / to focus search ---- */
useEffect(() => {
	const handler = (event: KeyboardEvent) => {
		if (event.key === "/" && document.activeElement?.tagName !== "INPUT") {
			event.preventDefault();
			searchInputRef.current?.focus();
		}
		if (event.key === "Escape") {
			setSearchText("");
			searchInputRef.current?.blur();
		}
	};
	window.addEventListener("keydown", handler);
	return () => window.removeEventListener("keydown", handler);
}, []);

/* ---- load on mount ---- */
useEffect(() => {
	void runVisualization();
}, [runVisualization]);

/* ---- keep selection in sync with loaded graph ---- */
useEffect(() => {
	if (!graph) return;
	if (!selectedNodeId) {
		const first = graph.nodes[0]?.id ?? null;
		setSelectedNodeId(first);
		return;
	}
	if (!nodeIdSet.has(selectedNodeId)) {
		setSelectedNodeId(graph.nodes[0]?.id ?? null);
	}
}, [graph, nodeIdSet, selectedNodeId]);
useEffect(() => {
	if (!hoveredNodeId) {
		return;
	}
	if (!nodeIdSet.has(hoveredNodeId)) {
		setHoveredNodeId(null);
	}
}, [hoveredNodeId, nodeIdSet]);

useEffect(() => {
	if (!selectedNodeId) {
		setIsInspectorCollapsed(false);
	}
}, [selectedNodeId]);

/* ---- search form submit ---- */
const handleSearchSubmit = (event: FormEvent) => {
	event.preventDefault();
	const first = findFirstSearchMatch(searchText);
	if (first) {
		selectNode(first.id, true);
		setSearchText("");
	}
};

const inspectorOpen =
	hoveredNode !== null || (selectedNode !== null && !isInspectorCollapsed);

return (
	<div className="relative flex min-h-0 flex-1 flex-col overflow-hidden rounded-lg border border-border/60 bg-background">
		{/* ============ FLOATING SEARCH (top-left) ============ */}

				{isDenseGraph ? (
					<>
						{" · "}
						<Tooltip>
							<TooltipTrigger asChild>
								<span className="cursor-help underline decoration-dotted underline-offset-2">
									{selectedNodeId ? "focus mode" : "overview mode"}
								</span>
							</TooltipTrigger>
							<TooltipContent side="bottom" className="max-w-xs text-xs">
								{selectedNodeId
									? "Focus mode prioritizes the selected node neighborhood in dense graphs."
									: "Overview mode shows a broad sampled slice of a dense graph."}
							</TooltipContent>
						</Tooltip>
					</>
				) : null}
			</span>
		</div>
	)}

{/* ============ ZOOM CONTROLS (bottom-left) ============ */}

{isLoading && !graph && (
	<div className="absolute inset-0 z-10 flex items-center justify-center bg-background/80 backdrop-blur-sm">
		<div className="flex items-center gap-2 text-sm text-muted-foreground">
			<Loader2 className="size-4 animate-spin" />
			Loading graph...
		</div>
	</div>
)}

{errorMessage && !graph && (
	<div className="absolute inset-0 z-10 flex flex-col items-center justify-center gap-3 bg-background/80">
		<p className="text-sm text-destructive">{errorMessage}</p>
		<Button
			variant="outline"
			size="sm"
			onClick={() => void runVisualization()}
		>
			Retry
		</Button>
	</div>
)}

{!graph && !isLoading && !errorMessage && (
	<div className="absolute inset-0 z-10 flex items-center justify-center">
		<p className="text-sm text-muted-foreground">
			No graph data loaded.
		</p>
	</div>
)}

	<GraphViewport
		graphRef={graphRef}
		nodes={reagraphNodes}
		edges={reagraphEdges}
		theme={reagraphTheme}
		layoutType={graphLayoutType}
		labelType={graphLabelType}
		clusterAttribute={graphClusterAttribute}
		layoutOverrides={graphLayoutOverrides}
		animated={graphAnimated}
		draggable={graphDraggable}
		selectedNodeIds={graphSelectionIds}
		activeIds={graphActiveIds}
		onNodeClick={handleGraphNodeClick}
		onNodePointerOver={handleGraphNodePointerOver}
		onNodePointerOut={handleGraphNodePointerOut}
		onCanvasClick={handleGraphCanvasClick}
	/>
</div>

import { afterEach, describe, expect, test } from "bun:test"

import { estimateEmbeddingCostUsd } from "@/lib/indexing/embedding-cost"

describe("embedding cost estimation", () => {
  const originalGlobalRate = process.env.OBS_EMBEDDING_COST_USD_PER_1K
  const originalModelRate = process.env.OBS_EMBEDDING_COST_USD_PER_1K_TEXT_EMBEDDING_3_SMALL

  afterEach(() => {
    if (originalGlobalRate === undefined) {
      delete process.env.OBS_EMBEDDING_COST_USD_PER_1K
    } else {
      process.env.OBS_EMBEDDING_COST_USD_PER_1K = originalGlobalRate
    }

    if (originalModelRate === undefined) {
      delete process.env.OBS_EMBEDDING_COST_USD_PER_1K_TEXT_EMBEDDING_3_SMALL
    } else {
      process.env.OBS_EMBEDDING_COST_USD_PER_1K_TEXT_EMBEDDING_3_SMALL = originalModelRate
    }
  })

  test("returns null when no embedding cost env is configured", () => {
    delete process.env.OBS_EMBEDDING_COST_USD_PER_1K
    delete process.env.OBS_EMBEDDING_COST_USD_PER_1K_TEXT_EMBEDDING_3_SMALL

    expect(
      estimateEmbeddingCostUsd({
        model: "text-embedding-3-small",
        totalTokens: 1_000,
      }),
    ).toBeNull()
  })

  test("prefers model-specific rate over global rate", () => {
    process.env.OBS_EMBEDDING_COST_USD_PER_1K = "0.01"
    process.env.OBS_EMBEDDING_COST_USD_PER_1K_TEXT_EMBEDDING_3_SMALL = "0.02"

    expect(
      estimateEmbeddingCostUsd({
        model: "text-embedding-3-small",
        totalTokens: 1_500,
      }),
    ).toBe(0.03)
  })

  test("rejects invalid rate values", () => {
    process.env.OBS_EMBEDDING_COST_USD_PER_1K = "not-a-number"

    expect(() =>
      estimateEmbeddingCostUsd({
        model: null,
        totalTokens: 1_000,
      }),
    ).toThrow('Invalid OBS_EMBEDDING_COST_USD_PER_1K value "not-a-number".')
  })
})

import { parsePositiveInt } from '@argus/shared-runtime/config-env'
import type { VectorChunkRecord } from '@argus/contracts-indexing'
import { chunkWithArgusSearch } from '@/lib/indexing/engines/argus-search'
import type { CodeChunk } from '@/lib/indexing/types'
import { sha256Hex } from '@/lib/utils/hash'

const normalizeChunkText = (value: string) => value.replace(/\s+/g, ' ').trim()
const DEFAULT_MAX_INPUT_TOKENS = 8_000
const DEFAULT_OVERLAP_TOKENS = 200
const BOUNDARY_SCAN_CHARS = 256
const SPLIT_BOUNDARY_CHARS = new Set(['\n', '\r', '\t', ' ', ',', '.', ';', ':', ')', ']', '}'])

type ChunkSplitPart = {
  content: string
  startByte: number
  endByte: number
}

const resolveEmbeddingMaxInputTokens = () =>
  parsePositiveInt(process.env.INDEXER_EMBEDDING_MAX_INPUT_TOKENS, DEFAULT_MAX_INPUT_TOKENS)

const resolveEmbeddingChunkOverlapTokens = () =>
  parsePositiveInt(process.env.INDEXER_EMBEDDING_CHUNK_OVERLAP_TOKENS, DEFAULT_OVERLAP_TOKENS)

const buildUtf8PrefixSums = (chars: string[]) => {
  const prefixSums = new Array<number>(chars.length + 1)
  prefixSums[0] = 0

  for (let index = 0; index < chars.length; index += 1) {
    prefixSums[index + 1] = prefixSums[index] + Buffer.byteLength(chars[index] ?? '', 'utf8')
  }

  return prefixSums
}

const findSegmentEndByBytes = (prefixSums: number[], startChar: number, maxBytes: number) => {
  const targetBytes = prefixSums[startChar] + maxBytes
  let low = startChar + 1
  let high = prefixSums.length - 1
  let best = startChar

  while (low <= high) {
    const middle = Math.floor((low + high) / 2)
    if ((prefixSums[middle] ?? 0) <= targetBytes) {
      best = middle
      low = middle + 1
    } else {
      high = middle - 1
    }
  }

  return best
}

const pickBoundaryEnd = (chars: string[], startChar: number, endChar: number) => {
  const searchFrom = Math.max(startChar + 1, endChar - BOUNDARY_SCAN_CHARS)
  for (let cursor = endChar - 1; cursor >= searchFrom; cursor -= 1) {
    if (SPLIT_BOUNDARY_CHARS.has(chars[cursor] ?? '')) {
      return cursor + 1
    }
  }

  return endChar
}

const findOverlapStart = (prefixSums: number[], endChar: number, overlapBytes: number) => {
  if (overlapBytes <= 0) {
    return endChar
  }

  const targetBytes = Math.max(0, (prefixSums[endChar] ?? 0) - overlapBytes)
  let low = 0
  let high = endChar

  while (low < high) {
    const middle = Math.floor((low + high) / 2)
    if ((prefixSums[middle] ?? 0) < targetBytes) {
      low = middle + 1
    } else {
      high = middle
    }
  }

  return low
}

const splitChunkByEmbeddingBudget = (args: {
  content: string
  maxBytes: number
  overlapBytes: number
}): ChunkSplitPart[] => {
  if (Buffer.byteLength(args.content, 'utf8') <= args.maxBytes) {
    return [
      {
        content: args.content,
        startByte: 0,
        endByte: Buffer.byteLength(args.content, 'utf8'),
      },
    ]
  }

  const chars = Array.from(args.content)
  const prefixSums = buildUtf8PrefixSums(chars)
  const parts: ChunkSplitPart[] = []

  let startChar = 0
  while (startChar < chars.length) {
    let endChar = findSegmentEndByBytes(prefixSums, startChar, args.maxBytes)
    if (endChar <= startChar) {
      endChar = Math.min(chars.length, startChar + 1)
    }

    const boundedEndChar = pickBoundaryEnd(chars, startChar, endChar)
    const segmentEndChar = boundedEndChar > startChar ? boundedEndChar : endChar
    const segmentContent = chars.slice(startChar, segmentEndChar).join('')
    parts.push({
      content: segmentContent,
      startByte: prefixSums[startChar] ?? 0,
      endByte: prefixSums[segmentEndChar] ?? 0,
    })

    if (segmentEndChar >= chars.length) {
      break
    }

    const overlapStartChar = findOverlapStart(prefixSums, segmentEndChar, args.overlapBytes)
    const nextStartChar = overlapStartChar < segmentEndChar ? overlapStartChar : segmentEndChar
    startChar = nextStartChar > startChar ? nextStartChar : segmentEndChar
  }

  return parts
}

const applyEmbeddingBudget = (chunk: CodeChunk) => {
  const maxInputTokens = resolveEmbeddingMaxInputTokens()
  const overlapTokens = resolveEmbeddingChunkOverlapTokens()
  // Use UTF-8 bytes as a conservative proxy so token count stays below model limits.
  const maxBytes = Math.max(1, maxInputTokens)
  const overlapBytes = Math.min(Math.max(0, overlapTokens), Math.max(0, maxBytes - 1))
  const parts = splitChunkByEmbeddingBudget({
    content: chunk.content ?? '',
    maxBytes,
    overlapBytes,
  })

  return parts.map((part, segmentIndex) => ({
    content: part.content,
    metadata: {
      ...chunk.metadata,
      embeddingChunking: {
        sourceChunkId: chunk.chunkId,
        sourceChunkIndex: chunk.chunkIndex,
        split: parts.length > 1,
        segmentIndex,
        segmentCount: parts.length,
        startByte: part.startByte,
        endByte: part.endByte,
        maxInputTokens,
        overlapTokens,
      },
    },
  }))
}

export const buildVectorChunks = async (args: {
  path: string
  content: string
  configHash: string
}): Promise<Array<Omit<VectorChunkRecord, 'embedding'>>> => {
  const chunks = await chunkWithArgusSearch(args.path, args.content)
  const preparedChunks = chunks.flatMap((chunk) => applyEmbeddingBudget(chunk))
  const vectorChunks: Array<Omit<VectorChunkRecord, 'embedding'>> = []

  for (const chunk of preparedChunks) {
    const normalized = normalizeChunkText(chunk.content)
    if (!normalized) {
      continue
    }

    vectorChunks.push({
      chunkIndex: vectorChunks.length,
      chunkId: sha256Hex(`${args.configHash}:${normalized}`),
      content: chunk.content,
      metadata: chunk.metadata ?? {},
    })
  }

  return vectorChunks
}

import { afterEach, describe, expect, mock, test } from "bun:test"

type LoggerContext = Record<string, unknown>

type ApiLogHandlerArgs = {
  logger: {
    set: (context: LoggerContext) => void
  }
}

type RunWithApiRequestLogArgs = {
  request: Request
  path: string
  event: string
  handler: (args: ApiLogHandlerArgs) => Promise<{
    response: Response
  }>
}

