      truncated: false,
    },
  }))
  const getDiffManifest = mock(async () => ({
    data: {
      mode: "full",
      limits: {
        globalBytes: 1024,
        perFileBytes: 128,
        chunkBytes: 32,
      },
      totals: {
        files: 1,
        additions: 0,
        deletions: 0,
        estimatedBytes: 32,
      },
      mergeRequest: {
        projectId: "10",
        mergeRequestIid: "22",
        webUrl: "https://gitlab.example.com/group/project/-/merge_requests/22",
        title: "Example",
      },
      files: [],
    },
  }))

  const getSessionUserId = mock(async () => "user-1")

  mock.module("@/lib/session", () => ({
    getSessionUserId,
  }))
  mock.module("@/lib/gitlab/diff-service/error", () => ({
    GitLabDiffServiceError,
  }))
  mock.module("@/lib/gitlab/diff-service/service", () => ({
    getDiffFile,
    getDiffManifest,
  }))
  mock.module("@/lib/utils/logger", () => ({
    runWithApiRequestLog,
    logScopedError: mock(() => {}),
  }))

  const routeModule = await import(`./route?cacheBust=${Math.random().toString(36).slice(2)}`)
  return {
    POST: routeModule.POST as (request: Request) => Promise<Response>,
    getDiffFile,
    loggerContext,
    GitLabDiffServiceError,
  }
