const providerPayload = parsedProviderResponse.value
const usage = extractUsageFromOpenAiCompatiblePayload(providerPayload)
const provider = resolveLlmProviderLabel(apiUrl)
logger.set({
  model,
  latencyMs,
  labels: {
    provider,
    model,
  },
  llmMetrics: buildLlmMetrics({
    provider,
    model,
    promptTokens: usage.promptTokens,
    completionTokens: usage.completionTokens,
    totalTokens: usage.totalTokens,
    latencyMs,
    requestCount: 1,
  }),
})

return {
  status: 200,
  outcome: "success",
  response: NextResponse.json({
    ok: true,
    data: {
      latencyMs,
    },
  }),
}

      } catch (error) {
        const message = buildNetworkErrorMessage(error)
        logger.set({
          model,
          networkError: message,
        })

        return {
          status: 502,
          outcome: "upstream_error",
          response: NextResponse.json({ error: message }, { status: 502 }),
        }
      } finally {
        clearTimeout(timeout)
      }
    },
  })
}

