  MergeRequestBranchScope,
} from '@/lib/indexing/mr-auto-index-types'

export const parseMergeRequestBranchScope = (value: unknown): MergeRequestBranchScope => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return {
      branch: null,
      headSha: null,
    }
  }

  const record = value as Record<string, unknown>
  const diffRefs =
    record.diff_refs && typeof record.diff_refs === 'object' && !Array.isArray(record.diff_refs)
      ? (record.diff_refs as Record<string, unknown>)
      : null

  return {
    branch: toNonEmptyString(record.source_branch),
    headSha: toNonEmptyString(diffRefs?.head_sha) ?? toNonEmptyString(record.sha),
  }
}

export const isEnvEnabled = (rawValue: string | undefined) => {
  if (!rawValue) {
    return true
  }

  const normalized = rawValue.trim().toLowerCase()
  return !(normalized === '0' || normalized === 'false' || normalized === 'off' || normalized === 'no')
}

export const isActivePlanJobStatus = (
  status: EnqueuedPlanJob['status'] | InFlightPlanJob['status'],
): status is 'pending' | 'processing' => status === 'pending' || status === 'processing'

export const resolveBranchScope = async ({
  args,
  deps,
  integration,
}: {
  args: EnsureMergeRequestSourceBranchIndexingArgs
  deps: EnsureMergeRequestSourceBranchIndexingDeps
  integration: IntegrationContext
}): Promise<MergeRequestBranchScope> => {
  const hintedBranch = toNonEmptyString(args.sourceBranchHint)
  const hintedHeadSha = toNonEmptyString(args.sourceHeadShaHint)
  if (hintedBranch && hintedHeadSha) {
    return {
      branch: hintedBranch,
      headSha: hintedHeadSha,
    }
  }

  const hintedFromPayload = parseMergeRequestBranchScope(args.mergeRequestDetails)
  if (hintedBranch || hintedFromPayload.branch) {
    return {
      branch: hintedBranch ?? hintedFromPayload.branch,
      headSha: hintedHeadSha ?? hintedFromPayload.headSha,
    }
  }

  const mergeRequestIid = toNonEmptyString(args.mergeRequestIid)
  if (!mergeRequestIid) {
    return {
      branch: null,
      headSha: null,
    }
  }

  const details = await deps.fetchMergeRequestDetails({
    instanceUrl: integration.instanceUrl,
    token: integration.token,
    projectId: integration.projectId,
    mergeRequestIid,
  })

  return parseMergeRequestBranchScope(details)
}

