  createdAt: timestamp("created_at", { withTimezone: true }),
  updatedAt: timestamp("updated_at", { withTimezone: true }),
});

import type { ArtifactStore } from '@argus/contracts-indexing'

type S3Object = {
  Key?: string
  Size?: number
}

type ListObjectsPage = {
  Contents?: S3Object[]
  IsTruncated?: boolean
  NextContinuationToken?: string
}

type S3Module = {
  S3Client: new (config: Record<string, unknown>) => {
    send: (command: unknown) => Promise<unknown>
  }
  PutObjectCommand: new (input: Record<string, unknown>) => unknown
  HeadObjectCommand: new (input: Record<string, unknown>) => unknown
  GetObjectCommand: new (input: Record<string, unknown>) => unknown
  ListObjectsV2Command: new (input: Record<string, unknown>) => unknown
  DeleteObjectsCommand: new (input: Record<string, unknown>) => unknown
}

type S3Credentials = {
  accessKeyId: string
  secretAccessKey: string
  sessionToken?: string
}

const parseBoolean = (value: string | undefined) => value?.trim().toLowerCase() === 'true'

const trimSlashes = (value: string) => value.replace(/^\/+|\/+$/g, '')

const joinKey = (...parts: Array<string | null | undefined>) =>
  parts
    .map((part) => (part ? trimSlashes(part) : ''))
    .filter(Boolean)
    .join('/')

const ensureTrailingNewline = (value: string) => (value.endsWith('\n') ? value : `${value}\n`)

const isMissingObjectError = (error: unknown): boolean => {
  if (!error || typeof error !== 'object') {
    return false
  }

  const record = error as {
    name?: string
    code?: string
    Code?: string
    $metadata?: { httpStatusCode?: number }
  }
  const code = String(record.code ?? record.Code ?? record.name ?? '').toLowerCase()
  const statusCode = record.$metadata?.httpStatusCode ?? null

  return (
    code === 'nosuchkey' ||
    code === 'notfound' ||
    code === 'not_found' ||
    statusCode === 404
  )
}

const readBodyToUtf8 = async (body: unknown): Promise<string> => {
  if (typeof body === 'string') {
    return body
  }

  if (body instanceof Uint8Array) {
    return Buffer.from(body).toString('utf8')
  }

  if (!body || typeof body !== 'object') {
    return ''
  }

  const maybeTransformable = body as {
    transformToString?: (encoding?: string) => Promise<string>
    text?: () => Promise<string>
  }

  if (typeof maybeTransformable.transformToString === 'function') {
    return maybeTransformable.transformToString('utf8')
  }

  if (typeof maybeTransformable.text === 'function') {
    return maybeTransformable.text()
  }

  // SDK body shapes differ across runtimes; fall back to generic readable stream handling.
  const maybeReadable = body as NodeJS.ReadableStream
  if (typeof maybeReadable.on !== 'function') {
    return ''
  }

  const chunks: Buffer[] = []
  for await (const chunk of maybeReadable) {
    if (typeof chunk === 'string') {
      chunks.push(Buffer.from(chunk))
      continue
    }
    chunks.push(Buffer.from(chunk))
  }

  return Buffer.concat(chunks).toString('utf8')
}

const resolveRequiredEnv = (name: string): string => {
  const value = process.env[name]?.trim()
  if (!value) {
    throw new Error(`Missing required ${name} for S3 artifact store.`)
  }
  return value
}

const resolveS3Bucket = () => {
  return resolveRequiredEnv('INDEXER_S3_BUCKET')
}

const resolveS3Region = () => resolveRequiredEnv('INDEXER_S3_REGION')

const resolveS3Credentials = (): S3Credentials | undefined => {
  const accessKeyId = process.env.INDEXER_S3_ACCESS_KEY_ID?.trim()
  const secretAccessKey = process.env.INDEXER_S3_SECRET_ACCESS_KEY?.trim()

  if ((accessKeyId && !secretAccessKey) || (!accessKeyId && secretAccessKey)) {
    throw new Error(
      'INDEXER_S3_ACCESS_KEY_ID and INDEXER_S3_SECRET_ACCESS_KEY must be configured together.',
    )
  }

  if (!accessKeyId || !secretAccessKey) {
    return undefined
  }

  return {
    accessKeyId,
    secretAccessKey,
    sessionToken: process.env.INDEXER_S3_SESSION_TOKEN?.trim() || undefined,
  }
}

let s3ModulePromise: Promise<S3Module> | null = null

const loadS3Module = async (): Promise<S3Module> => {
  if (!s3ModulePromise) {
    s3ModulePromise = import('@aws-sdk/client-s3') as unknown as Promise<S3Module>
  }
  return s3ModulePromise
}

const resolveS3Client = async (args: { region: string; credentials?: S3Credentials }) => {
  const { S3Client } = await loadS3Module()
  return new S3Client({
    region: args.region,
    endpoint: process.env.INDEXER_S3_ENDPOINT?.trim() || undefined,
    forcePathStyle: parseBoolean(process.env.INDEXER_S3_FORCE_PATH_STYLE),
    credentials: args.credentials,
  })
}

export class S3ArtifactStore implements ArtifactStore {
  private readonly bucket = resolveS3Bucket()
  private readonly region = resolveS3Region()
  private readonly credentials = resolveS3Credentials()
  private readonly clientPromise = resolveS3Client({
    region: this.region,
    credentials: this.credentials,
  })

private readonly keyPrefix = trimSlashes(process.env.INDEXER_S3_KEY_PREFIX?.trim() || '')

private resolveKey(args: { artifactsPrefix: string; filename: string }) {
  return joinKey(this.keyPrefix, args.artifactsPrefix, args.filename)
}

private async putObject(args: {
  artifactsPrefix: string
  filename: string
  body: string
  contentType: string
}) {
  const [client, { PutObjectCommand }] = await Promise.all([
    this.clientPromise,
    loadS3Module(),
  ])
  const key = this.resolveKey(args)
  await client.send(
    new PutObjectCommand({
      Bucket: this.bucket,
      Key: key,
      Body: args.body,
      ContentType: args.contentType,
    }),
  )
}

async writeRunJson(args: { artifactsPrefix: string; run: unknown }): Promise<void> {
  await this.putObject({
    artifactsPrefix: args.artifactsPrefix,
    filename: 'run.json',
    body: ensureTrailingNewline(JSON.stringify(args.run, null, 2)),
    contentType: 'application/json',
  })
}

async writeManifest(args: { artifactsPrefix: string; lines: string[] }): Promise<void> {
  await this.putObject({
    artifactsPrefix: args.artifactsPrefix,
    filename: 'manifest.jsonl',
    body: args.lines.length > 0 ? `${args.lines.join('\n')}\n` : '',
    contentType: 'application/x-ndjson',
  })
}

async writeChangedFiles(args: { artifactsPrefix: string; lines: string[] }): Promise<void> {
  await this.putObject({
    artifactsPrefix: args.artifactsPrefix,
    filename: 'changed_files.jsonl',
    body: args.lines.length > 0 ? `${args.lines.join('\n')}\n` : '',
    contentType: 'application/x-ndjson',
  })
}

async writeFile(args: {
  artifactsPrefix: string
  filename: string
  body: string
  contentType?: string
}): Promise<void> {
  await this.putObject({
    artifactsPrefix: args.artifactsPrefix,
    filename: args.filename,
    body: args.body,
    contentType: args.contentType ?? 'text/plain; charset=utf-8',
  })
}

async readTextFile(args: { artifactsPrefix: string; filename: string }): Promise<string> {
  const [client, { GetObjectCommand }] = await Promise.all([
    this.clientPromise,
    loadS3Module(),
  ])
  const key = this.resolveKey(args)

  const response = (await client.send(
    new GetObjectCommand({
      Bucket: this.bucket,
      Key: key,
    }),
  )) as { Body?: unknown }

  return readBodyToUtf8(response.Body)
}

async fileExists(args: { artifactsPrefix: string; filename: string }): Promise<boolean> {
  const [client, { HeadObjectCommand }] = await Promise.all([
    this.clientPromise,
    loadS3Module(),
  ])
  const key = this.resolveKey(args)

  try {
    await client.send(
      new HeadObjectCommand({
        Bucket: this.bucket,
        Key: key,
      }),
    )
    return true
  } catch (error) {
    if (isMissingObjectError(error)) {
      return false
    }
    throw error
  }
}

async describePrefix(args: {
  artifactsPrefix: string
}): Promise<{ bytes: number; objects: number }> {
  const [client, { ListObjectsV2Command }] = await Promise.all([
    this.clientPromise,
    loadS3Module(),
  ])
  const keyPrefix = joinKey(this.keyPrefix, args.artifactsPrefix)
  const prefix = keyPrefix ? `${keyPrefix}/` : ''
  let continuationToken: string | undefined
  let bytes = 0
  let objects = 0

  do {
    const page = (await client.send(
      new ListObjectsV2Command({
        Bucket: this.bucket,
        Prefix: prefix,
        ContinuationToken: continuationToken,
      }),
    )) as ListObjectsPage

    for (const object of page.Contents ?? []) {
      bytes += object.Size ?? 0
      if (object.Key) {
        objects += 1
      }
    }

    continuationToken = page.IsTruncated ? page.NextContinuationToken : undefined
  } while (continuationToken)

  return { bytes, objects }
}

  async deletePrefix(args: {
    artifactsPrefix: string
  }): Promise<{ bytes: number; objects: number }> {
    const [client, { DeleteObjectsCommand, ListObjectsV2Command }] = await Promise.all([
      this.clientPromise,
      loadS3Module(),
    ])
    const keyPrefix = joinKey(this.keyPrefix, args.artifactsPrefix)
    const prefix = keyPrefix ? `${keyPrefix}/` : ''
    let continuationToken: string | undefined
    let bytes = 0
    let objects = 0

    do {
      const page = (await client.send(
        new ListObjectsV2Command({
          Bucket: this.bucket,
          Prefix: prefix,
          ContinuationToken: continuationToken,
        }),
      )) as ListObjectsPage

      const keys = (page.Contents ?? []).flatMap((object) =>
        object.Key ? [{ Key: object.Key }] : [],
      )

      for (const object of page.Contents ?? []) {
        bytes += object.Size ?? 0
        if (object.Key) {
          objects += 1
        }
      }

      if (keys.length > 0) {
        await client.send(
          new DeleteObjectsCommand({
            Bucket: this.bucket,
            Delete: {
              Objects: keys,
              Quiet: true,
            },
          }),
        )
      }

      continuationToken = page.IsTruncated ? page.NextContinuationToken : undefined
    } while (continuationToken)

    return { bytes, objects }
  }
}

export const createS3ArtifactStore = () => new S3ArtifactStore()

