export const toNonEmptyString = (value: unknown): string | null => {
  if (typeof value !== 'string') {
    return null
  }

  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

type MetricRow = {
  timestamp: Date
  event: string
  service: string
  environment: string
  region: string | null
  requestId: string | null
  method: string | null
  path: string | null
  status: number | null
  durationMs: number | null
  payload: AppLogPayload
}

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const asSafePayload = (value: AppLogPayload): Record<string, unknown> => asRecord(value) ?? {}

const asDate = (value: unknown): Date | null => {
  if (!value) {
    return null
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = new Date(value)
    return Number.isNaN(parsed.getTime()) ? null : parsed
  }
  return null
}

const asNumber = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value
  }
  if (typeof value === "bigint") {
    return Number(value)
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = Number.parseFloat(value)
    return Number.isFinite(parsed) ? parsed : null
  }
  return null
}

const asInt = (value: unknown, fallback = 0): number => {
  const parsed = asNumber(value)
  return parsed === null ? fallback : Math.max(0, Math.floor(parsed))
}

const asNullableInt = (value: unknown): number | null => {
  const parsed = asNumber(value)
  return parsed === null ? null : Math.max(0, Math.floor(parsed))
}

const asString = (value: unknown): string | null =>
  typeof value === "string" && value.trim().length > 0 ? value.trim() : null

const lower = (value: string | null | undefined) => (value ?? "").trim().toLowerCase()

const sameIgnoreCase = (left: string | null, right: string | null) =>
  left !== null && right !== null && lower(left) === lower(right)

const percentile = (values: number[], p: number): number | null => {
  if (values.length === 0) {
    return null
  }
  const sorted = [...values].sort((a, b) => a - b)
  const rank = Math.max(0, Math.min(sorted.length - 1, Math.ceil(p * sorted.length) - 1))
  const value = sorted[rank]
  return Number.isFinite(value) ? Math.max(0, Math.round(value)) : null
}

const readThreshold = (key: string, fallback: number): number => {
  const raw = process.env[key]
  if (!raw || raw.trim().length === 0) {
    return fallback
  }
  const parsed = Number.parseFloat(raw)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return fallback
  }
  return parsed
}

