    p95LatencyMsCritical: readThreshold("OBS_ALERT_API_P95_LATENCY_MS_CRITICAL", 2_500),
    errorRatePctWarning: readThreshold("OBS_ALERT_API_ERROR_RATE_PCT_WARNING", 2),
    errorRatePctCritical: readThreshold("OBS_ALERT_API_ERROR_RATE_PCT_CRITICAL", 5),
  },
  indexingMetrics: {
    durationMsWarning: readThreshold("OBS_ALERT_INDEXING_DURATION_MS_WARNING", 120_000),
    durationMsCritical: readThreshold("OBS_ALERT_INDEXING_DURATION_MS_CRITICAL", 300_000),
    failuresWarning: readThreshold("OBS_ALERT_INDEXING_FAILURES_WARNING", 5),
    failuresCritical: readThreshold("OBS_ALERT_INDEXING_FAILURES_CRITICAL", 10),
    embeddingApiCallsWarning: readThreshold("OBS_ALERT_INDEXING_EMBEDDING_CALLS_WARNING", 200),
    embeddingApiCallsCritical: readThreshold("OBS_ALERT_INDEXING_EMBEDDING_CALLS_CRITICAL", 1_000),
  },
  llmMetrics: {
