    totalTokensWarning: readThreshold("OBS_ALERT_LLM_TOTAL_TOKENS_WARNING", 200_000),
    totalTokensCritical: readThreshold("OBS_ALERT_LLM_TOTAL_TOKENS_CRITICAL", 1_000_000),
  },
})

const readProviderAndModel = (payload: Record<string, unknown>) => {
  const labels = asRecord(payload.labels)
  const llmMetrics = asRecord(payload.llmMetrics)
  const provider =
    asString(labels?.provider) ??
    asString(llmMetrics?.provider) ??
    null
  const model =
    asString(labels?.model) ??
    asString(llmMetrics?.model) ??
    asString(payload.model) ??
    null
  return { provider, model }
}

const resolveWindow = (args: {
  sinceRaw?: string
  untilRaw?: string
  windowHours: number
}) => {
  const now = new Date()
  const until = args.untilRaw ? asDate(args.untilRaw) : now
  if (!until) {
    return { error: "Invalid until date." as const, since: null, until: null }
  }
  const since = args.sinceRaw
    ? asDate(args.sinceRaw)
    : new Date(until.getTime() - args.windowHours * 60 * 60 * 1_000)
  if (!since) {
    return { error: "Invalid since date." as const, since: null, until: null }
  }
  if (until.getTime() < since.getTime()) {
    return { error: "until cannot be before since." as const, since: null, until: null }
  }
  return { error: null, since, until }
}

