  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid query params." }, { status: 400 }),
  }
}

const resolvedWindow = resolveWindow({
  sinceRaw: parsed.data.since,
  untilRaw: parsed.data.until,
  windowHours: parsed.data.windowHours,
})

if (resolvedWindow.error || !resolvedWindow.since || !resolvedWindow.until) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: resolvedWindow.error ?? "Invalid time window." },
      { status: 400 },
    ),
  }
}

const sqlFilters = buildSqlFilters({
  since: resolvedWindow.since,
  until: resolvedWindow.until,
  service: parsed.data.service,
  environment: parsed.data.environment,
  region: parsed.data.region,
  event: parsed.data.event,
  path: parsed.data.path,
  method: parsed.data.method,
  status: parsed.data.status,
  requestId: parsed.data.requestId,
})
const where = and(...sqlFilters)

      logger.set({
        since: resolvedWindow.since.toISOString(),
        until: resolvedWindow.until.toISOString(),
        windowHours: parsed.data.windowHours,
        sampleLimit: parsed.data.limit,
        sampledEvents: asInt(totalRows[0]?.total, 0),
        returnedEvents: rows.length,
        labels: responsePayload.labels,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json(responsePayload),
      }
    },
  })
}

