import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { Indexer, KiteDB } from '../../js/sdk.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..', '..')
const projectRoot = process.env.PROJECT_ROOT ?? packageRoot
const query = process.env.CODE_INTEL_QUERY ?? 'Where is vector indexing implemented?'

const ix = new Indexer({ root: projectRoot })
ix.paths('src').include('*.ts', '*.tsx', '*.js', '*.jsx', '*.rs', '*.py')
ix.exclude('node_modules', 'dist', '__pycache__', '.venv')
ix.useVectors({ model: 'text-embedding-3-small' })

const db = new KiteDB({ root: projectRoot })

const run = await ix.persist({ db, clear: true })
console.log(`indexed ${run.fileCount} files in ${run.duration.toFixed(2)}s -> ${db.path}`)

const hits = await ix.search(query, { db, topK: 5 })
for (const [idx, hit] of hits.entries()) {
  console.log(`${idx + 1}. ${hit.score.toFixed(4)} ${hit.chunkId} ${hit.filePath ?? ''}`)
}

import { afterEach, describe, expect, mock, test } from "bun:test";

const loadCleanupModule = async (rowsByCall: Array<{ rows: Array<Record<string, unknown>> }>) => {
  const execute = mock(async () => rowsByCall.shift() ?? { rows: [] });
  mock.module("@/lib/db", () => ({
    db: {
      execute,
    },
  }));

  const logRetentionModule = await import(
    `./log-retention?cacheBust=${Math.random().toString(36).slice(2)}`,
  );
  return {
    cleanupAppLogs: logRetentionModule.cleanupAppLogs as (options?: {
      retentionDays?: number;
      maxRows?: number;
      deleteLimit?: number;
    }) => Promise<{
      deletedByAge: number;
      deletedByCap: number;
      rowsBefore: number | null;
      rowsAfter: number | null;
    }>,
  };
};

describe("cleanupAppLogs", () => {
  afterEach(() => {
    mock.restore();
  });

  test("applies age and cap policy in one cleanup run", async () => {
    const { cleanupAppLogs } = await loadCleanupModule([
      { rows: [{ count: 10 }] },
      { rows: [{ id: "age-1" }, { id: "age-2" }, { id: "age-3" }] },
      { rows: [{ id: "cap-1" }, { id: "cap-2" }] },
    ]);

    const summary = await cleanupAppLogs({
      retentionDays: 30,
      maxRows: 5,
      deleteLimit: 10,
    });

    expect(summary.rowsBefore).toBe(10);
    expect(summary.deletedByAge).toBe(3);
    expect(summary.deletedByCap).toBe(2);
    expect(summary.rowsAfter).toBe(5);
  });

  test("enforces deleteLimit while capping rows", async () => {
    const { cleanupAppLogs } = await loadCleanupModule([
      { rows: [{ count: 100 }] },
      { rows: [] },
      { rows: [{ id: "cap-1" }, { id: "cap-2" }, { id: "cap-3" }, { id: "cap-4" }] },
    ]);

    const summary = await cleanupAppLogs({
      retentionDays: 30,
      maxRows: 10,
      deleteLimit: 4,
    });

    expect(summary.deletedByAge).toBe(0);
    expect(summary.deletedByCap).toBe(4);
    expect(summary.rowsAfter).toBe(96);
  });
});

use std::path::{Path, PathBuf};

use napi::bindgen_prelude::{Env, Object, Unknown};
use napi::{Error, JsValue, Result};
use napi_derive::napi;

use crate::core::parse::chunker::TreeSitterChunker;
use crate::core::parse::languages::parse_language_name;
use crate::core::parse::registry::{
  register_language, ChunkKind, CustomGrammarSource, CustomQuerySet, RegisterLanguageOptions,
};
use crate::path_policy::resolve_path_within_root;

use super::path::{read_text_file, required_string};

const QUERY_FIELD_NAMES: [&str; 7] = [
  "functions",
  "classes",
  "types",
  "variables",
  "imports",
  "exports",
  "comments",
];

#[napi(js_name = "chunkFile")]
#[allow(dead_code)]
pub fn chunk_file(options: Object<'_>) -> Result<Unknown<'_>> {
  let env_raw = options.value().env;
  let file_path = required_string(&options, "filePath")?;
  let content = resolve_chunk_content(&options, &file_path)?;
  let language = options.get::<String>("language")?;

  let chunks =
    TreeSitterChunker::chunk_file_with_language(&file_path, &content, language.as_deref());
  let value = serde_json::to_value(chunks).map_err(|err| Error::from_reason(err.to_string()))?;

  let env = Env::from_raw(env_raw);
  let js = env.to_js_value(&value)?;
  // SAFETY: `js` was created from the same `env_raw` immediately above, so the env/value pair is
  // valid and can be wrapped as `Unknown`.
  Ok(unsafe { Unknown::from_raw_unchecked(env_raw, js.raw()) })
}

#[napi(js_name = "registerChunkLanguage")]
#[allow(dead_code)]
pub fn register_chunk_language(options: Object<'_>) -> Result<()> {

let id = required_string(&options, "id")?;
let extensions = options
  .get::<Vec<String>>("extensions")?
  .ok_or_else(|| Error::from_reason("missing required field: extensions".to_string()))?;

let grammar_obj = options
  .get::<Object<'_>>("grammar")?
  .ok_or_else(|| Error::from_reason("missing required field: grammar".to_string()))?;
let grammar_kind = grammar_obj
  .get::<String>("kind")?
  .unwrap_or_else(|| "builtin".to_string());
let grammar = match grammar_kind.as_str() {
  "builtin" => {
    let builtin = required_string(&grammar_obj, "builtin")?;
    let language = parse_language_name(&builtin).ok_or_else(|| {
      Error::from_reason(format!("unsupported built-in grammar language: {builtin}"))
    })?;
    CustomGrammarSource::Builtin(language)
  }
  "dylib" => {
    let path = required_string(&grammar_obj, "dylibPath")?;
    let symbol = required_string(&grammar_obj, "symbol")?;
    CustomGrammarSource::Dylib {
      path: PathBuf::from(path),
      symbol,
    }
  }
  _ => {
    return Err(Error::from_reason(format!(
      "unsupported grammar kind: {grammar_kind}"
    )));
  }
};

let queries = parse_custom_queries(&options)?;

let chunk_kinds = options
  .get::<Vec<String>>("chunkKinds")?
  .unwrap_or_default()
  .into_iter()
  .map(|name| {
    ChunkKind::from_name(name.as_str())
      .ok_or_else(|| Error::from_reason(format!("unsupported chunk kind: {name}")))
  })
  .collect::<Result<Vec<_>>>()?;

  let registration = RegisterLanguageOptions {
    id,
    extensions,
    grammar,
    queries,
    chunk_kinds,
  };
  register_language(registration).map_err(Error::from_reason)?;
  Ok(())
}

fn resolve_chunk_content(options: &Object<'_>, file_path: &str) -> Result<String> {
  let read_root = std::env::current_dir()
    .map_err(|err| Error::from_reason(format!("failed to resolve current directory: {err}")))?;
  let inline = options.get::<String>("content")?;
  let content_path = options.get::<String>("contentPath")?;
  if inline.is_some() && content_path.is_some() {
    return Err(Error::from_reason(
      "chunkFile accepts either content or contentPath, not both".to_string(),
    ));
  }
  if let Some(content) = inline {
    return Ok(content);
  }
  if let Some(path) = content_path {
    let path = resolve_path_within_root(&read_root, Path::new(&path), "contentPath")
      .map_err(Error::from_reason)?;
    return read_text_file(path);
  }

  let candidate = resolve_path_within_root(&read_root, Path::new(file_path), "filePath")
    .map_err(Error::from_reason)?;
  if candidate.is_file() {
    return read_text_file(candidate);
  }

  Err(Error::from_reason(
    "chunkFile requires content or contentPath (or a readable filePath on disk)".to_string(),
  ))
}

fn parse_custom_queries(options: &Object<'_>) -> Result<CustomQuerySet> {
  let mut queries = CustomQuerySet::default();
  let read_root = std::env::current_dir()
    .map_err(|err| Error::from_reason(format!("failed to resolve current directory: {err}")))?;

if let Some(dir) = options.get::<String>("queriesDir")? {
  let dir = resolve_path_within_root(&read_root, Path::new(&dir), "queriesDir")
    .map_err(Error::from_reason)?;
  for field in QUERY_FIELD_NAMES {
    let path = dir.join(format!("{field}.scm"));
    if path.is_file() {
      set_query_field(&mut queries, field, Some(read_text_file(path)?));
    }
  }
}

if let Some(query_paths) = options.get::<Object<'_>>("queryPaths")? {
  for field in QUERY_FIELD_NAMES {
    if let Some(path) = query_paths.get::<String>(field)? {
      let path = resolve_path_within_root(&read_root, Path::new(&path), "queryPaths")
        .map_err(Error::from_reason)?;
      set_query_field(&mut queries, field, Some(read_text_file(path)?));
    }
  }
}

  if let Some(inline) = options.get::<Object<'_>>("queries")? {
    for field in QUERY_FIELD_NAMES {
      let path_key = format!("{field}Path");
      if let Some(path) = inline.get::<String>(&path_key)? {
        let path = resolve_path_within_root(&read_root, Path::new(&path), &path_key)
          .map_err(Error::from_reason)?;
        set_query_field(&mut queries, field, Some(read_text_file(path)?));
      }
    }
    if let Some(value) = inline.get::<String>("functions")? {
      queries.functions = Some(value);
    }
    if let Some(value) = inline.get::<String>("classes")? {
      queries.classes = Some(value);
    }
    if let Some(value) = inline.get::<String>("types")? {
      queries.types = Some(value);
    }
    if let Some(value) = inline.get::<String>("variables")? {
      queries.variables = Some(value);
    }
    if let Some(value) = inline.get::<String>("imports")? {
      queries.imports = Some(value);
    }
    if let Some(value) = inline.get::<String>("exports")? {
      queries.exports = Some(value);
    }
    if let Some(value) = inline.get::<String>("comments")? {
      queries.comments = Some(value);
    }
  }

  Ok(queries)
}

fn set_query_field(queries: &mut CustomQuerySet, field: &str, value: Option<String>) {
  match field {
    "functions" => queries.functions = value,
    "classes" => queries.classes = value,
    "types" => queries.types = value,
    "variables" => queries.variables = value,
    "imports" => queries.imports = value,
    "exports" => queries.exports = value,
    "comments" => queries.comments = value,
    _ => {}
  }
}

