#[test]
fn emits_relationship_edges_for_inheritance_and_types() -> Result<(), Box<dyn std::error::Error>>
{
  let temp = tempfile::tempdir()?;
  let path = temp.path().join("index.scip");

  let mut doc = Document::new();

doc.relative_path = "src/model.ts".to_string();
doc.language = "typescript".to_string();

let mut animal = SymbolInformation::new();
animal.symbol = "scip:animal".to_string();
animal.display_name = "Animal".to_string();
animal.kind = ScipKind::Interface.into();

let mut dog = SymbolInformation::new();
dog.symbol = "scip:dog".to_string();
dog.display_name = "Dog".to_string();
dog.kind = ScipKind::Class.into();
dog.relationships.push(Relationship {
  symbol: "scip:animal".to_string(),
  is_implementation: true,
  ..Relationship::new()
});

let mut alias = SymbolInformation::new();
alias.symbol = "scip:name_alias".to_string();
alias.display_name = "Name".to_string();
alias.kind = ScipKind::TypeAlias.into();
alias.relationships.push(Relationship {
  symbol: "scip:string".to_string(),
  is_type_definition: true,
  ..Relationship::new()
});

let mut base_method = SymbolInformation::new();
base_method.symbol = "scip:base_sound".to_string();
base_method.display_name = "sound".to_string();
base_method.kind = ScipKind::Method.into();

let mut dog_method = SymbolInformation::new();
dog_method.symbol = "scip:dog_sound".to_string();
dog_method.display_name = "sound".to_string();
dog_method.kind = ScipKind::Method.into();
dog_method.relationships.push(Relationship {
  symbol: "scip:base_sound".to_string(),
  is_definition: true,
  ..Relationship::new()
});

doc
  .symbols
  .extend([animal, dog, alias, base_method, dog_method]);

  for (line, symbol) in [
    (0, "scip:animal"),
    (1, "scip:dog"),
    (2, "scip:name_alias"),
    (3, "scip:base_sound"),
    (4, "scip:dog_sound"),
  ] {
    let mut def_occ = Occurrence::new();
    def_occ.symbol = symbol.to_string();
    def_occ.range = vec![line, 0, line, 4];
    def_occ.symbol_roles = SYMBOL_ROLE_DEFINITION;
    doc.occurrences.push(def_occ);
  }

  let mut index = Index::new();
  index.documents.push(doc);
  let bytes = index.write_to_bytes()?;
  fs::write(&path, bytes)?;

  let artifacts = ScipBinaryProvider::parse_file(&path, temp.path())?;
  assert!(artifacts
    .edges
    .iter()
    .any(|edge| edge.edge_type == "IMPLEMENTS"
      && edge.source_id == "scip:dog"
      && edge.target_id == "scip:animal"));
  assert!(artifacts
    .edges
    .iter()
    .any(|edge| edge.edge_type == "HAS_TYPE"
      && edge.source_id == "scip:name_alias"
      && edge.target_id == "scip:string"));
  assert!(artifacts
    .edges
    .iter()
    .any(|edge| edge.edge_type == "OVERRIDES"
      && edge.source_id == "scip:dog_sound"
      && edge.target_id == "scip:base_sound"));
  Ok(())
}

#[test]

  fn rejects_oversized_binary_index_before_parse() -> Result<(), Box<dyn std::error::Error>> {
    let temp = tempfile::tempdir()?;
    let path = temp.path().join("oversized.scip");
    fs::write(&path, vec![0_u8; 1024])?;
    let error = ScipBinaryProvider::parse_file_with_limit(&path, temp.path(), 32)
      .expect_err("expected oversized file error");
    assert!(error.to_string().contains("scip file too large"));
    Ok(())
  }
}

