const CONFIG_HASH_PATTERN = /^[A-Za-z0-9._-]{1,120}$/

type PlanProcessorDeps = {
  source: GitLabSource
}

const defaultDeps = (): PlanProcessorDeps => ({
  source: createGitLabSource(),
})

const resolveDeltaFallbackThreshold = () =>
  parsePositiveInt(process.env.INDEXER_DELTA_FALLBACK_THRESHOLD, DEFAULT_DELTA_FALLBACK_THRESHOLD)

const isEnvTruthy = (value: string | undefined): boolean => {
  if (!value) {
    return false
  }

  const normalized = value.trim().toLowerCase()
  return normalized === '1' || normalized === 'true' || normalized === 'yes' || normalized === 'on'
}

const isEnvFalsy = (value: string | undefined): boolean => {
  if (!value) {
    return false
  }

  const normalized = value.trim().toLowerCase()
  return normalized === '0' || normalized === 'false' || normalized === 'no' || normalized === 'off'
}

const resolveDeltaModeEnabled = (): boolean => {
  if (isEnvTruthy(process.env.INDEXER_FORCE_SNAPSHOT)) {
    return false
  }

  const configured = process.env.INDEXER_ENABLE_DELTA
  if (isEnvFalsy(configured)) {
    return false
  }

  if (isEnvTruthy(configured)) {
    return true
  }

  // Default-on for Phase 2 rollout; keep INDEXER_FORCE_SNAPSHOT as emergency override.
  return true
}

