ALTER TABLE "index_branch_states" ADD COLUMN "pending_prune_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "index_branch_states" ADD COLUMN "pending_prune_reason" text;--> statement-breakpoint
CREATE INDEX "index_branch_states_integration_pending_prune_idx" ON "index_branch_states" USING btree ("integration_id","pending_prune_at");

import { eq } from 'drizzle-orm'
import { parsePositiveInt } from '@argus/shared-runtime/config-env'

import { GitLabApiError } from '@/lib/gitlab/client'
import { db } from '@/lib/db'
import { indexBranchStates, indexRuns } from '@/lib/db/schema'
import type { ReconcileJob } from '@argus/contracts-indexing'
import { enqueuePlanJob } from '@/lib/indexing/job-queue'
import { createGitLabSource } from '@/lib/indexing/sources/gitlab-source'
import { createArtifactCleanupStore } from '@/lib/indexing/stores/artifact-cleanup-store'

const resolveBranchLimit = () => parsePositiveInt(process.env.INDEXER_RECONCILE_BRANCH_LIMIT, 100)
const DEFAULT_BRANCH_PRUNE_GRACE_MS = 24 * 60 * 60_000
const DEFAULT_BRANCH_PRUNE_MAX_PER_JOB = 20
const PENDING_ARTIFACTS_PREFIX = 'pending'
const PRUNED_ARTIFACTS_PREFIX = 'pruned:'

const isEnvTruthy = (value: string | undefined): boolean => {
  if (!value) {
    return false
  }

  const normalized = value.trim().toLowerCase()
  return normalized === '1' || normalized === 'true' || normalized === 'yes' || normalized === 'on'
}

const isEnvFalsy = (value: string | undefined): boolean => {
  if (!value) {
    return false
  }

  const normalized = value.trim().toLowerCase()
  return normalized === '0' || normalized === 'false' || normalized === 'no' || normalized === 'off'
}

const resolveBranchPruneEnabled = () => {
  const configured = process.env.INDEXER_BRANCH_PRUNE_ENABLED
  if (isEnvFalsy(configured)) {
    return false
  }
  if (isEnvTruthy(configured)) {
    return true
  }
  return true
}

const resolveBranchPruneGraceMs = () =>
  parsePositiveInt(process.env.INDEXER_BRANCH_PRUNE_GRACE_MS, DEFAULT_BRANCH_PRUNE_GRACE_MS)

const resolveBranchPruneMaxPerJob = () =>
  parsePositiveInt(process.env.INDEXER_BRANCH_PRUNE_MAX_PER_JOB, DEFAULT_BRANCH_PRUNE_MAX_PER_JOB)

const isMissingBranchError = (error: unknown) =>
  error instanceof GitLabApiError && error.status === 404

const toErrorCode = (error: unknown) => {
  if (error instanceof GitLabApiError) {
    return `gitlab_${error.status}`
  }
  return 'reconcile_branch_check_failed'
}

const toErrorDetail = (error: unknown) => {
  if (error instanceof Error) {
    return error.message.slice(0, 500)
  }
  if (typeof error === 'string') {
    return error.slice(0, 500)
  }
  return null
}

const toDateOrNull = (value: unknown): Date | null => {
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return value
  }
  return null
}

const clearPendingPruneState = async (branchStateId: string) => {
  await db
    .update(indexBranchStates)
    .set({
      pendingPruneAt: null,
      pendingPruneReason: null,
      updatedAt: new Date(),
    })
    .where(eq(indexBranchStates.id, branchStateId))
}

const markBranchPendingPrune = async (args: {
  branchStateId: string
  pendingPruneAt: Date | null
  reason: string
}) => {
  if (args.pendingPruneAt) {
    await db
      .update(indexBranchStates)
      .set({
        pendingPruneReason: args.reason,
        updatedAt: new Date(),
      })
      .where(eq(indexBranchStates.id, args.branchStateId))
    return args.pendingPruneAt
  }

  const pendingPruneAt = new Date()
  await db
    .update(indexBranchStates)
    .set({
      pendingPruneAt,
      pendingPruneReason: args.reason,
      updatedAt: pendingPruneAt,
    })
    .where(eq(indexBranchStates.id, args.branchStateId))
  return pendingPruneAt
}

const listBranchArtifactsPrefixes = async (branchStateId: string) => {
  const runRows = await db
    .select({
      artifactsPrefix: indexRuns.artifactsPrefix,
    })
    .from(indexRuns)
    .where(eq(indexRuns.branchStateId, branchStateId))

  return Array.from(
    new Set(
      runRows
        .map((row) => row.artifactsPrefix?.trim() ?? '')
        .filter(
          (prefix) =>
            prefix.length > 0 &&
            prefix !== PENDING_ARTIFACTS_PREFIX &&
            !prefix.startsWith(PRUNED_ARTIFACTS_PREFIX),
        ),
    ),
  )
}

const pruneBranchState = async (args: {
  branchStateId: string
  cleanupStore: ReturnType<typeof createArtifactCleanupStore>
}) => {
  const artifactsPrefixes = await listBranchArtifactsPrefixes(args.branchStateId)
  for (const artifactsPrefix of artifactsPrefixes) {
    await args.cleanupStore.deletePrefix({ artifactsPrefix })
  }

  await db.delete(indexBranchStates).where(eq(indexBranchStates.id, args.branchStateId))
}

export const processReconcileJob = async (job: ReconcileJob) => {
  const source = createGitLabSource()
  const cleanupStore = createArtifactCleanupStore()
  const nowMs = Date.now()
  const pruneEnabled = resolveBranchPruneEnabled()
  const pruneGraceMs = resolveBranchPruneGraceMs()
  const pruneMaxPerJob = resolveBranchPruneMaxPerJob()
  const branches = await db
    .select({
      id: indexBranchStates.id,
      branch: indexBranchStates.branch,
      configHash: indexBranchStates.configHash,
      lastReadySha: indexBranchStates.lastReadySha,
      pendingPruneAt: indexBranchStates.pendingPruneAt,
    })
    .from(indexBranchStates)
    .where(eq(indexBranchStates.integrationId, job.integrationId))
    .limit(resolveBranchLimit())

  let defaultBranch: string | null = null
  let defaultBranchLookupFailed = false
  if (pruneEnabled) {
    try {
      defaultBranch = await source.resolveDefaultBranch({
        integrationId: job.integrationId,
      })
    } catch {
      defaultBranchLookupFailed = true
    }
  }

  let checked = 0
  let enqueued = 0
  let missing = 0
  let scheduledForPrune = 0
  let pruned = 0
  let pruneErrors = 0

let prunedThisJob = 0
const branchChecks: Array<{
  branch: string
  configHash: string
  lastReadySha: string | null
  headSha: string | null
  enqueued: boolean
  missing: boolean
  pendingPruneAt: string | null
  pruned: boolean
  errorCode: string | null
  errorDetail: string | null
}> = []

for (const branchState of branches) {
  checked += 1
  try {
    const headSha = await source.resolveHeadSha({
      integrationId: job.integrationId,
      branch: branchState.branch,
    })

    if (branchState.pendingPruneAt) {
      await clearPendingPruneState(branchState.id)
    }

    const isStale = branchState.lastReadySha !== headSha

    if (isStale) {
      await enqueuePlanJob({
        integrationId: job.integrationId,
        branch: branchState.branch,
        configHash: branchState.configHash,
        hintedHeadSha: headSha,
      })
      enqueued += 1
    }

    branchChecks.push({
      branch: branchState.branch,
      configHash: branchState.configHash,
      lastReadySha: branchState.lastReadySha,
      headSha,
      enqueued: isStale,
      missing: false,
      pendingPruneAt: null,
      pruned: false,
      errorCode: null,
      errorDetail: null,
    })
    continue
  } catch (error) {
    if (isMissingBranchError(error)) {
      missing += 1

const pendingPruneAt = await markBranchPendingPrune({
  branchStateId: branchState.id,
  pendingPruneAt: toDateOrNull(branchState.pendingPruneAt),
  reason: 'branch_missing',
})

const shouldProtectDefaultBranch = defaultBranch
  ? branchState.branch === defaultBranch
  : defaultBranchLookupFailed
const graceElapsed = nowMs >= pendingPruneAt.getTime() + pruneGraceMs
const canPruneNow =
  pruneEnabled &&
  !shouldProtectDefaultBranch &&
  graceElapsed &&
  prunedThisJob < pruneMaxPerJob

let wasPruned = false
let errorCode: string | null = null
let errorDetail: string | null = null

