		params.set("graphTraceNodeId", sourceNodeId);
		if (integrationId?.trim()) {
			params.set("graphTraceIntegrationId", integrationId.trim());
		}
		const sourceBranch = mergeRequestBranchInfo?.sourceBranch?.trim();
		if (sourceBranch) {
			params.set("graphTraceBranch", sourceBranch);
		}
		params.set("graphTraceRun", "1");
		return `${baseHref}?${params.toString()}`;
	},
	[integrationId, mergeRequestBranchInfo?.sourceBranch],
);

const manualCommentLineRange = useMemo(() => {
	if (!manualCommentSelection) {
		return null;
	}
	return toLineRange(manualCommentSelection.range);
}, [manualCommentSelection]);
const manualDraftAnnotationsByFileKey = useMemo<
	Record<string, InlineDiffAnnotation[]>
>(() => {
	if (!manualCommentSelection || !manualCommentLineRange) {
		return {};
	}

	const selectedSide = manualCommentSelection.range.side ?? "additions";
	const filePath =
		selectedSide === "deletions"
			? manualCommentSelection.file.prevName ?? manualCommentSelection.file.name
			: manualCommentSelection.file.name ?? manualCommentSelection.file.prevName;
	if (!filePath) {
		return {};
	}

	return {
		[manualCommentSelection.fileKey]: [
			{
				side: selectedSide,
				lineNumber: manualCommentLineRange.end,
				metadata: {
					kind: "manual-draft",
					filePath,
					rangeStart: manualCommentLineRange.start,
					rangeEnd: manualCommentLineRange.end,
				},
			},
		],
	};
}, [manualCommentLineRange, manualCommentSelection]);
const handleSubmitManualComment = useCallback(async () => {
	if (!manualCommentSelection || !manualCommentLineRange) {
		setManualCommentError("Select at least one line before posting.");
		return;
	}

	const commentBody = manualCommentBody.trim();
	if (!commentBody) {
		setManualCommentError("Comment body is required.");
		return;
	}

	const selectedSide = manualCommentSelection.range.side ?? "additions";
	const endSide = manualCommentSelection.range.endSide;

if (endSide && endSide !== selectedSide) {
	setManualCommentError(
		"Selection crosses additions and deletions. Select one side only.",
	);
	return;
}

const normalizedFilePath = normalizePatchPath(manualCommentSelection.file.name);
const normalizedPrevPath = manualCommentSelection.file.prevName
	? normalizePatchPath(manualCommentSelection.file.prevName)
	: null;
const oldPath = normalizedPrevPath ?? normalizedFilePath;
const newPath = normalizedFilePath || normalizedPrevPath;
const commentFilePath =
	selectedSide === "deletions"
		? oldPath || newPath
		: newPath || oldPath;

if (!commentFilePath) {
	setManualCommentError("Unable to resolve comment file path.");
	return;
}

setIsSubmittingManualComment(true);
setManualCommentError("");
setManualCommentSuccess("");

try {
	let postedCount = 0;
	for (
		let line = manualCommentLineRange.start;
		line <= manualCommentLineRange.end;
		line += 1
	) {
		const response = await fetch("/api/gitlab", {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
			},
			body: JSON.stringify({
				action: "create-merge-request-discussion",
				instanceUrl,
				token,
				integrationId,
				projectId,
				mergeRequestIid,
				commentBody,
				commentLine: line,
				commentSide: selectedSide,
				commentFilePath,
				commentOldPath: oldPath,
				commentNewPath: newPath,
			}),
		});

		if (!response.ok) {
			let detail = `Failed to post comment at line ${line}.`;
			try {
				const payload = (await response.json()) as {
					error?: unknown;
				};
				if (typeof payload?.error === "string" && payload.error.trim()) {
					detail = payload.error;
				}
			} catch {
				// best effort
			}
			throw new Error(detail);
		}

		postedCount += 1;
	}

	setManualCommentSuccess(
		postedCount === 1
			? "Comment posted to GitLab."
			: `Posted ${postedCount} comments to GitLab (one per selected line).`,
	);
	setManualCommentBody("");
} catch (error) {
	setManualCommentError(
		error instanceof Error && error.message.trim()
			? error.message
			: "Unable to post comment to GitLab.",
	);
} finally {
	setIsSubmittingManualComment(false);
}

}, [
	instanceUrl,
	integrationId,
	manualCommentBody,
	manualCommentLineRange,
	manualCommentSelection,
	mergeRequestIid,
	projectId,
	token,
]);

const renderReviewAnnotation = useCallback(
	(annotation: InlineDiffAnnotation): ReactNode => {
		if (isManualDraftAnnotation(annotation)) {
			return (
				<ManualDraftAnnotation
					metadata={annotation.metadata}
					manualCommentBody={manualCommentBody}
					manualCommentError={manualCommentError}
					manualCommentSuccess={manualCommentSuccess}
					isSubmittingManualComment={isSubmittingManualComment}
					onChangeBody={setManualCommentBody}
					onClearSelection={() => {
						setManualCommentSelection(null);
						setManualCommentError("");
						setManualCommentSuccess("");
					}}
					onSubmit={() => void handleSubmitManualComment()}
				/>
			);
		}

		return renderMergeRequestReviewAnnotation(
			annotation as DiffLineAnnotation<ReviewAnnotationMetadata>,
			{
				onSubmitFeedback: onSubmitReviewCommentFeedback,
				onPostToGitLab: onPostReviewCommentToGitLab,
				onRemoveFromGitLab: onRemoveReviewCommentFromGitLab,
				onQueueImpactBranchIndexing,
				onAnnotationLayoutChange: handleAnnotationLayoutChange,
				buildImpactGraphHref,
			},
		);
	},
	[
		buildImpactGraphHref,
		handleAnnotationLayoutChange,
		handleSubmitManualComment,
		isSubmittingManualComment,
		manualCommentBody,
		manualCommentError,
		manualCommentSuccess,
		onQueueImpactBranchIndexing,
		onPostReviewCommentToGitLab,
		onRemoveReviewCommentFromGitLab,
		onSubmitReviewCommentFeedback,
	],
);

const reviewCommentTargets = useMemo<ReviewCommentNavigationTarget[]>(() => {
	const next: ReviewCommentNavigationTarget[] = [];
	for (const file of visibleFiles) {
		const fileKey = getFileKey(file);
		const annotations = reviewAnnotationsByFileKey[fileKey] ?? [];
		for (const annotation of annotations) {
			const feedbackKey = annotation.metadata.feedbackKey.trim();
			if (!feedbackKey) {
				continue;
			}
			next.push({
				feedbackKey,
				file,
				fileKey,
			});
		}
	}
	return next;
}, [getFileKey, reviewAnnotationsByFileKey, visibleFiles]);
const scrollToCommentByKey = useCallback((feedbackKey: string) => {
	const selector = `[data-review-comment-key="${escapeAttributeValueForSelector(feedbackKey)}"]`;
	const target =
		scrollContainerRef.current?.querySelector<HTMLElement>(selector) ??
		document.querySelector<HTMLElement>(selector);
	if (!target) {
		return false;
	}
	target.scrollIntoView({ behavior: "smooth", block: "center" });
	target.focus({ preventScroll: true });
	return true;
}, []);
const scheduleScrollToCommentByKey = useCallback(
	(feedbackKey: string) => {
		let attempts = 0;
		const maxAttempts = 12;
		const tryScroll = () => {
			if (scrollToCommentByKey(feedbackKey)) {
				return;
			}
			attempts += 1;
			if (attempts < maxAttempts) {
				window.requestAnimationFrame(tryScroll);
			}
		};
		window.requestAnimationFrame(tryScroll);
	},
	[scrollToCommentByKey],
);

const activeCommentIndex = useMemo(() => {
	if (reviewCommentTargets.length === 0) {
		return 0;
	}
	if (!activeCommentKey) {
		return 0;
	}
	const foundIndex = reviewCommentTargets.findIndex(
		(target) => target.feedbackKey === activeCommentKey,
	);
	return foundIndex >= 0 ? foundIndex : 0;
}, [activeCommentKey, reviewCommentTargets]);
const navigateReviewComments = useCallback(
	(direction: -1 | 1) => {
		if (reviewCommentTargets.length === 0) {
			return;
		}
		const total = reviewCommentTargets.length;
		const currentIndex = activeCommentKey
			? reviewCommentTargets.findIndex(
					(target) => target.feedbackKey === activeCommentKey,
				)
			: activeCommentIndex;
		const nextIndex =
			direction > 0
				? ((currentIndex >= 0 ? currentIndex : 0) + 1) % total
				: ((currentIndex >= 0 ? currentIndex : 0) - 1 + total) % total;
		const target = reviewCommentTargets[nextIndex];

		setActiveCommentKey(target.feedbackKey);
		if (collapsedFileKeys.has(target.fileKey)) {
			onToggleFileCollapsed(target.file);
		}
		scheduleScrollToCommentByKey(target.feedbackKey);
	},
	[
		activeCommentKey,
		activeCommentIndex,
		collapsedFileKeys,
		onToggleFileCollapsed,
		reviewCommentTargets,
		scheduleScrollToCommentByKey,
	],
);

const reviewStatusByFileKey = useMemo<Record<string, FileReviewStatus>>(() => {
	const next: Record<string, FileReviewStatus> = {};
	const { failedFilePaths, reviewedFilePaths, reviewingFilePaths } =
		normalizedReviewPathSets;
	// If the run failed before any file-level bookkeeping landed, mark all files failed.
	const markAllFailed =
		reviewRun.stage === "failed" &&
		failedFilePaths.size === 0 &&
		reviewRun.completedBatches === 0 &&
		reviewError.trim().length > 0;

	for (const file of visibleFiles) {
		const fileKey = getFileKey(file);
		const candidatePaths = normalizedFilePathsByKey.get(fileKey) ?? [];

		if (
			markAllFailed ||
			candidatePaths.some((path) => failedFilePaths.has(path))
		) {
			next[fileKey] = "failed";
			continue;
		}

		if (candidatePaths.some((path) => reviewingFilePaths.has(path))) {
			next[fileKey] = "reviewing";
			continue;
		}

		if (candidatePaths.some((path) => reviewedFilePaths.has(path))) {
			next[fileKey] = reviewCoverageByFileKey[fileKey] ? "issues" : "clean";
			continue;
		}

		next[fileKey] = "pending";
	}

	return next;
}, [
	getFileKey,
	normalizedFilePathsByKey,
	normalizedReviewPathSets,
	reviewCoverageByFileKey,
	reviewError,
	reviewRun.completedBatches,
	reviewRun.stage,
	visibleFiles,
]);

const visibleFileEntries = useMemo(() => {
	return visibleFiles.map((file) => {
		const fileKey = getFileKey(file);
		const reviewLineAnnotations =
			(reviewAnnotationsByFileKey[fileKey] as InlineDiffAnnotation[] | undefined) ??
			EMPTY_INLINE_ANNOTATIONS;
		const draftLineAnnotations =
			manualDraftAnnotationsByFileKey[fileKey] ?? EMPTY_INLINE_ANNOTATIONS;
		return {
			file,
			fileKey,
			isCollapsed: collapsedFileKeys.has(fileKey),
			lineAnnotations:
				draftLineAnnotations.length > 0
					? [...reviewLineAnnotations, ...draftLineAnnotations]
					: reviewLineAnnotations,
			reviewCoverage: reviewCoverageByFileKey[fileKey],
			reviewStatus: reviewStatusByFileKey[fileKey] ?? "pending",
		};
	});
}, [
	collapsedFileKeys,
	getFileKey,
	manualDraftAnnotationsByFileKey,
	reviewAnnotationsByFileKey,
	reviewCoverageByFileKey,
	reviewStatusByFileKey,
	visibleFiles,
]);

return (
	<div className="relative flex min-h-0 flex-1 flex-col overflow-hidden">
		<ForceReviewDialog
			open={isForceReviewPromptOpen}
			onDismiss={onDismissForceReviewPrompt}
			onUseExisting={onUseExistingReviewForPrompt}
			onForceReview={onForceReviewForPrompt}
		/>
		{/* ── header: fixed above scroll ── */}

{!isDiffBusy &&
	!loadError &&
	!parseError &&
	visibleFiles.length === 0 ? (
	<div className="rounded-lg border border-dashed border-border/50 px-4 py-10 text-center text-sm text-muted-foreground/70">
		No files match your current filter.
	</div>
) : null}

	{visibleFileEntries.length > 0 ? (
		<WorkerPoolContextProvider
			poolOptions={poolOptions}
			highlighterOptions={highlighterOptions}
		>
			<div className="space-y-3">
				{visibleFileEntries.map((entry) => {
					return (
						<div key={entry.fileKey}>
							<MergeRequestDiffFileHeader
								file={entry.file}
								isCollapsed={entry.isCollapsed}
								reviewCoverage={entry.reviewCoverage}
								reviewStatus={entry.reviewStatus}
								isDarkMode={isDarkMode}
								onToggleCollapsed={() =>
									onToggleFileCollapsed(entry.file)
								}
							/>
							{!entry.isCollapsed ? (

												) : null}
											</div>
										);
									})}
							</div>
						</WorkerPoolContextProvider>
					) : null}

					{canLoadMore ? (
						<div className="pt-2 pb-4">
							<Button
								type="button"
								variant="outline"
								onClick={onLoadMore}
								className="text-xs"
							>
								Load more files ({remainingFileCount} remaining)
							</Button>
						</div>
					) : null}
				</div>

			</div>
		</div>
	);
}

type ModuleShape = Record<string, unknown>

export const mergeModuleWithOverrides = <TModule extends ModuleShape>(
  actual: TModule,
  overrides: Partial<TModule>,
) => {
  const defaultExport =
    "default" in actual ? (actual as { default?: unknown }).default : undefined

  return {
    ...actual,
    default: defaultExport ?? actual,
    ...overrides,
  }
}

