type RangeLike = {
  start: { row: number; column?: number }
  end: { row: number; column?: number }
}

export type RankablePersistedGraphNode = {
  kind: string
  name: string | null
  range: RangeLike | null | undefined
}

export const includesLine = (node: RankablePersistedGraphNode, lineNumber: number) => {
  if (!node.range) {
    return false
  }
  const safeLine = Math.max(1, Math.floor(lineNumber))
  const zeroBasedLine = safeLine - 1
  return zeroBasedLine >= node.range.start.row && zeroBasedLine <= node.range.end.row
}

export const nodeSpanRows = (node: RankablePersistedGraphNode) => {
  if (!node.range) {
    return Number.POSITIVE_INFINITY
  }
  return Math.max(0, node.range.end.row - node.range.start.row)
}

export const nodeKindRank = (kind: string) => {
  switch (kind.toLowerCase()) {
    case "function":
    case "method":
      return 0
    case "class":
    case "interface":
    case "type":
      return 1
    case "variable":
    case "constant":
      return 2
    case "file":
      return 9
    default:
      return 4
  }
}

export const pickBestNode = <T extends RankablePersistedGraphNode>(nodes: T[]) => {
  if (nodes.length === 0) {
    return null
  }
  return [...nodes].sort((left, right) => {
    const spanDelta = nodeSpanRows(left) - nodeSpanRows(right)
    if (spanDelta !== 0) {
      return spanDelta
    }

    const rankDelta = nodeKindRank(left.kind) - nodeKindRank(right.kind)
    if (rankDelta !== 0) {
      return rankDelta
    }

    const leftName = left.name ?? ""
    const rightName = right.name ?? ""
    return leftName.localeCompare(rightName)
  })[0] ?? null
}

export const pickBestSymbolNode = <T extends RankablePersistedGraphNode>(
  nodes: T[],
  normalizedSymbol: string,
) => {
  if (nodes.length === 0) {
    return null
  }

  return [...nodes].sort((left, right) => {
    const leftName = (left.name ?? "").trim()
    const rightName = (right.name ?? "").trim()
    const leftLower = leftName.toLowerCase()
    const rightLower = rightName.toLowerCase()

    const leftExact = leftLower === normalizedSymbol ? 0 : 1
    const rightExact = rightLower === normalizedSymbol ? 0 : 1
    if (leftExact !== rightExact) {
      return leftExact - rightExact
    }

    const leftSuffix = leftLower.endsWith(`.${normalizedSymbol}`) ? 0 : 1
    const rightSuffix = rightLower.endsWith(`.${normalizedSymbol}`) ? 0 : 1
    if (leftSuffix !== rightSuffix) {
      return leftSuffix - rightSuffix
    }

    const leftContains = leftLower.includes(normalizedSymbol) ? 0 : 1
    const rightContains = rightLower.includes(normalizedSymbol) ? 0 : 1
    if (leftContains !== rightContains) {
      return leftContains - rightContains
    }

    const rankDelta = nodeKindRank(left.kind) - nodeKindRank(right.kind)
    if (rankDelta !== 0) {
      return rankDelta
    }

    const spanDelta = nodeSpanRows(left) - nodeSpanRows(right)
    if (spanDelta !== 0) {
      return spanDelta
    }

    return leftName.localeCompare(rightName)
  })[0] ?? null
}

export const isFunctionLikeKind = (kind: string) => {
  const normalized = kind.trim().toLowerCase()
  return normalized === "function" || normalized === "method"
}

export const distanceFromLine = (node: RankablePersistedGraphNode, line: number) => {
  if (!node.range) {
    return Number.POSITIVE_INFINITY
  }
  const target = Math.max(1, Math.floor(line)) - 1
  if (target < node.range.start.row) {
    return node.range.start.row - target
  }
  if (target > node.range.end.row) {
    return target - node.range.end.row
  }
  return 0
}

import { mkdir, readFile, readdir, rm, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'

import type { ArtifactStore } from '@argus/contracts-indexing'

const resolveArtifactsRoot = () =>
  process.env.INDEXER_ARTIFACTS_DIR?.trim() || path.join(process.cwd(), '.indexer-artifacts')

const writeLinesFile = async (filePath: string, lines: string[]) => {
  const payload = lines.length > 0 ? `${lines.join('\n')}\n` : ''
  await writeFile(filePath, payload, 'utf8')
}

export class FsArtifactStore implements ArtifactStore {
  private readonly root = resolveArtifactsRoot()
  private readonly resolvedRoot = path.resolve(this.root)

  private resolveRunDir(prefix: string) {
    const runDir = path.resolve(this.resolvedRoot, prefix)
    const rootWithSeparator = `${this.resolvedRoot}${path.sep}`
    const isWithinRoot = runDir === this.resolvedRoot || runDir.startsWith(rootWithSeparator)
    if (!isWithinRoot) {
      throw new Error("Invalid artifacts prefix path.")
    }

    return runDir
  }

  private async ensureRunDir(prefix: string) {
    const runDir = this.resolveRunDir(prefix)
    await mkdir(runDir, { recursive: true })
    return runDir
  }

private resolveRunFilePath(args: { artifactsPrefix: string; filename: string }) {
  const runDir = this.resolveRunDir(args.artifactsPrefix)
  const filePath = path.resolve(runDir, args.filename)
  const runDirWithSeparator = `${runDir}${path.sep}`
  const isWithinRunDir = filePath === runDir || filePath.startsWith(runDirWithSeparator)
  if (!isWithinRunDir) {
    throw new Error("Invalid artifact filename path.")
  }

  return filePath
}

private async inspectRunDir(runDir: string): Promise<{ bytes: number; objects: number }> {
  const walk = async (currentDir: string): Promise<{ bytes: number; objects: number }> => {
    const entries = await readdir(currentDir, { withFileTypes: true })
    let bytes = 0
    let objects = 0

    for (const entry of entries) {
      const entryPath = path.join(currentDir, entry.name)
      if (entry.isDirectory()) {
        const nested = await walk(entryPath)
        bytes += nested.bytes
        objects += nested.objects
        continue
      }

      if (!entry.isFile()) {
        continue
      }

      const fileStats = await stat(entryPath)
      bytes += fileStats.size
      objects += 1
    }

    return { bytes, objects }
  }

  try {
    return await walk(runDir)
  } catch (error) {
    if ((error as NodeJS.ErrnoException)?.code === 'ENOENT') {
      return { bytes: 0, objects: 0 }
    }
    throw error
  }
}

async writeRunJson(args: { artifactsPrefix: string; run: unknown }): Promise<void> {
  const runDir = await this.ensureRunDir(args.artifactsPrefix)
  await writeFile(path.join(runDir, 'run.json'), `${JSON.stringify(args.run, null, 2)}\n`, 'utf8')
}

async writeManifest(args: { artifactsPrefix: string; lines: string[] }): Promise<void> {
  const runDir = await this.ensureRunDir(args.artifactsPrefix)
  await writeLinesFile(path.join(runDir, 'manifest.jsonl'), args.lines)
}

async writeChangedFiles(args: { artifactsPrefix: string; lines: string[] }): Promise<void> {
  const runDir = await this.ensureRunDir(args.artifactsPrefix)
  await writeLinesFile(path.join(runDir, 'changed_files.jsonl'), args.lines)
}

async writeFile(args: {
  artifactsPrefix: string
  filename: string
  body: string
  contentType?: string
}): Promise<void> {
  void args.contentType
  const filePath = this.resolveRunFilePath(args)
  await mkdir(path.dirname(filePath), { recursive: true })
  await writeFile(filePath, args.body, 'utf8')
}

async readTextFile(args: { artifactsPrefix: string; filename: string }): Promise<string> {
  const filePath = this.resolveRunFilePath(args)
  return readFile(filePath, 'utf8')
}

  async fileExists(args: { artifactsPrefix: string; filename: string }): Promise<boolean> {
    try {
      const filePath = this.resolveRunFilePath(args)
      const details = await stat(filePath)
      return details.isFile()
    } catch (error) {
      if ((error as NodeJS.ErrnoException)?.code === 'ENOENT') {
        return false
      }
      throw error
    }
  }

  async describePrefix(args: {
    artifactsPrefix: string
  }): Promise<{ bytes: number; objects: number }> {
    const runDir = this.resolveRunDir(args.artifactsPrefix)
    return this.inspectRunDir(runDir)
  }

  async deletePrefix(args: {
    artifactsPrefix: string
  }): Promise<{ bytes: number; objects: number }> {
    const runDir = this.resolveRunDir(args.artifactsPrefix)
    const details = await this.inspectRunDir(runDir)
    await rm(runDir, { recursive: true, force: true })
    return details
  }
}

