  }

  const matchingFunctionNodes =
    preferFunctionSymbols && identifierCandidates.size > 0
      ? nodes.filter((node) => {
          if (!isFunctionLikeKind(node.kind)) {
            return false
          }
          return nodeNameMatchesFinding(node.name, identifierCandidates)
        })
      : []

  const source = matchingFunctionNodes.length > 0 ? matchingFunctionNodes : nodes

  return [...source].sort((left, right) => {
    const leftInRange = includesLine(left, line) ? 1 : 0
    const rightInRange = includesLine(right, line) ? 1 : 0
    if (leftInRange !== rightInRange) {
      return rightInRange - leftInRange
    }

    const leftName = left.name ? normalizeIdentifier(left.name) : ""
    const rightName = right.name ? normalizeIdentifier(right.name) : ""
    const leftNameMatch = leftName.length > 0 && identifierCandidates.has(leftName) ? 1 : 0
    const rightNameMatch = rightName.length > 0 && identifierCandidates.has(rightName) ? 1 : 0
    if (leftNameMatch !== rightNameMatch) {
      return rightNameMatch - leftNameMatch
    }

    const leftDistance = distanceFromLine(left, line)
    const rightDistance = distanceFromLine(right, line)
    if (leftDistance !== rightDistance) {
      return leftDistance - rightDistance
    }

    const leftFunction = isFunctionLikeKind(left.kind) ? 1 : 0
    const rightFunction = isFunctionLikeKind(right.kind) ? 1 : 0
    if (leftFunction !== rightFunction) {
      return rightFunction - leftFunction
    }

    const spanDelta = nodeSpanRows(left) - nodeSpanRows(right)
    if (spanDelta !== 0) {
      return spanDelta
    }

    const rankDelta = nodeKindRank(left.kind) - nodeKindRank(right.kind)
    if (rankDelta !== 0) {
      return rankDelta
    }

    return (left.name ?? "").localeCompare(right.name ?? "")
  })[0] ?? null
}

export const collectReachableNodeIds = ({

  const queue: Array<{ id: string; depth: number }> = [{ id: startNodeId, depth: 0 }]
  const visited = new Set<string>([startNodeId])
  const reached = new Set<string>()

  while (queue.length > 0 && reached.size < maxNodes) {
    const current = queue.shift()
    if (!current) {
      break
    }
    if (current.depth >= depth) {
      continue
    }

    if (direction !== "incoming") {
      const outgoing = store.outgoing.get(current.id) ?? []
      for (const edge of outgoing) {
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        const nextId = edge.targetId
        if (nextId !== startNodeId) {
          reached.add(nextId)
        }
        if (!visited.has(nextId) && visited.size < maxNodes) {
          visited.add(nextId)
          queue.push({ id: nextId, depth: current.depth + 1 })
        }
      }
    }

    if (direction !== "outgoing") {
      const incoming = store.incoming.get(current.id) ?? []
      for (const edge of incoming) {
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        const nextId = edge.sourceId
        if (nextId !== startNodeId) {
          reached.add(nextId)
        }
        if (!visited.has(nextId) && visited.size < maxNodes) {
          visited.add(nextId)
          queue.push({ id: nextId, depth: current.depth + 1 })
        }
      }
    }
  }

  return reached
}

const pickBestSymbolNode = (nodes: GraphNode[], normalizedSymbol: string) => {
  if (nodes.length === 0) {
    return null
  }

  return [...nodes].sort((left, right) => {
    const leftName = (left.name ?? "").trim()
    const rightName = (right.name ?? "").trim()
    const leftLower = leftName.toLowerCase()
    const rightLower = rightName.toLowerCase()

    const leftExact = leftLower === normalizedSymbol ? 0 : 1
    const rightExact = rightLower === normalizedSymbol ? 0 : 1
    if (leftExact !== rightExact) {
      return leftExact - rightExact
    }

    const leftSuffix = leftLower.endsWith(`.${normalizedSymbol}`) ? 0 : 1
    const rightSuffix = rightLower.endsWith(`.${normalizedSymbol}`) ? 0 : 1
    if (leftSuffix !== rightSuffix) {
      return leftSuffix - rightSuffix
    }

    const leftContains = leftLower.includes(normalizedSymbol) ? 0 : 1
    const rightContains = rightLower.includes(normalizedSymbol) ? 0 : 1
    if (leftContains !== rightContains) {
      return leftContains - rightContains
    }

    const rankDelta = nodeKindRank(left.kind) - nodeKindRank(right.kind)
    if (rankDelta !== 0) {
      return rankDelta
    }

    const spanDelta = nodeSpanRows(left) - nodeSpanRows(right)
    if (spanDelta !== 0) {
      return spanDelta
    }

    return leftName.localeCompare(rightName)
  })[0] ?? null
}

export const resolveTraceStartNodeId = ({
  store,
  nodeId,
  symbol,
}: {
  store: GraphStore
  nodeId?: string
  symbol?: string
}): string | null => {
  const normalizedNodeId = nodeId?.trim()
  if (normalizedNodeId) {
    return normalizedNodeId
  }

  const normalizedSymbol = symbol?.trim().toLowerCase()
  if (!normalizedSymbol) {
    return null
  }

  const candidates: GraphNode[] = []
  for (const node of store.nodesById.values()) {
    if (node.kind === "file" || !node.name) {
      continue
    }
    const normalizedName = node.name.trim().toLowerCase()
    if (!normalizedName) {
      continue
    }
    if (
      normalizedName === normalizedSymbol ||
      normalizedName.endsWith(`.${normalizedSymbol}`) ||
      normalizedName.includes(normalizedSymbol)
    ) {
      candidates.push(node)
    }
  }

  return pickBestSymbolNode(candidates, normalizedSymbol)?.id ?? null
}

const parseRangeFromJson = (value: unknown): GraphNode["range"] => {
  if (typeof value !== "string" || value.trim().length === 0) {
    return null
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(value)
  } catch {
    return null
  }

  if (!isGraphRange(parsed)) {
    return null
  }

  return {
    start: {
      row: Math.floor(parsed.start.row),
      column: Math.floor(parsed.start.column),
    },
    end: {
      row: Math.floor(parsed.end.row),
      column: Math.floor(parsed.end.column),
    },
  }
}

const parseKiteTraceNode = (
  value: unknown,
  depthFallback: number,
): GraphTraceNodeLike | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  const record = value as Record<string, unknown>
  const id = toOptionalString(record.id)
  if (!id) {
    return null
  }

  const depth = toPositiveInt(record.depth) ?? depthFallback
  return {
    id,
    kind: toOptionalString(record.kind) ?? "external",
    name: toOptionalString(record.name) ?? id,
    filePath: toOptionalString(record.filePath) ?? "",
    depth: Math.max(1, depth),
    range: parseRangeFromJson(record.rangeJson),
  }
}

export const parseKiteTraceResult = (
  value: unknown,
  mode: "callers" | "impact",
): GraphTraceNodeLike[] | null => {
  if (!Array.isArray(value)) {
    return null
  }

  const nodes: GraphTraceNodeLike[] = []
  for (const item of value) {
    if (mode === "impact") {
      if (!item || typeof item !== "object" || Array.isArray(item)) {
        continue
      }
      const record = item as Record<string, unknown>
      const depth = toPositiveInt(record.depth) ?? 1
      const node = parseKiteTraceNode(record.node, depth)
      if (node) {
        nodes.push(node)
      }
      continue
    }

    const node = parseKiteTraceNode(item, 1)
    if (node) {
      nodes.push(node)
    }
  }

  return nodes
}

export const buildDepthMapFromEdges = ({
  startNodeId,
  edges,
  maxDepth,
}: {
  startNodeId: string
  edges: Array<{ sourceId: string; targetId: string }>
  maxDepth: number
}) => {
  const adjacency = new Map<string, Set<string>>()
  const addAdjacency = (from: string, to: string) => {
    const current = adjacency.get(from) ?? new Set<string>()
    current.add(to)
    adjacency.set(from, current)
  }

  for (const edge of edges) {
    addAdjacency(edge.sourceId, edge.targetId)
    addAdjacency(edge.targetId, edge.sourceId)
  }

  const queue: Array<{ id: string; depth: number }> = [{ id: startNodeId, depth: 0 }]
  const visited = new Set<string>([startNodeId])
  const depths = new Map<string, number>()

  while (queue.length > 0) {
    const current = queue.shift()
    if (!current) {
      break
    }
    if (current.depth >= maxDepth) {
      continue
    }

    for (const nextId of adjacency.get(current.id) ?? []) {
      if (!depths.has(nextId)) {
        depths.set(nextId, current.depth + 1)
      }
      if (!visited.has(nextId)) {
        visited.add(nextId)
        queue.push({ id: nextId, depth: current.depth + 1 })
      }
    }
  }

  depths.delete(startNodeId)
  return depths
}

export const collectEdgesWithinIncludedNodes = ({
  store,
  includedNodeIds,
  edgeTypes,
  direction,
  maxEdges,
}: {
  store: GraphStore
  includedNodeIds: Set<string>
  edgeTypes: Set<string>
  direction: "incoming" | "outgoing" | "both"
  maxEdges: number
}): GraphTraceEdgeLike[] => {
  const edgesByKey = new Map<string, GraphTraceEdgeLike>()
  const addEdge = (edge: GraphEdge) => {
    if (edgesByKey.size >= maxEdges) {
      return
    }
    if (!edgeTypes.has(edge.type)) {
      return
    }
    if (!includedNodeIds.has(edge.sourceId) || !includedNodeIds.has(edge.targetId)) {
      return
    }
    const key = `${edge.sourceId}->${edge.targetId}:${edge.type}`
    if (edgesByKey.has(key)) {
      return
    }
    edgesByKey.set(key, {
      sourceId: edge.sourceId,
      targetId: edge.targetId,
      type: edge.type,
    })
  }

  for (const nodeId of includedNodeIds) {
    if (direction !== "incoming") {
      for (const edge of store.outgoing.get(nodeId) ?? []) {
        addEdge(edge)
      }
    }

    if (direction !== "outgoing") {
      for (const edge of store.incoming.get(nodeId) ?? []) {
        addEdge(edge)
      }
    }

    if (edgesByKey.size >= maxEdges) {
      break
    }
  }

  return [...edgesByKey.values()]
}

export const collectReachableSubgraph = ({
  store,
  startNodeId,
  direction,
  edgeTypes,
  depth,
  maxNodes,
  maxEdges,
}: {
  store: GraphStore
  startNodeId: string
  direction: "incoming" | "outgoing" | "both"
  edgeTypes: Set<string>
  depth: number
  maxNodes: number
  maxEdges: number
}) => {

const queue: Array<{ id: string; depth: number }> = [{ id: startNodeId, depth: 0 }]
const visited = new Set<string>([startNodeId])
const reached = new Map<string, number>()
const edgesByKey = new Map<string, GraphTraceEdgeLike>()

  while (
    queue.length > 0 &&
    visited.size < maxNodes &&
    edgesByKey.size < maxEdges
  ) {
    const current = queue.shift()
    if (!current) {
      break
    }
    if (current.depth >= depth) {
      continue
    }

    const trackEdge = (edge: GraphEdge) => {
      if (!edgeTypes.has(edge.type)) {
        return
      }
      const edgeKey = `${edge.sourceId}->${edge.targetId}:${edge.type}`
      if (edgesByKey.has(edgeKey)) {
        return
      }
      edgesByKey.set(edgeKey, {
        sourceId: edge.sourceId,
        targetId: edge.targetId,
        type: edge.type,
      })
    }

    const enqueueNext = (nextId: string) => {
      if (nextId !== startNodeId && !reached.has(nextId)) {
        reached.set(nextId, current.depth + 1)
      }
      if (!visited.has(nextId) && visited.size < maxNodes) {
        visited.add(nextId)
        queue.push({ id: nextId, depth: current.depth + 1 })
      }
    }

    if (direction !== "incoming") {
      const outgoing = store.outgoing.get(current.id) ?? []
      for (const edge of outgoing) {
        trackEdge(edge)
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        enqueueNext(edge.targetId)
      }
    }

    if (direction !== "outgoing") {
      const incoming = store.incoming.get(current.id) ?? []
      for (const edge of incoming) {
        trackEdge(edge)
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        enqueueNext(edge.sourceId)
      }
    }
  }

  return {
    depths: reached,
    edges: [...edgesByKey.values()],
  }
}

]

