import { z } from "zod"

export type AiClientSettings = {
  apiUrl: string
  model: string
  token: string
}

export const AI_CLIENT_SETTINGS_STORAGE_KEY = "argus-ai-settings"
const DEFAULT_AI_API_URL = "https://api.ai.us.lmco.com/v1"
const DEFAULT_AI_MODEL = "gpt-oss-120b"
const MAX_API_URL_LENGTH = 2_048
const MAX_MODEL_LENGTH = 200
const MAX_TOKEN_LENGTH = 8_192

export class AiClientSettingsValidationError extends Error {
  constructor(message: string) {
    super(message)
    this.name = "AiClientSettingsValidationError"
  }
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const toValidatedApiUrl = (value: string) => {
  let parsed: URL
  try {
    parsed = new URL(value)
  } catch {
    throw new AiClientSettingsValidationError("API URL must be a valid absolute URL.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new AiClientSettingsValidationError("API URL must use http or https.")
  }
  if (parsed.username || parsed.password) {
    throw new AiClientSettingsValidationError("API URL must not include credentials.")
  }

  parsed.search = ""
  parsed.hash = ""
  const normalizedPath = parsed.pathname.replace(/\/+$/, "")
  const normalized = normalizedPath ? `${parsed.origin}${normalizedPath}` : parsed.origin
  return normalizeApiUrl(normalized)
}

const getPreferredEnvValue = (...candidates: Array<string | undefined>) => {
  for (const candidate of candidates) {
    if (isNonEmptyString(candidate)) {
      return candidate.trim()
    }
  }
  return ""
}

const aiClientSettingsShapeSchema = z.object({
  apiUrl: z.string().trim().min(1, "API URL is required.").max(MAX_API_URL_LENGTH),
  model: z.string().trim().min(1, "Model is required.").max(MAX_MODEL_LENGTH),
  token: z.string().optional().default("").transform((value) => value.trim()).pipe(
    z.string().max(MAX_TOKEN_LENGTH, `Token is too long (max ${MAX_TOKEN_LENGTH} characters).`),
  ),
}).strict()

export const getAiClientSettingsDefaults = (): AiClientSettings =>
  assertAiClientSettings({
    apiUrl:
      getPreferredEnvValue(
        process.env.NEXT_PUBLIC_AI_API_URL,
        process.env.NEXT_PUBLIC_OPENAI_BASE_URL,
      ) || DEFAULT_AI_API_URL,
    model: getPreferredEnvValue(
      process.env.NEXT_PUBLIC_AI_MODEL,
      process.env.NEXT_PUBLIC_OPENAI_MODEL,
    ) || DEFAULT_AI_MODEL,
    token: getPreferredEnvValue(
      process.env.NEXT_PUBLIC_AI_API_TOKEN,
      process.env.NEXT_PUBLIC_OPENAI_API_KEY,
    ),
  })

export const assertAiClientSettings = (value: unknown): AiClientSettings => {
  const parsed = aiClientSettingsShapeSchema.safeParse(value)
  if (!parsed.success) {
    throw new AiClientSettingsValidationError(parsed.error.issues[0]?.message ?? "Invalid AI settings payload.")
  }

  return {
    apiUrl: toValidatedApiUrl(parsed.data.apiUrl),
    model: parsed.data.model.trim(),
    token: parsed.data.token,
  }
}

export const readAiClientSettingsFromStorage = (): AiClientSettings | null => {
  if (typeof window === "undefined") {
    return null
  }

  const raw = window.localStorage.getItem(AI_CLIENT_SETTINGS_STORAGE_KEY)
  if (!raw) {
    return null
  }

  try {
    const parsed = JSON.parse(raw) as unknown
    return assertAiClientSettings(parsed)
  } catch {
    // Invalid cached settings should not keep poisoning future reads.
    window.localStorage.removeItem(AI_CLIENT_SETTINGS_STORAGE_KEY)
    return null
  }
}

