export const getReviewFlowRunByTraceId = async (args: {
  userId: string
  traceId: string
}) => {
  const traceId = asOptionalString(args.traceId)
  if (!traceId) {
    return null
  }

  const row = await db.query.aiReviewFlowRuns.findFirst({
    where: and(
      eq(aiReviewFlowRuns.userId, args.userId),
      eq(aiReviewFlowRuns.traceId, traceId),
    ),
  })
  if (!row) {
    return null
  }

  return toRunSummary(row as ClaimableRun)
}

export const cancelReviewFlowRunByTraceId = async (args: {
  userId: string
  traceId: string
  message?: string | null
}) => {
  const traceId = asOptionalString(args.traceId)
  if (!traceId) {
    return {
      cancelled: false,
      flowRunId: null,
    }
  }

  const now = new Date()
  const message = asOptionalString(args.message) ?? "AI review cancelled by user."
  const terminalStages: ReviewFlowStage[] = ["queued", "chunking", "analyzing", "mapping", "saving"]

  const rows = await db
    .update(aiReviewFlowRuns)
    .set({
      status: "failed",
      stage: "failed",
      latestError: message,
      finishedAt: now,
      nextAttemptAt: now,
      lastEventAt: now,
      leaseExpiresAt: null,
      claimedBy: null,
      claimVersion: sql`${aiReviewFlowRuns.claimVersion} + 1`,
      updatedAt: now,
    })
    .where(
      and(
        eq(aiReviewFlowRuns.userId, args.userId),
        eq(aiReviewFlowRuns.traceId, traceId),
        eq(aiReviewFlowRuns.status, "in_progress"),
        inArray(aiReviewFlowRuns.stage, terminalStages),
      ),
    )
    .returning({
      id: aiReviewFlowRuns.id,
      traceId: aiReviewFlowRuns.traceId,
    })

  const row = rows[0]
  if (!row) {
    return {
      cancelled: false,
      flowRunId: null,
    }
  }

  await appendReviewFlowEvent({
    flowRunId: row.id,
    traceId: row.traceId,
    stage: "failed",
    eventType: "failed",
    message,
    payload: {
      cancelled: true,
      reason: "user_requested",
    },
  })

  return {
    cancelled: true,
    flowRunId: row.id,
  }
}

export const listReviewFlowEventsByTraceId = async (args: {
  traceId: string
  afterId?: number
  limit?: number
  descending?: boolean
}) => {
  const traceId = asOptionalString(args.traceId)
  if (!traceId) {
    return [] as ReviewFlowEventRecord[]
  }

  const limit = Math.max(1, Math.min(args.limit ?? 200, 1_000))

  const rows = await db
    .select({
      id: aiReviewFlowEvents.id,
      traceId: aiReviewFlowEvents.traceId,
      flowRunId: aiReviewFlowEvents.flowRunId,
      stage: aiReviewFlowEvents.stage,
      eventType: aiReviewFlowEvents.eventType,
      message: aiReviewFlowEvents.message,
      payload: aiReviewFlowEvents.payload,
      createdAt: aiReviewFlowEvents.createdAt,
    })
    .from(aiReviewFlowEvents)
    .where(
      and(
        eq(aiReviewFlowEvents.traceId, traceId),
        ...(typeof args.afterId === "number" && Number.isFinite(args.afterId)
          ? [gt(aiReviewFlowEvents.id, Math.max(0, Math.floor(args.afterId)))]
          : []),
      ),
    )
    .orderBy(args.descending ? desc(aiReviewFlowEvents.id) : asc(aiReviewFlowEvents.id))
    .limit(limit)

  const normalized = rows.map((row) =>
    toEventRecord({
      ...row,
      stage: row.stage as ReviewFlowStage,
      createdAt: row.createdAt,
      message: row.message,
      payload: row.payload,
    }),
  )

  return args.descending ? normalized.reverse() : normalized
}

export const appendReviewFlowEvent = async (args: {

  flowRunId: string
  traceId: string
  stage: ReviewFlowStage
  eventType: string
  message?: string | null
  payload?: Record<string, unknown>
  expectedClaimVersion?: number
}) => {
  const flowRunId = asOptionalString(args.flowRunId)
  const traceId = asOptionalString(args.traceId)
  if (!flowRunId || !traceId) {
    throw new Error("flowRunId and traceId are required.")
  }

  const now = new Date()
  const inserted = await db
    .insert(aiReviewFlowEvents)
    .values({
      flowRunId,
      traceId,
      stage: args.stage,
      eventType: args.eventType.trim() || "progress",
      message: asOptionalString(args.message ?? null),
      payload: args.payload ?? {},
      createdAt: now,
    })
    .returning({
      id: aiReviewFlowEvents.id,
      traceId: aiReviewFlowEvents.traceId,
      flowRunId: aiReviewFlowEvents.flowRunId,
      stage: aiReviewFlowEvents.stage,
      eventType: aiReviewFlowEvents.eventType,
      message: aiReviewFlowEvents.message,
      payload: aiReviewFlowEvents.payload,
      createdAt: aiReviewFlowEvents.createdAt,
    })

  const leaseSettings = resolveReviewLeaseSettings()
  const touchFilters = [eq(aiReviewFlowRuns.id, flowRunId)]
  if (leaseSettings.enabled && typeof args.expectedClaimVersion === "number") {
    touchFilters.push(
      eq(
        aiReviewFlowRuns.claimVersion,
        normalizeClaimVersion(args.expectedClaimVersion),
      ),
    )
  }

const touchedRows = await db
  .update(aiReviewFlowRuns)
  .set({
    lastEventAt: now,
    leaseExpiresAt: leaseSettings.enabled
      ? buildLeaseExpiry(leaseSettings.leaseMs)
      : undefined,
    updatedAt: now,
  })
  .where(and(...touchFilters))
  .returning({ id: aiReviewFlowRuns.id })

const row = inserted[0]
if (!row) {
  throw new Error("Unable to persist review flow event.")
}

void notifyReviewFlowEvent({
  traceId: row.traceId,
  flowRunId: row.flowRunId,
  eventId: row.id,
  eventType: row.eventType,
})

return {
  ...toEventRecord({
    ...row,
    stage: row.stage as ReviewFlowStage,
    createdAt: row.createdAt,
    message: row.message,
    payload: row.payload,
  }),
  runTouched: touchedRows.length > 0,
}

}

export const markReviewRunProgress = async (args: {
  runId: string
  fields: MutableProgressFields
  expectedClaimVersion?: number
}) => {
  const runId = asOptionalString(args.runId)
  if (!runId) {
    return false
  }

  const now = new Date()
  const updates = toProgressUpdate(args.fields)
  const leaseSettings = resolveReviewLeaseSettings()
  const whereFilters = [eq(aiReviewFlowRuns.id, runId)]
  if (leaseSettings.enabled && typeof args.expectedClaimVersion === "number") {
    whereFilters.push(
      eq(
        aiReviewFlowRuns.claimVersion,
        normalizeClaimVersion(args.expectedClaimVersion),
      ),
    )
  }
  const rows = await db
    .update(aiReviewFlowRuns)
    .set({
      ...updates,
      lastEventAt: now,
      leaseExpiresAt: leaseSettings.enabled
        ? buildLeaseExpiry(leaseSettings.leaseMs)
        : undefined,
      updatedAt: now,
    })
    .where(and(...whereFilters))
    .returning({ id: aiReviewFlowRuns.id })
  return rows.length > 0
}

export const markReviewRunSuccess = async (args: {
  runId: string
  reviewId: string
  fields?: MutableProgressFields
  expectedClaimVersion?: number
}) => {
  const runId = asOptionalString(args.runId)
  const reviewId = asOptionalString(args.reviewId)
  if (!runId || !reviewId) {
    return false
  }

  const now = new Date()
  const updates = toProgressUpdate(args.fields ?? {})
  const leaseSettings = resolveReviewLeaseSettings()
  const whereFilters = [eq(aiReviewFlowRuns.id, runId)]
  if (leaseSettings.enabled && typeof args.expectedClaimVersion === "number") {
    whereFilters.push(
      eq(
        aiReviewFlowRuns.claimVersion,
        normalizeClaimVersion(args.expectedClaimVersion),
      ),
    )
  }
  const rows = await db
    .update(aiReviewFlowRuns)
    .set({
      ...updates,
