      status: "success",
      stage: "done",
      latestError: null,
      finishedAt: now,
      lastEventAt: now,
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: now,
    })
    .where(and(...whereFilters))
    .returning({ id: aiReviewFlowRuns.id })
  return rows.length > 0
}

export const markReviewRunFailed = async (args: {
  runId: string
  attempt: number
  maxAttempts: number
  message: string
  retryable: boolean
  fields?: MutableProgressFields
  expectedClaimVersion?: number
}) => {
  const runId = asOptionalString(args.runId)
  if (!runId) {
    return {
      committed: false,
      terminal: true,
      nextAttemptAt: null,
    }
  }

  const now = new Date()
  const updates = toProgressUpdate(args.fields ?? {})

const message = (args.message || "AI review failed.").trim()
const safeAttempt = Math.max(1, Math.floor(args.attempt))
const safeMaxAttempts = Math.max(1, Math.floor(args.maxAttempts))
const leaseSettings = resolveReviewLeaseSettings()
const whereFilters = [eq(aiReviewFlowRuns.id, runId)]
if (leaseSettings.enabled && typeof args.expectedClaimVersion === "number") {
  whereFilters.push(
    eq(
      aiReviewFlowRuns.claimVersion,
      normalizeClaimVersion(args.expectedClaimVersion),
    ),
  )
}

if (args.retryable && safeAttempt < safeMaxAttempts) {
  const nextAttemptAt = new Date(now.getTime() + getRetryDelayMs(safeAttempt))
  const rows = await db
    .update(aiReviewFlowRuns)
    .set({
      ...updates,
      status: "in_progress",
      stage: "queued",
      latestError: message,
      nextAttemptAt,
      lastEventAt: now,
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: now,
    })
    .where(and(...whereFilters))
    .returning({ id: aiReviewFlowRuns.id })

  return {
    committed: rows.length > 0,
    terminal: false,
    nextAttemptAt: rows.length > 0 ? nextAttemptAt : null,
  }
}

const rows = await db
  .update(aiReviewFlowRuns)
  .set({
    ...updates,
    status: "failed",
    stage: "failed",
    latestError: message,
    finishedAt: now,
    nextAttemptAt: now,
    lastEventAt: now,
    leaseExpiresAt: null,
    claimedBy: null,
    updatedAt: now,
  })
  .where(and(...whereFilters))
  .returning({ id: aiReviewFlowRuns.id })

  return {
    committed: rows.length > 0,
    terminal: rows.length > 0,
    nextAttemptAt: null,
  }
}

export const markStaleReviewFlowRunsFailed = async (args: {
  userId: string
  staleAfterMs?: number
}) => {
  const staleAfterMs =
    typeof args.staleAfterMs === "number" && Number.isFinite(args.staleAfterMs)
      ? Math.max(1_000, Math.floor(args.staleAfterMs))
      : REVIEW_FLOW_STALE_AFTER_MS
  const now = new Date()
  const staleBefore = new Date(now.getTime() - staleAfterMs)

  const rows = await db
    .update(aiReviewFlowRuns)
    .set({
      status: "failed",
      stage: "failed",
      latestError: REVIEW_FLOW_STALE_ERROR,
      finishedAt: sql`coalesce(${aiReviewFlowRuns.finishedAt}, ${aiReviewFlowRuns.lastEventAt})`,
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: now,
    })
    .where(
      and(
        eq(aiReviewFlowRuns.userId, args.userId),
        eq(aiReviewFlowRuns.status, "in_progress"),
        lte(aiReviewFlowRuns.lastEventAt, staleBefore),
      ),
    )
    .returning({ id: aiReviewFlowRuns.id })

  return rows.length
}

export const purgeReviewFlowRetentionData = async (args?: {
  retentionDays?: number
}) => {
  const retentionDays =
    typeof args?.retentionDays === "number" && Number.isFinite(args.retentionDays)
      ? Math.max(1, Math.floor(args.retentionDays))
      : REVIEW_FLOW_DEFAULT_RETENTION_DAYS

  const cutoff = new Date(Date.now() - retentionDays * 24 * 60 * 60 * 1_000)

  const deletedEvents = await db.execute(sql`
    delete from ${aiReviewFlowEvents}
    using ${aiReviewFlowRuns}
    where ${aiReviewFlowEvents.flowRunId} = ${aiReviewFlowRuns.id}
      and ${aiReviewFlowRuns.status} in ('success', 'failed')
      and coalesce(${aiReviewFlowRuns.finishedAt}, ${aiReviewFlowRuns.updatedAt}) < ${cutoff}
  `)

  const deletedRunRows = await db
    .delete(aiReviewFlowRuns)
    .where(
      and(
        inArray(aiReviewFlowRuns.status, ["success", "failed"]),
        lte(aiReviewFlowRuns.updatedAt, cutoff),
      ),
    )
    .returning({ id: aiReviewFlowRuns.id })

  return {
    eventsDeleted: deletedEvents.rowCount ?? 0,
    runsDeleted: deletedRunRows.length,
  }
}

export const startReviewFlowRun = async (args: {
  userId: string
  traceId: string | null
} & ReviewFlowScope) => {
  const traceId = asOptionalString(args.traceId)
  if (!traceId) {
