export const touchReviewFlowRunForApiResult = async (args: {
  traceId: string | null
  status: number
}) => {
  const traceId = asOptionalString(args.traceId)
  if (!traceId) {
    return
  }

  const now = new Date()
  if (args.status >= 400) {
    await db
      .update(aiReviewFlowRuns)
      .set({
        status: "failed",
        stage: "failed",
        lastEventAt: now,
        finishedAt: now,
        leaseExpiresAt: null,
        claimedBy: null,
        updatedAt: now,
      })
      .where(eq(aiReviewFlowRuns.traceId, traceId))
    return
  }

  await db
    .update(aiReviewFlowRuns)
    .set({
      lastEventAt: now,
      updatedAt: now,
    })
    .where(eq(aiReviewFlowRuns.traceId, traceId))
}

