      Some(LanguageId::Cpp)
    );
    assert_eq!(
      detect_language_from_path("src/Demo.cs"),
      Some(LanguageId::CSharp)
    );
    assert_eq!(
      detect_language_from_path("src/Demo.java"),
      Some(LanguageId::Java)
    );
    assert_eq!(
      detect_language_from_path("src/lib.rs"),
      Some(LanguageId::Rust)
    );
  }
}

