const createGraphFixture = async (args: {
  indexRunId: string
  nodesJsonl: string
  edgesJsonl: string
}) => {
  const rootDir = await mkdtemp(path.join(os.tmpdir(), "persisted-graph-query-test-"))
  await writeFile(path.join(rootDir, "argus-search.json"), JSON.stringify({ projectRoot: "." }), "utf8")

  const indexPackDir = path.join(rootDir, ".argus-search", "index-pack")
  await mkdir(indexPackDir, { recursive: true })

  await writeFile(
    path.join(indexPackDir, "manifest.json"),
    JSON.stringify({
      schemaVersion: "1.0.0",
      indexRunId: args.indexRunId,
      generatedAt: "2026-02-27T00:00:00.000Z",
      stats: {},
    }),
    "utf8",
  )
  await writeFile(path.join(indexPackDir, "graph.nodes.jsonl"), args.nodesJsonl, "utf8")
  await writeFile(path.join(indexPackDir, "graph.edges.jsonl"), args.edgesJsonl, "utf8")

  return rootDir
}

