const { indexStream } = require('./stream.js')
const { clampTopK } = require('./search-contract.js')

function toFloat32Array(vector) {
  if (vector instanceof Float32Array) return vector
  if (!Array.isArray(vector)) return new Float32Array()
  return Float32Array.from(vector.map((v) => Number(v) || 0))
}

function l2Normalize(vector) {
  let sumSq = 0
  for (let idx = 0; idx < vector.length; idx += 1) sumSq += vector[idx] * vector[idx]
  const norm = Math.sqrt(sumSq) || 1
  for (let idx = 0; idx < vector.length; idx += 1) vector[idx] /= norm
  return vector
}

function dot(a, b) {
  const len = Math.min(a.length, b.length)
  let sum = 0
  for (let idx = 0; idx < len; idx += 1) sum += a[idx] * b[idx]
  return sum
}

function isObject(value) {
  return value !== null && typeof value === 'object'
}

function readFirst(obj, keys) {
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      return obj[key]
    }
  }
  return undefined
}

function toPositiveFiniteNumber(value) {
  const numeric = Number(value)
  if (!Number.isFinite(numeric) || numeric <= 0) return null
  return numeric
}

function requiredNonEmptyString(value, label) {
  const text = String(value ?? '').trim()
  if (!text) {
    throw new Error(`${label} is required`)
  }
  return text
}

function normalizeRetrieverMatch(match, index) {
  if (!isObject(match)) {
    throw new Error(`createVectorRetriever: invalid match at index ${index}: expected object`)
  }
  const score = Number(match.score)
  if (!Number.isFinite(score)) {
    throw new Error(`createVectorRetriever: invalid match at index ${index}: score must be finite`)
  }

  const record = isObject(match.record) ? match.record : match
  const chunkId = requiredNonEmptyString(readFirst(record, ['chunkId', 'chunk_id']), 'chunkId')
  const filePath = requiredNonEmptyString(readFirst(record, ['filePath', 'file_path']), 'filePath')
  const chunk = record.chunk ?? match.chunk ?? null
  const metadata = record.metadata ?? match.metadata ?? null

  return { score, chunkId, filePath, chunk, metadata }
}

class InMemoryVectorStore {

  constructor(options) {
    const { normalize = true } = options ?? {}
    this._normalize = Boolean(normalize)
    this._records = []
    this._recordIndex = new Map()
  }

  clear() {
    this._records = []
    this._recordIndex = new Map()
  }

  size() {
    return this._records.length
  }

  upsertBatch(batch) {
    if (!Array.isArray(batch) || batch.length === 0) return
    for (const record of batch) {
      if (!record) continue
      const chunkId = String(record.chunkId ?? '')
      const filePath = String(record.filePath ?? '')
      if (!chunkId || !filePath) continue

      const embedding = toFloat32Array(record.embedding ?? [])
      if (this._normalize) l2Normalize(embedding)
      const next = {
        chunkId,
        filePath,
        embedding,
        metadata: record.metadata ?? null,
        chunk: record.chunk ?? null,
      }
      const currentIndex = this._recordIndex.get(chunkId)
      if (currentIndex == null) {
        this._recordIndex.set(chunkId, this._records.length)
        this._records.push(next)
      } else {
        this._records[currentIndex] = next
      }
    }
  }

  searchByEmbedding(queryEmbedding, { topK = 5, filter } = {}) {
    const embedding = toFloat32Array(queryEmbedding ?? [])
    if (this._normalize) l2Normalize(embedding)

    const scored = []
    for (const record of this._records) {
      if (filter && !filter(record)) continue
      scored.push({ score: dot(embedding, record.embedding), record })
    }
    scored.sort((a, b) => b.score - a.score)
    return scored.slice(0, clampTopK(topK))
  }
}

function createHttpEmbedder(options) {
  const { baseUrl, model, apiKey, timeoutMs, dimensions, dimension } = options ?? {}
  if (!baseUrl) throw new Error('createHttpEmbedder: baseUrl is required')
  if (!model) throw new Error('createHttpEmbedder: model is required')
  const timeout = timeoutMs == null ? null : toPositiveFiniteNumber(timeoutMs)
  if (timeoutMs != null && timeout == null) {
    throw new Error('createHttpEmbedder: timeoutMs must be a positive finite number')
  }

const embed = async (input) => {
  const controller = typeof AbortController !== 'undefined' ? new AbortController() : null
  const timer = controller && timeout ? setTimeout(() => controller.abort(), timeout) : null

  try {
    const normalizedBaseUrl = String(baseUrl).replace(/\/+$/g, '') + '/'
    const body = { model, input }
    const dims = dimensions ?? dimension
    if (dims != null) body.dimensions = dims

    const res = await fetch(new URL('embeddings', normalizedBaseUrl), {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        ...(apiKey ? { authorization: `Bearer ${apiKey}` } : {}),
      },
      body: JSON.stringify(body),
      signal: controller?.signal,
    })

    if (!res.ok) {
      const detail = await res.text().catch(() => '')
      throw new Error(`embedder: HTTP ${res.status}${detail ? `: ${detail}` : ''}`)
    }

    const payload = await res.json()
    const data = Array.isArray(payload?.data) ? payload.data : []
    return data.map((entry) => (Array.isArray(entry?.embedding) ? entry.embedding : []))
  } finally {
    if (timer) clearTimeout(timer)
  }
}

return {
  kind: 'http',
  embed,
  async embedQuery(text) {
    const out = await embed([String(text ?? '')])
    return out[0] ?? []
  },
}

}

function createVectorRetriever({ store, embedder }) {
  if (!store) throw new Error('createVectorRetriever: store is required')
  if (!embedder) throw new Error('createVectorRetriever: embedder is required')
  if (typeof embedder.embedQuery !== 'function') throw new Error('createVectorRetriever: embedder.embedQuery required')
  if (typeof store.searchByEmbedding !== 'function')
    throw new Error('createVectorRetriever: store.searchByEmbedding required')

  return {
    async search({ query, topK = 5, filter } = {}) {
      const text = String(query ?? '').trim()
      if (!text) throw new Error('query cannot be empty')
      const embedding = await embedder.embedQuery(text)
      const matches = await Promise.resolve(store.searchByEmbedding(embedding, { topK: clampTopK(topK), filter }))
      if (!Array.isArray(matches)) {
        throw new Error('createVectorRetriever: store.searchByEmbedding must return an array')
      }
      return matches.map((match, index) => normalizeRetrieverMatch(match, index))
    },
  }
}

function createCodeSearchTool({ retriever, name = 'code_search' } = {}) {
  if (!retriever) throw new Error('createCodeSearchTool: retriever is required')
  if (typeof retriever.search !== 'function') throw new Error('createCodeSearchTool: retriever.search required')

  return {
    name,
    description: 'Search over indexed code chunks.',
    parameters: {
      type: 'object',
      additionalProperties: false,
      properties: {
        query: { type: 'string', description: 'Natural-language query' },
        topK: { type: 'integer', minimum: 1, maximum: 50, default: 5 },
      },
      required: ['query'],
    },
    async execute({ query, topK = 5 } = {}) {
      return retriever.search({ query: String(query ?? ''), topK: clampTopK(topK) })
    },
  }
}

async function indexToStores(indexOptions, { vectorStore, graphStore, streamOptions } = {}) {
  if (!vectorStore && !graphStore) throw new Error('indexToStores: at least one store is required')
  const useCustomEmbedding = !indexOptions?.phases?.vector && vectorStore && streamOptions?.embedder

  const emit = {
    ...streamOptions?.emit,
    parseBatches: Boolean(useCustomEmbedding),
    vectorBatches: Boolean(vectorStore),
    graphBatches: Boolean(graphStore),
    scipBatches: Boolean(graphStore),
    phaseEvents: true,
  }
  const stream = indexStream(indexOptions, { ...streamOptions, emit })

  let complete = null
  try {
    for await (const item of stream) {
      if (item?.type === 'parse:batch' && useCustomEmbedding) {

  const rawChunks = Array.isArray(item?.chunks) ? item.chunks : []
  const chunks = rawChunks
    .map((chunk) => {
      if (!isObject(chunk)) return null
      const chunkId = requiredNonEmptyString(readFirst(chunk, ['id', 'chunkId', 'chunk_id']), 'chunk.id')
      const filePath = requiredNonEmptyString(readFirst(chunk, ['filePath', 'file_path']), 'chunk.filePath')
      const content = String(readFirst(chunk, ['content']) ?? '').trim()
      if (!content) return null
      return {
        chunkId,
        filePath,
        content,
        metadata: chunk.metadata ?? null,
        chunk: chunk,
      }
    })
    .filter(Boolean)
  if (chunks.length > 0) {
    const embeddings =
      typeof streamOptions.embedder.embed === 'function'
        ? await streamOptions.embedder.embed(chunks.map((chunk) => chunk.content))
        : await Promise.all(chunks.map((chunk) => streamOptions.embedder.embedQuery(chunk.content)))
    if (!Array.isArray(embeddings)) {
      throw new Error('indexToStores: embedder.embed must return an array')
    }
    const batch = chunks.map((chunk, index) => ({
      chunkId: chunk.chunkId,
      filePath: chunk.filePath,
      embedding: Array.isArray(embeddings[index]) ? embeddings[index] : [],
      metadata: chunk.metadata,
      chunk: chunk.chunk,
    }))
    await Promise.resolve(vectorStore.upsertBatch(batch))
  }
  continue
}

      if (item?.type === 'vector:batch') {
        if (vectorStore) await Promise.resolve(vectorStore.upsertBatch(item.batch ?? []))
        continue
      }
      if (item?.type === 'graph:batch') {
        if (graphStore) await Promise.resolve(graphStore.upsertGraphBatch(item.batch))
        continue
      }
      if (item?.type === 'scip:batch') {
        if (graphStore) await Promise.resolve(graphStore.upsertGraphBatch(item.batch))
        continue
      }
      if (item?.type === 'pipeline:complete') {
        complete = item
        break
      }
    }
  } catch (error) {
    if (typeof stream?.cancel === 'function') {
      stream.cancel()
    }
    throw error
  }

  return complete
}

function createArgusSearch(options) {
  const {
    projectRoot,
    inputs,
    vectorProvider,
    store = new InMemoryVectorStore(),
    graphStore = null,
    embedder = vectorProvider ? createHttpEmbedder(vectorProvider) : null,
    streamOptions,
  } = options ?? {}

  if (!projectRoot) throw new Error('createArgusSearch: projectRoot is required')
  if (!embedder) throw new Error('createArgusSearch: embedder or vectorProvider is required')

  const retriever = createVectorRetriever({ store, embedder })
  const tool = createCodeSearchTool({ retriever })

  return {
    store,
    graphStore,
    embedder,
    retriever,
    tool,
    async index({ phases, hooks, vector, ...rest } = {}) {
      const vectorRequested = phases?.vector == null ? true : Boolean(phases.vector)
      const vectorViaProvider = vectorRequested && Boolean(vectorProvider)
      const vectorViaEmbedder = vectorRequested && !vectorProvider
      return indexToStores(
        {
          projectRoot,
          inputs,
          ...rest,
          phases: {
            parse: true,
            graph: Boolean(graphStore),
            vector: vectorViaProvider,
            scip: Boolean(graphStore),
            indexPack: false,
            ...phases,
          },
          vector: { ...(vectorViaProvider ? { provider: vectorProvider } : {}), ...vector },
          hooks,
        },
        {
          vectorStore: store,
          graphStore,
          streamOptions: { ...streamOptions, embedder: vectorViaEmbedder ? embedder : null },
        },
      )
    },
    async search(query, { topK = 5, filter } = {}) {
      return retriever.search({ query, topK, filter })
    },
  }
}

module.exports = {
  InMemoryVectorStore,
  createHttpEmbedder,
  createVectorRetriever,
  createCodeSearchTool,
  indexToStores,
  indexToVectorStore: (indexOptions, options) =>
    indexToStores(indexOptions, { vectorStore: options?.store, streamOptions: options?.streamOptions }),
  createArgusSearch,
}

