import { readFile, stat } from "node:fs/promises"
import path from "node:path"

import {
  DEFAULT_RUN_GRAPH_ARTIFACT_FILES,
  normalizeRunGraphArtifactFiles,
} from "@/lib/indexing/graph-artifacts"
import { resolveArtifactBackend } from "@/lib/indexing/stores/artifact-store"

import type {
  GraphImpactSnapshotReady,
  ImpactGraphBackendKind,
  ReadyRunGraphSnapshotStatus,
} from "./impact-graph-backend-kitedb"

type ReadyGraphRun = {
  id: string
  status:
    | "planned"
    | "ingesting"
    | "indexing"
    | "cancelled"
    | "ready"
    | "failed"
    | "superseded"
  artifactsPrefix: string | null
  stats?: Record<string, unknown> | null
}

type RunGraphArtifactPaths = {
  runDir: string
  indexStorePath: string
  indexStoreManifestPath: string
  nodesPath: string
  edgesPath: string
  indexPackManifestPath: string
}

export type GraphArtifactStoreReader = {
  readTextFile: (args: { artifactsPrefix: string; filename: string }) => Promise<string>
  fileExists: (args: { artifactsPrefix: string; filename: string }) => Promise<boolean>
}

type GraphArtifactsManifest = {
  indexRunId: string
  generatedAt: string
}

const GRAPH_BUILD_READY_STATUSES = new Set(["ready", "succeeded", "active"])
const GRAPH_BUILD_FAILURE_STATUSES = new Set(["failed", "error", "dead"])
const GRAPH_BUILD_SKIPPED_STATUSES = new Set(["skipped", "missing", "not_started"])

export const DEFAULT_GRAPH_ARTIFACTS_ROOT = path.resolve(
  process.env.INDEXER_GRAPH_DIR?.trim() ||
    path.join(process.cwd(), ".indexer-artifacts", "graphs"),
)

const toOptionalString = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

const toOptionalAbsolutePath = (value: unknown) => {
  const normalized = toOptionalString(value)
  if (!normalized || !path.isAbsolute(normalized)) {
    return null
  }
  return path.resolve(normalized)
}

const resolveRunGraphStatsRecord = (value: unknown) => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  const stats = value as Record<string, unknown>
  const graph = stats.graph
  if (!graph || typeof graph !== "object" || Array.isArray(graph)) {
    return null
  }
  return graph as Record<string, unknown>
}

export const resolveRunGraphBuildStatus = (value: unknown) => {
  const graph = resolveRunGraphStatsRecord(value)
  if (!graph) {
    return null
  }
  const graphStatus = toOptionalString(graph.status)
  return graphStatus?.toLowerCase() ?? null
}

export const isGraphBuildFailed = (value: unknown) => {
  const status = resolveRunGraphBuildStatus(value)
  return Boolean(status && GRAPH_BUILD_FAILURE_STATUSES.has(status))
}

export const isGraphBuildSkipped = (value: unknown) => {
  const status = resolveRunGraphBuildStatus(value)
  return Boolean(status && GRAPH_BUILD_SKIPPED_STATUSES.has(status))
}

export const isGraphBuildMissingArtifacts = (value: unknown) => {
  const status = resolveRunGraphBuildStatus(value)
  return Boolean(status && !GRAPH_BUILD_READY_STATUSES.has(status))
}

const resolveRunGraphStatsPaths = (value: unknown) => {
  const graph = resolveRunGraphStatsRecord(value)
  if (!graph) {
    return {
      graphStorePath: null,
      indexPackDir: null,
    }
  }

  return {
    graphStorePath: toOptionalAbsolutePath(graph.graphStorePath),
    indexPackDir: toOptionalAbsolutePath(graph.indexPackDir),
  }
}

const resolveRunGraphIndexRunId = (value: unknown) => {
  const graph = resolveRunGraphStatsRecord(value)
  if (!graph) {
    return null
  }
  return toOptionalString(graph.indexRunId)
}

const resolveRunGraphArtifactStoreFiles = (value: unknown) => {
  const graph = resolveRunGraphStatsRecord(value)
  if (!graph) {
    return {
      ...DEFAULT_RUN_GRAPH_ARTIFACT_FILES,
    }
  }

  const artifactStore = graph.artifactStore
  if (
    !artifactStore ||
    typeof artifactStore !== "object" ||
    Array.isArray(artifactStore)
  ) {
    return {
      ...DEFAULT_RUN_GRAPH_ARTIFACT_FILES,
    }
  }

  const files = (artifactStore as Record<string, unknown>).files
  return normalizeRunGraphArtifactFiles(files)
}

const parseManifest = (raw: string): GraphArtifactsManifest => {
  const parsed = JSON.parse(raw) as Record<string, unknown>
  const indexRunId = toOptionalString(parsed.indexRunId)
  const generatedAt = toOptionalString(parsed.generatedAt)
  if (!indexRunId || !generatedAt) {
    throw new Error("Graph index-pack manifest is missing indexRunId/generatedAt.")
  }

  return {
    indexRunId,
    generatedAt,
  }
}

const ensureWithinRoot = (root: string, targetPath: string) => {
  const resolvedRoot = path.resolve(root)
  const resolvedPath = path.resolve(targetPath)
  const rootWithSeparator = `${resolvedRoot}${path.sep}`
  if (resolvedPath !== resolvedRoot && !resolvedPath.startsWith(rootWithSeparator)) {
    throw new Error("Graph artifact path escapes configured root.")
  }
  return resolvedPath
}

const buildRunGraphPaths = (runDir: string): RunGraphArtifactPaths => ({
  runDir,
  indexStorePath: path.join(runDir, DEFAULT_RUN_GRAPH_ARTIFACT_FILES.indexStore),
  indexStoreManifestPath: path.join(runDir, DEFAULT_RUN_GRAPH_ARTIFACT_FILES.indexStoreManifest),
  nodesPath: path.join(runDir, DEFAULT_RUN_GRAPH_ARTIFACT_FILES.nodes),
  edgesPath: path.join(runDir, DEFAULT_RUN_GRAPH_ARTIFACT_FILES.edges),
  indexPackManifestPath: path.join(runDir, DEFAULT_RUN_GRAPH_ARTIFACT_FILES.indexPackManifest),
})

const resolveRunGraphPaths = (graphRoot: string, artifactsPrefix: string): RunGraphArtifactPaths => {
  const runDir = ensureWithinRoot(graphRoot, path.join(graphRoot, artifactsPrefix))
  return buildRunGraphPaths(runDir)
}

const resolveRunGraphPathCandidates = ({
  graphArtifactsRoot,
  run,
}: {
  graphArtifactsRoot: string
  run: ReadyGraphRun
}): RunGraphArtifactPaths[] => {
  const candidates: RunGraphArtifactPaths[] = []
  const seen = new Set<string>()

  const push = (paths: RunGraphArtifactPaths | null) => {
    if (!paths) {
      return
    }
    if (seen.has(paths.runDir)) {
      return
    }
    seen.add(paths.runDir)
    candidates.push(paths)
  }

  const artifactsPrefix = toOptionalString(run.artifactsPrefix)
  if (artifactsPrefix) {
    try {
      push(resolveRunGraphPaths(graphArtifactsRoot, artifactsPrefix))
    } catch {
      // Ignore invalid prefixed path and rely on run stats fallback candidates.
    }
  }

  const graphStatsPaths = resolveRunGraphStatsPaths(run.stats)
  if (graphStatsPaths.indexPackDir) {
    push(buildRunGraphPaths(graphStatsPaths.indexPackDir))
  }
  if (graphStatsPaths.graphStorePath) {
    push(buildRunGraphPaths(path.dirname(graphStatsPaths.graphStorePath)))
  }

  return candidates
}

const loadReadySnapshotFromPaths = async (args: {
  backend: ImpactGraphBackendKind
  integrationId: string | null
  branch: string | null
  expectedIndexRunId?: string | null
  paths: RunGraphArtifactPaths
  statPath: (filePath: string) => Promise<unknown>
  readTextFile: (filePath: string) => Promise<string>
}): Promise<GraphImpactSnapshotReady | null> => {
  const requiredPaths = [
    args.paths.indexStorePath,
    args.paths.indexStoreManifestPath,
    args.paths.indexPackManifestPath,
    args.paths.nodesPath,
    args.paths.edgesPath,
  ]

  try {
    await Promise.all(requiredPaths.map((filePath) => args.statPath(filePath)))
    const manifestRaw = await args.readTextFile(args.paths.indexPackManifestPath)
    const manifest = parseManifest(manifestRaw)
    if (
      args.expectedIndexRunId &&
      manifest.indexRunId !== args.expectedIndexRunId
    ) {
      return null
    }
    return {
      status: "ready",
      backend: args.backend,
      integrationId: args.integrationId,
      branch: args.branch,
      indexRunId: manifest.indexRunId,
      generatedAt: manifest.generatedAt,
      graphStorePath: args.paths.indexStorePath,
      nodesPath: args.paths.nodesPath,
      edgesPath: args.paths.edgesPath,
      artifactStorePrefix: null,
      artifactStoreNodesFilename: null,
      artifactStoreEdgesFilename: null,
    }
  } catch {
    return null
  }
}

const loadReadySnapshotFromArtifactStore = async (args: {

  backend: ImpactGraphBackendKind
  integrationId: string | null
  branch: string | null
  run: ReadyGraphRun
  expectedIndexRunId?: string | null
  artifactStore: GraphArtifactStoreReader
}): Promise<GraphImpactSnapshotReady | null> => {
  const artifactsPrefix = toOptionalString(args.run.artifactsPrefix)
  if (!artifactsPrefix) {
    return null
  }

  const files = resolveRunGraphArtifactStoreFiles(args.run.stats)
  const requiredFiles = [
    files.indexPackManifest,
    files.nodes,
    files.edges,
  ]

  try {
    const exists = await Promise.all(
      requiredFiles.map((filename) =>
        args.artifactStore.fileExists({
          artifactsPrefix,
          filename,
        }),
      ),
    )
    if (exists.some((value) => !value)) {
      return null
    }

    const manifestRaw = await args.artifactStore.readTextFile({
      artifactsPrefix,
      filename: files.indexPackManifest,
    })
    const manifest = parseManifest(manifestRaw)
    if (
      args.expectedIndexRunId &&
      manifest.indexRunId !== args.expectedIndexRunId
    ) {
      return null
    }

    return {
      status: "ready",
      backend: args.backend,
      integrationId: args.integrationId,
      branch: args.branch,
      indexRunId: manifest.indexRunId,
      generatedAt: manifest.generatedAt,
      graphStorePath: null,
      nodesPath: null,
      edgesPath: null,
      artifactStorePrefix: artifactsPrefix,
      artifactStoreNodesFilename: files.nodes,
      artifactStoreEdgesFilename: files.edges,
    }
  } catch {
    return null
  }
}

export const resolveReadySnapshotFromRunArtifacts = async (args: {
  backend: ImpactGraphBackendKind
  integrationId: string | null
  branch: string | null
  run: ReadyGraphRun
  graphArtifactsRoot: string
  readTextFile: (filePath: string) => Promise<string>
  statPath: (filePath: string) => Promise<unknown>
  artifactStore: GraphArtifactStoreReader | null
}): Promise<GraphImpactSnapshotReady | null> => {
  if (args.run.status !== "ready") {
    return null
  }

  const expectedIndexRunId = resolveRunGraphIndexRunId(args.run.stats)

  if (args.artifactStore) {
    const snapshot = await loadReadySnapshotFromArtifactStore({
      backend: args.backend,
      integrationId: args.integrationId,
      branch: args.branch,
      run: args.run,
      expectedIndexRunId,
      artifactStore: args.artifactStore,
    })
    if (snapshot) {
      return snapshot
    }
  }

  if (resolveArtifactBackend() !== "fs") {
    return null
  }

  const candidates = resolveRunGraphPathCandidates({
    graphArtifactsRoot: args.graphArtifactsRoot,
    run: args.run,
  })
  for (const paths of candidates) {
    const snapshot = await loadReadySnapshotFromPaths({
      backend: args.backend,
      integrationId: args.integrationId,
      branch: args.branch,
      expectedIndexRunId,
      paths,
      readTextFile: args.readTextFile,
      statPath: args.statPath,
    })
    if (snapshot) {
      return snapshot
    }
  }

  return null
}

export const resolveReadyRunGraphSnapshotStatusWithDeps = async (args: {
  run: ReadyGraphRun
  graphArtifactsRoot: string
  readTextFile: (filePath: string) => Promise<string>
  statPath: (filePath: string) => Promise<unknown>
  artifactStore: GraphArtifactStoreReader | null
}): Promise<ReadyRunGraphSnapshotStatus> => {
  if (isGraphBuildFailed(args.run.stats)) {
    return "graph_build_failed"
  }
  if (isGraphBuildSkipped(args.run.stats)) {
    return "graph_build_skipped"
  }
  if (isGraphBuildMissingArtifacts(args.run.stats)) {
    return "missing_artifacts"
  }

  const snapshot = await resolveReadySnapshotFromRunArtifacts({
    backend: "kitedb_fs",
    integrationId: null,
    branch: null,
    run: args.run,
    graphArtifactsRoot: path.resolve(args.graphArtifactsRoot),
    readTextFile: args.readTextFile,
    statPath: args.statPath,
    artifactStore: args.artifactStore,
  })
  return snapshot ? "ready" : "missing_artifacts"
}

export const resolveReadyRunGraphSnapshotStatus = async (args: {
  run: ReadyGraphRun
  graphArtifactsRoot?: string
  readTextFile?: (filePath: string) => Promise<string>
  statPath?: (filePath: string) => Promise<unknown>
  artifactStore?: GraphArtifactStoreReader | null
}): Promise<ReadyRunGraphSnapshotStatus> => {
  return resolveReadyRunGraphSnapshotStatusWithDeps({
    run: args.run,
    graphArtifactsRoot: args.graphArtifactsRoot ?? DEFAULT_GRAPH_ARTIFACTS_ROOT,
    readTextFile: args.readTextFile ?? ((filePath) => readFile(filePath, "utf8")),
    statPath: args.statPath ?? ((filePath) => stat(filePath)),
    artifactStore: args.artifactStore ?? null,
  })
}

use std::path::{Component, Path, PathBuf};

fn absolute_from_cwd(path: &Path) -> PathBuf {
  if path.is_absolute() {
    return path.to_path_buf();
  }
  std::env::current_dir()
    .map(|cwd| cwd.join(path))
    .unwrap_or_else(|_| path.to_path_buf())
}

fn normalize_root_candidates(root_dir: &Path) -> (PathBuf, PathBuf) {
  let absolute = absolute_from_cwd(root_dir);
  let canonical = absolute.canonicalize().unwrap_or_else(|_| absolute.clone());
  (absolute, canonical)
}

fn path_within_root(path: &Path, root_absolute: &Path, root_canonical: &Path) -> bool {
  path.strip_prefix(root_absolute).is_ok() || path.strip_prefix(root_canonical).is_ok()
}

pub fn resolve_path_within_root(
  root_dir: &Path,
  candidate: &Path,
  label: &str,
) -> Result<PathBuf, String> {
  let (root_absolute, root_canonical) = normalize_root_candidates(root_dir);
  let joined = if candidate.is_absolute() {
    candidate.to_path_buf()
  } else {
    root_absolute.join(candidate)
  };
  let resolved = joined.canonicalize().unwrap_or(joined.clone());

  if !path_within_root(&resolved, &root_absolute, &root_canonical) {
    return Err(format!("{label} escapes project root"));
  }

  Ok(resolved)
}

pub fn resolve_store_path_within_root(
  project_root: &Path,
  candidate: PathBuf,
  label: &str,
) -> Result<PathBuf, String> {
  if candidate
    .components()
    .any(|component| matches!(component, Component::ParentDir))
  {
    return Err(format!("{label} escapes project root"));
  }

  let resolved = if candidate.is_absolute() {
    candidate
  } else {
    absolute_from_cwd(project_root).join(candidate)
  };

  resolve_path_within_root(project_root, &resolved, label).map(|_| resolved)
}

pub fn parse_safe_relative_path(file_path: &str) -> Result<PathBuf, String> {
  let rel = PathBuf::from(file_path.replace('\\', "/"));
  if rel.is_absolute() {
    return Err("path escapes project root".to_string());
  }
  if rel
    .components()
    .any(|component| matches!(component, Component::ParentDir))
  {
    return Err("path escapes project root".to_string());
  }
  Ok(rel)
}

pub fn normalize_relative_path_within_root(
  project_root: &Path,
  file_path: &str,
) -> Result<String, String> {
  let normalized = file_path.replace('\\', "/");
  let candidate = Path::new(&normalized);
  if candidate.is_absolute() {
    let absolute = resolve_path_within_root(project_root, candidate, "path")?;
    let (root_absolute, root_canonical) = normalize_root_candidates(project_root);
    let relative = absolute
      .strip_prefix(&root_absolute)
      .or_else(|_| absolute.strip_prefix(&root_canonical))
      .map(|value| value.to_path_buf())
      .unwrap_or(absolute);
    return Ok(relative.to_string_lossy().replace('\\', "/"));
  }

  parse_safe_relative_path(&normalized).map(|path| path.to_string_lossy().replace('\\', "/"))
}

#[cfg(test)]

mod tests {
  use super::*;

  #[test]
  fn resolves_store_path_inside_root_when_target_does_not_exist() {
    let temp = tempfile::tempdir().expect("tempdir");
    let root = temp.path();

    let resolved = resolve_store_path_within_root(
      root,
      PathBuf::from(".argus-search/index.kite"),
      "store.path",
    )
    .expect("store path should resolve");

    assert_eq!(resolved, root.join(".argus-search/index.kite"));
  }

  #[test]
  fn rejects_store_parent_traversal() {
    let temp = tempfile::tempdir().expect("tempdir");
    let root = temp.path();

    let error = resolve_store_path_within_root(root, PathBuf::from("../index.kite"), "store.path")
      .expect_err("expected traversal rejection");

    assert!(error.contains("escapes project root"));
  }

  #[test]
  fn rejects_absolute_path_outside_root() {
    let temp = tempfile::tempdir().expect("tempdir");
    let root = temp.path();

    let error = resolve_path_within_root(root, Path::new("/etc/passwd"), "path")
      .expect_err("expected out-of-root rejection");

    assert!(error.contains("escapes project root"));
  }

  #[test]
  fn normalizes_relative_path_and_rejects_parent_components() {
    let temp = tempfile::tempdir().expect("tempdir");
    let root = temp.path();

    let ok = normalize_relative_path_within_root(root, "src/main.ts").expect("valid relative path");
    assert_eq!(ok, "src/main.ts");

    let err = normalize_relative_path_within_root(root, "../secrets.txt")
      .expect_err("expected traversal rejection");
    assert!(err.contains("escapes project root"));
  }
}

