import { parseBoolean, parsePositiveInt } from "./config-env"

export type WorkerLeaseSettings = {
  enabled: boolean
  leaseMs: number
  staleReclaimIntervalMs: number
  gracefulShutdownMs: number
}

type WorkerLeaseSettingsArgs = {
  env?: Record<string, string | undefined>
  leaseMsEnv: string
  staleReclaimIntervalMsEnv: string
  gracefulShutdownMsEnv: string
  defaults: {
    leaseMs: number
    staleReclaimIntervalMs: number
    gracefulShutdownMs: number
  }
}

const resolveDefaultEnv = (): Record<string, string | undefined> => {
  const processEnv = (
    globalThis as { process?: { env?: Record<string, string | undefined> } }
  ).process?.env
  return processEnv ?? {}
}

export const resolveWorkerLeasesEnabled = (
  env: Record<string, string | undefined> = resolveDefaultEnv(),
): boolean => parseBoolean(env.WORKER_LEASES_ENABLED, "WORKER_LEASES_ENABLED") ?? false

export const resolveWorkerLeaseSettings = ({
  env = resolveDefaultEnv(),
  leaseMsEnv,
  staleReclaimIntervalMsEnv,
  gracefulShutdownMsEnv,
  defaults,
}: WorkerLeaseSettingsArgs): WorkerLeaseSettings => ({
  enabled: resolveWorkerLeasesEnabled(env),
  leaseMs: parsePositiveInt(env[leaseMsEnv], defaults.leaseMs, leaseMsEnv),
  staleReclaimIntervalMs: parsePositiveInt(
    env[staleReclaimIntervalMsEnv],
    defaults.staleReclaimIntervalMs,
    staleReclaimIntervalMsEnv,
  ),
  gracefulShutdownMs: parsePositiveInt(
    env[gracefulShutdownMsEnv],
    defaults.gracefulShutdownMs,
    gracefulShutdownMsEnv,
  ),
})

export const buildLeaseExpiry = (
  leaseMs: number,
  now: Date = new Date(),
): Date => new Date(now.getTime() + Math.max(1_000, Math.floor(leaseMs)))

export const normalizeClaimVersion = (value: unknown): number => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.floor(value))
  }
  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number.parseInt(value, 10)
    if (Number.isFinite(parsed)) {
      return Math.max(0, parsed)
    }
  }
  return 0
}

export const buildLeaseExpiredErrorPayload = (message: string) => ({
  code: "LEASE_EXPIRED",
  message: message.trim() || "Worker lease expired before completion.",
})

import type { FileDiffMetadata } from "@pierre/diffs"
import { useMemo } from "react"

import {
  getFileLabel,
  INITIAL_FILE_BATCH_SIZE,
  type DiffDataSource,
  type DiffLoadProfile,
} from "@/features/review/model/diff/viewer-utils"

type UseMergeRequestDiffDerivedOptions = {
  parsedFiles: FileDiffMetadata[]
  filenameFilter: string
  patchText: string
  visibleResetToken: number
  visibleWindow: { key: string; count: number }
  dataSource: DiffDataSource | null
  loadProfile: DiffLoadProfile
}

export function useMergeRequestDiffDerived({
  parsedFiles,
  filenameFilter,
  patchText,
  visibleResetToken,
  visibleWindow,
  dataSource,
  loadProfile,
}: UseMergeRequestDiffDerivedOptions) {
  const normalizedFilter = filenameFilter.trim().toLowerCase()

  const filteredFiles = useMemo(() => {
    if (!normalizedFilter) {
      return parsedFiles
    }

    return parsedFiles.filter((file) => {
      const label = getFileLabel(file).toLowerCase()
      return label.includes(normalizedFilter)
    })
  }, [normalizedFilter, parsedFiles])

  const totals = useMemo(
    () =>
      filteredFiles.reduce(
        (accumulator, file) => {
          for (const hunk of file.hunks) {
            accumulator.additions += hunk.additionLines
            accumulator.deletions += hunk.deletionLines
          }
          return accumulator
        },
        { additions: 0, deletions: 0 },
      ),
    [filteredFiles],
  )

  const visibleWindowKey = `${visibleResetToken}:${normalizedFilter}:${patchText}`

  const visibleFileCount =
    visibleWindow.key === visibleWindowKey
      ? visibleWindow.count
      : INITIAL_FILE_BATCH_SIZE

  const visibleFiles = filteredFiles.slice(0, visibleFileCount)
  const canLoadMore = visibleFileCount < filteredFiles.length

  const loadProfileSummary = useMemo(() => {
    if (!dataSource || loadProfile.fetchMs == null) {
      return ""
    }

    const parts = [
      `Source: ${dataSource === "changes" ? "changes" : dataSource === "manifest" ? "manifest" : "raw_diffs"}`,
      `fetch ${loadProfile.fetchMs}ms`,
    ]
    if (loadProfile.firstParseMs != null) {
      parts.push(`first parse ${loadProfile.firstParseMs}ms`)
    }
    if (loadProfile.fullParseMs != null) {
      parts.push(`full parse ${loadProfile.fullParseMs}ms`)
    }
    return parts.join(" · ")
  }, [dataSource, loadProfile.fetchMs, loadProfile.firstParseMs, loadProfile.fullParseMs])

  return {
    filteredFiles,
    totals,
    visibleWindowKey,
    visibleFileCount,
    visibleFiles,
    canLoadMore,
    loadProfileSummary,
  }
}

