import { parseJsonResponse } from "@/lib/http/response-json"

type IntegrationStatus = "active" | "degraded" | "disabled"

export type GitLabIntegrationQueryRow = {
  id: string
  instanceUrl: string
  projectId: string
  projectPath: string
  projectName: string
  aiReviewAutoPostEnabled: boolean
  status: IntegrationStatus
  webhookUrl: string
  hookId: string | null
  lastHookSyncAt: string | null
  lastWebhookReceivedAt: string | null
  lastError: string | null
  createdAt: string
  updatedAt: string
}

type GitLabIntegrationsCacheEntry = {
  expiresAt: number
  rows: GitLabIntegrationQueryRow[]
}

const GITLAB_INTEGRATIONS_FALLBACK_ERROR = "Failed to load integrations."

export const GITLAB_INTEGRATIONS_QUERY_KEY = "gitlab.integrations"
export const GITLAB_INTEGRATIONS_STALE_TIME_MS = 45_000

let gitLabIntegrationsCacheEntry: GitLabIntegrationsCacheEntry | null = null
let gitLabIntegrationsInFlight: Promise<GitLabIntegrationQueryRow[]> | null = null
let gitLabIntegrationsQueryVersion = 0

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const asString = (value: unknown) => (typeof value === "string" ? value : "")

const asNullableString = (value: unknown) => (typeof value === "string" && value.length > 0 ? value : null)

const toIntegrationStatus = (value: unknown): IntegrationStatus => {
  if (value === "active" || value === "degraded" || value === "disabled") {
    return value
  }
  return "disabled"
}

const toIsoString = (value: unknown) => {
  if (typeof value === "string" && value.trim().length > 0) {
    return value
  }

  if (value instanceof Date && Number.isFinite(value.getTime())) {
    return value.toISOString()
  }

  return ""
}

const extractErrorMessage = (payload: unknown, fallback: string) => {
  const root = asRecord(payload)
  const message = root?.error
  if (typeof message === "string" && message.trim().length > 0) {
    return message
  }
  return fallback
}

const parseIntegrationRow = (value: unknown): GitLabIntegrationQueryRow | null => {
  const row = asRecord(value)
  if (!row) {
    return null
  }

  const id = asString(row.id).trim()
  const instanceUrl = asString(row.instanceUrl).trim()
  const projectId = asString(row.projectId).trim()
  const projectPath = asString(row.projectPath).trim()
  const projectNameRaw = asString(row.projectName).trim()
  if (!id || !instanceUrl || !projectId || !projectPath) {
    return null
  }

  return {
    id,
    instanceUrl,
    projectId,
    projectPath,
    projectName: projectNameRaw || projectPath,
    aiReviewAutoPostEnabled: Boolean(row.aiReviewAutoPostEnabled),
    status: toIntegrationStatus(row.status),
    webhookUrl: asString(row.webhookUrl),
    hookId: asNullableString(row.hookId),
    lastHookSyncAt: asNullableString(row.lastHookSyncAt),
    lastWebhookReceivedAt: asNullableString(row.lastWebhookReceivedAt),
    lastError: asNullableString(row.lastError),
    createdAt: toIsoString(row.createdAt),
    updatedAt: toIsoString(row.updatedAt),
  }
}

const parseGitLabIntegrationsPayload = (payload: unknown) => {
  const root = asRecord(payload)
  const rows = root?.data
  if (!Array.isArray(rows)) {
    return []
  }

  return rows.flatMap((row) => {
    const normalized = parseIntegrationRow(row)
    return normalized ? [normalized] : []
  })
}

const normalizeGitLabIntegrations = (rows: readonly GitLabIntegrationQueryRow[]) =>
  rows.flatMap((row) => {
    const normalized = parseIntegrationRow(row)
    return normalized ? [normalized] : []
  })

export const getGitLabIntegrationsQueryVersion = () => gitLabIntegrationsQueryVersion

export const getFreshGitLabIntegrationsQueryData = () => {
  if (!gitLabIntegrationsCacheEntry) {
    return null
  }

  if (gitLabIntegrationsCacheEntry.expiresAt <= Date.now()) {
    gitLabIntegrationsCacheEntry = null
    return null
  }

  return gitLabIntegrationsCacheEntry.rows
}

export const invalidateGitLabIntegrationsQuery = () => {
  gitLabIntegrationsCacheEntry = null
  gitLabIntegrationsQueryVersion += 1
}

export const hydrateGitLabIntegrationsQuery = (rows: readonly GitLabIntegrationQueryRow[]) => {
  const now = Date.now()
  if (gitLabIntegrationsCacheEntry && gitLabIntegrationsCacheEntry.expiresAt > now) {
    return
  }

  gitLabIntegrationsCacheEntry = {
    expiresAt: now + GITLAB_INTEGRATIONS_STALE_TIME_MS,
    rows: normalizeGitLabIntegrations(rows),
  }
}

export const loadGitLabIntegrations = async (options?: { forceRefresh?: boolean; force?: boolean }) => {
  const shouldForceRefresh = options?.forceRefresh === true || options?.force === true
  const now = Date.now()

  if (!shouldForceRefresh && gitLabIntegrationsCacheEntry && gitLabIntegrationsCacheEntry.expiresAt > now) {
    return gitLabIntegrationsCacheEntry.rows
  }

  if (gitLabIntegrationsInFlight) {
    return gitLabIntegrationsInFlight
  }

  const request = (async () => {
    const response = await fetch("/api/gitlab/integrations", {
      method: "GET",
      cache: "no-store",
      headers: {
        "content-type": "application/json",
      },
    })

    const parsedResponse = await parseJsonResponse(response)
    const payload = parsedResponse.ok ? parsedResponse.value : null
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, GITLAB_INTEGRATIONS_FALLBACK_ERROR))
    }
    if (!parsedResponse.ok || parsedResponse.isEmpty) {
      throw new Error("Invalid integrations response payload.")
    }

    const rows = parseGitLabIntegrationsPayload(payload)
    gitLabIntegrationsCacheEntry = {
      expiresAt: Date.now() + GITLAB_INTEGRATIONS_STALE_TIME_MS,
      rows,
    }
    gitLabIntegrationsQueryVersion += 1
    return rows
  })()

  gitLabIntegrationsInFlight = request
  try {
    return await request
  } finally {
    if (gitLabIntegrationsInFlight === request) {
      gitLabIntegrationsInFlight = null
    }
  }
}

