}

fn manifest_path_for_store(store_path: &Path) -> PathBuf {
  let file_name = store_path
    .file_name()
    .and_then(|name| name.to_str())
    .map(|name| format!("{name}.manifest.json"))
    .unwrap_or_else(|| "index.kite.manifest.json".to_string());
  store_path
    .parent()
    .map(|parent| parent.join(&file_name))
    .unwrap_or_else(|| PathBuf::from(file_name))
}

#[derive(Debug)]
pub enum KiteStoreError {
  Kite(KiteError),
  Io(std::io::Error),
  Json(serde_json::Error),
}

impl std::fmt::Display for KiteStoreError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      KiteStoreError::Kite(err) => write!(f, "kitedb error: {err}"),
      KiteStoreError::Io(err) => write!(f, "io error: {err}"),
      KiteStoreError::Json(err) => write!(f, "json error: {err}"),
    }
  }
}

impl std::error::Error for KiteStoreError {}

impl From<KiteError> for KiteStoreError {
  fn from(value: KiteError) -> Self {
    KiteStoreError::Kite(value)
  }
}

impl From<std::io::Error> for KiteStoreError {
  fn from(value: std::io::Error) -> Self {
    KiteStoreError::Io(value)
  }
}

impl From<serde_json::Error> for KiteStoreError {
  fn from(value: serde_json::Error) -> Self {
    KiteStoreError::Json(value)
  }
}

#[derive(Debug, Clone)]
pub struct KiteStoreOptions {
  pub path: PathBuf,
  pub clear: bool,
  pub checkpoint_on_finish: bool,
  pub checkpoint_threshold: f64,
