type RepoAiSettingsPanelProps = {
  instanceUrl: string
  projectId: string
  projectPath: string
}

export function RepoAiSettingsPanel({
  instanceUrl,
  projectId,
  projectPath,
}: RepoAiSettingsPanelProps) {
  const [reviewSettings, setReviewSettings] =
    useState<ReviewGateSettings>(REVIEW_GATE_DEFAULTS)
  const [hasProjectReviewOverride, setHasProjectReviewOverride] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [isSaving, setIsSaving] = useState(false)
  const [error, setError] = useState("")
  const [status, setStatus] = useState("")

  const updateSetting = useCallback(
    (key: keyof ReviewGateSettings, value: ReviewGateSettings[keyof ReviewGateSettings]) => {
      setReviewSettings((current) => ({ ...current, [key]: value }))
    },
    [],
  )

  const updateTemplate = useCallback((persona: ReviewPersona, value: string) => {
    setReviewSettings((current) => ({
      ...current,
      personaTemplates: { ...current.personaTemplates, [persona]: value },
    }))
  }, [])

const loadSettings = useCallback(async () => {
  setIsLoading(true)
  setError("")

  try {
    const payload = await fetchReviewPreferences({ instanceUrl, projectId })
    const globalSettings = payload.global ?? REVIEW_GATE_DEFAULTS
    const projectOverride = payload.projectOverride

    setHasProjectReviewOverride(Boolean(projectOverride))
    setReviewSettings(projectOverride ?? globalSettings)
  } catch (err) {
    setError(
      err instanceof Error ? err.message : "Failed to load project AI review settings.",
    )
  } finally {
    setIsLoading(false)
  }
}, [instanceUrl, projectId])

const handleSave = useCallback(async () => {
  setIsSaving(true)
  setError("")
  setStatus("")

  try {
    const payload = await saveProjectReviewPreferences({
      instanceUrl,
      projectId,
      settings: reviewSettings,
    })
    setHasProjectReviewOverride(true)
    setReviewSettings(payload.projectOverride ?? reviewSettings)
    setStatus("Project AI review override saved.")
  } catch (err) {
    setError(
      err instanceof Error ? err.message : "Failed to save project AI review settings.",
    )
  } finally {
    setIsSaving(false)
  }
}, [instanceUrl, projectId, reviewSettings])

const handleClearOverride = useCallback(async () => {
  setIsSaving(true)
  setError("")
  setStatus("")

  try {
    const payload = await deleteProjectReviewPreferences({ instanceUrl, projectId })
    setHasProjectReviewOverride(false)
    setReviewSettings(payload.global ?? REVIEW_GATE_DEFAULTS)
    setStatus("Project override removed. Using global defaults.")
  } catch (err) {
    setError(
      err instanceof Error ? err.message : "Failed to remove project override.",
    )
  } finally {
    setIsSaving(false)
  }
}, [instanceUrl, projectId])

useEffect(() => {
  void loadSettings()
}, [loadSettings])

if (isLoading) {
  return (
    <div className="flex items-center justify-center py-12">
      <div className="flex items-center gap-2 text-sm text-muted-foreground">
        <Loader2 className="size-4 animate-spin" />
        Loading AI review settings…
      </div>
    </div>
  )
}

return (
  <div className="space-y-4">
