import { and, asc, eq } from "drizzle-orm";

import { db } from "@/lib/db";
import {
  onboardingEvents,
} from "@/lib/db/schema";
import {
  ONBOARDING_COMPLETED_EVENT,
  ONBOARDING_STARTED_EVENT,
  type OnboardingEventMetadata,
} from "@/lib/onboarding/types";

const ONBOARDING_COMPLETED_UNIQUE_INDEX = "onboarding_events_user_id_completed_uq";

const getFirstEventAt = async (
  userId: string,
  event: typeof ONBOARDING_STARTED_EVENT | typeof ONBOARDING_COMPLETED_EVENT,
) => {
  const rows = await db
    .select({ createdAt: onboardingEvents.createdAt })
    .from(onboardingEvents)
    .where(
      and(
        eq(onboardingEvents.userId, userId),
        eq(onboardingEvents.event, event),
      ),
    )
    .orderBy(asc(onboardingEvents.createdAt))
    .limit(1);

  return rows[0]?.createdAt ?? null;
};

const getFirstCompletionEvent = async (userId: string) => {
  const rows = await db
    .select({
      createdAt: onboardingEvents.createdAt,
      metadata: onboardingEvents.metadata,
    })
    .from(onboardingEvents)
    .where(
      and(
        eq(onboardingEvents.userId, userId),
        eq(onboardingEvents.event, ONBOARDING_COMPLETED_EVENT),
      ),
    )
    .orderBy(asc(onboardingEvents.createdAt))
    .limit(1);

  return rows[0] ?? null;
};

const resolveDurationMs = (metadata: OnboardingEventMetadata | null | undefined) => {
  const value = metadata?.onboardingDurationMs;
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return null;
  }
  return Math.max(0, value);
};

const isCompletedUniqueViolation = (error: unknown) => {
  if (!error || typeof error !== "object") {
    return false;
  }
  const candidate = error as { code?: unknown; constraint?: unknown };
  return (
    candidate.code === "23505" &&
    candidate.constraint === ONBOARDING_COMPLETED_UNIQUE_INDEX
  );
};

export const isOnboardingCompleted = async (userId: string) => {
  const completion = await getFirstCompletionEvent(userId);
  return completion !== null;
};

export const recordOnboardingCompletedIfMissing = async ({
  userId,
  metadata,
}: {
  userId: string;
  metadata?: OnboardingEventMetadata;
}) => {

  const [existingCompletion, startedAt] = await Promise.all([
    getFirstCompletionEvent(userId),
    getFirstEventAt(userId, ONBOARDING_STARTED_EVENT),
  ]);

  if (existingCompletion) {
    return {
      alreadyCompleted: true,
      onboardingDurationMs: resolveDurationMs(existingCompletion.metadata),
      onboardingCompletedAt: existingCompletion.createdAt,
    };
  }

  const completedAt = new Date();
  const onboardingDurationMs = startedAt
    ? Math.max(0, completedAt.getTime() - startedAt.getTime())
    : null;

  const completionMetadata: OnboardingEventMetadata = {
    ...metadata,
    onboardingStartedAt: startedAt?.toISOString(),
    onboardingCompletedAt: completedAt.toISOString(),
    onboardingDurationMs: onboardingDurationMs ?? undefined,
  };

  try {
    await db.insert(onboardingEvents).values({
      userId,
      event: ONBOARDING_COMPLETED_EVENT,
      createdAt: completedAt,
      metadata: completionMetadata,
    });
  } catch (error) {
    // The partial unique index guarantees one completion row per user.
    if (!isCompletedUniqueViolation(error)) {
      throw error;
    }

    const completion = await getFirstCompletionEvent(userId);
    if (!completion) {
      throw error;
    }

    return {
      alreadyCompleted: true,
      onboardingDurationMs: resolveDurationMs(completion.metadata),
      onboardingCompletedAt: completion.createdAt,
    };
  }

  return {
    alreadyCompleted: false,
    onboardingDurationMs,
    onboardingCompletedAt: completedAt,
  };
};

