import { Link, useRouterState } from "@tanstack/react-router"
import type { ReactNode } from "react"

import { DOCS_NAV_ITEMS } from "@/lib/docs-navigation"

type DocsShellProps = {
  children: ReactNode
}

const normalizePath = (value: string) => {
  if (!value || value === "/") {
    return "/"
  }

  return value.replace(/\/+$/, "")
}

const isNavItemActive = (pathname: string, href: string) => {
  const current = normalizePath(pathname)
  const target = normalizePath(href)

  if (target === "/") {
    return current === "/"
  }

  return current === target || current.startsWith(`${target}/`)
}

export function DocsShell({ children }: DocsShellProps) {
  const pathname = useRouterState({
    select: (state) => state.location.pathname,
  })

  return (
    <div className="docs-root">
      <header className="docs-header">
        <div className="docs-header-inner">
          <Link to="/" className="docs-brand">
            Argus Docs
          </Link>
          <a href="/" className="docs-app-link">
            Open app
          </a>
        </div>
      </header>
      <div className="docs-shell">
        <aside className="docs-sidebar" aria-label="Docs navigation">
          <p className="docs-sidebar-title">Docs</p>
          <ul className="docs-nav-list">
            {DOCS_NAV_ITEMS.map((item) => {
              const isActive = isNavItemActive(pathname, item.href)
              return (
                <li key={item.href}>
                  <Link
                    to={item.href}
                    className={`docs-nav-link${isActive ? " is-active" : ""}`}
                    activeOptions={{ exact: item.href === "/" }}
                  >
                    <span className="docs-nav-link-title">{item.title}</span>
                    <span className="docs-nav-link-description">{item.description}</span>
                  </Link>
                </li>
              )
            })}
          </ul>
        </aside>
        <main className="docs-main">
          <article className="docs-article">{children}</article>
        </main>
      </div>
    </div>
  )
}

