import { describe, expect, test } from "bun:test"

import { createRoutePrewarmIntentController } from "@/lib/navigation/route-prewarm-intent"

const wait = (ms: number) => new Promise<void>((resolve) => {
  setTimeout(resolve, ms)
})

describe("route-prewarm-intent", () => {
  test("debounces mouse/focus prewarm and supports cancellation", async () => {
    const calls: string[] = []
    const controller = createRoutePrewarmIntentController({
      onPrewarm: (href) => {
        calls.push(href)
      },
      debounceMs: 8,
    })
    const handlers = controller.getRoutePrewarmIntentHandlers("/settings")

    handlers.onMouseEnter()
    await wait(3)
    handlers.onMouseLeave()
    await wait(12)

    expect(calls).toEqual([])

    handlers.onFocus()
    await wait(12)

    expect(calls).toEqual(["/settings"])
    controller.dispose()
  })

  test("prewarms immediately on touch and primary mouse pointer down", () => {
    const calls: string[] = []
    const controller = createRoutePrewarmIntentController({
      onPrewarm: (href) => {
        calls.push(href)
      },
      debounceMs: 50,
    })
    const handlers = controller.getRoutePrewarmIntentHandlers("/repos/acme")

    handlers.onTouchStart()
    handlers.onPointerDown({ button: 1, pointerType: "mouse" })
    handlers.onPointerDown({ button: 0, pointerType: "touch" })
    handlers.onPointerDown({ button: 0, pointerType: "mouse" })

    expect(calls).toEqual(["/repos/acme", "/repos/acme"])
    controller.dispose()
  })

  test("dispose clears pending timers", async () => {
    const calls: string[] = []
    const controller = createRoutePrewarmIntentController({
      onPrewarm: (href) => {
        calls.push(href)
      },
      debounceMs: 8,
    })

    controller.scheduleRoutePrewarm("/observability")
    controller.dispose()
    await wait(12)

    expect(calls).toEqual([])
  })
})

import { readFile, stat } from "node:fs/promises"
import path from "node:path"

import { and, desc, eq, isNotNull } from "drizzle-orm"

import { db } from "@/lib/db"
import { indexBranchStates, indexRuns } from "@/lib/db/schema"
import { createArtifactStore } from "@/lib/indexing/stores/artifact-store"
import { createImpactGraphBackend, type GraphImpactSnapshotReady } from "@/lib/review/impact-graph-backend"
import type { GraphNode, GraphStore } from "@/lib/review/impact-graph-backend-kitedb-store"
import { loadGraphStoreFromSnapshot, normalizePath } from "@/lib/review/impact-graph-backend-kitedb-store"
import {
  DEFAULT_GRAPH_ARTIFACTS_ROOT,
  resolveReadySnapshotFromRunArtifacts,
  type GraphArtifactStoreReader,
} from "@/lib/review/impact-graph-backend-kitedb-snapshot"

type GraphQueryScope = {
  integrationId?: string | null
  sourceBranch?: string | null
}

type SnapshotRunCandidate = {
  integrationId: string
  branch: string
  runId: string
  status: "planned" | "ingesting" | "indexing" | "cancelled" | "ready" | "failed" | "superseded"
  artifactsPrefix: string
  stats: Record<string, unknown> | null
}

export type SnapshotGraphResolution =
  | {
      status: "ready"
      snapshot: GraphImpactSnapshotReady
      artifactStore: GraphArtifactStoreReader | null
    }
  | {
      status: "pending_graph"
      reason: string
      message: string
    }
  | {
      status: "error"
      error: string
    }

export type SnapshotGraphNode = {
  id: string
  kind: string
  name: string | null
  filePath: string | null
  language: string | null
  range: GraphNode["range"]
}

export type SnapshotGraphEdge = {
  sourceId: string
  targetId: string
  type: string
}

export type SnapshotGraphQueryResult = {
  indexRunId: string
  generatedAt: string
  totalNodes: number
  totalEdges: number
  availableEdgeTypes: string[]
  appliedEdgeTypes: string[]
  nodes: SnapshotGraphNode[]
  edges: SnapshotGraphEdge[]
}

export type SnapshotGraphEdgeTypes = {
  indexRunId: string
  generatedAt: string
  edgeTypes: string[]
}

export type SnapshotGraphSummary = {
  indexRunId: string
  generatedAt: string
  schemaVersion: string
  stats: {
    filesParsed: number
    chunksEmitted: number
    nodesEmitted: number
    edgesEmitted: number
  }
}

export type LoadedSnapshotGraphData = {
  snapshot: GraphImpactSnapshotReady
  store: GraphStore
  nodes: SnapshotGraphNode[]
  edges: SnapshotGraphEdge[]
  edgeTypes: string[]
  totalNodes: number
  totalEdges: number
}

export type SnapshotGraphImpactPreset = "callers" | "callees" | "dependencies" | "dependents" | "impact"

const MAX_FALLBACK_READY_RUN_CANDIDATES = 30

let cachedArtifactStoreReader: GraphArtifactStoreReader | null | undefined
const graphDataCache = new Map<string, Promise<LoadedSnapshotGraphData>>()

const toOptionalString = (value: string | null | undefined) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

const sampleArray = <T>(items: T[], limit: number): T[] => {
  if (limit <= 0) {
    return []
  }
  if (items.length <= limit) {
    return [...items]
  }

  const out: T[] = []
  const step = items.length / limit
  for (let index = 0; index < limit; index += 1) {
    const sourceIndex = Math.floor(index * step)
    const item = items[sourceIndex]
    if (item) {
      out.push(item)
    }
  }
  return out
}

const resolveGraphArtifactStoreReader = (): GraphArtifactStoreReader | null => {
  if (cachedArtifactStoreReader !== undefined) {
    return cachedArtifactStoreReader
  }

  const store = createArtifactStore()
  if (
    typeof store.readTextFile !== "function" ||
    typeof store.fileExists !== "function"
  ) {
    cachedArtifactStoreReader = null
    return cachedArtifactStoreReader
  }

  cachedArtifactStoreReader = {
    readTextFile: (args) => store.readTextFile!.call(store, args),
    fileExists: (args) => store.fileExists!.call(store, args),
  }
  return cachedArtifactStoreReader
}

const toSnapshotGraphNode = (node: GraphNode): SnapshotGraphNode => ({
  id: node.id,
  kind: node.kind,
  name: node.name,
  filePath: node.filePath,
  language: null,
  range: node.range,
})

const resolveNode = (data: LoadedSnapshotGraphData, id: string): SnapshotGraphNode =>
  data.store.nodesById.get(id)
    ? toSnapshotGraphNode(data.store.nodesById.get(id) as GraphNode)
    : {
        id,
        kind: "external",
        name: id,
        filePath: null,
        language: null,
        range: null,
      }

const normalizeEdgeTypeFilter = (edgeTypes: string[] | undefined, available: string[]) => {
  if (!edgeTypes?.length) {
    return null
  }
  const allowed = new Set(available)
  const normalized = edgeTypes
    .map((value) => value.trim())
    .filter((value) => value.length > 0 && allowed.has(value))

  return normalized.length > 0 ? new Set(normalized) : null
}

const filterEdgesByType = (
  edges: SnapshotGraphEdge[],
  edgeTypeFilter: Set<string> | null,
) => {
  if (!edgeTypeFilter) {
    return edges
  }
  return edges.filter((edge) => edgeTypeFilter.has(edge.type))
}

const buildDataCacheKey = (snapshot: GraphImpactSnapshotReady) =>
  [
    snapshot.indexRunId,
    snapshot.generatedAt,
    snapshot.nodesPath ?? "",
    snapshot.edgesPath ?? "",
    snapshot.artifactStorePrefix ?? "",
    snapshot.artifactStoreNodesFilename ?? "",
    snapshot.artifactStoreEdgesFilename ?? "",
  ].join(":")

const loadFallbackReadyRunCandidates = async (): Promise<SnapshotRunCandidate[]> => {
  const rows = await db
    .select({
      integrationId: indexBranchStates.integrationId,
      branch: indexBranchStates.branch,
      runId: indexRuns.id,
      status: indexRuns.status,
      artifactsPrefix: indexRuns.artifactsPrefix,
      stats: indexRuns.stats,
    })
    .from(indexRuns)
    .innerJoin(indexBranchStates, eq(indexRuns.branchStateId, indexBranchStates.id))
    .where(eq(indexRuns.status, "ready"))
    .orderBy(desc(indexRuns.updatedAt))
    .limit(MAX_FALLBACK_READY_RUN_CANDIDATES)

  return rows.map((row) => ({
    integrationId: row.integrationId,
    branch: row.branch,
    runId: row.runId,
    status: row.status,
    artifactsPrefix: row.artifactsPrefix,
    stats: (row.stats as Record<string, unknown> | null) ?? null,
  }))
}

const resolveLatestReadyBranchForIntegration = async (integrationId: string) => {
  const rows = await db
    .select({
      branch: indexBranchStates.branch,
    })
    .from(indexBranchStates)
    .where(
      and(
        eq(indexBranchStates.integrationId, integrationId),
        isNotNull(indexBranchStates.lastReadyRunId),
      ),
    )
    .orderBy(desc(indexBranchStates.servingUpdatedAt), desc(indexBranchStates.updatedAt))
    .limit(1)

  return rows[0]?.branch ?? null
}

const resolveFallbackSnapshot = async (artifactStore: GraphArtifactStoreReader | null) => {
  const candidates = await loadFallbackReadyRunCandidates()
  if (candidates.length === 0) {
    return null
  }

  for (const candidate of candidates) {
    const snapshot = await resolveReadySnapshotFromRunArtifacts({
      backend: "kitedb_fs",
      integrationId: candidate.integrationId,
      branch: candidate.branch,
      run: {
        id: candidate.runId,
        status: candidate.status,
        artifactsPrefix: candidate.artifactsPrefix,
        stats: candidate.stats,
      },
      graphArtifactsRoot: path.resolve(DEFAULT_GRAPH_ARTIFACTS_ROOT),
      readTextFile: (filePath) => readFile(filePath, "utf8"),
      statPath: (filePath) => stat(filePath),
      artifactStore,
    })

    if (snapshot) {
      return snapshot
    }
  }

  return null
}

export const resolveSnapshotGraphScope = async (
  scope: GraphQueryScope = {},
): Promise<SnapshotGraphResolution> => {
  const artifactStore = resolveGraphArtifactStoreReader()
  const integrationId = toOptionalString(scope.integrationId)
  const sourceBranch = toOptionalString(scope.sourceBranch)

try {
  if (integrationId || sourceBranch) {
    const resolvedSourceBranch =
      sourceBranch ??
      (integrationId ? await resolveLatestReadyBranchForIntegration(integrationId) : null)

    if (integrationId && !resolvedSourceBranch) {
      return {
        status: "pending_graph",
        reason: "no_ready_run",
        message: "No ready graph snapshot branch is available for this integration yet.",
      }
    }

    const backend = createImpactGraphBackend()
    const snapshot = await backend.resolveSnapshot({
      integrationId,
      sourceBranch: resolvedSourceBranch,
    })

    if (snapshot.status === "ready") {
      return {
        status: "ready",
        snapshot,
        artifactStore,
      }
    }

    if (snapshot.status === "pending_graph") {
      return {
        status: "pending_graph",
        reason: snapshot.reason,
        message: snapshot.message,
      }
    }

    return {
      status: "error",
      error: snapshot.error,
    }
  }

  const fallback = await resolveFallbackSnapshot(artifactStore)
  if (fallback) {
    return {
      status: "ready",
      snapshot: fallback,
      artifactStore,
    }
  }

  return {
    status: "pending_graph",
    reason: "no_ready_run",
    message: "No ready graph snapshot is available yet.",
  }
} catch (error) {
  return {
    status: "error",
    error: error instanceof Error ? error.message : "Failed to resolve graph snapshot.",
  }
}

}

export const loadSnapshotGraphData = async (args: {
  snapshot: GraphImpactSnapshotReady
  artifactStore: GraphArtifactStoreReader | null
}): Promise<LoadedSnapshotGraphData> => {
  const cacheKey = buildDataCacheKey(args.snapshot)
  const cached = graphDataCache.get(cacheKey)
  if (cached) {
    return cached
  }

  const next = (async () => {
    const store = await loadGraphStoreFromSnapshot({
      snapshot: args.snapshot,
      artifactStore: args.artifactStore,
    })
    const nodes = [...store.nodesById.values()].map(toSnapshotGraphNode)

    const edges: SnapshotGraphEdge[] = []
    for (const outgoing of store.outgoing.values()) {
      for (const edge of outgoing) {
        edges.push({
          sourceId: edge.sourceId,
          targetId: edge.targetId,
          type: edge.type,
        })
      }
    }

    const edgeTypes = [...new Set(edges.map((edge) => edge.type))]
      .filter((value) => value.trim().length > 0)
      .sort((left, right) => left.localeCompare(right))

    return {
      snapshot: args.snapshot,
      store,
      nodes,
      edges,
      edgeTypes,
      totalNodes: nodes.length,
      totalEdges: edges.length,
    }
  })()

  graphDataCache.set(cacheKey, next)
  return next
}

export const getSnapshotGraphSummary = (args: {
  data: LoadedSnapshotGraphData
}): SnapshotGraphSummary => ({
  indexRunId: args.data.snapshot.indexRunId,
  generatedAt: args.data.snapshot.generatedAt,
  schemaVersion: "artifact-store-v1",
  stats: {
    filesParsed: 0,
    chunksEmitted: 0,
    nodesEmitted: args.data.totalNodes,
    edgesEmitted: args.data.totalEdges,
  },
})

export const getSnapshotGraphEdgeTypes = (args: {
  data: LoadedSnapshotGraphData
}): SnapshotGraphEdgeTypes => ({
  indexRunId: args.data.snapshot.indexRunId,
  generatedAt: args.data.snapshot.generatedAt,
  edgeTypes: args.data.edgeTypes,
})

export const sampleSnapshotGraphForVisualization = (args: {
  data: LoadedSnapshotGraphData
  maxNodes?: number
  maxEdges?: number
  edgeTypes?: string[]
}): SnapshotGraphQueryResult => {
  const maxNodes = Math.min(2_000, Math.max(10, args.maxNodes ?? 220))
  const maxEdges = Math.min(10_000, Math.max(10, args.maxEdges ?? 420))

  const edgeTypeFilter = normalizeEdgeTypeFilter(args.edgeTypes, args.data.edgeTypes)
  const filteredEdges = filterEdgesByType(args.data.edges, edgeTypeFilter)
  const sampledEdges = sampleArray(filteredEdges, maxEdges)

  const selectedNodeIds = new Set<string>()
  const finalEdges: SnapshotGraphEdge[] = []
  for (const edge of sampledEdges) {
    const hasSource = selectedNodeIds.has(edge.sourceId)
    const hasTarget = selectedNodeIds.has(edge.targetId)
    const nodesToAdd = (hasSource ? 0 : 1) + (hasTarget ? 0 : 1)

    if (selectedNodeIds.size + nodesToAdd > maxNodes) {
      continue
    }

    selectedNodeIds.add(edge.sourceId)
    selectedNodeIds.add(edge.targetId)
    finalEdges.push(edge)

    if (finalEdges.length >= maxEdges || selectedNodeIds.size >= maxNodes) {
      break
    }
  }

  return {
    indexRunId: args.data.snapshot.indexRunId,
    generatedAt: args.data.snapshot.generatedAt,
    totalNodes: args.data.totalNodes,
    totalEdges: args.data.totalEdges,
    availableEdgeTypes: args.data.edgeTypes,
    appliedEdgeTypes: edgeTypeFilter ? [...edgeTypeFilter] : [],
    nodes: [...selectedNodeIds].map((id) => resolveNode(args.data, id)),
    edges: finalEdges,
  }
}

export const querySnapshotGraphNeighborhood = (args: {

  data: LoadedSnapshotGraphData
  nodeId: string
  depth?: number
  direction?: "incoming" | "outgoing" | "both"
  edgeTypes?: string[]
  maxNodes?: number
  maxEdges?: number
}): SnapshotGraphQueryResult => {
  const nodeId = args.nodeId.trim()
  if (!nodeId) {
    throw new Error("Neighborhood query requires a non-empty nodeId.")
  }

  const depth = Math.min(6, Math.max(1, args.depth ?? 2))
  const direction = args.direction ?? "both"
  const maxNodes = Math.min(2_000, Math.max(10, args.maxNodes ?? 400))
  const maxEdges = Math.min(10_000, Math.max(10, args.maxEdges ?? 900))
  const edgeTypeFilter = normalizeEdgeTypeFilter(args.edgeTypes, args.data.edgeTypes)

  const queue: Array<{ id: string; depth: number }> = [{ id: nodeId, depth: 0 }]
  const visited = new Set<string>([nodeId])
  const edgesByKey = new Map<string, SnapshotGraphEdge>()
  let queueIndex = 0

while (queueIndex < queue.length && visited.size < maxNodes && edgesByKey.size < maxEdges) {
  const current = queue[queueIndex]
  queueIndex += 1
  if (!current || current.depth >= depth) {
    continue
  }

  const outgoing = direction === "incoming" ? [] : args.data.store.outgoing.get(current.id) ?? []
  const incoming = direction === "outgoing" ? [] : args.data.store.incoming.get(current.id) ?? []
  const candidates = [...outgoing, ...incoming]

  for (const edge of candidates) {
    if (edgeTypeFilter && !edgeTypeFilter.has(edge.type)) {
      continue
    }
    const key = `${edge.sourceId}->${edge.targetId}:${edge.type}`
    if (!edgesByKey.has(key)) {
      edgesByKey.set(key, {
        sourceId: edge.sourceId,
        targetId: edge.targetId,
        type: edge.type,
      })
    }
    if (edgesByKey.size >= maxEdges) {
      break
    }

    const nextId = edge.sourceId === current.id ? edge.targetId : edge.sourceId
    if (!visited.has(nextId) && visited.size < maxNodes) {
      visited.add(nextId)
      queue.push({ id: nextId, depth: current.depth + 1 })
    }
  }
}

return {
  indexRunId: args.data.snapshot.indexRunId,
  generatedAt: args.data.snapshot.generatedAt,
  totalNodes: args.data.totalNodes,
  totalEdges: args.data.totalEdges,
  availableEdgeTypes: args.data.edgeTypes,
  appliedEdgeTypes: edgeTypeFilter ? [...edgeTypeFilter] : [],
  nodes: [...visited].map((id) => resolveNode(args.data, id)),
  edges: [...edgesByKey.values()],
}

}

export const querySnapshotGraphImpactPreset = (args: {
  data: LoadedSnapshotGraphData
  nodeId: string
  preset: SnapshotGraphImpactPreset
  depth?: number
  maxNodes?: number
  maxEdges?: number
}): SnapshotGraphQueryResult => {
  const presetToQuery: Record<
    SnapshotGraphImpactPreset,
    { direction: "incoming" | "outgoing" | "both"; edgeTypes: string[] }
  > = {
    callers: { direction: "incoming", edgeTypes: ["CALLS"] },
    callees: { direction: "outgoing", edgeTypes: ["CALLS"] },
    dependencies: { direction: "outgoing", edgeTypes: ["IMPORTS"] },
    dependents: { direction: "incoming", edgeTypes: ["IMPORTS"] },
    impact: { direction: "both", edgeTypes: ["CALLS", "IMPORTS", "REFERENCES"] },
  }

  const mapping = presetToQuery[args.preset]
  return querySnapshotGraphNeighborhood({
    data: args.data,
    nodeId: args.nodeId,
    depth: args.depth,
    direction: mapping.direction,
    edgeTypes: mapping.edgeTypes,
    maxNodes: args.maxNodes,
    maxEdges: args.maxEdges,
  })
}

export const findSnapshotGraphNodeForFileLine = (args: {
  data: LoadedSnapshotGraphData
  filePath: string
  line: number
}) => {
  const normalizedFilePath = normalizePath(args.filePath)
  const nodesInFile = args.data.store.nodesByFilePath.get(normalizedFilePath) ?? []
  if (nodesInFile.length === 0) {
    return null
  }

  const line = Math.max(1, Math.floor(args.line))
  const lineZero = line - 1
  const inRange = nodesInFile.filter((node) => {
    if (!node.range) {
      return false
    }
    return lineZero >= node.range.start.row && lineZero <= node.range.end.row
  })

  const source = inRange[0] ?? nodesInFile[0]
  if (!source) {
    return null
  }
  return {
    nodeId: source.id,
    sourceFile: source.filePath ?? normalizedFilePath,
    sourceLine: line,
  }
}

