import { NextResponse } from "next/server"

import {
  getReviewFlowRunByTraceId,
  listReviewFlowEventsByTraceId,
  type ReviewFlowEventRecord,
} from "@/lib/review/flow-run"
import { subscribeToReviewFlowEventNotifications } from "@/lib/review/review-flow-notifications"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const maxDuration = 300

const STREAM_POLL_INTERVAL_MS = 1_200
const STREAM_KEEPALIVE_INTERVAL_MS = 15_000
const STREAM_INITIAL_EVENT_LIMIT = 120

const asPositiveInt = (value: unknown) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.floor(value))
  }
  if (typeof value === "string") {
    const parsed = Number.parseInt(value, 10)
    if (Number.isFinite(parsed)) {
      return Math.max(0, parsed)
    }
  }
  return 0
}

const parseLastEventId = (request: Request, url: URL) => {
  const headerLastEventId = asPositiveInt(request.headers.get("last-event-id"))
  const queryLastEventId = asPositiveInt(url.searchParams.get("afterId"))
  return Math.max(headerLastEventId, queryLastEventId)
}

const toSseEventName = (eventType: string) => {
  if (
    eventType === "progress" ||
    eventType === "summary" ||
    eventType === "done" ||
    eventType === "failed"
  ) {
    return eventType
  }
  return "progress"
}

const serializeFlowEvent = (event: ReviewFlowEventRecord) => ({
  id: event.id,
  traceId: event.traceId,
  flowRunId: event.flowRunId,
  stage: event.stage,
  eventType: event.eventType,
  message: event.message,
  payload: event.payload,
  createdAt: event.createdAt,
})

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/diff/stream",
    event: "api.review.diff.stream",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const url = new URL(request.url)
      const traceId = (url.searchParams.get("traceId") ?? "").trim()
      if (!traceId) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "traceId is required." }, { status: 400 }),
        }
      }

      const run = await getReviewFlowRunByTraceId({
        userId,
        traceId,
      })
      if (!run) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Review run not found." }, { status: 404 }),
        }
      }

      const lastEventId = parseLastEventId(request, url)

const replayEvents = await listReviewFlowEventsByTraceId({
  traceId,
  afterId: lastEventId > 0 ? lastEventId : undefined,
  limit: STREAM_INITIAL_EVENT_LIMIT,
  descending: lastEventId <= 0,
})

logger.set({
  traceId,
  replayCount: replayEvents.length,
  lastEventId,
})

const encoder = new TextEncoder()
let closed = false
let pollTimer: ReturnType<typeof setInterval> | null = null
let keepAliveTimer: ReturnType<typeof setInterval> | null = null
let unsubscribeFlowEvents: (() => void) | null = null
let inFlight = false
let cursor = Math.max(
  lastEventId,
  replayEvents[replayEvents.length - 1]?.id ?? 0,
)

const close = (controller: ReadableStreamDefaultController<Uint8Array>) => {
  if (closed) {
    return
  }
  closed = true
  if (pollTimer) {
    clearInterval(pollTimer)
    pollTimer = null
  }
  if (keepAliveTimer) {
    clearInterval(keepAliveTimer)
    keepAliveTimer = null
  }
  if (unsubscribeFlowEvents) {
    unsubscribeFlowEvents()
    unsubscribeFlowEvents = null
  }
  try {
    controller.close()
  } catch {
    // no-op
  }
}

const sendEvent = (
  controller: ReadableStreamDefaultController<Uint8Array>,
  event: string,
  data: Record<string, unknown>,
) => {
  if (closed) {
    return
  }
  controller.enqueue(
    encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`),
  )
}

const sendFlowEvent = (
  controller: ReadableStreamDefaultController<Uint8Array>,
  event: ReviewFlowEventRecord,
) => {
  if (closed) {
    return
  }

  controller.enqueue(
    encoder.encode(
      `id: ${event.id}\nevent: ${toSseEventName(event.eventType)}\ndata: ${JSON.stringify(serializeFlowEvent(event))}\n\n`,
    ),
  )
}

const stream = new ReadableStream<Uint8Array>({
  start(controller) {
    request.signal.addEventListener("abort", () => {
      close(controller)
    })

    sendEvent(controller, "ready", {
      traceId,
      run,
      events: replayEvents.map(serializeFlowEvent),
      lastEventId: cursor,
      at: new Date().toISOString(),
    })

const sync = async () => {
  if (closed || inFlight) {
    return
  }
  inFlight = true
  try {
    const nextEvents = await listReviewFlowEventsByTraceId({
      traceId,
      afterId: cursor,
      limit: STREAM_INITIAL_EVENT_LIMIT,
    })
    if (nextEvents.length === 0) {
      return
    }

    for (const event of nextEvents) {
      cursor = Math.max(cursor, event.id)
      sendFlowEvent(controller, event)
      if (event.eventType === "done" || event.eventType === "failed") {
        close(controller)
        break
      }
    }
  } catch {
    sendEvent(controller, "failed", {
      traceId,
      message: "AI review stream failed.",
      at: new Date().toISOString(),
    })
    close(controller)
  } finally {
    inFlight = false
  }
}

pollTimer = setInterval(() => {
  void sync()
}, STREAM_POLL_INTERVAL_MS)

unsubscribeFlowEvents = subscribeToReviewFlowEventNotifications((payload) => {
  if (payload.traceId !== traceId) {
    return
  }
  void sync()
})

void sync()

          keepAliveTimer = setInterval(() => {
            if (closed) {
              return
            }
            sendEvent(controller, "heartbeat", {
              traceId,
              at: new Date().toISOString(),
            })
          }, STREAM_KEEPALIVE_INTERVAL_MS)
        },
        cancel() {
          closed = true
          if (pollTimer) {
            clearInterval(pollTimer)
            pollTimer = null
          }
          if (keepAliveTimer) {
            clearInterval(keepAliveTimer)
            keepAliveTimer = null
          }
          if (unsubscribeFlowEvents) {
            unsubscribeFlowEvents()
            unsubscribeFlowEvents = null
          }
        },
      })

      return {
        status: 200,
        outcome: "success",
        response: new Response(stream, {
          headers: {
            "content-type": "text/event-stream; charset=utf-8",
            "cache-control": "private, max-age=0, must-revalidate, no-transform",
            connection: "keep-alive",
            "x-accel-buffering": "no",
          },
        }),
      }
    },
  })
}

import { isIP } from "node:net"

const allowPrivateHosts = process.env.GITLAB_ALLOW_PRIVATE_HOSTS === "1"

const isPrivateIpv4 = (hostname: string) => {
  const parts = hostname.split(".").map((part) => Number.parseInt(part, 10))
  if (parts.length !== 4 || parts.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) {
    return true
  }

  const [first, second] = parts
  if (
    first === 10 ||
    first === 127 ||
    first === 0 ||
    (first === 169 && second === 254) ||
    (first === 172 && second >= 16 && second <= 31) ||
    (first === 192 && second === 168) ||
    (first === 100 && second >= 64 && second <= 127) ||
    (first === 198 && (second === 18 || second === 19)) ||
    first >= 224
  ) {
    return true
  }

  return false
}

const isPrivateIpv6 = (hostname: string) => {
  const normalized = hostname.toLowerCase()
  if (normalized === "::" || normalized === "::1") {
    return true
  }

  if (
    normalized.startsWith("fc") ||
    normalized.startsWith("fd") ||
    normalized.startsWith("fe8") ||
    normalized.startsWith("fe9") ||
    normalized.startsWith("fea") ||
    normalized.startsWith("feb") ||
    normalized.startsWith("2001:db8:")
  ) {
    return true
  }

  if (normalized.startsWith("::ffff:")) {
    return isPrivateIpv4(normalized.slice("::ffff:".length))
  }

  return false
}

const isPrivateHostname = (hostname: string) =>
  hostname === "localhost" ||
  hostname.endsWith(".localhost") ||
  hostname.endsWith(".local")

const isPrivateTarget = (hostname: string) => {
  const normalized = hostname.trim().toLowerCase()
  if (!normalized) {
    return true
  }

  const ipKind = isIP(normalized)
  if (ipKind === 4) {
    return isPrivateIpv4(normalized)
  }
  if (ipKind === 6) {
    return isPrivateIpv6(normalized)
  }

  return isPrivateHostname(normalized)
}

export const normalizeGitLabInstanceUrl = (input: string) => {
  const trimmed = input.trim().replace(/\/+$/, "")
  if (!trimmed) {
    throw new Error("GitLab instance URL is required.")
  }

  const withProtocol = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`

  let parsed: URL
  try {
    parsed = new URL(withProtocol)
  } catch {
    throw new Error("GitLab instance URL is invalid.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("GitLab instance URL must use http or https.")
  }
  if (parsed.username || parsed.password) {
    throw new Error("GitLab instance URL must not include credentials.")
  }
  if (!allowPrivateHosts && isPrivateTarget(parsed.hostname)) {
    throw new Error(
      "GitLab instance URL must use a public host. Set GITLAB_ALLOW_PRIVATE_HOSTS=1 to allow private hosts.",
    )
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  return pathname ? `${parsed.origin}${pathname}` : parsed.origin
}

