import { getErrorMessage } from "@/features/onboarding/model/flow.utils"
import { parseJsonResponse } from "@/lib/http/response-json"
import type { Project } from "@/features/onboarding/model/types"

type ConnectIntegrationAndEnableIndexingResult = {
  integrationId: string
  warning?: string
  branch?: string
  planJobId?: string
  reconcileJobId?: string
}

const asRecord = (value: unknown): Record<string, unknown> | null =>
  value && typeof value === "object" ? (value as Record<string, unknown>) : null

const getWarning = (payload: unknown) => {
  const root = asRecord(payload)
  return typeof root?.warning === "string" ? root.warning : ""
}

const getIntegrationId = (payload: unknown) => {
  const root = asRecord(payload)
  const data = asRecord(root?.data)
  return typeof data?.id === "string" && data.id.trim().length > 0 ? data.id : null
}

export const connectIntegrationAndEnableIndexing = async ({
  project,
  normalizedInstance,
  token,
  fetchImpl = fetch,
}: {
  project: Project
  normalizedInstance: string
  token: string
  fetchImpl?: typeof fetch
}): Promise<ConnectIntegrationAndEnableIndexingResult> => {
  const response = await fetchImpl("/api/gitlab/integrations/connect", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      instanceUrl: normalizedInstance,
      ...(token.trim() ? { token: token.trim() } : {}),
      projectId: project.id,
      projectPath: project.path,
      projectName: project.name,
    }),
  })

  const parsedPayload = await parseJsonResponse(response)

const payload = parsedPayload.ok ? parsedPayload.value : null
if (!response.ok) {
  throw new Error(getErrorMessage(payload))
}

const integrationId = getIntegrationId(payload)
if (!integrationId) {
  throw new Error("Connect response is missing integration id.")
}

const warning = getWarning(payload)
if (warning) {
  return { integrationId, warning }
}

const branch = project.defaultBranch?.trim()
if (!branch) {
  return {
    integrationId,
    warning:
      "Webhook active, but indexing was not queued because no default branch was found.",
  }
}

const enableResponse = await fetchImpl(
  `/api/gitlab/integrations/${integrationId}/index/enable`,
  {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({ branch }),
  },
)
const parsedEnablePayload = await parseJsonResponse(enableResponse)
const enablePayload = parsedEnablePayload.ok ? parsedEnablePayload.value : null
if (!enableResponse.ok) {
  return {
    integrationId,
    warning: `Webhook active, but indexing could not be queued. ${getErrorMessage(enablePayload)}`,
  }
}

const enableRoot = asRecord(enablePayload)
const enableData = asRecord(enableRoot?.data)
const job = asRecord(enableData?.job)
const reconcileJob = asRecord(enableData?.reconcileJob)
const resolvedBranch =
  typeof enableData?.branch === "string" && enableData.branch.trim().length > 0
    ? enableData.branch
    : branch

  return {
    integrationId,
    branch: resolvedBranch,
    planJobId: typeof job?.id === "string" ? job.id : undefined,
    reconcileJobId: typeof reconcileJob?.id === "string" ? reconcileJob.id : undefined,
  }
}

import { readFileSync } from "node:fs";
import { isAbsolute, join, relative } from "node:path";
import { globSync } from "node:fs";

const repoRoot = process.cwd();
const srcRoot = join(repoRoot, "src");
const loggerFile = join(srcRoot, "lib", "utils", "logger.ts");

const read = (path) => readFileSync(path, "utf8");
const toAbsolutePath = (path) => (isAbsolute(path) ? path : join(repoRoot, path));
const toRepoRelativePath = (path) => relative(repoRoot, path);
const sensitiveLogKeyRegex =
  /\b(token|password|secret|authorization|cookie|sessionToken|sessionId|apiKey|privateKey|accessKey)\b\s*:/i;

const loggingObjectLiteralRegexes = [
  /(logger\.(set|emit)|appLog\.(info|warn|error|debug))\s*\(\s*\{([\s\S]{0,700}?)\}\s*\)/g,
  /logScopedError\([\s\S]{0,200}?,\s*[\s\S]{0,200}?,\s*\{([\s\S]{0,700}?)\}\s*\)/g,
];

const fail = (label, items) => {
  if (items.length === 0) {
    return;
  }

  console.error(`\n[observability] ${label}`);
  for (const item of items) {
    console.error(`- ${item}`);
  }
};

const findDirectEvlogImports = () => {
  const files = globSync("src/**/*.{ts,tsx,mts,cts}", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const file of files) {
    const absolutePath = toAbsolutePath(file);
    if (absolutePath === loggerFile) {
      continue;
    }

    const source = read(absolutePath);
    if (/from\s+["']evlog["']|require\(\s*["']evlog["']\s*\)/.test(source)) {
      violations.push(toRepoRelativePath(absolutePath));
    }
  }

  return violations;
};

const findConsoleUsage = () => {
  const files = globSync("src/**/*.{ts,tsx,mts,cts}", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const file of files) {
    const absolutePath = toAbsolutePath(file);
    if (absolutePath === loggerFile) {
      continue;
    }

    const source = read(absolutePath);
    if (/\bconsole\.(debug|log|info|warn|error)\b/.test(source)) {
      violations.push(toRepoRelativePath(absolutePath));
    }
  }

  return violations;
};

const findUnwrappedApiRoutes = () => {
  const routes = globSync("src/app/api/**/route.ts", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const route of routes) {
    const absolutePath = toAbsolutePath(route);
    const source = read(absolutePath);
    if (!source.includes("runWithApiRequestLog(")) {
      violations.push(toRepoRelativePath(absolutePath));
    }
  }

  return violations;
};

const findSensitiveLoggingKeys = () => {
  const files = globSync("src/**/*.{ts,tsx,mts,cts}", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const file of files) {
    const absolutePath = toAbsolutePath(file);
    const source = read(absolutePath);

    for (const pattern of loggingObjectLiteralRegexes) {
      pattern.lastIndex = 0;
      let match = pattern.exec(source);
      while (match) {
        const objectText = match[0];
        if (sensitiveLogKeyRegex.test(objectText)) {
          violations.push(toRepoRelativePath(absolutePath));
          break;
        }
        match = pattern.exec(source);
      }
      if (violations[violations.length - 1] === toRepoRelativePath(absolutePath)) {
        break;
      }
    }
  }

  return violations;
};

const directEvlogImports = findDirectEvlogImports();
const consoleUsage = findConsoleUsage();
const unwrappedRoutes = findUnwrappedApiRoutes();
const sensitiveLoggingKeys = findSensitiveLoggingKeys();

fail("Direct evlog imports outside logger entrypoint", directEvlogImports);
fail("console.* usage outside logger entrypoint", consoleUsage);
