    failedCount,
  }
}

const binding = require('../index.js')

function isAbortSignalLike(value) {
  return (
    value != null &&
    typeof value === 'object' &&
    typeof value.aborted === 'boolean' &&
    typeof value.addEventListener === 'function' &&
    typeof value.removeEventListener === 'function'
  )
}

function indexStream(options, stream) {
  const signal = stream?.signal
  if (signal != null && !isAbortSignalLike(signal)) {
    throw new Error('indexStream: stream.signal must be an AbortSignal')
  }

  const handle = binding.createIndexStream(options, stream)
  let done = false
  let removeAbortListener = null

  const out = {
    cancel() {
      if (done) return
      done = true
      if (removeAbortListener) {
        removeAbortListener()
        removeAbortListener = null
      }
      handle.cancel()
    },
    async next() {
      if (done) return { done: true, value: undefined }
      const value = await handle.next()
      if (value == null) {
        done = true
        return { done: true, value: undefined }
      }
      return { done: false, value }
    },
    async return() {
      this.cancel()
      return { done: true, value: undefined }
    },
    async throw(err) {
      this.cancel()
      throw err
    },
    [Symbol.asyncIterator]() {
      return this
    },
  }

  if (signal != null) {
    if (signal.aborted) {
      out.cancel()
    } else {
      const onAbort = () => out.cancel()
      signal.addEventListener('abort', onAbort, { once: true })
      removeAbortListener = () => signal.removeEventListener('abort', onAbort)
    }
  }

  return out
}

