#[derive(Debug, Clone)]
struct GraphArtifacts {
  edges: Vec<EdgeInsert>,
}

#[derive(Debug, Clone)]
struct EdgeInsert {
  source_id: String,
  target_id: String,
  edge_type: String,
  metadata: serde_json::Value,
}

fn build_graph_artifacts(
  files: &[ParsedFile],
  project_root: &Path,
  config: &GraphConfig,
  cancel: &CancelToken,
) -> Result<HashMap<String, GraphArtifacts>, GraphError> {
  cancel.check().map_err(|_| GraphError::Cancelled)?;
  // Build a global symbol index once so per-file passes can resolve references quickly.
  let name_index = build_name_index(files, cancel)?;
  let mut artifacts = HashMap::new();
  let mut context = BuildContext::new(project_root, config);

  for file in files {
    cancel.check().map_err(|_| GraphError::Cancelled)?;
    let mut edges = Vec::new();
    let mut seen_edges = HashSet::new();
    let file_node_id = generate_file_node_id(&file.file_path);

    for chunk in &file.chunks {
      cancel.check().map_err(|_| GraphError::Cancelled)?;
      add_import_edges(chunk, &mut edges, &mut seen_edges, &mut context);
      add_reference_edges(chunk, &mut edges, &mut seen_edges, &name_index, None);
      add_export_edge(chunk, &mut edges, &mut seen_edges);
    }

    add_file_import_edges(
      &file_node_id,
      &file.file_path,
      &file.chunks,
      &mut edges,
      &mut seen_edges,
      &mut context,
    );

    artifacts.insert(file.file_path.clone(), GraphArtifacts { edges });
  }

  Ok(artifacts)
}

fn build_name_index(
  files: &[ParsedFile],
  cancel: &CancelToken,
) -> Result<HashMap<String, Vec<CodeChunk>>, GraphError> {
  let mut index = HashMap::new();
  // Name-based matching is intentionally permissive; disambiguation is handled later with locality heuristics.
  for file in files {
    for chunk in &file.chunks {
      cancel.check().map_err(|_| GraphError::Cancelled)?;
      if let Some(name) = &chunk.name {
        index
          .entry(name.clone())
          .or_insert_with(Vec::new)
          .push(chunk.clone());
      }
    }
  }
  Ok(index)
}

fn add_import_edges(
  chunk: &CodeChunk,
  edges: &mut Vec<EdgeInsert>,
  seen_edges: &mut HashSet<String>,
  context: &mut BuildContext<'_>,
) {
  let imports = chunk
    .metadata
    .as_ref()
    .and_then(|meta| meta.imports.clone())
    .unwrap_or_default();

  for entry in imports {
    let resolution = resolve_cached_module(&entry.module, &chunk.file_path, context);
    let resolved_target = resolution
      .as_ref()
      .map(|path| generate_file_node_id(&normalize_file_path(path, context.project_root)))
      .unwrap_or_else(|| entry.module.clone());

    let key = edge_key(&chunk.id, &resolved_target, "import");
    if seen_edges.contains(&key) {
      continue;
    }
    seen_edges.insert(key);

    edges.push(EdgeInsert {
      source_id: chunk.id.clone(),
      target_id: resolved_target,
      edge_type: "import".to_string(),
      metadata: json!({
        "module": entry.module,
        "symbols": entry.symbols.unwrap_or_default(),
        "resolvedPath": resolution
          .as_ref()
          .map(|path| normalize_file_path(path, context.project_root)),
        "isBuiltin": false,
      }),
    });
  }
}

fn add_reference_edges(
  chunk: &CodeChunk,
  edges: &mut Vec<EdgeInsert>,
  seen_edges: &mut HashSet<String>,
  name_index: &HashMap<String, Vec<CodeChunk>>,
  resolve_name: Option<&ResolveNameFn>,
) {
  let references = chunk
    .metadata
    .as_ref()
    .and_then(|meta| meta.references.clone())
    .unwrap_or_default();

  for reference in references {
    let targets = name_index
      .get(&reference.name)
      .cloned()
      .or_else(|| resolve_name.map(|resolver| resolver(&reference.name)))
      .unwrap_or_default();
    let preferred = targets
      .iter()
      // Prefer same-file targets to reduce cross-file false positives on common names.
      .find(|target| target.file_path == chunk.file_path)
      .cloned()
      .or_else(|| targets.first().cloned());

    let Some(preferred) = preferred else {
      continue;
    };

    let edge_type = match reference.kind {
      crate::core::parse::types::ReferenceKind::Call => "call",
      crate::core::parse::types::ReferenceKind::New => "reference",
    };
    let key = edge_key(&chunk.id, &preferred.id, edge_type);
    if seen_edges.contains(&key) {
      continue;
    }
    seen_edges.insert(key);

    edges.push(EdgeInsert {
      source_id: chunk.id.clone(),
      target_id: preferred.id.clone(),
      edge_type: edge_type.to_string(),
      metadata: json!({
          "name": reference.name,
          "kind": reference.kind,
          "targetFile": preferred.file_path,
      }),
    });
  }
}

fn add_export_edge(
  chunk: &CodeChunk,
  edges: &mut Vec<EdgeInsert>,
  seen_edges: &mut HashSet<String>,
) {
  let exported = chunk
    .metadata
    .as_ref()
    .and_then(|meta| meta.exported)
    .unwrap_or(false);
  let Some(name) = &chunk.name else {
    return;
  };
  if !exported {
    return;
  }
  let key = edge_key(&chunk.id, &chunk.id, "export");
  if seen_edges.contains(&key) {
    return;
  }
  seen_edges.insert(key);

  edges.push(EdgeInsert {
    source_id: chunk.id.clone(),
    target_id: chunk.id.clone(),
    edge_type: "export".to_string(),
    metadata: json!({ "symbol": name }),
  });
}

fn add_file_import_edges(
  file_node_id: &str,
  file_path: &str,
  chunks: &[CodeChunk],
  edges: &mut Vec<EdgeInsert>,
  seen_edges: &mut HashSet<String>,
  context: &mut BuildContext<'_>,
) {
  let imports = collect_file_imports(chunks);
  for entry in imports {
    let resolution = resolve_cached_module(&entry.module, file_path, context);
    let Some(resolved) = resolution else {
      continue;
    };

    let resolved_target =
      generate_file_node_id(&normalize_file_path(&resolved, context.project_root));
    let key = edge_key(file_node_id, &resolved_target, "import");
    if seen_edges.contains(&key) {
      continue;
    }
    seen_edges.insert(key);

    edges.push(EdgeInsert {
      source_id: file_node_id.to_string(),
      target_id: resolved_target,
      edge_type: "import".to_string(),
      metadata: json!({
          "module": entry.module,
          "symbols": entry.symbols.unwrap_or_default(),
          "resolvedPath": normalize_file_path(&resolved, context.project_root),
          "isBuiltin": false,
      }),
    });
  }
}

fn collect_file_imports(chunks: &[CodeChunk]) -> Vec<ImportEntry> {
  // Parsers emit file-level imports on the first relevant chunk for most languages.
  for chunk in chunks {
    let imports = chunk
      .metadata
      .as_ref()
      .and_then(|meta| meta.imports.clone())
      .unwrap_or_default();
    if !imports.is_empty() {
      return imports;
    }
  }
  Vec::new()
}

fn resolve_cached_module(
  specifier: &str,
  importer_path: &str,
  context: &mut BuildContext<'_>,
) -> Option<PathBuf> {
  let base_dir = Path::new(importer_path)
    .parent()
    .map(|path| path.to_path_buf())
    .unwrap_or_else(|| PathBuf::from("."));
  let cache_key = format!("{}::{}", base_dir.display(), specifier);
  // Module resolution is expensive on large graphs; cache by importer dir + raw specifier.
  if let Some(existing) = context.module_cache.get(&cache_key) {
    return Some(existing.clone());
  }

  let mut options = ModuleResolverOptions::default_for(context.project_root.to_path_buf());
  options.base_dir = Some(base_dir);
  options.extensions = context.config.extensions.clone();
  options.alias = context.config.alias.clone();

  if let Some(resolved) = resolve_module_specifier(specifier, &options) {
    context.module_cache.insert(cache_key, resolved.clone());
    return Some(resolved);
  }

  None
}

fn edge_key(source: &str, target: &str, edge_type: &str) -> String {
  format!("{source}::{edge_type}::{target}")
}

fn generate_file_node_id(file_path: &str) -> String {
  format!("ts:file:{file_path}")
}

fn edge_to_graph_edge(edge: EdgeInsert, project_root: &Path) -> GraphEdgeRecord {
  let metadata = normalize_edge_metadata(edge.metadata, project_root);
  GraphEdgeRecord {
    source_id: edge.source_id,
    target_id: edge.target_id,
    edge_type: map_edge_type(&edge.edge_type),
    sources: vec![GraphSource::TreeSitter],
    metadata: Some(metadata.clone()),
    metadata_by_source: Some(HashMap::from([("tree-sitter".to_string(), metadata)])),
  }
}

fn normalize_edge_metadata(metadata: serde_json::Value, project_root: &Path) -> serde_json::Value {
  let mut metadata = metadata;
  if let serde_json::Value::Object(ref mut map) = metadata {
    if let Some(serde_json::Value::String(target_file)) = map.get_mut("targetFile") {
      *target_file = normalize_maybe_path(target_file, project_root);
    }
    if let Some(serde_json::Value::String(resolved_path)) = map.get_mut("resolvedPath") {
      *resolved_path = normalize_maybe_path(resolved_path, project_root);
    }
  }
  metadata
}

fn normalize_maybe_path(value: &str, project_root: &Path) -> String {
  let path = Path::new(value);
  if !path.is_absolute() {
    return value.to_string();
  }
  normalize_file_path(path, project_root)
}

fn normalize_file_path(path: impl AsRef<Path>, project_root: &Path) -> String {
  let path = path.as_ref();
  let normalized = if let Ok(relative) = path.strip_prefix(project_root) {
    relative
  } else {
    path
  };

  let cleaned = clean_path(normalized);
  cleaned.to_string_lossy().replace('\\', "/")
}

fn clean_path(path: &Path) -> PathBuf {
  let mut out = PathBuf::new();
  for component in path.components() {
    match component {
      // Remove "." segments to stabilize node ids across equivalent paths.
      std::path::Component::CurDir => {}
      other => out.push(other.as_os_str()),
    }
  }
  out
}

fn infer_language_from_path(file_path: &str) -> String {
  match file_path
    .split('.')
    .next_back()
    .unwrap_or_default()
    .to_lowercase()
    .as_str()
  {
    "c" | "h" => "c".to_string(),
    "cc" | "cpp" | "cxx" | "c++" | "hpp" | "hh" | "hxx" | "h++" => "cpp".to_string(),
    "java" => "java".to_string(),
    "cs" | "csx" => "csharp".to_string(),
    "adb" | "ads" | "ada" => "ada".to_string(),
    "ts" | "tsx" => "typescript".to_string(),
    "js" | "jsx" => "javascript".to_string(),
    "mjs" | "cjs" => "javascript".to_string(),
    "py" => "python".to_string(),
    "rs" => "rust".to_string(),
    _ => "unknown".to_string(),
  }
}

type ResolveNameFn = dyn Fn(&str) -> Vec<CodeChunk>;

struct BuildContext<'a> {
  project_root: &'a Path,
  config: &'a GraphConfig,
  module_cache: HashMap<String, PathBuf>,
}

impl<'a> BuildContext<'a> {
  fn new(project_root: &'a Path, config: &'a GraphConfig) -> Self {
    Self {
      project_root,
      config,
      module_cache: HashMap::new(),
    }
  }
}

#[cfg(test)]
mod tests {
  use super::*;
  use crate::core::cancel::CancelToken;
  use crate::core::parse::engine::{
    collect_parsed_files, ParseCachePolicy, ParseInputs, ParseOptions,
  };
  use serde::Deserialize;

  #[test]

fn builds_graph_batch_with_file_nodes() {
  let temp = tempfile::tempdir().expect("tempdir");
  let file_path = "src/example.js".to_string();
  let chunk = CodeChunk {
    id: "ts:function:src/example.js:foo:0".to_string(),
    kind: "function".to_string(),
    language: "javascript".to_string(),
    file_path: file_path.clone(),
    name: Some("foo".to_string()),
    range: crate::core::parse::types::Range {
      start: crate::core::parse::types::Position { row: 0, column: 0 },
      end: crate::core::parse::types::Position { row: 1, column: 0 },
    },
    content: Some("function foo() {}".to_string()),
    metadata: None,
  };

  let files = vec![ParsedFile {
    file_path: file_path.clone(),
    chunks: vec![chunk],
    skipped: false,
  }];

  let batch = build_syntax_graph_batch(
    &files,
    temp.path(),
    &GraphConfig::default(),
    &CancelToken::new(),
  )
  .expect("graph batch");
  assert_eq!(batch.layer, GraphLayer::Syntax);
  assert!(batch.nodes.iter().any(|node| node.kind == "file"));
  assert!(!batch.edges.is_empty());
}

#[derive(Deserialize, serde::Serialize)]
struct ExpectedGraph {
  layer: GraphLayer,
  nodes: Vec<GraphNodeRecord>,
  edges: Vec<GraphEdgeRecord>,
}

#[test]

fn matches_ts_graph_fixture() {
  let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
    .join("fixtures")
    .join("mini");
  let expected_path = root.join("expected").join("graph.json");
  let expected_raw = std::fs::read_to_string(expected_path).expect("read expected");
  let mut expected: ExpectedGraph = serde_json::from_str(&expected_raw).expect("parse expected");

  let options = ParseOptions {
    project_root: root.clone(),
    inputs: ParseInputs {
      paths: vec![root.join("src")],
      include: vec!["*.ts".to_string()],
      exclude: Vec::new(),
      respect_gitignore: true,
    },
    batch_size: 256,
  };

  let (parsed_files, _) = collect_parsed_files(
    &options,
    &CancelToken::new(),
    None,
    ParseCachePolicy::default(),
  )
  .expect("parse files");
  let mut batch = build_syntax_graph_batch(
    &parsed_files,
    &root,
    &GraphConfig::default(),
    &CancelToken::new(),
  )
  .expect("graph batch");

  sort_nodes(&mut batch.nodes);
  sort_edges(&mut batch.edges);
  sort_nodes(&mut expected.nodes);
  sort_edges(&mut expected.edges);

  let actual_value = serde_json::to_value(batch).expect("serialize actual");
  let expected_value = serde_json::to_value(expected).expect("serialize expected");
  assert_eq!(actual_value, expected_value);
}

  fn sort_nodes(nodes: &mut [GraphNodeRecord]) {
    nodes.sort_by(|a, b| {
      a.id
        .cmp(&b.id)
        .then(a.kind.cmp(&b.kind))
        .then(range_sort_key(&a.range).cmp(&range_sort_key(&b.range)))
        .then(a.name.cmp(&b.name))
        .then(a.file_path.cmp(&b.file_path))
    });
  }

  fn range_sort_key(range: &Option<crate::core::parse::types::Range>) -> (u8, u32, u32, u32, u32) {
    match range {
      Some(value) => (
        1,
        value.start.row,
        value.start.column,
        value.end.row,
        value.end.column,
      ),
      None => (0, 0, 0, 0, 0),
    }
  }

  fn sort_edges(edges: &mut [GraphEdgeRecord]) {
    edges.sort_by(|a, b| {
      a.source_id
        .cmp(&b.source_id)
        .then(a.edge_type.cmp(&b.edge_type))
        .then(a.target_id.cmp(&b.target_id))
    });
  }
}

