  (connection: Connection) => {
    setEdges((current) => addEdge({ ...connection, style: edgeBaseStyle }, current))
  },
  [setEdges],
)

/* Auto-wire: insert new tool before output, rebuild chain */
const addToolNode = React.useCallback(
  (tool: WorkflowTool) => {

  const nextId = `tool-${tool.id}-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`

  setNodes((current) => {
    /* Position the new tool just left of the output node */
    const outputNode = current.find((n) => n.id === "output")
    const toolNodes = current.filter((n) => n.id.startsWith("tool-"))
    const toolCount = toolNodes.length

    /* Space tools evenly between trigger and output */
    const triggerX = current.find((n) => n.id === "trigger")?.position.x ?? 40
    const outputX = outputNode?.position.x ?? 920
    const gap = (outputX - triggerX) / (toolCount + 2)
    const newX = triggerX + gap * (toolCount + 1)
    const newY = 200 + (toolCount % 2) * 80

    /* Shift the output node right to make room */
    const shiftedOutput = outputNode
      ? { ...outputNode, position: { x: Math.max(outputX, newX + 280), y: outputNode.position.y } }
      : null

    const nextNode: Node = {
      id: nextId,
      type: "workflowTool",
      position: { x: newX, y: newY },
      data: {
        label: tool.name,
        description: tool.description,
        category: tool.category,
      },
    }

    const updated = current.map((n) => (n.id === "output" && shiftedOutput ? shiftedOutput : n))
    return [...updated, nextNode]
  })

  /* Rebuild edges after nodes update */
  setNodes((current) => {
    const chain = getChainOrder(current)
    setEdges(buildChainEdges(chain))
    return current
  })
},

  [setNodes, setEdges],
)

const connectLinearly = React.useCallback(() => {
  const chain = getChainOrder(nodes)
  setEdges(buildChainEdges(chain))
}, [nodes, setEdges])

const selectedNodeId = React.useMemo(
  () => nodes.find((node) => node.selected)?.id ?? null,
  [nodes],
)

/* Remove node and re-stitch the chain */
const removeSelectedNode = React.useCallback(() => {
  if (!selectedNodeId || !selectedNodeId.startsWith("tool-")) {
    return
  }

  setNodes((current) => {
    const next = current.filter((node) => node.id !== selectedNodeId)
    const chain = getChainOrder(next)
    setEdges(buildChainEdges(chain))
    return next
  })
}, [selectedNodeId, setEdges, setNodes])

return (
