            const config = CATEGORY_CONFIG[tool.category]
            const Icon = config.icon
            const isSelected = selectedTool === tool.id

return (
  <div
    key={tool.id}
    role="button"
    tabIndex={0}
    onClick={() => setSelectedTool(tool.id)}
    onKeyDown={(event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault()
        setSelectedTool(tool.id)
      }
    }}
    className={cn(
      "w-full cursor-pointer rounded-xl border p-3 text-left transition-colors hover:border-primary/50",
      isSelected && "border-primary bg-primary/5",
    )}
  >
    <div className="flex items-center justify-between gap-2">
      <div className="flex items-center gap-2">
        <Icon className="size-4 text-muted-foreground" />
        <p className="text-sm font-semibold">{tool.name}</p>
      </div>
      <Badge variant="outline" className={cn("text-[10px]", getCategoryColor(tool.category))}>
        {config.label}
      </Badge>
