    expect(computeAndPersistReviewImpacts).toHaveBeenCalledWith({
      userId: "user-1",
      reviewId: "review-1",
      force: true,
    })
  })

  test("POST maps service not-found errors to 404", async () => {
    const { POST } = await loadRouteModule({ throwNotFoundOnPost: true })

    const response = await POST(new Request("http://localhost/api/review/impact", {
      method: "POST",
      body: JSON.stringify({ reviewId: "review-1", force: false }),
      headers: { "content-type": "application/json" },
    }))
    expect(response.status).toBe(404)
    await expect(response.json()).resolves.toEqual({ error: "Review not found." })
  })
})

