import { describe, expect, test } from "bun:test"

import { shouldSkipPollingRequest } from "@/components/observability/polling"

describe("observability polling helpers", () => {
  test("skips polling when page is hidden", () => {
    expect(
      shouldSkipPollingRequest({
        isVisible: false,
        inFlightRequestKey: null,
      }),
    ).toBe(true)
  })

  test("skips polling while any request is in flight", () => {
    expect(
      shouldSkipPollingRequest({
        isVisible: true,
        inFlightRequestKey: "logs?page=1",
      }),
    ).toBe(true)
  })

  test("allows polling when visible and no in-flight request exists", () => {
    expect(
      shouldSkipPollingRequest({
        isVisible: true,
        inFlightRequestKey: null,
      }),
    ).toBe(false)
  })
})

import Link from "next/link"

import { RootAuth } from "@/components/auth/root-auth"
import { AdminUsersTable } from "@/components/admin/admin-users-table"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { ADMIN_ACCESS_DENIED_MESSAGE, getSessionAdminAccess } from "@/lib/admin-access"
import { listAdminManagedUsers } from "@/lib/admin-users"

export default async function AdminUsersPage() {
  const access = await getSessionAdminAccess()
  const session = access.session

  if (!session?.user?.id) {
    return (
      <div className="flex min-h-dvh items-center justify-center px-4">
        <RootAuth />
      </div>
    )
  }

  if (!access.isAdmin) {
    return (
      <Card className="border-dashed">
        <CardHeader>
          <CardTitle>Admin Access Required</CardTitle>
          <CardDescription>{ADMIN_ACCESS_DENIED_MESSAGE}</CardDescription>
        </CardHeader>
        <CardContent>
          <Button asChild>
            <Link href="/">Back to Dashboard</Link>
          </Button>
        </CardContent>
      </Card>
    )
  }

  const users = await listAdminManagedUsers()

  return (
    <Card>
      <CardHeader>
        <CardTitle>Users</CardTitle>
        <CardDescription>
          Grant or revoke admin permissions for workspace users.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <AdminUsersTable initialUsers={users} currentUserId={session.user.id} />
      </CardContent>
    </Card>
  )
}

import http from 'node:http'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { Indexer } from '../../js/sdk.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..', '..')
const fixtureRoot = path.join(packageRoot, 'fixtures', 'sample-repo')

function startEmbeddingServer(dimension = 3) {
  const server = http.createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/embeddings') {
      res.statusCode = 404
      res.end('not found')
      return
    }

    const body = await new Promise<string>((resolve, reject) => {
      let raw = ''
      req.on('data', (chunk) => (raw += String(chunk)))
      req.on('end', () => resolve(raw))
      req.on('error', reject)
    })

    let inputCount = 1
    try {
      const parsed = JSON.parse(body)
      inputCount = Array.isArray(parsed?.input) ? parsed.input.length : 1
    } catch {
      inputCount = 1
    }

    const embedding = Array.from({ length: dimension }, (_, idx) => (idx + 1) / 10)
    const data = Array.from({ length: inputCount }, () => ({ embedding }))

    res.statusCode = 200
    res.setHeader('content-type', 'application/json')
    res.end(JSON.stringify({ data }))
  })

  return new Promise<{ url: string; close: () => Promise<void> }>((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const address = server.address()
      const port = typeof address === 'object' && address ? address.port : 0
      resolve({
        url: `http://127.0.0.1:${port}`,
        close: () => new Promise((done) => server.close(() => done())),
      })
    })
  })
}

const { url, close } = await startEmbeddingServer(3)

try {
  const ix = new Indexer({ root: fixtureRoot, paths: ['.'], include: ['*.ts'] })
  ix.useVectors({ model: 'test-model', baseUrl: url, dimension: 3, batchSize: 1 })

  for await (const item of ix.stream({ highWaterMark: 16 })) {
