import { decryptIntegrationToken, getUserIntegration } from "@/lib/gitlab/service"
import {
  getGitLabUserInstanceToken,
  markGitLabUserInstanceTokenStale,
  upsertGitLabUserInstanceToken,
} from "@/lib/gitlab/user-token"

import { GitLabDiffServiceError } from "./error"
import {
  type DiffTokenSource,
  type ResolveDiffTokenResult,
} from "./types"

export const resolveTokenForRequest = async ({
  userId,
  instanceUrl,
  requestToken,
  integrationId,
  projectId,
}: {
  userId: string
  instanceUrl: string
  requestToken: string | undefined
  integrationId?: string
  projectId?: string
}): Promise<ResolveDiffTokenResult> => {
  const normalizedRequestToken = requestToken?.trim()
  if (normalizedRequestToken) {
    await upsertGitLabUserInstanceToken({
      userId,
      instanceUrl,
      token: normalizedRequestToken,
    }).catch(() => null)
    return {
      token: normalizedRequestToken,
      source: "request",
    }
  }

  let storedToken = null as Awaited<ReturnType<typeof getGitLabUserInstanceToken>>
  try {
    storedToken = await getGitLabUserInstanceToken(userId, instanceUrl)
  } catch {
    storedToken = null
  }

if (!storedToken) {
  const normalizedIntegrationId = integrationId?.trim()
  const normalizedProjectId = projectId?.trim()

  if (normalizedIntegrationId) {
    const integration = await getUserIntegration(normalizedIntegrationId, userId)
    const matchesScope =
      integration &&
      integration.instanceUrl === instanceUrl &&
      (!normalizedProjectId || integration.projectId === normalizedProjectId)

    if (matchesScope && integration) {
      try {
        const integrationToken = decryptIntegrationToken(integration)
        if (integrationToken.trim()) {
          return {
            token: integrationToken,
            source: "integration",
          }
        }
      } catch {
        // Fall through to required-token error.
      }
    }
  }

  throw new GitLabDiffServiceError(
    "Personal access token is required. Reconnect your GitLab instance.",
    {
      status: 400,
      code: "GITLAB_TOKEN_REQUIRED",
      reconnectRequired: true,
    },
  )
}

if (storedToken.staleAt) {
  throw new GitLabDiffServiceError(
    "Stored GitLab token is stale. Reconnect your GitLab instance.",
    {
      status: 401,
      code: "GITLAB_TOKEN_STALE",
      reconnectRequired: true,
      details: {
        staleAt: storedToken.staleAt.toISOString(),
        staleReason: storedToken.staleReason,
      },
    },
  )
}

return {
  token: storedToken.token,
  source: "stored",
}

}

export const markTokenStaleWhenAuthFails = async ({
  userId,
  instanceUrl,
  tokenSource,
  errorCode,
}: {
  userId: string
  instanceUrl: string
  tokenSource: DiffTokenSource
  errorCode: string
}) => {
  if (tokenSource !== "stored" && tokenSource !== "request") {
    return
  }
  if (errorCode !== "GITLAB_DIFF_UNAUTHORIZED") {
    return
  }

  await markGitLabUserInstanceTokenStale({
    userId,
    instanceUrl,
    reason: "GITLAB_TOKEN_INVALID",
  }).catch(() => null)
}

import { and, eq, ne, sql } from 'drizzle-orm'

import { db } from '@/lib/db'
import { indexFileStates, indexVectors } from '@/lib/db/schema'
import { INDEX_VECTOR_DIMENSION } from '@argus/contracts-indexing'
import type { VectorQueryCandidate, VectorStore } from '@argus/contracts-indexing'

const normalizeEmbedding = (embedding: number[]) => {
  if (embedding.length !== INDEX_VECTOR_DIMENSION) {
    throw new Error(
      `Embedding dimension mismatch. Expected ${INDEX_VECTOR_DIMENSION}, received ${embedding.length}.`,
    )
  }

  const values = embedding.map((value) => {
    if (!Number.isFinite(value)) {
      throw new Error('Embedding contains non-finite values.')
    }
    return Number(value.toFixed(8))
  })

  return `[${values.join(',')}]`
}

const parseCandidate = (row: Record<string, unknown>): VectorQueryCandidate => ({
  path: String(row.path),
  fileId: String(row.fileId),
  runId: String(row.runId),
  chunkIndex: Number(row.chunkIndex),
  score: Number(row.score),
  content: typeof row.content === 'string' ? row.content : '',
})

const computeHnswEfSearch = (effectiveLimit: number) =>
  Math.max(40, Math.min(1_000, effectiveLimit * 4))

export class PostgresVectorStore implements VectorStore {

async upsertChunks(args: {
  branchStateId: string
  runId: string
  path: string
  fileId: string
  chunks: Array<{
    chunkIndex: number
    chunkId: string
    content: string
    embedding: number[]
    metadata: Record<string, unknown>
  }>
}): Promise<void> {
  if (args.chunks.length === 0) {
    return
  }

  const now = new Date()

  await db
    .insert(indexVectors)
    .values(
      args.chunks.map((chunk) => ({
        branchStateId: args.branchStateId,
        runId: args.runId,
        path: args.path,
        fileId: args.fileId,
        chunkIndex: chunk.chunkIndex,
        chunkId: chunk.chunkId,
        content: chunk.content,
        embedding: chunk.embedding,
        metadata: chunk.metadata,
        createdAt: now,
        updatedAt: now,
      })),
    )
    .onConflictDoUpdate({
      target: [
        indexVectors.branchStateId,
        indexVectors.path,
        indexVectors.fileId,
        indexVectors.chunkIndex,
      ],
      set: {
        runId: args.runId,
        chunkId: sql`excluded.chunk_id`,
        content: sql`excluded.content`,
        embedding: sql`excluded.embedding`,
        metadata: sql`excluded.metadata`,
        updatedAt: now,
      },
    })
}

async queryCandidates(args: {
  branchStateId: string
  embedding: number[]
  limit: number
  oversample?: number
}): Promise<VectorQueryCandidate[]> {
  const oversample = Math.max(1, Math.floor(args.oversample ?? 5))
  const limit = Math.max(1, Math.floor(args.limit))
  const effectiveLimit = Math.min(1_000, limit * oversample)
  const queryVector = normalizeEmbedding(args.embedding)
  const efSearch = computeHnswEfSearch(effectiveLimit)

  return db.transaction(async (tx) => {
    await tx.execute(sql`set local hnsw.ef_search = ${efSearch}`)

    const result = await tx.execute(sql`
      select
        ${indexVectors.path} as "path",
        ${indexVectors.fileId} as "fileId",
        ${indexVectors.runId} as "runId",
        ${indexVectors.chunkIndex} as "chunkIndex",
        (1 - (${indexVectors.embedding} <=> ${queryVector}::vector)) as "score",
        ${indexVectors.content} as "content"
      from ${indexVectors}
      inner join ${indexFileStates}
        on ${indexFileStates.branchStateId} = ${indexVectors.branchStateId}
       and ${indexFileStates.path} = ${indexVectors.path}
       and ${indexFileStates.fileId} = ${indexVectors.fileId}
      where ${indexVectors.branchStateId} = ${args.branchStateId}
      order by ${indexVectors.embedding} <=> ${queryVector}::vector asc
      limit ${effectiveLimit}
    `)

    return result.rows.map((raw) => parseCandidate(raw as Record<string, unknown>))
  })
}

  async deleteStaleByPath(args: {
    branchStateId: string
    path: string
    keepFileId: string | null
  }): Promise<void> {
    if (args.keepFileId === null) {
      await db
        .delete(indexVectors)
        .where(
          and(
            eq(indexVectors.branchStateId, args.branchStateId),
            eq(indexVectors.path, args.path),
          ),
        )
      return
    }

    await db
      .delete(indexVectors)
      .where(
        and(
          eq(indexVectors.branchStateId, args.branchStateId),
          eq(indexVectors.path, args.path),
          ne(indexVectors.fileId, args.keepFileId),
        ),
      )
  }
}

export const createPostgresVectorStore = () => new PostgresVectorStore()

