use std::thread;

use napi::bindgen_prelude::Object;
use napi::{Error, Result};
use napi_derive::napi;

use crate::core::index_engine::{IndexEngine, IndexSink};
use crate::core::stream::{StreamError, StreamQueue};

use super::bindings::parse_index_options_core;

#[derive(Debug, Clone)]
struct StreamEmitOptions {
  parse_batches: bool,
  graph_batches: bool,
  vector_batches: bool,
  scip_batches: bool,
  phase_events: bool,
}

#[derive(Debug, Clone)]
struct ParsedStreamOptions {
  high_water_mark: usize,
  emit: StreamEmitOptions,
}

fn apply_hook_batch_overrides(
  index_options: &mut crate::core::index_engine::IndexOptions,
  options: &Object<'_>,
) -> Result<()> {
  let hooks = options.get::<Object<'_>>("hooks")?;
  if let Some(hooks) = hooks.as_ref() {
    if let Some(value) = hooks.get::<u32>("parseBatch")? {
      index_options.parse_batch = value as usize;
    }
    if let Some(value) = hooks.get::<u32>("graphBatch")? {
      index_options.graph_batch = value as usize;
    }
    if let Some(value) = hooks.get::<u32>("vectorBatch")? {
      index_options.vector.batch_size = value as usize;
    }
    if let Some(value) = hooks.get::<u32>("scipBatch")? {
      index_options.scip_batch = value as usize;
    }
  }
  Ok(())
}

fn parse_stream_options(
  options: &crate::core::index_engine::IndexOptions,
  stream: Option<Object<'_>>,
) -> Result<ParsedStreamOptions> {
  let mut high_water_mark = 16usize;
  let mut emit_parse_batches = false;
  let mut emit_graph_batches = options.phases.graph;
  let mut emit_vector_batches = options.phases.vector;
  let mut emit_scip_batches = options.phases.scip;
  let mut emit_phase_events = true;

  if let Some(stream) = stream {
    if let Some(value) = stream.get::<u32>("highWaterMark")? {
      high_water_mark = value.max(1) as usize;
    }
    if let Some(emit) = stream.get::<Object<'_>>("emit")? {
      if let Some(value) = emit.get::<bool>("parseBatches")? {
        emit_parse_batches = value;
      }
      if let Some(value) = emit.get::<bool>("graphBatches")? {
        emit_graph_batches = value;
      }
      if let Some(value) = emit.get::<bool>("vectorBatches")? {
        emit_vector_batches = value;
      }
      if let Some(value) = emit.get::<bool>("scipBatches")? {
        emit_scip_batches = value;
      }
      if let Some(value) = emit.get::<bool>("phaseEvents")? {
        emit_phase_events = value;
      }
    }
  }

  Ok(ParsedStreamOptions {
    high_water_mark,
    emit: StreamEmitOptions {
      parse_batches: emit_parse_batches,
      graph_batches: emit_graph_batches,
      vector_batches: emit_vector_batches,
      scip_batches: emit_scip_batches,
      phase_events: emit_phase_events,
    },
  })
}

struct StreamSink {
  queue: StreamQueue,
  emit: StreamEmitOptions,
}

impl StreamSink {
  fn push_json(&self, value: serde_json::Value) {
    let _ = self.queue.push_blocking(value);
  }
}

impl crate::core::parse::engine::ParseSink for StreamSink {
  fn on_parse_batch_ref(&mut self, batch: &[crate::core::parse::types::CodeChunk]) {
    if !self.emit.parse_batches {
      return;
    }
    match serde_json::to_value(batch) {
      Ok(chunks) => self.push_json(serde_json::json!({ "type": "parse:batch", "chunks": chunks })),
      Err(err) => self.queue.close(Some(err.to_string())),
    }
  }
}

impl crate::core::graph::engine::GraphSink for StreamSink {
  fn on_graph_batch(&mut self, batch: crate::core::graph::types::GraphBatch) {
    if !self.emit.graph_batches {
      return;
    }
    match serde_json::to_value(batch) {
      Ok(value) => self.push_json(serde_json::json!({ "type": "graph:batch", "batch": value })),
      Err(err) => self.queue.close(Some(err.to_string())),
    }
  }
}

impl crate::core::vector::engine::VectorSink for StreamSink {
  fn on_vector_batch(&mut self, batch: crate::core::vector::types::VectorBatch) {
    if !self.emit.vector_batches {
      return;
    }
    match serde_json::to_value(batch) {
      Ok(value) => self.push_json(serde_json::json!({ "type": "vector:batch", "batch": value })),
      Err(err) => self.queue.close(Some(err.to_string())),
    }
  }
}

impl crate::core::scip::engine::ScipSink for StreamSink {
  fn on_scip_batch(&mut self, batch: crate::core::graph::types::GraphBatch) {
    if !self.emit.scip_batches {
      return;
    }
    match serde_json::to_value(batch) {
      Ok(value) => self.push_json(serde_json::json!({ "type": "scip:batch", "batch": value })),
      Err(err) => self.queue.close(Some(err.to_string())),
    }
  }
}

impl IndexSink for StreamSink {
  fn on_event(&mut self, event: crate::core::index_engine::IndexEvent) {
    if !self.emit.phase_events {
      return;
    }
    self.push_json(event.to_json());
  }
}

#[napi]
pub struct IndexStreamHandle {
  queue: StreamQueue,
}

#[napi]
impl IndexStreamHandle {
  #[napi]
  pub fn cancel(&self) {
    self.queue.cancel();
  }

  #[napi]
  pub async fn next(&self) -> Result<Option<serde_json::Value>> {
    let queue = self.queue.clone();
    let next = napi::tokio::task::spawn_blocking(move || queue.next_blocking())
      .await
      .map_err(|err| Error::from_reason(format!("stream next task failed: {err}")))??;
    Ok(next)
  }
}

impl Drop for IndexStreamHandle {
  fn drop(&mut self) {
    self.queue.cancel();
  }
}

#[napi(js_name = "createIndexStream")]

pub fn create_index_stream(
  options: Object<'_>,
  stream: Option<Object<'_>>,
) -> Result<IndexStreamHandle> {
  let mut index_options = parse_index_options_core(&options)?;
  apply_hook_batch_overrides(&mut index_options, &options)?;
  let stream_options = parse_stream_options(&index_options, stream)?;

  if stream_options.emit.vector_batches {
    index_options.vector.include_chunk = true;
  }

  let queue = StreamQueue::new(stream_options.high_water_mark);
  let cancel = queue.cancel_token();
  let mut sink = StreamSink {
    queue: queue.clone(),
    emit: stream_options.emit,
  };
  let close_queue = queue.clone();

  thread::spawn(move || {
    let engine = IndexEngine::new(index_options);
    let result = engine.run(&mut sink, &cancel);
    match result {
      Ok(_) => close_queue.close(None),
      Err(err) => close_queue.close(Some(err.to_string())),
    }
  });

  Ok(IndexStreamHandle { queue })
}

impl From<StreamError> for Error {
  fn from(value: StreamError) -> Self {
    match value {
      StreamError::Cancelled => Error::from_reason("cancelled"),
      StreamError::Closed => Error::from_reason("closed"),
      StreamError::Fatal(message) => Error::from_reason(message),
    }
  }
}

