import { NextResponse } from "next/server"

import {
  createMergeRequestDiscussion,
  MergeRequestDiscussionError,
} from "@/lib/gitlab/merge-request-discussions"

import { buildRouteError, type GitLabApiClient } from "./api-client"
import {
  type GitLabAction,
  type GitLabCurrentUser,
  type GitLabDiscussionSide,
  type GitLabProjectPayload,
  type GitLabProxyRouteResult,
  type GitLabRouteLogger,
  type MergeRequest,
  type Project,
} from "./types"

const MERGE_REQUESTS_PER_PAGE_DEFAULT = 5
const MERGE_REQUESTS_PER_PAGE_MAX = 100
const PROJECTS_PER_PAGE_DEFAULT = 5
const PROJECTS_PER_PAGE_MAX = 100

const SUPPORTED_GITLAB_ACTIONS = new Set<GitLabAction>([
  "projects",
  "merge-requests",
  "merge-request",
  "create-merge-request-discussion",
  "update-merge-request-description",
  "validate-token",
  "recent-merge-requests",
])

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const normalizeDiscussionBody = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

const parseMergeRequestDescription = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  return value
}

const normalizeDiscussionLine = (value: unknown) => {
  if (typeof value !== "number" || Number.isNaN(value)) {
    return null
  }

  const normalized = Math.floor(value)
  if (normalized < 1) {
    return null
  }
  return normalized
}

const normalizeDiscussionSide = (value: unknown): GitLabDiscussionSide | null => {
  if (value === "additions" || value === "deletions") {
    return value
  }
  return null
}

const normalizeDiscussionPath = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "")
}

const normalizePerPage = (value: unknown, fallback: number, max: number) => {
  if (typeof value !== "number" || Number.isNaN(value)) {
    return fallback
  }

  const normalized = Math.floor(value)
  return Math.min(max, Math.max(1, normalized))
}

const normalizeGitLabUser = (value: unknown): GitLabCurrentUser => {
  const root = asRecord(value)
  if (!root) {
    return {
      id: null,
      username: null,
      name: null,
    }
  }

  return {
    id:
      typeof root.id === "number" && Number.isFinite(root.id) ? root.id : null,
    username:
      typeof root.username === "string" && root.username.trim().length > 0
        ? root.username.toLowerCase()
        : null,
    name:
      typeof root.name === "string" && root.name.trim().length > 0
        ? root.name.toLowerCase()
        : null,
  }
}

const isSameGitLabUser = (candidate: unknown, currentUser: GitLabCurrentUser) => {
  const root = asRecord(candidate)
  if (!root) {
    return false
  }

  if (
    currentUser.id !== null &&
    typeof root.id === "number" &&
    root.id === currentUser.id
  ) {
    return true
  }

  const username =
    typeof root.username === "string" && root.username.trim().length > 0
      ? root.username.toLowerCase()
      : null
  if (username && currentUser.username && username === currentUser.username) {
    return true
  }

  const name =
    typeof root.name === "string" && root.name.trim().length > 0
      ? root.name.toLowerCase()
      : null

  return Boolean(name && currentUser.name && name === currentUser.name)
}

