const handleProjectsAction = async ({
  payload,
  instanceUrl,
  token,
  logger,
  client,
}: GitLabActionHandlerInput): Promise<GitLabProxyRouteResult> => {
  const perPage = normalizePerPage(
    payload.perPage,
    PROJECTS_PER_PAGE_DEFAULT,
    PROJECTS_PER_PAGE_MAX,
  )
  const forceRefresh = payload.forceRefresh === true
  const forceRefreshInvalidatedEntries = forceRefresh
    ? client.invalidateGitLabProjectListCache({
        instanceUrl,
        token,
      })
    : 0
  const normalizedSearch = payload.search?.trim() ?? ""
  const useSearch = normalizedSearch.length >= 3

const searchParam = useSearch
  ? `&search=${encodeURIComponent(normalizedSearch)}`
  : ""
const projectsApiPath = `/api/v4/projects?membership=true&simple=true&per_page=${perPage}${searchParam}`

const responseData = await client.getCachedGitLabJson<Array<Record<string, unknown>>>({
  instanceUrl,
  token,
  action: "projects",
  forceRefresh,
  apiPath: projectsApiPath,
})

const toLastActivityAtTimestamp = (value: unknown) => {
  if (typeof value !== "string" || value.trim().length === 0) {
    return 0
  }
  const parsed = Date.parse(value)
  return Number.isFinite(parsed) ? parsed : 0
}

const projectRows = responseData
  .filter(
    (item): item is Record<string, unknown> =>
      Boolean(item) && typeof item === "object",
  )
  .sort((left, right) => {
    const rightActivity = toLastActivityAtTimestamp(right.last_activity_at)
    const leftActivity = toLastActivityAtTimestamp(left.last_activity_at)
    if (rightActivity !== leftActivity) {
      return rightActivity - leftActivity
    }

    // Stable tie-breaker keeps ordering deterministic across equal activity timestamps.
    return String(right.id ?? "").localeCompare(String(left.id ?? ""))
  })

}

