export const isSupportedGitLabAction = (
  action: unknown,
): action is GitLabAction =>
  typeof action === "string" &&
  SUPPORTED_GITLAB_ACTIONS.has(action as GitLabAction)

export const handleGitLabAction = async (
  input: GitLabActionHandlerInput,
): Promise<GitLabProxyRouteResult> => {
  if (input.payload.action === "validate-token") {
    return await handleValidateTokenAction(input)
  }
  if (input.payload.action === "projects") {
    return await handleProjectsAction(input)
  }
  if (input.payload.action === "recent-merge-requests") {
    return await handleRecentMergeRequestsAction(input)
  }
  if (input.payload.action === "merge-requests") {
    return await handleMergeRequestsAction(input)
  }
  if (input.payload.action === "merge-request") {
    return await handleMergeRequestAction(input)
  }
  if (input.payload.action === "create-merge-request-discussion") {
    return await handleCreateMergeRequestDiscussionAction(input)
  }
  if (input.payload.action === "update-merge-request-description") {
    return await handleUpdateMergeRequestDescriptionAction(input)
  }

  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "Unsupported action." },
      { status: 400 },
    ),
  }
}

export type ReviewFeedbackValue = "up" | "down"

export type ReviewCommentFeedbackKeyInput = {
  file: string
  side: "additions" | "deletions"
  line: number
  title: string
}

const MAX_COMMENT_KEY_LENGTH = 512

const normalizePatchPath = (value: string) =>
  value
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "")

const normalizeTitle = (value: string) => value.trim().replace(/\s+/g, " ").toLowerCase()

export const buildReviewCommentFeedbackKey = ({
  file,
  side,
  line,
  title,
}: ReviewCommentFeedbackKeyInput) => {
  const safeLine = Number.isFinite(line) ? Math.max(1, Math.floor(line)) : 1
  return `${normalizePatchPath(file)}:${side}:${safeLine}:${normalizeTitle(title)}`
}

export const normalizeReviewCommentFeedbackKey = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  const normalized = value.trim()
  if (!normalized || normalized.length > MAX_COMMENT_KEY_LENGTH) {
    return ""
  }
  return normalized
}

export const isReviewFeedbackValue = (value: unknown): value is ReviewFeedbackValue =>
  value === "up" || value === "down"

const parseNodeLine = (value: unknown): GraphNode | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  const record = value as Record<string, unknown>
  const id = toOptionalString(record.id)
  const kind = toOptionalString(record.kind)
  if (!id || !kind) {
    return null
  }

  return {
    id,
    kind,
    name: toOptionalString(record.name),
    filePath: toOptionalString(record.filePath),
    range: isGraphRange(record.range)
      ? {
          start: {
            row: Math.floor(record.range.start.row),
            column: Math.floor(record.range.start.column),
          },
          end: {
            row: Math.floor(record.range.end.row),
            column: Math.floor(record.range.end.column),
          },
        }
      : null,
  }
}

const parseEdgeLine = (value: unknown): GraphEdge | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  const record = value as Record<string, unknown>
  const sourceId = toOptionalString(record.sourceId)
  const targetId = toOptionalString(record.targetId)
  const type = toOptionalString(record.type)
  if (!sourceId || !targetId || !type) {
    return null
  }

  return {
    sourceId,
    targetId,
    type,
  }
}

const parseJsonLine = (line: string): unknown => {
  try {
    return JSON.parse(line)
  } catch {
    return null
  }
}

const readJsonl = async <T>(filePath: string, parse: (value: unknown) => T | null) => {
  const records: T[] = []
  const stream = createReadStream(filePath, { encoding: "utf8" })
  const rl = createInterface({ input: stream, crlfDelay: Infinity })

  try {
    for await (const line of rl) {
      const trimmed = line.trim()
      if (!trimmed) {
        continue
      }
      const parsed = parse(parseJsonLine(trimmed))
      if (parsed) {
        records.push(parsed)
      }
    }
  } finally {
    rl.close()
    stream.destroy()
  }

  return records
}

const parseJsonlText = <T>(raw: string, parse: (value: unknown) => T | null) => {
  const records: T[] = []
  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim()
    if (!trimmed) {
      continue
    }
    const parsed = parse(parseJsonLine(trimmed))
    if (parsed) {
      records.push(parsed)
    }
  }
  return records
}

const buildGraphStore = (nodes: GraphNode[], edges: GraphEdge[]): GraphStore => {
  const nodesById = new Map<string, GraphNode>()
  const nodesByFilePath = new Map<string, GraphNode[]>()
  for (const node of nodes) {
    nodesById.set(node.id, node)
    if (!node.filePath) {
      continue
    }
    const normalizedPath = normalizePath(node.filePath)
    const current = nodesByFilePath.get(normalizedPath) ?? []
    current.push(node)
    nodesByFilePath.set(normalizedPath, current)
  }

  const outgoing = new Map<string, GraphEdge[]>()
  const incoming = new Map<string, GraphEdge[]>()
  for (const edge of edges) {
    const currentOutgoing = outgoing.get(edge.sourceId) ?? []
    currentOutgoing.push(edge)
    outgoing.set(edge.sourceId, currentOutgoing)

    const currentIncoming = incoming.get(edge.targetId) ?? []
    currentIncoming.push(edge)
    incoming.set(edge.targetId, currentIncoming)
  }

  return {
    nodesById,
    nodesByFilePath,
    outgoing,
    incoming,
  }
}

export const loadGraphStoreFromSnapshot = async (args: {
  snapshot: GraphImpactSnapshotReady
  artifactStore: GraphArtifactStoreReader | null
}): Promise<GraphStore> => {
  const { snapshot, artifactStore } = args

  const [nodes, edges] = await (async () => {
    if (snapshot.nodesPath && snapshot.edgesPath) {
      return Promise.all([
        readJsonl(snapshot.nodesPath, parseNodeLine),
        readJsonl(snapshot.edgesPath, parseEdgeLine),
      ])
    }

    const artifactsPrefix = toOptionalString(snapshot.artifactStorePrefix)
    const nodesFilename = toOptionalString(snapshot.artifactStoreNodesFilename)
    const edgesFilename = toOptionalString(snapshot.artifactStoreEdgesFilename)
    if (!artifactsPrefix || !nodesFilename || !edgesFilename) {
      throw new Error("Snapshot does not include graph nodes/edges paths.")
    }
    if (!artifactStore) {
      throw new Error("Graph artifact store reader is not configured.")
    }

    const [nodesRaw, edgesRaw] = await Promise.all([
      artifactStore.readTextFile({
        artifactsPrefix,
        filename: nodesFilename,
      }),
      artifactStore.readTextFile({
        artifactsPrefix,
        filename: edgesFilename,
      }),
    ])
    return [
      parseJsonlText(nodesRaw, parseNodeLine),
      parseJsonlText(edgesRaw, parseEdgeLine),
    ] as const
  })()

  return buildGraphStore(nodes, edges)
}

