import { NextResponse } from "next/server"
import { z } from "zod"

import { getUserIntegration } from "@/lib/gitlab/service"
import { requireJsonBodyOrEmpty } from "@/lib/http/request-json"
import { ensureMergeRequestSourceBranchIndexing } from "@/lib/indexing/mr-auto-index"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const payloadSchema = z.object({
  mergeRequestIid: z.string().trim().min(1),
})

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params

  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/index/ensure-mr`,
    event: "api.gitlab.index.ensure_mr",
    context: { integrationId },
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBodyOrEmpty(request, "Invalid ensure-mr payload."),
      ])

      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const integration = await getUserIntegration(integrationId, userId)
      if (!integration) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
        }
      }

      if (integration.status === "disabled") {
        return {
          status: 409,
          outcome: "conflict",
          response: NextResponse.json({ error: "Integration is disabled." }, { status: 409 }),
        }
      }

      if (!body.ok) return body.result

      const parsed = payloadSchema.safeParse(body.value)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid ensure-mr payload." }, { status: 400 }),
        }
      }

      const result = await ensureMergeRequestSourceBranchIndexing({
        integrationId: integration.id,
        mergeRequestIid: parsed.data.mergeRequestIid,
        trigger: "lazy",
      })

      logger.set({
        mergeRequestIid: parsed.data.mergeRequestIid,
        decision: result.decision,
        reason: result.reason,
        branch: result.branch,
        headSha: result.headSha,
        queuedJobId: result.job?.id ?? null,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: result }),
      }
    },
  })
}

