type DiffManifestFile = {
  fileId: string
  contentState: DiffFileContentState
}

type DiffManifestDetails = {
  mode: DiffManifestMode
  files: DiffManifestFile[]
  webUrl: string
}

const toDiffManifestMode = (value: unknown): DiffManifestMode => {
  if (
    value === "full" ||
    value === "large_diff_mode" ||
    value === "external_review_required"
  ) {
    return value
  }
  return "full"
}

const toDiffFileContentState = (value: unknown): DiffFileContentState => {
  if (value === "available" || value === "truncated" || value === "requires_external") {
    return value
  }
  return "available"
}

const parseDiffManifest = (payload: DiffManifestPayload | null): DiffManifestDetails | null => {
  const root = payload?.data
  if (!root || !Array.isArray(root.files) || !root.mergeRequest) {
    return null
  }

  const files = root.files.flatMap((file): DiffManifestFile[] => {
    if (!file || typeof file !== "object") {
      return []
    }
    const fileId = typeof file.fileId === "string" ? file.fileId.trim() : ""
    if (!fileId) {
      return []
    }
    return [
      {
        fileId,
        contentState: toDiffFileContentState(file.contentState),
      },
    ]
  })

  const webUrl =
    typeof root.mergeRequest.webUrl === "string" ? root.mergeRequest.webUrl.trim() : ""

  return {
    mode: toDiffManifestMode(root.mode),
    files,
    webUrl,
  }
}

const toEnsureDecision = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }

  if (
    value === "queued" ||
    value === "already_ready" ||
    value === "already_pending" ||
    value === "skipped" ||
    value === "error"
  ) {
    return value
  }

  return null
}

type MergeRequestMetadataPayload = {
  data?: {
    sourceBranch?: unknown
    targetBranch?: unknown
  }
}

const toNonEmptyTrimmedString = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

const loadPatchFromManifest = async ({
  instanceUrl,
  token,
  integrationId,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string
  token: string
  integrationId?: string
  projectId: string
  mergeRequestIid: string
}) => {
  const manifestResponse = await fetch("/api/gitlab/diff/manifest", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      accept: "application/json",
    },
    body: JSON.stringify({
      instanceUrl,
      token,
      ...(integrationId ? { integrationId } : {}),
      projectId,
      mergeRequestIid,
    }),
  })
  const parsedManifestPayload = await parseJsonResponse(manifestResponse)
  const manifestPayload = parsedManifestPayload.ok
    ? (parsedManifestPayload.value as DiffManifestPayload)
    : null
  if (!manifestResponse.ok) {
    throw new Error(getErrorMessage(manifestPayload))
  }

  const manifest = parseDiffManifest(manifestPayload)
  if (!manifest) {
    throw new Error("Unexpected diff manifest response from server.")
  }

const renderableFiles = manifest.files.filter((file) => file.contentState !== "requires_external")
const requiresExternalCount = manifest.files.length - renderableFiles.length

if (renderableFiles.length === 0) {
  if (manifest.mode === "external_review_required" && manifest.webUrl) {
    throw new Error(`Diff is too large for in-app rendering. Open in GitLab: ${manifest.webUrl}`)
  }
  throw new Error("Merge request has no diff content to render.")
}

let truncatedCount = 0
const patchChunks: string[] = []

for (const file of renderableFiles) {
  let nextCursor: string | undefined
  let done = false
  const filePatchChunks: string[] = []

  while (!done) {
    const fileResponse = await fetch("/api/gitlab/diff/file", {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "application/json",
      },
      body: JSON.stringify({
        instanceUrl,
        token,
        ...(integrationId ? { integrationId } : {}),
        projectId,
        mergeRequestIid,
        fileId: file.fileId,
        ...(nextCursor ? { cursor: nextCursor } : {}),
      }),
    })
    const parsedFilePayload = await parseJsonResponse(fileResponse)
    const filePayload = parsedFilePayload.ok
      ? (parsedFilePayload.value as DiffFilePayload)
      : null
    if (!fileResponse.ok) {
      throw new Error(getErrorMessage(filePayload))
    }
    const data = filePayload?.data
    if (!data || !Array.isArray(data.chunks)) {
      throw new Error("Unexpected diff file response from server.")
    }
    for (const chunk of data.chunks) {
      if (typeof chunk === "string") {
        filePatchChunks.push(chunk)
      }
    }
    if (data.truncated === true) {
      truncatedCount += 1
    }
    done = data.done === true
    nextCursor = typeof data.nextCursor === "string" ? data.nextCursor : undefined
  }

  patchChunks.push(filePatchChunks.join(""))
}

const patch = patchChunks.join("\n\n")
let statusMessage = ""

  if (manifest.mode === "external_review_required") {
    statusMessage =
      requiresExternalCount > 0
        ? `${requiresExternalCount} file(s) require external review in GitLab.`
        : "Diff exceeds in-app limits. Review in GitLab."
  } else if (requiresExternalCount > 0 || truncatedCount > 0) {
    statusMessage = `Large diff mode: ${requiresExternalCount} file(s) external, ${truncatedCount} file(s) truncated.`
  }

  return {
    patch,
    source: toDiffDataSource("manifest"),
    statusMessage,
  }
}

