use std::collections::HashSet;
use std::path::{Path, PathBuf};

use globset::{Glob, GlobSet, GlobSetBuilder};

#[derive(Debug, Clone)]
pub struct FileDiscoveryOptions {
  pub base_path: PathBuf,
  pub include_patterns: Vec<String>,
  pub exclude_patterns: Vec<String>,
  pub respect_gitignore: bool,
}

impl Default for FileDiscoveryOptions {
  fn default() -> Self {
    Self {
      base_path: PathBuf::new(),
      include_patterns: Vec::new(),
      exclude_patterns: Vec::new(),
      respect_gitignore: true,
    }
  }
}

#[derive(Debug)]
pub enum FileDiscoveryError {
  InvalidGlobPattern { pattern: String, message: String },
}

impl std::fmt::Display for FileDiscoveryError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      FileDiscoveryError::InvalidGlobPattern { pattern, message } => {
        write!(f, "invalid file pattern {pattern:?}: {message}")
      }
    }
  }
}

impl std::error::Error for FileDiscoveryError {}

#[derive(Debug, Default, Clone)]
struct CompiledPatterns {
  include: Option<GlobSet>,
  exclude_globs: Option<GlobSet>,
  exclude_substrings: Vec<String>,
  exclude_names: HashSet<String>,
}

impl CompiledPatterns {
  fn compile(options: &FileDiscoveryOptions) -> Result<Self, FileDiscoveryError> {
    let include = compile_include_patterns(&options.include_patterns)?;
    let (exclude_globs, exclude_substrings, exclude_names) =
      compile_exclude_patterns(&options.exclude_patterns)?;

    Ok(Self {
      include,
      exclude_globs,
      exclude_substrings,
      exclude_names,
    })
  }

  fn is_excluded(&self, entry_name: &str, relative_path: &str) -> bool {
    if self.exclude_names.contains(entry_name) {
      return true;
    }
    if self
      .exclude_substrings
      .iter()
      .any(|pattern| relative_path.contains(pattern))
    {
      return true;
    }
    if let Some(globs) = &self.exclude_globs {
      if globs.is_match(relative_path) {
        return true;
      }
    }
    false
  }

  fn is_included(&self, relative_path: &str) -> bool {
    let Some(include) = &self.include else {
      return true;
    };
    include.is_match(relative_path)
  }
}

pub fn find_files(options: &FileDiscoveryOptions) -> Result<Vec<PathBuf>, FileDiscoveryError> {
  let compiled = CompiledPatterns::compile(options)?;
  let mut files = Vec::new();

  let base_path = options.base_path.clone();
  let mut walker = ignore::WalkBuilder::new(&base_path);

walker
  // Keep historical behavior: don't ignore dotfiles unless the user excludes them.
  .hidden(false)
  // Only respect git ignore rules (and only when inside a git repo).
  .ignore(false)
  .git_ignore(options.respect_gitignore)
  // Avoid non-deterministic machine-level ignores by default.
  .git_global(false)
  .git_exclude(options.respect_gitignore)
  .parents(true)
  .require_git(true)
  .follow_links(false)
  .filter_entry({
    let base_path = base_path.clone();
    let compiled = compiled.clone();
    move |entry| {
      let Some(ft) = entry.file_type() else {
        return true;
      };
      if !ft.is_dir() {
        return true;
      }

      let name = entry
        .path()
        .file_name()
        .map(|v| v.to_string_lossy())
        .unwrap_or_default();

      if name == ".git" {
        return false;
      }

      let relative = relative_path(&base_path, entry.path());
      !compiled.is_excluded(&name, &relative)
    }
  });

  for entry in walker.build() {
    let entry = match entry {
      Ok(entry) => entry,
      Err(_) => continue,
    };
    let Some(ft) = entry.file_type() else {
      continue;
    };
    if !ft.is_file() {
      continue;
    }

    let relative = relative_path(&base_path, entry.path());
    let entry_name = entry
      .path()
      .file_name()
      .map(|v| v.to_string_lossy())
      .unwrap_or_default();

    if compiled.is_excluded(&entry_name, &relative) {
      continue;
    }
    if !compiled.is_included(&relative) {
      continue;
    }

    files.push(entry.into_path());
  }

  Ok(files)
}

fn compile_include_patterns(patterns: &[String]) -> Result<Option<GlobSet>, FileDiscoveryError> {
  if patterns.is_empty() {
    return Ok(None);
  }

  let mut builder = GlobSetBuilder::new();
  for pattern in patterns.iter().map(|p| p.trim()).filter(|p| !p.is_empty()) {
    let normalized = normalize_include_pattern(pattern);
    let glob = Glob::new(&normalized).map_err(|err| FileDiscoveryError::InvalidGlobPattern {
      pattern: pattern.to_string(),
      message: err.to_string(),
    })?;
    builder.add(glob);
  }

  let set = builder
    .build()
    .map_err(|err| FileDiscoveryError::InvalidGlobPattern {
      pattern: "<include>".to_string(),
      message: err.to_string(),
    })?;
  Ok(Some(set))
}

fn compile_exclude_patterns(
  patterns: &[String],
) -> Result<CompiledExcludePatterns, FileDiscoveryError> {
  let mut exclude_glob_builder = GlobSetBuilder::new();
  let mut has_globs = false;
  let mut exclude_substrings = Vec::new();
  let mut exclude_names = HashSet::new();

  for raw in patterns.iter().map(|p| p.trim()).filter(|p| !p.is_empty()) {
    if looks_like_glob(raw) {
      let pattern = normalize_exclude_pattern(raw);
      let glob = Glob::new(&pattern).map_err(|err| FileDiscoveryError::InvalidGlobPattern {
        pattern: raw.to_string(),
        message: err.to_string(),
      })?;
      exclude_glob_builder.add(glob);
      has_globs = true;
      continue;
    }

    // Keep historical behavior: exact name match OR substring match.
    exclude_names.insert(raw.to_string());
    exclude_substrings.push(raw.to_string());
  }

  let exclude_globs = if has_globs {
    Some(
      exclude_glob_builder
        .build()
        .map_err(|err| FileDiscoveryError::InvalidGlobPattern {
          pattern: "<exclude>".to_string(),
          message: err.to_string(),
        })?,
    )
  } else {
    None
  };

  Ok((exclude_globs, exclude_substrings, exclude_names))
}

type CompiledExcludePatterns = (Option<GlobSet>, Vec<String>, HashSet<String>);

fn looks_like_glob(pattern: &str) -> bool {
  pattern.contains('*')
    || pattern.contains('?')
    || pattern.contains('[')
    || pattern.contains('{')
    || pattern.contains('}')
}

fn normalize_include_pattern(pattern: &str) -> String {
  // Historically, `include` behaved like an extension allowlist. Keep that as the default:
  // - "*.ts" / ".ts" / "ts" => "**/*.ts"
  // Additionally allow full globs (e.g. "src/**/*.ts"), which are matched against a
  // normalized ("/") relative path.
  let trimmed = pattern.trim();

  let has_separators = trimmed.contains('/') || trimmed.contains('\\');
  if looks_like_glob(trimmed) {
    // Treat plain filename globs as matching anywhere (e.g. "*.ts" should match "src/a.ts").
    if !has_separators {
      return format!("**/{}", trimmed.replace('\\', "/"));
    }
    return trimmed.replace('\\', "/");
  }

  if has_separators {
    return trimmed.replace('\\', "/");
  }

  let suffix = normalize_suffix(trimmed);
  format!("**/*{suffix}")
}

fn normalize_exclude_pattern(pattern: &str) -> String {
  // Exclude globs match against normalized relative paths.
  let normalized = pattern.trim().replace('\\', "/");
  if normalized.contains('/') {
    normalized
  } else {
    // Treat plain filename globs as matching anywhere (e.g. "*.min.js" should match "dist/a.min.js").
    format!("**/{normalized}")
  }
}

fn normalize_suffix(pattern: &str) -> String {
  if let Some(value) = pattern.strip_prefix("*.") {
    return format!(".{value}");
  }
  if let Some(value) = pattern.strip_prefix('.') {
    return format!(".{value}");
  }
  if let Some(idx) = pattern.rfind('.') {
    return pattern[idx..].to_string();
  }
  format!(".{pattern}")
}

fn relative_path(base: &Path, path: &Path) -> String {
  path
    .strip_prefix(base)
    .unwrap_or(path)
    .to_string_lossy()
    .replace('\\', "/")
}

