    touch(&temp.path().join("src/a.py"), "print('no')\n");
    touch(
      &temp.path().join("node_modules/pkg/ignore.ts"),
      "export const ignored = 1\n",
    );

    let options = FileDiscoveryOptions {
      base_path: temp.path().to_path_buf(),
      include_patterns: vec!["**/*.ts".to_string()],
      exclude_patterns: vec!["node_modules".to_string()],
      respect_gitignore: true,
    };

    let files = find_files(&options).expect("find_files");
    let mut rel = files
      .iter()
      .map(|p| relative_path(temp.path(), p))
      .collect::<Vec<_>>();
