import { DEFAULT_INDEX_CONFIG_HASH } from '@argus/contracts-indexing'
import type {
  EnsureMergeRequestSourceBranchIndexingArgs,
  EnsureMergeRequestSourceBranchIndexingDeps,
  EnsureMergeRequestSourceBranchIndexingResult,
} from '@/lib/indexing/mr-auto-index-types'
import { isActivePlanJobStatus, resolveBranchScope } from '@/lib/indexing/mr-auto-index-utils'
import { toNonEmptyString } from '@/lib/indexing/string-utils'

export const ensureMergeRequestSourceBranchIndexing = async (
  args: EnsureMergeRequestSourceBranchIndexingArgs,
  deps: EnsureMergeRequestSourceBranchIndexingDeps,
): Promise<EnsureMergeRequestSourceBranchIndexingResult> => {
  if (!deps.isTriggerEnabled(args.trigger)) {
    return {
      decision: 'skipped',
      reason: 'trigger_disabled',
      branch: null,
      headSha: null,
    }
  }

  try {
    const integration = await deps.loadIntegration(args.integrationId)
    if (!integration) {
      return {
        decision: 'error',
        reason: 'integration_not_found',
        branch: null,
        headSha: null,
      }
    }

    const scope = await resolveBranchScope({
      args,
      deps,
      integration,
    })

    const branch = toNonEmptyString(scope.branch)
    const headSha = toNonEmptyString(scope.headSha)

    if (!branch) {
      return {
        decision: 'skipped',
        reason: 'missing_source_branch',
        branch: null,
        headSha: null,
      }
    }

    if (!headSha) {
      return {
        decision: 'skipped',
        reason: 'missing_source_head_sha',
        branch,
        headSha: null,
      }
    }

const configHash = toNonEmptyString(args.configHash) ?? DEFAULT_INDEX_CONFIG_HASH
const latestState = await deps.getLatestBranchState({
  integrationId: args.integrationId,
  branch,
  configHash,
})

const headAlreadyIndexed = latestState?.lastReadySha === headSha
let requiresGraphReplan = false
if (headAlreadyIndexed) {
  const graphReady = await deps.isBranchGraphReady({
    integrationId: args.integrationId,
    branch,
  })
  if (graphReady) {
    return {
      decision: 'already_ready',
      reason: 'head_already_indexed',
      branch,
      headSha,
    }
  }
  requiresGraphReplan = true
}

const inFlightPlanJob = await deps.getInFlightPlanJob({
  integrationId: args.integrationId,
  branch,
  configHash,
})
if (inFlightPlanJob) {
  return {
    decision: 'already_pending',
    reason: 'plan_job_in_flight',
    branch,
    headSha,
    job: {
      id: inFlightPlanJob.id,
      debounceKey: inFlightPlanJob.debounceKey,
      status: inFlightPlanJob.status,
    },
  }
}

if (latestState) {
  const inFlightRun = await deps.getInFlightRunForHead({
    branchStateId: latestState.id,
    headSha,
  })
  if (inFlightRun) {
    return {
      decision: 'already_pending',
      reason: 'run_in_flight',
      branch,
      headSha,
    }
  }
}

    const queuedJob = await deps.enqueuePlanJob({
      integrationId: args.integrationId,
      branch,
      configHash,
      hintedHeadSha: headSha,
      forceReplan: requiresGraphReplan,
      coalesceInFlight: true,
    })

    if (queuedJob.wasQueued === false) {
      if (!isActivePlanJobStatus(queuedJob.status)) {
        return {
          decision: 'skipped',
          reason: 'plan_job_not_active',
          branch,
          headSha,
        }
      }

      return {
        decision: 'already_pending',
        reason: 'plan_job_in_flight',
        branch,
        headSha,
        job: {
          id: queuedJob.id,
          debounceKey: queuedJob.debounceKey,
          status: queuedJob.status,
        },
      }
    }

    if (!isActivePlanJobStatus(queuedJob.status)) {
      return {
        decision: 'skipped',
        reason: 'plan_job_not_active',
        branch,
        headSha,
      }
    }

    return {
      decision: 'queued',
      reason: requiresGraphReplan ? 'graph_not_ready_replan_queued' : 'plan_job_queued',
      branch,
      headSha,
      job: {
        id: queuedJob.id,
        debounceKey: queuedJob.debounceKey,
        status: queuedJob.status,
      },
    }
  } catch {
    return {
      decision: 'error',
      reason: 'auto_index_failed',
      branch: toNonEmptyString(args.sourceBranchHint),
      headSha: toNonEmptyString(args.sourceHeadShaHint),
    }
  }
}

import { asc, gte } from "drizzle-orm"
import { NextResponse } from "next/server"

import { db } from "@/lib/db"
import { onboardingEvents } from "@/lib/db/schema"
import type { ObservabilityOnboardingTtfrPayload } from "@/lib/observability/types"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const TTFR_SLO_MS = 20_000
const DEFAULT_WINDOW_DAYS = 30

type SessionMilestones = {
  userId: string
  instanceBucket: "US" | "Global" | "Custom" | "Unknown"
  errorClass: string
  startedAt: Date
  tokenValidatedAt: Date | null
  projectsReadyAt: Date | null
  mrsReadyAt: Date | null
  reviewOpenedAt: Date | null
  quickReviewOutputAt: Date | null
  fullIndexedReadyAt: Date | null
}

const percentile = (values: number[], p: number) => {
  if (values.length === 0) {
    return null
  }

  const sorted = [...values].sort((a, b) => a - b)
  const index = (sorted.length - 1) * p
  const lower = Math.floor(index)
  const upper = Math.ceil(index)

  if (lower === upper) {
    return Math.round(sorted[lower])
  }

  const weight = index - lower
  const blended = sorted[lower] * (1 - weight) + sorted[upper] * weight
  return Math.round(blended)
}

const toMs = (start: Date, end: Date | null) => {
  if (!end) {
    return null
  }

  return Math.max(0, end.getTime() - start.getTime())
}

const instanceBucketFromUrl = (value: string | null | undefined) => {
  const normalized = value?.trim().toLowerCase()
  if (!normalized) {
    return "Unknown" as const
  }

  if (normalized === "https://us.global.lmco.com") {
    return "US" as const
  }

  if (normalized === "https://gitlab.global.lmco.com") {
    return "Global" as const
  }

  return "Custom" as const
}

const getMetadataString = (value: unknown, key: string) => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  const record = value as Record<string, unknown>
  return typeof record[key] === "string" && record[key]
    ? String(record[key])
    : null
}

const pushSession = (
  sessions: SessionMilestones[],
  current: SessionMilestones | null,
) => {
  if (!current) {
    return
  }

  sessions.push(current)
}

const aggregateByKey = (
  sessions: SessionMilestones[],
  key: "instanceBucket" | "errorClass",
) => {
  const grouped = new Map<string, number[]>()

  for (const session of sessions) {
    const ttfrMs = toMs(session.startedAt, session.reviewOpenedAt)
    if (ttfrMs === null) {
      continue
    }

    const bucket = String(session[key])
    const rows = grouped.get(bucket) ?? []
    rows.push(ttfrMs)
    grouped.set(bucket, rows)
  }

  return Array.from(grouped.entries())
    .map(([bucket, values]) => {
      const p50Ms = percentile(values, 0.5)
      const p95Ms = percentile(values, 0.95)
      return {
        bucket,
        count: values.length,
        p50Ms,
        p95Ms,
        sloBreached: p95Ms !== null && p95Ms > TTFR_SLO_MS,
      }
    })
    .sort((a, b) => b.count - a.count)
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/observability/onboarding-ttfr",
    event: "api.observability.onboarding_ttfr",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const since = new Date(Date.now() - DEFAULT_WINDOW_DAYS * 24 * 60 * 60 * 1000)

const rows = await db
  .select({
    userId: onboardingEvents.userId,
    event: onboardingEvents.event,
    createdAt: onboardingEvents.createdAt,
    metadata: onboardingEvents.metadata,
  })
  .from(onboardingEvents)
  .where(gte(onboardingEvents.createdAt, since))
  .orderBy(asc(onboardingEvents.userId), asc(onboardingEvents.createdAt))

const sessions: SessionMilestones[] = []
let current: SessionMilestones | null = null

for (const row of rows) {
  if (row.event === "onboarding_started") {
    pushSession(sessions, current)
    current = {
      userId: row.userId,
      instanceBucket: instanceBucketFromUrl(
        getMetadataString(row.metadata, "instanceUrl"),
      ),
      errorClass: getMetadataString(row.metadata, "errorCode") ?? "none",
      startedAt: row.createdAt,
      tokenValidatedAt: null,
      projectsReadyAt: null,
      mrsReadyAt: null,
      reviewOpenedAt: null,
      quickReviewOutputAt: null,
      fullIndexedReadyAt: null,
    }
    continue
  }

  if (!current || current.userId !== row.userId) {
    continue
  }

  const instanceUrl = getMetadataString(row.metadata, "instanceUrl")
  if (instanceUrl) {
    current.instanceBucket = instanceBucketFromUrl(instanceUrl)
  }

  const errorCode = getMetadataString(row.metadata, "errorCode")
  if (errorCode) {
    current.errorClass = errorCode
  }

  if (row.event === "onboarding_token_validated" && !current.tokenValidatedAt) {
    current.tokenValidatedAt = row.createdAt
  }
  if (row.event === "onboarding_projects_ready" && !current.projectsReadyAt) {
    current.projectsReadyAt = row.createdAt
  }
  if (row.event === "onboarding_mrs_ready" && !current.mrsReadyAt) {
    current.mrsReadyAt = row.createdAt
  }
  if (row.event === "onboarding_review_opened" && !current.reviewOpenedAt) {
    current.reviewOpenedAt = row.createdAt
  }
  if (
    row.event === "onboarding_quick_review_output" &&
    !current.quickReviewOutputAt
  ) {
    current.quickReviewOutputAt = row.createdAt
  }
  if (
    row.event === "onboarding_full_review_ready" &&
    !current.fullIndexedReadyAt
  ) {
    current.fullIndexedReadyAt = row.createdAt
  }
}

pushSession(sessions, current)

const sessionTtfrValues = sessions
  .map((session) => toMs(session.startedAt, session.reviewOpenedAt))
  .filter((value): value is number => value !== null)

const responsePayload: ObservabilityOnboardingTtfrPayload = {
  windowDays: DEFAULT_WINDOW_DAYS,
  sloTargetMs: TTFR_SLO_MS,
  summary: {
    totalSessions: sessions.length,
    sessionsWithTtfr: sessionTtfrValues.length,
    p50Ms: overallP50,
    p95Ms: overallP95,
    sloBreached: overallP95 !== null && overallP95 > TTFR_SLO_MS,
  },
  byInstance,
  byErrorClass,
  stageBreakdown: {
    tokenValidatedMs: {
      p50Ms: percentile(stageValues.tokenValidatedMs, 0.5),
      p95Ms: percentile(stageValues.tokenValidatedMs, 0.95),
    },
    projectsReadyMs: {
      p50Ms: percentile(stageValues.projectsReadyMs, 0.5),
      p95Ms: percentile(stageValues.projectsReadyMs, 0.95),
    },
    mrsReadyMs: {
      p50Ms: percentile(stageValues.mrsReadyMs, 0.5),
      p95Ms: percentile(stageValues.mrsReadyMs, 0.95),
    },
    reviewOpenedMs: {
      p50Ms: percentile(stageValues.reviewOpenedMs, 0.5),
      p95Ms: percentile(stageValues.reviewOpenedMs, 0.95),
    },
    quickReviewOutputMs: {
      p50Ms: percentile(stageValues.quickReviewOutputMs, 0.5),
      p95Ms: percentile(stageValues.quickReviewOutputMs, 0.95),
    },
    fullIndexedReadyMs: {
      p50Ms: percentile(stageValues.fullIndexedReadyMs, 0.5),
      p95Ms: percentile(stageValues.fullIndexedReadyMs, 0.95),
    },
  },
  alerts,
}

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json(responsePayload),
      }
    },
  })
}

import { afterEach, describe, expect, mock, test } from "bun:test"

import { ensureMergeRequestSourceBranchIndexing } from "@/lib/indexing/mr-auto-index-engine"
import type { EnsureMergeRequestSourceBranchIndexingDeps } from "@/lib/indexing/mr-auto-index-types"

const baseDeps = (): EnsureMergeRequestSourceBranchIndexingDeps => ({
  loadIntegration: mock(async () => ({
    instanceUrl: "https://gitlab.example.com",
    projectId: "123",
    token: "token",
  })),
  fetchMergeRequestDetails: mock(async () => ({
    source_branch: "feature/test",
    diff_refs: {
      head_sha: "sha-new",
    },
  })),
  getLatestBranchState: mock(async () => null),
  getInFlightPlanJob: mock(async () => null),
  getInFlightRunForHead: mock(async () => null),
  enqueuePlanJob: mock(async () => ({
    id: "job-1",
    debounceKey: "plan:integration-1:feature/test:default-v1",
    status: "pending" as const,
    wasQueued: true,
  })),
  isBranchGraphReady: mock(async () => true),
  isTriggerEnabled: mock(() => true),
})

describe("ensureMergeRequestSourceBranchIndexing", () => {

test("returns skipped when source branch cannot be resolved", async () => {
  const deps = baseDeps()
  deps.fetchMergeRequestDetails = mock(async () => ({
    source_branch: null,
  }))

  const result = await ensureMergeRequestSourceBranchIndexing(
    {
      integrationId: "integration-1",
      mergeRequestIid: "42",
      trigger: "lazy",
    },
    deps,
  )

  expect(result).toMatchObject({
    decision: "skipped",
    reason: "missing_source_branch",
    branch: null,
    headSha: null,
  })
  expect(deps.enqueuePlanJob).toHaveBeenCalledTimes(0)
})

test("returns already_ready when head sha matches serving sha", async () => {
  const deps = baseDeps()
  deps.getLatestBranchState = mock(async () => ({
    id: "branch-state-1",
    configHash: "default-v1",
    lastReadySha: "sha-new",
    updatedAt: new Date("2026-02-26T10:00:00.000Z"),
    servingUpdatedAt: new Date("2026-02-26T10:00:00.000Z"),
  }))

  const result = await ensureMergeRequestSourceBranchIndexing(
    {
      integrationId: "integration-1",
      mergeRequestIid: "42",
      trigger: "webhook",
    },
    deps,
  )

  expect(result).toMatchObject({
    decision: "already_ready",
    reason: "head_already_indexed",
    branch: "feature/test",
    headSha: "sha-new",
  })
  expect(deps.isBranchGraphReady).toHaveBeenCalledTimes(1)
  expect(deps.enqueuePlanJob).toHaveBeenCalledTimes(0)
})

test("queues forced replan when head is indexed but graph is not ready", async () => {
  const deps = baseDeps()
  deps.getLatestBranchState = mock(async () => ({
    id: "branch-state-1",
    configHash: "default-v1",
    lastReadySha: "sha-new",
    updatedAt: new Date("2026-02-26T10:00:00.000Z"),
    servingUpdatedAt: new Date("2026-02-26T10:00:00.000Z"),
  }))
  deps.isBranchGraphReady = mock(async () => false)

  const result = await ensureMergeRequestSourceBranchIndexing(
    {
      integrationId: "integration-1",
      mergeRequestIid: "42",
      trigger: "webhook",
    },
    deps,
  )

  expect(deps.enqueuePlanJob).toHaveBeenCalledTimes(1)
  expect(deps.enqueuePlanJob).toHaveBeenCalledWith({
    integrationId: "integration-1",
    branch: "feature/test",
    configHash: "default-v1",
    hintedHeadSha: "sha-new",
    forceReplan: true,
    coalesceInFlight: true,
  })
  expect(result).toMatchObject({
    decision: "queued",
    reason: "graph_not_ready_replan_queued",
    branch: "feature/test",
    headSha: "sha-new",
  })
})

test("returns already_pending when a matching plan job is in flight", async () => {
  const deps = baseDeps()
  deps.getInFlightPlanJob = mock(async () => ({
    id: "job-123",
    debounceKey: "plan:integration-1:feature/test:default-v1",
    status: "processing" as const,
  }))

  const result = await ensureMergeRequestSourceBranchIndexing(
    {
      integrationId: "integration-1",
      mergeRequestIid: "42",
      trigger: "webhook",
    },
    deps,
  )

  expect(result).toMatchObject({
    decision: "already_pending",
    reason: "plan_job_in_flight",
    branch: "feature/test",
    headSha: "sha-new",
    job: {
      id: "job-123",
    },
  })
  expect(deps.enqueuePlanJob).toHaveBeenCalledTimes(0)
})

  test("queues plan job when branch is stale and no in-flight work exists", async () => {
    const deps = baseDeps()
    deps.getLatestBranchState = mock(async () => ({
      id: "branch-state-1",
      configHash: "default-v1",
      lastReadySha: "sha-old",
      updatedAt: new Date("2026-02-26T10:00:00.000Z"),
      servingUpdatedAt: new Date("2026-02-26T10:00:00.000Z"),
    }))

    const result = await ensureMergeRequestSourceBranchIndexing(
      {
        integrationId: "integration-1",
        mergeRequestIid: "42",
        trigger: "webhook",
      },
      deps,
    )

    expect(deps.enqueuePlanJob).toHaveBeenCalledTimes(1)
    expect(deps.enqueuePlanJob).toHaveBeenCalledWith({
      integrationId: "integration-1",
      branch: "feature/test",
      configHash: "default-v1",
      hintedHeadSha: "sha-new",
      forceReplan: false,
      coalesceInFlight: true,
    })
    expect(result).toMatchObject({
      decision: "queued",
      reason: "plan_job_queued",
      branch: "feature/test",
      headSha: "sha-new",
      job: {
        id: "job-1",
      },
    })
  })
})

afterEach(() => {
  mock.restore()
})

import { NextResponse } from "next/server"
import { z } from "zod"

import { getUserIntegration, resyncGitLabIntegration } from "@/lib/gitlab/service"
import { invalidateUserIntegrations } from "@/lib/gitlab/user-integrations-cache"
import { requireJsonBodyOrEmpty } from "@/lib/http/request-json"
import { prewarmMergeRequestSourceBranches } from "@/lib/indexing/mr-auto-index"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const resyncSchema = z.object({
  token: z.string().optional(),
})

const PREWARM_INLINE_BUDGET_MS = 250

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/resync`,
    event: "api.gitlab.integrations.resync",
    context: { integrationId },
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const [integration, body] = await Promise.all([
        getUserIntegration(integrationId, userId),
        requireJsonBodyOrEmpty(request, "Invalid resync payload."),
      ])

if (!integration) {
  return {
    status: 404,
    outcome: "not_found",
    response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
  }
}

if (!body.ok) return body.result

const parsed = resyncSchema.safeParse(body.value)
if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid resync payload." }, { status: 400 }),
  }
}

try {
  const result = await resyncGitLabIntegration({
    integration,
    token: parsed.data.token,
  })
  const prewarmPromise = prewarmMergeRequestSourceBranches({
    integrationId: result.integration.id,
  }).catch(() => null)
  const prewarm = await Promise.race([
    prewarmPromise,
    new Promise<null>((resolve) => {
      setTimeout(() => resolve(null), PREWARM_INLINE_BUDGET_MS)
    }),
  ])
  const prewarmMode = prewarm ? "inline_completed" : "queued_async"
  if (!prewarm) {
    void prewarmPromise
  }
  invalidateUserIntegrations(userId)
  logger.set({
    hasWarning: Boolean(result.warning),
    prewarmMode,
    prewarmEnabled: prewarm?.enabled ?? null,
    prewarmScanned: prewarm?.scanned ?? null,
    prewarmQueued: prewarm?.queued ?? null,
    prewarmAlreadyReady: prewarm?.alreadyReady ?? null,
    prewarmAlreadyPending: prewarm?.alreadyPending ?? null,
    prewarmSkipped: prewarm?.skipped ?? null,
    prewarmErrored: prewarm?.errored ?? null,
  })
  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: result.integration,
      warning: result.warning,
      prewarm,
      prewarmStatus: {
        mode: prewarmMode,
      },
    }),
  }
} catch (error) {

        const message = error instanceof Error ? error.message : "Failed to resync integration."
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: message }, { status: 400 }),
        }
      }
    },
  })
}

