import type { AdminManagedUser } from "@/lib/admin-users"

type AdminUsersTableProps = {
  initialUsers: AdminManagedUser[]
  currentUserId: string
}

type UsersPayload = {
  data?: {
    user?: AdminManagedUser
  }
  error?: string
}

const formatDate = (value: string) => {
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "-"
  }
  return parsed.toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  })
}

export function AdminUsersTable({ initialUsers, currentUserId }: AdminUsersTableProps) {
  const [users, setUsers] = useState(initialUsers)
  const [updatingUserIds, setUpdatingUserIds] = useState<Set<string>>(new Set())

  const sortedUsers = useMemo(
    () => [...users].sort((left, right) => left.email.localeCompare(right.email)),
    [users],
  )

  const setIsUpdating = (userId: string, isUpdating: boolean) => {
    setUpdatingUserIds((current) => {
      const next = new Set(current)
      if (isUpdating) {
        next.add(userId)
      } else {
        next.delete(userId)
      }
      return next
    })
  }

const handleToggleAdmin = async (targetUser: AdminManagedUser) => {
  if (updatingUserIds.has(targetUser.id)) {
    return
  }

  const nextIsAdmin = !targetUser.isAdmin
  setIsUpdating(targetUser.id, true)

  try {
    const response = await fetch("/api/admin/users", {
      method: "PATCH",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        userId: targetUser.id,
        isAdmin: nextIsAdmin,
      }),
    })
    const parsedPayload = await parseJsonResponse(response)
    const payload = parsedPayload.ok ? (parsedPayload.value as UsersPayload) : null
    if (!response.ok) {
      throw new Error(payload?.error || "Unable to update user admin permissions.")
    }

    const updated = payload?.data?.user
    if (!updated) {
      throw new Error("Updated user payload is missing.")
    }

    setUsers((current) =>
      current.map((entry) => (entry.id === updated.id ? updated : entry)),
    )
    toast.success(nextIsAdmin ? "Admin access granted" : "Admin access removed")
  } catch (error) {
    toast.error(error instanceof Error ? error.message : "Unable to update user admin permissions.")
  } finally {
    setIsUpdating(targetUser.id, false)
  }
}

return (
  <Table>

          return (
            <TableRow key={entry.id}>
              <TableCell>{entry.name?.trim() || "-"}</TableCell>
              <TableCell>{entry.email}</TableCell>
              <TableCell>
                <Badge variant={entry.emailVerified ? "default" : "outline"}>
                  {entry.emailVerified ? "Verified" : "Unverified"}
                </Badge>
              </TableCell>
              <TableCell>
                <div className="flex items-center gap-2">
                  <Badge variant={entry.isAdmin ? "default" : "secondary"}>
                    {entry.isAdmin ? "Admin" : "Member"}
                  </Badge>
                  {entry.isAdminManagedByAllowlist ? (
                    <Badge variant="outline">Allowlist</Badge>
                  ) : null}
                </div>
              </TableCell>
              <TableCell>{formatDate(entry.createdAt)}</TableCell>
              <TableCell className="text-right">
                <Button
                  variant="outline"
                  size="sm"
                  disabled={actionDisabled}
                  onClick={() => {
                    void handleToggleAdmin(entry)
                  }}
                >
                  {actionLabel}
                </Button>
              </TableCell>
            </TableRow>
          )
        })}
      </TableBody>
    </Table>
  )
}

import { and, eq, inArray } from "drizzle-orm"
import { NextResponse } from "next/server"

import { db } from "@/lib/db"
import { indexBranchStates, indexRuns } from "@/lib/db/schema"
import { getUserIntegration } from "@/lib/gitlab/service"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const CANCELLABLE_STATUSES = ["planned", "ingesting", "indexing"] as const
const CANCELLED_CODE = "RUN_CANCELLED_BY_USER"
const CANCELLED_MESSAGE = "Indexing run cancelled by user request."

const isCancellableStatus = (
  status: string,
): status is (typeof CANCELLABLE_STATUSES)[number] =>
  (CANCELLABLE_STATUSES as readonly string[]).includes(status)

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string; runId: string }> },
) {
  const { integrationId, runId } = await context.params

  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/index/runs/${runId}/cancel`,
    event: "api.gitlab.index.runs.cancel",
    context: { integrationId, runId },
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const integration = await getUserIntegration(integrationId, userId)

if (!integration) {
  return {
    status: 404,
    outcome: "not_found",
    response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
  }
}

const [run] = await db
  .select({
    id: indexRuns.id,
    status: indexRuns.status,
  })
  .from(indexRuns)
  .innerJoin(indexBranchStates, eq(indexRuns.branchStateId, indexBranchStates.id))
  .where(
    and(
      eq(indexRuns.id, runId),
      eq(indexBranchStates.integrationId, integration.id),
    ),
  )
  .limit(1)

if (!run) {
  return {
    status: 404,
    outcome: "not_found",
    response: NextResponse.json({ error: "Index run not found." }, { status: 404 }),
  }
}

if (run.status === "cancelled") {
  logger.set({
    runStatus: run.status,
    alreadyCancelled: true,
  })
  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: {
        runId: run.id,
        status: "cancelled",
        cancelled: true,
        alreadyCancelled: true,
      },
    }),
  }
}

if (!isCancellableStatus(run.status)) {
  logger.set({
    runStatus: run.status,
    alreadyCancelled: false,
    cancellable: false,
  })
  return {
    status: 409,
    outcome: "conflict",
    response: NextResponse.json(
      {
        error: `Run is not cancellable from status '${run.status}'.`,
      },
      { status: 409 },
    ),
  }
}

const now = new Date()
const [cancelled] = await db
  .update(indexRuns)
  .set({
    status: "cancelled",
    error: {
      code: CANCELLED_CODE,
      message: CANCELLED_MESSAGE,
      cancelledAt: now.toISOString(),
    },
    updatedAt: now,
  })
  .where(
    and(
      eq(indexRuns.id, run.id),
      inArray(indexRuns.status, [...CANCELLABLE_STATUSES]),
    ),
  )
  .returning({
    id: indexRuns.id,
    status: indexRuns.status,
  })

if (!cancelled) {
  const [latest] = await db
    .select({
      status: indexRuns.status,
    })
    .from(indexRuns)
    .where(eq(indexRuns.id, run.id))
    .limit(1)

  if (latest?.status === "cancelled") {
    logger.set({
      runStatus: latest.status,
      alreadyCancelled: true,
    })
    return {
      status: 200,
      outcome: "success",
      response: NextResponse.json({
        data: {
          runId: run.id,
          status: "cancelled",
          cancelled: true,
          alreadyCancelled: true,
        },
      }),
    }
  }

  logger.set({
    runStatus: latest?.status ?? "unknown",
    alreadyCancelled: false,
    cancellable: false,
  })
  return {
    status: 409,
    outcome: "conflict",
    response: NextResponse.json(
      {
        error: `Run is no longer cancellable (current status: ${latest?.status ?? "unknown"}).`,
      },
      { status: 409 },
    ),
  }
}

logger.set({
  previousStatus: run.status,
  runStatus: cancelled.status,
  alreadyCancelled: false,
})

      return {
        status: 202,
        outcome: "accepted",
        response: NextResponse.json(
          {
            data: {
              runId: cancelled.id,
              status: cancelled.status,
              cancelled: true,
              alreadyCancelled: false,
            },
          },
          { status: 202 },
        ),
      }
    },
  })
}

