test("prunes stale token test cache entries", () => {
  const now = Date.now()
  const cache: TokenTestResultCache = new Map([
    [
      "fresh",
      { checkedAt: now, feedback: { kind: "success", message: "ok" } },
    ],
    [
      "old",
      { checkedAt: now - 11 * 60_000, feedback: { kind: "error", message: "bad" } },
    ],
  ])

  pruneTokenTestCache(cache, now)

  expect(cache.has("fresh")).toBe(true)
  expect(cache.has("old")).toBe(false)
})

test("extracts useful error messages", () => {
