  expect(getErrorMessage(rawSqlError)).toBe(
    "Could not complete that action. Please verify your GitLab settings and try again.",
  )
})

  test("persists onboarding state patches without dropping existing keys", () => {
    const originalWindow = (globalThis as { window?: unknown }).window
    const storage = new Map<string, string>()
    const mockWindow = {
      sessionStorage: {
        getItem: (key: string) => storage.get(key) ?? null,
        setItem: (key: string, value: string) => {
          storage.set(key, value)
        },
        removeItem: (key: string) => {
          storage.delete(key)
        },
        clear: () => {
          storage.clear()
        },
      },
    }

    Object.defineProperty(globalThis, "window", {
      configurable: true,
      value: mockWindow,
    })

    try {
      mockWindow.sessionStorage.setItem(
        ONBOARDING_STORAGE_KEY,
        JSON.stringify({
          token: "existing-token",
          selectedProjectId: "",
        }),
      )

      persistOnboardingStatePatch({
        selectedProjectId: "project-9",
        selectedMergeRequestId: "",
      })

      expect(readPersistedState()).toMatchObject({
        token: "existing-token",
        selectedProjectId: "project-9",
        selectedMergeRequestId: "",
      })
    } finally {
      if (originalWindow === undefined) {
        Reflect.deleteProperty(globalThis, "window")
      } else {
        Object.defineProperty(globalThis, "window", {
          configurable: true,
          value: originalWindow,
        })
      }
    }
  })
})

const payloadSchema = z.discriminatedUnion("kind", [
  edgeTypesPayloadSchema,
  neighborhoodPayloadSchema,
  presetPayloadSchema,
])

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/graph/query",
    event: "api.code.graph.query",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBodyOrEmpty(request, "Invalid graph query payload."),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const parsed = payloadSchema.safeParse(body.value)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid graph query payload." }, { status: 400 }),
        }
      }

      try {
        const resolution = await resolveSnapshotGraphScope({
          integrationId: parsed.data.integrationId,
          sourceBranch: parsed.data.sourceBranch,
        })
        if (resolution.status === "pending_graph") {
          logger.set({
            graphPendingReason: resolution.reason,
          })
          return {
            status: 409,
            outcome: "graph_pending",
            response: NextResponse.json({ error: resolution.message }, { status: 409 }),
          }
        }

if (resolution.status === "error") {
  logger.set({
    graphErrorCode: "snapshot_error",
    graphErrorDetails: { message: resolution.error },
  })
  return {
    status: 502,
    outcome: "graph_failed",
    response: NextResponse.json({ error: resolution.error }, { status: 502 }),
  }
}

const graphData = await loadSnapshotGraphData({
  snapshot: resolution.snapshot,
  artifactStore: resolution.artifactStore,
})

if (parsed.data.kind === "edge-types") {
  const result = getSnapshotGraphEdgeTypes({ data: graphData })
  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({ data: result }),
  }
}

if (parsed.data.kind === "neighborhood") {
  const result = querySnapshotGraphNeighborhood({
    data: graphData,
    nodeId: parsed.data.nodeId,
    depth: parsed.data.depth,
    direction: parsed.data.direction,
    edgeTypes: parsed.data.edgeTypes,
    maxNodes: parsed.data.maxNodes,
    maxEdges: parsed.data.maxEdges,
  })
  logger.set({
    queryKind: "neighborhood",
    nodeCount: result.nodes.length,
    edgeCount: result.edges.length,
  })
  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({ data: result }),
  }
}

        const result = querySnapshotGraphImpactPreset({
          data: graphData,
          nodeId: parsed.data.nodeId,
          preset: parsed.data.preset,
          depth: parsed.data.depth,
          maxNodes: parsed.data.maxNodes,
          maxEdges: parsed.data.maxEdges,
        })
        logger.set({
          queryKind: "preset",
          preset: parsed.data.preset,
          nodeCount: result.nodes.length,
          edgeCount: result.edges.length,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: result }),
        }
      } catch {
        logger.set({ graphErrorCode: "unknown" })
        return {
          status: 500,
          outcome: "graph_failed",
          response: NextResponse.json({ error: "Failed to run graph query." }, { status: 500 }),
        }
      }
    },
  })
}

