import { describe, expect, mock, test } from "bun:test"

const ONBOARDING_COMPLETED_UNIQUE_INDEX = "onboarding_events_user_id_completed_uq"

type DbSelectRow = {
  createdAt: Date
  metadata?: {
    onboardingDurationMs?: number
  } | null
}

const loadServiceModule = async (dbMock: {
  select: () => {
    from: () => {
      where: () => {
        orderBy: () => {
          limit: () => Promise<DbSelectRow[]>
        }
      }
    }
  }
  insert: () => {
    values: (value: unknown) => Promise<unknown>
  }
}) => {
  mock.module("@/lib/db", () => ({ db: dbMock }))
  return import(`@/lib/onboarding/service.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
}

const createDbMock = (options: {
  limitResponses: DbSelectRow[][]
  insertError?: unknown
}) => {
  const insertValues: unknown[] = []
  const queued = [...options.limitResponses]

  const dbMock = {
    select: () => ({
      from: () => ({
        where: () => ({
          orderBy: () => ({
            limit: () => Promise.resolve(queued.shift() ?? []),
          }),
        }),
      }),
    }),
    insert: () => ({
      values: (value: unknown) => {
        if (options.insertError) {
          return Promise.reject(options.insertError)
        }
        insertValues.push(value)
        return Promise.resolve([])
      },
    }),
  }

  return { dbMock, insertValues }
}

describe("onboarding service", () => {

test("records onboarding completion once and computes duration", async () => {
  const startedAt = new Date(Date.now() - 12_000)
  const { dbMock, insertValues } = createDbMock({
    limitResponses: [[], [{ createdAt: startedAt }]],
  })
  const mod = await loadServiceModule(dbMock)

  const result = await mod.recordOnboardingCompletedIfMissing({
    userId: "user-1",
    metadata: {
      completionSource: "first_ai_review",
      findingsCount: 3,
    },
  })

  expect(result.alreadyCompleted).toBe(false)
  expect(result.onboardingDurationMs).toBeTypeOf("number")
  expect((result.onboardingDurationMs ?? 0) >= 10_000).toBe(true)
  expect(insertValues).toHaveLength(1)
  expect(insertValues[0]).toMatchObject({
    userId: "user-1",
    event: "onboarding_completed",
    metadata: expect.objectContaining({
      completionSource: "first_ai_review",
      findingsCount: 3,
    }),
  })
})

test("skips insert when onboarding is already completed", async () => {
  const completedAt = new Date(Date.now() - 5_000)
  const { dbMock, insertValues } = createDbMock({
    limitResponses: [[{ createdAt: completedAt, metadata: { onboardingDurationMs: 4_000 } }]],
  })
  const mod = await loadServiceModule(dbMock)

  const result = await mod.recordOnboardingCompletedIfMissing({
    userId: "user-1",
    metadata: { completionSource: "manual" },
  })

  expect(result.alreadyCompleted).toBe(true)
  expect(result.onboardingDurationMs).toBe(4_000)
  expect(result.onboardingCompletedAt).toBe(completedAt)
  expect(insertValues).toHaveLength(0)
})

test("does not use caller metadata fallback for existing completion duration", async () => {
  const completedAt = new Date(Date.now() - 5_000)
  const { dbMock } = createDbMock({
    limitResponses: [[{ createdAt: completedAt, metadata: null }]],
  })
  const mod = await loadServiceModule(dbMock)

  const result = await mod.recordOnboardingCompletedIfMissing({
    userId: "user-1",
    metadata: { onboardingDurationMs: 9_999 },
  })

  expect(result.alreadyCompleted).toBe(true)
  expect(result.onboardingDurationMs).toBeNull()
})

  test("handles concurrent completion by relying on unique constraint", async () => {
    const startedAt = new Date(Date.now() - 6_000)
    const completedAt = new Date(Date.now() - 2_000)
    const { dbMock, insertValues } = createDbMock({
      limitResponses: [
        [],
        [{ createdAt: startedAt }],
        [{ createdAt: completedAt, metadata: { onboardingDurationMs: 4_000 } }],
      ],
      insertError: {
        code: "23505",
        constraint: ONBOARDING_COMPLETED_UNIQUE_INDEX,
      },
    })
    const mod = await loadServiceModule(dbMock)

