fn python_indexer_index_runs_parse_and_returns_stats() -> PyResult<()> {
  ensure_python_initialized();
  Python::with_gil(|py| {
    let tempdir = tempfile::tempdir().map_err(|err| PyValueError::new_err(err.to_string()))?;
    let src_dir = tempdir.path().join("src");
    std::fs::create_dir_all(&src_dir).map_err(|err| PyValueError::new_err(err.to_string()))?;
    let file_path = src_dir.join("sample.ts");
    std::fs::write(&file_path, "export const answer = 42;\n")
      .map_err(|err| PyValueError::new_err(err.to_string()))?;

    let module = PyModule::new_bound(py, "argus_search")?;
    argus_search(py, &module)?;
    let indexer_cls = module.getattr("Indexer")?;
    let kwargs = PyDict::new_bound(py);
    kwargs.set_item("root", tempdir.path().to_string_lossy().to_string())?;
    kwargs.set_item("paths", vec!["src"])?;
    kwargs.set_item("include", vec!["*.ts"])?;
    let indexer = indexer_cls.call((), Some(&kwargs))?;

    let run = indexer.call_method0("index")?;
    let file_count = run.getattr("file_count")?.extract::<u64>()?;
    assert!(file_count >= 1);
