    let event = bindings::stream_event_to_py(py, &payload, true)?;
    let bound = event.bind(py);
    let type_name = bound.get_type().name()?.extract::<String>()?;
    assert!(type_name.ends_with("VectorBatch"));

    let records = bound.getattr("records")?.downcast_into::<PyList>()?;
    assert_eq!(records.len(), 1);
    let first = records.get_item(0)?;
    let chunk_id = first.getattr("chunk_id")?.extract::<String>()?;
    let file_path = first.getattr("file_path")?.extract::<String>()?;
    assert_eq!(chunk_id, "chunk-1");
    assert_eq!(file_path, "src/main.py");
    Ok(())
  })
}

