      "src/components/app-sidebar.tsx",
      "src/features/command-palette/components/palette.tsx",
      "src/features/indexing/components/console/console.tsx",
      "src/features/settings/hooks/use-gitlab-settings.ts",
    ]

    for (const path of files) {
      const source = readSource(path)
      expect(source.includes('from "@/lib/gitlab/client-integrations-query"')).toBe(true)
      expect(/fetch\(\s*["']\/api\/gitlab\/integrations["']\s*[,)]/.test(source)).toBe(false)
    }
  })

  test("invalidates the shared integrations query after integration mutations", () => {
    const sidebarSource = readSource("src/components/app-sidebar.tsx")
    const settingsSource = readSource("src/features/settings/hooks/use-gitlab-settings.ts")

    expect(sidebarSource.includes("invalidateGitLabIntegrationsQuery()")).toBe(true)
    expect(settingsSource.includes("invalidateGitLabIntegrationsQuery()")).toBe(true)
  })
})

