const getPendingGraphMessage = (reason: string | null) => {
  if (reason === "branch_state_not_found") {
    return "Impact analysis pending: this branch does not have a graph snapshot yet."
  }
  if (reason === "no_ready_run") {
    return "Impact analysis pending: branch graph indexing is still in progress."
  }
  if (reason === "missing_source_branch") {
    return "Impact analysis pending: source branch metadata is missing for this review."
  }
  if (reason === "missing_integration_id") {
    return "Impact analysis pending: integration context is missing for this review."
  }
  if (reason === "graph_build_failed") {
    return "Impact analysis pending: latest ready run failed to build graph artifacts."
  }
  if (reason === "graph_build_skipped") {
    return "Impact analysis pending: latest ready run did not produce graph artifacts."
  }
  if (reason === "ready_run_not_found" || reason === "missing_artifacts") {
    return "Impact analysis pending: graph snapshot artifacts are not ready yet."
  }
  return "Impact analysis pending: graph snapshot is not ready yet."
}

