function MergeRequestReviewAnnotation({

  annotation,
  options,
}: {
  annotation: DiffLineAnnotation<ReviewAnnotationMetadata>
  options?: {
    onSubmitFeedback?: (commentKey: string, feedback: ReviewFeedback | null) => void
    onPostToGitLab?: (input: {
      commentKeyInput: string
