}) {
  const metadata = annotation.metadata
  const severityMeta = REVIEW_SEVERITY_META[metadata.severity]
  const isDeletionComment = annotation.side === "deletions"
  const lineLabel = `${isDeletionComment ? "-" : "+"}${annotation.lineNumber}`
  const confidencePercent = Math.round(metadata.confidence * 100)
  const [pendingFeedbackAction, setPendingFeedbackAction] = useState<ReviewFeedback | null>(null)
  const impact = metadata.impact
  const showPendingGraphWarning = metadata.isImpactPendingGraph
  const showPendingImpactWarning = !showPendingGraphWarning && impact?.status === "pending"
  const pendingGraphMessage = showPendingGraphWarning
    ? getPendingGraphMessage(metadata.impactGraphPendingReason)
    : null

const pendingImpactMessage = (() => {
  if (metadata.impactGraphResolutionStatus === "ready") {
    if (metadata.impactComputationStatus === "not_started") {
      return "Impact analysis pending: graph is ready, but impact computation has not started for this review."
    }
    if (metadata.impactComputationStatus === "in_progress") {
      return "Impact analysis pending: graph is ready, but impact computation is still in progress for this review."
    }
  }
  if (metadata.impactComputationStatus === "not_started") {
    return "Impact analysis pending: impact computation has not started yet."
  }
  if (metadata.impactComputationStatus === "in_progress") {
    return "Impact analysis pending: impact computation is still in progress."
  }
  return "Impact analysis pending: impact computation is still running."
})()
const impactLevelMeta =
  impact?.impactLevel && impact.impactLevel in IMPACT_LEVEL_META
    ? IMPACT_LEVEL_META[impact.impactLevel]
    : null

const hasCompletedImpact = impact && impact.status !== "pending"
const impactGraphHref =
