import type {
  ReviewGateEffectiveSettings,
  ReviewGateSettings,
} from "@/lib/review/gate"
import { parseJsonResponse } from "@/lib/http/response-json"

export type ReviewGatePreferencesPayload = {
  global?: ReviewGateSettings
  projectOverride?: ReviewGateSettings | null
  effective?: ReviewGateEffectiveSettings
}

const getErrorMessage = (payload: unknown, fallback: string) => {
  if (payload && typeof payload === "object" && "error" in payload) {
    const value = (payload as { error?: unknown }).error
    if (typeof value === "string" && value.trim().length > 0) {
      return value
    }
  }
  return fallback
}

const parsePreferencesPayload = (payload: unknown): ReviewGatePreferencesPayload => {
  if (!payload || typeof payload !== "object") {
    return {}
  }

  const root = payload as { data?: unknown }
  if (!root.data || typeof root.data !== "object") {
    return {}
  }

  const data = root.data as Record<string, unknown>
  return {
    global: data.global as ReviewGateSettings | undefined,
    projectOverride: (data.projectOverride as ReviewGateSettings | null | undefined) ?? null,
    effective: data.effective as ReviewGateEffectiveSettings | undefined,
  }
}

export const fetchReviewPreferences = async ({
  instanceUrl,
  projectId,
}: {
  instanceUrl?: string
  projectId?: string
}) => {
  const params = new URLSearchParams()
  if (instanceUrl?.trim()) {
    params.set("instanceUrl", instanceUrl.trim())
  }
  if (projectId?.trim()) {
    params.set("projectId", projectId.trim())
  }

  const response = await fetch(`/api/review/preferences${params.size > 0 ? `?${params.toString()}` : ""}`)
  const parsedResponse = await parseJsonResponse(response)
  const payload = parsedResponse.ok ? parsedResponse.value : null
  if (!response.ok) {
    throw new Error(getErrorMessage(payload, "Failed to load review preferences."))
  }
  if (!parsedResponse.ok || parsedResponse.isEmpty) {
    throw new Error("Invalid review preferences response.")
  }

  return parsePreferencesPayload(payload)
}

export const saveGlobalReviewPreferences = async (settings: ReviewGateSettings) => {
  const response = await fetch("/api/review/preferences/global", {
    method: "PUT",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify(settings),
  })
  const parsedResponse = await parseJsonResponse(response)
  const payload = parsedResponse.ok ? parsedResponse.value : null
  if (!response.ok) {
    throw new Error(getErrorMessage(payload, "Failed to save global review preferences."))
  }
  if (!parsedResponse.ok || parsedResponse.isEmpty) {
    throw new Error("Invalid global review preferences response.")
  }

  return parsePreferencesPayload(payload)
}

export const saveProjectReviewPreferences = async ({
  instanceUrl,
  projectId,
  settings,
}: {
  instanceUrl: string
  projectId: string
  settings: ReviewGateSettings
}) => {
  const response = await fetch("/api/review/preferences/project", {
    method: "PUT",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      instanceUrl,
      projectId,
      ...settings,
    }),
  })
  const parsedResponse = await parseJsonResponse(response)
  const payload = parsedResponse.ok ? parsedResponse.value : null
  if (!response.ok) {
    throw new Error(getErrorMessage(payload, "Failed to save project review preferences."))
  }
  if (!parsedResponse.ok || parsedResponse.isEmpty) {
    throw new Error("Invalid project review preferences response.")
  }

  return parsePreferencesPayload(payload)
}

export const deleteProjectReviewPreferences = async ({
  instanceUrl,
  projectId,
}: {
  instanceUrl: string
  projectId: string
}) => {
  const response = await fetch("/api/review/preferences/project", {
    method: "DELETE",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      instanceUrl,
      projectId,
    }),
  })
  const parsedResponse = await parseJsonResponse(response)
  const payload = parsedResponse.ok ? parsedResponse.value : null
  if (!response.ok) {
    throw new Error(getErrorMessage(payload, "Failed to delete project review preferences."))
  }
  if (!parsedResponse.ok || parsedResponse.isEmpty) {
    throw new Error("Invalid project review preferences response.")
  }

  return parsePreferencesPayload(payload)
}

import { type FormEvent, useState } from "react"

import { authClient } from "@/lib/auth-client"

type UseSignUpFormOptions = {
  onSuccess: () => void
}

const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object") {
    if ("message" in value && typeof value.message === "string") {
      return value.message
    }
    if ("error" in value && typeof value.error === "string") {
      return value.error
    }
  }
  return "Could not create your account. Try again."
}

export function useSignUpForm({ onSuccess }: UseSignUpFormOptions) {
  const [name, setName] = useState("")
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [confirmPassword, setConfirmPassword] = useState("")
  const [submitting, setSubmitting] = useState(false)
  const [errorMessage, setErrorMessage] = useState("")

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    setErrorMessage("")

    if (password !== confirmPassword) {
      setErrorMessage("Passwords do not match.")
      return
    }

    if (password.length < 8) {
      setErrorMessage("Password must be at least 8 characters.")
      return
    }

    setSubmitting(true)

    const { error } = await authClient.signUp.email({
      name: name.trim(),
      email: email.trim(),
      password,
      callbackURL: "/",
    })

    setSubmitting(false)

    if (error) {
      setErrorMessage(getErrorMessage(error))
      return
    }

    onSuccess()
  }

  const handleOidcSignIn = async () => {
    setErrorMessage("")
    setSubmitting(true)

    const { error } = await authClient.signIn.oauth2({
      providerId: "oidc",
      callbackURL: "/",
      errorCallbackURL: "/sign-up",
    })

    if (error) {
      setErrorMessage(getErrorMessage(error))
      setSubmitting(false)
    }
  }

  return {
    name,
    email,
    password,
    confirmPassword,
    submitting,
    errorMessage,
    setName,
    setEmail,
    setPassword,
    setConfirmPassword,
    handleSubmit,
    handleOidcSignIn,
  }
}

