import { db } from "@/lib/db"
import { onboardingEvents } from "@/lib/db/schema"
import { recordOnboardingCompletedIfMissing } from "@/lib/onboarding/service"
import {
  ONBOARDING_COMPLETED_EVENT,
  ONBOARDING_EVENTS,
  type OnboardingEventMetadata,
  type OnboardingTrackedEvent,
} from "@/lib/onboarding/types"
import { requireJsonBody } from "@/lib/http/request-json"
import { getSession } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

type TrackEventPayload = {
  event: OnboardingTrackedEvent
  metadata?: OnboardingEventMetadata
}

const isOnboardingEvent = (value: unknown): value is OnboardingTrackedEvent =>
  typeof value === "string" && ONBOARDING_EVENTS.includes(value as OnboardingTrackedEvent)

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/onboarding/track",
    event: "api.onboarding.track",
    handler: async ({ logger }) => {
      const [session, body] = await Promise.all([
        getSession(),
        requireJsonBody(request, "Invalid onboarding event."),
      ])

      if (!session?.user?.id) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const payloadValue = body.value
      const payload = payloadValue as TrackEventPayload | null

if (!payload || !isOnboardingEvent(payload.event)) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid onboarding event." }, { status: 400 }),
  }
}

const metadata =
  payload.metadata && typeof payload.metadata === "object"
    ? payload.metadata
    : undefined

let onboardingDurationMs: number | null = null
let onboardingAlreadyCompleted = false
let onboardingCompletionSource: OnboardingEventMetadata["completionSource"] | null =
  metadata?.completionSource ?? null

if (payload.event === ONBOARDING_COMPLETED_EVENT) {
  onboardingCompletionSource = metadata?.completionSource ?? "manual"
  const completion = await recordOnboardingCompletedIfMissing({
    userId: session.user.id,
    metadata: {
      ...metadata,
      completionSource: onboardingCompletionSource,
    },
  })
  onboardingDurationMs = completion.onboardingDurationMs
  onboardingAlreadyCompleted = completion.alreadyCompleted
} else {
  await db.insert(onboardingEvents).values({
    userId: session.user.id,
    event: payload.event,
    metadata,
  })
}

logger.set({
  onboardingEvent: payload.event,
  onboardingDurationMs,
  onboardingAlreadyCompleted,
  onboardingCompletionSource,
})

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          ok: true,
          data: {
            onboardingDurationMs,
            onboardingAlreadyCompleted,
          },
        }),
      }
    },
  })
}

import { and, eq, inArray, isNull, sql } from 'drizzle-orm'
import { resolveWorkerLeasesEnabled } from '@argus/shared-runtime/worker-lease'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexFileStates,
  indexRunFileChanges,
  indexRuns,
} from '@/lib/db/schema'

type FinalizeStatus = 'ready' | 'superseded' | 'not_found' | 'invalid_state'

export type FinalizeIndexRunResult = {
  runId: string
  status: FinalizeStatus
}

const FINALIZABLE_STATUSES = new Set(['ingesting', 'indexing'])
const isLeaseFenceEnabled = () => resolveWorkerLeasesEnabled()

export const markIndexRunFailed = async (
  runId: string,
  error: Record<string, unknown>,
  options?: { expectedClaimVersion?: number },
): Promise<void> => {
  const whereFilters = [eq(indexRuns.id, runId)]
  if (isLeaseFenceEnabled() && typeof options?.expectedClaimVersion === 'number') {
    whereFilters.push(eq(indexRuns.claimVersion, Math.max(0, Math.floor(options.expectedClaimVersion))))
  }
  await db
    .update(indexRuns)
    .set({
      status: 'failed',
      error,
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: new Date(),
    })
    .where(and(...whereFilters))
}

export const finalizeIndexRun = async (
  runId: string,
  options?: { expectedClaimVersion?: number },
): Promise<FinalizeIndexRunResult> => {
  return db.transaction(async (tx) => {

const [run] = await tx
  .select({
    id: indexRuns.id,
    branchStateId: indexRuns.branchStateId,
    baseSha: indexRuns.baseSha,
    headSha: indexRuns.headSha,
    status: indexRuns.status,
    claimVersion: indexRuns.claimVersion,
  })
  .from(indexRuns)
  .where(eq(indexRuns.id, runId))
  .limit(1)

if (!run) {
  return { runId, status: 'not_found' }
}

if (!FINALIZABLE_STATUSES.has(run.status)) {
  return { runId, status: 'invalid_state' }
}
if (
  isLeaseFenceEnabled() &&
  typeof options?.expectedClaimVersion === 'number' &&
  Math.max(0, Math.floor(options.expectedClaimVersion)) !== run.claimVersion
) {
  return { runId, status: 'invalid_state' }
}

const now = new Date()
const casWhere = run.baseSha
  ? and(
      eq(indexBranchStates.id, run.branchStateId),
      eq(indexBranchStates.lastReadySha, run.baseSha),
    )
  : and(eq(indexBranchStates.id, run.branchStateId), isNull(indexBranchStates.lastReadySha))

const casUpdated = await tx
  .update(indexBranchStates)
  .set({
    lastReadySha: run.headSha,
    lastReadyRunId: run.id,
    servingUpdatedAt: now,
    updatedAt: now,
  })
  .where(casWhere)
  .returning({ id: indexBranchStates.id })

if (casUpdated.length === 0) {
  await tx
    .update(indexRuns)
    .set({
      status: 'superseded',
      leaseExpiresAt: null,
      claimedBy: null,
      error: {
        code: 'CAS_MISS',
        message: 'Run superseded by newer serving pointer.',
      },
      updatedAt: now,
    })
    .where(eq(indexRuns.id, run.id))

  return { runId: run.id, status: 'superseded' }
}

const stagedChanges = await tx
  .select({
    path: indexRunFileChanges.path,
    changeType: indexRunFileChanges.changeType,
    fileId: indexRunFileChanges.fileId,
    sizeBytes: indexRunFileChanges.sizeBytes,
    skipReason: indexRunFileChanges.skipReason,
  })
  .from(indexRunFileChanges)
  .where(eq(indexRunFileChanges.runId, run.id))

const deletePaths = stagedChanges
  .filter((change) => change.changeType === 'delete')
  .map((change) => change.path)

if (deletePaths.length > 0) {
  await tx
    .delete(indexFileStates)
    .where(
      and(
        eq(indexFileStates.branchStateId, run.branchStateId),
        inArray(indexFileStates.path, deletePaths),
      ),
    )
}

const upserts = stagedChanges.filter(
  (change) => change.changeType === 'upsert' && change.fileId && change.sizeBytes !== null,
)

    if (upserts.length > 0) {
      await tx
        .insert(indexFileStates)
        .values(
          upserts.map((change) => ({
            branchStateId: run.branchStateId,
            path: change.path,
            fileId: change.fileId as string,
            sizeBytes: change.sizeBytes as number,
            skipReason: change.skipReason,
            lastReadySha: run.headSha,
            createdAt: now,
            updatedAt: now,
          })),
        )
        .onConflictDoUpdate({
          target: [indexFileStates.branchStateId, indexFileStates.path],
          set: {
            fileId: sql`excluded.file_id`,
            sizeBytes: sql`excluded.size_bytes`,
            skipReason: sql`excluded.skip_reason`,
            lastReadySha: run.headSha,
            updatedAt: now,
          },
        })
    }

    await tx
      .update(indexRuns)
        .set({
          status: 'ready',
          leaseExpiresAt: null,
          claimedBy: null,
          error: null,
          updatedAt: now,
      })
      .where(eq(indexRuns.id, run.id))

    return { runId: run.id, status: 'ready' }
  })
}

