type MergeRequest = {
  id: string
  iid: string
  title: string
  state: string
  author: string
  webUrl: string
  sourceBranch?: string
  targetBranch?: string
  authoredByCurrentUser?: boolean
  assignedToCurrentUser?: boolean
  reviewRequestedFromCurrentUser?: boolean
}

type RepoMergeRequestsPanelProps = {
  mergeRequests: MergeRequest[]
  repoRouteId: string
  isLoading: boolean
  isRefreshing: boolean
  error: string
  onRefresh: () => void
  onPrewarmReviewData?: (mergeRequestIid: string) => void
}

const statusVariant = (status: string): React.ComponentProps<typeof Badge>["variant"] => {
  if (status === "ready" || status === "succeeded" || status === "active" || status === "opened") {
    return "default"
  }
  if (status === "failed" || status === "dead") {
    return "destructive"
  }
  if (status === "planned" || status === "pending" || status === "processing" || status === "indexing" || status === "ingesting") {
    return "secondary"
  }
  return "outline"
}

export type { MergeRequest }

export function RepoMergeRequestsPanel({

  mergeRequests,
  repoRouteId,
  isLoading,
  isRefreshing,
  error,
  onRefresh,
  onPrewarmReviewData,
}: RepoMergeRequestsPanelProps) {
  const router = useRouter()
  const [searchQuery, setSearchQuery] = useState("")
  const prefetchedReviewRoutesRef = useRef<Set<string>>(new Set())
  const deferredQuery = useDeferredValue(searchQuery)

  const normalizedSearchQuery = deferredQuery.trim().toLowerCase()
  const filteredMergeRequests = useMemo(() => {
    if (!normalizedSearchQuery) {
      return mergeRequests
    }

    return mergeRequests.filter((mergeRequest) => {
      const title = mergeRequest.title.toLowerCase()
      const author = mergeRequest.author.toLowerCase()
      const iid = mergeRequest.iid.toLowerCase()
      const sourceBranch = (mergeRequest.sourceBranch ?? "").toLowerCase()
      const targetBranch = (mergeRequest.targetBranch ?? "").toLowerCase()
      return (
        title.includes(normalizedSearchQuery) ||
        author.includes(normalizedSearchQuery) ||
        iid.includes(normalizedSearchQuery) ||
        sourceBranch.includes(normalizedSearchQuery) ||
        targetBranch.includes(normalizedSearchQuery)
      )
    })
  }, [mergeRequests, normalizedSearchQuery])

  const getReviewHref = useCallback((mergeRequestIid: string) =>
    `/repos/${encodeURIComponent(repoRouteId)}/mrs/${encodeURIComponent(mergeRequestIid)}`,
  [repoRouteId])

const prefetchReviewRoute = useCallback((mergeRequestIid: string) => {
  prefetchRouteOnce({
    href: getReviewHref(mergeRequestIid),
    prefetchedHrefs: prefetchedReviewRoutesRef.current,
    prefetch: router.prefetch,
  })
}, [getReviewHref, router])

return (
  <div className="space-y-4">
    <div className="flex items-center justify-between">
      <p className="text-sm text-muted-foreground">
        {isLoading
          ? "Loading..."
          : mergeRequests.length === 0
            ? "No open merge requests."
            : normalizedSearchQuery
              ? `${filteredMergeRequests.length} of ${mergeRequests.length} open`
              : `${mergeRequests.length} open`}
      </p>
      <Button
        size="sm"
        type="button"
        variant="outline"
        onClick={onRefresh}
        disabled={isLoading || isRefreshing}
      >
        {isRefreshing ? (
          <>
            <Loader2 className="size-3.5 animate-spin" />
            Refreshing…
          </>
        ) : (
          "Refresh"
        )}
      </Button>
    </div>

    {error ? (
      <p className="text-sm text-destructive">{error}</p>
    ) : null}

    {!isLoading && mergeRequests.length > 0 ? (
      <Input
        id="merge-request-search"
        value={searchQuery}
        onChange={(event) => setSearchQuery(event.target.value)}
        placeholder="Search merge requests..."
      />
    ) : null}

    {!isLoading && filteredMergeRequests.length > 0 ? (

  {(mr.reviewRequestedFromCurrentUser || mr.assignedToCurrentUser || mr.authoredByCurrentUser) ? (
    <div className="flex flex-wrap gap-1.5">
      {mr.reviewRequestedFromCurrentUser ? (
        <Badge variant="outline" className="text-[10px] px-1.5 py-0">Review requested</Badge>
      ) : null}
      {mr.assignedToCurrentUser ? (
        <Badge variant="outline" className="text-[10px] px-1.5 py-0">Assigned</Badge>
      ) : null}
      {mr.authoredByCurrentUser ? (
        <Badge variant="outline" className="text-[10px] px-1.5 py-0">Authored by you</Badge>
      ) : null}
    </div>
  ) : null}
</div>

import { describe, expect, test } from "bun:test"

const loadNormalizer = async (allowPrivateHosts?: string) => {
  const previous = process.env.GITLAB_ALLOW_PRIVATE_HOSTS
  if (allowPrivateHosts === undefined) {
    delete process.env.GITLAB_ALLOW_PRIVATE_HOSTS
  } else {
    process.env.GITLAB_ALLOW_PRIVATE_HOSTS = allowPrivateHosts
  }

  try {
    const mod = await import(`./instance.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
    return mod.normalizeGitLabInstanceUrl as (input: string) => string
  } finally {
    if (previous === undefined) {
      delete process.env.GITLAB_ALLOW_PRIVATE_HOSTS
    } else {
      process.env.GITLAB_ALLOW_PRIVATE_HOSTS = previous
    }
  }
}

describe("normalizeGitLabInstanceUrl", () => {
  test("normalizes valid public URLs", async () => {
    const normalize = await loadNormalizer()

    expect(normalize("gitlab.com/")).toBe("https://gitlab.com")
    expect(normalize("https://gitlab.com/group/project/?foo=bar#frag")).toBe(
      "https://gitlab.com/group/project",
    )
  })

  test("rejects credentials and private hosts by default", async () => {
    const normalize = await loadNormalizer()

    expect(() => normalize("https://")).toThrow("GitLab instance URL is invalid.")
    expect(() => normalize("https://user:pass@gitlab.com")).toThrow(
      "GitLab instance URL must not include credentials.",
    )
    expect(() => normalize("http://localhost:3000")).toThrow(
      "GitLab instance URL must use a public host.",
    )
    expect(() => normalize("http://127.0.0.1:3000")).toThrow(
      "GitLab instance URL must use a public host.",
    )
    expect(() => normalize("http://192.168.1.10")).toThrow(
      "GitLab instance URL must use a public host.",
    )
  })

  test("allows private hosts when explicitly enabled", async () => {
    const normalize = await loadNormalizer("1")
    expect(normalize("http://localhost:3000")).toBe("http://localhost:3000")
  })
})

