import { describe, expect, test } from "bun:test"
import type { NextRequest } from "next/server"

import { proxy } from "./proxy"

const buildRequest = (path: string, cookieHeader?: string) => {
  const url = `http://localhost${path}`
  return {
    url,
    headers: new Headers(cookieHeader ? { cookie: cookieHeader } : undefined),
    nextUrl: new URL(url),
  } as NextRequest
}

describe("proxy auth routing", () => {
  test("redirects unauthenticated protected routes to root with next", () => {
    const response = proxy(buildRequest("/repos/abc"))

    expect(response.status).toBe(307)
    expect(response.headers.get("location")).toBe("http://localhost/?next=%2Frepos%2Fabc")
  })

  test("does not redirect unauthenticated onboarding routes", () => {
    const response = proxy(buildRequest("/onboarding/tokens"))

    expect(response.status).toBe(200)
    expect(response.headers.get("location")).toBeNull()
  })

  test("does not redirect unauthenticated docs routes", () => {
    const response = proxy(buildRequest("/docs/getting-started"))

    expect(response.status).toBe(200)
    expect(response.headers.get("location")).toBeNull()
  })

  test("allows authenticated protected routes", () => {
    const response = proxy(buildRequest("/repos/abc", "better-auth.session_token=token"))

    expect(response.status).toBe(200)
    expect(response.headers.get("location")).toBeNull()
  })
})

