const argusSummary: EngineSummary = { name: 'argus-ci', warmup: [], measured: [] }
const grepaiSummary: EngineSummary = { name: 'grepai', warmup: [], measured: [] }

function runArgusPass(passIndex: number): RunResult {
  cleanArgusStore(argusStorePath)
  if (argusQueryCacheMode === 'cold') {
    fs.rmSync(argusQueryCachePath(argusStorePath), { force: true })
  }
  if (!dryRun) {
    applyPhasesToArgusConfig(argusConfigPath, argusPhaseConfig)
  }

  const watchArgs = ['--config', argusConfigPath, '--store', argusStorePath, 'watch', '--once']
  if (argusWatchSupportsPhases) {
    watchArgs.push('--phases', argusPhases)
  }
  if (argusCheckpointWarmup === 'off') {
    watchArgs.push('--no-checkpoint-warmup')
  }
  const indexRun = runCommand(argusBin, watchArgs, { cwd: argusRoot, timeoutMs, dryRun })

  const queryMs: number[] = []
  const queryHitCounts: number[] = []
  for (const query of queries) {
    const searchRun = runCommand(
      argusBin,
      ['--config', argusConfigPath, '--store', argusStorePath, 'search', query, '--top-k', String(topK), '--json'],
      { cwd: argusRoot, timeoutMs, dryRun },
    )
    queryMs.push(searchRun.durationMs)
    queryHitCounts.push(maybeParseHitCount(searchRun.stdout))
  }
  const impactQueryMs: number[] = []
  const impactHitCounts: number[] = []

}

function resetGrepaiProject() {
  fs.rmSync(path.join(grepaiRoot, '.grepai'), { recursive: true, force: true })
