function runGrepaiPass(passIndex: number): RunResult {
  runCommand(grepaiBin, ['watch', '--stop'], { cwd: grepaiRoot, timeoutMs, allowFailure: true, dryRun })
  resetGrepaiProject()

  const indexRun = runCommandWithRetries(
    grepaiBin,
    ['watch', '--background'],
    { cwd: grepaiRoot, timeoutMs, dryRun },
    2,
    'grepai watch --background failed, retrying startup',
    () => {
      runCommand(grepaiBin, ['watch', '--stop'], { cwd: grepaiRoot, timeoutMs, allowFailure: true, dryRun })
