  const queryHitCounts: number[] = []
  for (const query of queries) {
    const searchRun = runCommand(grepaiBin, ['search', query, '--json', '--compact', '--limit', String(topK)], {
      cwd: grepaiRoot,
      timeoutMs,
      dryRun,
    })
    queryMs.push(searchRun.durationMs)
    queryHitCounts.push(maybeParseHitCount(searchRun.stdout))
  }
  const impactQueryMs: number[] = []
  const impactHitCounts: number[] = []

