    const impactRun = runCommand(grepaiBin, traceArgs, {
      cwd: grepaiRoot,
      timeoutMs,
      dryRun,
    })
    impactQueryMs.push(impactRun.durationMs)
    impactHitCounts.push(maybeParseImpactCount(impactRun.stdout))
  }
}

runCommand(grepaiBin, ['watch', '--stop'], { cwd: grepaiRoot, timeoutMs, allowFailure: true, dryRun })

