  indexMs: indexRun.durationMs,
  searchMs,
  queryMs,
  queryHitCounts,
  impactMs,
  impactQueryMs,
  impactHitCounts,
}
const label = passIndex <= warmup ? `warmup ${passIndex}` : `run ${passIndex - warmup}`
const impactText = includeImpact ? ` impact=${run.impactMs.toFixed(2)}ms` : ''
console.log(
  `[grepai] ${label.padEnd(10)} index=${run.indexMs.toFixed(2)}ms search=${run.searchMs.toFixed(2)}ms${impactText}`,
)
return run

