  const argusImpact = argusSummary.measured.map((run) => run.impactMs)
  const grepaiIndex = grepaiSummary.measured.map((run) => run.indexMs)
  const grepaiSearch = grepaiSummary.measured.map((run) => run.searchMs)
  const grepaiImpact = grepaiSummary.measured.map((run) => run.impactMs)

  const report = {
    generatedAt: new Date().toISOString(),
    host: {
      platform: os.platform(),
      arch: os.arch(),
      cpus: os.cpus().length,
      node: process.version,
    },
    sourceProjectRoot: projectRoot,
    workdirs: {
      root: benchRoot,
      argus: argusRoot,
      grepai: grepaiRoot,
    },

} finally {
  stopMockEmbeddingsServer(mockEmbeddingsServer)
  if (!keepWorkdirs && !dryRun) {
    fs.rmSync(benchRoot, { recursive: true, force: true })
  } else {
    console.log(`workdirs kept at: ${benchRoot}`)
  }
}

