import {
  getFreshGitLabIntegrationsQueryData,
  hydrateGitLabIntegrationsQuery,
  type GitLabIntegrationQueryRow,
  invalidateGitLabIntegrationsQuery,
  loadGitLabIntegrations,
} from "@/lib/gitlab/client-integrations-query"
import { parseJsonResponse } from "@/lib/http/response-json"
import {
  markRouteNavigationStart,
  prefetchRouteOnce,
} from "@/lib/navigation/perf-navigation"

type AppSidebarProps = React.ComponentProps<typeof Sidebar> & {
  isAdmin: boolean
  initialGitLabIntegrations: GitLabIntegrationQueryRow[] | null
}

const REPO_PREWARM_MR_LIMIT = 100
const REPO_PREWARM_RUN_LIMIT = 4
const REPO_PREWARM_TTL_MS = 45_000

const toReviewProjects = (integrations: readonly GitLabIntegrationQueryRow[]): ReviewProject[] =>
  integrations.map((integration) => ({
    id: integration.id,
    instanceUrl: integration.instanceUrl,
    projectId: integration.projectId,
    projectPath: integration.projectPath,
    projectName: integration.projectName,
    status: integration.status,
    updatedAt: integration.updatedAt,
  })).sort((left, right) => asDateValue(right.updatedAt) - asDateValue(left.updatedAt))

export function AppSidebar({ isAdmin, initialGitLabIntegrations, ...props }: AppSidebarProps) {
  const { isMobile } = useSidebar()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const router = useRouter()
  const [activeTool, setActiveTool] = React.useState<ToolId>("review-agent")
  const [reviewProjects, setReviewProjects] = React.useState<ReviewProject[]>(() =>
    toReviewProjects(initialGitLabIntegrations ?? []),
  )

const [projectsState, setProjectsState] = React.useState<"idle" | "loading" | "ready" | "error">(
  initialGitLabIntegrations ? "ready" : "idle",
)
const [discoverableProjects, setDiscoverableProjects] = React.useState<DiscoverableProject[]>([])
const [discoverProjectsState, setDiscoverProjectsState] = React.useState<
  "idle" | "loading" | "ready" | "error"
>("idle")
const [discoverProjectsStatus, setDiscoverProjectsStatus] = React.useState("")
const [isConnectingDiscoverableProject, setIsConnectingDiscoverableProject] = React.useState(false)
const [projectsReloadNonce, setProjectsReloadNonce] = React.useState(0)
const forceProjectsRefreshNonceRef = React.useRef<number | null>(null)
const discoverableProjectsCacheRef = React.useRef<Map<string, DiscoverableProjectsCacheEntry>>(new Map())
const prefetchedSidebarRoutesRef = React.useRef<Set<string>>(new Set())
const [isRepoDialogOpen, setIsRepoDialogOpen] = React.useState(false)
const [hasOpenedRepoDialog, setHasOpenedRepoDialog] = React.useState(false)
const repoDataPrewarmExpiryRef = React.useRef<Map<string, number>>(new Map())
const repoDataPrewarmInFlightRef = React.useRef<Set<string>>(new Set())

const availableTools = React.useMemo(
  () =>
    TOOLS.filter((tool) =>
      tool.id === "analytics" || tool.id === "admin" ? isAdmin : true,
    ),
  [isAdmin],
)
const defaultToolId = availableTools[0]?.id ?? "review-agent"

const clearRepoDialogCaches = React.useCallback(() => {
  discoverableProjectsCacheRef.current.clear()
}, [])

const prefetchSidebarRoute = React.useCallback((href: string) => {
  prefetchRouteOnce({
    href,
    prefetchedHrefs: prefetchedSidebarRoutesRef.current,
    prefetch: router.prefetch,
  })
}, [router])

const prewarmRepoData = React.useCallback((project: ReviewProject) => {
  const now = Date.now()
  const cachedUntil = repoDataPrewarmExpiryRef.current.get(project.id) ?? 0
  if (cachedUntil > now || repoDataPrewarmInFlightRef.current.has(project.id)) {
    return
  }

  repoDataPrewarmInFlightRef.current.add(project.id)
  void Promise.allSettled([
    fetch("/api/gitlab", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        action: "merge-requests",
        instanceUrl: project.instanceUrl,
        integrationId: project.id,
        projectId: project.projectId,
        perPage: REPO_PREWARM_MR_LIMIT,
      }),
    }).then((response) => response.ok),
    fetch(
      `/api/gitlab/integrations/${encodeURIComponent(project.id)}/index/runs?page=1&limit=${REPO_PREWARM_RUN_LIMIT}`,
      {
        method: "GET",
        headers: { "content-type": "application/json" },
      },
    ).then((response) => response.ok),
  ])
    .then((results) => {
      const succeeded = results.some(
        (result) => result.status === "fulfilled" && result.value,
      )
      repoDataPrewarmExpiryRef.current.set(
        project.id,
        Date.now() + (succeeded ? REPO_PREWARM_TTL_MS : 5_000),
      )
    })
    .catch(() => {
      repoDataPrewarmExpiryRef.current.set(project.id, Date.now() + 5_000)
    })
    .finally(() => {
      repoDataPrewarmInFlightRef.current.delete(project.id)
    })
}, [])

const projectByRepoHref = React.useMemo(() => {
  const map = new Map<string, ReviewProject>()
  for (const project of reviewProjects) {
    map.set(buildRepoPath(project), project)
  }
  return map
}, [reviewProjects])

const prewarmRepoForHref = React.useCallback((href: string) => {
  const routePath = href.split("?")[0]?.trim() ?? ""
  if (!routePath) {
    return
  }

  const project = projectByRepoHref.get(routePath)
  if (!project) {
    return
  }

  prewarmRepoData(project)
}, [prewarmRepoData, projectByRepoHref])

const navigate = React.useCallback((href: string, source: string) => {
  prefetchSidebarRoute(href)
  markRouteNavigationStart({ href, source })
  router.push(href)
}, [prefetchSidebarRoute, router])

const getSidebarLinkProps = React.useCallback((href: string) => ({
  onMouseEnter: () => {
    prefetchSidebarRoute(href)
    prewarmRepoForHref(href)
  },
  onFocus: () => {
    prefetchSidebarRoute(href)
    prewarmRepoForHref(href)
  },
  onClick: () => {
    prewarmRepoForHref(href)
    markRouteNavigationStart({ href, source: "sidebar" })
  },
}), [prefetchSidebarRoute, prewarmRepoForHref])

const handleReloadProjects = React.useCallback((options?: ReloadProjectsOptions) => {
  setProjectsReloadNonce((current) => {
    const nextNonce = current + 1
    if (options?.forceRefresh === true) {
      forceProjectsRefreshNonceRef.current = nextNonce
    }
    return nextNonce
  })
}, [])

const handleOpenRepoDialog = React.useCallback(() => {
  setHasOpenedRepoDialog(true)
  setIsRepoDialogOpen(true)
}, [])

const handleOpenRepo = React.useCallback(
  (project: ReviewProject) => {
    setIsRepoDialogOpen(false)
    prewarmRepoData(project)
    navigate(buildRepoPath(project), "sidebar")
  },
  [navigate, prewarmRepoData],
)

const handleOpenConnectSettings = React.useCallback(() => {
  setIsRepoDialogOpen(false)
  navigate("/settings?tab=gitlab", "sidebar")
}, [navigate])

const instanceSeeds = React.useMemo<InstanceSeed[]>(() => {
  const uniqueByInstance = new Map<string, InstanceSeed>()
  for (const project of reviewProjects) {
    if (uniqueByInstance.has(project.instanceUrl)) {
      continue
    }
    uniqueByInstance.set(project.instanceUrl, {
      instanceUrl: project.instanceUrl,
      integrationId: project.id,
    })
  }
  return [...uniqueByInstance.values()]
}, [reviewProjects])

const loadDiscoverableProjects = React.useCallback(async (options?: ReloadProjectsOptions) => {
  if (instanceSeeds.length === 0) {
    setDiscoverableProjects([])
    setDiscoverProjectsState("ready")
    setDiscoverProjectsStatus("")
    return
  }

  const shouldForceRefresh = options?.forceRefresh === true
  const seedKey = buildInstanceSeedCacheKey(instanceSeeds)
  const scopeKey = buildDiscoverableProjectsScopeKey(reviewProjects)
  const cacheKey = `${scopeKey}##${seedKey}`

const connectedKeys = new Set(
  reviewProjects.map((project) => buildProjectScopeKey(project.instanceUrl, project.projectId)),
)

const toVisibleDiscoverableProjects = (projects: DiscoverableProject[]) => {
  const discovered = new Map<string, DiscoverableProject>()
  for (const project of projects) {
    const projectKey = buildProjectScopeKey(project.instanceUrl, project.projectId)
    if (connectedKeys.has(projectKey) || discovered.has(projectKey)) {
      continue
    }
    discovered.set(projectKey, project)
  }

  return [...discovered.values()].sort((left, right) =>
    left.projectPath.localeCompare(right.projectPath),
  )
}

if (!shouldForceRefresh) {
  const cached = getFreshDiscoverableProjectsCache(discoverableProjectsCacheRef.current, cacheKey)
  if (cached) {
    const cachedResult = getDiscoverProjectsResult(cached.failureCount, cached.instanceCount)
    setDiscoverableProjects(toVisibleDiscoverableProjects(cached.projects))
    setDiscoverProjectsState(cachedResult.state)
    setDiscoverProjectsStatus(cachedResult.status)
    return
  }
}

setDiscoverProjectsState("loading")
setDiscoverProjectsStatus("")

const resultByInstance = await Promise.allSettled(
  instanceSeeds.map(async (seed) => {
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action: "projects",
        instanceUrl: seed.instanceUrl,
        integrationId: seed.integrationId,
        perPage: 100,
        forceRefresh: shouldForceRefresh,
      }),
    })

    const parsedPayload = await parseJsonResponse(response)
    const payload = parsedPayload.ok ? parsedPayload.value : null
    if (!response.ok) {
      throw new Error(
        getApiErrorMessage(payload, "Failed to load repositories from connected instances."),
      )
    }

    const rows =
      isRecord(payload) && Array.isArray(payload.data)
        ? payload.data
        : []

    return rows.flatMap((row) => {
      if (!isRecord(row)) {
        return []
      }
      if (typeof row.id !== "string" || typeof row.path !== "string") {
        return []
      }

      const projectName =
        typeof row.name === "string" && row.name.trim().length > 0
          ? row.name
          : row.path

      return [{
        instanceUrl: seed.instanceUrl,
        integrationId: seed.integrationId,
        projectId: row.id,
        projectPath: row.path,
        projectName,
      }]
    })
  }),
)

  const discovered = new Map<string, DiscoverableProject>()
  let failureCount = 0

  for (const result of resultByInstance) {
    if (result.status === "rejected") {
      failureCount += 1
      continue
    }

    for (const project of result.value) {
      const projectKey = buildProjectScopeKey(project.instanceUrl, project.projectId)
      if (discovered.has(projectKey)) {
        continue
      }
      discovered.set(projectKey, project)
    }
  }

  const discoveredProjects = [...discovered.values()]
  const discoverResult = getDiscoverProjectsResult(failureCount, instanceSeeds.length)

  if (failureCount !== instanceSeeds.length) {
    setDiscoverableProjectsCache(
      discoverableProjectsCacheRef.current,
      cacheKey,
      seedKey,
      discoveredProjects,
      failureCount,
      instanceSeeds.length,
    )
  }

  setDiscoverableProjects(toVisibleDiscoverableProjects(discoveredProjects))
  setDiscoverProjectsState(discoverResult.state)
  setDiscoverProjectsStatus(discoverResult.status)
}, [instanceSeeds, reviewProjects])

const handleConnectDiscoverableProject = React.useCallback(
  async (project: DiscoverableProject) => {
    if (isConnectingDiscoverableProject) {
      return
    }

    setIsConnectingDiscoverableProject(true)
    setDiscoverProjectsStatus("")

try {
  const response = await fetch("/api/gitlab/integrations/connect", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      instanceUrl: project.instanceUrl,
      integrationId: project.integrationId,
      projectId: project.projectId,
      projectPath: project.projectPath,
      projectName: project.projectName,
    }),
  })

  const parsedPayload = await parseJsonResponse(response)
  const payload = parsedPayload.ok ? parsedPayload.value : null
  if (!response.ok) {
    throw new Error(getApiErrorMessage(payload, "Failed to connect repository."))
  }

  const integration = isRecord(payload) && isRecord(payload.data) ? payload.data : null
  if (
    !integration ||
    typeof integration.id !== "string" ||
    typeof integration.instanceUrl !== "string" ||
    typeof integration.projectId !== "string" ||
    typeof integration.projectPath !== "string"
  ) {
    throw new Error("Connect response is missing repository details.")
  }

  invalidateGitLabIntegrationsQuery()
  clearRepoDialogCaches()
  handleReloadProjects({ forceRefresh: true })
  setIsRepoDialogOpen(false)
  navigate(buildRepoPath({
    id: integration.id,
    instanceUrl: integration.instanceUrl,
    projectId: integration.projectId,
    projectPath: integration.projectPath,
  }), "sidebar")
} catch (error) {

      setDiscoverProjectsStatus(
        error instanceof Error ? error.message : "Failed to connect repository.",
      )
    } finally {
      setIsConnectingDiscoverableProject(false)
    }
  },
  [clearRepoDialogCaches, handleReloadProjects, isConnectingDiscoverableProject, navigate],
)

const handleRefreshRepoDialog = React.useCallback(() => {
  invalidateGitLabIntegrationsQuery()
  clearRepoDialogCaches()
  handleReloadProjects({ forceRefresh: true })
  void loadDiscoverableProjects({ forceRefresh: true })
}, [clearRepoDialogCaches, handleReloadProjects, loadDiscoverableProjects])

const handleSelectTool = React.useCallback(
  (toolId: ToolId) => {
    setActiveTool(toolId)

    if (toolId === "observability") {
      if (!pathname.startsWith("/observability")) {
        navigate("/observability", "sidebar")
      }
      return
    }

    if (toolId === "analytics") {
      if (!pathname.startsWith("/analytics")) {
        navigate("/analytics", "sidebar")
      }
      return
    }

    if (toolId === "admin") {
      if (!pathname.startsWith("/admin")) {
        navigate("/admin/users", "sidebar")
      }
      return
    }

    if (toolId === "sldc-flow") {
      if (!pathname.startsWith("/sldc-flow")) {
        navigate("/sldc-flow", "sidebar")
      }
      return
    }

    if (
      toolId === "review-agent" &&
      (
        pathname.startsWith("/observability") ||
        pathname.startsWith("/analytics") ||
