import { spawnSync } from "node:child_process"
import { existsSync, readdirSync, readFileSync } from "node:fs"
import path from "node:path"

const [, , scriptName, ...args] = process.argv

if (!scriptName) {
  console.error(
    "[workspace-runner] usage: bun run scripts/run-workspace-script.mjs <script> [--scope=all|apps|shared|declared]",
  )
  process.exit(1)
}

const scopeArg = args.find((arg) => arg.startsWith("--scope="))
const scope = scopeArg ? scopeArg.slice("--scope=".length) : "all"

if (!["all", "apps", "shared", "declared"].includes(scope)) {
  console.error(`[workspace-runner] unsupported scope: ${scope}`)
  process.exit(1)
}

const rootDir = process.cwd()

const toPosixPath = (value) => value.split(path.sep).join("/")

const readRootWorkspacePatterns = () => {
  const rootPackageJsonPath = path.join(rootDir, "package.json")
  if (!existsSync(rootPackageJsonPath)) {
    console.error("[workspace-runner] root package.json was not found")
    process.exit(1)
  }

  const rootPackageJson = JSON.parse(readFileSync(rootPackageJsonPath, "utf8"))
  const patterns = rootPackageJson.workspaces
  if (!Array.isArray(patterns) || patterns.some((entry) => typeof entry !== "string")) {
    console.error("[workspace-runner] package.json#workspaces must be an array of glob strings")
    process.exit(1)
  }
  return patterns.map((pattern) => pattern.trim()).filter((pattern) => pattern.length > 0)
}

const resolveWorkspacePattern = (pattern) => {
  const segments = toPosixPath(pattern)
    .replace(/\/+$/, "")
    .split("/")
    .filter((segment) => segment.length > 0)

  if (segments.length === 0) {
    return []
  }

  const matches = []

  const walk = (cursor, index) => {
    if (index >= segments.length) {
      if (existsSync(path.join(cursor, "package.json"))) {
        matches.push(cursor)
      }
      return
    }

    const segment = segments[index]
    if (segment === "*") {
      if (!existsSync(cursor)) {
        return
      }

      const entries = readdirSync(cursor, { withFileTypes: true })
      for (const entry of entries) {
        if (!entry.isDirectory()) {
          continue
        }
        walk(path.join(cursor, entry.name), index + 1)
      }
      return
    }

    const nextCursor = path.join(cursor, segment)
    if (!existsSync(nextCursor)) {
      return
    }
    walk(nextCursor, index + 1)
  }

  walk(rootDir, 0)
  return matches
}

const workspacePatternMatches = readRootWorkspacePatterns().flatMap(resolveWorkspacePattern)

const workspaceDirSet = new Set()
const workspaceDescriptors = []

for (const packageDir of workspacePatternMatches) {
  if (workspaceDirSet.has(packageDir)) {
    continue
  }
  workspaceDirSet.add(packageDir)

  const packageJson = JSON.parse(readFileSync(path.join(packageDir, "package.json"), "utf8"))
  const relativePath = toPosixPath(path.relative(rootDir, packageDir))
  const isAppWorkspace = relativePath.startsWith("apps/")
  const isPrivatePackageWorkspace = relativePath.startsWith("packages/") && packageJson.private === true

  workspaceDescriptors.push({
    packageDir,
    packageJson,
    relativePath,
    isInScope:
      scope === "declared"
        ? true
        : scope === "apps"
          ? isAppWorkspace
          : scope === "shared"
            ? isPrivatePackageWorkspace
            : isAppWorkspace || isPrivatePackageWorkspace,
  })
}

const TEST_FILE_PATTERN = /(\.test\.|_test_|\.spec\.|_spec_)/
const TEST_SCAN_SKIP_DIRS = new Set(["node_modules", ".git", ".next", "dist", "build", "coverage"])

const hasTestFiles = (dirPath) => {
  const entries = readdirSync(dirPath, { withFileTypes: true })
  for (const entry of entries) {
    if (entry.isDirectory()) {
      if (TEST_SCAN_SKIP_DIRS.has(entry.name)) {
        continue
      }
      if (hasTestFiles(path.join(dirPath, entry.name))) {
        return true
      }
      continue
    }

    if (TEST_FILE_PATTERN.test(entry.name)) {
      return true
    }
  }

  return false
}

const workspaceDirs = workspaceDescriptors
  .filter((descriptor) => descriptor.isInScope)
  .map((descriptor) => descriptor.packageDir)
  .sort((left, right) => left.localeCompare(right))

let runCount = 0

for (const packageDir of workspaceDirs) {
  const packageJson = JSON.parse(readFileSync(path.join(packageDir, "package.json"), "utf8"))
  const scripts = packageJson.scripts ?? {}
  if (!scripts[scriptName]) {
    continue
  }

  if (scriptName === "test" && !hasTestFiles(packageDir)) {
    const displayName = packageJson.name ?? path.relative(rootDir, packageDir)
    console.log(
      `\n[workspace-runner] skipping ${displayName} (${path.relative(rootDir, packageDir)}) - no test files found`,
    )
    continue
  }

  runCount += 1
  const displayName = packageJson.name ?? path.relative(rootDir, packageDir)
  console.log(`\n[workspace-runner] ${displayName} (${path.relative(rootDir, packageDir)})`)
  console.log(`[workspace-runner] bun run ${scriptName}`)

  const result = spawnSync("bun", ["run", scriptName], {
    cwd: packageDir,
    stdio: "inherit",
    env: process.env,
  })

  if ((result.status ?? 1) !== 0) {
    process.exit(result.status ?? 1)
  }
}

if (runCount === 0) {
  console.error(`[workspace-runner] no workspace packages expose script "${scriptName}" for scope "${scope}"`)
  process.exit(1)
}

console.log(`\n[workspace-runner] completed "${scriptName}" in ${runCount} package(s).`)

