import type { ArtifactStore } from '@argus/contracts-indexing'
import { createFsArtifactStore } from '@/lib/indexing/stores/artifact-store.fs'
import { createS3ArtifactStore } from '@/lib/indexing/stores/artifact-store.s3'

type ArtifactBackend = 'fs' | 's3'

export const resolveArtifactBackend = (): ArtifactBackend => {
  const configured = process.env.INDEXER_ARTIFACTS_BACKEND?.trim().toLowerCase()
  if (!configured) {
    return 's3'
  }

  if (configured === 'fs' || configured === 's3') {
    return configured
  }

  throw new Error(
    `Invalid INDEXER_ARTIFACTS_BACKEND value "${configured}". Expected "fs" or "s3".`,
  )
}

export const createArtifactStore = (): ArtifactStore => {
  const backend = resolveArtifactBackend()
  if (backend === 's3') {
    return createS3ArtifactStore()
  }

  return createFsArtifactStore()
}

import { NextResponse } from "next/server"

import { requireJsonBody } from "@/lib/http/request-json"
import { cancelReviewFlowRunByTraceId } from "@/lib/review/flow-run"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

type CancelReviewPayload = {
  traceId?: unknown
}

const asOptionalString = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/diff/cancel",
    event: "api.review.diff.cancel",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "traceId is required."),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const payload = body.value as CancelReviewPayload | null
      const traceId = asOptionalString(payload?.traceId)
      if (!traceId) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "traceId is required." }, { status: 400 }),
        }
      }

      const result = await cancelReviewFlowRunByTraceId({
        userId,
        traceId,
        message: "AI review cancelled by user.",
      })

      logger.set({
        traceId,
        cancelled: result.cancelled,
        flowRunId: result.flowRunId,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            traceId,
            cancelled: result.cancelled,
          },
        }),
      }
    },
  })
}

