}

const resolveWindow = (args: { sinceRaw?: string; untilRaw?: string; windowHours: number }) => {
  const now = new Date()
  const until = args.untilRaw ? new Date(args.untilRaw) : now
  if (Number.isNaN(until.getTime())) {
    return { error: "Invalid until date." as const, since: null, until: null }
  }
  const since = args.sinceRaw
    ? new Date(args.sinceRaw)
    : new Date(until.getTime() - args.windowHours * 60 * 60 * 1_000)
  if (Number.isNaN(since.getTime())) {
    return { error: "Invalid since date." as const, since: null, until: null }
  }
  if (until.getTime() < since.getTime()) {
    return { error: "until cannot be before since." as const, since: null, until: null }
  }
  return { error: null, since, until }
}

const createAccumulator = (traceId: string, flowRun?: AiReviewFlowRunRow): AiRunAccumulator => ({
  traceId,
  reviewId: flowRun?.reviewId ?? null,
  status: flowRun?.status ?? "in_progress",
  statusSource: flowRun ? "flow" : "derived",
  personaMode: normalizeReviewPersonaMode(flowRun?.personaMode),
  persona: normalizeReviewPersona(flowRun?.persona),
  personaPasses: (() => {
    const mode = normalizeReviewPersonaMode(flowRun?.personaMode)
    const persona = normalizeReviewPersona(flowRun?.persona)
    const resolved = asStringArray(flowRun?.personaPasses).map((value) =>
      normalizeReviewPersona(value),
    )
    if (mode === "disabled") {
      return [] as Array<"generalist" | "security" | "performance" | "maintainability">
    }
    if (mode === "multi") {
      return (resolved.length > 0 ? resolved : ["generalist", "security", "performance", "maintainability"])
    }
    return [persona]
  })(),
  personaExecutionStrategy: resolveReviewPersonaExecutionStrategy(
    normalizeReviewPersonaMode(flowRun?.personaMode),
  ),
  startedAt: flowRun?.startedAt ?? null,
  finishedAt: flowRun ? (flowRun.finishedAt ?? flowRun.lastEventAt) : null,
  totalEvents: 0,
  diffCalls: 0,
  saveCalls: 0,
  findingsCount: null,
  suppressedFindingsCount: 0,
  llmRequests: 0,
  promptTokens: 0,
  completionTokens: 0,
  totalTokens: 0,
  toolCallCount: 0,
  latestProvider: null,
  latestModel: null,
  hasError: flowRun ? (flowRun.status === "failed" || Boolean(flowRun.latestError)) : false,
  hasSaveSuccess: flowRun ? flowRun.status === "success" : false,
  steps: [],
})

const applyTimestampToAccumulator = (run: AiRunAccumulator, timestamp: Date) => {
  if (!run.startedAt || timestamp.getTime() < run.startedAt.getTime()) {
    run.startedAt = timestamp
  }
  if (!run.finishedAt || timestamp.getTime() > run.finishedAt.getTime()) {
    run.finishedAt = timestamp
  }
}

const applyLogRowToAccumulator = (run: AiRunAccumulator, row: AiRunLogRow) => {
  applyTimestampToAccumulator(run, row.timestamp)

  run.totalEvents += 1
  if (row.event === "api.review.diff") {
    run.diffCalls += 1
  }
  if (row.event === "api.review.save") {
    run.saveCalls += 1
  }

  if (row.level === "error" || (row.status !== null && row.status >= 400)) {
    run.hasError = true
  }
  if (row.event === "api.review.save" && row.status !== null && row.status >= 200 && row.status < 300) {
    run.hasSaveSuccess = true
  }

  const payload = asSafePayload(row.payload)
  const llmMetrics = asRecord(payload.llmMetrics)
  const llmTrace = asRecord(payload.llmTrace)
  const labels = asRecord(payload.labels)
  const reviewId = asString(payload.reviewId)
  if (!run.reviewId && reviewId) {
    run.reviewId = reviewId
  }

  run.llmRequests += asInt(llmMetrics?.requestCount)
  run.promptTokens += asInt(llmMetrics?.promptTokens)
  run.completionTokens += asInt(llmMetrics?.completionTokens)
  run.totalTokens += asInt(llmMetrics?.totalTokens)
  run.toolCallCount += asInt(llmTrace?.toolCallCount)

  const findingsCount = asNullableInt(payload.findingsCount)

  if (findingsCount !== null) {
    run.findingsCount = run.findingsCount === null
      ? findingsCount
      : Math.max(run.findingsCount, findingsCount)
  }
  run.suppressedFindingsCount = Math.max(
    run.suppressedFindingsCount,
    asInt(payload.suppressedFindingsCount),
  )

  const provider = asString(labels?.provider) ?? asString(llmMetrics?.provider)
  const model = asString(labels?.model) ?? asString(llmMetrics?.model) ?? asString(payload.model)
  if (!run.latestProvider && provider) {
    run.latestProvider = provider
  }
  if (!run.latestModel && model) {
    run.latestModel = model
  }

  run.steps.push({
    id: row.id,
    timestamp: row.timestamp.toISOString(),
    level: row.level,
    event: row.event,
    path: row.path,
    status: row.status,
    durationMs: row.durationMs,
    payload,
  })
}

const applyFlowEventRowToAccumulator = (run: AiRunAccumulator, row: AiReviewFlowEventRow) => {
  applyTimestampToAccumulator(run, row.createdAt)

  run.totalEvents += 1
  if (row.eventType === "failed") {
    run.hasError = true
  }
  if (row.eventType === "done") {
