const fallbackLlmTrace = (() => {
  const parsedFindingsCount = asNullableInt(payload.parsedFindingsCount)
  const reconciledFindingsCount = asNullableInt(payload.reconciledFindingsCount)
  const toolCallCount = asNullableInt(payload.toolCallCount)
