  if (reconciledFindingsCount !== null) next.reconciledFindingsCount = reconciledFindingsCount
  if (toolCallCount !== null) next.toolCallCount = toolCallCount
  if (toolCalls.length > 0) next.toolCalls = toolCalls
  if (responsePreview) next.responsePreview = responsePreview
