const mergedPayload: Record<string, unknown> = {
  ...payload,
  reviewFlowStage: row.stage,
  reviewFlowEventType: row.eventType,
  reviewFlowMessage: asString(row.message),
  reviewBatchIndex,
  reviewTotalBatches,
  currentBatchFiles: batchFiles.length > 0 ? batchFiles : currentBatchFiles,
  batchFiles,
  outcome:
    row.eventType === "done"
      ? "success"
      : row.eventType === "failed"
        ? "failed"
        : "in_progress",
