  run.personaMode = normalizeReviewPersonaMode(payload.personaMode)
  run.personaExecutionStrategy = resolveReviewPersonaExecutionStrategy(run.personaMode)
}
if (Object.prototype.hasOwnProperty.call(payload, "persona")) {
  run.persona = normalizeReviewPersona(payload.persona)
}
if (Object.prototype.hasOwnProperty.call(payload, "personaPasses")) {
  const resolvedPasses = asStringArray(payload.personaPasses).map((entry) =>
    normalizeReviewPersona(entry),
  )
  if (run.personaMode === "disabled") {
    run.personaPasses = []
  } else if (run.personaMode === "multi") {
    run.personaPasses = resolvedPasses.length > 0
      ? resolvedPasses
      : ["generalist", "security", "performance", "maintainability"]
  } else {
    run.personaPasses = [run.persona]
  }
