  run.findingsCount = run.findingsCount === null
    ? findingsCount
    : Math.max(run.findingsCount, findingsCount)
}
run.suppressedFindingsCount = Math.max(
  run.suppressedFindingsCount,
  asInt(payload.suppressedFindingsCount),
)

