const promptTokens = asInt(payload.promptTokens) || asInt(normalizedLlmMetrics?.promptTokens)
const completionTokens = asInt(payload.completionTokens) || asInt(normalizedLlmMetrics?.completionTokens)
const totalTokens = asInt(payload.totalTokens) || asInt(normalizedLlmMetrics?.totalTokens)
const toolCallCount = asInt(payload.toolCallCount) || asInt(normalizedLlmTrace?.toolCallCount)

run.llmRequests = Math.max(run.llmRequests, requestCount)
run.promptTokens = Math.max(run.promptTokens, promptTokens)
run.completionTokens = Math.max(run.completionTokens, completionTokens)
run.totalTokens = Math.max(run.totalTokens, totalTokens)
run.toolCallCount = Math.max(run.toolCallCount, toolCallCount)

const provider = asString(payload.latestProvider) ?? asString(normalizedLlmMetrics?.provider)
const model = asString(payload.latestModel) ?? asString(normalizedLlmMetrics?.model)
if (!run.latestProvider && provider) {
  run.latestProvider = provider
