const loadReviewMap = async (userId: string, runs: Map<string, AiRunAccumulator>) => {
  const reviewIds = Array.from(
    new Set(
      Array.from(runs.values())
        .map((run) => run.reviewId)
        .filter((value): value is string => Boolean(value)),
    ),
  )
  if (reviewIds.length === 0) {
    return new Map<string, ObservabilityAiRunReview>()
  }

  const reviewRows = await db
    .select({
      id: aiReviewRuns.id,
      summary: aiReviewRuns.summary,
      findings: aiReviewRuns.findings,
      createdAt: aiReviewRuns.createdAt,
    })
    .from(aiReviewRuns)
    .where(
      and(
        eq(aiReviewRuns.userId, userId),
        inArray(aiReviewRuns.id, reviewIds),
      ),
    ) as ReviewRow[]

  return new Map(
    reviewRows.map((row) => [
      row.id,
      {
        id: row.id,
        summary: row.summary,
        findings: row.findings,
        createdAt: row.createdAt.toISOString(),
      },
    ]),
  )
}

const finalizeAccumulator = (
  run: AiRunAccumulator,
  reviewById: Map<string, ObservabilityAiRunReview>,
): ObservabilityAiRun => {
  if (run.statusSource === "derived") {
    if (run.hasError) {
      run.status = "failed"
    } else if (run.status === "in_progress" && run.hasSaveSuccess) {
      run.status = "success"
    }
  }

  const durationMs =
    run.startedAt && run.finishedAt
      ? Math.max(0, run.finishedAt.getTime() - run.startedAt.getTime())
      : null

  const steps = [...run.steps]
    .sort((left, right) => {
      const leftAt = left.timestamp ? new Date(left.timestamp).getTime() : 0
      const rightAt = right.timestamp ? new Date(right.timestamp).getTime() : 0
      return leftAt - rightAt
    })
    .slice(-30)

  return {
    traceId: run.traceId,
    status: run.status,
    personaMode: run.personaMode,
    persona: run.persona,
    personaPasses: run.personaPasses,
    personaExecutionStrategy: run.personaExecutionStrategy,
    startedAt: toIso(run.startedAt),
    finishedAt: toIso(run.finishedAt),
    durationMs,
    totalEvents: run.totalEvents,
    diffCalls: run.diffCalls,
    saveCalls: run.saveCalls,
    findingsCount: run.findingsCount,
    suppressedFindingsCount: run.suppressedFindingsCount,
    llmRequests: run.llmRequests,
    promptTokens: run.promptTokens,
    completionTokens: run.completionTokens,
    totalTokens: run.totalTokens,
    toolCallCount: run.toolCallCount,
    latestProvider: run.latestProvider,
    latestModel: run.latestModel,
    review: run.reviewId ? (reviewById.get(run.reviewId) ?? null) : null,
    steps,
  }
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
