      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const url = new URL(request.url)
      const parsed = querySchema.safeParse({
        windowHours: url.searchParams.get("windowHours") ?? undefined,
        since: url.searchParams.get("since") ?? undefined,
        until: url.searchParams.get("until") ?? undefined,
        traceId: url.searchParams.get("traceId") ?? undefined,
        status: url.searchParams.get("status") ?? undefined,
        page: url.searchParams.get("page") ?? undefined,
        limit: url.searchParams.get("limit") ?? undefined,
      })
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid query params." }, { status: 400 }),
        }
      }

      const { error: windowError, since, until } = resolveWindow({
        sinceRaw: parsed.data.since,
        untilRaw: parsed.data.until,
        windowHours: parsed.data.windowHours,
      })

if (windowError || !since || !until) {
