    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: windowError ?? "Invalid window." }, { status: 400 }),
  }
}

const requestedPage = parsed.data.page
const limit = parsed.data.limit
let staleFlowRunsMarked = 0
let staleLeasesInProgress = 0

try {
  staleFlowRunsMarked = await markStaleReviewFlowRunsFailed({
    userId,
    staleAfterMs: REVIEW_FLOW_STALE_AFTER_MS,
  })
  const [staleLeaseRow] = await db
    .select({
      staleLeasesInProgress:
        sql<number>`count(*) filter (
          where ${aiReviewFlowRuns.status} = 'in_progress'
            and ${aiReviewFlowRuns.leaseExpiresAt} is not null
            and ${aiReviewFlowRuns.leaseExpiresAt} <= now()
        )`,
    })
    .from(aiReviewFlowRuns)
    .where(eq(aiReviewFlowRuns.userId, userId))
  staleLeasesInProgress = asInt(staleLeaseRow?.staleLeasesInProgress)

  const flowFilters = [
    eq(aiReviewFlowRuns.userId, userId),
    gte(aiReviewFlowRuns.startedAt, since),
    lte(aiReviewFlowRuns.startedAt, until),
    ...(parsed.data.traceId ? [eq(aiReviewFlowRuns.traceId, parsed.data.traceId)] : []),
    ...(parsed.data.status !== "all" ? [eq(aiReviewFlowRuns.status, parsed.data.status)] : []),
  ]
  const flowWhere = and(...flowFilters)

  flowEventRows = await db
    .select({
      id: aiReviewFlowEvents.id,
      traceId: aiReviewFlowEvents.traceId,
      stage: aiReviewFlowEvents.stage,
      eventType: aiReviewFlowEvents.eventType,
      message: aiReviewFlowEvents.message,
      payload: aiReviewFlowEvents.payload,
      createdAt: aiReviewFlowEvents.createdAt,
    })
    .from(aiReviewFlowEvents)
    .where(
      and(
        gte(aiReviewFlowEvents.createdAt, since),
        lte(aiReviewFlowEvents.createdAt, until),
        inArray(aiReviewFlowEvents.traceId, traceIds),
      ),
    )
    .orderBy(desc(aiReviewFlowEvents.createdAt), desc(aiReviewFlowEvents.id))
    .limit(flowEventSampleLimit) as AiReviewFlowEventRow[]
}

const runsByTraceId = new Map<string, AiRunAccumulator>()
for (const flowRow of flowRows) {
  runsByTraceId.set(flowRow.traceId, createAccumulator(flowRow.traceId, flowRow))
}

for (const row of rows) {
  const traceId = asString(row.requestId)
  if (!traceId) {
    continue
  }

  const run = runsByTraceId.get(traceId)
  if (!run) {
    continue
  }

  applyLogRowToAccumulator(run, row)
}

for (const flowEventRow of flowEventRows) {
  const traceId = asString(flowEventRow.traceId)
  if (!traceId) {
    continue
  }

  const run = runsByTraceId.get(traceId)
  if (!run) {
    continue
  }

  applyFlowEventRowToAccumulator(run, flowEventRow)
}

const reviewById = await loadReviewMap(userId, runsByTraceId)

const runs = flowRows
  .map((flowRow) => runsByTraceId.get(flowRow.traceId))
  .filter((run): run is AiRunAccumulator => Boolean(run))
  .map((run) => finalizeAccumulator(run, reviewById))

const payload: ObservabilityAiRunsPayload = {
  data: runs,
  meta: {
    page,
    limit,
    totalRuns,
    totalPages,
    hasNextPage: page < totalPages,
    hasPreviousPage: page > 1,
    sampleLimit,
    windowHours: parsed.data.windowHours,
    since: since.toISOString(),
    until: until.toISOString(),
    status: parsed.data.status,
    traceId: parsed.data.traceId ?? null,
    scannedRows: rows.length + flowEventRows.length,
    scannedRuns: flowRows.length,
    returnedRuns: runs.length,
    truncated: rows.length >= logSampleLimit || flowEventRows.length >= flowEventSampleLimit,
    staleFlowRunsMarked,
    staleLeasesInProgress,
  },
}

        logger.set({
          filters: parsed.data,
          staleFlowRunsMarked,
          staleLeasesInProgress,
          logSampleLimit,
          flowEventSampleLimit,
          sampleLimit,
          scannedRows: rows.length + flowEventRows.length,
          scannedLogRows: rows.length,
          scannedFlowEventRows: flowEventRows.length,
          scannedRuns: flowRows.length,
          totalRuns,
          page,
          limit,
          returnedRuns: runs.length,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json(payload),
        }
      } catch (error) {
        const schemaDrift = isSchemaDriftError(error)
        logger.set({
          filters: parsed.data,
          staleFlowRunsMarked,
          staleLeasesInProgress,
          flowSourceOfTruthError: error instanceof Error ? error.message : "unknown",
          schemaDrift,
        })

        return {
          status: schemaDrift ? 503 : 500,
          outcome: "error",
          response: NextResponse.json(
            {
              error: schemaDrift
                ? AI_RUNS_SCHEMA_ERROR_MESSAGE
                : "Observability AI runs unavailable. See server logs for details.",
            },
            { status: schemaDrift ? 503 : 500 },
          ),
        }
      }
    },
  })
}

