const CANCELLATION_ERROR_MESSAGE = 'Indexing run cancelled by user request.'
const CANCELLATION_POLL_INTERVAL_MS = 1_000
const INDEXER_LEASE_MS = 5 * 60_000
const INDEXER_STALE_RECLAIM_INTERVAL_MS = 30_000
const INDEXER_GRACEFUL_SHUTDOWN_MS = 20_000

const resolveIndexerLeaseSettings = () =>
  resolveWorkerLeaseSettings({
    leaseMsEnv: 'INDEXER_LEASE_MS',
    staleReclaimIntervalMsEnv: 'INDEXER_STALE_RECLAIM_INTERVAL_MS',
    gracefulShutdownMsEnv: 'INDEXER_GRACEFUL_SHUTDOWN_MS',
    defaults: {
      leaseMs: INDEXER_LEASE_MS,
      staleReclaimIntervalMs: INDEXER_STALE_RECLAIM_INTERVAL_MS,
      gracefulShutdownMs: INDEXER_GRACEFUL_SHUTDOWN_MS,
    },
  })

class IngestRunCancelledError extends Error {
  readonly runId: string

  constructor(runId: string) {
    super(CANCELLATION_ERROR_MESSAGE)
    this.name = 'IngestRunCancelledError'
    this.runId = runId
  }
}

class IngestRunFenceLostError extends Error {
  readonly runId: string

  constructor(runId: string) {
    super('Run claim ownership moved to another worker.')
    this.name = 'IngestRunFenceLostError'
    this.runId = runId
  }
}

const toErrorPayload = (error: unknown) => {
  const details = getErrorDetails(error)
  if (error instanceof Error) {
    return {
      code: 'INGEST_FAILED',
      message: error.message.slice(0, 500),
      stack: error.stack?.slice(0, 1000) ?? null,
      details,
    }
  }

  return {
    code: 'INGEST_FAILED',
    message: 'Unexpected ingest failure.',
    stack: null,
    details,
  }
}

const cleanupStaleVectorsForRun = async (args: {
  runId: string
  branchStateId: string
  vectorStore: VectorStore
}) => {
  const stagedChanges = await db
    .select({
      path: indexRunFileChanges.path,
      changeType: indexRunFileChanges.changeType,
      fileId: indexRunFileChanges.fileId,
    })
    .from(indexRunFileChanges)
    .where(eq(indexRunFileChanges.runId, args.runId))

  for (const change of stagedChanges) {
    await args.vectorStore.deleteStaleByPath({
      branchStateId: args.branchStateId,
      path: change.path,
      keepFileId: change.changeType === 'upsert' ? change.fileId : null,
    })
  }
}

const cleanupCancelledRunArtifacts = async (runId: string) => {
  await Promise.all([
    db.delete(indexRunFileChanges).where(eq(indexRunFileChanges.runId, runId)),
    db.delete(indexVectors).where(eq(indexVectors.runId, runId)),
  ])
}

const toCancelledResult = (args: {
  runId: string
  ingestMode: 'snapshot' | 'delta' | null
  modeFallback: 'snapshot' | null
  modeFallbackReason: string | null
  indexingMetrics: IngestRunMetrics | null
}) => ({
  runId: args.runId,
  status: 'cancelled' as const,
  ingestMode: args.ingestMode,
  modeFallback: args.modeFallback,
  modeFallbackReason: args.modeFallbackReason,
  finalizeStatus: null,
  gcStatus: 'not_applicable' as const,
  errorCode: CANCELLATION_ERROR_CODE,
  errorMessage: CANCELLATION_ERROR_MESSAGE,
  errorDetails: null,
  indexingMetrics: args.indexingMetrics,
})

const resolveArtifactBackendLabel = () =>
  process.env.INDEXER_ARTIFACTS_BACKEND?.trim().toLowerCase() || 'fs'

const publishRunGraphArtifacts = async (args: {
  artifactStore: ArtifactStore
  artifactsPrefix: string
  graphSummary: Awaited<ReturnType<typeof buildRunGraphArtifacts>>
}): Promise<PublishedGraphArtifacts> => {

  const writeFile = args.artifactStore.writeFile
  if (typeof writeFile !== 'function') {
    throw new Error('Configured artifact store backend does not support graph artifact writes.')
  }

  const files = {
    ...DEFAULT_RUN_GRAPH_ARTIFACT_FILES,
  }
  const sourceFiles = {
    indexStoreManifest: `${args.graphSummary.graphStorePath}.manifest.json`,
    indexPackManifest: path.join(args.graphSummary.indexPackDir, files.indexPackManifest),
    nodes: path.join(args.graphSummary.indexPackDir, files.nodes),
    edges: path.join(args.graphSummary.indexPackDir, files.edges),
  }
  const entries = [
    {
      filename: files.indexStoreManifest,
      sourcePath: sourceFiles.indexStoreManifest,
      contentType: 'application/json',
    },
    {
      filename: files.indexPackManifest,
      sourcePath: sourceFiles.indexPackManifest,
      contentType: 'application/json',
    },
    {
      filename: files.nodes,
      sourcePath: sourceFiles.nodes,
      contentType: 'application/x-ndjson',
    },
    {
      filename: files.edges,
      sourcePath: sourceFiles.edges,
      contentType: 'application/x-ndjson',
    },
  ] as const

  for (const entry of entries) {
    const body = await readFile(entry.sourcePath, 'utf8')
    await writeFile.call(args.artifactStore, {
      artifactsPrefix: args.artifactsPrefix,
      filename: entry.filename,
      body,
      contentType: entry.contentType,
    })
  }

  return {
    backend: resolveArtifactBackendLabel(),
    files,
  }
}

type LoadedIngestRun = {
  id: string
  status: string
  mode: 'snapshot' | 'delta'
  claimVersion: number
  branchStateId: string
  baseSha: string | null
  headSha: string
  artifactsPrefix: string
  configHash: string
  integrationId: string
}

type RunIngestContext = {
  runId: string
  branchStateId: string
  integrationId: string
  configHash: string
  baseSha: string | null
  headSha: string
  artifactsPrefix: string
}

type IngestModeExecutionResult = {
  ingestStats: Record<string, number>
  modeFallback: 'snapshot' | null
  modeFallbackReason: string | null
}

const toRunIngestContext = (run: LoadedIngestRun): RunIngestContext => ({
  runId: run.id,
  branchStateId: run.branchStateId,
  integrationId: run.integrationId,
  configHash: run.configHash,
  baseSha: run.baseSha,
  headSha: run.headSha,
  artifactsPrefix: run.artifactsPrefix,
})

const toIngestProgressStep = (
  event: {
    step: string
    message: string
    path?: string
    stats?: Record<string, number> | null
    details?: Record<string, unknown> | null
  },
): IngestStepEvent => ({
  stage: 'ingest',
  step: event.step,
  message: event.message,
  path: event.path,
  stats: event.stats,
  details: event.details ?? null,
})

const executeIngestMode = async (args: {
  run: LoadedIngestRun
  deps: IngestProcessorDeps
  sharedWorkspace: RepoWorkspace | null
  assertNotCancelled: (force?: boolean) => Promise<void>
  emitStep: (event: IngestStepEvent) => void
}): Promise<IngestModeExecutionResult> => {
  const runContext = toRunIngestContext(args.run)

const emitProgress = (event: Parameters<NonNullable<Parameters<typeof runSnapshotIngest>[0]["onProgress"]>>[0]) => {
  args.emitStep(toIngestProgressStep(event))
}

if (args.run.mode === 'delta') {
  args.emitStep({
    stage: 'ingest',
    step: 'delta_started',
    message: 'Delta ingest started.',
  })

  try {
    const delta = await runDeltaIngest({
      run: runContext,
      source: args.deps.source,
      vectorStore: args.deps.vectorStore,
      artifactStore: args.deps.artifactStore,
      workspace: args.sharedWorkspace ?? undefined,
      shouldAbort: () => args.assertNotCancelled(true),
      onProgress: emitProgress,
    })

    return {
      ingestStats: delta.stats,
      modeFallback: null,
      modeFallbackReason: null,
    }
  } catch (error) {
    if (!(error instanceof DeltaSnapshotFallbackError)) {
      throw error
    }

    args.emitStep({
      stage: 'ingest',
      step: 'delta_fallback',
      message: `Delta fallback to snapshot (${error.reason}).`,
      details: {
        reason: error.reason,
      },
    })

    const snapshot = await runSnapshotIngest({
      run: runContext,
      source: args.deps.source,
      vectorStore: args.deps.vectorStore,
      artifactStore: args.deps.artifactStore,
      workspace: args.sharedWorkspace ?? undefined,
      shouldAbort: () => args.assertNotCancelled(true),
      onProgress: emitProgress,
    })

    return {
      ingestStats: snapshot.stats,
      modeFallback: 'snapshot',
      modeFallbackReason: error.reason,
    }
  }
}

args.emitStep({
  stage: 'ingest',
  step: 'snapshot_started',
  message: 'Snapshot ingest started.',
})

  const snapshot = await runSnapshotIngest({
    run: runContext,
    source: args.deps.source,
    vectorStore: args.deps.vectorStore,
    artifactStore: args.deps.artifactStore,
    workspace: args.sharedWorkspace ?? undefined,
    shouldAbort: () => args.assertNotCancelled(true),
    onProgress: emitProgress,
  })

  return {
    ingestStats: snapshot.stats,
    modeFallback: null,
    modeFallbackReason: null,
  }
}

type GraphBuildResult = {
  graphSummary: Awaited<ReturnType<typeof buildRunGraphArtifacts>> | null
  publishedGraphArtifacts: PublishedGraphArtifacts | null
  graphError: string | null
}

const buildGraphArtifactsForRun = async (args: {
  run: LoadedIngestRun
  deps: IngestProcessorDeps
  sharedWorkspace: RepoWorkspace | null
  graphRequired: boolean
  emitStep: (event: IngestStepEvent) => void
}): Promise<GraphBuildResult> => {
  let graphSummary: Awaited<ReturnType<typeof buildRunGraphArtifacts>> | null = null
  let publishedGraphArtifacts: PublishedGraphArtifacts | null = null
  let graphError: string | null = null

  args.emitStep({
    stage: 'graph',
    step: 'graph_build_started',
    message: args.graphRequired
      ? 'Graph artifact build started.'
      : 'Graph artifact build started (optional).',
    details: {
      required: args.graphRequired,
    },
  })

  try {
    graphSummary = await buildRunGraphArtifacts({
      source: args.deps.source,
      integrationId: args.run.integrationId,
      headSha: args.run.headSha,
      artifactsPrefix: args.run.artifactsPrefix,
      workspace: args.sharedWorkspace ?? undefined,
    })
    args.emitStep({
      stage: 'graph',
      step: 'graph_build_succeeded',
      message: 'Graph artifacts built.',
      details: {
        backend: graphSummary.backend,
        durationMs: graphSummary.durationMs,
      },
    })
    publishedGraphArtifacts = await publishRunGraphArtifacts({
      artifactStore: args.deps.artifactStore,
      artifactsPrefix: args.run.artifactsPrefix,
      graphSummary,
    })
    args.emitStep({
      stage: 'graph',
      step: 'graph_artifacts_published',
      message: 'Graph artifacts published to artifact store.',
      details: {
        backend: publishedGraphArtifacts.backend,
      },
    })
  } catch (error) {
    graphError = error instanceof Error ? error.message : 'Failed to build graph artifacts.'
    args.emitStep({
      stage: 'graph',
      step: 'graph_build_failed',
      message: graphError,
      details: {
        required: args.graphRequired,
      },
    })
    if (args.graphRequired) {
      throw error
    }
  }

  return {
    graphSummary,
    publishedGraphArtifacts,
    graphError,
  }
}

const runFinalizeAndGc = async (args: {

  run: LoadedIngestRun
  deps: IngestProcessorDeps
  expectedClaimVersion: number
  leaseFencingEnabled: boolean
  modeFallback: 'snapshot' | null
  modeFallbackReason: string | null
  indexingMetrics: IngestRunMetrics | null
  checkCancellation: (force?: boolean) => Promise<boolean>
  emitStep: (event: IngestStepEvent) => void
}): Promise<IngestResult> => {
  if (await args.checkCancellation(true)) {
    await cleanupCancelledRunArtifacts(args.run.id)
    args.emitStep({
      stage: 'finalize',
      step: 'run_cancelled_before_finalize',
      message: CANCELLATION_ERROR_MESSAGE,
    })
    return toCancelledResult({
      runId: args.run.id,
      ingestMode: args.run.mode,
      modeFallback: args.modeFallback,
      modeFallbackReason: args.modeFallbackReason,
      indexingMetrics: args.indexingMetrics,
    })
  }

  const finalized = await finalizeIndexRun(args.run.id, {
    expectedClaimVersion: args.expectedClaimVersion,
  })
  args.emitStep({
    stage: 'finalize',
    step: 'run_finalized',
    message: `Finalize result: ${finalized.status}.`,
    details: {
      finalizeStatus: finalized.status,
    },
  })

if (finalized.status === 'ready') {
  gcStatus = 'succeeded'
  args.emitStep({
    stage: 'gc',
    step: 'vector_gc_started',
    message: 'Vector cleanup started.',
  })
  try {
    await cleanupStaleVectorsForRun({
      runId: args.run.id,
      branchStateId: args.run.branchStateId,
      vectorStore: args.deps.vectorStore,
    })
    args.emitStep({
      stage: 'gc',
      step: 'vector_gc_succeeded',
      message: 'Vector cleanup succeeded.',
    })
  } catch (error) {
    gcStatus = 'failed'
    errorCode = 'VECTOR_GC_FAILED'
    errorMessage = error instanceof Error ? error.message.slice(0, 500) : 'Vector cleanup failed.'
    args.emitStep({
      stage: 'gc',
      step: 'vector_gc_failed',
      message: errorMessage,
    })
    await db
      .update(indexRuns)
      .set({
        error: {
          code: 'VECTOR_GC_FAILED',
          message: errorMessage,
        },
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(indexRuns.id, args.run.id),
          ...(
            args.leaseFencingEnabled
              ? [eq(indexRuns.claimVersion, args.expectedClaimVersion)]
              : []
          ),
        ),
      )
  }
} else {
  gcStatus = 'skipped'
}

  return {
    runId: args.run.id,
    status: finalized.status,
    ingestMode: args.run.mode,
    modeFallback: args.modeFallback,
    modeFallbackReason: args.modeFallbackReason,
    finalizeStatus: finalized.status,
    gcStatus,
    errorCode,
    errorMessage,
    errorDetails: null,
    indexingMetrics: args.indexingMetrics,
  }
}

export const processIngestJob = async (
  job: IngestJob & { onStep?: (event: IngestStepEvent) => void; claimVersion?: number },
  deps: IngestProcessorDeps = defaultDeps(),
): Promise<IngestResult> => {
  const emitStep = (event: IngestStepEvent) => {
    if (!job.onStep) {
      return
    }

    try {
      job.onStep(event)
    } catch {
      // Progress logging should never block ingest processing.
    }
  }

  const [rawRun] = await db
    .select({
      id: indexRuns.id,
      status: indexRuns.status,
      mode: indexRuns.mode,
      claimVersion: indexRuns.claimVersion,
      branchStateId: indexRuns.branchStateId,
      baseSha: indexRuns.baseSha,
      headSha: indexRuns.headSha,
      artifactsPrefix: indexRuns.artifactsPrefix,
      configHash: indexBranchStates.configHash,
      integrationId: indexBranchStates.integrationId,
    })
    .from(indexRuns)
    .innerJoin(indexBranchStates, eq(indexRuns.branchStateId, indexBranchStates.id))
    .where(eq(indexRuns.id, job.runId))
    .limit(1)

  const run = rawRun
    ? {
        ...rawRun,
        mode: rawRun.mode as 'snapshot' | 'delta',
        claimVersion: normalizeClaimVersion(rawRun.claimVersion),
      }
    : null

if (!run) {
  return {
    runId: job.runId,
    status: 'skipped',
    ingestMode: null,
    modeFallback: null,
    modeFallbackReason: null,
    finalizeStatus: 'not_found',
    gcStatus: 'not_applicable',
    errorCode: null,
    errorMessage: null,
    errorDetails: null,
    indexingMetrics: null,
  }
}

const leaseSettings = resolveIndexerLeaseSettings()
const leaseFencingEnabled = leaseSettings.enabled
const expectedClaimVersion = normalizeClaimVersion(job.claimVersion ?? run.claimVersion)
if (leaseFencingEnabled && expectedClaimVersion !== run.claimVersion) {
  return {
    runId: run.id,
    status: 'skipped',
    ingestMode: run.mode,
    modeFallback: null,
    modeFallbackReason: null,
    finalizeStatus: 'invalid_state',
    gcStatus: 'not_applicable',
    errorCode: 'RECLAIMED_OR_STALE_WRITER',
    errorMessage: 'Run claim version no longer owned by this worker.',
    errorDetails: {
      event: WORKER_EVENTS.INDEXER_RUN_FENCE_MISS,
    },
    indexingMetrics: null,
  }
}

if (run.status === 'ready' || run.status === 'superseded') {
  return {
    runId: run.id,
    status: 'skipped',
    ingestMode: run.mode,
    modeFallback: null,
    modeFallbackReason: null,
    finalizeStatus: 'invalid_state',
    gcStatus: 'not_applicable',
    errorCode: null,
    errorMessage: null,
    errorDetails: null,
    indexingMetrics: null,
  }
}

if (run.status === 'cancelled') {
  return toCancelledResult({
    runId: run.id,
    ingestMode: run.mode,
    modeFallback: null,
    modeFallbackReason: null,
    indexingMetrics: null,
  })
}

let sharedWorkspace: RepoWorkspace | null = null
let repoMaterialization: RepoWorkspaceMetrics | null = null

try {
  let lastCancellationCheckAt = 0
  let lastLeaseRefreshAt = 0
  let isCancelled = false
  const refreshLease = async (force = false) => {
    if (!leaseFencingEnabled) {
      return true
    }
    const now = Date.now()
    const refreshIntervalMs = Math.max(5_000, Math.floor(leaseSettings.leaseMs / 3))
    if (!force && now - lastLeaseRefreshAt < refreshIntervalMs) {
      return true
    }
    const refreshed = await db
      .update(indexRuns)
      .set({
        leaseExpiresAt: buildLeaseExpiry(leaseSettings.leaseMs),
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(indexRuns.id, run.id),
          eq(indexRuns.claimVersion, expectedClaimVersion),
          inArray(indexRuns.status, ['ingesting', 'indexing']),
        ),
      )
      .returning({ id: indexRuns.id })
    if (refreshed.length === 0) {
      return false
    }
    lastLeaseRefreshAt = now
    return true
  }

  const checkCancellation = async (force = false) => {
    if (isCancelled) {
      return true
    }

    const now = Date.now()
    if (!force && now - lastCancellationCheckAt < CANCELLATION_POLL_INTERVAL_MS) {
      return false
    }

    lastCancellationCheckAt = now
    const [statusRow] = await db
      .select({ status: indexRuns.status })
      .from(indexRuns)
      .where(eq(indexRuns.id, run.id))
      .limit(1)
    isCancelled = statusRow?.status === 'cancelled'
    return isCancelled
  }

  const assertNotCancelled = async (force = false) => {
    if (!(await refreshLease(force))) {
      throw new IngestRunFenceLostError(run.id)
    }
    if (await checkCancellation(force)) {
      throw new IngestRunCancelledError(run.id)
    }
  }

  await assertNotCancelled()

const [indexingStarted] = await db
  .update(indexRuns)
  .set({
    status: 'indexing',
    leaseExpiresAt: leaseFencingEnabled ? buildLeaseExpiry(leaseSettings.leaseMs) : null,
    claimedBy: leaseFencingEnabled ? (process.env.INDEXER_SERVICE_NAME?.trim() || 'argus-indexer-worker') : null,
    updatedAt: new Date(),
  })
  .where(
    and(
      eq(indexRuns.id, run.id),
      inArray(indexRuns.status, ['planned', 'ingesting']),
      ...(leaseFencingEnabled ? [eq(indexRuns.claimVersion, expectedClaimVersion)] : []),
    ),
  )
  .returning({
    id: indexRuns.id,
  })

if (!indexingStarted) {
  if (await checkCancellation(true)) {
    return toCancelledResult({
      runId: run.id,
      ingestMode: run.mode,
      modeFallback: null,
      modeFallbackReason: null,
      indexingMetrics: null,
    })
  }

  return {
    runId: run.id,
    status: 'skipped',
    ingestMode: run.mode,
    modeFallback: null,
    modeFallbackReason: null,
    finalizeStatus: 'invalid_state',
    gcStatus: 'not_applicable',
    errorCode: null,
    errorMessage: null,
    errorDetails: null,
    indexingMetrics: null,
  }
}

emitStep({
  stage: 'ingest',
  step: 'run_indexing_started',
  message: `Run entered indexing (${run.mode}).`,
  details: {
    runMode: run.mode,
  },
})

let modeFallback: 'snapshot' | null = null
let modeFallbackReason: string | null = null
let indexingMetrics: IngestRunMetrics | null = null
const useSharedWorkspace = resolveSingleArchiveEnabled(run.integrationId)

try {
  await assertNotCancelled()

if (useSharedWorkspace) {
  sharedWorkspace = await prepareRepoWorkspace({
    source: deps.source,
    integrationId: run.integrationId,
    sha: run.headSha,
  })
  repoMaterialization = sharedWorkspace.metrics
  emitStep({
    stage: 'ingest',
    step: 'repo_workspace_ready',
    message: 'Repository workspace prepared.',
    details: {
      downloadMs: repoMaterialization.downloadMs,
      extractMs: repoMaterialization.extractMs,
      archiveBytes: repoMaterialization.archiveBytes,
    },
  })
}

const ingestModeResult = await executeIngestMode({
  run,
  deps,
  sharedWorkspace,
  assertNotCancelled,
  emitStep,
})
modeFallback = ingestModeResult.modeFallback
modeFallbackReason = ingestModeResult.modeFallbackReason
const ingestStats = ingestModeResult.ingestStats
emitStep({
  stage: 'ingest',
  step: 'ingest_stats_ready',
  message: 'Ingest stats computed.',
  stats: ingestStats,
})

const graphRequired = resolveGraphRequiredForRun(useSharedWorkspace)
const graphBuildResult = await buildGraphArtifactsForRun({
  run,
  deps,
  sharedWorkspace,
  graphRequired,
  emitStep,
})

await assertNotCancelled()

  await db
    .update(indexRuns)
    .set({
      stats,
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(indexRuns.id, run.id),
        ...(leaseFencingEnabled ? [eq(indexRuns.claimVersion, expectedClaimVersion)] : []),
      ),
    )
  emitStep({
    stage: 'ingest',
    step: 'run_stats_persisted',
    message: 'Run stats persisted.',
    stats: ingestStats,
    details: {
      modeFallback,
      modeFallbackReason,
    },
  })
} catch (error) {
  if (error instanceof IngestRunFenceLostError) {
    emitStep({
      stage: 'finalize',
      step: 'fence_lost',
      message: 'Run ownership moved to another worker; skipping stale writer updates.',
      details: {
        event: WORKER_EVENTS.INDEXER_RUN_FENCE_MISS,
      },
    })
    return {
      runId: run.id,
      status: 'skipped',
      ingestMode: run.mode,
      modeFallback,
      modeFallbackReason,
      finalizeStatus: 'invalid_state',
      gcStatus: 'not_applicable',
      errorCode: 'RECLAIMED_OR_STALE_WRITER',
      errorMessage: error.message,
      errorDetails: {
        event: WORKER_EVENTS.INDEXER_RUN_FENCE_MISS,
      },
      indexingMetrics,
    }
  }

    if (error instanceof IngestRunCancelledError) {
      await cleanupCancelledRunArtifacts(run.id)
      emitStep({
        stage: 'ingest',
        step: 'ingest_cancelled',
        message: CANCELLATION_ERROR_MESSAGE,
      })
      return toCancelledResult({
        runId: run.id,
        ingestMode: run.mode,
        modeFallback,
        modeFallbackReason,
        indexingMetrics,
      })
    }

    const errorPayload = toErrorPayload(error)
    emitStep({
      stage: 'ingest',
      step: 'ingest_failed',
      message: errorPayload.message,
      details: asRecord(errorPayload.details),
    })
    await markIndexRunFailed(run.id, errorPayload, {
      expectedClaimVersion,
    })

    return {
      runId: run.id,
      status: 'failed',
      ingestMode: run.mode,
      modeFallback,
      modeFallbackReason,
      finalizeStatus: null,
      gcStatus: 'not_applicable',
      errorCode: 'INGEST_FAILED',
      errorMessage: errorPayload.message,
      errorDetails: asRecord(errorPayload.details),
      indexingMetrics,
    }
  }

  return runFinalizeAndGc({
    run,
    deps,
    expectedClaimVersion,
    leaseFencingEnabled,
    modeFallback,
    modeFallbackReason,
    indexingMetrics,
    checkCancellation,
    emitStep,
  })
  } finally {
    if (sharedWorkspace) {
      await sharedWorkspace.cleanup().catch(() => {})
    }
  }
}

#!/usr/bin/env node

import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const cwd = process.cwd();

const readSource = (relativePath) =>
  readFileSync(resolve(cwd, relativePath), "utf8");

const checks = [
  {
    id: "cache_headers_static_assets",
    description: "next config has immutable static cache headers",
    run: () => {
      const source = readSource("next.config.ts");
      return (
        source.includes('source: "/_next/static/:path*"') &&
        source.includes("max-age=31536000, immutable")
      );
    },
  },
  {
    id: "route_nav_metrics",
    description: "app layout emits route nav timing metadata",
    run: () => {
      const source = readSource("src/app/(app)/app-layout-client.tsx");
      return (
        source.includes("navDurationMs") &&
        source.includes("prefetchHit") &&
        source.includes("route_navigation")
      );
    },
  },
  {
    id: "query_defaults",
    description: "query provider uses aggressive stale/gc windows",
    run: () => {
      const source = readSource("src/components/query-provider.tsx");
      return (
        source.includes("staleTime: 10 * 60_000") &&
        source.includes("gcTime: 45 * 60_000")
      );
    },
  },
  {
    id: "mr_loading_skeleton",
    description: "merge request page uses skeleton fallback instead of blocking text loader",
    run: () => {
      const source = readSource("src/app/(app)/repos/[integrationId]/mrs/[mergeRequestIid]/page.tsx");
      return source.includes("<Skeleton");
    },
  },
];

let warnings = 0;

console.log("Performance report (warn-only):");
for (const check of checks) {
  try {
    const passed = check.run();
    if (passed) {
      console.log(`  [ok]   ${check.id} - ${check.description}`);
    } else {
      warnings += 1;
      console.log(`  [warn] ${check.id} - ${check.description}`);
    }
  } catch (error) {
    warnings += 1;
    console.log(
      `  [warn] ${check.id} - check failed to run: ${
        error instanceof Error ? error.message : "unknown error"
      }`,
    );
  }
}

console.log(
  `Summary: ${checks.length - warnings} passing, ${warnings} warnings (non-blocking).`,
);
process.exit(0);

use std::net::IpAddr;
use std::time::Duration;

use reqwest::blocking::Client;
use serde::Deserialize;

const DEFAULT_EMBEDDING_DIM: usize = 1536;
const DEFAULT_HTTP_TIMEOUT_SECS: u64 = 30;
const MAX_INPUT_BYTES: usize = 8191;

fn truncate_utf8_bytes(value: &str, max_bytes: usize) -> &str {
  if max_bytes == 0 {
    return "";
  }
  if value.len() <= max_bytes {
    return value;
  }
  let mut end = max_bytes;
  while end > 0 && !value.is_char_boundary(end) {
    end -= 1;
  }
  &value[..end]
}

#[derive(Debug)]
pub enum EmbeddingError {
  InvalidConfig(String),
  Http(reqwest::Error),
  UnexpectedResponse(String),
}

impl std::fmt::Display for EmbeddingError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      EmbeddingError::InvalidConfig(err) => write!(f, "invalid embedding config: {err}"),
      EmbeddingError::Http(err) => write!(f, "embedding request failed: {err}"),
      EmbeddingError::UnexpectedResponse(msg) => write!(f, "unexpected response: {msg}"),
    }
  }
}

impl std::error::Error for EmbeddingError {}

impl From<reqwest::Error> for EmbeddingError {
  fn from(err: reqwest::Error) -> Self {
    EmbeddingError::Http(err)
  }
}

pub trait EmbeddingsProvider: Send + Sync {
  fn embed_texts(&self, texts: &[&str]) -> Result<Vec<Vec<f32>>, EmbeddingError>;
  fn dimension(&self) -> Option<usize> {
    None
  }
  fn model_id(&self) -> Option<&str> {
    None
  }
}

#[derive(Debug, Clone)]

pub struct HttpEmbeddingConfig {
  pub base_url: String,
  pub api_key: Option<String>,
  pub model: String,
  pub dimension: Option<usize>,
  pub timeout: Option<Duration>,
}

impl HttpEmbeddingConfig {
  pub fn new(
    base_url: impl Into<String>,
    api_key: Option<String>,
    model: impl Into<String>,
  ) -> Self {
    Self {
      base_url: base_url.into(),
      api_key,
      model: model.into(),
      dimension: None,
      timeout: None,
    }
  }
}

#[derive(Debug, Clone)]
pub struct HttpEmbeddingsProvider {
  client: Client,
  config: HttpEmbeddingConfig,
}

impl HttpEmbeddingsProvider {
  pub fn new(config: HttpEmbeddingConfig) -> Result<Self, EmbeddingError> {
    validate_http_config(&config)?;
    let mut builder = Client::builder();
    let timeout = config
      .timeout
      .unwrap_or_else(|| Duration::from_secs(DEFAULT_HTTP_TIMEOUT_SECS));
    builder = builder.timeout(timeout);
    let client = builder.build()?;
    Ok(Self { client, config })
  }
}

fn validate_http_config(config: &HttpEmbeddingConfig) -> Result<(), EmbeddingError> {
  let url = reqwest::Url::parse(config.base_url.as_str())
    .map_err(|err| EmbeddingError::InvalidConfig(format!("invalid base_url: {err}")))?;
  let scheme = url.scheme();
  if scheme != "http" && scheme != "https" {
    return Err(EmbeddingError::InvalidConfig(format!(
      "unsupported base_url scheme: {scheme}"
    )));
  }
  if !url.username().is_empty() || url.password().is_some() {
    return Err(EmbeddingError::InvalidConfig(
      "base_url must not include credentials".to_string(),
    ));
  }
  let _ = url
    .host_str()
    .ok_or_else(|| EmbeddingError::InvalidConfig("base_url host is missing".to_string()))?;
  Ok(())
}

fn is_local_or_private_host(host: &str) -> bool {
  if host.eq_ignore_ascii_case("localhost") || host.ends_with(".localhost") {
    return true;
  }
  match host.parse::<IpAddr>() {
    Ok(IpAddr::V4(ip)) => {
      ip.is_private() || ip.is_loopback() || ip.is_link_local() || ip.is_broadcast()
    }
    Ok(IpAddr::V6(ip)) => ip.is_loopback() || ip.is_unique_local() || ip.is_unicast_link_local(),
    Err(_) => false,
  }
}

fn should_send_auth_header(base_url: &str) -> bool {
  let host = reqwest::Url::parse(base_url)
    .ok()
    .and_then(|url| url.host_str().map(|value| value.to_string()));
  host
    .as_deref()
    .map(|value| !is_local_or_private_host(value))
    .unwrap_or(false)
}

impl EmbeddingsProvider for HttpEmbeddingsProvider {
  fn embed_texts(&self, texts: &[&str]) -> Result<Vec<Vec<f32>>, EmbeddingError> {

if texts.is_empty() {
  return Ok(Vec::new());
}

let mut filtered: Vec<&str> = Vec::new();
let mut index_map = Vec::with_capacity(texts.len());
for text in texts {
  let trimmed = text.trim();
  if trimmed.is_empty() {
    index_map.push(None);
  } else {
    index_map.push(Some(filtered.len()));
    filtered.push(truncate_utf8_bytes(trimmed, MAX_INPUT_BYTES));
  }
}

if filtered.is_empty() {
  let dim = self.config.dimension.unwrap_or(DEFAULT_EMBEDDING_DIM);
  return Ok(
    index_map
      .iter()
      .map(|_| zero_vector(dim))
      .collect::<Vec<_>>(),
  );
}

let url = format!("{}/embeddings", self.config.base_url.trim_end_matches('/'));
let mut payload = serde_json::json!({
  "input": filtered,
  "model": self.config.model,
});
if let Some(dimension) = self.config.dimension {
  payload["dimensions"] = serde_json::json!(dimension);
}
let mut request = self.client.post(url).json(&payload);

if let Some(api_key) = &self.config.api_key {
  if !api_key.is_empty() && should_send_auth_header(&self.config.base_url) {
    request = request.bearer_auth(api_key);
  }
}

let response = request.send()?.error_for_status()?;
let payload: EmbeddingResponse = response.json()?;

if payload.data.is_empty() {
  return Err(EmbeddingError::UnexpectedResponse(
    "missing embedding data".to_string(),
  ));
}

let mut embeddings: Vec<Vec<f32>> = Vec::with_capacity(payload.data.len());

    for item in payload.data {
      let mut embedding = item
        .embedding
        .into_iter()
        .map(|value| value as f32)
        .collect::<Vec<_>>();
      if let Some(expected_dim) = self.config.dimension {
        embedding = normalize_vector_dimension(embedding, expected_dim);
      }
      embeddings.push(embedding);
    }

    let mut embedding_iter = embeddings.into_iter();
    let dim = self
      .config
      .dimension
      .or_else(|| embedding_iter.as_slice().first().map(|vec| vec.len()))
      .unwrap_or(DEFAULT_EMBEDDING_DIM);

    let mut results = Vec::with_capacity(texts.len());
    for entry in index_map {
      if entry.is_none() {
        results.push(zero_vector(dim));
        continue;
      }
      let next = embedding_iter.next().ok_or_else(|| {
        EmbeddingError::UnexpectedResponse("embedding count mismatch".to_string())
      })?;
      results.push(next);
    }

    if embedding_iter.next().is_some() {
      return Err(EmbeddingError::UnexpectedResponse(
        "embedding count mismatch".to_string(),
      ));
    }

    Ok(results)
  }

  fn dimension(&self) -> Option<usize> {
    self.config.dimension
  }

  fn model_id(&self) -> Option<&str> {
    Some(self.config.model.as_str())
  }
}

#[derive(Debug, Deserialize)]
struct EmbeddingResponse {
  data: Vec<EmbeddingData>,
}

#[derive(Debug, Deserialize)]
struct EmbeddingData {
  embedding: Vec<f64>,
}

fn zero_vector(dim: usize) -> Vec<f32> {
  vec![0.0; dim]
}

fn normalize_vector_dimension(mut vector: Vec<f32>, expected_dim: usize) -> Vec<f32> {
  match vector.len().cmp(&expected_dim) {
    std::cmp::Ordering::Less => {
      vector.resize(expected_dim, 0.0);
      vector
    }
    std::cmp::Ordering::Equal => vector,
    std::cmp::Ordering::Greater => {
      vector.truncate(expected_dim);
      vector
    }
  }
}

#[cfg(test)]
mod tests {
  use super::*;
  use mockito::Server;

  #[test]
  fn http_provider_embeds_texts() -> Result<(), Box<dyn std::error::Error>> {
    let mut server = Server::new();
    let body = serde_json::json!({
      "data": [
        { "embedding": [0.1, 0.2] },
        { "embedding": [0.3, 0.4] }
      ]
    })
    .to_string();

    let _mock = server
      .mock("POST", "/embeddings")
      .with_status(200)
      .with_header("content-type", "application/json")
      .with_body(body)
      .create();

    let config = HttpEmbeddingConfig {
      base_url: server.url(),
      api_key: None,
      model: "test-model".to_string(),
      dimension: Some(2),
      timeout: None,
    };

    let provider = HttpEmbeddingsProvider::new(config)?;
    let inputs = ["hello", "world"];
    let embeddings = provider.embed_texts(&inputs)?;

    assert_eq!(embeddings.len(), 2);
    assert!((embeddings[0][0] - 0.1).abs() < 1e-6);
    assert!((embeddings[0][1] - 0.2).abs() < 1e-6);
    assert!((embeddings[1][0] - 0.3).abs() < 1e-6);
    assert!((embeddings[1][1] - 0.4).abs() < 1e-6);

    Ok(())
  }

