import { NextResponse } from "next/server"
import { z } from "zod"

import { requireJsonBody } from "@/lib/http/request-json"
import { createImpactGraphBackend } from "@/lib/review/impact-graph-backend"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const tracePayloadSchema = z
  .object({
    mode: z.enum(["callers", "impact"]).optional(),
    symbol: z.string().trim().min(1).max(300).optional(),
    nodeId: z.string().trim().min(1).max(500).optional(),
    limit: z.number().int().positive().max(200).optional(),
    depth: z.number().int().positive().max(64).optional(),
    integrationId: z.string().trim().min(1).max(200).optional(),
    sourceBranch: z.string().trim().min(1).max(300).optional(),
  })
  .superRefine((value, ctx) => {
    if (!value.symbol && !value.nodeId) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Either symbol or nodeId is required.",
      })
    }
  })

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/trace-callers",
    event: "api.code.trace_callers",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "Invalid trace payload."),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

if (!body.ok) return body.result

const parsed = tracePayloadSchema.safeParse(body.value)
if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid trace payload." }, { status: 400 }),
  }
}

const {
  mode = "callers",
  symbol,
  nodeId,
  limit,
  depth,
  integrationId,
  sourceBranch,
} = parsed.data

try {
  const backend = createImpactGraphBackend()
  const snapshot = await backend.resolveSnapshot({
    integrationId: integrationId ?? null,
    sourceBranch: sourceBranch ?? null,
  })

  if (snapshot.status === "pending_graph") {
    logger.set({
      mode,
      symbol: symbol ?? null,
      nodeId: nodeId ?? null,
      sourceBranch: sourceBranch ?? null,
      integrationId: integrationId ?? null,
      tracePendingReason: snapshot.reason,
      traceBackend: backend.kind,
    })
    return {
      status: 409,
      outcome: "trace_pending",
      response: NextResponse.json(
        { error: snapshot.message },
        { status: 409 },
      ),
    }
  }

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({
            data: {
              mode,
              symbol: targetNode?.name ?? symbol ?? null,
              nodeId: targetNode?.id ?? nodeId ?? null,
              target: targetNode,
              depth: mode === "impact" ? depth ?? 3 : null,
              count: tracedNodes.length,
              results: tracedNodes,
              edges: tracedEdges,
            },
          }),
        }
      } catch {
        logger.set({
          traceErrorCode: "unknown",
        })

        return {
          status: 500,
          outcome: "trace_failed",
          response: NextResponse.json({ error: "Failed to trace code graph." }, { status: 500 }),
        }
      }
    },
  })
}

