import path from 'node:path'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

import test from 'ava'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..')

function loadStreamWithMockBinding(mockBinding: any) {
  const streamPath = path.join(packageRoot, 'js', 'stream.js')
  const requireFromStream = createRequire(streamPath)

  const indexResolved = requireFromStream.resolve('../index.js')
  const streamResolved = requireFromStream.resolve('./stream.js')

  const prevIndex = requireFromStream.cache[indexResolved]
  const prevStream = requireFromStream.cache[streamResolved]

  requireFromStream.cache[indexResolved] = {
    id: indexResolved,
    filename: indexResolved,
    loaded: true,
    exports: mockBinding,
  } as any
  delete requireFromStream.cache[streamResolved]

  const mod = requireFromStream('./stream.js') as any
  const restore = () => {
    if (prevIndex) requireFromStream.cache[indexResolved] = prevIndex
    else delete requireFromStream.cache[indexResolved]
    if (prevStream) requireFromStream.cache[streamResolved] = prevStream
    else delete requireFromStream.cache[streamResolved]
  }

  return { mod, restore }
}

test.serial('stream adapter: ends naturally on null next()', async (t) => {
  let cancelCalls = 0
  let nextCalls = 0

  const { mod, restore } = loadStreamWithMockBinding({
    createIndexStream() {
      return {
        cancel() {
          cancelCalls += 1
        },
        async next() {
          nextCalls += 1
          return null
        },
      }
    },
  })
  t.teardown(restore)

  const it = mod.indexStream({}) as AsyncIterable<any> & { cancel(): void }
  const first = await (it as any).next()
  t.true(first.done)
  t.is(nextCalls, 1)
  t.is(cancelCalls, 0)

  it.cancel()
  t.is(cancelCalls, 0)
})

test.serial('stream adapter: cancel is idempotent and forces done', async (t) => {
  let cancelCalls = 0
  const values = [
    { type: 'x', n: 1 },
    { type: 'y', n: 2 },
  ]

  const { mod, restore } = loadStreamWithMockBinding({
    createIndexStream() {
      let idx = 0
      return {
        cancel() {
          cancelCalls += 1
        },
        async next() {
          if (idx >= values.length) return null
          return values[idx++]
        },
      }
    },
  })
  t.teardown(restore)

  const it = mod.indexStream({}) as AsyncIterable<any> & { cancel(): void }
  const first = await (it as any).next()
  t.false(first.done)
  t.deepEqual(first.value, values[0])

  it.cancel()
  it.cancel()
  t.is(cancelCalls, 1)

  const after = await (it as any).next()
  t.true(after.done)
})

