class DeltaSnapshotFallbackError extends Error {
  readonly reason: string

  constructor(reason: string) {
    super(`Delta ingest fallback required: ${reason}`)
    this.reason = reason
    this.name = "DeltaSnapshotFallbackError"
  }
}

const createIngestDbMock = (args: {
  run: IngestRun | null
  stagedChanges?: Array<{
    path: string
    changeType: "upsert" | "delete"
    fileId: string | null
  }>
}) => {
  let currentRunStatus = args.run?.status ?? null
  const calls = {
    updates: [] as Array<Record<string, unknown>>,
    deletes: [] as Array<unknown>,
  }

  const db = {

select: () => ({
  from: (table: unknown) => {
    if (table === indexRuns) {
      const statusRow = currentRunStatus ? [{ status: currentRunStatus }] : []
      const fullRunRow = args.run
        ? [
            {
              ...args.run,
              status: currentRunStatus ?? args.run.status,
            },
          ]
        : []
      return {
        where: () => ({
          limit: () => Promise.resolve(statusRow),
        }),
        innerJoin: (_joinTable: unknown) => {
          if (_joinTable !== indexBranchStates) {
            throw new Error("Unexpected join table in ingest test.")
          }
          return {
            where: () => ({
              limit: () => Promise.resolve(fullRunRow),
            }),
          }
        },
      }
    }

    if (table === indexRunFileChanges) {
      return {
        where: () => Promise.resolve(args.stagedChanges ?? []),
      }
    }

    throw new Error("Unexpected select table in ingest test.")
  },
}),

    update: (table: unknown) => ({
      set: (values: Record<string, unknown>) => {
        calls.updates.push(values)
        const requestedStatus = typeof values.status === "string" ? values.status : null
        return {
          where: () => {
            const returning = () => {
              if (table !== indexRuns || !args.run || requestedStatus !== "indexing") {
                return Promise.resolve([])
              }

              if (currentRunStatus !== "planned" && currentRunStatus !== "ingesting") {
                return Promise.resolve([])
              }

              currentRunStatus = "indexing"
              return Promise.resolve([{ id: args.run.id }])
            }

            return {
              returning,
              then: (onfulfilled: (value: unknown[]) => unknown) =>
                Promise.resolve([]).then(onfulfilled),
            }
          },
        }
      },
    }),
    delete: (table: unknown) => ({
      where: () => {
        calls.deletes.push(table)
        return Promise.resolve([])
      },
    }),
  }

  return {
    db,
    calls,
    setRunStatus: (status: string | null) => {
      currentRunStatus = status
    },
  }
}

