import { useCallback, useEffect, useMemo, useRef, useState } from "react"

import {
  invalidateGitLabIntegrationsQuery,
  loadGitLabIntegrations,
} from "@/lib/gitlab/client-integrations-query"
import { parseJsonResponse } from "@/lib/http/response-json"
import {
  asRecord,
  encodeProjectScopeKey,
  extractErrorMessage,
  type GitLabIntegration,
  type GitLabProject,
} from "../model/settings.shared"

const clearStatusLater = (setStatus: (value: string) => void) => {
  window.setTimeout(() => {
    setStatus("")
  }, 2000)
}

export function useGitLabSettings() {
  const [integrations, setIntegrations] = useState<GitLabIntegration[]>([])
  const [integrationBusyId, setIntegrationBusyId] = useState<string | null>(null)
  const [integrationStatus, setIntegrationStatus] = useState("")
  const [connectInstanceUrl, setConnectInstanceUrl] = useState("https://gitlab.us.lmco.com")
  const [connectToken, setConnectToken] = useState("")
  const [connectProjects, setConnectProjects] = useState<GitLabProject[]>([])
  const [connectProjectId, setConnectProjectId] = useState("")
  const [isLoadingConnectProjects, setIsLoadingConnectProjects] = useState(false)
  const [isConnectingProject, setIsConnectingProject] = useState(false)
  const [showConnectToken, setShowConnectToken] = useState(false)
  const [connectStatus, setConnectStatus] = useState("")

  const loadIntegrationsRequestIdRef = useRef(0)
  const loadConnectProjectsRequestIdRef = useRef(0)

const selectedConnectProject = useMemo(
  () => connectProjects.find((project) => project.id === connectProjectId) ?? null,
  [connectProjectId, connectProjects],
)

const connectedReviewProjects = useMemo(() => {
  const deduped = new Map<string, { key: string; label: string; instanceUrl: string; projectId: string }>()
  for (const integration of integrations) {
    const key = encodeProjectScopeKey(integration.instanceUrl, integration.projectId)
    if (!deduped.has(key)) {
      deduped.set(key, {
        key,
        label: integration.projectPath,
        instanceUrl: integration.instanceUrl,
        projectId: integration.projectId,
      })
    }
  }
  return Array.from(deduped.values()).sort((a, b) => a.label.localeCompare(b.label))
}, [integrations])

const loadIntegrationsData = useCallback(async (options?: { forceRefresh?: boolean }) => {
  const requestId = loadIntegrationsRequestIdRef.current + 1
  loadIntegrationsRequestIdRef.current = requestId
  const data = await loadGitLabIntegrations({ forceRefresh: options?.forceRefresh === true })
  if (loadIntegrationsRequestIdRef.current !== requestId) {
    return
  }
  setIntegrations(data)
}, [])

const callIntegrationAction = useCallback(async (
  integrationId: string,
  action: "resync" | "disconnect",
  token?: string,
) => {
  const response = await fetch(`/api/gitlab/integrations/${integrationId}/${action}`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify(token ? { token } : {}),
  })

  const parsedPayload = await parseJsonResponse(response)
  const payload = parsedPayload.ok ? parsedPayload.value : null
  if (!response.ok) {
    const message =
      payload &&
        typeof payload === "object" &&
        "error" in payload &&
        typeof (payload as { error?: unknown }).error === "string"
        ? (payload as { error: string }).error
        : `Failed to ${action} integration.`
    throw new Error(message)
  }

  return payload
}, [])

const runIntegrationAction = useCallback(async (
  integrationId: string,
  action: "resync" | "disconnect",
  options?: { token?: string },
) => {
  setIntegrationBusyId(integrationId)
  try {
    const payload = await callIntegrationAction(integrationId, action, options?.token)
    const warning = (() => {
      const root = asRecord(payload)
      return typeof root?.warning === "string" ? root.warning : ""
    })()

    setIntegrationStatus(
      warning ||
        (action === "resync"
          ? "Integration resync requested."
          : "Integration disconnected."),
    )
    clearStatusLater(setIntegrationStatus)
    invalidateGitLabIntegrationsQuery()
    await loadIntegrationsData({ forceRefresh: true })
  } catch (error) {
    setIntegrationStatus(error instanceof Error ? error.message : "Action failed.")
    clearStatusLater(setIntegrationStatus)
  } finally {
    setIntegrationBusyId(null)
  }
}, [callIntegrationAction, loadIntegrationsData])

const updateIntegrationAutoPost = useCallback(async (

  integrationId: string,
  autoPostEnabled: boolean,
) => {
  setIntegrationBusyId(integrationId)
  const previousIntegrations = integrations
  setIntegrations((current) =>
    current.map((integration) =>
      integration.id === integrationId
        ? {
            ...integration,
            aiReviewAutoPostEnabled: autoPostEnabled,
          }
        : integration
    ),
  )

  try {
    const response = await fetch(`/api/gitlab/integrations/${integrationId}/ai-review-settings`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        autoPostEnabled,
      }),
    })
    const parsedPayload = await parseJsonResponse(response)
    const payload = parsedPayload.ok ? parsedPayload.value : null
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, "Failed to update AI review settings."))
    }

    setIntegrationStatus(
      autoPostEnabled
        ? "Auto-post enabled for this project."
        : "Auto-post disabled for this project.",
    )
    clearStatusLater(setIntegrationStatus)
    invalidateGitLabIntegrationsQuery()
    await loadIntegrationsData({ forceRefresh: true })
  } catch (error) {
    setIntegrations(previousIntegrations)
    setIntegrationStatus(error instanceof Error ? error.message : "Failed to update auto-post setting.")
    clearStatusLater(setIntegrationStatus)
  } finally {
    setIntegrationBusyId(null)
  }
}, [integrations, loadIntegrationsData])

const handleLoadConnectProjects = useCallback(async () => {
  const instanceUrl = connectInstanceUrl.trim()
  const token = connectToken.trim()

  if (!instanceUrl) {
    setConnectStatus("GitLab instance URL is required.")
    return
  }
  if (!token) {
    setConnectStatus("Personal access token is required.")
    return
  }

  const requestId = loadConnectProjectsRequestIdRef.current + 1
  loadConnectProjectsRequestIdRef.current = requestId
  const isStaleRequest = () => loadConnectProjectsRequestIdRef.current !== requestId

  setIsLoadingConnectProjects(true)
  try {
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action: "projects",
        instanceUrl,
        token,
      }),
    })
    const parsedPayload = await parseJsonResponse(response)
    const payload = parsedPayload.ok ? parsedPayload.value : null
    if (isStaleRequest()) {
      return
    }
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, "Failed to load projects from GitLab."))
    }

    const root = asRecord(payload)
    const records = Array.isArray(root?.data) ? root.data : []

    const projects = records.flatMap((record) => {
      const row = asRecord(record)
      if (!row) {
        return []
      }
      if (typeof row.id !== "string" || typeof row.path !== "string") {
        return []
      }
      return [{
        id: row.id,
        path: row.path,
        name: typeof row.name === "string" ? row.name : row.path,
        defaultBranch:
          typeof row.defaultBranch === "string" && row.defaultBranch.trim().length > 0
            ? row.defaultBranch
            : undefined,
      }]
    })

    setConnectProjects(projects)
    setConnectProjectId((current) =>
      current && projects.some((project) => project.id === current)
        ? current
        : (projects[0]?.id ?? ""),
    )
    setConnectStatus(
      projects.length > 0
        ? `Loaded ${projects.length} projects. Select one to connect.`
        : "No projects found for this token.",
    )
  } catch (error) {
    if (isStaleRequest()) {
      return
    }
    setConnectStatus(error instanceof Error ? error.message : "Failed to load projects.")
  } finally {
    if (!isStaleRequest()) {
      setIsLoadingConnectProjects(false)
    }
  }
}, [connectInstanceUrl, connectToken])

const handleConnectProject = useCallback(async () => {
  const project = selectedConnectProject
  const instanceUrl = connectInstanceUrl.trim()
  const token = connectToken.trim()
  if (!project) {
    setConnectStatus("Select a project first.")
    return
  }

if (!instanceUrl || !token) {
  setConnectStatus("GitLab instance URL and token are required.")
  return
}

setIsConnectingProject(true)
try {
  const connectResponse = await fetch("/api/gitlab/integrations/connect", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      instanceUrl,
      token,
      projectId: project.id,
      projectPath: project.path,
      projectName: project.name,
    }),
  })
  const parsedConnectPayload = await parseJsonResponse(connectResponse)
  const connectPayload = parsedConnectPayload.ok ? parsedConnectPayload.value : null
  if (!connectResponse.ok) {
    throw new Error(extractErrorMessage(connectPayload, "Failed to connect integration."))
  }

  const connectRoot = asRecord(connectPayload)
  const warning =
    typeof connectRoot?.warning === "string" && connectRoot.warning.trim().length > 0
      ? connectRoot.warning
      : null
  const integration = asRecord(connectRoot?.data)
  const integrationId =
    typeof integration?.id === "string" && integration.id.trim().length > 0
      ? integration.id
      : null

  if (!integrationId) {
    throw new Error("Connect response is missing integration id.")
  }

    if (!project.defaultBranch) {
      setConnectStatus(
        warning ??
          `Connected ${project.path}. No default branch found, so indexing was not queued.`,
      )
      invalidateGitLabIntegrationsQuery()
      await loadIntegrationsData({ forceRefresh: true })
      return
    }

    const enableResponse = await fetch(`/api/gitlab/integrations/${integrationId}/index/enable`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        branch: project.defaultBranch,
      }),
    })
    const parsedEnablePayload = await parseJsonResponse(enableResponse)
    const enablePayload = parsedEnablePayload.ok ? parsedEnablePayload.value : null
    if (!enableResponse.ok) {
      throw new Error(extractErrorMessage(enablePayload, "Connected, but failed to queue indexing."))
    }

    setConnectStatus(
      warning ??
        `Connected ${project.path}. Indexing queued for ${project.defaultBranch}.`,
    )
    invalidateGitLabIntegrationsQuery()
    await loadIntegrationsData({ forceRefresh: true })
  } catch (error) {
    setConnectStatus(error instanceof Error ? error.message : "Failed to connect project.")
  } finally {
    setIsConnectingProject(false)
  }
}, [connectInstanceUrl, connectToken, loadIntegrationsData, selectedConnectProject])

