#[derive(Debug, Clone, Copy)]
pub struct IndexPhases {
  pub parse: bool,
  pub graph: bool,
  pub vector: bool,
  pub scip: bool,
  pub index_pack: bool,
}

impl Default for IndexPhases {
  fn default() -> Self {
    Self {
      parse: true,
      graph: true,
      vector: false,
      scip: false,
      index_pack: true,
    }
  }
}

impl IndexPhases {
  pub fn normalized(self) -> Self {
    let mut phases = self;
    // Downstream phases consume parsed chunks, so parse must be enabled when any of them run.
    if phases.graph || phases.vector || phases.scip {
      phases.parse = true;
    }
    phases
  }
}

#[derive(Debug, Clone)]
pub struct IndexOutputOptions {
  pub data_dir: Option<PathBuf>,
  pub index_pack_dir: Option<PathBuf>,
  pub schema_version: String,
  pub index_run_id: String,
  pub project_root_rel: Option<String>,
  pub incremental: bool,
}

impl Default for IndexOutputOptions {
  fn default() -> Self {
    let run_id = OffsetDateTime::now_utc().unix_timestamp();
    Self {
      data_dir: None,
      index_pack_dir: None,
      schema_version: "1.0.0".to_string(),
      index_run_id: format!("run-{run_id}"),
      project_root_rel: None,
      incremental: false,
    }
  }
}

impl IndexOutputOptions {
  pub fn resolve_data_dir(&self, project_root: &Path) -> PathBuf {
    self
      .data_dir
      .clone()
      .unwrap_or_else(|| project_root.join(".argus-search"))
  }

  pub fn resolve_index_pack_dir(&self, project_root: &Path) -> PathBuf {
    self
      .index_pack_dir
      .clone()
      .unwrap_or_else(|| self.resolve_data_dir(project_root).join("index-pack"))
  }
}

#[derive(Debug, Clone, Default)]
pub struct ScipIndexSettings {
  pub data_dir: Option<PathBuf>,
  pub indexer_config: ScipIndexerConfig,
}

#[derive(Clone)]

pub struct IndexOptions {
  pub project_root: PathBuf,
  pub inputs: ParseInputs,
  pub phases: IndexPhases,
  pub output: IndexOutputOptions,
  pub cache: CacheOptions,
  pub parse_batch: usize,
  pub graph_batch: usize,
  pub scip_batch: usize,
  pub vector: VectorOptions,
  pub scip_index: ScipIndexSettings,
  pub vector_provider: Option<Arc<dyn EmbeddingsProvider>>,
}

impl IndexOptions {
  pub fn new(project_root: impl Into<PathBuf>) -> Self {
    let project_root = project_root.into();
    Self {
      project_root,
      inputs: ParseInputs::default(),
      phases: IndexPhases::default(),
      output: IndexOutputOptions::default(),
      cache: CacheOptions::default(),
      parse_batch: 256,
      graph_batch: 512,
      scip_batch: 512,
      vector: VectorOptions::default(),
      scip_index: ScipIndexSettings::default(),
      vector_provider: None,
    }
  }
}

#[derive(Debug, Clone, Default, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct IndexStats {
  pub parse: Option<ParseStats>,
  pub graph: Option<GraphStats>,
  pub vector: Option<VectorStats>,
  pub scip: Option<ScipStats>,
  pub index_pack: Option<IndexPackManifest>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IndexPhase {
  Parse,
  Graph,
  Vector,
  Scip,
}

impl IndexPhase {
  pub fn as_str(self) -> &'static str {
    match self {
      IndexPhase::Parse => "parse",
      IndexPhase::Graph => "graph",
      IndexPhase::Vector => "vector",
      IndexPhase::Scip => "scip",
    }
  }
}

#[derive(Debug, Clone)]

pub enum IndexEvent {
  PhaseStarted {
    phase: IndexPhase,
    timestamp_ms: i64,
  },
  PhaseProgress {
    phase: IndexPhase,
    current: u64,
    total: u64,
    file: Option<String>,
    detail: Option<String>,
    unit: Option<String>,
  },
  PhaseCompleted {
    phase: IndexPhase,
    duration_ms: u64,
    stats: Option<PhaseStats>,
  },
  PhaseError {
    phase: IndexPhase,
    error: String,
    recoverable: bool,
  },
  PipelineCompleted {
    duration_ms: u64,
    stats: Box<IndexStats>,
    errors: Vec<String>,
  },
}

#[derive(Debug, Clone)]
pub enum PhaseStats {
  Parse(ParseStats),
  Graph(GraphStats),
  Vector(VectorStats),
  Scip(ScipStats),
}

impl PhaseStats {
  pub fn to_json(&self) -> serde_json::Value {
    match self {
      PhaseStats::Parse(stats) => serde_json::to_value(stats).unwrap_or_default(),
      PhaseStats::Graph(stats) => serde_json::to_value(stats).unwrap_or_default(),
      PhaseStats::Vector(stats) => serde_json::to_value(stats).unwrap_or_default(),
      PhaseStats::Scip(stats) => serde_json::to_value(stats).unwrap_or_default(),
    }
  }
}

impl IndexEvent {
  pub fn to_json(&self) -> serde_json::Value {
    match self {
      IndexEvent::PhaseStarted {
        phase,
        timestamp_ms,
      } => serde_json::json!({
        "type": "phase:start",
        "phase": phase.as_str(),
        "timestamp": timestamp_ms,
      }),
      IndexEvent::PhaseProgress {
        phase,
        current,
        total,
        file,
        detail,
        unit,
      } => serde_json::json!({
        "type": "phase:progress",
        "phase": phase.as_str(),
        "current": current,
        "total": total,
        "file": file,
        "detail": detail,
        "unit": unit,
      }),
      IndexEvent::PhaseCompleted {
        phase,
        duration_ms,
        stats,
      } => serde_json::json!({
        "type": "phase:complete",
        "phase": phase.as_str(),
        "durationMs": duration_ms,
        "stats": stats.as_ref().map(PhaseStats::to_json),
      }),
      IndexEvent::PhaseError {
        phase,
        error,
        recoverable,
      } => serde_json::json!({
        "type": "phase:error",
        "phase": phase.as_str(),
        "error": error,
        "recoverable": recoverable,
      }),
      IndexEvent::PipelineCompleted {
        duration_ms,
        stats,
        errors,
      } => serde_json::json!({
        "type": "pipeline:complete",
        "durationMs": duration_ms,
        "stats": stats,
        "errors": if errors.is_empty() { None } else { Some(errors) },
      }),
    }
  }
}

pub trait IndexSink: ParseSink + GraphSink + VectorSink + ScipSink {
  fn on_event(&mut self, _event: IndexEvent) {}
  // Sinks that need complete snapshots (for example, persistence sinks) can force re-parse.
  fn disable_parse_skip(&self, _phases: IndexPhases) -> bool {
    false
  }
  fn on_parsed_files(
    &mut self,
    _files: &[crate::core::parse::types::ParsedFile],
    _phases: IndexPhases,
  ) -> Result<(), String> {
    Ok(())
  }
}

#[derive(Debug)]
pub enum IndexError {
  Parse(ParseError),
  Graph(GraphError),
  Vector(VectorError),
  Scip(ScipError),
  Io(std::io::Error),
  Cache(CacheError),
  Sink(String),
  MissingVectorProvider,
  Cancelled,
}

impl std::fmt::Display for IndexError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      IndexError::Parse(err) => write!(f, "parse error: {err}"),
      IndexError::Graph(err) => write!(f, "graph error: {err}"),
      IndexError::Vector(err) => write!(f, "{err}"),
      IndexError::Scip(err) => write!(f, "{err}"),
      IndexError::Io(err) => write!(f, "index io error: {err}"),
      IndexError::Cache(err) => write!(f, "{err}"),
      IndexError::Sink(err) => write!(f, "{err}"),
      IndexError::MissingVectorProvider => write!(f, "vector provider missing"),
      IndexError::Cancelled => write!(f, "cancelled"),
    }
  }
}

impl std::error::Error for IndexError {}

impl From<ParseError> for IndexError {
  fn from(value: ParseError) -> Self {
    match value {
      ParseError::Cancelled => IndexError::Cancelled,
      other => IndexError::Parse(other),
    }
  }
}

impl From<GraphError> for IndexError {
  fn from(value: GraphError) -> Self {
    match value {
      GraphError::Cancelled => IndexError::Cancelled,
      other => IndexError::Graph(other),
    }
  }
}

impl From<VectorError> for IndexError {
  fn from(value: VectorError) -> Self {
    match value {
      VectorError::Cancelled => IndexError::Cancelled,
      other => IndexError::Vector(other),
    }
  }
}

impl From<CacheError> for IndexError {
  fn from(value: CacheError) -> Self {
    IndexError::Cache(value)
  }
}

impl From<ScipError> for IndexError {
  fn from(value: ScipError) -> Self {
    match value {
      ScipError::Cancelled => IndexError::Cancelled,
      other => IndexError::Scip(other),
    }
  }
}

impl From<std::io::Error> for IndexError {
  fn from(value: std::io::Error) -> Self {
    IndexError::Io(value)
  }
}

pub struct IndexEngine {
  options: IndexOptions,
}

impl IndexEngine {
  pub fn new(options: IndexOptions) -> Self {
    Self { options }
  }

  pub fn run(
    &self,
    sink: &mut dyn IndexSink,
    cancel: &CancelToken,
  ) -> Result<IndexStats, IndexError> {
    cancel.check().map_err(|_| IndexError::Cancelled)?;
    let start_time = Instant::now();
    let phases = self.options.phases.normalized();
    let mut stats = IndexStats::default();
    let mut errors: Vec<String> = Vec::new();

    let data_dir = self
      .options
      .output
      .resolve_data_dir(&self.options.project_root);
    let index_pack_dir = self
      .options
      .output
      .resolve_index_pack_dir(&self.options.project_root);

// Index-pack is an optional side-channel artifact emitted during each phase.
let mut writer = if phases.index_pack {
  let mut options = IndexPackWriterOptions::new(
    &index_pack_dir,
    self.options.output.schema_version.clone(),
    self.options.output.index_run_id.clone(),
    &self.options.project_root,
  );
  options.project_root_rel = self.options.output.project_root_rel.clone();
  Some(IndexPackWriter::new(options)?)
} else {
  None
};

// Cache state is shared across parse runs and persisted once at the end.
let mut cache = if self.options.cache.enabled {
  let cache_path = self.options.cache.resolve_path(&data_dir);
  Some(CacheState::load(cache_path))
} else {
  None
};

// Keep parse options local so phase-level overrides do not mutate engine defaults.
let mut parse_options = ParseOptions::new(self.options.project_root.clone());
parse_options.inputs = self.options.inputs.clone();
parse_options.batch_size = self.options.parse_batch;

let (parsed_files, parse_stats) = if phases.parse {
  let phase_start = Instant::now();
  sink.on_event(IndexEvent::PhaseStarted {
    phase: IndexPhase::Parse,
    timestamp_ms: epoch_millis(),
  });
  // Incremental parse skip is only valid when cache + incremental output are enabled.
  // Sinks may still opt out to guarantee full chunk emission.
  let cache_policy = ParseCachePolicy {
    allow_skip: self.options.cache.enabled
      && self.options.output.incremental
      && !sink.disable_parse_skip(phases),
    force: self.options.cache.force,
  };
  let (files, parse_stats) = run_parse(
    &parse_options,
    cancel,
    cache.as_mut(),
    cache_policy,
    sink,
    writer.as_mut(),
  )?;
  sink.on_event(IndexEvent::PhaseCompleted {
    phase: IndexPhase::Parse,
    duration_ms: phase_start.elapsed().as_millis() as u64,
    stats: Some(PhaseStats::Parse(parse_stats.clone())),
  });
  (files, parse_stats)
} else {
  (Vec::new(), ParseStats::default())
};

if let Some(writer) = writer.as_mut() {
  writer.set_files_parsed(parse_stats.files_parsed);
}
stats.parse = if phases.parse {
  Some(parse_stats)
} else {
  None
};

// Give sinks access to the full parse snapshot before graph/vector/scip phases.
sink
  .on_parsed_files(&parsed_files, phases)
  .map_err(IndexError::Sink)?;

if phases.graph {
  let phase_start = Instant::now();
  sink.on_event(IndexEvent::PhaseStarted {
    phase: IndexPhase::Graph,
    timestamp_ms: epoch_millis(),
  });
  let mut graph_options = GraphOptions::new(&self.options.project_root);
  graph_options.batch_size = self.options.graph_batch;
  let graph_stats = run_graph(&parsed_files, &graph_options, cancel, sink, writer.as_mut())?;
  sink.on_event(IndexEvent::PhaseCompleted {
    phase: IndexPhase::Graph,
    duration_ms: phase_start.elapsed().as_millis() as u64,
    stats: Some(PhaseStats::Graph(graph_stats.clone())),
  });
  stats.graph = Some(graph_stats);
}

if phases.vector {
  let provider = self
    .options
    .vector_provider
    .clone()
    .ok_or(IndexError::MissingVectorProvider)?;
  // Vector progress is measured in chunks so UI clients can render deterministic progress bars.
  let total_chunks = parsed_files
    .iter()
    .map(|file| file.chunks.len() as u64)
    .sum::<u64>();
  let phase_start = Instant::now();
  sink.on_event(IndexEvent::PhaseStarted {
    phase: IndexPhase::Vector,
    timestamp_ms: epoch_millis(),
  });

  struct VectorProgressSink<'a> {
    inner: &'a mut dyn IndexSink,
    current: u64,
    total: u64,
  }

  impl crate::core::vector::engine::VectorSink for VectorProgressSink<'_> {
    fn on_vector_batch(&mut self, batch: crate::core::vector::types::VectorBatch) {
      // Forward raw batch first, then emit phase progress derived from processed chunk count.
      self.current = self.current.saturating_add(batch.len() as u64);
      self.inner.on_vector_batch(batch);
      self.inner.on_event(IndexEvent::PhaseProgress {
        phase: IndexPhase::Vector,
        current: self.current,
        total: self.total,
        file: None,
        detail: None,
        unit: Some("chunk".to_string()),
      });
    }
  }

  let vector_stats = {
    let mut sink = VectorProgressSink {
      inner: sink,
      current: 0,
      total: total_chunks,
    };
    run_vector(
      &parsed_files,
      &self.options.vector,
      provider,
      cancel,
      &mut sink,
      writer.as_mut(),
    )?
  };
  sink.on_event(IndexEvent::PhaseCompleted {
    phase: IndexPhase::Vector,
    duration_ms: phase_start.elapsed().as_millis() as u64,
    stats: Some(PhaseStats::Vector(vector_stats.clone())),
  });
  stats.vector = Some(vector_stats);
}

if phases.scip {
  // SCIP runs from discovered source files, not parse output, so it can index files skipped by parse cache.
  let input_files = discover_files(&self.options.project_root, &self.options.inputs, cancel)?;

let scip_files = input_files
  .iter()
  .map(|path| relative_path(&self.options.project_root, path))
  .collect::<Vec<_>>();
let scip_data_dir = self
  .options
  .scip_index
  .data_dir
  .clone()
  .unwrap_or_else(|| data_dir.clone());

let scip_index_options = ScipIndexOptions {
  project_root: self.options.project_root.clone(),
  files: scip_files,
  data_dir: Some(scip_data_dir),
  indexer_config: self.options.scip_index.indexer_config.clone(),
};

let provider = ScipCliProvider::from_default_indexers(&scip_index_options);
let phase_start = Instant::now();
sink.on_event(IndexEvent::PhaseStarted {
  phase: IndexPhase::Scip,
  timestamp_ms: epoch_millis(),
});

  if !provider.indexers.is_empty() {
    let mut scip_options = ScipOptions::new(&self.options.project_root);
    scip_options.batch_size = self.options.scip_batch;
    let scip_stats = run_scip(
      &provider,
      &scip_index_options,
      &scip_options,
      cancel,
      sink,
      writer.as_mut(),
    )?;
    sink.on_event(IndexEvent::PhaseCompleted {
      phase: IndexPhase::Scip,
      duration_ms: phase_start.elapsed().as_millis() as u64,
      stats: Some(PhaseStats::Scip(scip_stats.clone())),
    });
    stats.scip = Some(scip_stats);
  } else {
    let message = "no SCIP indexers available; skipping SCIP phase".to_string();
    errors.push(message.clone());
    sink.on_event(IndexEvent::PhaseError {
      phase: IndexPhase::Scip,
      error: message,
      recoverable: true,
    });
    let scip_stats = ScipStats::default();
    sink.on_event(IndexEvent::PhaseCompleted {
      phase: IndexPhase::Scip,
      duration_ms: phase_start.elapsed().as_millis() as u64,
      stats: Some(PhaseStats::Scip(scip_stats.clone())),
    });
    stats.scip = Some(scip_stats);
  }
}

if let Some(writer) = writer.as_mut() {
  let manifest = writer.finalize()?;
  stats.index_pack = Some(manifest);
}

if let Some(cache) = cache.as_mut() {
  cache.save()?;
}

    sink.on_event(IndexEvent::PipelineCompleted {
      duration_ms: start_time.elapsed().as_millis() as u64,
      stats: Box::new(stats.clone()),
      errors,
    });

    Ok(stats)
  }
}

fn epoch_millis() -> i64 {
  let nanos = OffsetDateTime::now_utc().unix_timestamp_nanos();
  (nanos / 1_000_000) as i64
}

fn relative_path(project_root: &Path, path: &Path) -> String {
  path
    .strip_prefix(project_root)
    .unwrap_or(path)
    .to_string_lossy()
    .replace('\\', "/")
}

