#[test]

fn runs_parse_and_graph_with_index_pack() -> Result<(), Box<dyn std::error::Error>> {
  let temp = tempfile::tempdir()?;
  let file_path = temp.path().join("sample.js");
  std::fs::write(&file_path, "function foo() {}\n")?;

  let mut options = IndexOptions::new(temp.path());
  options.inputs.paths = vec![temp.path().to_path_buf()];
  options.inputs.include = vec!["*.js".to_string()];
  options.phases = IndexPhases {
    parse: true,
    graph: true,
    vector: false,
    scip: false,
    index_pack: true,
  };
  options.output.index_pack_dir = Some(temp.path().join("index-pack"));
  options.output.schema_version = "1.0.0".to_string();
  options.output.index_run_id = "run-test".to_string();
  options.parse_batch = 1;
  options.graph_batch = 1;

  let engine = IndexEngine::new(options);
  let mut sink = TestSink {
    parse_batches: 0,
    graph_batches: 0,
  };

  let stats = engine.run(&mut sink, &CancelToken::new())?;
  assert!(stats.parse.is_some());
  assert!(stats.graph.is_some());
  assert!(sink.parse_batches > 0);
  assert!(sink.graph_batches > 0);

  let index_pack_dir = temp.path().join("index-pack");
  assert!(index_pack_dir.join("manifest.json").exists());
  assert!(index_pack_dir.join("chunks.jsonl").exists());
  assert!(index_pack_dir.join("graph.nodes.jsonl").exists());
  assert!(index_pack_dir.join("graph.edges.jsonl").exists());

  Ok(())
}

