  options.inputs.paths = vec![temp.path().to_path_buf()];
  options.inputs.include = vec!["*.js".to_string()];
  options.phases = IndexPhases {
    parse: true,
    graph: true,
    vector: false,
    scip: false,
    index_pack: false,
  };
  options.cache.enabled = true;

  options.output.incremental = true;

  let run_once = |options: &IndexOptions,
                  store_path: &std::path::Path|
   -> Result<(), Box<dyn std::error::Error>> {
    let engine = IndexEngine::new(options.clone());
    let mut sink = KiteDbIndexSink::new(store_path.to_path_buf(), false);
    engine.run(&mut sink, &CancelToken::new())?;
    sink.finish()?;
    Ok(())
  };

  run_once(&options, &store_path)?;
  let store = KiteCodeStore::open_readonly(store_path.clone())?;
  assert!(store.has_ci_id("ts:function:sample.js:foo:0"));

  fs::write(&file_path, "function bar() {}\n")?;
  run_once(&options, &store_path)?;
  let store = KiteCodeStore::open_readonly(store_path.clone())?;
  assert!(!store.has_ci_id("ts:function:sample.js:foo:0"));
  assert!(store.has_ci_id("ts:function:sample.js:bar:0"));

  fs::remove_file(&file_path)?;
  run_once(&options, &store_path)?;
  let store = KiteCodeStore::open_readonly(store_path)?;
  assert!(!store.has_ci_id("ts:function:sample.js:bar:0"));
  assert!(!store.has_ci_id("ts:file:sample.js"));

  Ok(())
}

