import { useCallback, useEffect, useRef, useState } from "react"

import {
  REVIEW_STREAM_MAX_RECONNECT_ATTEMPTS,
  REVIEW_STREAM_RECONNECT_BASE_DELAY_MS,
  REVIEW_TRACE_STORAGE_PREFIX,
  normalizeReviewRunStage,
  parseReviewStreamEventRecord,
  toRecord,
  type ReviewStreamEventRecord,
  type ReviewStreamReadyPayload,
} from "./use-ai-review.utils"

type UseMergeRequestAiReviewStreamArgs = {
  instanceUrl: string
  projectId: string
  mergeRequestIid: string
  getLatestEventId: () => number
  applyStreamRunSnapshot: (runValue: unknown) => void
  applyStreamEvent: (record: ReviewStreamEventRecord) => void
  onConnectionLost: () => void
}

export function useMergeRequestAiReviewStream({
  instanceUrl,
  projectId,
  mergeRequestIid,
  getLatestEventId,
  applyStreamRunSnapshot,
  applyStreamEvent,
  onConnectionLost,
}: UseMergeRequestAiReviewStreamArgs) {
  const [reviewTraceId, setReviewTraceId] = useState<string | null>(null)
  const reviewTraceIdRef = useRef<string | null>(null)
  const reviewStreamRef = useRef<EventSource | null>(null)
  const reviewStreamSessionRef = useRef(0)
  const reviewStreamReconnectTimerRef = useRef<number | null>(null)

  const buildRequestHeaders = useCallback((base: Record<string, string> = {}) => {
    const traceId = reviewTraceIdRef.current?.trim()
    if (!traceId) {
      return base
    }
    return {
      ...base,
      "x-request-id": traceId,
    }
  }, [])

  const setCurrentTraceId = useCallback((traceId: string | null) => {
    reviewTraceIdRef.current = traceId
    setReviewTraceId(traceId)
  }, [])

const getCurrentTraceId = useCallback(() => {
  return reviewTraceIdRef.current ?? ""
}, [])

const buildReviewTraceStorageKey = useCallback(() => {
  return [
    REVIEW_TRACE_STORAGE_PREFIX,
    instanceUrl.trim().replace(/\/+$/, ""),
    projectId.trim(),
    mergeRequestIid.trim(),
  ].join(":")
}, [instanceUrl, mergeRequestIid, projectId])

const storeActiveTraceId = useCallback(
  (traceId: string) => {
    if (typeof window === "undefined") {
      return
    }
    window.sessionStorage.setItem(buildReviewTraceStorageKey(), traceId)
  },
  [buildReviewTraceStorageKey],
)

const clearActiveTraceId = useCallback(() => {
  if (typeof window === "undefined") {
    return
  }
  window.sessionStorage.removeItem(buildReviewTraceStorageKey())
}, [buildReviewTraceStorageKey])

const readStoredTraceId = useCallback(() => {
  if (typeof window === "undefined") {
    return ""
  }
  return window.sessionStorage.getItem(buildReviewTraceStorageKey()) ?? ""
}, [buildReviewTraceStorageKey])

const clearReviewStreamReconnectTimer = useCallback(() => {
  if (reviewStreamReconnectTimerRef.current) {
    window.clearTimeout(reviewStreamReconnectTimerRef.current)
    reviewStreamReconnectTimerRef.current = null
  }
}, [])

const closeReviewStream = useCallback(() => {
  reviewStreamSessionRef.current += 1
  clearReviewStreamReconnectTimer()
  if (reviewStreamRef.current) {
    reviewStreamRef.current.close()
    reviewStreamRef.current = null
  }
}, [clearReviewStreamReconnectTimer])

useEffect(() => {
  return () => {
    closeReviewStream()
  }
}, [closeReviewStream])

const connectReviewStream = useCallback(
  async (traceId: string) => {
    closeReviewStream()
    const sessionId = reviewStreamSessionRef.current + 1
    reviewStreamSessionRef.current = sessionId

    return await new Promise<"done" | "failed" | "closed">((resolve) => {
      let reconnectAttempts = 0

      const finish = (status: "done" | "failed" | "closed") => {
        if (reviewStreamSessionRef.current !== sessionId) {
          return
        }
        clearReviewStreamReconnectTimer()
        if (reviewStreamRef.current) {
          reviewStreamRef.current.close()
          reviewStreamRef.current = null
        }
        resolve(status)
      }

      const connect = () => {
        if (reviewStreamSessionRef.current !== sessionId) {
          resolve("closed")
          return
        }

        const params = new URLSearchParams({ traceId })
        const afterId = getLatestEventId()
        if (afterId > 0) {
          params.set("afterId", String(afterId))
        }

        const source = new EventSource(`/api/review/diff/stream?${params.toString()}`)
        reviewStreamRef.current = source

        source.onopen = () => {
          reconnectAttempts = 0
        }

source.addEventListener("ready", (event) => {
  let payload: ReviewStreamReadyPayload
  try {
    payload = JSON.parse((event as MessageEvent).data ?? "{}") as ReviewStreamReadyPayload
  } catch {
    payload = {}
  }
  setCurrentTraceId(traceId)
  applyStreamRunSnapshot(payload.run)

  if (Array.isArray(payload.events)) {
    for (const streamEvent of payload.events) {
      const parsed = parseReviewStreamEventRecord(streamEvent)
      if (!parsed) {
        continue
      }
      applyStreamEvent(parsed)
      if (parsed.eventType === "done") {
        clearActiveTraceId()
        finish("done")
        return
      }
      if (parsed.eventType === "failed") {
        clearActiveTraceId()
        finish("failed")
        return
      }
    }
  }

  const readyRun = toRecord(payload.run)
  const readyStage = normalizeReviewRunStage(readyRun.stage, "queued")
  const readyStatus = String(readyRun.status ?? "").trim().toLowerCase()
  if (readyStage === "done" || readyStatus === "success") {
    clearActiveTraceId()
    finish("done")
  } else if (readyStage === "failed" || readyStatus === "failed") {
    clearActiveTraceId()
    finish("failed")
  }
})

const handleStreamEvent = (event: MessageEvent) => {
  let parsedPayload: unknown = {}
  try {
    parsedPayload = JSON.parse(event.data ?? "{}")
  } catch {
    parsedPayload = {}
  }
  const parsed = parseReviewStreamEventRecord(parsedPayload)
  if (!parsed) {
    return
  }
  applyStreamEvent(parsed)
  if (parsed.eventType === "done") {
    clearActiveTraceId()
    finish("done")
  } else if (parsed.eventType === "failed") {
    clearActiveTraceId()
    finish("failed")
  }
}

source.addEventListener("progress", (event) => {
  handleStreamEvent(event as MessageEvent)
})
source.addEventListener("summary", (event) => {
  handleStreamEvent(event as MessageEvent)
})
source.addEventListener("done", (event) => {
  handleStreamEvent(event as MessageEvent)
})
source.addEventListener("failed", (event) => {
  handleStreamEvent(event as MessageEvent)
})

          source.onerror = () => {
            if (reviewStreamSessionRef.current !== sessionId) {
              resolve("closed")
              return
            }
            source.close()
            if (reconnectAttempts >= REVIEW_STREAM_MAX_RECONNECT_ATTEMPTS) {
              onConnectionLost()
              finish("failed")
              return
            }
            reconnectAttempts += 1
            const delayMs = Math.min(
              10_000,
              REVIEW_STREAM_RECONNECT_BASE_DELAY_MS * 2 ** (reconnectAttempts - 1),
            )
            reviewStreamReconnectTimerRef.current = window.setTimeout(connect, delayMs)
          }
        }

        connect()
      })
    },
    [
      applyStreamEvent,
      applyStreamRunSnapshot,
      clearActiveTraceId,
      clearReviewStreamReconnectTimer,
      closeReviewStream,
      getLatestEventId,
      onConnectionLost,
      setCurrentTraceId,
    ],
  )

  return {
    reviewTraceId,
    buildRequestHeaders,
    buildReviewTraceStorageKey,
    storeActiveTraceId,
    clearActiveTraceId,
    readStoredTraceId,
    closeReviewStream,
    connectReviewStream,
    setCurrentTraceId,
    getCurrentTraceId,
  }
}

import {
  DIFF_CHUNK_BYTES_CAP,
  DIFF_GLOBAL_BYTES_CAP,
  DIFF_PER_FILE_BYTES_CAP,
} from "./constants"
import {
  type DiffFileContentState,
  type DiffManifestFile,
  type DiffManifestMode,
  type DiffManifestResponseData,
  type GitLabMergeRequestChange,
  type GitLabMergeRequestDetails,
  type ParsedChangesResult,
  type ParsedPatchFile,
} from "./types"

export const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

export const asString = (value: unknown) => (typeof value === "string" ? value.trim() : "")
const asBoolean = (value: unknown) => value === true

export const countDiffStats = (patch: string) => {
  let additions = 0
  let deletions = 0

  const lines = patch.split("\n")
  for (const line of lines) {
    if (line.startsWith("+++ ")) {
      continue
    }
    if (line.startsWith("--- ")) {
      continue
    }
    if (line.startsWith("+")) {
      additions += 1
      continue
    }
    if (line.startsWith("-")) {
      deletions += 1
    }
  }

  return {
    additions,
    deletions,
  }
}

const splitPatchIntoFileChunks = (patchText: string) => {
  const splitByFile = patchText.split(/^diff --git /m)
  if (splitByFile.length <= 1) {
    return []
  }

  const metadataPrefix = splitByFile[0].trim()

  return splitByFile
    .slice(1)
    .map((part, index) => {
      const chunk = `diff --git ${part}`.trim()
      if (!chunk) {
        return ""
      }
      if (index === 0 && metadataPrefix) {
        return `${metadataPrefix}\n${chunk}`
      }
      return chunk
    })
    .filter((chunk): chunk is string => chunk.length > 0)
}

const parseFilePaths = (fileChunk: string) => {
  const lines = fileChunk.split("\n")
  const first = lines[0] ?? ""

  const diffMatch = first.match(/^diff --git a\/(.+?) b\/(.+)$/)
  let oldPath = diffMatch ? diffMatch[1] : null
  let newPath = diffMatch ? diffMatch[2] : null

  const oldHeader = lines.find((line) => line.startsWith("--- "))
  const newHeader = lines.find((line) => line.startsWith("+++ "))

  if (oldHeader) {
    const value = oldHeader.slice(4).trim()
    oldPath = value === "/dev/null" ? null : value.replace(/^a\//, "")
  }
  if (newHeader) {
    const value = newHeader.slice(4).trim()
    newPath = value === "/dev/null" ? null : value.replace(/^b\//, "")
  }

  return {
    oldPath,
    newPath,
  }
}

const resolveChangeType = (fileChunk: string): DiffManifestFile["changeType"] => {
  if (/\nnew file mode /m.test(fileChunk)) {
    return "added"
  }
  if (/\ndeleted file mode /m.test(fileChunk)) {
    return "deleted"
  }
  if (/\nrename from /m.test(fileChunk) || /\nrename to /m.test(fileChunk)) {
    return "renamed"
  }
  return "modified"
}

const resolveChangeTypeFromChange = (
  change: GitLabMergeRequestChange,
  filePatch: string | null,
): DiffManifestFile["changeType"] => {
  if (change.newFile) {
    return "added"
  }
  if (change.deletedFile) {
    return "deleted"
  }
  if (change.renamedFile) {
    return "renamed"
  }
  if (filePatch) {
    return resolveChangeType(filePatch)
  }
  return "modified"
}

const buildFilePatchFromChange = (change: GitLabMergeRequestChange) => {
  if (!change.diff) {
    return null
  }

  if (change.diff.startsWith("diff --git ")) {
    return change.diff
  }

  const oldPath = change.oldPath ?? change.newPath ?? "unknown"
  const newPath = change.newPath ?? change.oldPath ?? "unknown"
  const oldHeader = change.newFile ? "/dev/null" : `a/${oldPath}`
  const newHeader = change.deletedFile ? "/dev/null" : `b/${newPath}`
  const diffHeader = `diff --git a/${oldPath} b/${newPath}`
  const includesFileHeaders = /^---\s/m.test(change.diff) && /^\+\+\+\s/m.test(change.diff)

  if (includesFileHeaders) {
    return `${diffHeader}\n${change.diff}`
  }

  return `${diffHeader}\n--- ${oldHeader}\n+++ ${newHeader}\n${change.diff}`
}

const parseMergeRequestChanges = (payload: unknown): GitLabMergeRequestChange[] => {
  const root = asRecord(payload)
  const rawChanges = Array.isArray(root?.changes) ? root.changes : []

  return rawChanges.flatMap((value) => {
    const row = asRecord(value)
    if (!row) {
      return []
    }

    const oldPath = asString(row.old_path) || null
    const newPath = asString(row.new_path) || null
    if (!oldPath && !newPath) {
      return []
    }

    const diffValue = row.diff
    const diff = typeof diffValue === "string" ? diffValue.trimEnd() : ""

    return [
      {
        oldPath,
        newPath,
        diff,
        newFile: asBoolean(row.new_file),
        deletedFile: asBoolean(row.deleted_file),
        renamedFile: asBoolean(row.renamed_file),
        tooLarge: asBoolean(row.too_large),
        collapsed: asBoolean(row.collapsed),
      } satisfies GitLabMergeRequestChange,
    ]
  })
}

export const buildParsedFilesFromChangesPayload = (payload: unknown): ParsedChangesResult => {
  const changes = parseMergeRequestChanges(payload)
  const parsedFiles: ParsedPatchFile[] = []
  let additions = 0
  let deletions = 0
  let estimatedBytesTotal = 0
  let estimatedBytesKnown = true

for (let index = 0; index < changes.length; index += 1) {
  const change = changes[index]
  const filePatch = buildFilePatchFromChange(change)
  const changeType = resolveChangeTypeFromChange(change, filePatch)
  const estimatedBytes = filePatch ? Buffer.byteLength(filePatch, "utf8") : null
  const requiresExternal = estimatedBytes !== null && estimatedBytes > DIFF_PER_FILE_BYTES_CAP
  const upstreamTruncated = change.tooLarge || change.collapsed

  let contentState: DiffFileContentState
  let content: string | null

  if (!filePatch || requiresExternal) {
    contentState = "requires_external"
    content = null
  } else if (upstreamTruncated) {
    contentState = "truncated"
    content = filePatch
  } else {
    contentState = "available"
    content = filePatch
  }

  if (filePatch) {
    const stats = countDiffStats(filePatch)
    additions += stats.additions
    deletions += stats.deletions
  }

  if (estimatedBytes === null) {
    estimatedBytesKnown = false
  } else {
    estimatedBytesTotal += estimatedBytes
  }

  parsedFiles.push({
    fileId: `file_${index + 1}`,
    oldPath: change.oldPath,
    newPath: change.newPath,
    changeType,
    estimatedBytes,
    contentState,
    content,
    truncated: upstreamTruncated,
  })
}

return {
  files: parsedFiles,
  additions,
  deletions,
  estimatedBytesTotal: estimatedBytesKnown ? estimatedBytesTotal : null,
}

}

export const splitIntoByteChunks = (value: string, maxBytes: number) => {
  const bytes = Buffer.from(value, "utf8")
  if (bytes.length === 0) {
    return []
  }

  const chunks: string[] = []
  for (let index = 0; index < bytes.length; index += maxBytes) {
    chunks.push(bytes.subarray(index, Math.min(index + maxBytes, bytes.length)).toString("utf8"))
  }
  return chunks
}

export const buildParsedFiles = ({
  patchText,
  exceeded,
}: {
  patchText: string
  exceeded: boolean
}) => {
  const fileChunks = splitPatchIntoFileChunks(patchText)
  return fileChunks.map((fileChunk, index): ParsedPatchFile => {
    const estimatedBytes = Buffer.byteLength(fileChunk, "utf8")
    const paths = parseFilePaths(fileChunk)
    const requiresExternal = estimatedBytes > DIFF_PER_FILE_BYTES_CAP
    const content = requiresExternal ? null : fileChunk

    const isLastChunk = index === fileChunks.length - 1
    const truncated = exceeded && isLastChunk

    const contentState: DiffFileContentState = requiresExternal
      ? "requires_external"
      : truncated
        ? "truncated"
        : "available"

    return {
      fileId: `file_${index + 1}`,
      oldPath: paths.oldPath,
      newPath: paths.newPath,
      changeType: resolveChangeType(fileChunk),
      estimatedBytes,
      contentState,
      content,
      truncated,
    }
  })
}

export const buildManifestMode = ({
  exceeded,
  parsedFiles,
}: {
  exceeded: boolean
  parsedFiles: ParsedPatchFile[]
}): DiffManifestMode => {
  if (exceeded) {
    return "external_review_required"
  }
  if (parsedFiles.some((file) => file.contentState !== "available")) {
    return "large_diff_mode"
  }
  return "full"
}

export const normalizeCursor = (cursor: string | undefined) => {
  if (!cursor) {
    return 0
  }
  const parsed = Number.parseInt(cursor, 10)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return 0
  }
  return parsed
}

export const buildManifestResponse = ({
  parsedFiles,
  mode,
  mergeRequestDetails,
  projectId,
  mergeRequestIid,
  totalBytes,
  estimatedBytesKnown,
  additions,
  deletions,
}: {
  parsedFiles: ParsedPatchFile[]
  mode: DiffManifestMode
  mergeRequestDetails: GitLabMergeRequestDetails
  projectId: string
  mergeRequestIid: string
  totalBytes: number
  estimatedBytesKnown: boolean
  additions: number
  deletions: number
}) => ({
  data: {
    mode,
    limits: {
      globalBytes: DIFF_GLOBAL_BYTES_CAP,
      perFileBytes: DIFF_PER_FILE_BYTES_CAP,
      chunkBytes: DIFF_CHUNK_BYTES_CAP,
    },
    totals: {
      files: parsedFiles.length,
      additions,
      deletions,
      estimatedBytes: estimatedBytesKnown ? totalBytes : null,
    },
    mergeRequest: {
      projectId,
      mergeRequestIid,
      webUrl: mergeRequestDetails.webUrl,
      title: mergeRequestDetails.title,
    },
    files: parsedFiles.map((file) => ({
      fileId: file.fileId,
      oldPath: file.oldPath,
      newPath: file.newPath,
      changeType: file.changeType,
      estimatedBytes: file.estimatedBytes,
      contentState: file.contentState,
    })),
  } satisfies DiffManifestResponseData,
})

export const buildFilesById = (parsedFiles: ParsedPatchFile[]) => {
  const filesById = new Map<
    string,
    {
      chunks: string[]
      truncated: boolean
      contentState: DiffFileContentState
    }
  >()

  for (const file of parsedFiles) {
    if (!file.content) {
      filesById.set(file.fileId, {
        chunks: [],
        truncated: file.truncated,
        contentState: file.contentState,
      })
      continue
    }

    filesById.set(file.fileId, {
      chunks: splitIntoByteChunks(file.content, DIFF_CHUNK_BYTES_CAP),
      truncated: file.truncated,
      contentState: file.contentState,
    })
  }

  return filesById
}

