import {
  DIFF_GLOBAL_BYTES_CAP,
  DIFF_REQUEST_TIMEOUT_MS,
} from "./constants"
import { GitLabDiffServiceError } from "./error"
import {
  asRecord,
  asString,
} from "./parsing"
import { type GitLabMergeRequestDetails } from "./types"
import { parseJsonResponse } from "@/lib/http/response-json"

export const getGitLabRequest = async ({
  instanceUrl,
  token,
  apiPath,
}: {
  instanceUrl: string
  token: string
  apiPath: string
}) => {
  const controller = new AbortController()
  const timeout = setTimeout(() => {
    controller.abort()
  }, DIFF_REQUEST_TIMEOUT_MS)

  try {
    const response = await fetch(`${instanceUrl}${apiPath}`, {
      method: "GET",
      headers: {
        "PRIVATE-TOKEN": token,
        "User-Agent": "argus-app",
      },
      signal: controller.signal,
    })

if (!response.ok) {
  let responseText = ""
  try {
    responseText = (await response.text()).slice(0, 400)
  } catch {
    // Body unreadable — proceed with empty context.
  }

  if (response.status === 429) {
    throw new GitLabDiffServiceError("GitLab rate limit reached. Wait and retry.", {
      status: 429,
      code: "GITLAB_DIFF_RATE_LIMITED",
      retryable: true,
    })
  }

  if (response.status === 401 || response.status === 403 || response.status === 404) {
    throw new GitLabDiffServiceError(
      responseText || "You do not have access to this merge request diff.",
      {
        status: response.status,
        code: "GITLAB_DIFF_UNAUTHORIZED",
        reconnectRequired: response.status === 401 || response.status === 403,
      },
    )
  }

  if (response.status >= 500 || response.status === 408) {
    throw new GitLabDiffServiceError(
      "GitLab is temporarily unavailable. Try again shortly.",
      {
        status: response.status,
        code: "GITLAB_DIFF_UPSTREAM_UNAVAILABLE",
        retryable: true,
      },
    )
  }

  throw new GitLabDiffServiceError(
    responseText || `GitLab request failed (${response.status}).`,
    {
      status: response.status,
      code: "GITLAB_DIFF_UPSTREAM_UNAVAILABLE",
    },
  )
}

return response

  } catch (error) {
    if (error instanceof GitLabDiffServiceError) {
      throw error
    }

    if (error instanceof Error && error.name === "AbortError") {
      throw new GitLabDiffServiceError("GitLab diff request timed out.", {
        status: 504,
        code: "GITLAB_DIFF_UPSTREAM_UNAVAILABLE",
        retryable: true,
      })
    }

    throw new GitLabDiffServiceError("Unable to reach GitLab host.", {
      status: 502,
      code: "GITLAB_DIFF_UPSTREAM_UNAVAILABLE",
      retryable: true,
      details: {
        cause: error instanceof Error ? error.message : String(error),
      },
    })
  } finally {
    clearTimeout(timeout)
  }
}

const buildMergeRequestFallbackUrl = ({
  instanceUrl,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string
  projectId: string
  mergeRequestIid: string
}) => `${instanceUrl}/${encodeURIComponent(projectId)}/-/merge_requests/${encodeURIComponent(mergeRequestIid)}`

export const loadMergeRequestDetails = async ({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string
  token: string
  projectId: string
  mergeRequestIid: string
}): Promise<GitLabMergeRequestDetails> => {
  const encodedProjectId = encodeURIComponent(projectId)
  const encodedMergeRequestIid = encodeURIComponent(mergeRequestIid)
  const response = await getGitLabRequest({
    instanceUrl,
    token,
    apiPath: `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}`,
  })
  const parsedResponse = await parseJsonResponse(response)
  if (!parsedResponse.ok || parsedResponse.isEmpty) {
    throw new GitLabDiffServiceError("GitLab returned an invalid merge request payload.", {
      status: 502,
      code: "GITLAB_DIFF_UPSTREAM_UNAVAILABLE",
      retryable: true,
    })
  }

  const payload = parsedResponse.value
  const root = asRecord(payload)
  const title = asString(root?.title) || `Merge request !${mergeRequestIid}`
  const webUrl =
    asString(root?.web_url) ||
    buildMergeRequestFallbackUrl({ instanceUrl, projectId, mergeRequestIid })

  return {
    title,
    webUrl,
  }
}

export const loadRawDiffText = async ({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string
  token: string
  projectId: string
  mergeRequestIid: string
}) => {
  const encodedProjectId = encodeURIComponent(projectId)
  const encodedMergeRequestIid = encodeURIComponent(mergeRequestIid)

const response = await getGitLabRequest({
  instanceUrl,
  token,
  apiPath: `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}/raw_diffs`,
})

const contentLength = Number(response.headers.get("content-length"))
if (Number.isFinite(contentLength) && contentLength <= 0) {
  return {
    patchText: "",
    totalBytes: 0,
    exceeded: false,
  }
}

if (!response.body) {
  const text = await response.text()
  const textBytes = Buffer.from(text, "utf8")
  const bytes = textBytes.byteLength
  const exceeded = bytes > DIFF_GLOBAL_BYTES_CAP
  return {
    patchText: exceeded
      ? textBytes.subarray(0, DIFF_GLOBAL_BYTES_CAP).toString("utf8")
      : text,
    totalBytes: bytes,
    exceeded,
  }
}

const reader = response.body.getReader()
const decoder = new TextDecoder()
const chunks: string[] = []
let bytesRead = 0
let exceeded = false

try {
  while (true) {
    const { done, value } = await reader.read()
    if (done) {
      break
    }
    if (!value || value.byteLength === 0) {
      continue
    }
    const nextTotal = bytesRead + value.byteLength
    if (nextTotal > DIFF_GLOBAL_BYTES_CAP) {
      const remainingBytes = DIFF_GLOBAL_BYTES_CAP - bytesRead
      if (remainingBytes > 0) {
        chunks.push(decoder.decode(value.subarray(0, remainingBytes), { stream: true }))
      }
      bytesRead = nextTotal
      exceeded = true
      break
    }
    bytesRead = nextTotal

    chunks.push(decoder.decode(value, { stream: true }))
  }
} finally {
  const trailing = decoder.decode()
  if (trailing && !exceeded) {
    chunks.push(trailing)
  }
  if (exceeded) {
    await reader.cancel("diff size exceeded")
  } else {
    reader.releaseLock()
  }
}

return {
  patchText: chunks.join(""),
  totalBytes: bytesRead,
  exceeded,
}

}

export const loadChangesPayload = async ({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: {
  instanceUrl: string
  token: string
  projectId: string
  mergeRequestIid: string
}) => {
  const encodedProjectId = encodeURIComponent(projectId)
  const encodedMergeRequestIid = encodeURIComponent(mergeRequestIid)
  const response = await getGitLabRequest({
    instanceUrl,
    token,
    apiPath: `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}/changes?access_raw_diffs=true`,
  })

  const parsedResponse = await parseJsonResponse(response)
  if (!parsedResponse.ok || parsedResponse.isEmpty) {
    throw new GitLabDiffServiceError("GitLab returned an invalid changes payload.", {
      status: 502,
      code: "GITLAB_DIFF_UPSTREAM_UNAVAILABLE",
      retryable: true,
    })
  }

  return parsedResponse.value
}

export type ReviewPersona =
  | "generalist"
  | "security"
  | "performance"
  | "maintainability"

export type ReviewPersonaMode = "disabled" | "single" | "multi"
export type ReviewPersonaExecutionStrategy = "sequential" | "parallel"

export const REVIEW_PERSONA_DEFAULT: ReviewPersona = "generalist"
export const REVIEW_PERSONA_MODE_DEFAULT: ReviewPersonaMode = "single"
export const REVIEW_PERSONA_VALUES: ReviewPersona[] = [
  "generalist",
  "security",
  "performance",
  "maintainability",
]

export const REVIEW_PERSONA_MODE_OPTIONS: Array<{
  value: ReviewPersonaMode
  label: string
  description: string
}> = [
  {
    value: "disabled",
    label: "Disabled",
    description: "Use a general review pass without persona-specific prompting.",
  },
  {
    value: "single",
    label: "Single persona",
    description: "Run one pass using the selected persona.",
  },
  {
    value: "multi",
    label: "All personas",
    description: "Run one pass per persona and merge findings.",
  },
]

export const REVIEW_PERSONA_OPTIONS: Array<{
  value: ReviewPersona
  label: string
  description: string
}> = [
  {
    value: "generalist",
    label: "Generalist",
    description: "Balanced correctness-first review across bugs, regressions, and security risks.",
  },
  {
    value: "security",
    label: "Security",
    description: "Prioritize authz/authn, data exposure, injection, and trust-boundary violations.",
  },
  {
    value: "performance",
    label: "Performance",
    description: "Prioritize latency, scalability, hot-path work, and unnecessary allocations.",
  },
  {
    value: "maintainability",
    label: "Maintainability",
    description: "Prioritize readability, modularity, and long-term change safety risks.",
  },
]

export const isReviewPersona = (value: unknown): value is ReviewPersona =>
  value === "generalist" ||
  value === "security" ||
  value === "performance" ||
  value === "maintainability"

export const isReviewPersonaMode = (value: unknown): value is ReviewPersonaMode =>
  value === "disabled" || value === "single" || value === "multi"

export const normalizeReviewPersona = (
  value: unknown,
  fallback: ReviewPersona = REVIEW_PERSONA_DEFAULT,
): ReviewPersona => {
  if (isReviewPersona(value)) {
    return value
  }
  return fallback
}

export const normalizeReviewPersonaMode = (
  value: unknown,
  fallback: ReviewPersonaMode = REVIEW_PERSONA_MODE_DEFAULT,
): ReviewPersonaMode => {
  if (isReviewPersonaMode(value)) {
    return value
  }
  return fallback
}

export const resolveReviewPersonaExecutionStrategy = (
  mode: ReviewPersonaMode,
): ReviewPersonaExecutionStrategy => (mode === "multi" ? "parallel" : "sequential")

export const REVIEW_PERSONA_TEMPLATE_MAX_CHARS = 2_000

export const REVIEW_PERSONA_TEMPLATE_DEFAULTS: Record<ReviewPersona, string> = {
  generalist:
    "Prioritize high-confidence correctness bugs, regressions, and behavior-breaking risks in changed lines.",
  security:
    "Focus on exploitability, trust boundaries, authz/authn gaps, data exposure, and injection vectors.",
  performance:
    "Focus on algorithmic regressions, repeated expensive work, hot-path overhead, and memory churn.",
  maintainability:
    "Focus on brittle coupling, unclear invariants, weak abstractions, and testability regressions that increase defect risk.",
}

export type ReviewPersonaTemplateOverrides = Partial<Record<ReviewPersona, string>>

const normalizeTemplateText = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  const normalized = value.trim()
  if (!normalized) {
    return ""
  }
  return normalized.slice(0, REVIEW_PERSONA_TEMPLATE_MAX_CHARS)
}

export const normalizeReviewPersonaTemplateOverrides = (
  value: unknown,
): ReviewPersonaTemplateOverrides => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {}
  }

  const record = value as Record<string, unknown>
  const next: ReviewPersonaTemplateOverrides = {}

  for (const persona of REVIEW_PERSONA_VALUES) {
    const template = normalizeTemplateText(record[persona])
    if (template) {
      next[persona] = template
    }
  }

  return next
}

export const resolveReviewPersonaTemplate = ({
  persona,
  overrides,
}: {
  persona: ReviewPersona
  overrides: ReviewPersonaTemplateOverrides
}) => overrides[persona]?.trim() || REVIEW_PERSONA_TEMPLATE_DEFAULTS[persona]

import { eq } from "drizzle-orm";

import {
  assertAiClientSettings,
  getAiClientSettingsDefaults,
  type AiClientSettings,
} from "@/lib/ai/client-settings";
import { db } from "@/lib/db";
import { aiClientSettings } from "@/lib/db/schema";
import { decryptGitLabToken, encryptGitLabToken } from "@/lib/gitlab/crypto";

export type PersistedAiClientSettings = AiClientSettings & {
  hasStoredToken: boolean;
};

const decryptStoredToken = (row: typeof aiClientSettings.$inferSelect) => {
  if (!row.tokenCiphertext || !row.tokenIv || !row.tokenAuthTag) {
    return "";
  }

  try {
    return decryptGitLabToken({
      ciphertext: row.tokenCiphertext,
      iv: row.tokenIv,
      authTag: row.tokenAuthTag,
    });
  } catch {
    // Corrupt ciphertext should fail closed to empty token.
    return "";
  }
};

export const getAiClientSettingsForUser = async (
  userId: string,
): Promise<PersistedAiClientSettings> => {
  const defaults = getAiClientSettingsDefaults();
  const row = await db.query.aiClientSettings.findFirst({
    where: eq(aiClientSettings.userId, userId),
  });

  if (!row) {
    return {
      ...defaults,
      hasStoredToken: false,
    };
  }

  const token = decryptStoredToken(row);
  const validated = assertAiClientSettings({
    apiUrl: row.apiUrl,
    model: row.model,
    token,
  });

  return {
    ...validated,
    hasStoredToken: Boolean(
      row.tokenCiphertext && row.tokenIv && row.tokenAuthTag,
    ),
  };
};

export const upsertAiClientSettingsForUser = async ({
  userId,
  settings,
}: {
  userId: string;
  settings: AiClientSettings;
}): Promise<PersistedAiClientSettings> => {
  const now = new Date();
  const validated = assertAiClientSettings(settings);
  const encryptedToken = validated.token
    ? encryptGitLabToken(validated.token)
    : null;

  await db
    .insert(aiClientSettings)
    .values({
      userId,
      apiUrl: validated.apiUrl,
      model: validated.model,
      tokenCiphertext: encryptedToken?.ciphertext ?? null,
      tokenIv: encryptedToken?.iv ?? null,
      tokenAuthTag: encryptedToken?.authTag ?? null,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [aiClientSettings.userId],
      set: {
        apiUrl: validated.apiUrl,
        model: validated.model,
        tokenCiphertext: encryptedToken?.ciphertext ?? null,
        tokenIv: encryptedToken?.iv ?? null,
        tokenAuthTag: encryptedToken?.authTag ?? null,
        updatedAt: now,
      },
    });

  return {
    ...validated,
    hasStoredToken: Boolean(encryptedToken),
  };
};

