export const reclaimStaleIndexJobs = async (args?: {
  staleBefore?: Date
}) => {
  const leaseSettings = resolveIndexerLeaseSettings()
  if (!leaseSettings.enabled) {
    return [] as Array<{ id: string }>
  }

  const staleBefore = args?.staleBefore ?? new Date()
  const rows = await db
    .update(indexJobs)
    .set({
      status: 'failed',
      nextAttemptAt: new Date(),
      finishedAt: null,
      lastError: 'Lease expired while processing. Requeued for retry.',
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(indexJobs.status, 'processing'),
        sql`${indexJobs.leaseExpiresAt} is not null`,
        sql`${indexJobs.leaseExpiresAt} <= ${staleBefore}`,
      ),
    )
    .returning({ id: indexJobs.id })

  return rows
}

export const refreshIndexJobLease = async (args: {
  jobId: string
  claimVersion: number
  leaseMs?: number
}) => {
  const leaseSettings = resolveIndexerLeaseSettings()
  if (!leaseSettings.enabled) {
    return false
  }
  const leaseMs = Math.max(1_000, Math.floor(args.leaseMs ?? leaseSettings.leaseMs))
  const rows = await db
    .update(indexJobs)
    .set({
      leaseExpiresAt: buildLeaseExpiry(leaseMs),
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(indexJobs.id, args.jobId),
        eq(indexJobs.status, 'processing'),
        eq(indexJobs.claimVersion, Math.max(0, Math.floor(args.claimVersion))),
      ),
    )
    .returning({ id: indexJobs.id })
  return rows.length > 0
}

export const markIndexJobSucceeded = async (args: {
  jobId: string
  result: Record<string, unknown>
  claimVersion?: number
}) => {
  const leaseSettings = resolveIndexerLeaseSettings()
  const whereFilters = [eq(indexJobs.id, args.jobId), eq(indexJobs.status, 'processing')]
  if (leaseSettings.enabled) {
    whereFilters.push(eq(indexJobs.claimVersion, Math.max(0, Math.floor(args.claimVersion ?? -1))))
  }
  const rows = await db
    .update(indexJobs)
    .set({
      status: 'succeeded',
      finishedAt: new Date(),
      lastError: null,
      result: args.result,
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: new Date(),
    })
    .where(and(...whereFilters))
    .returning({ id: indexJobs.id })

  return rows.length > 0
}

export const markIndexJobFailed = async (args: {
  job: ClaimedIndexJob
  error: unknown
}) => {
  const message =
    args.error instanceof Error
      ? args.error.message.slice(0, 500)
      : 'Unexpected indexing job processing error.'

  const maxAttempts = resolveIndexJobMaxAttempts()
  const exceededAttempts = args.job.attempts >= maxAttempts
  const leaseSettings = resolveIndexerLeaseSettings()
  const whereFilters = [eq(indexJobs.id, args.job.id), eq(indexJobs.status, 'processing')]
  if (leaseSettings.enabled) {
    whereFilters.push(eq(indexJobs.claimVersion, normalizeClaimVersion(args.job.claimVersion)))
  }
  const rows = await db
    .update(indexJobs)
    .set({
      status: exceededAttempts ? 'dead' : 'failed',
      finishedAt: exceededAttempts ? new Date() : null,
      nextAttemptAt: exceededAttempts
        ? new Date()
        : new Date(Date.now() + getRetryDelayMs(args.job.attempts)),
      lastError: message,
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: new Date(),
    })
    .where(and(...whereFilters))
    .returning({ id: indexJobs.id, status: indexJobs.status })

  return rows[0]?.status ?? null
}

import { afterEach, describe, expect, mock, test } from "bun:test"

describe("review engine multi persona execution", () => {
  afterEach(() => {
    mock.restore()
  })

  test("runs persona passes in parallel when persona mode is multi", async () => {

    let inFlight = 0
    let maxInFlight = 0
    const blockers: Array<() => void> = []
    const originalFetch = globalThis.fetch

    globalThis.fetch = async () => {
      inFlight += 1
      maxInFlight = Math.max(maxInFlight, inFlight)

      await new Promise<void>((resolve) => {
        blockers.push(resolve)
      })

      inFlight -= 1

      return new Response(
        JSON.stringify({
          choices: [{ message: { content: "{\"findings\":[]}" } }],
          usage: {
            prompt_tokens: 10,
            completion_tokens: 5,
            total_tokens: 15,
          },
        }),
        {
          status: 200,
          headers: { "content-type": "application/json" },
        },
      )
    }

    try {
      const moduleId = `@/lib/review/review-engine?cacheBust=${Math.random().toString(36).slice(2)}`
      const { runReviewEngine } = await import(moduleId)

      const runPromise = runReviewEngine({
        patch: "diff --git a/src/a.ts b/src/a.ts\n+const x = 1\n",
        apiUrl: "https://api.example.com/v1",
        model: "gpt-5-mini",
        token: "token",
        personaMode: "multi",
      })

      for (let i = 0; i < 40 && blockers.length < 4; i += 1) {
        await new Promise((resolve) => setTimeout(resolve, 5))
      }

      expect(blockers.length).toBe(4)
      expect(maxInFlight).toBeGreaterThan(1)

      for (const release of blockers) {
        release()
      }

      const result = await runPromise
      expect(result.totalBatches).toBe(4)
    } finally {
      globalThis.fetch = originalFetch
    }
  })
})

