import type { CodeChunk, IndexOptions, VectorBatch, VectorRecord } from '@argus/argus-search'
import type { IndexStreamOptions } from '@argus/argus-search/stream'

export type ToolExecuteParams = { query: string; topK?: number }

export type ChunkMatch = {
  score: number
  filePath: string
  chunkId: string
  chunk: CodeChunk | null
  metadata: unknown | null
}

export interface VectorStoreRecord {
  chunkId: string
  filePath: string
  embedding?: Float32Array | number[]
  metadata: unknown | null
  chunk: CodeChunk | null
}

export type VectorStoreFilter = (record: VectorStoreRecord) => boolean

export interface VectorStoreSearchMatch {
  score: number
  record: VectorStoreRecord
}

export interface VectorStore {
  searchByEmbedding(
    queryEmbedding: number[] | Float32Array,
    options?: { topK?: number; filter?: VectorStoreFilter },
  ): Array<VectorStoreSearchMatch> | Promise<Array<VectorStoreSearchMatch>>
}

export class InMemoryVectorStore {
  constructor(options?: { normalize?: boolean })
  clear(): void
  size(): number
  upsertBatch(batch: VectorBatch | VectorRecord[]): void
  searchByEmbedding(
    queryEmbedding: number[] | Float32Array,
    options?: { topK?: number; filter?: VectorStoreFilter },
  ): Array<{ score: number; record: VectorStoreRecord }>
}

export interface Embedder {
  kind: string
  embed(input: string[]): Promise<number[][]>
  embedQuery(text: string): Promise<number[]>
}

export type HttpEmbedderOptions = {
  baseUrl: string
  model: string
  apiKey?: string
  timeoutMs?: number
}

export function createHttpEmbedder(options: HttpEmbedderOptions): Embedder

export interface VectorRetriever {
  search(options: { query: string; topK?: number; filter?: VectorStoreFilter }): Promise<ChunkMatch[]>
}

export function createVectorRetriever(options: { store: VectorStore; embedder: Embedder }): VectorRetriever

export type CodeSearchTool = {
  name: string
  description: string
  parameters: unknown
  execute(params: ToolExecuteParams): Promise<ChunkMatch[]>
}

export function createCodeSearchTool(options: { retriever: VectorRetriever; name?: string }): CodeSearchTool

export function indexToVectorStore(
  indexOptions: IndexOptions,
  options: { store: InMemoryVectorStore; streamOptions?: IndexStreamOptions },
): Promise<any>

export type ArgusSearch = {
  store: VectorStore & { clear?(): void; size?(): number }
  embedder: Embedder
  retriever: VectorRetriever
  tool: CodeSearchTool
  index(overrides?: Partial<IndexOptions>): Promise<any>
  search(query: string, options?: { topK?: number; filter?: VectorStoreFilter }): Promise<ChunkMatch[]>
}

export function createArgusSearch(options: {
  projectRoot: string
  inputs?: IndexOptions['inputs']
  vectorProvider?: IndexOptions['vector'] extends { provider?: infer P } ? P : any
  store?: VectorStore & { clear?(): void; size?(): number }
  embedder?: Embedder
  streamOptions?: IndexStreamOptions
}): ArgusSearch

import { mkdtemp, readFile, rm } from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { describe, expect, test } from "bun:test"

import { FsArtifactStore } from "@/lib/indexing/stores/artifact-store.fs"

const withArtifactsRoot = async <T>(fn: (root: string) => Promise<T>) => {
  const root = await mkdtemp(path.join(os.tmpdir(), "argus-artifacts-test-"))
  const previous = process.env.INDEXER_ARTIFACTS_DIR
  process.env.INDEXER_ARTIFACTS_DIR = root

  try {
    return await fn(root)
  } finally {
    if (previous === undefined) {
      delete process.env.INDEXER_ARTIFACTS_DIR
    } else {
      process.env.INDEXER_ARTIFACTS_DIR = previous
    }
    await rm(root, { recursive: true, force: true })
  }
}

describe("FsArtifactStore", () => {
  test("writes artifacts under the configured root", async () =>
    withArtifactsRoot(async (root) => {
      const store = new FsArtifactStore()
      const prefix = "integrations/a/runs/default/main/sha/run-1"

      await store.writeRunJson({
        artifactsPrefix: prefix,
        run: { id: "run-1", status: "ready" },
      })

      const runJsonPath = path.join(root, prefix, "run.json")
      const payload = await readFile(runJsonPath, "utf8")
      expect(payload).toContain('"id": "run-1"')
    }))

  test("rejects traversal prefixes that escape root", async () =>
    withArtifactsRoot(async () => {
      const store = new FsArtifactStore()

      await expect(
        store.writeRunJson({
          artifactsPrefix: "../../outside-root",
          run: { id: "bad" },
        }),
      ).rejects.toThrow("Invalid artifacts prefix path.")
    }))
})

import { getAiClientSettingsForUser } from "@/lib/ai/server-settings"

const DEFAULT_AI_API_URL = "https://api.openai.com/v1"
const DEFAULT_AI_MODEL = "gpt-4o-mini"

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const pickFirstNonEmpty = (...values: Array<string | undefined>) => {
  for (const value of values) {
    if (isNonEmptyString(value)) {
      return value.trim()
    }
  }
  return ""
}

const resolveEnvApiUrl = () =>
  normalizeApiUrl(
    pickFirstNonEmpty(process.env.AI_API_URL, process.env.OPENAI_BASE_URL) || DEFAULT_AI_API_URL,
  )

const resolveEnvModel = () =>
  pickFirstNonEmpty(process.env.AI_MODEL, process.env.OPENAI_MODEL) || DEFAULT_AI_MODEL

const resolveEnvToken = () =>
  pickFirstNonEmpty(process.env.AI_API_TOKEN, process.env.OPENAI_API_KEY)

export class ReviewProviderSettingsError extends Error {
  status: number

  constructor(message: string, status = 400) {
    super(message)
    this.name = "ReviewProviderSettingsError"
    this.status = status
  }
}

export type ReviewProviderSettings = {
  apiUrl: string
  model: string
  token: string
  usesServerToken: boolean
}

export const resolveReviewProviderSettingsForUser = async (
  userId: string,
): Promise<ReviewProviderSettings> => {
  const settings = await getAiClientSettingsForUser(userId)

  const apiUrl = normalizeApiUrl(settings.apiUrl || resolveEnvApiUrl())
  const model = settings.model.trim() || resolveEnvModel()
  const token = settings.token.trim() || resolveEnvToken()
  const usesServerToken = settings.token.trim().length === 0

  if (!token) {
    throw new ReviewProviderSettingsError(
      "AI token missing. Configure your token in Settings or set AI_API_TOKEN/OPENAI_API_KEY on the server.",
      400,
    )
  }

  if (!apiUrl) {
    throw new ReviewProviderSettingsError("AI provider URL is invalid.", 400)
  }

  if (!model) {
    throw new ReviewProviderSettingsError("AI model is missing.", 400)
  }

  return {
    apiUrl,
    model,
    token,
    usesServerToken,
  }
}

import {
  darkTheme,
  lightTheme,
  type LayoutOverrides,
  type Theme,
} from "reagraph"

import {
  type GraphEdge,
  type GraphNode,
  type GraphPayload,
  type GraphRequestLimits,
  type TraceGraphParams,
} from "./types"

const EDGE_COLORS = [
  "#2563eb",
  "#16a34a",
  "#ea580c",
  "#dc2626",
  "#0891b2",
  "#7c3aed",
  "#c2410c",
]

const NODE_COLORS = {
  dark: {
    file: "#2dd4bf",
    function: "#60a5fa",
    class: "#a78bfa",
    external: "#94a3b8",
    default: "#64748b",
  },
  light: {
    file: "#0f766e",
    function: "#1d4ed8",
    class: "#6d28d9",
    external: "#6b7280",
    default: "#374151",
  },
} as const

export const EMPTY_NODES: GraphNode[] = []
export const EMPTY_EDGES: GraphEdge[] = []
export const EMPTY_IDS: string[] = []
export const DENSE_GRAPH_LAYOUT_OVERRIDES = {
  maxIterations: 12,
  margin: 2,
  ratio: 1.1,
} as const
export const EMPTY_CONNECTED_ENTITIES = []
export const MAX_CONNECTED_ENTITIES = 80
export const MAX_SEARCH_RESULTS = 12
export const DENSE_OVERVIEW_NODE_LIMIT = 550
export const DENSE_OVERVIEW_EDGE_LIMIT = 420
export const DENSE_FOCUS_NODE_LIMIT = 140
export const DENSE_FOCUS_EDGE_LIMIT = 900

export const shortId = (id: string) =>
  id.length <= 42 ? id : `${id.slice(0, 20)}...${id.slice(-18)}`

export const buildReagraphTheme = (isDark: boolean): Theme => {
  const base = isDark ? darkTheme : lightTheme
  return {
    ...base,
    canvas: {
      ...base.canvas,
      background: undefined,
    },
    node: {
      ...base.node,
      label: {
        ...base.node.label,
        color: isDark ? "#cbd5e1" : "#334155",
        stroke: isDark ? "#020617" : "#ffffff",
        activeColor: isDark ? "#f8fafc" : "#0f172a",
      },
    },
    edge: {
      ...base.edge,
      opacity: isDark ? 0.28 : 0.35,
      selectedOpacity: 0.75,
      inactiveOpacity: isDark ? 0.08 : 0.1,
    },
    cluster: {
      stroke: isDark ? "#334155" : "#cbd5e1",
      label: {
        stroke: isDark ? "#0f172a" : "#f8fafc",
        color: isDark ? "#94a3b8" : "#64748b",
      },
    },
  }
}

export const nodeColor = (kind: string, isDark: boolean) => {
  const palette = isDark ? NODE_COLORS.dark : NODE_COLORS.light
  if (kind === "file") return palette.file
  if (kind === "function") return palette.function
  if (kind === "class" || kind === "type") return palette.class
  if (kind === "external") return palette.external
  return palette.default
}

export const packageKeyFromNode = (node: GraphNode) => {
  if (!node.filePath) {
    return node.kind === "external" ? "external" : "workspace"
  }
  const parts = node.filePath.split("/").filter((p) => p.length > 0)
  if (parts.length === 0) return "workspace"
  return parts.slice(0, Math.min(2, parts.length)).join("/")
}

export const sampleArray = <T,>(items: T[], limit: number): T[] => {
  if (limit <= 0 || items.length <= limit) {
    return items
  }

  const out: T[] = []
  for (let offset = 0; offset < limit; offset += 1) {
    const index = Math.floor((offset * items.length) / limit)
    const item = items[index]
    if (item) {
      out.push(item)
    }
  }
  return out
}

export const resolveGraphRequestLimits = (): GraphRequestLimits => {
  if (typeof navigator === "undefined") {
    return { maxNodes: 2_000, maxEdges: 10_000 }
  }

  const browserNavigator = navigator as Navigator & { deviceMemory?: number }
  const cores = navigator.hardwareConcurrency || 8
  const deviceMemory = browserNavigator.deviceMemory ?? 8

  if (cores <= 4 || deviceMemory <= 4) {
    return { maxNodes: 900, maxEdges: 2_500 }
  }
  if (cores <= 8 || deviceMemory <= 8) {
    return { maxNodes: 1_200, maxEdges: 4_000 }
  }
  return { maxNodes: 1_600, maxEdges: 6_000 }
}

export const normalizeGraphPayload = (payload: GraphPayload): GraphPayload => {
  const nodeIds = new Set(payload.nodes.map((node) => node.id))
  const edges = payload.edges.filter(
    (edge) => nodeIds.has(edge.sourceId) && nodeIds.has(edge.targetId),
  )

  if (edges.length === payload.edges.length) {
    return payload
  }

  return {
    ...payload,
    edges,
  }
}

export const pickRenderableEdges = (
  edges: GraphEdge[],
  budget: number,
  selectedNodeId: string | null,
) => {
  if (budget <= 0 || edges.length <= budget) {
    return edges
  }

  const picked = new Set<number>()
  const out: GraphEdge[] = []

  // Keep local neighborhood edges first so selected-node exploration stays useful.
  if (selectedNodeId) {
    for (let index = 0; index < edges.length && out.length < budget; index += 1) {
      const edge = edges[index]
      if (!edge) continue
      if (edge.sourceId === selectedNodeId || edge.targetId === selectedNodeId) {
        picked.add(index)
        out.push(edge)
      }
    }
  }

  const remaining = budget - out.length
  if (remaining <= 0) {
    return out
  }

  for (let offset = 0; offset < remaining; offset += 1) {
    const sampleIndex = Math.floor((offset * edges.length) / remaining)
    const edge = edges[sampleIndex]
    if (!edge || picked.has(sampleIndex)) {
      continue
    }
    picked.add(sampleIndex)
    out.push(edge)
    if (out.length >= budget) {
      return out
    }
  }

  for (let index = 0; index < edges.length && out.length < budget; index += 1) {
    if (picked.has(index)) {
      continue
    }
    const edge = edges[index]
    if (!edge) continue
    picked.add(index)
    out.push(edge)
  }

  return out
}

export const buildEdgeColorMap = (
  allEdges: GraphEdge[],
  availableEdgeTypes: string[] | undefined,
) => {
  const types = availableEdgeTypes?.length
    ? availableEdgeTypes
    : [...new Set(allEdges.map((edge) => edge.type))]
  const map = new Map<string, string>()
  types.forEach((type, index) => {
    map.set(type, EDGE_COLORS[index % EDGE_COLORS.length] as string)
  })
  return map
}

const parseIntParam = (
  raw: string | null,
  fallback: number,
  max: number,
) => {
  const parsed = Number.parseInt(raw?.trim() ?? "", 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback
  }
  return Math.min(max, parsed)
}

export const resolveTraceGraphParams = (args: {
  searchParams: Pick<URLSearchParams, "get">
  initialIntegrationId?: string
  initialSourceBranch?: string
}): TraceGraphParams => {
  const traceModeParam = args.searchParams.get("graphTraceMode")
  const traceMode =
    traceModeParam === "impact" || traceModeParam === "callers"
      ? traceModeParam
      : "impact"
  const traceNodeId = args.searchParams.get("graphTraceNodeId")?.trim() ?? ""
  const traceSymbol = args.searchParams.get("graphTraceSymbol")?.trim() ?? ""
  const traceBranch =
    args.searchParams.get("graphTraceBranch")?.trim() ??
    args.initialSourceBranch?.trim() ??
    ""
  const traceIntegrationId =
    args.searchParams.get("graphTraceIntegrationId")?.trim() ??
    args.initialIntegrationId?.trim() ??
    ""
  const traceDepth = parseIntParam(args.searchParams.get("graphTraceDepth"), 3, 6)
  const traceLimit = parseIntParam(args.searchParams.get("graphTraceLimit"), 120, 200)
  const shouldLoadTraceGraph = traceNodeId.length > 0 || traceSymbol.length > 0

  return {
    traceMode,
    traceNodeId,
    traceSymbol,
    traceBranch,
    traceIntegrationId,
    traceDepth,
    traceLimit,
    shouldLoadTraceGraph,
  }
}

export const toDenseLayoutOverrides = (): LayoutOverrides =>
  DENSE_GRAPH_LAYOUT_OVERRIDES as unknown as LayoutOverrides

import { describe, expect, test } from "bun:test"

import { parseBoolean, parsePositiveInt, resolveIndexerWorkerConfig } from "./config-env"

describe("shared config env parsing", () => {
  test("parsePositiveInt keeps fallback only when value is empty", () => {
    expect(parsePositiveInt(undefined, 25)).toBe(25)
    expect(parsePositiveInt("", 25)).toBe(25)
  })

  test("parsePositiveInt rejects invalid numeric values", () => {
    expect(() => parsePositiveInt("0", 25, "INDEXER_BATCH_SIZE")).toThrow(
      'Invalid positive integer for INDEXER_BATCH_SIZE. Received "0".',
    )
    expect(() => parsePositiveInt("-1", 25)).toThrow('Invalid positive integer. Received "-1".')
    expect(() => parsePositiveInt("nope", 25)).toThrow(
      'Invalid positive integer. Received "nope".',
    )
  })

  test("parsePositiveInt returns parsed positive integers", () => {
    expect(parsePositiveInt("1", 25)).toBe(1)
    expect(parsePositiveInt("300", 25)).toBe(300)
  })

  test("parseBoolean parses known true/false values", () => {
    expect(parseBoolean("1")).toBe(true)
    expect(parseBoolean("true")).toBe(true)
    expect(parseBoolean("yes")).toBe(true)
    expect(parseBoolean("on")).toBe(true)
    expect(parseBoolean("0")).toBe(false)
    expect(parseBoolean("false")).toBe(false)
    expect(parseBoolean("no")).toBe(false)
    expect(parseBoolean("off")).toBe(false)
  })

  test("parseBoolean rejects unknown values", () => {
    expect(parseBoolean(undefined)).toBeUndefined()
    expect(parseBoolean("")).toBeUndefined()
    expect(() => parseBoolean("maybe", "INDEXER_LOG_PRETTY")).toThrow(
      "Invalid boolean for INDEXER_LOG_PRETTY.",
    )
    expect(() => parseBoolean("nope")).toThrow("Invalid boolean.")
  })

  test("resolveIndexerWorkerConfig returns parsed worker settings", () => {
    expect(
      resolveIndexerWorkerConfig({
        INDEXER_SERVICE_NAME: " indexer-a ",
        INDEXER_ENVIRONMENT: "production",
        INDEXER_SERVICE_VERSION: "1.2.3",
        INDEXER_LOG_PRETTY: "true",
        INDEXER_BATCH_SIZE: "40",
        INDEXER_POLL_MS: "5000",
        INDEXER_CONTINUOUS: "1",
      }),
    ).toEqual({
      service: "indexer-a",
      environment: "production",
      version: "1.2.3",
      pretty: true,
      batchSize: 40,
      pollIntervalMs: 5000,
      continuous: true,
    })
  })

  test("resolveIndexerWorkerConfig falls back to defaults", () => {
    expect(resolveIndexerWorkerConfig({})).toEqual({
      service: "argus-indexer-worker",
      environment: "development",
      version: undefined,
      pretty: undefined,
      batchSize: 25,
      pollIntervalMs: 30_000,
      continuous: false,
    })
  })
})

import { parsePositiveInt } from "./config-env"

type EmbeddingProvider = "openai" | "deterministic"

type CacheEntry = {
