  ) => Promise<void>
}

const DEFAULT_EMBEDDING_MODEL = "text-embedding-3-small"
const DEFAULT_OPENAI_BASE_URL = "https://api.openai.com/v1"
const DEFAULT_MAX_REQUEST_TOKENS = 8_000

const asNonNegativeInt = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
    return Math.floor(value)
  }

  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number.parseInt(value, 10)
    if (Number.isFinite(parsed) && parsed >= 0) {
      return parsed
    }
  }

  return null
}

const createEmbeddingRequestError = (message: string, retryable: boolean) => {
  const error = new Error(message) as Error & { retryable?: boolean }
  error.retryable = retryable
  return error
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

const resolveProvider = (): EmbeddingProvider => {
  const configured = process.env.INDEXER_EMBEDDING_PROVIDER?.trim().toLowerCase()
  if (!configured) {
    return "openai"
  }

  if (configured === "openai" || configured === "deterministic") {
    return configured
  }

  throw new Error(
    `Invalid INDEXER_EMBEDDING_PROVIDER value "${configured}". Expected "openai" or "deterministic".`,
  )
}

const resolveEmbeddingModel = () =>
  process.env.INDEXER_EMBEDDING_MODEL?.trim() || DEFAULT_EMBEDDING_MODEL

const resolveBaseUrl = () => {
  const baseUrl = (
    process.env.INDEXER_EMBEDDING_BASE_URL?.trim() || DEFAULT_OPENAI_BASE_URL
  ).replace(/\/+$/, "")

  try {
    const parsed = new URL(baseUrl)
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
      throw new Error("Embedding base URL must use http or https.")
    }
    return parsed.toString().replace(/\/+$/, "")
  } catch {
    throw new Error(`Invalid INDEXER_EMBEDDING_BASE_URL value "${baseUrl}".`)
  }
}

const resolveApiKeyFromEnv = (env: NodeJS.ProcessEnv) =>
  env.INDEXER_EMBEDDING_API_KEY?.trim() ||
  env.OPENAI_API_KEY?.trim() ||
  env.AI_API_TOKEN?.trim() ||
  ""

const resolveApiKey = () => resolveApiKeyFromEnv(process.env)

const resolveMaxRequestTokens = () =>
  parsePositiveInt(
    process.env.INDEXER_EMBEDDING_MAX_REQUEST_TOKENS,
    DEFAULT_MAX_REQUEST_TOKENS,
  )

// Byte length intentionally overestimates tokenizer usage so request splitting is conservative.
const estimateTokenUpperBound = (input: string) =>
  Math.max(1, Buffer.byteLength(input, "utf8"))

const buildEmbeddingBatches = (args: {
  inputs: string[]
  maxBatchSize: number
  maxRequestTokens: number
}): string[][] => {
  const maxBatchSize = Math.max(1, args.maxBatchSize)
  const maxRequestTokens = Math.max(1, args.maxRequestTokens)
  const batches: string[][] = []
  let currentBatch: string[] = []
  let currentBatchTokens = 0

  for (const input of args.inputs) {
    const estimatedTokens = estimateTokenUpperBound(input)
    if (currentBatch.length > 0) {
      const exceedsBatchSize = currentBatch.length >= maxBatchSize
      const exceedsTokenBudget = currentBatchTokens + estimatedTokens > maxRequestTokens
      if (exceedsBatchSize || exceedsTokenBudget) {
        batches.push(currentBatch)
        currentBatch = []
        currentBatchTokens = 0
      }
    }

    currentBatch.push(input)
    currentBatchTokens += estimatedTokens
  }

  if (currentBatch.length > 0) {
    batches.push(currentBatch)
  }

  return batches
}

const resolveCacheModelKey = () => {
  const provider = resolveProvider()
  if (provider === "deterministic") {
    return "deterministic:sha256-v1"
  }

  return `openai:${resolveBaseUrl()}:${resolveEmbeddingModel()}`
}

const resolveTelemetryModel = () => {
  if (resolveProvider() === "deterministic") {
    return "deterministic:sha256-v1"
  }

  return resolveEmbeddingModel()
}

const parseOpenAiResponse = (payload: unknown, normalizeEmbedding: (value: number[]) => number[]) => {
  if (!payload || typeof payload !== "object") {
    throw new Error("Invalid embedding response payload.")
  }

  const root = payload as {
    data?: unknown
    usage?: {
      prompt_tokens?: unknown
      total_tokens?: unknown
      promptTokens?: unknown
      totalTokens?: unknown
    } | null
  }
  const maybeData = root.data
  if (!Array.isArray(maybeData)) {
    throw new Error("Embedding response missing data array.")
  }

  const embeddings = maybeData.map((entry, index) => {
    const embedding = (entry as { embedding?: unknown })?.embedding
    if (!Array.isArray(embedding)) {
      throw new Error(`Embedding response item ${index} is missing embedding array.`)
    }

    return normalizeEmbedding(embedding as number[])
  })

  const promptTokens =
    asNonNegativeInt(root.usage?.prompt_tokens) ??
    asNonNegativeInt(root.usage?.promptTokens) ??
    0
  const totalTokens =
    asNonNegativeInt(root.usage?.total_tokens) ??
    asNonNegativeInt(root.usage?.totalTokens) ??
    promptTokens

  return {
    embeddings,
    promptTokens,
    totalTokens,
  }
}

export const createEmbedderCore = <TChunk extends VectorChunkLike>({
  indexVectorDimension,
  estimateEmbeddingCostUsd,
  sha256Hex,
  loadCache,
  upsertCache,
}: CreateEmbedderCoreArgs) => {

const normalizeEmbedding = (embedding: number[]): number[] => {
  if (embedding.length !== indexVectorDimension) {
    throw new Error(
      `Embedding dimension mismatch. Expected ${indexVectorDimension}, received ${embedding.length}.`,
    )
  }

  return embedding.map((value) => {
    if (!Number.isFinite(value)) {
      throw new Error("Embedding contains non-finite values.")
    }

    return Number(value.toFixed(8))
  })
}

const embedTextDeterministic = (text: string, dimension: number): number[] => {
  const values: number[] = []
  let counter = 0

  while (values.length < dimension) {
    const hash = sha256Hex(`${text}:${counter}`)
    for (
      let offset = 0;
      offset < hash.length && values.length < dimension;
      offset += 2
    ) {
      const byte = Number.parseInt(hash.slice(offset, offset + 2), 16)
      const normalized = (byte / 255) * 2 - 1
      values.push(Number(normalized.toFixed(8)))
    }
    counter += 1
  }

  return values
}

const collectUniqueMisses = (args: {
  chunks: Array<Omit<TChunk, "embedding">>
  cached: Map<string, CacheEntry>
  model: string
}): Array<{ chunkId: string; content: string }> => {
  const uniqueMisses = new Map<string, { chunkId: string; content: string }>()

  for (const chunk of args.chunks) {
    const hit = args.cached.get(chunk.chunkId)
    if (hit && hit.model === args.model && hit.embedding.length === indexVectorDimension) {
      continue
    }

    if (!uniqueMisses.has(chunk.chunkId)) {
      uniqueMisses.set(chunk.chunkId, {
        chunkId: chunk.chunkId,
        content: chunk.content,
      })
    }
  }

  return [...uniqueMisses.values()]
}

const requestOpenAiEmbeddings = async (
  inputs: string[],
  telemetry?: EmbeddingTelemetry,
): Promise<number[][]> => {
  const apiKey = resolveApiKey()
  if (!apiKey) {
    if (telemetry) {
      telemetry.failureCount += 1
    }
    throw new Error(
      "Missing embedding API key for openai provider. Set INDEXER_EMBEDDING_API_KEY, OPENAI_API_KEY, or AI_API_TOKEN.",
    )
  }

  const model = resolveEmbeddingModel()
  const url = `${resolveBaseUrl()}/embeddings`
  const timeoutMs = parsePositiveInt(process.env.INDEXER_EMBEDDING_TIMEOUT_MS, 30_000)
  const maxAttempts = parsePositiveInt(process.env.INDEXER_EMBEDDING_RETRIES, 3)

  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {

try {
  if (telemetry) {
    telemetry.requestCount += 1
  }

  const response = await fetch(url, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model,
      input: inputs,
    }),
    signal: AbortSignal.timeout(timeoutMs),
  })

  if (!response.ok) {
    const bodyText = (await response.text()).slice(0, 500)
    const isRetryable = response.status === 429 || response.status >= 500
    if (!isRetryable || attempt === maxAttempts) {
      throw createEmbeddingRequestError(
        `Embedding request failed (${response.status}): ${bodyText || response.statusText}`,
        isRetryable,
      )
    }

    await sleep(200 * 2 ** (attempt - 1))
    continue
  }

  const payload = await response.json()
  const parsed = parseOpenAiResponse(payload, normalizeEmbedding)
  const embeddings = parsed.embeddings
  if (embeddings.length !== inputs.length) {
    throw new Error(
      `Embedding response count mismatch. Expected ${inputs.length}, received ${embeddings.length}.`,
    )
  }
  if (telemetry) {
    telemetry.promptTokens += parsed.promptTokens
    telemetry.totalTokens += parsed.totalTokens
  }

  return embeddings
} catch (error) {

      const retryable = (error as { retryable?: unknown })?.retryable
      const shouldRetry = retryable === false ? false : attempt < maxAttempts
      if (!shouldRetry) {
        if (telemetry) {
          telemetry.failureCount += 1
        }
        throw error
      }

      await sleep(200 * 2 ** (attempt - 1))
    }
  }

  throw new Error("Embedding request failed unexpectedly.")
}

const createEmptyTelemetry = (args: {
  inputCount: number
  cacheHitCount: number
  cacheMissCount: number
}): EmbeddingTelemetry => ({
  provider: resolveProvider(),
  model: resolveTelemetryModel(),
  inputCount: args.inputCount,
  cacheHitCount: args.cacheHitCount,
  cacheMissCount: args.cacheMissCount,
  requestCount: 0,
  failureCount: 0,
  promptTokens: 0,
  totalTokens: 0,
  latencyMs: 0,
  costUsd: null,
})

const finalizeTelemetry = (telemetry: EmbeddingTelemetry, startedAt: number) => {
  telemetry.latencyMs = Math.max(0, Date.now() - startedAt)
  telemetry.costUsd = estimateEmbeddingCostUsd({
    model: telemetry.model,
    totalTokens: telemetry.totalTokens,
  })
}

const emitTelemetry = (
  hook: EmbedTelemetryHook | undefined,
  telemetry: EmbeddingTelemetry,
) => {
  if (!hook) {
    return
  }

  try {
    hook(telemetry)
  } catch {
    // Telemetry hook errors must never break embedding flow.
  }
}

const embedTexts = async (
  inputs: string[],
  telemetry?: EmbeddingTelemetry,
): Promise<number[][]> => {
  if (inputs.length === 0) {
    return []
  }

  if (resolveProvider() === "deterministic") {
    return inputs.map((input) =>
      normalizeEmbedding(embedTextDeterministic(input, indexVectorDimension)),
    )
  }

  const batchSize = parsePositiveInt(process.env.INDEXER_EMBEDDING_BATCH_SIZE, 32)
  const maxRequestTokens = resolveMaxRequestTokens()
  const batches = buildEmbeddingBatches({
    inputs,
    maxBatchSize: batchSize,
    maxRequestTokens,
  })
  const output: number[][] = []

  for (const batch of batches) {
    const vectors = await requestOpenAiEmbeddings(batch, telemetry)
    output.push(...vectors)
  }

  if (telemetry && telemetry.provider === "openai" && telemetry.promptTokens <= 0) {
    const estimatedPromptTokens = inputs.reduce(
      (sum, input) => sum + estimateTokenUpperBound(input),
      0,
    )
    telemetry.promptTokens = Math.max(0, estimatedPromptTokens)
    telemetry.totalTokens = Math.max(telemetry.totalTokens, telemetry.promptTokens)
  }

  return output
}

const embedQueryText = async (
  query: string,
  options: { onTelemetry?: EmbedTelemetryHook } = {},
): Promise<number[]> => {
  const startedAt = Date.now()
  const telemetry = createEmptyTelemetry({
    inputCount: 1,
    cacheHitCount: 0,
    cacheMissCount: 1,
  })

  try {
    const [embedding] = await embedTexts([query], telemetry)
    if (!embedding) {
      telemetry.failureCount = Math.max(1, telemetry.failureCount)
      throw new Error("Failed to embed query text.")
    }

    return embedding
  } catch (error) {
    telemetry.failureCount = Math.max(1, telemetry.failureCount)
    throw error
  } finally {
    finalizeTelemetry(telemetry, startedAt)
    emitTelemetry(options.onTelemetry, telemetry)
  }
}

const embedVectorChunks = async (
  chunks: Array<Omit<TChunk, "embedding">>,
  options: { onTelemetry?: EmbedTelemetryHook } = {},
): Promise<Array<Omit<TChunk, "embedding"> & { embedding: number[] }>> => {
  if (chunks.length === 0) {
    return []
  }

  const chunkIds = [...new Set(chunks.map((chunk) => chunk.chunkId))]
  const model = resolveCacheModelKey()
  const cached = await loadCache(chunkIds)
  const misses = collectUniqueMisses({
    chunks,
    cached,
    model,
  })
  const startedAt = Date.now()
  const telemetry = createEmptyTelemetry({
    inputCount: misses.length,
    cacheHitCount: Math.max(0, chunkIds.length - misses.length),
    cacheMissCount: misses.length,
  })

  const missEmbeddings = new Map<string, number[]>()

try {
  if (misses.length > 0) {
    const vectors = await embedTexts(
      misses.map((miss) => miss.content),
      telemetry,
    )
    misses.forEach((miss, index) => {
      const vector = vectors[index]
      if (!vector) {
        telemetry.failureCount = Math.max(1, telemetry.failureCount)
        throw new Error(`Missing embedding response for chunk ${miss.chunkId}.`)
      }

      missEmbeddings.set(miss.chunkId, vector)
    })

    await upsertCache(
      misses.map((miss) => {
        const embedding = missEmbeddings.get(miss.chunkId)
        if (!embedding) {
          telemetry.failureCount = Math.max(1, telemetry.failureCount)
          throw new Error(
            `Missing embedding cache payload for chunk ${miss.chunkId}.`,
          )
        }

        return {
          chunkId: miss.chunkId,
          embedding,
        }
      }),
      model,
    )
  }

  return chunks.map((chunk) => {
    const cacheHit = cached.get(chunk.chunkId)
    const embedding = missEmbeddings.get(chunk.chunkId) ?? cacheHit?.embedding
    if (!embedding) {
      telemetry.failureCount = Math.max(1, telemetry.failureCount)
      throw new Error(`Embedding unavailable for chunk ${chunk.chunkId}.`)
    }

    return {
      ...chunk,
      embedding: normalizeEmbedding(embedding),
    }
  })
} catch (error) {

      telemetry.failureCount = Math.max(1, telemetry.failureCount)
      throw error
    } finally {
      finalizeTelemetry(telemetry, startedAt)
      emitTelemetry(options.onTelemetry, telemetry)
    }
  }

  return {
    embedQueryText,
    embedVectorChunks,
    __testables: {
      buildEmbeddingBatches,
      estimateTokenUpperBound,
      collectUniqueMisses,
      resolveApiKey,
      resolveApiKeyFromEnv,
      resolveProvider,
      resolveBaseUrl,
    },
  }
}

import { NextResponse } from "next/server"
import { z } from "zod"

import {
  buildLlmMetrics,
  extractUsageFromOpenAiCompatiblePayload,
  resolveLlmProviderLabel,
} from "@/lib/observability/metrics"
import { requireJsonBody } from "@/lib/http/request-json"
import { parseJsonResponse } from "@/lib/http/response-json"
import { isPrivateOrLocalHost } from "@/lib/http/private-host"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const CHAT_TIMEOUT_MS = 30_000
const DEFAULT_AI_API_URL = "https://api.openai.com/v1"
const DEFAULT_AI_MODEL = "gpt-4o-mini"
const MAX_PROVIDER_ERROR_LENGTH = 260
const MAX_QUESTION_LENGTH = 1_200

type ChatMessage = {
  role: "user" | "assistant"
  content: string
}

type ProviderChatResponse = {
  choices?: Array<{
    message?: {
      content?: unknown
    }
  }>
  usage?: {
    prompt_tokens?: unknown
    completion_tokens?: unknown
    total_tokens?: unknown
  }
}

const chatPayloadSchema = z.object({
  question: z.string().trim().min(1).max(MAX_QUESTION_LENGTH),
  history: z
    .array(
      z.object({
        role: z.enum(["user", "assistant"]),
        content: z.string().trim().min(1).max(2_000),
      }),
    )
    .max(10)
    .optional(),
  pathname: z.string().trim().max(200).optional(),
  apiUrl: z.string().trim().min(1).optional(),
  model: z.string().trim().min(1).optional(),
  token: z.string().optional(),
})

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const pickFirstNonEmpty = (...values: Array<string | undefined>) => {
  for (const value of values) {
    if (isNonEmptyString(value)) {
      return value.trim()
    }
  }
  return ""
}

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const resolveApiUrl = (rawApiUrl: string) => {
  let parsed: URL
  try {
    parsed = new URL(rawApiUrl)
  } catch {
    throw new Error("API URL must be a valid absolute URL.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("API URL must use http or https.")
  }
  if (parsed.username || parsed.password) {
    throw new Error("API URL must not include credentials.")
  }
  if (isPrivateOrLocalHost(parsed.hostname)) {
    throw new Error("API URL must not target localhost or private network hosts.")
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  const normalized = pathname ? `${parsed.origin}${pathname}` : parsed.origin
  return normalizeApiUrl(normalized)
}

const getEnvApiUrl = () =>
  pickFirstNonEmpty(
    process.env.AI_API_URL,
    process.env.OPENAI_BASE_URL,
  ) || DEFAULT_AI_API_URL

const getEnvModel = () =>
  pickFirstNonEmpty(
    process.env.AI_MODEL,
    process.env.OPENAI_MODEL,
  ) || DEFAULT_AI_MODEL

const getEnvToken = () =>
  pickFirstNonEmpty(
    process.env.AI_API_TOKEN,
    process.env.OPENAI_API_KEY,
  )

const getChatCompletionsUrl = (apiUrl: string) => {
  const normalized = normalizeApiUrl(apiUrl)
  if (/\/chat\/completions$/i.test(normalized)) {
    return normalized
  }
  return `${normalized}/chat/completions`
}

const readProviderErrorMessage = async (response: Response) => {
  const parsedResponse = await parseJsonResponse(response)
  const trimmed = parsedResponse.bodyText.trim()
  if (!trimmed) {
    return ""
  }

  if (parsedResponse.ok && !parsedResponse.isEmpty) {
    const parsed = parsedResponse.value
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return trimmed.slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }

    const root = parsed as Record<string, unknown>
    if (typeof root.error === "string" && root.error.trim().length > 0) {
      return root.error.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }

    if (root.error && typeof root.error === "object" && !Array.isArray(root.error)) {
      const nested = root.error as Record<string, unknown>
      if (typeof nested.message === "string" && nested.message.trim().length > 0) {
        return nested.message.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
      }
    }

    if (typeof root.message === "string" && root.message.trim().length > 0) {
      return root.message.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }
  }

  return trimmed.slice(0, MAX_PROVIDER_ERROR_LENGTH)
}

const buildNetworkErrorMessage = (error: unknown) => {
  if (error instanceof Error && error.name === "AbortError") {
    return `AI request timed out after ${Math.round(CHAT_TIMEOUT_MS / 1000)} seconds.`
  }

  if (error instanceof Error && error.message.trim().length > 0) {
    return `AI request failed before response: ${error.message}`
  }

  return "AI request failed before response."
}

const extractMessageText = (content: unknown): string => {
  if (typeof content === "string") {
    return content.trim()
  }

  if (!Array.isArray(content)) {
    return ""
  }

  const parts = content
    .map((part) => {
      if (!part || typeof part !== "object" || Array.isArray(part)) {
        return ""
      }
      const candidate = part as Record<string, unknown>
      if (typeof candidate.text === "string") {
        return candidate.text
      }
      if (candidate.type === "text" && typeof candidate.content === "string") {
        return candidate.content
      }
      return ""
    })
    .filter((part) => part.trim().length > 0)

  return parts.join("\n").trim()
}

const toPromptMessages = (args: {
  question: string
  history: ChatMessage[]
  pathname: string
}) => {
  const systemPrompt = [
    "You are Argus command palette assistant.",
    "Primary job: quickly answer where to find features in the Argus app and how to perform common actions.",
    "Answer in 2-5 concise bullets. Mention exact route paths when possible.",
    "If unsure, say you are unsure and suggest the closest likely route.",
    "Do not invent features that are not in this route guide.",
    "",
    `Current route: ${args.pathname || "(unknown)"}`,
    "Known routes and features:",
    APP_GUIDE,
  ].join("\n")

  return [
    {
      role: "system",
      content: systemPrompt,
    },
    ...args.history,
    {
      role: "user",
      content: args.question,
    },
  ]
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/command-palette/chat",
    event: "api.command_palette.chat",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "question is required."),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const parsed = chatPayloadSchema.safeParse(body.value)

if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "question is required." },
      { status: 400 },
    ),
  }
}

let serverApiUrl: string
try {
  serverApiUrl = resolveApiUrl(getEnvApiUrl())
} catch {
  return {
    status: 500,
    outcome: "missing_config",
    response: NextResponse.json(
      { error: "Server AI provider URL is invalid." },
      { status: 500 },
    ),
  }
}

let clientApiUrl = ""
if (parsed.data.apiUrl) {
  try {
    clientApiUrl = resolveApiUrl(parsed.data.apiUrl)
  } catch (error) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        { error: error instanceof Error ? error.message : "API URL is invalid." },
        { status: 400 },
      ),
    }
  }
}
const apiUrl = clientApiUrl || serverApiUrl
const hasCustomApiUrl = clientApiUrl.length > 0 && clientApiUrl !== serverApiUrl

const model = parsed.data.model?.trim() || getEnvModel()
const clientToken = parsed.data.token?.trim() ?? ""
const token = clientToken || (hasCustomApiUrl ? "" : getEnvToken())

if (!token) {
  return {
    status: 400,
    outcome: hasCustomApiUrl ? "invalid_request" : "missing_config",
    response: NextResponse.json(
      {
        error: hasCustomApiUrl
          ? "Custom API URL requires an explicit token."
          : "AI token missing. Set API token in settings or server env.",
      },
      { status: 400 },
    ),
  }
}

const history: ChatMessage[] = (parsed.data.history ?? [])
  .map((entry) => ({
    role: entry.role,
    content: entry.content.trim(),
  }))
  .filter((entry) => entry.content.length > 0)

const controller = new AbortController()
const timeout = setTimeout(() => {
  controller.abort()
}, CHAT_TIMEOUT_MS)
const startedAt = Date.now()
const provider = resolveLlmProviderLabel(apiUrl)

try {
  const response = await fetch(getChatCompletionsUrl(apiUrl), {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      model,
      temperature: 0.2,
      max_tokens: 420,
      messages: toPromptMessages({
        question: parsed.data.question,
        history,
        pathname: parsed.data.pathname ?? "",
      }),
    }),
    signal: controller.signal,
  })

if (!response.ok) {
  const providerError = await readProviderErrorMessage(response)
  const suffix = providerError ? ` ${providerError}` : ""
  logger.set({
    model,
    providerStatus: response.status,
    labels: {
      provider,
      model,
    },
  })
  return {
    status: 502,
    outcome: "upstream_error",
    response: NextResponse.json(
      {
        error: `AI provider request failed (${response.status}).${suffix}`,
        providerStatus: response.status,
      },
      { status: 502 },
    ),
  }
}

const latencyMs = Math.max(1, Date.now() - startedAt)
const parsedProviderResponse = await parseJsonResponse(response)
if (!parsedProviderResponse.ok || parsedProviderResponse.isEmpty) {
  logger.set({
    model,
    responseError: "invalid_json",
    labels: {
      provider,
      model,
    },
  })
  return {
    status: 502,
    outcome: "upstream_error",
    response: NextResponse.json(
      {
        error: "AI provider returned an invalid JSON payload.",
      },
      { status: 502 },
    ),
  }
}

const providerPayload = parsedProviderResponse.value as ProviderChatResponse
const answer = extractMessageText(providerPayload?.choices?.[0]?.message?.content)

  if (!answer) {
    logger.set({
      model,
      responseError: "empty_message",
      labels: {
        provider,
        model,
      },
    })
    return {
      status: 502,
      outcome: "upstream_error",
      response: NextResponse.json(
        {
          error: "AI response did not include a message.",
        },
        { status: 502 },
      ),
    }
  }

  const usage = extractUsageFromOpenAiCompatiblePayload(providerPayload)
  logger.set({
    model,
    latencyMs,
    labels: {
      provider,
      model,
    },
    llmMetrics: buildLlmMetrics({
      provider,
      model,
      promptTokens: usage.promptTokens,
      completionTokens: usage.completionTokens,
      totalTokens: usage.totalTokens,
      latencyMs,
      requestCount: 1,
    }),
  })

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({ answer }),
  }
} catch (error) {
  const message = buildNetworkErrorMessage(error)
  logger.set({
    model,
    networkError: message,
    labels: {
      provider,
      model,
    },
  })
  return {
    status: 502,
    outcome: "upstream_error",
    response: NextResponse.json(
      { error: message },
      { status: 502 },
    ),
  }
} finally {

        clearTimeout(timeout)
      }
    },
  })
}

