      const parsedPayload = await parseJsonResponse(response)
      const payload = parsedPayload.ok
        ? (parsedPayload.value as ReviewFeedbackPayload)
        : null
      if (!response.ok) {
        throw new Error(getReviewErrorMessage(payload))
      }
      setReviewFeedback(normalizeFeedback(payload?.data?.review?.feedback))
    } catch (error) {
      setReviewFeedbackError(getReviewErrorMessage(error))
    } finally {
      setIsSubmittingReviewFeedback(false)
    }
  },
  [buildRequestHeaders, isSubmittingReviewFeedback, reviewId],
)

