import { indexStream } from '@argus/argus-search/stream'

for await (const item of indexStream(
  {
    projectRoot: '/repo',
    inputs: { paths: ['src'], include: ['*.ts', '*.tsx'], exclude: ['node_modules', 'dist', '.git'] },
    phases: { parse: true, graph: true, vector: true, scip: false, indexPack: false },
    vector: {
      provider: { kind: 'http', baseUrl: 'http://127.0.0.1:8080', model: 'text-embedding-3-small', dimension: 1536 },
    },
  },
  { highWaterMark: 16 },
)) {
  if (item.type === 'vector:batch') {
    for (const record of item.batch) {
      // record.chunk is present in the stream (includes content by default)
      await writeVector(record)
    }
  }
  if (item.type === 'pipeline:complete') break
}
```

### Agent integration pattern (RAG)

The indexing pipeline is intended to feed an _agent-facing retrieval tool_:

1. Run `indexStream()` with `phases.vector=true` to emit `vector:batch` records (chunk + embedding).
2. Write those records into your vector store (pgvector/Qdrant/etc), keyed by `chunkId` + `filePath`.
3. Expose a tool like `code_search(query, topK)` that returns the top-matching chunks + metadata.
4. Let your agent call `code_search` before answering/editing code.

export const toError = (value: unknown, fallbackMessage = "Unknown error."): Error => {
  if (value instanceof Error) {
    return value
  }

  if (typeof value === "string" && value.trim().length > 0) {
    return new Error(value)
  }

  return new Error(fallbackMessage)
}

export const errorMessage = (value: unknown, fallbackMessage = "Unknown error."): string => {
  if (value instanceof Error) {
    return value.message
  }

  if (typeof value === "string" && value.trim().length > 0) {
    return value
  }

  return fallbackMessage
}

