type DbClient = typeof db

type KiteDbFsBackendDeps = {
  dbClient: DbClient
  graphArtifactsRoot: string
  readTextFile: (filePath: string) => Promise<string>
  statPath: (filePath: string) => Promise<Awaited<ReturnType<typeof stat>>>
  artifactStore: GraphArtifactStoreReader | null
}

let cachedGraphArtifactStoreReader: GraphArtifactStoreReader | null | undefined

const resolveGraphArtifactStoreReader = (): GraphArtifactStoreReader | null => {
  if (cachedGraphArtifactStoreReader !== undefined) {
    return cachedGraphArtifactStoreReader
  }

  const store = createArtifactStore()
  if (
    typeof store.readTextFile !== "function" ||
    typeof store.fileExists !== "function"
  ) {
    cachedGraphArtifactStoreReader = null
    return cachedGraphArtifactStoreReader
  }

  cachedGraphArtifactStoreReader = {
    readTextFile: (args) => store.readTextFile!.call(store, args),
    fileExists: (args) => store.fileExists!.call(store, args),
  }
  return cachedGraphArtifactStoreReader
}

const toOptionalString = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

const basePendingSnapshot = ({
  backend,
  integrationId,
  branch,
  reason,
  message,
}: {
  backend: ImpactGraphBackendKind
  integrationId: string | null
  branch: string | null
  reason: GraphSnapshotPendingReason
  message: string
}): GraphImpactSnapshotPending => ({
  status: "pending_graph",
  backend,
  integrationId,
  branch,
  reason,
  message,
})

const toMillis = (value: Date | null) => value?.getTime() ?? 0

const sortTraceNodes = (nodes: GraphTraceNode[], limit: number) =>
  [...nodes]
    .sort((left, right) => {
      if (left.depth !== right.depth) {
        return left.depth - right.depth
      }
      const kindDelta = nodeKindRank(left.kind) - nodeKindRank(right.kind)
      if (kindDelta !== 0) {
        return kindDelta
      }
      return left.name.localeCompare(right.name)
    })
    .slice(0, limit)

const buildTraceStartNode = (store: GraphStore, startNodeId: string): GraphTraceNode => {
  const startNode = store.nodesById.get(startNodeId)
  return {
    id: startNodeId,
    kind: startNode?.kind ?? "external",
    name: startNode?.name ?? startNodeId,
    filePath: startNode?.filePath ?? "",
    depth: 0,
    range: startNode?.range ?? null,
  }
}

const buildTraceResult = (args: {
  store: GraphStore
  startNodeId: string
  nodes: GraphTraceNode[]
  edges: GraphTraceEdge[]
}): GraphTraceResult => ({
  startNode: buildTraceStartNode(args.store, args.startNodeId),
  nodes: args.nodes,
  edges: args.edges,
})

