class KiteDbFsGraphImpactBackend implements GraphImpactBackend {
  readonly kind: ImpactGraphBackendKind = "kitedb_fs"
  private readonly deps: KiteDbFsBackendDeps
  private readonly storeCache = new Map<string, Promise<GraphStore>>()

  constructor(deps: KiteDbFsBackendDeps) {
    this.deps = deps
  }

private async resolveReadySnapshotFromRun(args: {
  integrationId: string
  branch: string
  run: {
    id: string
    status: "planned" | "ingesting" | "indexing" | "cancelled" | "ready" | "failed" | "superseded"
    artifactsPrefix: string | null
    stats?: Record<string, unknown> | null
  }
}): Promise<GraphImpactSnapshotReady | null> {
  return resolveReadySnapshotFromRunArtifacts({
    backend: this.kind,
    integrationId: args.integrationId,
    branch: args.branch,
    run: args.run,
    graphArtifactsRoot: this.deps.graphArtifactsRoot,
    readTextFile: this.deps.readTextFile,
    statPath: this.deps.statPath,
    artifactStore: this.deps.artifactStore,
  })
}

async resolveSnapshot(args: {
  integrationId: string | null
  sourceBranch: string | null
}): Promise<GraphImpactSnapshotResolution> {
  const integrationId = toOptionalString(args.integrationId)
  if (!integrationId) {
    return basePendingSnapshot({
      backend: this.kind,
      integrationId: null,
      branch: toOptionalString(args.sourceBranch),
      reason: "missing_integration_id",
      message: "Review is missing integration scope.",
    })
  }

  const branch = toOptionalString(args.sourceBranch)
  if (!branch) {
    return basePendingSnapshot({
      backend: this.kind,
      integrationId,
      branch: null,
      reason: "missing_source_branch",
      message: "Review is missing source branch metadata.",
    })
  }

try {
  const branchStates = await this.deps.dbClient.query.indexBranchStates.findMany({
    where: and(
      eq(indexBranchStates.integrationId, integrationId),
      eq(indexBranchStates.branch, branch),
    ),
    columns: {
      id: true,
      lastReadyRunId: true,
      servingUpdatedAt: true,
      updatedAt: true,
    },
  })

  if (branchStates.length === 0) {
    return basePendingSnapshot({
      backend: this.kind,
      integrationId,
      branch,
      reason: "branch_state_not_found",
      message: "Branch has not been indexed yet.",
    })
  }

  const selectedState = [...branchStates]
    .sort(
      (left, right) =>
        toMillis(right.servingUpdatedAt ?? right.updatedAt) -
        toMillis(left.servingUpdatedAt ?? left.updatedAt),
    )
    .find((state) => typeof state.lastReadyRunId === "string" && state.lastReadyRunId.length > 0)

  if (!selectedState?.lastReadyRunId) {
    return basePendingSnapshot({
      backend: this.kind,
      integrationId,
      branch,
      reason: "no_ready_run",
      message: "Branch indexing is still in progress.",
    })
  }

  const run = await this.deps.dbClient.query.indexRuns.findFirst({
    where: eq(indexRuns.id, selectedState.lastReadyRunId),
    columns: {
      id: true,
      status: true,
      artifactsPrefix: true,
      stats: true,
    },
  })

if (!run || run.status !== "ready") {
  return basePendingSnapshot({
    backend: this.kind,
    integrationId,
    branch,
    reason: "ready_run_not_found",
    message: "No ready graph snapshot is available for this branch.",
  })
}

if (isGraphBuildFailed(run.stats)) {
  return basePendingSnapshot({
    backend: this.kind,
    integrationId,
    branch,
    reason: "graph_build_failed",
    message: "Latest ready run failed to build graph artifacts.",
  })
}

if (isGraphBuildSkipped(run.stats)) {
  return basePendingSnapshot({
    backend: this.kind,
    integrationId,
    branch,
    reason: "graph_build_skipped",
    message: "Latest ready run did not produce graph artifacts.",
  })
}

if (isGraphBuildMissingArtifacts(run.stats)) {
  return basePendingSnapshot({
    backend: this.kind,
    integrationId,
    branch,
    reason: "missing_artifacts",
    message: "Branch graph artifacts are not ready yet.",
  })
}

const resolved = await this.resolveReadySnapshotFromRun({
  integrationId,
  branch,
  run,
})
if (resolved) {
  return resolved
}
return basePendingSnapshot({
  backend: this.kind,
  integrationId,
  branch,
  reason: "missing_artifacts",
  message: "Branch graph artifacts are not ready yet.",
})

  } catch (error) {
    return {
      status: "error",
      backend: this.kind,
      integrationId,
      branch,
      error: errorMessage(error),
    }
  }
}

private async loadStore(snapshot: GraphImpactSnapshotReady): Promise<GraphStore> {
  const cacheKey = (() => {
    const prefix = toOptionalString(snapshot.artifactStorePrefix)
    const nodesFilename = toOptionalString(snapshot.artifactStoreNodesFilename)
    const edgesFilename = toOptionalString(snapshot.artifactStoreEdgesFilename)
    if (prefix && nodesFilename && edgesFilename) {
      return `${snapshot.indexRunId}:artifact-store:${prefix}:${nodesFilename}:${edgesFilename}`
    }
    return `${snapshot.indexRunId}:local-fs:${snapshot.nodesPath}:${snapshot.edgesPath}`
  })()
  const cached = this.storeCache.get(cacheKey)
  if (cached) {
    return cached
  }

  const loading = loadGraphStoreFromSnapshot({
    snapshot,
    artifactStore: this.deps.artifactStore,
  }).catch((error) => {
    this.storeCache.delete(cacheKey)
    throw error
  })

  this.storeCache.set(cacheKey, loading)
  return loading
}

async matchFindingLocation(args: {
  snapshot: GraphImpactSnapshotReady
  filePath: string
  line: number
  title?: string
  body?: string
  evidence?: string
}): Promise<GraphImpactNodeMatch | null> {
  const store = await this.loadStore(args.snapshot)
  const normalizedFilePath = normalizePath(args.filePath)
  if (!normalizedFilePath) {
    return null
  }

const nodesInFile = store.nodesByFilePath.get(normalizedFilePath) ?? []
if (nodesInFile.length === 0) {
  return null
}

const findingText = [args.title, args.body, args.evidence].filter(Boolean).join("\n")
const identifierCandidates = extractFindingIdentifierCandidates(findingText)
const signatureHint = includesAnyKeyword(findingText.toLowerCase(), [
  "signature",
  "return type",
  "parameter",
  "mismatch",
  "changed from",
])

const symbolNodes = nodesInFile.filter((node) => node.kind !== "file" && includesLine(node, args.line))
const namedSymbolNodes = nodesInFile.filter((node) => {
  if (node.kind === "file") {
    return false
  }
  return nodeNameMatchesFinding(node.name, identifierCandidates)
})

const symbolNode =
  pickBestFindingSymbolNode({
    nodes: symbolNodes,
    line: args.line,
    identifierCandidates,
    preferFunctionSymbols: signatureHint,
  }) ??
  pickBestFindingSymbolNode({
    nodes: namedSymbolNodes,
    line: args.line,
    identifierCandidates,
    preferFunctionSymbols: signatureHint,
  }) ??
  pickBestNode(symbolNodes)
if (symbolNode) {
  return {
    nodeId: symbolNode.id,
    scope: "symbol",
    sourceFile: symbolNode.filePath ?? normalizedFilePath,
    sourceLine: args.line,
  }
}

if (signatureHint && identifierCandidates.size > 0) {
  return null
}

const fileNode = nodesInFile.find((node) => node.kind === "file") ?? nodesInFile[0]

  if (!fileNode) {
    return null
  }

  return {
    nodeId: fileNode.id,
    scope: "file",
    sourceFile: fileNode.filePath ?? normalizedFilePath,
    sourceLine: args.line,
  }
}

async summarizeImpact(args: {
  snapshot: GraphImpactSnapshotReady
  nodeId: string
}): Promise<GraphImpactSummary> {
  const store = await this.loadStore(args.snapshot)
  const nodeId = args.nodeId.trim()
  if (!nodeId) {
    throw new Error("Impact summary requires a non-empty nodeId.")
  }

  const callers = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "incoming",
    edgeTypes: new Set(["CALLS"]),
    depth: 2,
    maxNodes: 4_000,
  })
  const callees = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "outgoing",
    edgeTypes: new Set(["CALLS"]),
    depth: 2,
    maxNodes: 4_000,
  })
  const dependents = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "incoming",
    edgeTypes: new Set(["IMPORTS"]),
    depth: 2,
    maxNodes: 4_000,
  })
  const dependencies = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "outgoing",
    edgeTypes: new Set(["IMPORTS"]),
    depth: 2,
    maxNodes: 4_000,
  })
  const impacted = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "both",
    edgeTypes: new Set(["CALLS", "IMPORTS", "REFERENCES"]),
    depth: 2,
    maxNodes: 4_000,
  })

  const fileCounts = new Map<string, number>()

let affectedSymbolsCount = 0
for (const impactedNodeId of impacted) {
  const node = store.nodesById.get(impactedNodeId)
  if (!node) {
    continue
  }
  if (node.kind !== "file") {
    affectedSymbolsCount += 1
  }
  if (!node.filePath) {
    continue
  }
  const normalizedFilePath = normalizePath(node.filePath)
  fileCounts.set(normalizedFilePath, (fileCounts.get(normalizedFilePath) ?? 0) + 1)
}

const topImpactedFiles = [...fileCounts.entries()]
  .sort((left, right) => {
    if (right[1] !== left[1]) {
      return right[1] - left[1]
    }
    return left[0].localeCompare(right[0])
  })
  .slice(0, 5)
  .map(([filePath, count]) => ({ filePath, count }))

return {
  callersCount: callers.size,
  calleesCount: callees.size,
  dependentsCount: dependents.size,
  dependenciesCount: dependencies.size,
  affectedFilesCount: fileCounts.size,
  affectedSymbolsCount,
  topImpactedFiles,
}

}

async traceGraph(args: {
  snapshot: GraphImpactSnapshotReady
  mode: GraphTraceMode
  symbol?: string
  nodeId?: string
  depth?: number
  limit?: number
}): Promise<GraphTraceResult | null> {
  const limit = Math.min(200, Math.max(1, args.limit ?? 25))
  const depth = args.mode === "impact" ? Math.min(6, Math.max(1, args.depth ?? 3)) : 1

  // Prefer KiteDB-native traversal whenever we have a local store path.
  const kiteResult = await this.traceGraphViaKiteCli({
    ...args,
    limit,
    depth,
  })
  if (kiteResult) {
    return kiteResult
  }

  // Fallback traversal for remote artifact-only snapshots or SDK/runtime failures.
  return this.traceGraphViaStoreFallback({
    ...args,
    limit,
    depth,
  })
}

private async traceGraphViaKiteCli(args: TraceGraphArgs & { limit: number; depth: number }) {
  if (!args.snapshot.graphStorePath) {
    return null
  }

  const kiteTraceNodes = await (async () => {
    try {
      const raw = await runTraceGraph({
        mode: args.mode,
        symbol: args.symbol?.trim(),
        nodeId: args.nodeId?.trim(),
        limit: args.limit,
        depth: args.mode === "impact" ? args.depth : undefined,
        projectRoot: process.cwd(),
        storePath: args.snapshot.graphStorePath ?? undefined,
        timeoutMs: 30_000,
      })
      return parseKiteTraceResult(raw, args.mode)
    } catch {
      return null
    }
  })()

  if (!kiteTraceNodes) {
    return null
  }

  const store = await this.loadStore(args.snapshot)
  const startNodeId = resolveTraceStartNodeId({
    store,
    nodeId: args.nodeId,
    symbol: args.symbol,
  })
  if (!startNodeId) {
    return null
  }

  const dedupedNodes = new Map<string, GraphTraceNode>()
  for (const node of kiteTraceNodes) {
    if (node.id === startNodeId) {
      continue
    }
    const current = dedupedNodes.get(node.id)
    if (!current || node.depth < current.depth) {
      dedupedNodes.set(node.id, node)
    }
  }

  const nodes = sortTraceNodes([...dedupedNodes.values()], args.limit)
  const includedNodeIds = new Set<string>([
    startNodeId,
    ...nodes.map((node) => node.id),
  ])
  const edges = collectEdgesWithinIncludedNodes({
    store,
    includedNodeIds,
    edgeTypes: args.mode === "impact" ? new Set(["CALLS", "IMPORTS", "REFERENCES"]) : new Set(["CALLS"]),
    direction: args.mode === "impact" ? "both" : "incoming",
    maxEdges: Math.min(10_000, Math.max(args.limit * 20, 500)),
  })

  return buildTraceResult({
    store,
    startNodeId,
    nodes,
    edges,
  })
}

private async traceGraphViaStoreFallback(args: TraceGraphArgs & { limit: number; depth: number }) {
  const store = await this.loadStore(args.snapshot)
  const startNodeId = resolveTraceStartNodeId({
    store,
    nodeId: args.nodeId,
    symbol: args.symbol,
  })
  if (!startNodeId) {
    return null
  }

  const maxNodes = Math.min(4_000, Math.max(args.limit + 1, args.limit * 8))

const traversal =
  args.mode === "impact"
    ? collectReachableSubgraph({
        store,
        startNodeId,
        direction: "both",
        edgeTypes: new Set(["CALLS", "IMPORTS", "REFERENCES"]),
        depth: args.depth,
        maxNodes,
        maxEdges: Math.min(10_000, Math.max(args.limit * 12, 300)),
      })
    : collectReachableSubgraph({
        store,
        startNodeId,
        direction: "incoming",
        edgeTypes: new Set(["CALLS"]),
        depth: 1,
        maxNodes,
        maxEdges: Math.min(10_000, Math.max(args.limit * 10, 200)),
      })

const nodes = sortTraceNodes(
  [...traversal.depths.entries()]
  .map(([id, depth]) => {
    const node = store.nodesById.get(id)
    if (!node) {
      return null
    }
    return {
      id: node.id,
      kind: node.kind,
      name: node.name ?? node.id,
      filePath: node.filePath ?? "",
      depth,
      range: node.range,
    } satisfies GraphTraceNode
  })
  .filter((item): item is GraphTraceNode => item !== null),
  args.limit,
)
const includedNodeIds = new Set<string>([
  startNodeId,
  ...nodes.map((node) => node.id),
])
const edges = traversal.edges
  .filter(
    (edge) =>
      includedNodeIds.has(edge.sourceId) &&
      includedNodeIds.has(edge.targetId),
  )
  .slice(0, Math.min(10_000, Math.max(args.limit * 20, 500)))

    return buildTraceResult({
      store,
      startNodeId,
      nodes,
      edges,
    })
  }
}

