import { describe, expect, test } from "bun:test"

import { extractLogEventName, toSafeJsonObject } from "./observability"

describe("shared observability event utils", () => {
  test("extractLogEventName prefers explicit event name", () => {
    expect(extractLogEventName({ event: "indexer.batch.done", tag: "warn", path: "/x" })).toBe(
      "indexer.batch.done",
    )
  })

  test("extractLogEventName falls back to tag/path", () => {
    expect(extractLogEventName({ tag: "warn" })).toBe("log.warn")
    expect(extractLogEventName({ path: "/api/x" })).toBe("request./api/x")
    expect(extractLogEventName({})).toBe("log.unknown")
  })

  test("toSafeJsonObject serializes plain objects and guards bad payloads", () => {
    expect(toSafeJsonObject({ a: 1 })).toEqual({ a: 1 })

    const circular: Record<string, unknown> = {}
    circular.self = circular
    expect(toSafeJsonObject(circular)).toEqual({ serializationError: true })

    expect(toSafeJsonObject("x")).toEqual({})
  })
})

import { afterEach, describe, expect, mock, test } from "bun:test"
import * as actualReact from "react"
import { mergeModuleWithOverrides } from "@/test-utils/module-mock"

const flushMicrotasks = async () => {
  await Promise.resolve()
  await Promise.resolve()
}

const loadModule = async () => {
  mock.module("react", () =>
    mergeModuleWithOverrides<typeof import("react")>(actualReact, {
      useEffect: (effect: () => void | (() => void)) => {
        effect()
      },
    }),
  )

  return import(
    `@/features/onboarding/hooks/use-mr-prefetch.ts?cacheBust=${Math.random()
      .toString(36)
      .slice(2)}`,
  )
}

afterEach(() => {
  mock.restore()
})

describe("use-mr-prefetch", () => {
  test("includes selected project outside top preload window and skips fresh queries", async () => {
    const mod = await loadModule()
    const prefetchedProjectIds: string[] = []
    const queryState = new Map<string, { fetchStatus: string; dataUpdatedAt: number }>()
    const keyFor = (value: unknown) => JSON.stringify(value)

    const mergeRequestsQueryKey = (projectId: string, perPage: number) =>
      ["onboarding", "merge-requests", "cache-key", projectId, perPage] as const

    queryState.set(keyFor(mergeRequestsQueryKey("p1", 5)), {
      fetchStatus: "idle",
      dataUpdatedAt: Date.now(),
    })

    const queryClient = {
      getQueryState: mock((queryKey: unknown) => queryState.get(keyFor(queryKey))),
      prefetchQuery: mock(
        async ({ queryKey }: { queryKey: readonly [string, string, string, string, number] }) => {
          prefetchedProjectIds.push(queryKey[3])
          queryState.set(keyFor(queryKey), {
            fetchStatus: "idle",
            dataUpdatedAt: Date.now(),
          })
          return undefined
        },
      ),
    }

    mod.useOnboardingMrPrefetch({
      isHydrated: true,
      routeStep: "projects",
      projectsCacheKey: "cache-key",
      projects: [
        { id: "p1", name: "P1", path: "g/p1", webUrl: "https://gitlab/p1" },
        { id: "p2", name: "P2", path: "g/p2", webUrl: "https://gitlab/p2" },
        { id: "p3", name: "P3", path: "g/p3", webUrl: "https://gitlab/p3" },
