const toReviewSeverity = (value: unknown): AiReviewFinding["severity"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (normalized === "high") {
    return "high"
  }
  if (normalized === "medium" || normalized === "med") {
    return "med"
  }
  return "low"
}

const toConfidence = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return 0.7
  }
  return Math.max(0, Math.min(1, value))
}

const toEvidence = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

const parseFindings = (value: unknown): AiReviewFinding[] => {
  if (!Array.isArray(value)) {
    return []
  }

  const normalizedFindings: AiReviewFinding[] = []
  for (const item of value) {
    if (!item || typeof item !== "object") {
      continue
    }
    const finding = item as Record<string, unknown>
    const line = Number(finding.line)
    const file = String(finding.file ?? "").trim()
    const title = String(finding.title ?? "").trim()
    const body = String(finding.body ?? finding.explanation ?? "").trim()
    if (!file || !title || !body || !Number.isFinite(line) || line < 1) {
      continue
    }

    const normalizedFinding: AiReviewFinding = {
      file,
      line: Math.floor(line),
      side: toReviewSide(finding.side),
      severity: toReviewSeverity(finding.severity),
      title,
      body,
      confidence: toConfidence(finding.confidence),
      evidence: toEvidence(finding.evidence),
    }
    normalizedFindings.push(normalizedFinding)
  }

  return normalizedFindings.slice(0, MAX_FINDINGS)
}

const toOptionalString = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

const toTraceId = (value: unknown) => {
  const normalized = toOptionalString(value)
  if (!normalized) {
    return null
  }
  return normalized.slice(0, MAX_TRACE_ID_LENGTH)
}

const toFindingPreview = (findings: AiReviewFinding[]) =>
  findings.map((finding) => ({
    file: finding.file,
    line: finding.line,
    side: finding.side,
    severity: finding.severity,
    title: finding.title,
    body: finding.body.slice(0, MAX_FINDING_BODY_PREVIEW_CHARS),
    confidence: finding.confidence,
    evidence: finding.evidence ?? "",
  }))

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/save",
    event: "api.review.save",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "Patch is required."),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const payload = body.value as SaveReviewPayload | null
      const patch = isNonEmptyString(payload?.patch) ? payload.patch : ""
      const instanceUrl = normalizeApiUrl(String(payload?.instanceUrl ?? "").trim())
      const projectId = String(payload?.projectId ?? "").trim()
      const mergeRequestIid = String(payload?.mergeRequestIid ?? "").trim()
      const integrationId = toOptionalString(payload?.integrationId)
      const reviewTraceId = toTraceId(payload?.reviewTraceId)
      const findings = reconcileFindingLinesWithPatch({
        patch,
        findings: parseFindings(payload?.findings),
      })

const usedServerToken = payload?.usedServerToken === true

if (reviewTraceId) {
  try {
    await startReviewFlowRun({
      userId,
      traceId: reviewTraceId,
      instanceUrl,
      projectId,
      mergeRequestIid,
      integrationId,
    })
  } catch (error) {
    logger.set({
      reviewFlowStartError: error instanceof Error ? error.message : "unknown",
    })
  }
}

try {
  const result = await persistReviewRun({
    userId,
    patch,
    findings,
    summary: toOptionalString(payload?.summary),
    instanceUrl,
    projectId,
    mergeRequestIid,
    integrationId,
    sourceBranch: toOptionalString(payload?.sourceBranch),
    sourceHeadSha: toOptionalString(payload?.sourceHeadSha),
    usedServerToken,
    logger,
  })

  if (reviewTraceId && result.review) {
    try {
      await markReviewFlowRunSuccess({
        userId,
        traceId: reviewTraceId,
        reviewId: result.review.id,
        instanceUrl,
        projectId,
        mergeRequestIid,
        integrationId: result.integrationId ?? integrationId,
      })
    } catch (error) {
      logger.set({
        reviewFlowSuccessError: error instanceof Error ? error.message : "unknown",
      })
    }
  }

        logger.set({
          reviewTraceId,
          reviewSummary: result.summary.slice(0, MAX_SUMMARY_PREVIEW_CHARS),
          findings: toFindingPreview(result.filteredFindings),
          model: result.model,
          patchLength: patch.length,
          findingsCount: result.filteredFindings.length,
          suppressedFindingsCount: result.suppressedFindingsCount,
          suppressedByReason: result.suppressedByReason,
          gateScopeSource: result.gateProfile.scopeSource,
          autoPostEnabled: Object.keys(result.review?.commentPublishByKey ?? {}).length > 0,
          reviewId: result.review?.id ?? null,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({
            data: {
              review: result.review,
              suppressedFindingsCount: result.suppressedFindingsCount,
              suppressedByReason: result.suppressedByReason,
              gateProfile: result.gateProfile,
            },
          }),
        }
      } catch (error) {
        if (error instanceof PersistReviewRunError) {
          return {
            status: error.status,
            outcome: "invalid_request",
            response: NextResponse.json({ error: error.message }, { status: error.status }),
          }
        }
        throw error
      }
    },
  })
}

