import { NextResponse } from "next/server"
import { z } from "zod"

import { secureCompare } from "@/lib/gitlab/crypto"
import { gitlabEnv } from "@/lib/gitlab/env"
import { requireJsonBodyOrEmpty } from "@/lib/http/request-json"
import { runGitLabJobRunner } from "@/lib/gitlab/jobs"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const runPayloadSchema = z.object({
  batchSize: z.number().int().positive().max(200).optional(),
})

const isAuthorizedRunnerRequest = (request: Request) => {
  const headerValue = request.headers.get("x-internal-runner-key")
  if (!headerValue) {
    return false
  }
  return secureCompare(headerValue, gitlabEnv.internalRunnerKey)
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/internal/gitlab-jobs/run",
    event: "api.gitlab.jobs.run",
    handler: async ({ logger }) => {
      if (!isAuthorizedRunnerRequest(request)) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const body = await requireJsonBodyOrEmpty(request, "Invalid runner payload.")
      if (!body.ok) return body.result

      const parsed = runPayloadSchema.safeParse(body.value)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid runner payload." }, { status: 400 }),
        }
      }

      const summary = await runGitLabJobRunner(parsed.data.batchSize)
      logger.set({
        summary,
      })
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: summary }),
      }
    },
  })
}

