import { asRecord } from "@/components/observability/utils"

export const statusConfig = (status: ObservabilityAiRunStatus) => {
  if (status === "failed")
    return {
      variant: "destructive" as const,
      icon: IconCircleX,
      label: "Failed",
      dotColor: "bg-red-500",
      ringColor: "ring-red-500/20",
    }
  if (status === "in_progress")
    return {
      variant: "secondary" as const,
      icon: IconLoader2,
      label: "Running",
      dotColor: "bg-amber-500",
      ringColor: "ring-amber-500/20",
    }
  return {
    variant: "default" as const,
    icon: IconCircleCheck,
    label: "Success",
    dotColor: "bg-emerald-500",
    ringColor: "ring-emerald-500/20",
  }
}

export const asNumber = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value)) return value
  if (typeof value === "string" && value.trim()) {
    const parsed = Number.parseFloat(value)
    return Number.isFinite(parsed) ? parsed : null
  }
  return null
}

export const asStringArray = (value: unknown) => {
  if (!Array.isArray(value)) return [] as string[]
  return Array.from(
    new Set(
      value
        .map((entry) => String(entry ?? "").trim())
        .filter((entry) => entry.length > 0),
    ),
  )
}

export const formatStepAction = (step: ObservabilityAiRun["steps"][number]) => {
  const payload = asRecord(step.payload) ?? {}
  const batchIndex = asNumber(payload.reviewBatchIndex)
  const totalBatches = asNumber(payload.reviewTotalBatches)
  const flowMessage = typeof payload.reviewFlowMessage === "string" ? payload.reviewFlowMessage.trim() : ""
  const flowStage = typeof payload.reviewFlowStage === "string" ? payload.reviewFlowStage.trim() : ""
  const flowEventType = typeof payload.reviewFlowEventType === "string" ? payload.reviewFlowEventType.trim() : ""

  if (step.event === "api.review.diff") {
    if (batchIndex !== null && totalBatches !== null)
      return `Analyze batch ${batchIndex}/${totalBatches}`
    return "Analyze diff batch"
  }
  if (step.event === "api.review.flow") {
    if (flowMessage) return flowMessage
    if (flowStage) return `Worker ${flowStage}`
    if (flowEventType) return `Worker ${flowEventType}`
    return "Worker progress"
  }
  if (step.event === "api.review.diff.latest") return "Fetch latest review"
  if (step.event === "api.review.save") return "Persist review run"
  if (step.event === "api.review.comment-publish") return "Publish comment"
  if (step.event === "api.review.comment-remove") return "Remove comment"
  if (step.event === "api.review.impact") return "Compute impact graph"
  if (step.event === "api.review.impact.get") return "Get impact graph"
  if (step.event === "api.review.impact.post") return "Build impact graph"
  if (step.event === "api.review.description") return "Generate description"

  if (step.event === "api.review.description.latest") return "Fetch latest description"
  if (step.event === "api.review.feedback") return "Submit feedback"
  if (step.event === "api.review.preferences.get") return "Get review preferences"
  if (step.event.startsWith("api.review.preferences.")) return "Update preferences"
  return step.event.replace("api.review.", "")
}

export const stepStyle = (event: string, isError: boolean) => {
  if (isError)
    return { icon: IconCircleX, iconColor: "text-red-500", borderColor: "border-red-500/30", bgColor: "bg-red-500/10" }
  if (event === "api.review.flow")
    return { icon: IconServer, iconColor: "text-cyan-500", borderColor: "border-cyan-500/30", bgColor: "bg-cyan-500/10" }
  if (event === "api.review.diff")
    return { icon: IconSearch, iconColor: "text-violet-500", borderColor: "border-violet-500/30", bgColor: "bg-violet-500/10" }
  if (event === "api.review.save")
    return { icon: IconShieldCheck, iconColor: "text-emerald-500", borderColor: "border-emerald-500/30", bgColor: "bg-emerald-500/10" }
  if (event === "api.review.comment-publish" || event === "api.review.comment-remove")
    return { icon: IconMessage, iconColor: "text-sky-500", borderColor: "border-sky-500/30", bgColor: "bg-sky-500/10" }
  if (event.startsWith("api.review.impact"))
    return { icon: IconActivity, iconColor: "text-orange-500", borderColor: "border-orange-500/30", bgColor: "bg-orange-500/10" }

  if (event.startsWith("api.review.description"))
    return { icon: IconWand, iconColor: "text-pink-500", borderColor: "border-pink-500/30", bgColor: "bg-pink-500/10" }
  if (event === "api.review.feedback")
    return { icon: IconMessage, iconColor: "text-teal-500", borderColor: "border-teal-500/30", bgColor: "bg-teal-500/10" }
  if (event.endsWith(".latest") || event.endsWith(".get"))
    return { icon: IconSearch, iconColor: "text-blue-500", borderColor: "border-blue-500/30", bgColor: "bg-blue-500/10" }
  return { icon: IconBolt, iconColor: "text-muted-foreground", borderColor: "border-border", bgColor: "bg-muted" }
}

export type FindingPreview = {
  file: string
  line: number
  severity: string
  title: string
  body: string
  confidence: number | null
}

export const toFindingPreviewList = (value: unknown): FindingPreview[] => {
  if (!Array.isArray(value)) return []
  return value
    .map((item) => {
      const record = asRecord(item)
      if (!record) return null
      const file = typeof record.file === "string" ? record.file : ""
      const line = asNumber(record.line)
      const severity = typeof record.severity === "string" ? record.severity : "n/a"
      const title = typeof record.title === "string" ? record.title : ""
      const body = typeof record.body === "string" ? record.body : ""
      const confidence = asNumber(record.confidence)
      if (!file || line === null || !title) return null
      return { file, line, severity, title, body, confidence }
    })
    .filter((item): item is FindingPreview => item !== null)
}

export const severityConfig = (severity: string) => {
  if (severity === "high")
    return { color: "text-red-600 dark:text-red-400", bg: "bg-red-500/10", label: "HIGH" }
  if (severity === "med")
    return { color: "text-amber-600 dark:text-amber-400", bg: "bg-amber-500/10", label: "MED" }
  return { color: "text-blue-600 dark:text-blue-400", bg: "bg-blue-500/10", label: "LOW" }
}

export const formatTokens = (n: number) => {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`
  return n.toLocaleString()
}

export const formatSmartDuration = (ms: number | null) => {
  if (ms === null || ms < 0) return "n/a"
  if (ms < 1000) return `${ms}ms`
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`
  const minutes = Math.floor(ms / 60_000)
  const seconds = Math.round((ms % 60_000) / 1000)
  return `${minutes}m ${seconds}s`
}

export const formatTimeOnly = (value: string | null | undefined) => {
  if (!value) return "n/a"
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) return "invalid"
  return parsed.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" })
}

export const formatPersonaModeLabel = (mode: "disabled" | "single" | "multi") => {
  if (mode === "multi") return "All personas"
  if (mode === "disabled") return "Disabled"
  return "Single persona"
}

export const formatResponsePreview = (raw: string): { cleaned: string; isJson: boolean } => {
  const cleaned = raw.replace(/^```(?:json|jsonc)?\s*\n?/i, "").replace(/\n?```\s*$/i, "")
  try {
    const parsed = JSON.parse(cleaned)
    return { cleaned: JSON.stringify(parsed, null, 2), isJson: true }
  } catch {
    const looksLikeJson = /^\s*[{[]/.test(cleaned)
    return { cleaned, isJson: looksLikeJson }
  }
}

