import * as loggerModule from '@/lib/utils/logger'

import type { RunnerScopedLogger } from '@/lib/indexing/runner/types'

export const createRunnerScopedLogger = (args: {
  method: string
  path: string
  requestId?: string
}): RunnerScopedLogger => {
  const createScopedLogger =
    loggerModule.createScopedLogger as
      | ((options: { method?: string; path?: string; requestId?: string }) => RunnerScopedLogger)
      | undefined

  if (!createScopedLogger) {
    return {
      set: () => {},
      emit: () => {},
    }
  }

  return createScopedLogger(args)
}

export const logRunnerScopedError = (
  logger: RunnerScopedLogger,
  error: unknown,
  metadata: {
    code?: string
    why?: string
    fix?: string
    details?: Record<string, unknown>
  },
) => {
  const logScopedError =
    loggerModule.logScopedError as
      | ((
          scopedLogger: RunnerScopedLogger,
          scopedError: unknown,
          scopedMetadata?: {
            code?: string
            why?: string
            fix?: string
            details?: Record<string, unknown>
          },
        ) => void)
      | undefined
  if (!logScopedError) {
    return
  }

  logScopedError(logger, error, metadata)
}

