use std::collections::{HashMap, HashSet};

use super::languages::LanguageId;
use super::query::{run_combined_query_with_tree, QueryMatch};
use super::references::{extract_references_from_tree, filter_references_to_known, range_contains};
use super::registry::{resolve_chunking_plan, ChunkKind};
use super::types::{CodeChunk, ExportEntry, ImportEntry, Range, Reference};

#[derive(Debug, Clone)]
struct CommentEntry {
  text: String,
  end_row: u32,
}

fn create_file_chunk(file_path: &str, content: &str, language: &str) -> CodeChunk {
  let line_count = count_lines(content);
  let range = Range {
    start: super::types::Position { row: 0, column: 0 },
    end: super::types::Position {
      row: line_count.saturating_sub(1),
      column: 0,
    },
  };

  CodeChunk {
    id: format!("ts:file:{file_path}"),
    kind: "file".to_string(),
    language: language.to_string(),
    file_path: file_path.to_string(),
    name: None,
    range,
    content: Some(content.to_string()),
    metadata: None,
  }
}

fn count_lines(content: &str) -> u32 {
  if content.is_empty() {
    return 1;
  }
  let mut count = 1u32;
  for ch in content.chars() {
    if ch == '\n' {
      count += 1;
    }
  }
  count
}

fn extract_imports_from_matches(matches: &[QueryMatch]) -> Vec<ImportEntry> {

  let mut seen_modules: HashMap<String, ImportEntry> = HashMap::new();

  for match_entry in matches {
    let source_capture = match_entry
      .captures
      .iter()
      .find(|capture| capture.name == "import.source");
    let Some(source_capture) = source_capture else {
      continue;
    };
    if source_capture.text.is_empty() {
      continue;
    }

    let module_name = source_capture.text.clone();
    let entry = seen_modules
      .entry(module_name.clone())
      .or_insert(ImportEntry {
        module: module_name,
        symbols: None,
        is_type_only: None,
      });

    let mut symbols = entry.symbols.clone().unwrap_or_default();

    if let Some(default_capture) = match_entry
      .captures
      .iter()
      .find(|capture| capture.name == "import.default")
    {
      if !default_capture.text.is_empty() {
        symbols.push(default_capture.text.clone());
      }
    }

    if let Some(namespace_capture) = match_entry
      .captures
      .iter()
      .find(|capture| capture.name == "import.namespace")
    {
      if !namespace_capture.text.is_empty() {
        symbols.push(format!("* as {}", namespace_capture.text));
      }
    }

    for named_capture in match_entry
      .captures
      .iter()
      .filter(|capture| capture.name == "import.named")
    {
      if !named_capture.text.is_empty() {
        symbols.push(named_capture.text.clone());
      }
    }

    if !symbols.is_empty() {
      entry.symbols = Some(symbols);
    }
  }

  seen_modules.into_values().collect()
}

fn extract_exports_from_matches(matches: &[QueryMatch]) -> Vec<ExportEntry> {
  let mut exports_list = Vec::new();

  for match_entry in matches {
    let name_capture = match_entry
      .captures
      .iter()
      .find(|capture| capture.name == "export.name");
    let default_capture = match_entry
      .captures
      .iter()
      .find(|capture| capture.name == "export.default");
    let alias_capture = match_entry
      .captures
      .iter()
      .find(|capture| capture.name == "export.alias_name");

    if default_capture.is_some() {
      exports_list.push(ExportEntry {
        symbol: None,
        is_default: Some(true),
      });
    } else if let Some(alias_capture) = alias_capture {
      exports_list.push(ExportEntry {
        symbol: Some(alias_capture.text.clone()),
        is_default: None,
      });
    } else if let Some(name_capture) = name_capture {
      exports_list.push(ExportEntry {
        symbol: Some(name_capture.text.clone()),
        is_default: None,
      });
    }
  }

  exports_list
}

fn build_comment_index(matches: &[QueryMatch]) -> Vec<CommentEntry> {
  let mut comments = Vec::new();
  for match_entry in matches {
    let Some(comment_capture) = match_entry.captures.first() else {
      continue;
    };
    if comment_capture.text.is_empty() {
      continue;
    }
    comments.push(CommentEntry {
      text: comment_capture.text.clone(),
      end_row: comment_capture.range.end.row,
    });
  }
  comments.sort_by_key(|entry| entry.end_row);
  comments
}

fn find_leading_docstring(comments: &[CommentEntry], start_row: u32) -> Option<String> {
  if start_row == 0 || comments.is_empty() {
    return None;
  }

  let max_end = start_row - 1;
  let mut left = 0;
  let mut right = comments.len().saturating_sub(1);
  let mut idx: Option<usize> = None;

  while left <= right {
    let mid = (left + right) / 2;
    if comments[mid].end_row <= max_end {
      idx = Some(mid);
      left = mid + 1;
    } else if mid == 0 {
      break;
    } else {
      right = mid - 1;
    }
  }

  let idx = idx?;
  let candidate = &comments[idx];
  let gap = start_row
    .saturating_sub(candidate.end_row)
    .saturating_sub(1);
  if gap <= 1 {
    return Some(candidate.text.clone());
  }

  None
}

fn process_chunk_matches(
  matches: &[QueryMatch],
  file_path: &str,
  language_label: &str,
  kind: &str,
  seen_node_ids: &mut HashSet<u64>,
  id_counters: &mut HashMap<String, u32>,
) -> Vec<CodeChunk> {
  let mut chunks = Vec::new();
  let capture_prefix = format!("chunk.{kind}");

  for match_entry in matches {
    let name_capture = match_entry
      .captures
      .iter()
      .find(|capture| capture.name.ends_with("symbol.name"));
    let node_capture = match_entry
      .captures
      .iter()
      .find(|capture| capture.name.starts_with(&capture_prefix));

    let Some(node_capture) = node_capture else {
      continue;
    };

    if seen_node_ids.contains(&node_capture.node_id) {
      continue;
    }
    seen_node_ids.insert(node_capture.node_id);

    let raw_name = name_capture.and_then(|capture| {
      let trimmed = capture.text.trim();
      if trimmed.is_empty() {
        None
      } else {
        Some(trimmed.to_string())
      }
    });

    let name_for_id = raw_name.clone().unwrap_or_else(|| "anonymous".to_string());
    let counter_key = format!("{kind}:{name_for_id}");
    let ordinal = id_counters.entry(counter_key).or_insert(0);
    let ordinal_value = *ordinal;
    *ordinal += 1;

    chunks.push(CodeChunk {
      id: format!("ts:{kind}:{file_path}:{name_for_id}:{ordinal_value}"),
      kind: kind.to_string(),
      language: language_label.to_string(),
      file_path: file_path.to_string(),
      name: raw_name,
      range: node_capture.range,
      content: Some(node_capture.text.clone()),
      metadata: None,
    });
  }

  chunks
}

  let mut buckets = MatchBuckets::default();

  for match_entry in matches {
    let mut has_func = false;
    let mut has_class = false;
    let mut has_type = false;
    let mut has_var = false;
    let mut has_import = false;
    let mut has_export = false;
    let mut has_comment = false;

    for capture in &match_entry.captures {
      let name = capture.name.as_str();
      if !has_func && name.starts_with("chunk.function") {
        has_func = true;
      }
      if !has_class && name.starts_with("chunk.class") {
        has_class = true;
      }
      if !has_type && name.starts_with("chunk.type") {
        has_type = true;
      }
      if !has_var && name.starts_with("chunk.variable") {
        has_var = true;
      }
      if !has_import && name.starts_with("import.") {
        has_import = true;
      }
      if !has_export && name.starts_with("export.") {
        has_export = true;
      }
      if !has_comment && name.starts_with("comment.") {
        has_comment = true;
      }
    }

    if has_func {
      buckets.functions.push(match_entry.clone());
    }
    if has_class {
      buckets.classes.push(match_entry.clone());
    }
    if has_type {
      buckets.types.push(match_entry.clone());
    }
    if has_var {
      buckets.variables.push(match_entry.clone());
    }
    if has_import {
      buckets.imports.push(match_entry.clone());
    }
    if has_export {
      buckets.exports.push(match_entry.clone());
    }
    if has_comment {
      buckets.comments.push(match_entry);
    }
  }

  buckets
}

#[derive(Default)]

struct MatchBuckets {
  functions: Vec<QueryMatch>,
  classes: Vec<QueryMatch>,
  types: Vec<QueryMatch>,
  variables: Vec<QueryMatch>,
  imports: Vec<QueryMatch>,
  exports: Vec<QueryMatch>,
  comments: Vec<QueryMatch>,
}

fn attach_file_metadata(chunk: &mut CodeChunk, imports: &[ImportEntry], exports: &[ExportEntry]) {
  if imports.is_empty() && exports.is_empty() {
    return;
  }
  let mut metadata = chunk.metadata.take().unwrap_or_default();
  if !imports.is_empty() {
    metadata.imports = Some(imports.to_vec());
  }
  if !exports.is_empty() {
    metadata.exports = Some(exports.to_vec());
  }
  chunk.metadata = Some(metadata);
}

fn attach_references(
  chunk: &mut CodeChunk,
  references: Vec<Reference>,
  exported_names: &HashSet<String>,
  imports: &[ImportEntry],
  exports: &[ExportEntry],
) {
  let mut metadata = chunk.metadata.take().unwrap_or_default();
  if !references.is_empty() {
    metadata.references = Some(references);
  }
  if !imports.is_empty() {
    metadata.imports = Some(imports.to_vec());
  }
  if !exports.is_empty() {
    metadata.exports = Some(exports.to_vec());
  }

  let is_exported = chunk
    .name
    .as_ref()
    .map(|name| exported_names.contains(name))
    .unwrap_or(false);
  if is_exported {
    metadata.exported = Some(true);
  }

  chunk.metadata = Some(metadata);
}

fn imported_symbol_names(imports: &[ImportEntry]) -> HashSet<String> {
  let mut names = HashSet::new();
  for entry in imports {
    let Some(symbols) = &entry.symbols else {
      continue;
    };
    for symbol in symbols {
      let trimmed = symbol.trim();
      if trimmed.is_empty() {
        continue;
      }

      if let Some(alias) = trimmed.strip_prefix("* as ") {
        let alias = alias.trim();
        if !alias.is_empty() {
          names.insert(alias.to_string());
        }
        continue;
      }

      if let Some((_, local_name)) = trimmed.rsplit_once(" as ") {
        let local_name = local_name.trim();
        if !local_name.is_empty() {
          names.insert(local_name.to_string());
        }
        continue;
      }

      names.insert(trimmed.to_string());
    }
  }
  names
}

pub struct TreeSitterChunker;

impl TreeSitterChunker {
  pub fn chunk_file(
    file_path: &str,
    content: &str,
    language: Option<LanguageId>,
  ) -> Vec<CodeChunk> {
    let language_name = language.map(LanguageId::as_str);
    Self::chunk_file_with_language(file_path, content, language_name)
  }

  pub fn chunk_file_with_language(
    file_path: &str,
    content: &str,
    language: Option<&str>,
  ) -> Vec<CodeChunk> {
    let Some(plan) = resolve_chunking_plan(file_path, language) else {
      return vec![create_file_chunk(file_path, content, "unknown")];
    };

    if plan.query_texts.is_empty() {
      return vec![create_file_chunk(
        file_path,
        content,
        plan.language_label.as_str(),
      )];
    }

let Some(output) = run_combined_query_with_tree(&plan.language, content, &plan.query_texts)
else {
  return vec![create_file_chunk(
    file_path,
    content,
    plan.language_label.as_str(),
  )];
};

let buckets = split_matches(output.matches);
let mut chunks = Vec::new();
let mut seen_node_ids = HashSet::new();
let mut id_counters = HashMap::new();

for kind in &plan.chunk_kinds {
  let matches = match kind {
    ChunkKind::Function => &buckets.functions,
    ChunkKind::Class => &buckets.classes,
    ChunkKind::Type => &buckets.types,
    ChunkKind::Variable => &buckets.variables,
  };
  chunks.extend(process_chunk_matches(
    matches,
    file_path,
    plan.language_label.as_str(),
    kind.as_str(),
    &mut seen_node_ids,
    &mut id_counters,
  ));
}

let file_imports = extract_imports_from_matches(&buckets.imports);
let file_exports = extract_exports_from_matches(&buckets.exports);

if chunks.is_empty() {
  let mut file_chunk = create_file_chunk(file_path, content, plan.language_label.as_str());
  attach_file_metadata(&mut file_chunk, &file_imports, &file_exports);
  return vec![file_chunk];
}

let exported_names: HashSet<String> = file_exports
  .iter()
  .filter_map(|entry| entry.symbol.clone())
  .filter(|name| !name.is_empty())
  .collect();

let all_refs = extract_references_from_tree(content, &output.tree);
let comment_index = build_comment_index(&buckets.comments);

    let mut reference_symbols: HashSet<String> = chunks
      .iter()
      .filter_map(|chunk| chunk.name.clone())
      .filter(|name| !name.is_empty())
      .collect();
    reference_symbols.extend(imported_symbol_names(&file_imports));

    for chunk in &mut chunks {
      let refs_in_chunk: Vec<Reference> = all_refs
        .iter()
        .filter(|reference| range_contains(chunk.range, reference.range))
        .cloned()
        .collect();

      let filtered_refs = filter_references_to_known(refs_in_chunk, &reference_symbols);
      let docstring = find_leading_docstring(&comment_index, chunk.range.start.row);

      if let Some(docstring) = docstring {
        let mut metadata = chunk.metadata.take().unwrap_or_default();
        metadata.docstring = Some(docstring);
        chunk.metadata = Some(metadata);
      }

      attach_references(
        chunk,
        filtered_refs,
        &exported_names,
        &file_imports,
        &file_exports,
      );
    }

    chunks
  }
}

#[cfg(test)]
mod tests {
  use std::collections::HashSet;

  use super::*;
  use crate::core::parse::languages::{language_for, LanguageId};
  use crate::core::parse::queries::query_text;
  use crate::core::parse::query::run_combined_query_with_tree;

  #[test]

  fn chunks_javascript_function() {
    let source = "import { foo } from './foo'\n\nfunction bar() {\n  foo()\n}\n";
    let chunks =
      TreeSitterChunker::chunk_file("src/example.js", source, Some(LanguageId::JavaScript));

    let function_chunk = chunks
      .iter()
      .find(|chunk| chunk.kind == "function")
      .expect("function chunk");
    let metadata = function_chunk.metadata.as_ref().expect("metadata");
    assert!(metadata
      .imports
      .as_ref()
      .map(|list| !list.is_empty())
      .unwrap_or(false));
  }

  #[test]
  fn keeps_imported_call_references_for_graph_resolution() {
    let source = r#"
import { add } from "./util.js";

export function run(): number {
  return add(2, 3);
}
"#;

    let chunks =
      TreeSitterChunker::chunk_file("src/index.ts", source, Some(LanguageId::TypeScript));
    let run_chunk = chunks
      .iter()
      .find(|chunk| chunk.name.as_deref() == Some("run"))
      .expect("run chunk");
    let references = run_chunk
      .metadata
      .as_ref()
      .and_then(|meta| meta.references.as_ref())
      .expect("references");
    assert!(
      references.iter().any(|reference| reference.name == "add"),
      "expected imported callee reference to be preserved for graph linking"
    );
  }

  #[test]

  fn typescript_variable_query_matches() {
    let source = "export const value = foo();\\n";
    let query = query_text(LanguageId::TypeScript, "variables")
      .expect("variables query")
      .to_string();
    let language = language_for(LanguageId::TypeScript);
    let output = run_combined_query_with_tree(&language, source, &[query]).expect("query");

    let mut has_variable = false;
    for match_entry in output.matches {
      for capture in match_entry.captures {
        if capture.name.starts_with("chunk.variable") {
          has_variable = true;
        }
      }
    }
    assert!(has_variable);
  }

  #[test]
  fn built_in_languages_emit_core_symbol_kinds() {
    let fixtures = vec![
      (
        "src/sample.js",
        r#"
