import { and, desc, eq, inArray } from 'drizzle-orm'

import { db } from '@/lib/db'
import { indexBranchStates, indexJobs, indexRuns } from '@/lib/db/schema'
import { getMergeRequestDetails } from '@/lib/gitlab/client'
import { decryptIntegrationToken, getIntegrationById } from '@/lib/gitlab/service'
import { enqueuePlanJob } from '@/lib/indexing/job-queue'
import type { EnsureMergeRequestSourceBranchIndexingDeps } from '@/lib/indexing/mr-auto-index-types'
import { isEnvEnabled } from '@/lib/indexing/mr-auto-index-utils'
import { createImpactGraphBackend } from '@/lib/review/impact-graph-backend'

const ACTIVE_PLAN_JOB_STATUSES = ['pending', 'processing'] as const
const ACTIVE_RUN_STATUSES = ['planned', 'ingesting', 'indexing'] as const

export const createDefaultEnsureDeps = (): EnsureMergeRequestSourceBranchIndexingDeps => ({
  loadIntegration: async (integrationId) => {
    const integration = await getIntegrationById(integrationId)
    if (!integration) {
      return null
    }

    return {
      instanceUrl: integration.instanceUrl,
      projectId: integration.projectId,
      token: decryptIntegrationToken(integration),
    }
  },
  fetchMergeRequestDetails: async ({ instanceUrl, token, projectId, mergeRequestIid }) =>
    getMergeRequestDetails(instanceUrl, token, projectId, mergeRequestIid),

getLatestBranchState: async ({ integrationId, branch, configHash }) => {
  // Schema enforces one row per (integrationId, branch, configHash).
  const row = await db.query.indexBranchStates.findFirst({
    where: and(
      eq(indexBranchStates.integrationId, integrationId),
      eq(indexBranchStates.branch, branch),
      eq(indexBranchStates.configHash, configHash),
    ),
    columns: {
      id: true,
      configHash: true,
      lastReadySha: true,
      servingUpdatedAt: true,
      updatedAt: true,
    },
  })

  if (!row) {
    return null
  }

  return {
    id: row.id,
    configHash: row.configHash,
    lastReadySha: row.lastReadySha,
    updatedAt: row.updatedAt,
    servingUpdatedAt: row.servingUpdatedAt,
  }
},
getInFlightPlanJob: async ({ integrationId, branch, configHash }) => {
  const row = await db.query.indexJobs.findFirst({
    where: and(
      eq(indexJobs.integrationId, integrationId),
      eq(indexJobs.jobType, 'plan'),
      eq(indexJobs.branch, branch),
      eq(indexJobs.configHash, configHash),
      inArray(indexJobs.status, ACTIVE_PLAN_JOB_STATUSES),
    ),
    orderBy: [desc(indexJobs.updatedAt)],
    columns: {
      id: true,
      debounceKey: true,
      status: true,
    },
  })

  if (!row || (row.status !== 'pending' && row.status !== 'processing')) {
    return null
  }

  return {
    id: row.id,
    debounceKey: row.debounceKey,
    status: row.status,
  }
},

  getInFlightRunForHead: async ({ branchStateId, headSha }) => {
    const row = await db.query.indexRuns.findFirst({
      where: and(
        eq(indexRuns.branchStateId, branchStateId),
        eq(indexRuns.headSha, headSha),
        inArray(indexRuns.status, ACTIVE_RUN_STATUSES),
      ),
      orderBy: [desc(indexRuns.updatedAt)],
      columns: {
        id: true,
        status: true,
      },
    })

    if (!row || (row.status !== 'planned' && row.status !== 'ingesting' && row.status !== 'indexing')) {
      return null
    }

    return {
      id: row.id,
      status: row.status,
    }
  },
  enqueuePlanJob: async ({
    integrationId,
    branch,
    configHash,
    hintedHeadSha,
    forceReplan,
    coalesceInFlight,
  }) =>
    enqueuePlanJob({
      integrationId,
      branch,
      configHash,
      hintedHeadSha,
      forceReplan,
      coalesceInFlight,
    }),
  isBranchGraphReady: async ({ integrationId, branch }) => {
    const backend = createImpactGraphBackend()
    const snapshot = await backend.resolveSnapshot({
      integrationId,
      sourceBranch: branch,
    })
    return snapshot.status === 'ready'
  },
  isTriggerEnabled: (trigger) => {
    if (trigger === 'webhook') {
      return isEnvEnabled(process.env.INDEXER_AUTO_INDEX_MR_WEBHOOK_ENABLED)
    }

    if (trigger === 'lazy') {
      return isEnvEnabled(process.env.INDEXER_AUTO_INDEX_MR_LAZY_ENABLED)
    }

    return isEnvEnabled(process.env.INDEXER_MR_PREWARM_ENABLED)
  },
})

