function hasNativeBinding(): boolean {
  if (process.env.NAPI_RS_NATIVE_LIBRARY_PATH) {
    return true
  }
  try {
    const roots = [packageRoot, path.join(packageRoot, 'native')]
    return roots.some((dir) => {
      try {
        return fs.readdirSync(dir).some((entry) => entry.endsWith('.node'))
      } catch {
        return false
      }
    })
  } catch {
    return false
  }
}

const testWithBinding = hasNativeBinding() ? test : test.skip

function startEmbeddingServer(dimension: number) {
  const server = http.createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/embeddings') {
      res.statusCode = 404
      res.end('not found')
      return
    }

    const body = await new Promise<string>((resolve, reject) => {
      let raw = ''
      req.on('data', (chunk) => (raw += String(chunk)))
      req.on('end', () => resolve(raw))
      req.on('error', reject)
    })

    let inputCount = 1
    try {
      const parsed = JSON.parse(body) as { input?: unknown }
      inputCount = Array.isArray(parsed?.input) ? parsed.input.length : 1
    } catch {
      inputCount = 1
    }

    const embedding = Array.from({ length: dimension }, (_, idx) => (idx + 1) / 10)
    const data = Array.from({ length: inputCount }, () => ({ embedding }))

    res.statusCode = 200
    res.setHeader('content-type', 'application/json')
    res.end(JSON.stringify({ data }))
  })

  return new Promise<{ url: string; close: () => Promise<void> }>((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const address = server.address()
      const port = typeof address === 'object' && address ? address.port : 0
      resolve({
        url: `http://127.0.0.1:${port}`,
        close: () => new Promise<void>((done) => server.close(() => done())),
      })
    })
  })
}

async function loadBinding() {
  const mod = (await import('../index.js')) as any
  const binding = mod?.default ?? mod
  const indexToKiteDb = binding?.indexToKiteDb
  const searchKiteDb = binding?.searchKiteDb
  const traceCallersKiteDb = binding?.traceCallersKiteDb
  const traceImpactKiteDb = binding?.traceImpactKiteDb
  if (typeof indexToKiteDb !== 'function') throw new Error('indexToKiteDb not found')
  if (typeof searchKiteDb !== 'function') throw new Error('searchKiteDb not found')
  if (typeof traceCallersKiteDb !== 'function') throw new Error('traceCallersKiteDb not found')
  if (typeof traceImpactKiteDb !== 'function') throw new Error('traceImpactKiteDb not found')
  return { indexToKiteDb, searchKiteDb, traceCallersKiteDb, traceImpactKiteDb }
}

testWithBinding('kitedb: indexToKiteDb + searchKiteDb', async (t) => {
