import { afterEach, describe, expect, mock, test } from "bun:test";

const loadCleanupModule = async (rowsByCall: Array<{ rows: Array<Record<string, unknown>> }>) => {
  const execute = mock(async () => rowsByCall.shift() ?? { rows: [] });
  const transaction = mock(async (callback: (tx: { execute: typeof execute }) => Promise<unknown>) =>
    callback({ execute }),
  );
  mock.module("@/lib/db", () => ({
    db: {
      execute,
      transaction,
    },
  }));

  const logRetentionModule = await import(
    `./log-retention?cacheBust=${Math.random().toString(36).slice(2)}`,
  );
  return {
    cleanupAppLogs: logRetentionModule.cleanupAppLogs as (options?: {
      retentionDays?: number;
      maxRows?: number;
      deleteLimit?: number;
    }) => Promise<{
      lock: "acquired" | "skipped";
      deletedByAge: number;
      deletedByCap: number;
      rowsBefore: number | null;
      rowsAfter: number | null;
    }>,
  };
};

describe("cleanupAppLogs", () => {
  afterEach(() => {
    mock.restore();
  });

test("applies age and cap policy in one cleanup run", async () => {
  const { cleanupAppLogs } = await loadCleanupModule([
    { rows: [{ acquired: true }] },
    { rows: [{ count: 10 }] },
    { rows: [{ id: "age-1" }, { id: "age-2" }, { id: "age-3" }] },
    { rows: [{ id: "cap-1" }, { id: "cap-2" }] },
    { rows: [{ count: 5 }] },
  ]);

  const summary = await cleanupAppLogs({
    retentionDays: 30,
    maxRows: 5,
    deleteLimit: 10,
  });

  expect(summary.rowsBefore).toBe(10);
  expect(summary.deletedByAge).toBe(3);
  expect(summary.deletedByCap).toBe(2);
  expect(summary.rowsAfter).toBe(5);
});

test("enforces deleteLimit while capping rows", async () => {
  const { cleanupAppLogs } = await loadCleanupModule([
    { rows: [{ acquired: true }] },
    { rows: [{ count: 100 }] },
    { rows: [] },
    { rows: [{ id: "cap-1" }, { id: "cap-2" }, { id: "cap-3" }, { id: "cap-4" }] },
    { rows: [{ count: 96 }] },
  ]);

  const summary = await cleanupAppLogs({
    retentionDays: 30,
    maxRows: 10,
    deleteLimit: 4,
  });

  expect(summary.deletedByAge).toBe(0);
  expect(summary.deletedByCap).toBe(4);
  expect(summary.rowsAfter).toBe(96);
});

  test("skips cleanup when advisory lock is unavailable", async () => {
    const { cleanupAppLogs } = await loadCleanupModule([{ rows: [{ acquired: false }] }]);

    const summary = await cleanupAppLogs();

    expect(summary.lock).toBe("skipped");
    expect(summary.rowsBefore).toBeNull();
    expect(summary.rowsAfter).toBeNull();
    expect(summary.deletedByAge).toBe(0);
    expect(summary.deletedByCap).toBe(0);
  });

  test("rejects invalid option values", async () => {
    const { cleanupAppLogs } = await loadCleanupModule([]);

    await expect(
      cleanupAppLogs({
        deleteLimit: 0,
      }),
    ).rejects.toThrow("Invalid deleteLimit. Expected a positive integer.");
  });
});

