class JiraClientError extends Error {
  status: number

  constructor(message: string, status = 502) {
    super(message)
    this.status = status
  }
}

type JiraCredentialsInput = {
  baseUrl: string
  email: string
  token: string
}

const requireTrimmed = (value: string, fieldLabel: string) => {
  const normalized = value.trim()
  if (!normalized) {
    throw new JiraClientError(`${fieldLabel} is required.`, 400)
  }
  return normalized
}

const normalizePositiveInteger = (
  value: number,
  fieldLabel: string,
) => {
  if (!Number.isInteger(value) || value <= 0) {
    throw new JiraClientError(`${fieldLabel} must be a positive integer.`, 400)
  }
  return value
}

const resolveJiraConfig = async ({
  baseUrl,
  email,
  token,
}: JiraCredentialsInput): Promise<JiraRequestConfig> => {
  const normalizedBaseUrl = normalizeJiraInstanceUrl(baseUrl)
  // DNS check blocks domains that resolve to private ranges, not only literal private IP inputs.
  await assertJiraInstancePublicHost(normalizedBaseUrl)

  return {
    baseUrl: normalizedBaseUrl,
    email: requireTrimmed(email, "Jira email"),
    token: requireTrimmed(token, "Jira API token"),
  }
}

const createJiraHeaders = (email: string, token: string): HeadersInit => ({
  Authorization: `Basic ${Buffer.from(`${email}:${token}`, "utf8").toString("base64")}`,
  Accept: "application/json",
  "Content-Type": "application/json",
  "User-Agent": "argus-app",
})

const parseJiraErrorText = async (response: Response) => {
  const text = await response.text()
  if (!text) {
    return ""
  }

  try {
    const parsed = JSON.parse(text) as {
      errorMessages?: string[]
      message?: string
      errors?: Record<string, string>
    }
    if (Array.isArray(parsed.errorMessages) && parsed.errorMessages.length > 0) {
      return parsed.errorMessages.join("; ")
    }
    if (parsed.message) {
      return parsed.message
    }
    if (parsed.errors && Object.keys(parsed.errors).length > 0) {
      return Object.values(parsed.errors).join("; ")
    }
  } catch {
    return text.slice(0, 400)
  }

  return text.slice(0, 400)
}

const getJiraResponse = async (
  config: JiraRequestConfig,
  path: string,
) => {
  const response = await fetch(`${config.baseUrl}${path}`, {
    method: "GET",
    headers: createJiraHeaders(config.email, config.token),
  })

  return response
}

const throwForJiraResponseError = async (
  response: Response,
  context: string,
) => {
  if (response.status === 401) {
    throw new JiraClientError("Invalid Jira email/token.", 401)
  }
  if (response.status === 403) {
    throw new JiraClientError("Jira denied access. Check token permissions.", 403)
  }

  const details = await parseJiraErrorText(response)
  throw new JiraClientError(
    `${context} (${response.status}): ${details || response.statusText}`,
    response.status,
  )
}

const getJiraJson = async <T>(
  config: JiraRequestConfig,
  path: string,
) => {
  const response = await getJiraResponse(config, path)
  if (!response.ok) {
    await throwForJiraResponseError(response, "Jira request failed")
  }

  return await response.json() as T
}

const getRestApiJson = async <T>(
  config: JiraRequestConfig,
  apiPathWithQuery: string,
) => {
  // This integration intentionally targets Jira REST API v3 only.
  const response = await getJiraResponse(config, `/rest/api/3${apiPathWithQuery}`)
  if (!response.ok) {
    if (response.status === 404) {
      throw new JiraClientError(
        "Jira REST API v3 endpoint not found. This integration requires Jira REST API v3.",
        404,
      )
    }
    await throwForJiraResponseError(response, "Jira REST API request failed")
  }
  return await response.json() as T
}

export const validateJiraCredentials = async ({
