const listJiraBoardsByConfig = async (
  config: JiraRequestConfig,
  maxResults = 100,
) => {
  const normalizedMaxResults = normalizePositiveInteger(maxResults, "maxResults")

  const boards: JiraBoardSummary[] = []
  let startAt = 0
  let isLast = false

  while (!isLast && boards.length < normalizedMaxResults) {
    const response = await getJiraJson<JiraAgilePagedResponse<JiraBoard>>(
      config,
      `/rest/agile/1.0/board?startAt=${startAt}&maxResults=${Math.min(50, normalizedMaxResults - boards.length)}`,
    )

    boards.push(...response.values.map(normalizeBoard))
    isLast = response.isLast
    startAt += response.values.length

    if (response.values.length === 0) {
      break
    }
  }

  return boards
}

