export const listJiraSprints = async ({
  baseUrl,
  email,
  token,
  boardId,
  maxResults = 100,
}: {
  baseUrl: string
  email: string
  token: string
  boardId: number
  maxResults?: number
}) => {
  const config = await resolveJiraConfig({ baseUrl, email, token })
  const normalizedMaxResults = normalizePositiveInteger(maxResults, "maxResults")

  const sprints: JiraSprintSummary[] = []
  let startAt = 0
  let isLast = false

  while (!isLast && sprints.length < normalizedMaxResults) {
    const response = await getJiraJson<JiraAgilePagedResponse<JiraSprint>>(
      config,
      `/rest/agile/1.0/board/${boardId}/sprint?startAt=${startAt}&maxResults=${Math.min(50, normalizedMaxResults - sprints.length)}`,
    )

    sprints.push(...response.values.map(normalizeSprint))
    isLast = response.isLast
    startAt += response.values.length

    if (response.values.length === 0) {
      break
    }
  }

  // Jira state values are lexical strings; explicit ranking keeps UI ordering stable.
  const stateOrder: Record<string, number> = {
    active: 0,
    future: 1,
    closed: 2,
  }

  return sprints.sort((a, b) => {
    const aOrder = stateOrder[a.state] ?? 3
    const bOrder = stateOrder[b.state] ?? 3
    return aOrder - bOrder
  })
}

export const listJiraIssuesForSprint = async ({
  baseUrl,
  email,
  token,
  sprintId,
  maxResults = 200,
}: {
  baseUrl: string
  email: string
  token: string
  sprintId: number
  maxResults?: number
}) => {
  const config = await resolveJiraConfig({ baseUrl, email, token })
  const normalizedMaxResults = normalizePositiveInteger(maxResults, "maxResults")

  const issues: JiraIssueSummary[] = []
  let startAt = 0

  while (issues.length < normalizedMaxResults) {
    const jql = encodeURIComponent(`sprint = ${sprintId} ORDER BY created DESC`)
    const response = await getRestApiJson<JiraSearchResponse>(
      config,
      `/search?jql=${jql}&startAt=${startAt}&maxResults=${Math.min(50, normalizedMaxResults - issues.length)}&fields=summary,status,assignee,reporter,priority,issuetype,project,created,updated,labels`,
    )

    issues.push(...response.issues.map(normalizeIssue))

    if (startAt + response.issues.length >= response.total || response.issues.length === 0) {
      break
    }
    startAt += response.issues.length
  }

  return issues
}

