      return
    }

    const normalizedInstanceUrl = instanceUrl.trim().replace(/\/+$/, "")
    const normalizedProjectId = projectId.trim()
    const normalizedMergeRequestIid = mergeRequestIid.trim()
    if (!normalizedInstanceUrl || !normalizedProjectId || !normalizedMergeRequestIid) {
      resetReviewSessionState("Missing merge request scope.")
      return
    }

    reviewStartInFlightRef.current = true

    try {
      const force = options?.force === true
