      instanceUrl: normalizedInstanceUrl,
      projectId: normalizedProjectId,
      mergeRequestIid: normalizedMergeRequestIid,
      integrationId,
      force,
    }),
  })

  const parsedPayload = await parseJsonResponse(response)
  payload = parsedPayload.ok
    ? (parsedPayload.value as ReviewRunEnqueuePayload)
    : null
  if (!response.ok) {
    throw new Error(getReviewErrorMessage(payload))
  }

  dedupeReason = normalizeReviewRunDedupeReason(payload?.data?.dedupeReason)
  const deduped = payload?.data?.deduped === true
  if (deduped && dedupeReason === "same_patch_success" && !force) {
    setPendingForceReviewPrompt({
      patchText,
      options,
    })
    return
  }
  break
}

const traceId = String(payload?.data?.traceId ?? "").trim()
if (!traceId) {
  throw new Error("Review enqueue did not return a trace ID.")
}
const queuedPersonaMode = toReviewPersonaMode(payload?.data?.personaMode)
const queuedPersona = toReviewPersona(payload?.data?.persona)

  appendReviewRunEvent(
    initialStage,
    payload?.data?.deduped
      ? dedupeReason === "same_patch_success"
        ? "Reused previous completed review (unchanged diff)."
        : "Resumed active review run."
      : "Review run queued in background worker.",
  )

  const streamResult = await connectReviewStream(traceId)
  if (streamResult === "done") {
    await fetchLatestSavedReview({
      preserveRun: true,
    }).catch(() => null)
  } else if (streamResult === "failed") {
    setReviewRun((current) => ({
      ...current,
      stage: "failed",
      finishedAt: current.finishedAt ?? Date.now(),
    }))
  }
} catch (error) {
  const message = getReviewErrorMessage(error)
  setReviewSummary("")
  setReviewError(message)
  setReviewRun((current) => ({
    ...current,
    stage: "failed",
    finishedAt: Date.now(),
    failedFiles: Array.from(new Set([...current.failedFiles, ...current.currentBatchFiles])),
    currentBatchFiles: [],
  }))
  appendReviewRunEvent("failed", message)
} finally {
  reviewStartInFlightRef.current = false
  setIsReviewing(false)
}

  if (isAbortingReview) {
    return
  }

  const traceId =
    getCurrentTraceId().trim() || reviewTraceId?.trim() || readStoredTraceId().trim()
  closeReviewStream()
  setIsReviewing(false)

  if (!traceId) {
    clearActiveTraceId()
    setCurrentTraceId(null)
    return
  }

  setIsAbortingReview(true)
  try {
    const response = await fetch("/api/review/diff/cancel", {
      method: "POST",
      headers: buildRequestHeaders({
        "content-type": "application/json",
      }),
      body: JSON.stringify({ traceId }),
    })
    const parsedPayload = await parseJsonResponse(response)
    const payload = parsedPayload.ok
      ? (parsedPayload.value as {
          data?: {
            cancelled?: unknown
          }
          error?: unknown
        })
      : null
    if (!response.ok) {
      throw new Error(getReviewErrorMessage(payload))
    }

    if (payload?.data?.cancelled === true) {
      setReviewError("AI review cancelled.")
      setReviewRun((current) => ({
        ...current,
        stage: current.stage === "done" ? "done" : "failed",
        finishedAt: Date.now(),
        currentBatchFiles: [],
      }))
      appendReviewRunEvent("failed", "AI review cancelled by user.")
    }
  } catch (error) {
    setReviewError(getReviewErrorMessage(error))
  } finally {
    clearActiveTraceId()
    setCurrentTraceId(null)
    closeReviewStream()
    setIsReviewing(false)
    setIsAbortingReview(false)
  }
}, [

  appendReviewRunEvent,
  buildRequestHeaders,
  clearActiveTraceId,
  closeReviewStream,
  getCurrentTraceId,
  isAbortingReview,
  readStoredTraceId,
  reviewTraceId,
  setCurrentTraceId,
])

