const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..')
const fixtureRoot = path.join(__dirname, '..', 'fixtures', 'sample-repo')

function startEmbeddingServer(dimension: number) {
  const server = http.createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/embeddings') {
      res.statusCode = 404
      res.end('not found')
      return
    }

    const body = await new Promise<string>((resolve, reject) => {
      let raw = ''
      req.on('data', (chunk) => (raw += String(chunk)))
      req.on('end', () => resolve(raw))
      req.on('error', reject)
    })

    let inputCount = 1
    try {
      const parsed = JSON.parse(body) as { input?: unknown }
      inputCount = Array.isArray(parsed?.input) ? parsed.input.length : 1
    } catch {
      inputCount = 1
    }

    const embedding = Array.from({ length: dimension }, (_, idx) => (idx + 1) / 10)
    const data = Array.from({ length: inputCount }, () => ({ embedding }))

    res.statusCode = 200
    res.setHeader('content-type', 'application/json')
    res.end(JSON.stringify({ data }))
  })

  return new Promise<{ url: string; close: () => Promise<void> }>((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const address = server.address()
      const port = typeof address === 'object' && address ? address.port : 0
      resolve({
        url: `http://127.0.0.1:${port}`,
        close: () => new Promise<void>((done) => server.close(() => done())),
      })
    })
  })
}

function resolveRustMcpBinary(): string | null {
  const exe = process.platform === 'win32' ? 'argus-search-mcp.exe' : 'argus-search-mcp'
  const debugPath = path.join(packageRoot, 'target', 'debug', exe)
  const releasePath = path.join(packageRoot, 'target', 'release', exe)
  if (fs.existsSync(debugPath)) return debugPath
  if (fs.existsSync(releasePath)) return releasePath
  return null
}

function ensureRustMcpBinary(): { path: string | null; reason?: string } {
  const cargoCheck = spawnSync('cargo', ['--version'], { cwd: packageRoot, encoding: 'utf8' })
  if (cargoCheck.status !== 0) {
    return { path: null, reason: `cargo not available: ${cargoCheck.stderr || cargoCheck.stdout}` }
  }

  const build = spawnSync('cargo', ['build', '--quiet', '--bin', 'argus-search-mcp'], {
    cwd: packageRoot,
    encoding: 'utf8',
  })
  if (build.status !== 0) {
    return { path: null, reason: `failed to build rust mcp binary:\n${build.stdout}\n${build.stderr}` }
  }

  const built = resolveRustMcpBinary()
  if (!built) {
    return { path: null, reason: 'rust mcp binary not found after build' }
  }
  return { path: built }
}

function waitForLine(child: any, predicate: (line: string) => boolean, timeoutMs = 20000): Promise<string> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('timeout waiting for line')), timeoutMs)
    let buffer = ''
    child.stdout.on('data', (chunk: Buffer) => {
      buffer += chunk.toString('utf8')
      while (true) {
        const idx = buffer.indexOf('\n')
        if (idx === -1) break
        const line = buffer.slice(0, idx).trimEnd()
        buffer = buffer.slice(idx + 1)
        if (predicate(line)) {
          clearTimeout(timer)
          resolve(line)
          return
        }
      }
    })
    child.on('error', (err: any) => {
      clearTimeout(timer)
      reject(err)
    })
  })
}

test.serial('mcp rust: semantic search + graph neighbors', async (t) => {
  const { url, close } = await startEmbeddingServer(3)
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'argus-search-mcp-rust-'))
  const configPath = path.join(tmpDir, 'argus-search.json')
  const storePath = path.join(tmpDir, 'index.kite')

  const config = {
    projectRoot: fixtureRoot,
    inputs: { paths: [fixtureRoot], include: ['*.ts'], exclude: ['node_modules', 'dist', '.git'] },
    phases: { parse: true, graph: true, vector: true, scip: false, indexPack: false },
    vector: { provider: { kind: 'http', baseUrl: url, model: 'test-model', dimension: 3 } },
  }
  fs.writeFileSync(configPath, JSON.stringify(config), 'utf8')

  const bin = ensureRustMcpBinary()

if (!bin.path) {
  t.log(bin.reason ?? 'rust mcp binary unavailable')
  t.skip()
  return
}

const binPath = bin.path
const child = spawn(
  binPath,
  ['--config', configPath, '--project-root', fixtureRoot, '--store', storePath, '--no-index-on-start'],
  { cwd: packageRoot, stdio: ['pipe', 'pipe', 'pipe'] },
)

try {
  child.stdin.write(
