import { describe, expect, test } from "bun:test"

import {
  INDEX_RUN_MODES,
  INDEX_RUN_MODE_SCHEMA,
  INDEX_RUN_STATUSES,
  INDEX_RUN_STATUS_SCHEMA,
  type IndexRunMode,
  type IndexRunStatus,
} from "@argus/contracts-indexing"

describe("indexing run contracts", () => {
  test("exposes supported run modes", () => {
    expect(INDEX_RUN_MODES).toEqual(["snapshot", "delta"])
    const mode: IndexRunMode = INDEX_RUN_MODES[0]
    expect(mode).toBe("snapshot")
  })

  test("exposes supported run statuses", () => {
    expect(INDEX_RUN_STATUSES).toEqual([
      "planned",
      "ingesting",
      "indexing",
      "cancelled",
      "ready",
      "failed",
      "superseded",
    ])
    const status: IndexRunStatus = INDEX_RUN_STATUSES[0]
    expect(status).toBe("planned")
  })

  test("exposes runtime validators for mode and status", () => {
    expect(INDEX_RUN_MODE_SCHEMA.parse("delta")).toBe("delta")
    expect(() => INDEX_RUN_MODE_SCHEMA.parse("full")).toThrow()

    expect(INDEX_RUN_STATUS_SCHEMA.parse("ready")).toBe("ready")
    expect(() => INDEX_RUN_STATUS_SCHEMA.parse("queued")).toThrow()
  })
})

const defaultRuntimeDeps: DeltaRuntimeDeps = {
  clearStagedChanges,
  loadExistingStates,
  stageDelete,
  stageUpsert,
  buildVectorChunks,
  embedVectorChunks,
}

const resolveMaxFileSizeBytes = () =>
  parsePositiveInt(process.env.INDEXER_MAX_FILE_SIZE_BYTES, DEFAULT_MAX_FILE_SIZE_BYTES)

const resolveDeltaFallbackThreshold = () =>
  parsePositiveInt(process.env.INDEXER_DELTA_FALLBACK_THRESHOLD, DEFAULT_DELTA_FALLBACK_THRESHOLD)

const toErrorMessage = (error: unknown) =>
  error instanceof Error ? error.message : 'Unexpected embedding failure.'

const wrapEmbeddingError = (args: {
  path: string
  chunks: Array<Omit<VectorChunkRecord, 'embedding'>>
  error: unknown
}) => {
  const maxChunk = args.chunks.reduce<{ chunkIndex: number; size: number } | null>(
    (largest, chunk) => {
      const size = chunk.content.length
      if (!largest || size > largest.size) {
        return {
          chunkIndex: chunk.chunkIndex,
          size,
        }
      }

      return largest
    },
    null,
  )

  const wrapped = new Error(
    `Embedding failed for ${args.path} (chunks=${args.chunks.length}, maxChunkChars=${maxChunk?.size ?? 0}): ${toErrorMessage(args.error)}`,
  )
  ;(wrapped as Error & { details?: Record<string, unknown> }).details = {
    stage: 'embedding',
    path: args.path,
    chunkCount: args.chunks.length,
    maxChunkChars: maxChunk?.size ?? 0,
    maxChunkIndex: maxChunk?.chunkIndex ?? null,
  }

  return wrapped
}

export class DeltaSnapshotFallbackError extends Error {
  readonly reason: DeltaFallbackReason

  constructor(reason: DeltaFallbackReason) {
    super(`Delta ingest fallback required: ${reason}`)
    this.reason = reason
    this.name = 'DeltaSnapshotFallbackError'
  }
}

export const runDeltaIngest = async (args: {
  run: DeltaRunContext
  source: GitLabSource
  vectorStore: VectorStore
  artifactStore: ArtifactStore
  shouldAbort?: () => Promise<void>
  onProgress?: (event: DeltaProgressEvent) => void
  workspace?: RepoWorkspace
  runtimeDeps?: Partial<DeltaRuntimeDeps>
}): Promise<DeltaResult> => {
  const runtime: DeltaRuntimeDeps = {
    ...defaultRuntimeDeps,
    ...args.runtimeDeps,
  }
  const maxFileSizeBytes = resolveMaxFileSizeBytes()

  const stats = {
    compareChanges: 0,
    filesProcessed: 0,
    filesFetched: 0,
    filesUnchanged: 0,
    filesIndexed: 0,
    filesSkipped: 0,
    filesDeleted: 0,
    chunksUpserted: 0,
    embeddingApiCalls: 0,
    embeddingFailures: 0,
    embeddingPromptTokens: 0,
    embeddingTotalTokens: 0,
    embeddingCostUsd: 0,
  }

  const manifestLines: string[] = []
  const changedFileLines: string[] = []
  const existingByPath = await runtime.loadExistingStates(args.run.branchStateId)

  const emitProgress = (event: Omit<DeltaProgressEvent, 'stage' | 'stats'>) => {
    if (!args.onProgress) {
      return
    }

    args.onProgress({
      stage: 'ingest',
      ...event,
      stats: { ...stats },
    })
  }

  await runtime.clearStagedChanges(args.run.runId)
  await args.shouldAbort?.()

if (!args.run.baseSha) {
  throw new DeltaSnapshotFallbackError('missing_base_sha')
}

const compare = await args.source.compare({
  integrationId: args.run.integrationId,
  fromSha: args.run.baseSha,
  toSha: args.run.headSha,
})
stats.compareChanges = compare.changes.length

await args.shouldAbort?.()

const fallbackReason = resolveDeltaFallbackReason({
  baseSha: args.run.baseSha,
  compare,
  maxChanges: resolveDeltaFallbackThreshold(),
})

if (fallbackReason) {
  throw new DeltaSnapshotFallbackError(fallbackReason)
}

const deltaPlan = buildDeltaIngestPlan(compare.changes)
emitProgress({
  step: 'delta_plan_ready',
  message: `Delta plan ready (${deltaPlan.upserts.length} upsert(s), ${deltaPlan.deletes.length} delete(s)).`,
  details: {
    compareChanges: compare.changes.length,
    upserts: deltaPlan.upserts.length,
    deletes: deltaPlan.deletes.length,
  },
})

for (const deletion of deltaPlan.deletes) {
  await args.shouldAbort?.()
  stats.filesProcessed += 1
  await runtime.stageDelete({
    runId: args.run.runId,
    path: deletion.path,
    skipReason: deletion.reason,
  })
  stats.filesDeleted += 1
  emitProgress({
    step: 'file_deleted',
    message: `Deleted ${deletion.path} from index state (${deletion.reason}).`,
    path: deletion.path,
    details: {
      reason: deletion.reason,
    },
  })
  manifestLines.push(
    JSON.stringify({
      path: deletion.path,
      status: 'deleted',
      reason: deletion.reason,
    }),
  )
  changedFileLines.push(
    JSON.stringify({
      path: deletion.path,
      changeType: 'deleted',
      reason: deletion.reason,
    }),
  )
}

for (const upsert of deltaPlan.upserts) {
  await args.shouldAbort?.()
  stats.filesProcessed += 1
  const file = args.workspace
    ? {
        path: upsert.path,
        content: await args.workspace.readFile(upsert.path),
      }
    : await args.source.fetchFile({
        integrationId: args.run.integrationId,
        path: upsert.path,
        ref: args.run.headSha,
      })
  stats.filesFetched += 1

  const skipReason = classifySkipReason({
    relativePath: upsert.path,
    content: file.content,
    maxFileSizeBytes,
  })

  const existing = existingByPath.get(upsert.path)

if (skipReason) {
  stats.filesSkipped += 1
  emitProgress({
    step: 'file_skipped',
    message: `Skipped ${upsert.path} (${skipReason}).`,
    path: upsert.path,
    details: {
      skipReason,
    },
  })
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: 'skipped',
      skipReason,
    }),
  )

  if (existing) {
    await runtime.stageDelete({
      runId: args.run.runId,
      path: upsert.path,
      skipReason,
    })
    stats.filesDeleted += 1
    changedFileLines.push(
      JSON.stringify({
        path: upsert.path,
        changeType: 'deleted',
        reason: skipReason,
      }),
    )
  }

  continue
}

const fileId = sha256Hex(file.content)
if (existing?.fileId === fileId) {
  stats.filesUnchanged += 1
  emitProgress({
    step: 'file_unchanged',
    message: `Unchanged ${upsert.path}; reuse existing vectors.`,
    path: upsert.path,
  })
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: 'unchanged',
    }),
  )
  continue
}

const chunks = await runtime.buildVectorChunks({
  path: upsert.path,
  content: file.content.toString('utf8'),
  configHash: args.run.configHash,
})

if (chunks.length === 0) {
  stats.filesSkipped += 1
  emitProgress({
    step: 'file_skipped',
    message: `Skipped ${upsert.path} (no chunks).`,
    path: upsert.path,
    details: {
      skipReason: 'no_chunks',
    },
  })
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: 'skipped',
      skipReason: 'no_chunks',
    }),
  )

  if (existing) {
    await runtime.stageDelete({
      runId: args.run.runId,
      path: upsert.path,
      skipReason: 'no_chunks',
    })
    stats.filesDeleted += 1
    changedFileLines.push(
      JSON.stringify({
        path: upsert.path,
        changeType: 'deleted',
        reason: 'no_chunks',
      }),
    )
  }
  continue
}

let embeddedChunks: VectorChunkRecord[]
try {
  embeddedChunks = await runtime.embedVectorChunks(chunks, {
    onTelemetry: (telemetry) => {
      stats.embeddingApiCalls += telemetry.requestCount
      stats.embeddingFailures += telemetry.failureCount
      stats.embeddingPromptTokens += telemetry.promptTokens
      stats.embeddingTotalTokens += telemetry.totalTokens
      stats.embeddingCostUsd += telemetry.costUsd ?? 0
    },
  })
} catch (error) {
  throw wrapEmbeddingError({
    path: upsert.path,
    chunks,
    error,
  })
}

  await args.vectorStore.upsertChunks({
    branchStateId: args.run.branchStateId,
    runId: args.run.runId,
    path: upsert.path,
    fileId,
    chunks: embeddedChunks,
  })

  await runtime.stageUpsert({
    runId: args.run.runId,
    path: upsert.path,
    fileId,
    sizeBytes: file.content.length,
  })

  stats.filesIndexed += 1
  stats.chunksUpserted += embeddedChunks.length
  emitProgress({
    step: 'file_indexed',
    message: `Indexed ${upsert.path} (${embeddedChunks.length} chunk(s)).`,
    path: upsert.path,
    details: {
      chunks: embeddedChunks.length,
      changeType: upsert.changeType,
    },
  })
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: existing ? 'changed' : 'new',
      chunks: embeddedChunks.length,
    }),
  )
  changedFileLines.push(
    JSON.stringify({
      path: upsert.path,
      changeType: upsert.changeType,
      oldPath: upsert.oldPath,
      fileId,
    }),
  )
}

await args.shouldAbort?.()
await args.artifactStore.writeManifest({
  artifactsPrefix: args.run.artifactsPrefix,
  lines: manifestLines,
})

await args.artifactStore.writeChangedFiles({
  artifactsPrefix: args.run.artifactsPrefix,
  lines: changedFileLines,
})

await args.artifactStore.writeRunJson({
  artifactsPrefix: args.run.artifactsPrefix,
  run: {
    runId: args.run.runId,
    mode: 'delta',
    baseSha: args.run.baseSha,
    headSha: args.run.headSha,
    stats,
  },
})

  emitProgress({
    step: 'delta_artifacts_written',
    message: 'Delta artifacts written.',
    details: {
      manifestLines: manifestLines.length,
      changedFiles: changedFileLines.length,
    },
  })

  return {
    stats,
  }
}

export function foo() {
  return 1
}

export const value = foo()

fn main() {
  napi_build::setup();

  // `pyo3` with `extension-module` intentionally doesn't link to libpython.
  // That's correct for the extension module itself, but it breaks `cargo test`
  // when `python-tests` are enabled because the unit-test binary needs Python
  // symbols resolved at link/runtime.
  //
  // For a nicer dev experience on macOS, link against the interpreter's
  // `libpythonX.Y.dylib` and add an `rpath` so the test binary can run.
  #[cfg(target_os = "macos")]
  if std::env::var_os("CARGO_FEATURE_PYTHON_TESTS").is_some() {
    println!("cargo:rerun-if-env-changed=PYTHON_SYS_EXECUTABLE");
    println!("cargo:rerun-if-env-changed=PYO3_PYTHON");

    let python = std::env::var("PYTHON_SYS_EXECUTABLE")
      .or_else(|_| std::env::var("PYO3_PYTHON"))
      .unwrap_or_else(|_| "python3".to_string());

    let output = std::process::Command::new(&python)
      .args([
        "-c",
        "import sysconfig; \
         print(sysconfig.get_config_var('LIBDIR') or ''); \
         print(sysconfig.get_config_var('LDLIBRARY') or '')",
      ])
      .output();

    let Ok(output) = output else {
      println!("cargo:warning=python-tests enabled but failed to run python to discover libpython");
      return;
    };
    if !output.status.success() {
      println!(
        "cargo:warning=python-tests enabled but python discovery failed (exit {})",
        output.status
      );
      return;
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut lines = stdout.lines();

    let Some(libdir) = lines.next() else {
      println!("cargo:warning=python-tests enabled but LIBDIR was not discovered");
      return;
    };
    let Some(ldlibrary) = lines.next() else {
      println!("cargo:warning=python-tests enabled but LDLIBRARY was not discovered");
      return;
    };

    let libdir = libdir.trim();
    let ldlibrary = ldlibrary.trim();
    if libdir.is_empty() || ldlibrary.is_empty() {
      println!("cargo:warning=python-tests enabled but libpython path could not be determined");
      return;
    }

    let libname = ldlibrary
      .strip_prefix("lib")
      .and_then(|name| name.strip_suffix(".dylib"))
      .unwrap_or(ldlibrary);

    println!("cargo:rustc-link-search=native={libdir}");
    println!("cargo:rustc-link-lib=dylib={libname}");
    println!("cargo:rustc-link-arg=-Wl,-rpath,{libdir}");
  }
}

export type User = {
  id: string
  name: string
}

export const formatUser = (user: User): string => {
  return `${user.name} (${user.id})`
}

export const add = (a: number, b: number): number => {
  return a + b
}

const path = require('node:path')

const native = require('../index.js')
const { indexStream } = require('./stream.js')
const { clampTopK, normalizeSearchHits } = require('./search-contract.js')
const { formatSearchHits, resolveColorMode } = require('./search-format.js')

const DEFAULT_EMBEDDING_BASE_URL = 'https://api.openai.com/v1'
const DEFAULT_EMBEDDING_MODEL = 'text-embedding-3-small'
const DEFAULT_EMBEDDING_DIMENSION = 1536
const DEFAULT_EMBEDDING_TIMEOUT_MS = 30_000
const DEFAULT_VECTOR_BATCH_SIZE = 256
const DEFAULT_VECTOR_CONCURRENCY = 4
const DEFAULT_TOP_K = 5
const DEFAULT_STORE_RELATIVE_PATH = '.argus-search/index.kite'

const StreamEventType = Object.freeze({
  ParseBatch: 'parse:batch',
  GraphBatch: 'graph:batch',
  VectorBatch: 'vector:batch',
  ScipBatch: 'scip:batch',
  PhaseStart: 'phase:start',
  PhaseProgress: 'phase:progress',
  PhaseComplete: 'phase:complete',
  PhaseError: 'phase:error',
  PipelineComplete: 'pipeline:complete',
})

function resolveRoot(root) {
  if (root == null) return process.cwd()
  const value = String(root).trim()
  if (!value) throw new Error('root cannot be empty')
  return path.resolve(value)
}

function resolveProjectPath(root, candidate) {
  const value = String(candidate ?? '').trim()
  if (!value) return root
  return path.isAbsolute(value) ? value : path.join(root, value)
}

function defaultStorePath(root) {
  return path.join(root, DEFAULT_STORE_RELATIVE_PATH)
}

function withDefaultOpenAiKey(apiKey) {
  if (typeof apiKey === 'string' && apiKey.trim()) return apiKey
  const fromEnv = process.env.OPENAI_API_KEY
  return typeof fromEnv === 'string' && fromEnv.trim() ? fromEnv : undefined
}

function normalizeStringList(input, fallback = []) {
  const values = Array.isArray(input) ? input : [input]
  const unique = []
  for (const raw of values) {
    if (raw == null) continue
    const value = String(raw).trim()
    if (!value) continue
    if (!unique.includes(value)) unique.push(value)
  }
  return unique.length > 0 ? unique : [...fallback]
}

function appendUnique(target, values) {
  for (const value of values) {
    if (!target.includes(value)) target.push(value)
  }
}

function flattenStringArgs(args) {
  if (!args || args.length === 0) return []
  if (args.length === 1 && Array.isArray(args[0])) return normalizeStringList(args[0], [])
  return normalizeStringList(args, [])
}

function toIndexRun(stats, durationMs, storePath) {
  const parse = stats?.parse ?? null
  const graph = stats?.graph ?? null
  const vector = stats?.vector ?? null
  return {
    duration: durationMs / 1000,
    durationMs,
    fileCount: Number(parse?.filesParsed ?? 0) + Number(parse?.filesSkipped ?? 0),
    vectorCount: Number(vector?.vectorsEmitted ?? 0),
    graphNodes: Number(graph?.nodesEmitted ?? 0),
    graphEdges: Number(graph?.edgesEmitted ?? 0),
    storePath: storePath ?? null,
    stats: stats ?? null,
  }
}

class VectorConfig {

  constructor(options = {}) {
    const {
      model = DEFAULT_EMBEDDING_MODEL,
      apiKey,
      baseUrl = DEFAULT_EMBEDDING_BASE_URL,
      dimension = DEFAULT_EMBEDDING_DIMENSION,
      timeoutMs = DEFAULT_EMBEDDING_TIMEOUT_MS,
      batchSize = DEFAULT_VECTOR_BATCH_SIZE,
      concurrency = DEFAULT_VECTOR_CONCURRENCY,
    } = options

    if (!String(model).trim()) throw new Error('model cannot be empty')
    if (!String(baseUrl).trim()) throw new Error('baseUrl cannot be empty')
    if (!Number.isFinite(Number(dimension)) || Number(dimension) <= 0) {
      throw new Error('dimension must be greater than 0')
    }
    if (!Number.isFinite(Number(timeoutMs)) || Number(timeoutMs) <= 0) {
      throw new Error('timeoutMs must be greater than 0')
    }
    if (!Number.isFinite(Number(batchSize)) || Number(batchSize) <= 0) {
      throw new Error('batchSize must be greater than 0')
    }
    if (!Number.isFinite(Number(concurrency)) || Number(concurrency) <= 0) {
      throw new Error('concurrency must be greater than 0')
    }

    this.model = String(model)
    this.apiKey = withDefaultOpenAiKey(apiKey)
    this.baseUrl = String(baseUrl)
    this.dimension = Math.floor(Number(dimension))
    this.timeoutMs = Math.floor(Number(timeoutMs))
    this.batchSize = Math.floor(Number(batchSize))
    this.concurrency = Math.floor(Number(concurrency))
  }

  toProvider() {
    return {
      kind: 'http',
      baseUrl: this.baseUrl,
      model: this.model,
      apiKey: this.apiKey,
      dimension: this.dimension,
      timeoutMs: this.timeoutMs,
    }
  }
}

class KiteDB {
  constructor(options = {}) {
    const normalized = typeof options === 'string' ? { path: options } : options
    const root = resolveRoot(normalized?.root)
    this.path = normalized?.path ? resolveProjectPath(root, normalized.path) : defaultStorePath(root)
  }
}

class Indexer {
  constructor(options = {}) {
    const normalized = typeof options === 'string' ? { root: options } : options
    this.root = resolveRoot(normalized.root)
    this._paths = normalizeStringList(normalized.paths ?? ['.'], ['.'])
    this._include = normalizeStringList(normalized.include ?? [], [])
    this._exclude = normalizeStringList(normalized.exclude ?? [], [])
    this._respectGitignore = normalized.respectGitignore ?? true
    this._vector = null
  }

  paths(...pathsInput) {
    this._paths = normalizeStringList(flattenStringArgs(pathsInput), ['.'])
    return this
  }

  include(...patterns) {
    appendUnique(this._include, flattenStringArgs(patterns))
    return this
  }

  exclude(...patterns) {
    appendUnique(this._exclude, flattenStringArgs(patterns))
    return this
  }

  useGitignore(enabled = true) {
    this._respectGitignore = Boolean(enabled)
    return this
  }

  useVectors(options = {}) {
    this._vector = options instanceof VectorConfig ? options : new VectorConfig(options)
    return this
  }

createStore(pathOrOptions) {
  if (pathOrOptions instanceof KiteDB) return pathOrOptions
  if (pathOrOptions == null) return new KiteDB({ root: this.root })
  if (typeof pathOrOptions === 'string') return new KiteDB({ root: this.root, path: pathOrOptions })
  return new KiteDB({ root: this.root, ...pathOrOptions })
}

stream(options = {}) {
  const {
    batchSize,
    highWaterMark = 16,
    signal,
    emit,
    graph = false,
    vector,
    scip = false,
    indexPack = false,
  } = options
  const indexOptions = this._buildIndexOptions({ graph, vector, scip, indexPack, batchSize })
  const streamOptions = { highWaterMark, signal }
  if (emit) streamOptions.emit = emit
  return indexStream(indexOptions, streamOptions)
}

async index(options = {}) {
  const { graph = true, vector, scip = false, indexPack = false, batchSize } = options
  const indexOptions = this._buildIndexOptions({ graph, vector, scip, indexPack, batchSize })
  const started = Date.now()
  const stats = await native.index(indexOptions)
  return toIndexRun(stats, Date.now() - started, null)
}

async persist(options = {}) {
  const { db, clear = false, graph = true, vector, scip = false, indexPack = false, batchSize } = options
  const store = this.createStore(db)
  const indexOptions = this._buildIndexOptions({ graph, vector, scip, indexPack, batchSize })
  const started = Date.now()
  const stats = await native.indexToKiteDb(indexOptions, { path: store.path, clear: Boolean(clear) })
  return toIndexRun(stats, Date.now() - started, store.path)
}

async search(query, options = {}) {
  const text = String(query ?? '').trim()
  if (!text) throw new Error('query cannot be empty')
  if (!this._vector) throw new Error('search requires useVectors(...)')

  const { db, topK = DEFAULT_TOP_K, includeContent = false, contentContext = 2, contentMaxChars = 4000 } = options
  const store = this.createStore(db)
  const hits = await native.searchKiteDb({
    projectRoot: this.root,
    store: { path: store.path },
    query: text,
    topK: clampTopK(topK),
    includeContent: Boolean(includeContent),
    contentContext: Number.isFinite(Number(contentContext)) ? Number(contentContext) : 2,
    contentMaxChars: Number.isFinite(Number(contentMaxChars)) ? Number(contentMaxChars) : 4000,
    vectorProvider: this._vector.toProvider(),
  })
  return normalizeSearchHits(hits, 'searchKiteDb')
}

  _buildIndexOptions({ graph = true, vector, scip = false, indexPack = false, batchSize } = {}) {
    const vectorEnabled = vector ?? Boolean(this._vector)
    if (vectorEnabled && !this._vector) {
      throw new Error('vector phase requires useVectors(...)')
    }

    const options = {
      projectRoot: this.root,
      inputs: {
        paths: this._paths.map((entry) => resolveProjectPath(this.root, entry)),
        include: [...this._include],
        exclude: [...this._exclude],
        respectGitignore: this._respectGitignore,
      },
      phases: {
        parse: true,
        graph: Boolean(graph),
        vector: Boolean(vectorEnabled),
        scip: Boolean(scip),
        indexPack: Boolean(indexPack),
      },
    }

    const maybeBatchSize = Number(batchSize)
    if (Number.isFinite(maybeBatchSize) && maybeBatchSize > 0) {
      const size = Math.floor(maybeBatchSize)
      options.hooks = {
        parseBatch: size,
        graphBatch: size,
        vectorBatch: size,
        scipBatch: size,
      }
    }

    if (vectorEnabled && this._vector) {
      options.vector = {
        batchSize: this._vector.batchSize,
        concurrency: this._vector.concurrency,
        provider: this._vector.toProvider(),
      }
    }

    return options
  }
}

module.exports = {
  ...native,
  indexStream,
  StreamEventType,
  VectorConfig,
  KiteDB,
  Indexer,
  formatSearchHits,
  resolveColorMode,
}

