const loadInitialGitLabIntegrations = async (
  userId: string | null | undefined,
): Promise<GitLabIntegrationQueryRow[] | null> => {
  if (!userId) {
    return []
  }

  try {
    const integrations = await getCachedUserIntegrations(userId)
    return integrations.map(toClientIntegrationRow)
  } catch (error) {
    const logger = createScopedLogger({
      method: "GET",
      path: "/(app)/layout",
    })
    logScopedError(logger, error, {
      code: "APP_LAYOUT_INTEGRATIONS_LOAD_FAILED",
      why: "Failed to load initial GitLab integrations for app shell hydration.",
      fix: "Verify integrations query dependencies and database connectivity.",
    })
    return null
  }
}

export default async function AppLayout({
  children,
}: Readonly<{
  children: ReactNode
}>) {
  const access = await getSessionAdminAccess()
  const isAuthenticated = Boolean(access.session?.user?.id)
  const initialGitLabIntegrations = await loadInitialGitLabIntegrations(access.session?.user?.id)

  return (
    <ThemeProvider
      attribute="class"
      defaultTheme="system"
      enableSystem
      disableTransitionOnChange
    >
      <AppLayoutClient
        isAuthenticated={isAuthenticated}
        isAdmin={access.isAdmin}
        initialGitLabIntegrations={initialGitLabIntegrations}
      >
        {children}
      </AppLayoutClient>
      <Toaster />
    </ThemeProvider>
  )
}

