function printUsage(command) {
  const c = getColors()

  if (command && COMMAND_USAGE[command]) {
    // Format command-specific help with colors
    const usage = COMMAND_USAGE[command]
    const formatted = usage
      // Color the "Usage:" header
      .replace(/^Usage:/m, `${c.bold}${c.underline}USAGE${c.reset}`)
      // Color the "Options:" header
      .replace(/^Options:/m, `${c.bold}${c.underline}OPTIONS${c.reset}`)
      // Color the "Supported shells:" header
      .replace(/^Supported shells:/m, `${c.bold}${c.underline}SUPPORTED SHELLS${c.reset}`)
      // Color command names in usage examples
      .replace(/argus-search/g, `${c.cyan}${c.bold}argus-search${c.reset}`)
