export const getActualThemeMode = (mode: ThemeMode) => {
  if (mode === "argus") {
    const prefersDark = typeof window !== "undefined" &&
      window.matchMedia("(prefers-color-scheme: dark)").matches
    return prefersDark ? "argus-dark" : "argus-light"
  }
  return mode
}

export const statusLabel: Record<IntegrationStatus, string> = {
  active: "Active",
  degraded: "Degraded",
  disabled: "Disabled",
}

export const formatDateTime = (value: string | null) => {
  if (!value) {
    return "Never"
  }

  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "Unknown"
  }

  return parsed.toLocaleString()
}

export const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

export const extractErrorMessage = (payload: unknown, fallback: string) => {
  const root = asRecord(payload)
  const rawError = root?.error
  return typeof rawError === "string" && rawError.trim().length > 0 ? rawError : fallback
}

export const readThemeModeFromStorage = (): ThemeMode => {
  if (typeof window === "undefined") {
    return "system"
  }

  const themeRaw = window.localStorage.getItem(THEME_SETTINGS_STORAGE_KEY)
  return isThemeMode(themeRaw) ? themeRaw : "system"
}

