const normalizeUrl = (value: string) => {
  const trimmed = value.trim().replace(/\/+$/, "")
  if (!trimmed) {
    return ""
  }

  const withProtocol = /^https?:\/\//i.test(trimmed)
    ? trimmed
    : `https://${trimmed}`

  try {
    const parsed = new URL(withProtocol)
    const pathname = parsed.pathname.replace(/\/+$/, "")
    return pathname
      ? `${parsed.origin}${pathname}`.toLowerCase()
      : parsed.origin.toLowerCase()
  } catch {
    return trimmed.toLowerCase()
  }
}

const resolveIntegrationFromApi = async () => {
  const response = await fetch("/api/gitlab/integrations", {
    method: "GET",
    headers: {
      "content-type": "application/json",
    },
  })
  const parsedPayload = await parseJsonResponse(response)
  const payload = parsedPayload.ok
    ? (parsedPayload.value as { data?: unknown })
    : null
  if (!response.ok) {
    throw new Error(getErrorMessage(payload))
  }
  const rows = Array.isArray(payload?.data)
    ? (payload.data as Array<Record<string, unknown>>)
    : []
  const integration = rows.find((entry) => {
    const projectId = String(entry?.projectId ?? "").trim()
    const instanceUrl = normalizeUrl(String(entry?.instanceUrl ?? ""))
    return (
      projectId === selectedProjectId &&
      instanceUrl === normalizeUrl(resolvedGitLabInstance)
    )
  })
  if (!integration) {
    return null
  }
  const integrationId = String(integration.id ?? "").trim()
  return integrationId.length > 0 ? integrationId : null
}

const wait = (ms: number) =>
  new Promise<void>((resolve) => {
    window.setTimeout(resolve, ms)
  })

void (async () => {
  const selectedProject = projects.find((project) => project.id === selectedProjectId)
  const connectIntegrationPromise = selectedProject
    ? connectIntegration(selectedProject).catch(() => null)
    : Promise.resolve<string | null>(null)

  let integrationId = getProjectIntegrationId(selectedProjectId)

  const attempts = 8
  for (let attempt = 0; attempt < attempts && !integrationId; attempt += 1) {
    integrationId = getProjectIntegrationId(selectedProjectId)
    if (integrationId) {
      break
    }

    const [connectedIntegrationId, resolvedIntegrationId] = await Promise.all([
      Promise.race<string | null>([
        connectIntegrationPromise,
        wait(220).then(() => null),
      ]),
      resolveIntegrationFromApi().catch(() => null),
    ])

    integrationId =
      getProjectIntegrationId(selectedProjectId) ??
      connectedIntegrationId ??
      resolvedIntegrationId

    if (integrationId) {
      break
    }
    if (attempt < attempts - 1) {
      await wait(200)
    }
  }

  if (integrationId) {
    const repoRouteId = selectedProject
      ? buildRepoRouteId({
        id: integrationId,
        instanceUrl: resolvedGitLabInstance,
        projectPath: selectedProject.path,
        projectId: selectedProject.id,
      })
      : integrationId

    setMergeRequestsError("")
    routePrefetchReview(repoRouteId, mergeRequestIid)
    routePushReview(repoRouteId, mergeRequestIid)
    return
  }

  setMergeRequestsError("Project integration is still being prepared. Try again in a moment.")
})()

