  apiPath: string
}): Promise<Response> => {
  const timeoutMs = resolveGitLabRequestTimeoutMs()
  const retries = resolveGitLabRequestRetries()

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    let response: Response
    try {
      response = await fetch(`${args.integration.instanceUrl}${args.apiPath}`, {
        headers: {
          'private-token': args.integration.token,
          'user-agent': 'argus-app',
        },
        signal: AbortSignal.timeout(timeoutMs),
      })
    } catch (error) {
      if (attempt < retries) {
        await wait((attempt + 1) * 100)
        continue
      }

      throw new Error(
        `GitLab request failed after ${attempt + 1} attempt(s): ${toErrorMessage(error)}`,
      )
    }

    if (response.ok) {
      return response
    }

    if (attempt < retries && RETRYABLE_STATUS_CODES.has(response.status)) {
      await wait((attempt + 1) * 100)
      continue
    }

    const body = await readErrorText(response)
    throw new GitLabApiError(
      `GitLab request failed (${response.status})${body ? `: ${body}` : ''}`,
      response.status,
      body || undefined,
    )
  }
  throw new Error('GitLab request failed after exhausting retries.')
}

const toCompareChangeType = (diff: {
  new_file?: boolean
  renamed_file?: boolean
  deleted_file?: boolean
}): GitLabCompareChange['type'] => {
  if (diff.deleted_file) {
    return 'deleted'
  }

  if (diff.renamed_file) {
    return 'renamed'
  }

  if (diff.new_file) {
    return 'added'
  }

  return 'modified'
}

export class GitLabApiSource implements GitLabSource {
  async resolveDefaultBranch(args: { integrationId: string }): Promise<string | null> {
    const integration = await loadIntegrationContext(args.integrationId)
    const encodedProjectId = encodeProjectId(integration.projectId)

    const response = await gitLabRequest({
      integration,
      apiPath: `/api/v4/projects/${encodedProjectId}`,
    })

    const payload = (await response.json()) as GitLabProjectResponse
    const defaultBranch = payload.default_branch?.trim()
    return defaultBranch && defaultBranch.length > 0 ? defaultBranch : null
  }

async resolveHeadSha(args: {
  integrationId: string
  branch: string
  hintedHeadSha?: string
}): Promise<string> {
  const hinted = args.hintedHeadSha?.trim()
  if (hinted) {
    return hinted
  }

  const integration = await loadIntegrationContext(args.integrationId)
  const encodedProjectId = encodeProjectId(integration.projectId)
  const encodedBranch = encodeURIComponent(args.branch)

  const response = await gitLabRequest({
    integration,
    apiPath: `/api/v4/projects/${encodedProjectId}/repository/branches/${encodedBranch}`,
  })

  const payload = (await response.json()) as GitLabBranchResponse
  const commitId = payload.commit?.id?.trim()
  if (!commitId) {
    throw new Error(`Unable to resolve head SHA for branch ${args.branch}.`)
  }

  return commitId
}

async compare(args: {
  integrationId: string
  fromSha: string
  toSha: string
}): Promise<{
  valid: boolean
  incomplete: boolean
  changes: GitLabCompareChange[]
}> {
  try {
    const integration = await loadIntegrationContext(args.integrationId)
    const encodedProjectId = encodeProjectId(integration.projectId)
    const from = encodeURIComponent(args.fromSha)
    const to = encodeURIComponent(args.toSha)

    const response = await gitLabRequest({
      integration,
      apiPath: `/api/v4/projects/${encodedProjectId}/repository/compare?from=${from}&to=${to}`,
    })

    const payload = (await response.json()) as GitLabCompareResponse
    const diffs = payload.diffs ?? []
    const changes: GitLabCompareChange[] = diffs.map((diff) => ({
      oldPath: diff.old_path ?? null,
      newPath: diff.new_path ?? null,
      type: toCompareChangeType(diff),
    }))

    return {
      valid: true,
      incomplete: Boolean(payload.compare_timeout),
      changes,
    }
  } catch {
    return {
      valid: false,
      incomplete: true,
      changes: [],
    }
  }
}

async fetchFile(args: {
  integrationId: string
  path: string
  ref: string
}): Promise<{
  path: string
  content: Buffer
}> {
  const integration = await loadIntegrationContext(args.integrationId)
  const encodedProjectId = encodeProjectId(integration.projectId)
  const filePath = encodeURIComponent(args.path)
  const ref = encodeURIComponent(args.ref)

  const response = await gitLabRequest({
    integration,
    apiPath: `/api/v4/projects/${encodedProjectId}/repository/files/${filePath}/raw?ref=${ref}`,
  })

  const content = Buffer.from(await response.arrayBuffer())
  return {
    path: args.path,
    content,
  }
}

async downloadArchive(args: {
  integrationId: string
  sha: string
}): Promise<{
  archivePath: string
}> {

  const integration = await loadIntegrationContext(args.integrationId)
  const encodedProjectId = encodeProjectId(integration.projectId)
  const sha = encodeURIComponent(args.sha)

  const response = await gitLabRequest({
    integration,
    apiPath: `/api/v4/projects/${encodedProjectId}/repository/archive.tar.gz?sha=${sha}`,
  })

  const maxArchiveBytes = resolveGitLabArchiveMaxBytes()
  const contentLength = Number.parseInt(response.headers.get('content-length') ?? '', 10)
  if (Number.isFinite(contentLength) && contentLength > maxArchiveBytes) {
    throw new Error(
      `GitLab archive exceeds configured limit (${contentLength} > ${maxArchiveBytes} bytes).`,
    )
  }

  if (!response.body) {
    throw new Error('GitLab archive response body is empty.')
  }

  const tempDir = await mkdtemp(path.join(os.tmpdir(), 'argus-indexer-archive-'))
  const archivePath = path.join(tempDir, 'source.tar.gz')
  const responseStream = Readable.fromWeb(response.body as WebReadableStream<Uint8Array>)
  let bytesRead = 0

  responseStream.on('data', (chunk: Buffer) => {
    bytesRead += chunk.byteLength
    if (bytesRead > maxArchiveBytes) {
      responseStream.destroy(
        new Error(`GitLab archive exceeds configured limit (${maxArchiveBytes} bytes).`),
      )
    }
  })

  try {
    await pipeline(responseStream, createWriteStream(archivePath))
  } catch (error) {
    await unlink(archivePath).catch(() => {})
    throw error
  }

  return {
    archivePath,
  }
}

