  return "stale_writer"
}

await appendWorkerEvent({
  stage: failure.terminal ? "failed" : "queued",
  eventType: failure.terminal ? "failed" : "progress",
  message: failure.terminal ? message : `Attempt ${run.attempts} failed, retry scheduled.`,
  payload: {
    retryable,
    attempt: run.attempts,
    maxAttempts,
    nextAttemptAt: failure.nextAttemptAt?.toISOString() ?? null,
    failedFiles,
  },
})

    return failure.terminal ? "dead" : "retry"
  }
}

let lastRetentionRunAt = 0

export const runReviewWorkerBatch = async (args?: {
  batchSize?: number
  concurrency?: number
  maxAttempts?: number
  retentionDays?: number
  shouldStopClaiming?: () => boolean
}): Promise<ReviewWorkerBatchSummary> => {
  const batchSize = Math.max(1, Math.min(args?.batchSize ?? REVIEW_WORKER_BATCH_SIZE, 200))
  const concurrency = Math.max(1, Math.min(args?.concurrency ?? REVIEW_WORKER_CONCURRENCY, 24))
  const maxAttempts = Math.max(1, args?.maxAttempts ?? REVIEW_JOB_MAX_ATTEMPTS)
  const shouldStopClaiming = args?.shouldStopClaiming

  if (shouldStopClaiming?.()) {
    return {
      claimed: 0,
      succeeded: 0,
      failed: 0,
      retryScheduled: 0,
      dead: 0,
      fenceMisses: 0,
    }
  }

  const claimed = await claimDueReviewRuns({ batchSize })

  const summary: ReviewWorkerBatchSummary = {
    claimed: claimed.length,
    succeeded: 0,
    failed: 0,
    retryScheduled: 0,
    dead: 0,
    fenceMisses: 0,
  }

  let cursor = 0

  const runNext = async (): Promise<void> => {
    if (shouldStopClaiming?.()) {
      return
    }

    const run = claimed[cursor]
    if (!run) {
      return
    }
    cursor += 1

    const status = await processClaimedRun(run, maxAttempts)
    if (status === "succeeded") {
      summary.succeeded += 1
    } else if (status === "retry") {
      summary.retryScheduled += 1
      summary.failed += 1
    } else if (status === "stale_writer") {
      summary.fenceMisses += 1
    } else {
      summary.failed += 1
      summary.dead += 1
    }

    await runNext()
  }

  await Promise.all(
    Array.from({ length: Math.min(concurrency, claimed.length) }, () => runNext()),
  )

  const now = Date.now()
  if (now - lastRetentionRunAt >= 60 * 60 * 1_000) {
    lastRetentionRunAt = now
    await purgeReviewFlowRetentionData({
      retentionDays: args?.retentionDays ?? REVIEW_FLOW_RETENTION_DAYS,
    })
  }

  return summary
}

export const runReviewWorker = async () => {
  const leaseSettings = resolveReviewLeaseSettings()

initAppLogger({
  service: process.env.SERVICE_NAME?.trim() || "review-worker",
  initEvent: "review.worker.started",
  initContext: {
    continuous: REVIEW_WORKER_CONTINUOUS,
    pollMs: REVIEW_WORKER_POLL_MS,
    batchSize: REVIEW_WORKER_BATCH_SIZE,
    concurrency: REVIEW_WORKER_CONCURRENCY,
    maxAttempts: REVIEW_JOB_MAX_ATTEMPTS,
    retentionDays: REVIEW_FLOW_RETENTION_DAYS,
    leasesEnabled: leaseSettings.enabled,
    leaseMs: leaseSettings.leaseMs,
    staleReclaimIntervalMs: leaseSettings.staleReclaimIntervalMs,
    gracefulShutdownMs: leaseSettings.gracefulShutdownMs,
  },
})

let shutdownRequested = false
let shutdownSignal: "SIGINT" | "SIGTERM" | null = null
let resolveShutdownSignal: (() => void) | null = null
const shutdownSignalPromise = new Promise<void>((resolve) => {
  resolveShutdownSignal = resolve
})

const requestShutdown = (signal: "SIGINT" | "SIGTERM") => {
  if (shutdownRequested) {
    return
  }
  shutdownRequested = true
  shutdownSignal = signal
  appLog.warn({
    event: WORKER_EVENTS.REVIEW_WORKER_SHUTDOWN_SIGNAL,
    signal,
    gracefulShutdownMs: leaseSettings.gracefulShutdownMs,
  })
  resolveShutdownSignal?.()
}

const handleSigint = () => requestShutdown("SIGINT")
const handleSigterm = () => requestShutdown("SIGTERM")
process.on("SIGINT", handleSigint)
process.on("SIGTERM", handleSigterm)

const loopBackoffMs = Math.max(
  REVIEW_WORKER_POLL_MS,
  REVIEW_WORKER_LOOP_ERROR_BACKOFF_MS,
)

const runBatchSafely = async () => {
  const batchPromise = runReviewWorkerBatch({
    shouldStopClaiming: () => shutdownRequested,
  })

  const outcome = await Promise.race([
    batchPromise.then((summary) => ({ kind: "batch" as const, summary })),
    shutdownSignalPromise.then(() => ({ kind: "shutdown" as const })),
  ])

  if (outcome.kind === "batch") {
    return {
      summary: outcome.summary,
      drainedBeforeTimeout: true,
    }
  }

  const drainedBeforeTimeout = await Promise.race([
    batchPromise.then(() => true),
    sleep(leaseSettings.gracefulShutdownMs).then(() => false),
  ])

  if (!drainedBeforeTimeout) {
    appLog.warn({
      event: WORKER_EVENTS.REVIEW_WORKER_SHUTDOWN_COMPLETE,
      signal: shutdownSignal,
      drainedBeforeTimeout: false,
      gracefulShutdownMs: leaseSettings.gracefulShutdownMs,
    })
  }

  return {
    summary: await batchPromise.catch(() => ({
      claimed: 0,
      succeeded: 0,
      failed: 0,
      retryScheduled: 0,
      dead: 0,
      fenceMisses: 0,
    })),
    drainedBeforeTimeout,
  }
}

if (!REVIEW_WORKER_CONTINUOUS) {
  try {
    const { summary } = await runBatchSafely()
    appLog.info({
      event: "review.worker.batch_cycle",
      summary,
    })
  } finally {
    process.off("SIGINT", handleSigint)
    process.off("SIGTERM", handleSigterm)
    appLog.info({
      event: WORKER_EVENTS.REVIEW_WORKER_SHUTDOWN_COMPLETE,
      signal: shutdownSignal,
      drainedBeforeTimeout: true,
    })
  }
  return
}

  try {
    while (!shutdownRequested) {
      try {
        const { summary } = await runBatchSafely()
        appLog.info({
          event: "review.worker.batch_cycle",
          summary,
        })
        if (shutdownRequested) {
          break
        }

        if (summary.claimed === 0) {
          const waitResult = await waitForReviewQueueNotification(REVIEW_WORKER_POLL_MS)
          if (waitResult === "disabled") {
            await sleep(REVIEW_WORKER_POLL_MS)
          }
        }
      } catch (error) {
        const errorToLog = toError(error, "Review worker batch loop failed.")
        appLog.error({
          event: WORKER_EVENTS.REVIEW_WORKER_LOOP_ERROR,
          retryable: true,
          error: {
            name: errorToLog.name,
            message: errorToLog.message,
          },
        })
        if (shutdownRequested) {
          break
        }
        await sleep(loopBackoffMs)
      }
    }
  } finally {
    process.off("SIGINT", handleSigint)
    process.off("SIGTERM", handleSigterm)
    appLog.info({
      event: WORKER_EVENTS.REVIEW_WORKER_SHUTDOWN_COMPLETE,
      signal: shutdownSignal,
      drainedBeforeTimeout: true,
    })
  }
}

