import { and, eq, lt, sql } from "drizzle-orm"

import { db } from "@/lib/db"
import { gitlabJobs, gitlabWebhookDeliveries, indexBranchStates } from "@/lib/db/schema"
import {
  getCommitDetails,
  getMergeRequestChanges,
  getMergeRequestDetails,
} from "@/lib/gitlab/client"
import {
  GITLAB_MAX_JOB_ATTEMPTS,
  GITLAB_WEBHOOK_RETENTION_DAYS,
} from "@/lib/gitlab/constants"
import { gitlabEnv } from "@/lib/gitlab/env"
import * as gitlabService from "@/lib/gitlab/service"
import { enqueuePlanJob, enqueueReconcileJob } from "@/lib/indexing/job-queue"
import { ensureMergeRequestSourceBranchIndexing } from "@/lib/indexing/mr-auto-index"

const ZERO_GIT_SHA = "0000000000000000000000000000000000000000"

type ClaimedJob = {
  id: string
  integrationId: string
  deliveryId: string | null
  jobType: "push" | "merge_request" | "hook_sync"
  attempts: number
  normalizedPayload: Record<string, unknown> | null
}

const parseNormalizedPayload = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const parseJobType = (value: unknown): ClaimedJob["jobType"] => {
  if (value === "push" || value === "merge_request" || value === "hook_sync") {
    return value
  }
  throw new Error("Invalid claimed job type.")
}

const claimDueJobs = async (batchSize: number): Promise<ClaimedJob[]> => {
  const query = sql<ClaimedJob>`
    with due_jobs as (
      select ${gitlabJobs.id}
      from ${gitlabJobs}
      where ${gitlabJobs.status} in ('pending', 'failed')
        and ${gitlabJobs.nextAttemptAt} <= now()
      order by ${gitlabJobs.nextAttemptAt} asc, ${gitlabJobs.createdAt} asc
      for update skip locked
      limit ${batchSize}
    )
    update ${gitlabJobs}
      set
        "status" = 'processing',
        "started_at" = now(),
        "updated_at" = now(),
        "attempts" = "attempts" + 1
    from due_jobs
    where ${gitlabJobs.id} = due_jobs.id
    returning
      ${gitlabJobs.id} as "id",
      ${gitlabJobs.integrationId} as "integrationId",
      ${gitlabJobs.deliveryId} as "deliveryId",
      ${gitlabJobs.jobType} as "jobType",
      ${gitlabJobs.attempts} as "attempts",
      ${gitlabJobs.normalizedPayload} as "normalizedPayload"
  `

  const result = await db.execute(query)
  return result.rows.map((rawRow) => {
    const row = rawRow as Record<string, unknown>
    return {
      id: String(row.id),
      integrationId: String(row.integrationId),
      deliveryId: typeof row.deliveryId === "string" ? row.deliveryId : null,
      jobType: parseJobType(row.jobType),
      attempts: Number(row.attempts),
      normalizedPayload: parseNormalizedPayload(row.normalizedPayload),
    }
  })
}

const getRetryDelayMs = (attempt: number) => {
  const exponent = Math.max(0, attempt - 1)
  const baseDelayMs = 30_000
  return Math.min(60 * 60 * 1_000, baseDelayMs * 2 ** exponent)
}

const markJobSucceeded = async (jobId: string, result: Record<string, unknown>) => {
  await db
    .update(gitlabJobs)
    .set({
      status: "succeeded",
      finishedAt: new Date(),
      lastError: null,
      result,
      updatedAt: new Date(),
    })
    .where(eq(gitlabJobs.id, jobId))
}

const markJobFailed = async ({
  job,
  error,
}: {
  job: ClaimedJob
  error: unknown
}) => {
  const message =
    error instanceof Error ? error.message.slice(0, 500) : "Unexpected job processing error."

  const exceededAttempts = job.attempts >= GITLAB_MAX_JOB_ATTEMPTS
  await db
    .update(gitlabJobs)
    .set({
      status: exceededAttempts ? "dead" : "failed",
      finishedAt: exceededAttempts ? new Date() : null,
      nextAttemptAt: exceededAttempts
        ? new Date()
        : new Date(Date.now() + getRetryDelayMs(job.attempts)),
      lastError: message,
      updatedAt: new Date(),
    })
    .where(eq(gitlabJobs.id, job.id))

  return exceededAttempts
}

const readString = (
  payload: Record<string, unknown> | null,
  key: string,
  fieldName: string,
) => {
  const value = payload?.[key]
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`Missing ${fieldName} in job payload.`)
  }
  return value
}

const branchFromRef = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }

  const normalized = value.trim()
  const prefix = "refs/heads/"
  if (!normalized.startsWith(prefix)) {
    return null
  }

  const branch = normalized.slice(prefix.length).trim()
  return branch.length > 0 ? branch : null
}

const normalizeBranchName = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }

  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

const normalizeMergeRequestState = (value: unknown) => {
  const normalized = normalizeBranchName(value)
  return normalized ? normalized.toLowerCase() : null
}

const scheduleBranchCleanup = async (args: {
  integrationId: string
  branch: string | null
  reason: string
}) => {
  if (!args.branch) {
    return {
      action: "skipped" as const,
      reason: "missing_source_branch",
      branch: null,
    }
  }

  const pendingPruneAt = new Date()
  await db
    .update(indexBranchStates)
    .set({
      pendingPruneAt,
      pendingPruneReason: args.reason,
      updatedAt: pendingPruneAt,
    })
    .where(
      and(
        eq(indexBranchStates.integrationId, args.integrationId),
        eq(indexBranchStates.branch, args.branch),
      ),
    )

  return {
    action: "scheduled" as const,
    reason: args.reason,
    branch: args.branch,
    pendingPruneAt: pendingPruneAt.toISOString(),
  }
}

const clearScheduledBranchCleanup = async (args: { integrationId: string; branch: string | null }) => {
  if (!args.branch) {
    return {
      action: "skipped" as const,
      reason: "missing_source_branch",
      branch: null,
    }
  }

  await db
    .update(indexBranchStates)
    .set({
      pendingPruneAt: null,
      pendingPruneReason: null,
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(indexBranchStates.integrationId, args.integrationId),
        eq(indexBranchStates.branch, args.branch),
      ),
    )

  return {
    action: "cleared" as const,
    reason: "mr_reactivated",
    branch: args.branch,
  }
}

const processPushJob = async (job: ClaimedJob) => {
  const integration = await gitlabService.getIntegrationById(job.integrationId)
  if (!integration) {
    throw new Error("Integration not found for push job.")
  }

  const afterSha = readString(job.normalizedPayload, "after", "after")
  const isBranchDeleted = afterSha === ZERO_GIT_SHA
  const token = gitlabService.decryptIntegrationToken(integration)
  const branch = branchFromRef(job.normalizedPayload?.ref)
  const commit = isBranchDeleted
    ? null
    : await getCommitDetails(
        integration.instanceUrl,
        token,
        integration.projectId,
        afterSha,
      )
  const queuedPlanJob = branch
    ? isBranchDeleted
      ? null
      : await enqueuePlanJob({
          integrationId: job.integrationId,
          branch,
          hintedHeadSha: afterSha,
        })
    : null

  const queuedReconcileJob = await enqueueReconcileJob({
    integrationId: job.integrationId,
  })

  return {
    type: "push",
    ref: typeof job.normalizedPayload?.ref === "string" ? job.normalizedPayload.ref : null,
    after: afterSha,
    branch,
    branchDeleted: isBranchDeleted,
    indexing:
      queuedPlanJob === null
        ? {
            queued: false,
            reason: branch
              ? isBranchDeleted
                ? "branch_deleted"
                : "plan_not_queued"
              : "non_branch_ref",
          }
        : {
            queued: true,
            jobId: queuedPlanJob.id,
            debounceKey: queuedPlanJob.debounceKey,
            status: queuedPlanJob.status,
          },
    reconcile: {
      queued: true,
      jobId: queuedReconcileJob.id,
      debounceKey: queuedReconcileJob.debounceKey,
      status: queuedReconcileJob.status,
    },
    commit,
  }
}

const processMergeRequestJob = async (job: ClaimedJob) => {
  const integration = await gitlabService.getIntegrationById(job.integrationId)
  if (!integration) {
    throw new Error("Integration not found for merge request job.")
  }

  const mergeRequestIid = readString(
    job.normalizedPayload,
    "mergeRequestIid",
    "mergeRequestIid",
  )

  const token = gitlabService.decryptIntegrationToken(integration)
  const mergeRequest = await getMergeRequestDetails(
    integration.instanceUrl,
    token,
    integration.projectId,
    mergeRequestIid,
  )

const action =
  typeof job.normalizedPayload?.action === "string"
    ? job.normalizedPayload.action.trim().toLowerCase()
    : null
const payloadState =
  typeof job.normalizedPayload?.state === "string"
    ? job.normalizedPayload.state.trim().toLowerCase()
    : null
const mergeRequestState =
  normalizeMergeRequestState(mergeRequest.state) ?? payloadState
const sourceBranchHint =
  normalizeBranchName(job.normalizedPayload?.sourceBranch)
const sourceHeadShaHint =
  typeof job.normalizedPayload?.lastCommitSha === "string"
    ? job.normalizedPayload.lastCommitSha
    : null
const sourceBranch = sourceBranchHint ?? normalizeBranchName(mergeRequest.source_branch)
const isCurrentMrOpen = mergeRequestState === "opened" || mergeRequestState === "open"
const isCurrentMrClosed = mergeRequestState === "closed" || mergeRequestState === "merged"
const shouldAutoQueueIndexing =
  (action === "open" || action === "reopen" || action === "update") &&
  (mergeRequestState === null || isCurrentMrOpen)
const shouldQueueReconcile = action === "merge" || action === "close"

const resolvedIndexing = shouldAutoQueueIndexing
  ? await ensureMergeRequestSourceBranchIndexing({
      integrationId: job.integrationId,
      mergeRequestIid,
      trigger: "webhook",
      sourceBranchHint: sourceBranch,
      sourceHeadShaHint,
      mergeRequestDetails: mergeRequest,
    })
  : {
      decision: "skipped" as const,
      reason: "non_actionable_mr_event",
      branch: sourceBranch,
      headSha: sourceHeadShaHint,
    }
const cleanup =
  isCurrentMrClosed
    ? await scheduleBranchCleanup({
        integrationId: job.integrationId,
        branch: sourceBranch,
        reason: "mr_closed",
      })
    : isCurrentMrOpen
      ? await clearScheduledBranchCleanup({
          integrationId: job.integrationId,
          branch: sourceBranch,
        })
      : {
          action: "unchanged" as const,
          reason: "non_actionable_mr_event",
          branch: sourceBranch,
        }
const queuedReconcileJob = shouldQueueReconcile
  ? await enqueueReconcileJob({
      integrationId: job.integrationId,
    })
  : null

let changes: Record<string, unknown> | null = null
try {
  changes = await getMergeRequestChanges(
    integration.instanceUrl,
    token,
    integration.projectId,
    mergeRequestIid,
  )
} catch {
  changes = null
}

  return {
    type: "merge_request",
    mergeRequestIid,
    action,
    state: payloadState,
    mergeRequestState,
    indexing: resolvedIndexing,
    cleanup,
    reconcile:
      queuedReconcileJob === null
        ? {
            queued: false,
            reason: "non_terminal_mr_event",
          }
        : {
            queued: true,
            jobId: queuedReconcileJob.id,
            debounceKey: queuedReconcileJob.debounceKey,
            status: queuedReconcileJob.status,
          },
    mergeRequest,
    ...(changes ? { changes } : {}),
  }
}

const processHookSyncJob = async (job: ClaimedJob) => {
  const integration = await gitlabService.getIntegrationById(job.integrationId)
  if (!integration) {
    throw new Error("Integration not found for hook sync job.")
  }

  const token = gitlabService.decryptIntegrationToken(integration)
  const syncResult = await gitlabService.syncIntegrationWebhook({
    integration,
    token,
  })

  if (!syncResult.ok) {
    throw new Error(syncResult.error ?? "Hook sync failed.")
  }

  return {
    type: "hook_sync",
    reason:
      typeof job.normalizedPayload?.reason === "string"
        ? job.normalizedPayload.reason
        : "scheduled",
  }
}

const processClaimedJob = async (job: ClaimedJob): Promise<Record<string, unknown>> => {
  if (job.jobType === "push") {
    return processPushJob(job)
  }

  if (job.jobType === "merge_request") {
    return processMergeRequestJob(job)
  }

  return processHookSyncJob(job)
}

export const runGitLabJobRunner = async (batchSize = gitlabEnv.jobBatchSize) => {
  const normalizedBatchSize = Math.min(200, Math.max(1, Math.floor(batchSize)))
  const jobs = await claimDueJobs(normalizedBatchSize)

  const summary = {
    claimed: jobs.length,
    succeeded: 0,
    failed: 0,
    dead: 0,
  }

  for (const job of jobs) {
    try {
      const result = await processClaimedJob(job)
      await markJobSucceeded(job.id, result)
      summary.succeeded += 1
    } catch (error) {
      const isDead = await markJobFailed({ job, error })
      if (isDead) {
        summary.dead += 1
      } else {
        summary.failed += 1
      }
    }
  }

  return summary
}

export const cleanupOldWebhookDeliveries = async (
  retentionDays = GITLAB_WEBHOOK_RETENTION_DAYS,
) => {
  const normalizedDays = Math.max(1, Math.floor(retentionDays))
  const cutoff = new Date(Date.now() - normalizedDays * 24 * 60 * 60 * 1_000)

  const deleted = await db
    .delete(gitlabWebhookDeliveries)
    .where(lt(gitlabWebhookDeliveries.receivedAt, cutoff))
    .returning({ id: gitlabWebhookDeliveries.id })

  return {
    deletedDeliveries: deleted.length,
    retentionDays: normalizedDays,
  }
}

import { Loader2 } from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"

import {
  type BranchGraphStatus,
  formatStatusLabel,
  type LiveIndexerLogLevel,
  type PipelineStageState,
  RUN_ACTIVE_STATUSES,
  RUN_CANCELLED_STATUSES,
  RUN_FAILURE_STATUSES,
  RUN_SUCCESS_STATUSES,
} from "@/features/indexing/model/console/model"

export const statusVariant = (status: string): React.ComponentProps<typeof Badge>["variant"] => {
  if (status === "ready" || status === "succeeded" || status === "active") {
    return "default"
  }
  if (status === "failed" || status === "dead") {
    return "destructive"
  }
  if (status === "cancelled") {
    return "outline"
  }
  if (
    status === "planned" ||
    status === "pending" ||
    status === "processing" ||
    status === "ingesting" ||
    status === "indexing"
  ) {
    return "secondary"
  }
  return "outline"
}

export const logLevelVariant = (
  level: LiveIndexerLogLevel,
): React.ComponentProps<typeof Badge>["variant"] => {
  if (level === "error") {
    return "destructive"
  }
  if (level === "warn") {
    return "secondary"
  }
  if (level === "info") {
    return "default"
  }
  return "outline"
}

export const pipelineStageBadgeVariant = (
  state: PipelineStageState,
): React.ComponentProps<typeof Badge>["variant"] => {
  if (state === "done") {
    return "default"
  }
  if (state === "active") {
    return "secondary"
  }
  if (state === "failed") {
    return "destructive"
  }
  return "outline"
}

const statusPillClassName = (status: string) => {
