import { spawn } from "node:child_process"

const commands = [
  {
    name: "web",
    cwd: "apps/web",
    args: ["run", "--env-file=../../.env", "dev"],
  },
  {
    name: "indexer",
    cwd: "apps/indexer",
    args: ["run", "--env-file=../../.env", "dev"],
  },
]

const bunExecutable = process.platform === "win32" ? "bun.exe" : "bun"
const children = []
let shuttingDown = false

const stopAll = (signal = "SIGTERM") => {
  if (shuttingDown) {
    return
  }
  shuttingDown = true

  for (const child of children) {
    if (!child.killed) {
      child.kill(signal)
    }
  }
}

for (const command of commands) {
  const child = spawn(bunExecutable, command.args, {
    cwd: command.cwd,
    stdio: "inherit",
    env: process.env,
  })

  child.on("exit", (code, signal) => {
    if (!shuttingDown) {
      console.error(
        `[dev:all] ${command.name} exited ${signal ? `with signal ${signal}` : `with code ${code}`}`,
      )
      stopAll(signal ?? "SIGTERM")
      process.exit(code ?? 1)
    }
  })

  child.on("error", (error) => {
    console.error(`[dev:all] failed to start ${command.name}:`, error)
    stopAll()
    process.exit(1)
  })

  children.push(child)
}

process.once("SIGINT", () => {
  stopAll("SIGINT")
  process.exit(0)
})

process.once("SIGTERM", () => {
  stopAll("SIGTERM")
  process.exit(0)
})

use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::Path;
use std::process::Command;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

use tempfile::TempDir;

fn ci_cmd() -> Command {
  Command::new(env!("CARGO_BIN_EXE_ci"))
}

fn run_ci<I, S>(args: I) -> Result<std::process::Output, Box<dyn std::error::Error>>
where
  I: IntoIterator<Item = S>,
  S: AsRef<std::ffi::OsStr>,
{
  Ok(ci_cmd().args(args).output()?)
}

fn assert_command_success(output: &std::process::Output, context: &str) {
  assert!(
    output.status.success(),
    "{}: {}",
    context,
    String::from_utf8_lossy(&output.stderr)
  );
}

fn write_file(path: &Path, contents: &str) {
  if let Some(parent) = path.parent() {
    std::fs::create_dir_all(parent).unwrap();
  }
  std::fs::write(path, contents).unwrap();
}

fn spawn_embeddings_server() -> (String, thread::JoinHandle<()>) {
  let (base_url, _requests, handle) = spawn_embeddings_server_with_counter();
  (base_url, handle)
}

fn spawn_embeddings_server_with_counter() -> (String, Arc<AtomicUsize>, thread::JoinHandle<()>) {
  let listener = TcpListener::bind("127.0.0.1:0").unwrap();
  let addr = listener.local_addr().unwrap();
  let base_url = format!("http://127.0.0.1:{}", addr.port());
  let requests = Arc::new(AtomicUsize::new(0));
  let counter = Arc::clone(&requests);

  let handle = thread::spawn(move || {
    for stream in listener.incoming() {
      let Ok(mut stream) = stream else { break };
      if let Err(err) = handle_conn(&mut stream, &counter) {
        let _ = writeln!(std::io::stderr(), "embeddings server error: {err}");
        break;
      }
    }
  });

  (base_url, requests, handle)
}

fn handle_conn(stream: &mut TcpStream, requests: &Arc<AtomicUsize>) -> anyhow::Result<()> {
  let mut buf = Vec::new();
  let mut tmp = [0u8; 4096];
  loop {
    let read = stream.read(&mut tmp)?;
    if read == 0 {
      break;
    }
    buf.extend_from_slice(&tmp[..read]);
    if buf.windows(4).any(|w| w == b"\r\n\r\n") {
      break;
    }
    if buf.len() > 1024 * 1024 {
      anyhow::bail!("request headers too large");
    }
  }

  let header_end = buf
    .windows(4)
    .position(|w| w == b"\r\n\r\n")
    .ok_or_else(|| anyhow::anyhow!("missing header terminator"))?
    + 4;

  let headers = String::from_utf8_lossy(&buf[..header_end]);
  let mut lines = headers.lines();
  let request_line = lines.next().unwrap_or_default();
  let (method, path) = request_line
    .split_once(' ')
    .and_then(|(m, rest)| rest.split_once(' ').map(|(p, _)| (m, p)))
    .unwrap_or(("", ""));

let mut content_length = 0usize;
for line in lines {
  let (k, v) = match line.split_once(':') {
    Some(pair) => pair,
    None => continue,
  };
  if k.eq_ignore_ascii_case("content-length") {
    content_length = v.trim().parse::<usize>().unwrap_or(0);
  }
}

let mut body = buf[header_end..].to_vec();
while body.len() < content_length {
  let read = stream.read(&mut tmp)?;
  if read == 0 {
    break;
  }
  body.extend_from_slice(&tmp[..read]);
  if body.len() > 10 * 1024 * 1024 {
    anyhow::bail!("request body too large");
  }
}

if method != "POST" || path != "/embeddings" {
  respond(stream, 404, r#"{"error":"not found"}"#.as_bytes())?;
  return Ok(());
}
requests.fetch_add(1, Ordering::SeqCst);

let req: serde_json::Value = serde_json::from_slice(&body).unwrap_or(serde_json::json!({}));
let input = req
  .get("input")
  .and_then(|v| v.as_array())
  .cloned()
  .unwrap_or_default();
let data = input
  .into_iter()
  .map(|_| serde_json::json!({ "embedding": [0.1, 0.2, 0.3] }))
  .collect::<Vec<_>>();
let resp = serde_json::json!({ "data": data }).to_string();
respond(stream, 200, resp.as_bytes())?;
Ok(())

}

fn respond(stream: &mut TcpStream, status: u16, body: &[u8]) -> anyhow::Result<()> {
  let reason = match status {
    200 => "OK",
    404 => "Not Found",
    _ => "Error",
  };
  write!(
    stream,
    "HTTP/1.1 {} {}\r\ncontent-type: application/json\r\ncontent-length: {}\r\n\r\n",
    status,
    reason,
    body.len()
  )?;
  stream.write_all(body)?;
  stream.flush()?;
  Ok(())
}

