  let (base_url, requests, _handle) = spawn_embeddings_server_with_counter();
  let tmp = TempDir::new()?;
  write_file(
    &tmp.path().join("src/a.ts"),
    r#"export function Login() { return 1 }
export function main() { return Login() }
"#,
  );

  let init = run_ci([
    "--project-root",
    tmp.path().to_str().unwrap(),
    "init",
    "--vector-base-url",
    &base_url,
    "--vector-model",
    "test-model",
  ])?;
  assert_command_success(&init, "init failed");

  let config = tmp.path().join("argus-search.json");
  let watch = run_ci([
    "--config",
    config.to_str().unwrap(),
    "watch",
    "--once",
    "--phases",
    "parse,vector",
  ])?;
  assert_command_success(&watch, "watch failed");

  let before = requests.load(Ordering::SeqCst);
  let search1 = run_ci([
    "--config",
    config.to_str().unwrap(),
    "search",
    "Login",
    "--top-k",
    "3",
    "--json",
  ])?;
  assert_command_success(&search1, "first search failed");

  let after_first = requests.load(Ordering::SeqCst);
  assert!(
    after_first > before,
    "expected first search to request embeddings: before={before} after={after_first}"
  );

  let search2 = run_ci([
    "--config",
    config.to_str().unwrap(),
    "search",
    "Login",
    "--top-k",
    "3",
    "--json",
  ])?;
  assert_command_success(&search2, "second search failed");

  let after_second = requests.load(Ordering::SeqCst);
  assert_eq!(
    after_second, after_first,
    "expected second identical search to hit cache without extra embeddings request"
  );
  Ok(())
}

