export const getErrorMessage = (value: unknown) => {
	const sanitize = (message: string) => {
		const normalized = message.trim().replace(/\s+/g, " ");
		if (!normalized) {
			return "Unable to load merge request diff.";
		}

		const looksLikeRawSqlLeak =
			/failed query:/i.test(normalized) ||
			/\bparams:\b/i.test(normalized) ||
			/\binsert into\b/i.test(normalized) ||
			/\bon conflict\b/i.test(normalized) ||
			/\btoken_ciphertext\b|\btoken_iv\b|\btoken_auth_tag\b/i.test(normalized);

		if (looksLikeRawSqlLeak) {
			return "Unable to load merge request diff.";
		}

		return normalized;
	};

	if (typeof value === "string") {
		return sanitize(value);
	}
	if (value instanceof Error && value.message.trim().length > 0) {
		return sanitize(value.message);
	}
	if (value && typeof value === "object" && "message" in value) {
		const message = String(
			(value as { message?: unknown }).message ?? "",
		).trim();
		if (message.length > 0) {
			return sanitize(message);
		}
	}
	if (value && typeof value === "object" && "error" in value) {
		return sanitize(String((value as { error?: string }).error));
	}
	return "Unable to load merge request diff.";
};

export const getReviewErrorMessage = (value: unknown) => {
	if (typeof value === "string") {
		return value;
	}
	if (value instanceof Error && value.message.trim().length > 0) {
		return value.message;
	}
	if (value && typeof value === "object" && "message" in value) {
		const message = String(
			(value as { message?: unknown }).message ?? "",
		).trim();
		if (message.length > 0) {
			return message;
		}
	}
	if (value && typeof value === "object" && "error" in value) {
		return String((value as { error?: string }).error);
	}
	return "Unable to complete AI review.";
};

export const normalizePatchPath = (value: string) =>
	value
		.trim()
		.replace(/^(\.\/)+/, "")
		.replace(/^[ab]\//, "");

const isLineInHunkRange = (line: number, start: number, count: number) => {
	const safeCount = Math.max(1, count);
	return line >= start && line < start + safeCount;
};

export const findHunkIndexForFinding = (
	file: FileDiffMetadata,
	finding: ReviewFinding,
) => {
	for (let index = 0; index < file.hunks.length; index += 1) {
		const hunk = file.hunks[index];
		const inRange =
			finding.side === "deletions"
				? isLineInHunkRange(
						finding.line,
						hunk.deletionStart,
						hunk.deletionCount,
					)
				: isLineInHunkRange(
						finding.line,
						hunk.additionStart,
						hunk.additionCount,
					);
		if (inRange) {
			return index;
		}
	}

	return -1;
};

const toReviewSide = (value: unknown): ReviewFinding["side"] => {
	const normalized = String(value ?? "")
		.trim()
		.toLowerCase();
	if (
		normalized === "deletions" ||
		normalized === "deletion" ||
		normalized === "removed" ||
		normalized === "left"
	) {
		return "deletions";
	}
	return "additions";
};

const toReviewSeverity = (value: unknown): ReviewFinding["severity"] => {
	const normalized = String(value ?? "")
		.trim()
		.toLowerCase();
	if (normalized === "high") {
		return "high";
	}
	if (normalized === "medium" || normalized === "med") {
		return "med";
	}
	return "low";
};

const toReviewConfidence = (value: unknown) => {
	if (typeof value !== "number" || !Number.isFinite(value)) {
		return 0.7;
	}
	return Math.max(0, Math.min(1, value));
};

const toReviewEvidence = (value: unknown) => {
	if (typeof value !== "string") {
		return "";
	}
	return value.trim();
};

const toReviewFeedback = (value: unknown): ReviewFeedback | null => {
	if (value === "up" || value === "down") {
		return value;
	}
	return null;
};

const normalizeCommentFeedbackByKey = (
	value: unknown,
): Record<string, ReviewFeedback> => {
	if (!value || typeof value !== "object") {
		return {};
	}

	const next: Record<string, ReviewFeedback> = {};
	for (const [commentKey, feedback] of Object.entries(
		value as Record<string, unknown>,
	)) {
		const normalizedKey = commentKey.trim();
		const normalizedFeedback = toReviewFeedback(feedback);
		if (!normalizedKey || !normalizedFeedback) {
			continue;
		}
		next[normalizedKey] = normalizedFeedback;
	}

	return next;
};

const normalizeCommentPublishByKey = (
	value: unknown,
): Record<string, ReviewCommentPublishState> => {
	if (!value || typeof value !== "object") {
		return {};
	}

	const next: Record<string, ReviewCommentPublishState> = {};
	for (const [commentKey, state] of Object.entries(
		value as Record<string, unknown>,
	)) {
		if (!state || typeof state !== "object" || Array.isArray(state)) {
			continue;
		}
		const normalizedKey = commentKey.trim();
		if (!normalizedKey) {
			continue;
		}
		const record = state as Record<string, unknown>;
		const rawStatus = String(record.status ?? "").trim();
		if (
			rawStatus !== "pending" &&
			rawStatus !== "processing" &&
			rawStatus !== "failed" &&
			rawStatus !== "succeeded" &&
			rawStatus !== "dead"
		) {
			continue;
		}

		const attempts = Number(record.attempts);
		const discussionId = String(record.discussionId ?? "").trim();
		const noteId = String(record.noteId ?? "").trim();
		next[normalizedKey] = {
			status: rawStatus,
			attempts: Number.isFinite(attempts) ? Math.max(0, Math.floor(attempts)) : 0,
			lastError: String(record.lastError ?? "").trim(),
			discussionId: discussionId.length > 0 ? discussionId : null,
			noteId: noteId.length > 0 ? noteId : null,
			updatedAt: String(record.updatedAt ?? "").trim(),
		};
	}

	return next;
};

const normalizeImpactByKey = (
	value: unknown,
): Record<string, ReviewFindingImpact> => {
	if (!value || typeof value !== "object") {
		return {};
	}

	const next: Record<string, ReviewFindingImpact> = {};
	for (const [commentKey, impact] of Object.entries(

	value as Record<string, unknown>,
)) {
	if (!impact || typeof impact !== "object" || Array.isArray(impact)) {
		continue;
	}
	const record = impact as Record<string, unknown>;
	const normalizedCommentKey = String(commentKey).trim();
	const status = String(record.status ?? "").trim();
	if (
		!normalizedCommentKey ||
		(status !== "pending" &&
			status !== "succeeded" &&
			status !== "failed")
	) {
		continue;
	}

	const scope = String(record.scope ?? "").trim();
	const sourceNodeId = String(record.sourceNodeId ?? "").trim();
	const sourceFile = String(record.sourceFile ?? "").trim();
	const sourceLine = Number(record.sourceLine);
	const impactLevel = String(record.impactLevel ?? "").trim();
	const rawImpactScore = record.impactScore;
	const impactScore =
		rawImpactScore === null ||
		rawImpactScore === undefined ||
		(typeof rawImpactScore === "string" &&
			rawImpactScore.trim().length === 0)
			? null
			: Number(rawImpactScore);
	const callersCount = Number(record.callersCount);
	const calleesCount = Number(record.calleesCount);
	const dependentsCount = Number(record.dependentsCount);
	const dependenciesCount = Number(record.dependenciesCount);
	const affectedFilesCount = Number(record.affectedFilesCount);
	const affectedSymbolsCount = Number(record.affectedSymbolsCount);

const topImpactedFiles = Array.isArray(record.topImpactedFiles)
	? record.topImpactedFiles
			.map((item) => {
				if (
					!item ||
					typeof item !== "object" ||
					Array.isArray(item)
				) {
					return null;
				}
				const filePath = String(
					(item as { filePath?: unknown }).filePath ?? "",
				).trim();
				const count = Number((item as { count?: unknown }).count);
				if (!filePath) {
					return null;
				}
				return {
					filePath,
					count: Number.isFinite(count)
						? Math.max(0, Math.floor(count))
						: 0,
				};
			})
			.filter(
				(item): item is { filePath: string; count: number } =>
					item !== null,
			)
	: [];

const review = value as Record<string, unknown>;
const reviewId = String(review.reviewId ?? "").trim();
const status = String(review.status ?? "").trim();
if (
	!reviewId ||
	(status !== "not_started" &&
		status !== "in_progress" &&
		status !== "completed" &&
		status !== "partial" &&
		status !== "failed" &&
		status !== "pending_graph")
) {
	return null;
}

const graph = (() => {
	const graphValue = review.graph;
	if (!graphValue || typeof graphValue !== "object" || Array.isArray(graphValue)) {
		return null;
	}

	const record = graphValue as Record<string, unknown>;
	const indexRunId = String(record.indexRunId ?? "").trim();
	const generatedAt = String(record.generatedAt ?? "").trim();
	if (!indexRunId || !generatedAt) {
		return null;
	}
	return { indexRunId, generatedAt };
})();

const indexing = (() => {
	const indexingValue = review.indexing;
	if (
		!indexingValue ||
		typeof indexingValue !== "object" ||
		Array.isArray(indexingValue)
	) {
		return {
			graphResolutionStatus: "not_checked" as const,
			graphPendingReason: null,
			branch: null,
			integrationId: null,
		};
	}

	const record = indexingValue as Record<string, unknown>;
	const graphResolutionStatus = String(
		record.graphResolutionStatus ?? "",
	).trim();
	const normalizedStatus: ReviewImpactPayload["indexing"]["graphResolutionStatus"] =
		graphResolutionStatus === "ready" ||
		graphResolutionStatus === "pending_graph" ||
		graphResolutionStatus === "error" ||
		graphResolutionStatus === "not_checked"
			? graphResolutionStatus
			: "not_checked";
	const graphPendingReason =
		typeof record.graphPendingReason === "string"
			? record.graphPendingReason.trim() || null
			: null;
	const branch =
		typeof record.branch === "string" ? record.branch.trim() || null : null;
	const integrationId =
		typeof record.integrationId === "string"
			? record.integrationId.trim() || null
			: null;
	return {
		graphResolutionStatus: normalizedStatus,
		graphPendingReason,
		branch,
		integrationId,
	};
})();

return {
	reviewId,
	status,
	impactByKey: normalizeImpactByKey(review.impactByKey),
	graph,
	indexing,
};

};

export const normalizeReviewFindings = (value: unknown): ReviewFinding[] => {
	if (!Array.isArray(value)) {
		return [];
	}

	return value
		.map<ReviewFinding | null>((item) => {
			if (!item || typeof item !== "object") {
				return null;
			}

			const finding = item as Record<string, unknown>;
			const file = String(finding.file ?? "").trim();
			const line = Number(finding.line);
			const title = String(finding.title ?? "").trim();
			const body = String(finding.body ?? finding.explanation ?? "").trim();

			if (!file || !title || !body || !Number.isFinite(line) || line < 1) {
				return null;
			}

			return {
				file,
				line: Math.floor(line),
				side: toReviewSide(finding.side),
				severity: toReviewSeverity(finding.severity),
				title,
				body,
				confidence: toReviewConfidence(finding.confidence),
				evidence: toReviewEvidence(finding.evidence),
				persona: finding.persona ? normalizeReviewPersona(finding.persona) : undefined,
				personas: Array.isArray(finding.personas)
					? finding.personas
							.map((persona) => normalizeReviewPersona(persona))
							.filter((persona, index, all) => all.indexOf(persona) === index)
					: undefined,
			} satisfies ReviewFinding;
		})
		.filter((item): item is ReviewFinding => item !== null);
};

export const normalizePersistedReview = (
	value: unknown,
): PersistedReview | null => {
	if (!value || typeof value !== "object") {
		return null;
	}

	const review = value as Record<string, unknown>;
	const id = String(review.id ?? "").trim();
	const summary = String(review.summary ?? "").trim();
	const createdAt = String(review.createdAt ?? "").trim();
	const findings = normalizeReviewFindings(review.findings);

	if (!id || !createdAt) {
		return null;
	}

	return {
		id,
		summary,
		findings,
		personaMode: normalizeReviewPersonaMode(review.personaMode),
		persona: normalizeReviewPersona(review.persona),
		personaPasses: Array.isArray(review.personaPasses)
			? review.personaPasses
					.map((entry) => String(entry ?? "").trim())
					.filter((entry) => entry.length > 0)
			: [],
		feedback: toReviewFeedback(review.feedback),
		commentFeedbackByKey: normalizeCommentFeedbackByKey(
			review.commentFeedbackByKey,
		),
		commentPublishByKey: normalizeCommentPublishByKey(
			review.commentPublishByKey,
		),
		createdAt,
	};
};

export const normalizePersistedDescription = (
	value: unknown,
): PersistedDescription | null => {
	if (!value || typeof value !== "object") {
		return null;
	}

	const description = value as Record<string, unknown>;
	const id = String(description.id ?? "").trim();
	const markdown = String(description.markdown ?? "").trim();
	const createdAt = String(description.createdAt ?? "").trim();

	if (!id || !createdAt || !markdown) {
		return null;
	}

	return {
		id,
		markdown,
		createdAt,
	};
};

export const getFileLabel = (file: FileDiffMetadata) => {
	if (file.prevName && file.prevName !== file.name) {
		return `${file.prevName} -> ${file.name}`;
	}

	return file.name;
};

export const getStableFileKey = (
	file: Pick<FileDiffMetadata, "cacheKey" | "prevName" | "name">,
) => {
	return file.cacheKey ?? `${file.prevName ?? ""}->${file.name}`;
};

export const splitPatchIntoFileChunks = (patchText: string) => {
	const splitByFile = patchText.split(/^diff --git /m);
	if (splitByFile.length <= 1) {
		return [];
	}

	const metadataPrefix = splitByFile[0].trim();

	return splitByFile
		.slice(1)
		.map((part, index) => {
			const chunk = `diff --git ${part}`.trim();
			if (!chunk) {
				return "";
			}
			if (index === 0 && metadataPrefix) {
				return `${metadataPrefix}\n${chunk}`;
			}
			return chunk;
		})
		.filter((chunk): chunk is string => chunk.length > 0);
};

export type ParsePatchResult = {
	files: FileDiffMetadata[];
	parseError: string;
};

export type PendingParseRequest = {
	resolve: (value: ParsePatchResult) => void;
	reject: (reason?: unknown) => void;
};

export type DiffLoadProfile = {
	fetchMs: number | null;
	firstParseMs: number | null;
	fullParseMs: number | null;
};

export const getNow = () =>
	typeof performance === "undefined" ? Date.now() : performance.now();

let parsePatchFilesModulePromise: Promise<
	typeof import("@pierre/diffs")
> | null = null;
export const getParsePatchFilesModule = async () => {
	parsePatchFilesModulePromise ??= import("@pierre/diffs");
	return await parsePatchFilesModulePromise;
};

if (!parsed.success) {
  return {
    status: 400,
    outcome: 'invalid_request',
    response: NextResponse.json({ error: 'Invalid search payload.' }, { status: 400 }),
  }
}

const { integrationId, branch, query, configHash } = parsed.data
const limit = parsed.data.limit ?? 10
const oversample = parsed.data.oversample ?? 5

const integration = await getUserIntegration(integrationId, userId)
if (!integration) {
  return {
    status: 404,
    outcome: 'not_found',
    response: NextResponse.json({ error: 'Integration not found.' }, { status: 404 }),
  }
}

const branchWhere = and(
  eq(indexBranchStates.integrationId, integration.id),
  eq(indexBranchStates.branch, branch),
  ...(configHash ? [eq(indexBranchStates.configHash, configHash)] : []),
)

const embeddingTelemetry: {
  requestCount: number
  failureCount: number
  promptTokens: number
  totalTokens: number
  costUsd: number | null
  model: string | null
  provider: string | null
} = {
  requestCount: 0,
  failureCount: 0,
  promptTokens: 0,
  totalTokens: 0,
  costUsd: null,
  model: null,
  provider: null,
}

const [branchState] = await db
  .select({
    id: indexBranchStates.id,
    configHash: indexBranchStates.configHash,
    lastReadySha: indexBranchStates.lastReadySha,
    lastReadyRunId: indexBranchStates.lastReadyRunId,
    updatedAt: indexBranchStates.updatedAt,
  })
  .from(indexBranchStates)
  .where(branchWhere)
  .orderBy(desc(indexBranchStates.updatedAt))
  .limit(1)

if (!branchState) {
  return {
    status: 404,
    outcome: 'not_ready',
    response: NextResponse.json({ error: 'No indexed branch state found.' }, { status: 404 }),
  }
}

if (!branchState.lastReadySha || !branchState.lastReadyRunId) {
  return {
    status: 409,
    outcome: 'not_ready',
    response: NextResponse.json({ error: 'Branch is not ready for search.' }, { status: 409 }),
  }
}

const embedding = await embedQueryText(query, {
  onTelemetry: (telemetry) => {
    embeddingTelemetry.requestCount = telemetry.requestCount
    embeddingTelemetry.failureCount = telemetry.failureCount
    embeddingTelemetry.promptTokens = telemetry.promptTokens
    embeddingTelemetry.totalTokens = telemetry.totalTokens
    embeddingTelemetry.costUsd = telemetry.costUsd
    embeddingTelemetry.model = telemetry.model
    embeddingTelemetry.provider = telemetry.provider
  },
})
const vectorStore = createPostgresVectorStore()

const candidates = await vectorStore.queryCandidates({
  branchStateId: branchState.id,
  embedding,
  limit,
  oversample,
})

const seen = new Set<string>()
const filtered = [] as typeof candidates
for (const candidate of candidates) {
  const dedupeKey = `${candidate.path}:${candidate.fileId}:${candidate.chunkIndex}`
  if (seen.has(dedupeKey)) {
    continue
  }

  seen.add(dedupeKey)
  filtered.push(candidate)

  if (filtered.length >= limit) {
    break
  }
}

logger.set({
  integrationId,
  branch,
  queryLength: query.length,
  count: filtered.length,
  labels: {
    provider: embeddingTelemetry.provider,
    model: embeddingTelemetry.model,
  },
  indexingMetrics: {
    durationMs: null,
    filesProcessed: 1,
    failures: embeddingTelemetry.failureCount,
    embeddingApiCalls: embeddingTelemetry.requestCount,
    pendingJobs: null,
    processingJobs: null,
  },
  llmMetrics: {
    provider: embeddingTelemetry.provider,
    model: embeddingTelemetry.model,
    promptTokens: embeddingTelemetry.promptTokens,
    completionTokens: 0,
    totalTokens: embeddingTelemetry.totalTokens,
    latencyMs: null,
    costUsd: embeddingTelemetry.costUsd,
    requestCount: embeddingTelemetry.requestCount,
  },
})

      return {
        status: 200,
        outcome: 'success',
        response: NextResponse.json({
          data: {
            integrationId,
            branch,
            configHash: branchState.configHash,
            lastReadySha: branchState.lastReadySha,
            count: filtered.length,
            results: filtered,
          },
        }),
      }
    },
  })
}

import { afterEach, beforeEach, describe, expect, mock, test } from "bun:test"

import {
  consumeRouteNavigationSample,
  markRouteNavigationStart,
  markRoutePrefetched,
  prefetchRouteOnce,
} from "@/lib/navigation/perf-navigation"

const originalWindowDescriptor = Object.getOwnPropertyDescriptor(globalThis, "window")

const installWindow = (origin = "https://argus.local") => {
  const fakeWindow = {
    location: { origin },
  } as unknown as Window
  Object.defineProperty(globalThis, "window", {
    configurable: true,
    writable: true,
    value: fakeWindow,
  })
}

const restoreWindow = () => {
  if (originalWindowDescriptor) {
    Object.defineProperty(globalThis, "window", originalWindowDescriptor)
    return
  }
  Reflect.deleteProperty(globalThis, "window")
}

describe("perf-navigation", () => {
  let nowMs = 0
  const originalPerformanceNowDescriptor =
    Object.getOwnPropertyDescriptor(performance, "now") ??
    Object.getOwnPropertyDescriptor(Object.getPrototypeOf(performance), "now")

  beforeEach(() => {
    installWindow()
    nowMs = 1_000
    Object.defineProperty(performance, "now", {
      configurable: true,
      value: () => nowMs,
    })
  })

  afterEach(() => {
    mock.restore()
    if (originalPerformanceNowDescriptor) {
      Object.defineProperty(performance, "now", originalPerformanceNowDescriptor)
    }
    restoreWindow()
  })

test("prefetches once and marks prefetched routes as warm", () => {
  const prefetchedHrefs = new Set<string>()
  const calls: string[] = []

  const firstCall = prefetchRouteOnce({
    href: " /code-graph ",
    prefetchedHrefs,
    prefetch: (href) => calls.push(href),
  })
  const secondCall = prefetchRouteOnce({
    href: "/code-graph",
    prefetchedHrefs,
    prefetch: (href) => calls.push(href),
  })

  expect(firstCall).toBe(true)
  expect(secondCall).toBe(false)
  expect(calls).toEqual(["/code-graph"])
  expect(markRouteNavigationStart({ href: "/code-graph", source: "sidebar" })?.prefetchHit).toBe(true)
})

test("expires stale prefetch markers", () => {
  expect(markRoutePrefetched("/settings")).toBe(true)
  nowMs += 30_001

  const sample = markRouteNavigationStart({
    href: "/settings",
    source: "sidebar",
  })

  expect(sample?.prefetchHit).toBe(false)
})

test("consumes pending samples exactly once and computes duration", () => {
  expect(
    markRouteNavigationStart({
      href: "/repos/acme/mrs/1",
      source: "repo_merge_requests",
    }),
  ).not.toBeNull()
  nowMs += 157.2

  const sample = consumeRouteNavigationSample("/repos/acme/mrs/1")
  expect(sample?.navDurationMs).toBe(157)
  expect(consumeRouteNavigationSample("/repos/acme/mrs/1")).toBeNull()
})

  test("rejects external routes and blank sources", () => {
    expect(markRoutePrefetched("https://example.com/outside")).toBe(false)
    expect(
      markRouteNavigationStart({
        href: "https://example.com/outside",
        source: "sidebar",
      }),
    ).toBeNull()
    expect(markRouteNavigationStart({ href: "/settings", source: "   " })).toBeNull()
  })
})

