}

.docs-nav-link-title {
  font-size: 0.92rem;
  font-weight: 600;
}

.docs-nav-link-description {
  font-size: 0.78rem;
  color: var(--docs-muted);
}

.docs-main {
  min-width: 0;
}

.docs-article {
  background: var(--docs-surface);
  border: 1px solid var(--docs-border);
  border-radius: 20px;
  box-shadow: 0 10px 40px rgba(29, 32, 41, 0.05);
  padding: 26px 24px;
}

.docs-article > :first-child {
  margin-top: 0;
}

.docs-article > :last-child {
  margin-bottom: 0;
}

.docs-article h1,
.docs-article h2,
.docs-article h3 {
  margin: 1.4em 0 0.5em;
  line-height: 1.2;
}

.docs-article h1 {
  margin-top: 0;
  font-size: clamp(1.8rem, 2.5vw, 2.28rem);
}

.docs-article h2 {
  font-size: clamp(1.35rem, 2vw, 1.72rem);
}

.docs-article h3 {
  font-size: 1.18rem;
}

.docs-article ul,
.docs-article ol {
  padding-left: 1.3rem;
}

.docs-article hr {
  border: 0;
  border-top: 1px solid var(--docs-border);
  margin: 1.5rem 0;
}

.docs-link {
  color: var(--docs-accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.docs-link:hover {
