    expect(source.includes("dynamic(")).toBe(true)
  })
})

const DEFAULT_ROUTE_PREWARM_DEBOUNCE_MS = 65

type TimerHandle = ReturnType<typeof setTimeout>

type RoutePrewarmPointerLikeEvent = {
  button: number
  pointerType?: string | null
}

type RoutePrewarmIntentHandlers<TPointerEvent = RoutePrewarmPointerLikeEvent> = {
  onMouseEnter: () => void
  onFocus: () => void
  onTouchStart: () => void
  onPointerDown: (event: TPointerEvent) => void
  onMouseLeave: () => void
  onBlur: () => void
}

type CreateRoutePrewarmIntentControllerOptions = {
  onPrewarm: (href: string) => void
  debounceMs?: number
}

type RoutePrewarmIntentController = {
  getRoutePrewarmIntentHandlers: (href: string) => RoutePrewarmIntentHandlers
  prewarmRouteNow: (href: string) => void
  scheduleRoutePrewarm: (href: string) => void
  cancelRoutePrewarm: (href: string) => void
  dispose: () => void
}

const isPrimaryMousePointerDown = (event: RoutePrewarmPointerLikeEvent) =>
  event.button === 0 && (event.pointerType === undefined || event.pointerType === null || event.pointerType === "mouse")

export const createRoutePrewarmIntentController = ({

  onPrewarm,
  debounceMs = DEFAULT_ROUTE_PREWARM_DEBOUNCE_MS,
}: CreateRoutePrewarmIntentControllerOptions): RoutePrewarmIntentController => {
  const timersByHref = new Map<string, TimerHandle>()

  const cancelRoutePrewarm = (href: string) => {
    const pendingTimer = timersByHref.get(href)
    if (pendingTimer) {
      clearTimeout(pendingTimer)
      timersByHref.delete(href)
    }
  }

  const prewarmRouteNow = (href: string) => {
    cancelRoutePrewarm(href)
    onPrewarm(href)
  }

  const scheduleRoutePrewarm = (href: string) => {
    cancelRoutePrewarm(href)
    const nextTimer = setTimeout(() => {
      timersByHref.delete(href)
      onPrewarm(href)
    }, debounceMs)
    timersByHref.set(href, nextTimer)
  }

  const getRoutePrewarmIntentHandlers = (href: string): RoutePrewarmIntentHandlers => ({
    onMouseEnter: () => {
      scheduleRoutePrewarm(href)
    },
    onFocus: () => {
      scheduleRoutePrewarm(href)
    },
    onTouchStart: () => {
      prewarmRouteNow(href)
    },
    onPointerDown: (event) => {
      if (!isPrimaryMousePointerDown(event)) {
        return
      }
      prewarmRouteNow(href)
    },
    onMouseLeave: () => {
      cancelRoutePrewarm(href)
    },
    onBlur: () => {
      cancelRoutePrewarm(href)
    },
  })

  const dispose = () => {
    for (const pendingTimer of timersByHref.values()) {
      clearTimeout(pendingTimer)
    }
    timersByHref.clear()
  }

  return {
    getRoutePrewarmIntentHandlers,
    prewarmRouteNow,
    scheduleRoutePrewarm,
    cancelRoutePrewarm,
    dispose,
  }
}

