type ReviewScope = {
  instanceUrl: string
  projectId: string
  mergeRequestIid: string
}

type PersistedReview = {
  id: string
  summary: string
  findings: AiReviewFinding[]
  personaMode: "disabled" | "single" | "multi"
  persona: "generalist" | "security" | "performance" | "maintainability"
  personaPasses: string[]
  feedback: "up" | "down" | null
  commentFeedbackByKey: Record<string, "up" | "down">
  commentPublishByKey: Record<string, {
    status: "pending" | "processing" | "failed" | "succeeded" | "dead"
    attempts: number
    lastError: string
    discussionId: string | null
    noteId: string | null
    updatedAt: string
  }>
  createdAt: string
}

type ReviewRequestPayload = {
  patch?: unknown
  instanceUrl?: unknown
  projectId?: unknown
  mergeRequestIid?: unknown
  integrationId?: unknown
  force?: unknown
}

const asOptionalString = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

const asBoolean = (value: unknown) => value === true

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const resolveReviewScopeFromSearchParams = (params: URLSearchParams): ReviewScope | null => {
  const instanceUrl = normalizeApiUrl(params.get("instanceUrl") ?? "")
  const projectId = (params.get("projectId") ?? "").trim()
  const mergeRequestIid = (params.get("mergeRequestIid") ?? "").trim()
  if (!instanceUrl || !projectId || !mergeRequestIid) {
    return null
  }
  return {
    instanceUrl,
    projectId,
    mergeRequestIid,
  }
}

const resolveReviewScopeFromPayload = (payload: ReviewRequestPayload | null): ReviewScope | null => {
  const instanceUrl = normalizeApiUrl(String(payload?.instanceUrl ?? "").trim())
  const projectId = String(payload?.projectId ?? "").trim()
  const mergeRequestIid = String(payload?.mergeRequestIid ?? "").trim()
  if (!instanceUrl || !projectId || !mergeRequestIid) {
    return null
  }
  return {
    instanceUrl,
    projectId,
    mergeRequestIid,
  }
}

