export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/diff",
    event: "api.review.diff",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "Patch is required."),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const payload = body.value as ReviewRequestPayload | null
      const patch = String(payload?.patch ?? "")
      const scope = resolveReviewScopeFromPayload(payload)
      const integrationId = asOptionalString(payload?.integrationId)
      const force = asBoolean(payload?.force)

if (!patch.trim()) {
  return {
    status: 400,
    outcome: "invalid_request",
