})
const effectiveGateSettings = normalizeReviewGateSettings(gatePreferences.effectiveSettings)
const reviewPersonaMode = normalizeReviewPersonaMode(effectiveGateSettings.personaMode)
const reviewPersona =
  reviewPersonaMode === "single"
    ? normalizeReviewPersona(effectiveGateSettings.persona)
    : "generalist"
const reviewPersonaPasses = getReviewPersonaPasses(effectiveGateSettings)

const hasCustomPersonaTemplates =
  Object.keys(effectiveGateSettings.personaTemplates).length > 0

const patchHash = sha256Hex(patch)
const reviewBatchCount = buildReviewBatches(patch).length
const personaPassCount =
  reviewPersonaMode === "disabled" ? 1 : Math.max(1, reviewPersonaPasses.length)
const totalBatches = reviewBatchCount * personaPassCount
const skipSamePatchReuse = force || hasCustomPersonaTemplates
if (!skipSamePatchReuse) {
  const dedupeCandidate = await findReviewRunDedupeCandidate({
