import {
  type DiscoverableProject,
  type InstanceSeed,
  type ReviewProject,
} from "./types"

export const REPO_DIALOG_CACHE_TTL_MS = 45_000

export type DiscoverableProjectsCacheEntry = {
  expiresAt: number
  seedKey: string
  projects: DiscoverableProject[]
  failureCount: number
  instanceCount: number
}

export const getFreshDiscoverableProjectsCache = (
  cache: Map<string, DiscoverableProjectsCacheEntry>,
  cacheKey: string,
) => {
  const cached = cache.get(cacheKey)
  if (!cached) {
    return null
  }

  if (cached.expiresAt <= Date.now()) {
    cache.delete(cacheKey)
    return null
  }

  return cached
}

export const setDiscoverableProjectsCache = (
  cache: Map<string, DiscoverableProjectsCacheEntry>,
  cacheKey: string,
  seedKey: string,
  projects: DiscoverableProject[],
  failureCount: number,
  instanceCount: number,
) => {
  cache.set(cacheKey, {
    expiresAt: Date.now() + REPO_DIALOG_CACHE_TTL_MS,
    seedKey,
    projects,
    failureCount,
    instanceCount,
  })
}

export const buildInstanceSeedCacheKey = (seeds: InstanceSeed[]) =>
  seeds
    .map((seed) => `${seed.instanceUrl.trim().toLowerCase()}::${seed.integrationId.trim()}`)
    .sort()
    .join("|")

export const buildDiscoverableProjectsScopeKey = (projects: ReviewProject[]) =>
  projects
    .map((project) =>
      `${project.instanceUrl.trim().toLowerCase()}::${project.projectId.trim()}::${project.id.trim()}`,
    )
    .sort()
    .join("|")

export const asDateValue = (value: string | null | undefined) => {
  if (!value) {
    return 0
  }

  const parsed = new Date(value)
  return Number.isNaN(parsed.getTime()) ? 0 : parsed.getTime()
}

export const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null

export const buildProjectScopeKey = (instanceUrl: string, projectId: string) =>
  `${instanceUrl.trim().toLowerCase()}::${projectId.trim()}`

export const getApiErrorMessage = (payload: unknown, fallback: string) => {
  if (isRecord(payload) && typeof payload.error === "string") {
    return payload.error
  }

  return fallback
}

export const getDiscoverProjectsResult = (failureCount: number, instanceCount: number) => {
  if (failureCount === instanceCount) {
    return {
      state: "error" as const,
      status: "Could not load repositories from connected GitLab instances.",
    }
  }

  return {
    state: "ready" as const,
    status:
      failureCount > 0
        ? "Loaded repositories from available instances. Some instances failed."
        : "",
  }
}

