const normalizeEnvValue = (value: string | undefined) => value?.trim()

const formatEnvName = (name: string | undefined) => (name ? ` for ${name}` : "")

export const parsePositiveInt = (value: string | undefined, fallback: number, envName?: string) => {
  const normalized = normalizeEnvValue(value)
  if (!normalized) {
    return fallback
  }

  const parsed = Number.parseInt(normalized, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error(`Invalid positive integer${formatEnvName(envName)}. Received "${normalized}".`)
  }

  return parsed
}

export const parseBoolean = (value: string | undefined, envName?: string): boolean | undefined => {
  const normalized = normalizeEnvValue(value)
  if (!normalized) {
    return undefined
  }

  const lowered = normalized.toLowerCase()
  if (lowered === "1" || lowered === "true" || lowered === "yes" || lowered === "on") {
    return true
  }
  if (lowered === "0" || lowered === "false" || lowered === "no" || lowered === "off") {
    return false
  }

  throw new Error(
    `Invalid boolean${formatEnvName(envName)}. Expected one of: 1, 0, true, false, yes, no, on, off.`,
  )
}

export type IndexerWorkerConfig = {
  service: string
  environment: string
  version: string | undefined
  pretty: boolean | undefined
  batchSize: number
  pollIntervalMs: number
  continuous: boolean
}

const resolveDefaultEnv = (): Record<string, string | undefined> => {
  const processEnv = (
    globalThis as { process?: { env?: Record<string, string | undefined> } }
  ).process?.env
  return processEnv ?? {}
}

export const resolveIndexerWorkerConfig = (
  env: Record<string, string | undefined> = resolveDefaultEnv(),
): IndexerWorkerConfig => ({
  service: env.INDEXER_SERVICE_NAME?.trim() || "argus-indexer-worker",
  environment: env.INDEXER_ENVIRONMENT?.trim() || env.NODE_ENV || "development",
  version: env.INDEXER_SERVICE_VERSION?.trim() || env.npm_package_version,
  pretty: parseBoolean(env.INDEXER_LOG_PRETTY, "INDEXER_LOG_PRETTY"),
  batchSize: parsePositiveInt(env.INDEXER_BATCH_SIZE, 25, "INDEXER_BATCH_SIZE"),
  pollIntervalMs: parsePositiveInt(env.INDEXER_POLL_MS, 30_000, "INDEXER_POLL_MS"),
  continuous: env.INDEXER_CONTINUOUS === "1",
})

