import { useEffect, useRef, type MutableRefObject } from "react"

import type {
  MergeRequest,
  OnboardingRouteStep,
  Project,
} from "@/features/onboarding/model/types"

type UseOnboardingDigitShortcutsOptions = {
  isHydrated: boolean
  routeStep: OnboardingRouteStep
  actionBusy: boolean
  recentProjects: Project[]
  mergeRequests: MergeRequest[]
  shortcutLimit: number
  projectSelectionHandlerRef: MutableRefObject<((projectId: string) => Promise<void>) | null>
  mergeRequestSelectionHandlerRef: MutableRefObject<((mrId: string) => void) | null>
}

export function useOnboardingDigitShortcuts({
  isHydrated,
  routeStep,
  actionBusy,
  recentProjects,
  mergeRequests,
  shortcutLimit,
  projectSelectionHandlerRef,
  mergeRequestSelectionHandlerRef,
}: UseOnboardingDigitShortcutsOptions) {
  const isHydratedRef = useRef(isHydrated)
  const routeStepRef = useRef(routeStep)
  const actionBusyRef = useRef(actionBusy)
  const recentProjectsRef = useRef(recentProjects)
  const mergeRequestsRef = useRef(mergeRequests)
  const shortcutLimitRef = useRef(shortcutLimit)

  useEffect(() => {
    isHydratedRef.current = isHydrated
  }, [isHydrated])

  useEffect(() => {
    routeStepRef.current = routeStep
  }, [routeStep])

  useEffect(() => {
    actionBusyRef.current = actionBusy
  }, [actionBusy])

  useEffect(() => {
    recentProjectsRef.current = recentProjects
  }, [recentProjects])

  useEffect(() => {
    mergeRequestsRef.current = mergeRequests
  }, [mergeRequests])

  useEffect(() => {
    shortcutLimitRef.current = shortcutLimit
  }, [shortcutLimit])

useEffect(() => {
  // Keep one listener bound and read current data via refs to avoid rebinding
  // on array identity changes from upstream queries/state.
  const onKeyDown = (event: KeyboardEvent) => {
    const currentIsHydrated = isHydratedRef.current
    const currentActionBusy = actionBusyRef.current
    const currentRouteStep = routeStepRef.current
    const currentRecentProjects = recentProjectsRef.current
    const currentMergeRequests = mergeRequestsRef.current
    const currentShortcutLimit = shortcutLimitRef.current

    if (
      !currentIsHydrated ||
      currentActionBusy ||
      (currentRouteStep !== "projects" && currentRouteStep !== "mrs") ||
      (currentRouteStep === "projects" && currentRecentProjects.length === 0) ||
      (currentRouteStep === "mrs" && currentMergeRequests.length === 0)
    ) {
      return
    }

    if (
      event.defaultPrevented ||
      event.metaKey ||
      event.ctrlKey ||
      event.altKey ||
      event.repeat
    ) {
      return
    }

    const target = event.target as HTMLElement | null
    if (
      target &&
      (target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.tagName === "SELECT" ||
        target.isContentEditable)
    ) {
      return
    }

    if (!/^[0-9]$/.test(event.key)) {
      return
    }

    const index = event.key === "0" ? currentShortcutLimit - 1 : Number(event.key) - 1

      if (currentRouteStep === "projects") {
        const project = currentRecentProjects[index]
        if (!project) {
          return
        }

        event.preventDefault()
        void projectSelectionHandlerRef.current?.(project.id)
        return
      }

      const mergeRequest = currentMergeRequests[index]
      if (!mergeRequest) {
        return
      }
      event.preventDefault()
      mergeRequestSelectionHandlerRef.current?.(mergeRequest.id)
    }

    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [mergeRequestSelectionHandlerRef, projectSelectionHandlerRef])
}

