      eq(indexJobs.branch, branch),
      eq(indexJobs.configHash, configHash),
      inArray(indexJobs.status, ACTIVE_PLAN_JOB_STATUSES),
    ),
    orderBy: [desc(indexJobs.updatedAt)],
    columns: {
      id: true,
      debounceKey: true,
      status: true,
    },
