      eq(indexRuns.branchStateId, branchStateId),
      eq(indexRuns.headSha, headSha),
      inArray(indexRuns.status, ACTIVE_RUN_STATUSES),
    ),
    orderBy: [desc(indexRuns.updatedAt)],
    columns: {
      id: true,
      status: true,
    },
  })

  if (!row || (row.status !== 'planned' && row.status !== 'ingesting' && row.status !== 'indexing')) {
