  isBranchGraphReady: async ({ integrationId, branch }) => {
    const latestBranchState = await db.query.indexBranchStates.findFirst({
      where: and(
        eq(indexBranchStates.integrationId, integrationId),
        eq(indexBranchStates.branch, branch),
      ),
      orderBy: [desc(indexBranchStates.updatedAt)],
      columns: {
        lastReadyRunId: true,
      },
    })
    const lastReadyRunId = latestBranchState?.lastReadyRunId
    if (!lastReadyRunId) {
