export type ParsedJsonResponse =
  | {
      ok: true
      value: unknown
      isEmpty: boolean
      bodyText: string
    }
  | {
      ok: false
      bodyText: string
    }

/**
 * Parse a `fetch` response body once and preserve both parsed JSON and raw text.
 *
 * Use this on client/server fetch callers that need predictable handling for:
 * - valid JSON payloads,
 * - empty bodies, and
 * - non-JSON error bodies.
 *
 * Callers should branch on `parsed.ok` explicitly instead of silently falling
 * back to `null` payloads.
 */
export const parseJsonResponse = async (response: Response): Promise<ParsedJsonResponse> => {
  let bodyText = ""
  try {
    bodyText = await response.text()
  } catch {
    return {
      ok: false,
      bodyText: "",
    }
  }

  if (bodyText.trim().length === 0) {
    return {
      ok: true,
      value: null,
      isEmpty: true,
      bodyText,
    }
  }

  try {
    return {
      ok: true,
      value: JSON.parse(bodyText) as unknown,
      isEmpty: false,
      bodyText,
    }
  } catch {
    return {
      ok: false,
      bodyText,
    }
  }
}

