import { NextResponse } from "next/server"
import { z } from "zod"

import { GitLabDiffServiceError } from "@/lib/gitlab/diff-service/error"
import { getDiffFile } from "@/lib/gitlab/diff-service/service"
import { requireJsonBody } from "@/lib/http/request-json"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const payloadSchema = z.object({
  instanceUrl: z.string().trim().min(1),
  token: z.string().optional(),
  integrationId: z.string().optional(),
  projectId: z.string().trim().min(1),
  mergeRequestIid: z.string().trim().min(1),
  fileId: z.string().trim().min(1),
  cursor: z.string().optional(),
})

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/gitlab/diff/file",
    event: "api.gitlab.diff.file",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "Invalid diff file payload."),
      ])

      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const parsed = payloadSchema.safeParse(body.value)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid diff file payload." }, { status: 400 }),
        }
      }

      try {
        const result = await getDiffFile({
          userId,
          ...parsed.data,
        })

        logger.set({
          fileId: result.data.fileId,
          done: result.data.done,
          chunkCount: result.data.chunks.length,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json(result, {
            headers: {
              "cache-control": "private, no-store",
            },
          }),
        }
      } catch (error) {
        if (error instanceof GitLabDiffServiceError) {
          logger.set({
            errorCode: error.code,
            fileId: parsed.data.fileId,
          })
          return {
            status: error.status,
            outcome: "failed",
            response: NextResponse.json(
              {
                error: error.message,
                code: error.code,
                retryable: error.retryable,
                reconnectRequired: error.reconnectRequired,
                details: error.details,
              },
              { status: error.status },
            ),
          }
        }

        logger.set({
          errorCode: "unknown",
          fileId: parsed.data.fileId,
        })
        return {
          status: 500,
          outcome: "failed",
          response: NextResponse.json(
            { error: "Failed to load merge request diff file." },
            { status: 500 },
          ),
        }
      }
    },
  })
}

