const parseReviewQueueNotification = (raw: string): ReviewQueueNotification | null => {
  try {
    const parsed = JSON.parse(raw) as Partial<ReviewQueueNotification>
    const traceId = String(parsed.traceId ?? "").trim()
    const runId = String(parsed.runId ?? "").trim()
    const at = String(parsed.at ?? "").trim() || new Date().toISOString()
    if (!traceId || !runId) {
      return null
    }
    return {
      traceId,
      runId,
      at,
    }
  } catch {
    return null
  }
}

const parseReviewFlowEventNotification = (raw: string): ReviewFlowEventNotification | null => {
  try {
    const parsed = JSON.parse(raw) as Partial<ReviewFlowEventNotification>
    const traceId = String(parsed.traceId ?? "").trim()
    const flowRunId = String(parsed.flowRunId ?? "").trim()
    const eventType = String(parsed.eventType ?? "").trim() || "progress"
    const eventId =
      typeof parsed.eventId === "number"
        ? Math.max(0, Math.floor(parsed.eventId))
        : Number.parseInt(String(parsed.eventId ?? ""), 10)
    const at = String(parsed.at ?? "").trim() || new Date().toISOString()
    if (!traceId || !flowRunId || !Number.isFinite(eventId) || eventId <= 0) {
      return null
    }
    return {
      traceId,
      flowRunId,
      eventId,
      eventType,
      at,
    }
  } catch {
    return null
  }
}

class PgNotificationHub<TPayload> {
  private handlers = new Set<NotificationHandler<TPayload>>()
  private client: Client | null = null
  private connectPromise: Promise<void> | null = null
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null

  constructor(
    private readonly channel: string,
    private readonly parser: (raw: string) => TPayload | null,
  ) {}

  subscribe(handler: NotificationHandler<TPayload>) {
    if (!REVIEW_FLOW_NOTIFICATIONS_ENABLED) {
      return () => {}
    }

    this.handlers.add(handler)
    void this.ensureConnected()

    return () => {
      this.handlers.delete(handler)
      if (this.handlers.size === 0) {
        void this.disconnect()
      }
    }
  }

private async ensureConnected() {
  if (this.client || this.connectPromise || this.handlers.size === 0) {
    return
  }

  const databaseUrl = resolveDatabaseUrl()
  if (!databaseUrl) {
    return
  }

  this.connectPromise = (async () => {

  const client = new Client({
    connectionString: databaseUrl,
  })

  const handleNotification = (message: Notification) => {
    if (message.channel !== this.channel || typeof message.payload !== "string") {
      return
    }
    const payload = this.parser(message.payload)
    if (!payload) {
      return
    }
    for (const handler of Array.from(this.handlers)) {
      try {
        handler(payload)
      } catch {
        // no-op
      }
    }
  }

  const handleDisconnect = () => {
    if (this.client !== client) {
      return
    }
    this.client = null
    void client.end().catch(() => {})
    if (this.handlers.size > 0) {
      this.scheduleReconnect()
    }
  }

  client.on("notification", handleNotification)
  client.on("error", handleDisconnect)
  client.on("end", handleDisconnect)

  try {
    await client.connect()
    await client.query(`LISTEN ${this.channel}`)
  } catch (error) {
    try {
      await client.end()
    } catch {
      // no-op
    }
    throw error
  }

  if (this.handlers.size === 0) {
    await client.query(`UNLISTEN ${this.channel}`).catch(() => {})
    await client.end().catch(() => {})
    return
  }

  this.client = client
})()
  .catch(() => {
    if (this.handlers.size > 0) {
      this.scheduleReconnect()
    }
  })
  .finally(() => {
    this.connectPromise = null
  })

    await this.connectPromise
  }

  private scheduleReconnect() {
    if (this.reconnectTimer || this.handlers.size === 0) {
      return
    }
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null
      void this.ensureConnected()
    }, REVIEW_NOTIFY_RECONNECT_MS)
  }

  private async disconnect() {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }
    const client = this.client
    this.client = null
    if (!client) {
      return
    }
    try {
      await client.query(`UNLISTEN ${this.channel}`)
    } catch {
      // no-op
    }
    try {
      await client.end()
    } catch {
      // no-op
    }
  }
}

const queueHub = new PgNotificationHub<ReviewQueueNotification>(
  REVIEW_QUEUE_NOTIFY_CHANNEL,
  parseReviewQueueNotification,
)

const eventHub = new PgNotificationHub<ReviewFlowEventNotification>(
  REVIEW_FLOW_EVENT_NOTIFY_CHANNEL,
  parseReviewFlowEventNotification,
)

const emitPgNotification = async (channel: string, payload: Record<string, unknown>) => {
  if (!REVIEW_FLOW_NOTIFICATIONS_ENABLED) {
    return false
  }
  const databaseUrl = resolveDatabaseUrl()
  if (!databaseUrl) {
    return false
  }

  const payloadString = toEventPayloadString(payload)
  if (!payloadString) {
    return false
  }

  try {
    const { db } = await import("@/lib/db")
    await db.execute(
      sql`select pg_notify(${channel}, ${payloadString})`,
    )
    return true
  } catch {
    return false
  }
}

export const notifyReviewRunQueued = async (args: {
  traceId: string
  runId: string
}) =>
  emitPgNotification(REVIEW_QUEUE_NOTIFY_CHANNEL, {
    traceId: args.traceId,
    runId: args.runId,
    at: new Date().toISOString(),
  })

export const notifyReviewFlowEvent = async (args: {
  traceId: string
  flowRunId: string
  eventId: number
  eventType: string
}) =>
  emitPgNotification(REVIEW_FLOW_EVENT_NOTIFY_CHANNEL, {
    traceId: args.traceId,
    flowRunId: args.flowRunId,
    eventId: Math.max(0, Math.floor(args.eventId)),
    eventType: args.eventType.trim() || "progress",
    at: new Date().toISOString(),
  })

export const subscribeToReviewQueueNotifications = (
  handler: NotificationHandler<ReviewQueueNotification>,
) => queueHub.subscribe(handler)

export const subscribeToReviewFlowEventNotifications = (
  handler: NotificationHandler<ReviewFlowEventNotification>,
) => eventHub.subscribe(handler)

export const waitForReviewQueueNotification = async (timeoutMs: number) => {
  if (!REVIEW_FLOW_NOTIFICATIONS_ENABLED) {
    return "disabled" as const
  }

  const boundedTimeoutMs = Math.max(1, Math.floor(timeoutMs))

  return await new Promise<"notified" | "timeout">((resolve) => {
    let settled = false
    const done = (result: "notified" | "timeout") => {
      if (settled) {
        return
      }
      settled = true
      clearTimeout(timer)
      unsubscribe()
      resolve(result)
    }

    const unsubscribe = subscribeToReviewQueueNotifications(() => {
      done("notified")
    })
    const timer = setTimeout(() => {
      done("timeout")
    }, boundedTimeoutMs)
  })
}

