import { parseJsonResponse } from "@/lib/http/response-json"

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

export const getChatCompletionsUrl = (apiUrl: string) => {
  const normalized = normalizeApiUrl(apiUrl)
  if (/\/chat\/completions$/i.test(normalized)) {
    return normalized
  }
  return `${normalized}/chat/completions`
}

export const readProviderError = async (response: Response) => {
  const parsedResponse = await parseJsonResponse(response)
  const trimmed = parsedResponse.bodyText.trim()
  if (!trimmed) {
    return ""
  }

  if (!parsedResponse.ok || parsedResponse.isEmpty) {
    return trimmed.slice(0, 400)
  }

  const root = parsedResponse.value
  if (!root || typeof root !== "object" || Array.isArray(root)) {
    return trimmed.slice(0, 400)
  }

  const payload = root as Record<string, unknown>
  if (typeof payload.error === "string" && payload.error.trim().length > 0) {
    return payload.error.trim().slice(0, 400)
  }
  if (typeof payload.message === "string" && payload.message.trim().length > 0) {
    return payload.message.trim().slice(0, 400)
  }
  if (
    payload.error &&
    typeof payload.error === "object" &&
    !Array.isArray(payload.error)
  ) {
    const nested = payload.error as Record<string, unknown>
    if (typeof nested.message === "string" && nested.message.trim().length > 0) {
      return nested.message.trim().slice(0, 400)
    }
  }

  return trimmed.slice(0, 400)
}

export class LlmProviderHttpError extends Error {
  readonly status: number
  readonly providerError: string

  constructor(status: number, providerError: string) {
    super(`AI provider request failed (${status})${providerError ? `: ${providerError}` : ""}`)
    this.name = "LlmProviderHttpError"
    this.status = status
    this.providerError = providerError
  }
}

export class LlmProviderTimeoutError extends Error {
  readonly timeoutMs: number

  constructor(timeoutMs: number) {
    super(`AI provider request timed out after ${Math.round(timeoutMs / 1000)} seconds.`)
    this.name = "LlmProviderTimeoutError"
    this.timeoutMs = timeoutMs
  }
}

export const requestChatCompletions = async <TPayload>({
  apiUrl,
  token,
  timeoutMs,
  body,
}: {
  apiUrl: string
  token: string
  timeoutMs: number
  body: Record<string, unknown>
}) => {
  const controller = new AbortController()
  const timeout = setTimeout(() => {
    controller.abort()
  }, timeoutMs)
  const startedAt = Date.now()

  try {
    const response = await fetch(getChatCompletionsUrl(apiUrl), {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    })

    if (!response.ok) {
      const providerError = await readProviderError(response)
      throw new LlmProviderHttpError(response.status, providerError)
    }

    const payload = (await response.json()) as TPayload
    return {
      payload,
      latencyMs: Math.max(1, Date.now() - startedAt),
    }
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      throw new LlmProviderTimeoutError(timeoutMs)
    }
    throw error
  } finally {
    clearTimeout(timeout)
  }
}

