    event: "api.review.preferences.project.delete",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "instanceUrl and projectId are required."),
      ])

      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const payload = body.value
      const scope = normalizeReviewGateScope(
        payload && typeof payload === "object"
          ? (payload as { instanceUrl?: unknown; projectId?: unknown })
          : {},
      )

      if (!scope) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: getScopeErrorResponse(),
        }
      }

      await deleteReviewGateProjectOverride({
        userId,
        scope,
      })

      const resolved = await resolveReviewGatePreferences({
        userId,
        scope,
      })

      logger.set({
        scopeSource: resolved.effectiveSettings.scopeSource,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            global: resolved.globalSettings,
            projectOverride: null,
            effective: resolved.effectiveSettings,
          },
        }),
      }
    },
  })
}

