import { useTheme } from "next-themes"
import { useMemo } from "react"

import type { MergeRequestDiffPanelProps } from "@/features/review/components/diff/panel"
import {
  DEFAULT_WORKER_COUNT,
  DIFF_CACHE_SIZE,
  DIFF_THEME,
  type DiffStyle,
  type DiffThemeMode,
} from "@/features/review/model/diff/viewer-utils"

type MergeRequestDiffRenderingOptions = {
  diffThemeMode: DiffThemeMode
  diffStyle: DiffStyle
  wrapLines: boolean
  showLineNumbers: boolean
}

type MergeRequestDiffRenderingState = Pick<
  MergeRequestDiffPanelProps,
  "effectiveDiffThemeType" | "diffOptions" | "poolOptions" | "highlighterOptions"
>

export function useMergeRequestDiffRendering({
  diffThemeMode,
  diffStyle,
  wrapLines,
  showLineNumbers,
}: MergeRequestDiffRenderingOptions): MergeRequestDiffRenderingState {
  const { resolvedTheme } = useTheme()
  const effectiveDiffThemeType: "system" | "light" | "dark" = useMemo(() => {
    if (diffThemeMode !== "system") {
      return diffThemeMode
    }

    if (resolvedTheme === "dark" || resolvedTheme === "argus-dark") {
      return "dark"
    }
    if (resolvedTheme === "light" || resolvedTheme === "argus-light") {
      return "light"
    }

    return "system"
  }, [diffThemeMode, resolvedTheme])

  const workerPoolSize = useMemo(() => {
    if (typeof navigator === "undefined") {
      return DEFAULT_WORKER_COUNT
    }

    const cores = navigator.hardwareConcurrency || DEFAULT_WORKER_COUNT
    return Math.max(2, Math.min(8, cores - 1))
  }, [])

  const diffOptions = useMemo(
    () => ({
      diffStyle,
      disableFileHeader: true,
      overflow: (wrapLines ? "wrap" : "scroll") as "wrap" | "scroll",
      disableLineNumbers: !showLineNumbers,
      lineDiffType: "word" as const,
      diffIndicators: "bars" as const,
      hunkSeparators: "line-info" as const,
      expansionLineCount: 20,
      tokenizeMaxLineLength: 1500,
      theme: DIFF_THEME,
      themeType: effectiveDiffThemeType,
    }),
    [diffStyle, showLineNumbers, wrapLines, effectiveDiffThemeType],
  )

  const poolOptions = useMemo(
    () => ({
      workerFactory: () => {
        return new Worker(
          new URL("@pierre/diffs/worker/worker.js", import.meta.url),
          { type: "module" },
        )
      },
      poolSize: workerPoolSize,
      totalASTLRUCacheSize: DIFF_CACHE_SIZE,
    }),
    [workerPoolSize],
  )

  const highlighterOptions = useMemo(
    () => ({
      theme: DIFF_THEME,
      lineDiffType: "word" as const,
      tokenizeMaxLineLength: 1500,
    }),
    [],
  )

  return {
    effectiveDiffThemeType,
    diffOptions,
    poolOptions,
    highlighterOptions,
  }
}

