const fs = require('node:fs')
const fsp = require('node:fs/promises')
const path = require('node:path')
const process = require('node:process')

const DEFAULT_CONFIG_FILES = ['argus-search.json', '.argus-search.json']
const DEFAULT_CONFIG_BASENAME = 'argus-search.json'
const DEFAULT_STORE_PATH = '.argus-search/index.kite'
const DEFAULT_VECTOR_BASE_URL = 'https://api.openai.com/v1'
const DEFAULT_VECTOR_MODEL = 'text-embedding-3-small'
const DEFAULT_INIT_PATHS = ['.']
const DEFAULT_INIT_INCLUDE = ['*.ts', '*.tsx', '*.js', '*.jsx', '*.py', '*.cpp', '*.cc', '*.c', '*.hpp', '*.h', '*.ada']
const DEFAULT_INIT_EXCLUDE = [
  'node_modules',
  'dist',
  'build',
  'target',
  '.git',
  '.venv',
  '__pycache__',
  '.argus-search',
]

function normalizePath(value) {
  return String(value).replace(/\\/g, '/')
}

async function pathExists(filePath) {
  if (!filePath) return false
  try {
    await fsp.access(filePath)
    return true
  } catch {
    return false
  }
}

async function resolveConfigPath(explicitPath) {
  if (explicitPath) {
    return path.resolve(String(explicitPath))
  }

  let dir = process.cwd()
  while (true) {
    for (const candidate of DEFAULT_CONFIG_FILES) {
      const candidatePath = path.resolve(dir, candidate)
      if (await pathExists(candidatePath)) {
        return candidatePath
      }
    }

    const parent = path.dirname(dir)
    if (parent === dir) break
    dir = parent
  }

  return null
}

function resolveBootstrapProjectRoot(projectRootOverride, fallbackConfigPath) {
  if (projectRootOverride) {
    return path.resolve(String(projectRootOverride))
  }
  if (fallbackConfigPath) {
    return path.dirname(fallbackConfigPath)
  }
  const envRoot = process.env.CODE_INTELLIGENCE_PROJECT_ROOT || process.env.CODE_INTEL_PROJECT_ROOT
  if (envRoot) {
    return path.resolve(String(envRoot))
  }
  return process.cwd()
}

function resolveProjectRoot(configPath, options, overrideRoot) {
  if (overrideRoot) return overrideRoot
  if (configPath && options.projectRoot && !path.isAbsolute(options.projectRoot)) {
    return path.resolve(path.dirname(configPath), String(options.projectRoot))
  }
  if (options.projectRoot) return String(options.projectRoot)
  const envRoot = process.env.CODE_INTELLIGENCE_PROJECT_ROOT || process.env.CODE_INTEL_PROJECT_ROOT
  if (envRoot) return String(envRoot)
  if (configPath) return path.dirname(configPath)
  return process.cwd()
}

async function ensureProjectRoot(projectRoot) {
  try {
    const stat = await fsp.stat(projectRoot)
    if (!stat.isDirectory()) {
      throw new Error('project root is not a directory')
    }
  } catch (error) {
    throw new Error(
      `project root not found: ${projectRoot} (${error instanceof Error ? error.message : String(error)})`,
    )
  }
}

function resolveStorePath(projectRoot, storeFlag) {
  const storePath = storeFlag ? String(storeFlag) : DEFAULT_STORE_PATH
  return path.isAbsolute(storePath) ? storePath : path.join(projectRoot, storePath)
}

function ensureGitignore(projectRoot) {
  const gitignorePath = path.join(projectRoot, '.gitignore')
  const entry = '.argus-search/'
  let existing = ''
  try {
    existing = fs.readFileSync(gitignorePath, 'utf8')
  } catch {
    existing = ''
  }
  if (existing.includes(entry)) {
    return
  }
  let updated = existing
  if (updated.length > 0 && !updated.endsWith('\n')) {
    updated += '\n'
  }
  updated += '\n# argus-search\n'
  updated += `${entry}\n`
  fs.writeFileSync(gitignorePath, updated)
}

function buildInitConfig({ projectRoot = '.', paths, include, exclude, vectorBaseUrl, vectorModel, incremental, includeCheckpointDefaults = false }) {
  const output = includeCheckpointDefaults
    ? {
        incremental,
        checkpointOnFinish: true,
        checkpointThreshold: 0.0,
      }
    : { incremental }

  return {
    projectRoot,
    inputs: {
      paths,
      include,
      exclude,
      respectGitignore: true,
    },
    phases: { parse: true, graph: true, vector: true, scip: false, indexPack: false },
    vector: {
      provider: {
        kind: 'http',
        baseUrl: vectorBaseUrl,
        model: vectorModel,
      },
    },
    cache: { enabled: incremental, force: false },
    output,
  }
}

async function createAutoConfig(configPath, projectRoot, reason, log = (line) => process.stderr.write(`${line}\n`)) {
  const resolvedConfigPath = path.resolve(configPath)
  const resolvedProjectRoot = path.resolve(projectRoot)
  await ensureProjectRoot(resolvedProjectRoot)

  const configDir = path.dirname(resolvedConfigPath)
  const relRoot = path.relative(configDir, resolvedProjectRoot)
  const configProjectRoot = normalizePath(relRoot || '.')
  const payload = buildInitConfig({
    projectRoot: configProjectRoot,
    paths: [...DEFAULT_INIT_PATHS],
    include: [...DEFAULT_INIT_INCLUDE],
    exclude: [...DEFAULT_INIT_EXCLUDE],
    vectorBaseUrl: DEFAULT_VECTOR_BASE_URL,
    vectorModel: DEFAULT_VECTOR_MODEL,
    incremental: true,
  })

  log(`[argus-search] ${reason}`)
  log(`[argus-search] Creating default config at ${resolvedConfigPath}`)

  await fsp.mkdir(configDir, { recursive: true })
  await fsp.writeFile(resolvedConfigPath, JSON.stringify(payload, null, 2))
  await fsp.mkdir(path.join(resolvedProjectRoot, '.argus-search'), { recursive: true })
  ensureGitignore(resolvedProjectRoot)

  log(`[argus-search] Created config (projectRoot=${configProjectRoot}, vector.model=${DEFAULT_VECTOR_MODEL})`)
}

