    .delete(gitlabIntegrationMemberships)
    .where(
      and(
        eq(gitlabIntegrationMemberships.integrationId, integration.id),
        eqGitLabMembershipUserId(userId),
      ),
    )

  const countResult = await db
    .select({ value: count() })
    .from(gitlabIntegrationMemberships)
    .where(eq(gitlabIntegrationMemberships.integrationId, integration.id))

  const memberCount = Number(countResult[0]?.value ?? 0)
  if (memberCount > 0) {
    return {
      scope: "personal" as const,
      warning: undefined,
    }
  }

  let warning: string | undefined
  try {
    if (integration.tokenCiphertext && integration.tokenIv && integration.tokenAuthTag) {
      const token = decryptIntegrationToken(integration)
      await deleteProjectWebhook({
        instanceUrl: integration.instanceUrl,
        token,
        projectId: integration.projectId,
        callbackUrl: integration.webhookUrl,
        hookId: integration.hookId,
      })
    }
  } catch (error) {
    warning = `Hook cleanup warning: ${toErrorMessage(error)}`
  }

  await db
    .update(gitlabIntegrations)
    .set({
      hookId: null,
      webhookSecretHash: null,
      tokenCiphertext: null,
      tokenIv: null,
      tokenAuthTag: null,
      status: "disabled",
      lastError: warning ?? null,
      updatedAt: new Date(),
    })
    .where(eq(gitlabIntegrations.id, integration.id))

  return {
    scope: "global" as const,
    warning,
  }
}

export const ingestWebhookDelivery = async ({
  integrationId,
  eventUuid,
  eventName,
  eventType,
  ref,
  payload,
  jobType,
  normalizedPayload,
}: {
  integrationId: string
  eventUuid: string
  eventName: string
  eventType: "push" | "merge_request" | "ignored"
  ref: string | null
  payload: Record<string, unknown>
  jobType?: "push" | "merge_request"
  normalizedPayload?: Record<string, unknown>
}) => {
  return db.transaction(async (tx) => {
    await tx
      .update(gitlabIntegrations)
      .set({
        lastWebhookReceivedAt: new Date(),
        updatedAt: new Date(),
      })
      .where(eq(gitlabIntegrations.id, integrationId))

    const insertedDeliveries = await tx
      .insert(gitlabWebhookDeliveries)
      .values({
        integrationId,
        eventUuid,
        eventName,
        eventType,
        ref,
        payload,
      })
      .onConflictDoNothing()
      .returning({ id: gitlabWebhookDeliveries.id })

    const deliveryId = insertedDeliveries[0]?.id
    if (!deliveryId) {
      return {
        deduped: true,
        enqueued: false,
      }
    }

    if (jobType) {
      await tx.insert(gitlabJobs).values({
        integrationId,
        deliveryId,
        jobType,
        status: "pending",
        attempts: 0,
        nextAttemptAt: new Date(),
        normalizedPayload,
        updatedAt: new Date(),
      })
    }

    return {
      deduped: false,
      enqueued: Boolean(jobType),
    }
  })
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { getSessionCookie } from "better-auth/cookies";

const PUBLIC_PATHS = new Set(["/"]);
// Onboarding auth is enforced server-side in app layout; keeping it public here avoids
// proxy/session false negatives that can cause redirect loops on first-login flows.
const PUBLIC_PREFIXES = ["/sign-up", "/welcome", "/onboarding", "/docs"];
const GITLAB_MERGE_REQUEST_PATH_PATTERN =
  /^\/(.+)\/-\/merge_requests\/([^/]+)(?:\/.*)?$/;

const isPublicPath = (pathname: string) =>
  PUBLIC_PATHS.has(pathname) ||
  PUBLIC_PREFIXES.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
  );

// This allows us to enable users to replace the gitlab from the URL with argus
// and it should basically redirect the user to our instance.
const parseGitLabMergeRequestPath = (pathname: string) => {
  const match = pathname.match(GITLAB_MERGE_REQUEST_PATH_PATTERN);
  if (!match) {
    return null;
  }

  const projectPath = match[1]?.trim().replace(/^\/+|\/+$/g, "");
  const mergeRequestIid = match[2]?.trim();
  if (!projectPath || !mergeRequestIid) {
    return null;
  }

  return { projectPath, mergeRequestIid };
};

export function proxy(request: NextRequest) {
  const { pathname, search } = request.nextUrl;

  if (isPublicPath(pathname)) {
    return NextResponse.next();
  }

  const sessionToken = getSessionCookie(request);
  if (sessionToken) {
    const gitLabMergeRequestPath = parseGitLabMergeRequestPath(pathname);
    if (gitLabMergeRequestPath) {
      const bridgeUrl = new URL("/mr-bridge", request.url);
      bridgeUrl.searchParams.set(
        "projectPath",
        gitLabMergeRequestPath.projectPath,
      );
      bridgeUrl.searchParams.set(
        "mergeRequestIid",
        gitLabMergeRequestPath.mergeRequestIid,
      );
      const requestedInstance = request.nextUrl.searchParams.get("instance");
      if (requestedInstance) {
        bridgeUrl.searchParams.set("instance", requestedInstance);
      }
      return NextResponse.rewrite(bridgeUrl);
    }

    return NextResponse.next();
  }

  const redirectUrl = new URL("/", request.url);
  const nextPath = `${pathname}${search}`;
  if (nextPath !== "/") {
    redirectUrl.searchParams.set("next", nextPath);
  }

  return NextResponse.redirect(redirectUrl);
}

export const config = {
  matcher: ["/((?!api|_next/static|_next/image|favicon.ico|.*\\..*).*)"],
};

