type RepoRouteIntegrationLike = {
  id: string
  instanceUrl: string
  projectPath: string
  projectId: string
}

const slugify = (value: string, fallback: string) => {
  const normalized = value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")

  return normalized.length > 0 ? normalized : fallback
}

const compactToken = (value: string) =>
  value.toLowerCase().replace(/[^a-z0-9]+/g, "")

const getInstanceHost = (instanceUrl: string) => {
  const trimmed = instanceUrl.trim()
  if (!trimmed) {
    return "instance"
  }

  try {
    return new URL(trimmed).host
  } catch {
    return trimmed
  }
}

export const buildRepoRouteId = ({
  id,
  instanceUrl,
  projectPath,
  projectId,
}: RepoRouteIntegrationLike) => {
  const hostSlug = slugify(getInstanceHost(instanceUrl), "instance")
  const pathSlug = slugify(projectPath, "repo")
  const projectToken = compactToken(projectId) || compactToken(id) || "repo"

  return `${hostSlug}--${pathSlug}--p${projectToken}`
}

export const buildRepoPath = (integration: RepoRouteIntegrationLike) =>
  `/repos/${encodeURIComponent(buildRepoRouteId(integration))}`

export const buildRepoMergeRequestPath = (
  integration: RepoRouteIntegrationLike,
  mergeRequestIid: string,
) => `${buildRepoPath(integration)}/mrs/${encodeURIComponent(mergeRequestIid)}`

export const buildRepoMergeRequestDescriptionPath = (
  integration: RepoRouteIntegrationLike,
  mergeRequestIid: string,
) => `${buildRepoMergeRequestPath(integration, mergeRequestIid)}/description`

export const findIntegrationByRepoRouteId = <T extends RepoRouteIntegrationLike>(
  integrations: readonly T[],
  routeId: string,
) => {
  const normalizedRouteId = routeId.trim()
  if (!normalizedRouteId) {
    return undefined
  }

  return integrations.find((integration) => (
    integration.id === normalizedRouteId ||
    buildRepoRouteId(integration) === normalizedRouteId
  ))
}

