import { notFound, redirect } from "next/navigation"

import { RepoProjectTabs } from "@/features/repos/components/project-tabs"
import { SiteHeaderTitle } from "@/components/site-header-title"
import { buildRepoRouteId, findIntegrationByRepoRouteId } from "@/lib/gitlab/repo-route"
import { getCachedUserIntegrations } from "@/lib/gitlab/user-integrations-cache"
import { getSession } from "@/lib/session"

type RepoPageProps = {
  params: Promise<{
    integrationId: string
  }>
}

const integrationStatusLabel: Record<"active" | "degraded" | "disabled", string> = {
  active: "Active",
  degraded: "Degraded",
  disabled: "Disabled",
}

const integrationStatusVariant: Record<"active" | "degraded" | "disabled", "default" | "secondary" | "outline"> = {
  active: "default",
  degraded: "secondary",
  disabled: "outline",
}

export default async function RepoPage({ params }: RepoPageProps) {
  const [session, { integrationId: repoRouteId }] = await Promise.all([
    getSession(),
    params,
  ])

  if (!session?.user?.id) {
    redirect("/")
  }

  const integrations = await getCachedUserIntegrations(session.user.id)
  const integration = findIntegrationByRepoRouteId(integrations, repoRouteId)

  if (!integration) {
    notFound()
  }

  const canonicalRepoRouteId = buildRepoRouteId(integration)
  if (repoRouteId !== canonicalRepoRouteId) {
    redirect(`/repos/${encodeURIComponent(canonicalRepoRouteId)}`)
  }

  return (
    <div className="space-y-6 pt-6">
      <SiteHeaderTitle title={integration.projectName} />

      <RepoProjectTabs
        integrationId={integration.id}
        repoRouteId={canonicalRepoRouteId}
        instanceUrl={integration.instanceUrl}
        projectId={integration.projectId}
        projectName={integration.projectName}
        projectPath={integration.projectPath}
        integrationStatus={integration.status}
        integrationStatusLabel={integrationStatusLabel[integration.status]}
        integrationStatusVariant={integrationStatusVariant[integration.status]}
        lastWebhookReceivedAt={integration.lastWebhookReceivedAt?.toISOString() ?? null}
        lastHookSyncAt={integration.lastHookSyncAt?.toISOString() ?? null}
        lastError={integration.lastError}
      />
    </div>
  )
}

