#[napi]
pub fn index(options: Object<'_>) -> Result<Unknown<'_>> {

  let env_raw = options.value().env;
  let (index_options, mut sink, callback_error) = parse_index_options(options)?;
  let cancel = CancelToken::new();
  let operation_id = register_in_flight_cancel(cancel.clone());

  let fut = async move {
    let _guard = InFlightCancelGuard::new(operation_id);
    let stats = napi::tokio::task::spawn_blocking(move || {
      let engine = IndexEngine::new(index_options);
      let result = engine.run(&mut sink, &cancel);
      let mut guard = lock_callback_error(&callback_error);
      let callback_failure = guard.take();
      match (result, callback_failure) {
        (_, Some(message)) => Err(Error::from_reason(message)),
        (Err(err), None) => Err(Error::from_reason(err.to_string())),
        (Ok(stats), None) => Ok(stats),
      }
    })
    .await
    .map_err(|err| Error::from_reason(format!("index task failed: {err}")))??;

    Ok::<IndexStats, Error>(stats)
  };

  let promise = napi::bindgen_prelude::execute_tokio_future(env_raw, fut, |env, stats| {
    let env = Env::from_raw(env);
    let value = serde_json::to_value(stats).map_err(|err| Error::from_reason(err.to_string()))?;
    let js = env.to_js_value(&value)?;
    Ok(js.raw())
  })?;

  // SAFETY: `execute_tokio_future(env_raw, ..)` returned successfully, so `promise` is a valid
  // `napi_value` for the same `env_raw` (specifically: a JS Promise created by N-API). Wrapping it
  // as `Unknown` is sound as long as the env/value pair is valid, which N-API guarantees here.
  Ok(unsafe { Unknown::from_raw_unchecked(env_raw, promise) })
}

#[napi(js_name = "indexToKiteDb")]
#[allow(dead_code)]
pub fn index_to_kitedb<'a>(options: Object<'a>, store: Object<'a>) -> Result<Unknown<'a>> {
  let env_raw = options.value().env;
  let index_options = parse_index_options_core(&options)?;

  if index_options.phases.vector && index_options.vector_provider.is_none() {
    return Err(Error::from_reason(
      "vector phase requires vector.provider config".to_string(),
    ));
  }

  let store_path = required_string(&store, "path")?;
  let store_path = resolve_store_path(&index_options.project_root, PathBuf::from(store_path))?;
  let clear = store.get::<bool>("clear")?.unwrap_or(false);
  let cancel = CancelToken::new();
  let operation_id = register_in_flight_cancel(cancel.clone());

  let fut = async move {
    let _guard = InFlightCancelGuard::new(operation_id);
    let stats = napi::tokio::task::spawn_blocking(move || {
      let engine = IndexEngine::new(index_options);
      let mut sink = KiteDbIndexSink::new(store_path, clear);
      match engine.run(&mut sink, &cancel) {
        Err(err) => {
          let _ = sink.abort();
          Err(Error::from_reason(err.to_string()))
        }
        Ok(stats) => {
          sink
            .finish()
            .map_err(|err| Error::from_reason(err.to_string()))?;
          Ok(stats)
        }
      }
    })
    .await
    .map_err(|err| Error::from_reason(format!("index task failed: {err}")))??;

    Ok::<IndexStats, Error>(stats)
  };

  let promise = napi::bindgen_prelude::execute_tokio_future(env_raw, fut, |env, stats| {
    let env = Env::from_raw(env);
    let value = serde_json::to_value(stats).map_err(|err| Error::from_reason(err.to_string()))?;
    let js = env.to_js_value(&value)?;
    Ok(js.raw())
  })?;

  // SAFETY: `promise` is a valid JS Promise allocated in `env_raw` by N-API.
  Ok(unsafe { Unknown::from_raw_unchecked(env_raw, promise) })
}

#[napi(js_name = "searchKiteDb")]
#[allow(dead_code)]
pub fn search_kitedb(options: Object<'_>) -> Result<Unknown<'_>> {
  let env_raw = options.value().env;

  let project_root = required_string(&options, "projectRoot")?;
  let project_root = PathBuf::from(project_root);

  let store = options
    .get::<Object<'_>>("store")?
    .ok_or_else(|| Error::from_reason("missing required field: store".to_string()))?;
  let store_path = required_string(&store, "path")?;
  let store_path = resolve_store_path(&project_root, PathBuf::from(store_path))?;

  let query = required_string(&options, "query")?;
  let query = query.trim().to_string();
  if query.is_empty() {
    return Err(Error::from_reason("query cannot be empty".to_string()));
  }
  let top_k = options.get::<u32>("topK")?.unwrap_or(5).clamp(1, 50) as usize;
  let include_content = options.get::<bool>("includeContent")?.unwrap_or(false);
  let content_context = options
    .get::<u32>("contentContext")?
    .unwrap_or(2)
    .clamp(0, 100) as usize;
  let content_max_chars = options
    .get::<u32>("contentMaxChars")?
    .unwrap_or(4000)
    .clamp(256, 200_000) as usize;

let provider = options
  .get::<Object<'_>>("vectorProvider")?
  .ok_or_else(|| Error::from_reason("missing required field: vectorProvider".to_string()))?;
let provider = parse_http_embedding_provider(provider)?;

let fut = async move {
  napi::tokio::task::spawn_blocking(
    move || -> Result<Vec<crate::core::kitedb_store::KiteSearchHit>> {
      let embeddings = provider
        .embed_texts(&[query.as_str()])
        .map_err(|err| Error::from_reason(err.to_string()))?;
      let embedding = embeddings.into_iter().next().ok_or_else(|| {
        Error::from_reason("vector provider returned no embeddings".to_string())
      })?;

      let store = KiteCodeStore::open_readonly(store_path)
        .map_err(|err| Error::from_reason(err.to_string()))?;

      let mut hits = store
        .search_by_embedding(&embedding, top_k)
        .map_err(|err| Error::from_reason(err.to_string()))?;

      if include_content {
        for hit in &mut hits {
          hit.content = store
            .chunk_content_by_id(&hit.chunk_id)
            .or_else(|| {
              snippet_for_hit(
                &project_root,
                hit.file_path.as_deref(),
                &hit.range_json,
                content_context,
                content_max_chars,
              )
            })
            .map(|value| truncate_chars(value, content_max_chars));
        }
      }

      Ok(hits)
    },
  )
  .await
  .map_err(|err| Error::from_reason(format!("search task failed: {err}")))?
};

  let promise = napi::bindgen_prelude::execute_tokio_future(env_raw, fut, |env, hits| {
    let env = Env::from_raw(env);
    let value = serde_json::to_value(hits).map_err(|err| Error::from_reason(err.to_string()))?;
    let js = env.to_js_value(&value)?;
    Ok(js.raw())
  })?;

  // SAFETY: `promise` is a valid JS Promise allocated in `env_raw` by N-API.
  Ok(unsafe { Unknown::from_raw_unchecked(env_raw, promise) })
}

