use tree_sitter::{Node, Point};

use super::types::{Position, Range};

pub fn to_position(point: Point) -> Position {
  Position {
    row: point.row as u32,
    column: point.column as u32,
  }
}

pub fn to_range(node: Node) -> Range {
  Range {
    start: to_position(node.start_position()),
    end: to_position(node.end_position()),
  }
}

pub fn node_text(source: &str, node: Node) -> String {
  let bytes = source.as_bytes();
  let range = node.byte_range();
  if range.end <= bytes.len() {
    String::from_utf8_lossy(&bytes[range]).to_string()
  } else {
    String::new()
  }
}

