import { useCallback, useState } from "react"

import {
  getReviewErrorMessage,
  normalizeReviewImpact,
  type ReviewFindingImpact,
  type ReviewImpactPayload,
  type ReviewImpactStatus,
} from "@/features/review/model/diff/viewer-utils"
import { parseJsonResponse } from "@/lib/http/response-json"
import {
  DEFAULT_REVIEW_IMPACT_INDEXING,
  QUEUEABLE_GRAPH_PENDING_REASONS,
  getBranchIndexingErrorMessage,
} from "./use-ai-review.utils"

type BuildRequestHeaders = (base?: Record<string, string>) => Record<string, string>

type UseMergeRequestAiReviewImpactArgs = {
  integrationId?: string
  reviewId: string | null
  buildRequestHeaders: BuildRequestHeaders
}

export function useMergeRequestAiReviewImpact({
  integrationId,
  reviewId,
  buildRequestHeaders,
}: UseMergeRequestAiReviewImpactArgs) {
  const [reviewImpactByKey, setReviewImpactByKey] = useState<Record<string, ReviewFindingImpact>>({})
  const [reviewImpactStatus, setReviewImpactStatus] = useState<ReviewImpactStatus>("not_started")
  const [reviewImpactIndexing, setReviewImpactIndexing] = useState<ReviewImpactPayload["indexing"]>(
    DEFAULT_REVIEW_IMPACT_INDEXING,
  )
  const [isLoadingReviewImpact, setIsLoadingReviewImpact] = useState(false)
  const [isQueueingBranchIndexing, setIsQueueingBranchIndexing] = useState(false)
  const [branchIndexingQueued, setBranchIndexingQueued] = useState(false)
  const [branchIndexingError, setBranchIndexingError] = useState("")

const applyReviewImpactPayload = useCallback(
  (value: unknown) => {
    const normalized = normalizeReviewImpact(value)
    if (!normalized) {
      return null
    }
    setReviewImpactByKey(normalized.impactByKey)
    setReviewImpactStatus(normalized.status)
    setReviewImpactIndexing({
      ...normalized.indexing,
      integrationId: normalized.indexing.integrationId ?? integrationId ?? null,
    })
    if (
      normalized.status !== "pending_graph" ||
      normalized.indexing.graphPendingReason === null ||
      !QUEUEABLE_GRAPH_PENDING_REASONS.has(normalized.indexing.graphPendingReason)
    ) {
      setBranchIndexingQueued(false)
      setBranchIndexingError("")
    }
    return normalized
  },
  [integrationId],
)

const requestReviewImpact = useCallback(
  async ({
    reviewId: targetReviewId,
    method,
    force,
  }: {
    reviewId: string
    method: "GET" | "POST"
    force?: boolean
  }) => {
    const normalizedReviewId = targetReviewId.trim()
    if (!normalizedReviewId) {
      return null
    }

    const response =
      method === "GET"
        ? await fetch(
            `/api/review/impact?${new URLSearchParams({ reviewId: normalizedReviewId }).toString()}`,
            {
              method: "GET",
              headers: buildRequestHeaders(),
            },
          )
        : await fetch("/api/review/impact", {
            method: "POST",
            headers: buildRequestHeaders({
              "content-type": "application/json",
            }),
            body: JSON.stringify({
              reviewId: normalizedReviewId,
              force: force === true,
            }),
          })

    const parsedPayload = await parseJsonResponse(response)
    const payload = parsedPayload.ok
      ? (parsedPayload.value as {
          data?: unknown
          error?: unknown
        })
      : null
    if (!response.ok) {
      throw new Error(getReviewErrorMessage(payload))
    }

    return applyReviewImpactPayload(payload?.data)
  },
  [applyReviewImpactPayload, buildRequestHeaders],
)

const loadReviewImpact = useCallback(
  async (targetReviewId: string) => {
    setIsLoadingReviewImpact(true)
    try {
      const loaded = await requestReviewImpact({
        reviewId: targetReviewId,
        method: "GET",
      })
      if (loaded && (loaded.status === "not_started" || loaded.status === "in_progress")) {
        await requestReviewImpact({
          reviewId: targetReviewId,
          method: "POST",
          force: false,
        }).catch(() => null)
      }
    } catch {
      setReviewImpactByKey({})
      setReviewImpactStatus("not_started")
      setReviewImpactIndexing(DEFAULT_REVIEW_IMPACT_INDEXING)
    } finally {
      setIsLoadingReviewImpact(false)
    }
  },
  [requestReviewImpact],
)

const queueImpactBranchIndexing = useCallback(
  async (input: { branch: string; integrationId: string }) => {
    if (isQueueingBranchIndexing) {
      return
    }

    const branch = input.branch.trim() || reviewImpactIndexing.branch?.trim() || ""
    const targetIntegrationId =
      input.integrationId.trim() ||
      (reviewImpactIndexing.integrationId ?? integrationId ?? "").trim()
    if (
      !branch ||
      !targetIntegrationId ||
      reviewImpactIndexing.graphPendingReason === null ||
      !QUEUEABLE_GRAPH_PENDING_REASONS.has(reviewImpactIndexing.graphPendingReason)
    ) {
      return
    }

    setIsQueueingBranchIndexing(true)
    setBranchIndexingError("")
    setBranchIndexingQueued(false)

    try {
      const response = await fetch(
        `/api/gitlab/integrations/${targetIntegrationId}/index/reindex`,
        {
          method: "POST",
          headers: buildRequestHeaders({
            "content-type": "application/json",
          }),
          body: JSON.stringify({ branch }),
        },
      )
      const parsedPayload = await parseJsonResponse(response)
      const payload = parsedPayload.ok
        ? (parsedPayload.value as {
            data?: unknown
            error?: unknown
          })
        : null
      if (!response.ok) {
        throw new Error(getBranchIndexingErrorMessage(payload))
      }

      setBranchIndexingQueued(true)
      if (reviewId) {
        await requestReviewImpact({
          reviewId,
          method: "GET",
        }).catch(() => null)
      }
    } catch (error) {
      setBranchIndexingError(getBranchIndexingErrorMessage(error))
      setBranchIndexingQueued(false)
    } finally {
      setIsQueueingBranchIndexing(false)
    }
  },
  [
    buildRequestHeaders,
    integrationId,
    isQueueingBranchIndexing,
    requestReviewImpact,
    reviewId,
    reviewImpactIndexing,
  ],
)

const resetReviewImpactState = useCallback(() => {
  setReviewImpactByKey({})
  setReviewImpactStatus("not_started")
  setReviewImpactIndexing(DEFAULT_REVIEW_IMPACT_INDEXING)
  setIsLoadingReviewImpact(false)
  setIsQueueingBranchIndexing(false)
  setBranchIndexingQueued(false)
  setBranchIndexingError("")
}, [])

import { describe, expect, test } from "bun:test"

import {
  createCorrelationId,
  parseBooleanWithFallback,
  parseDurationMs,
  parsePositiveIntWithFallback,
  parseRate,
} from "./observability"

describe("shared observability utils", () => {
  test("parseBooleanWithFallback handles truthy/falsey values", () => {
    expect(parseBooleanWithFallback("true", false)).toBe(true)
    expect(parseBooleanWithFallback("yes", false)).toBe(true)
    expect(parseBooleanWithFallback("0", true)).toBe(false)
    expect(parseBooleanWithFallback("no", true)).toBe(false)
    expect(parseBooleanWithFallback(undefined, true)).toBe(true)
    expect(() => parseBooleanWithFallback("maybe", true, "APP_LOG_DB_ENABLED")).toThrow(
      "Invalid boolean for APP_LOG_DB_ENABLED.",
    )
  })

  test("parsePositiveIntWithFallback enforces positive integers", () => {
    expect(parsePositiveIntWithFallback("5", 10)).toBe(5)
    expect(parsePositiveIntWithFallback(undefined, 10)).toBe(10)
    expect(() => parsePositiveIntWithFallback("0", 10, "APP_LOG_DB_BATCH_SIZE")).toThrow(
      'Invalid positive integer for APP_LOG_DB_BATCH_SIZE. Received "0".',
    )
    expect(() => parsePositiveIntWithFallback("-1", 10)).toThrow(
      'Invalid positive integer. Received "-1".',
    )
    expect(() => parsePositiveIntWithFallback("abc", 10)).toThrow(
      'Invalid positive integer. Received "abc".',
    )
  })

  test("parseRate clamps to [0, 100] and rejects non-numeric input", () => {
    expect(parseRate("50", 100)).toBe(50)
    expect(parseRate("150", 100)).toBe(100)
    expect(parseRate("-5", 100)).toBe(0)
    expect(parseRate(undefined, 25)).toBe(25)
    expect(() => parseRate("bad", 25, "APP_LOG_SAMPLE_INFO")).toThrow(
      'Invalid rate for APP_LOG_SAMPLE_INFO. Received "bad".',
    )
  })

  test("parseDurationMs parses number, ms, and s values", () => {
    expect(parseDurationMs(500.8)).toBe(500)
    expect(parseDurationMs("250ms")).toBe(250)
    expect(parseDurationMs("2s")).toBe(2000)
    expect(parseDurationMs("bad")).toBeNull()
  })

  test("createCorrelationId returns non-empty ids", () => {
    const id1 = createCorrelationId()
    const id2 = createCorrelationId()
    expect(id1.length).toBeGreaterThan(0)
    expect(id2.length).toBeGreaterThan(0)
    expect(id1).not.toBe(id2)
  })
})

