import { afterEach, describe, expect, mock, test } from "bun:test"

type InsertRow = {
  id: string
  debounceKey: string
  status: "pending" | "processing" | "failed" | "succeeded" | "dead"
}

const loadModule = async (args: {
  returningRows: InsertRow[]
  existingRows?: InsertRow[]
}) => {
  const returning = mock(async () => args.returningRows)
  const limit = mock(async () => args.existingRows ?? [])
  const onConflictCalls: Array<Record<string, unknown>> = []

  const db = {
    insert: mock(() => ({
      values: () => ({
        onConflictDoUpdate: (value: Record<string, unknown>) => {
          onConflictCalls.push(value)
          return {
          returning,
          }
        },
      }),
    })),
    select: mock(() => ({
      from: () => ({
        where: () => ({
          limit,
        }),
      }),
    })),
  }

  mock.module("@/lib/db", () => ({ db }))

  const mod = await import(`@/lib/indexing/job-queue?cacheBust=${Math.random().toString(36).slice(2)}`)

  return {
    enqueuePlanJob: mod.enqueuePlanJob as (args: {
      integrationId: string
      branch: string
      hintedHeadSha?: string
      configHash?: string
      configJson?: Record<string, unknown>
      forceReplan?: boolean
      coalesceInFlight?: boolean
    }) => Promise<{ id: string; debounceKey: string; status: string; wasQueued: boolean }>,
    db,
    returning,
    limit,
    onConflictCalls,
  }
}

describe("enqueuePlanJob", () => {

test("does not coalesce in-flight jobs unless explicitly enabled", async () => {
  const { enqueuePlanJob, onConflictCalls } = await loadModule({
    returningRows: [
      {
        id: "job-updated",
        debounceKey: "plan:integration-1:main:default-v1",
        status: "pending",
      },
    ],
  })

  await enqueuePlanJob({
    integrationId: "integration-1",
    branch: "main",
  })

  expect(onConflictCalls[0]).not.toHaveProperty("where")
})

test("returns existing in-flight row with wasQueued=false when coalesced", async () => {
  const { enqueuePlanJob, onConflictCalls } = await loadModule({
    returningRows: [],
    existingRows: [
      {
        id: "job-existing",
        debounceKey: "plan:integration-1:main:default-v1",
        status: "processing",
      },
    ],
  })

  const row = await enqueuePlanJob({
    integrationId: "integration-1",
    branch: "main",
    coalesceInFlight: true,
  })

  expect(row).toEqual({
    id: "job-existing",
    debounceKey: "plan:integration-1:main:default-v1",
    status: "processing",
    wasQueued: false,
  })
  expect(onConflictCalls[0]).toHaveProperty("where")
})

  test("returns inserted row with wasQueued=true", async () => {
    const { enqueuePlanJob } = await loadModule({
      returningRows: [
        {
          id: "job-new",
          debounceKey: "plan:integration-1:main:default-v1",
          status: "pending",
        },
      ],
    })

    const row = await enqueuePlanJob({
      integrationId: "integration-1",
      branch: "main",
    })

    expect(row).toEqual({
      id: "job-new",
      debounceKey: "plan:integration-1:main:default-v1",
      status: "pending",
      wasQueued: true,
    })
  })
})

afterEach(() => {
  mock.restore()
})

import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { db } from "@/lib/db";
import { nextCookies } from "better-auth/next-js";
import { betterAuth } from "better-auth";
import { genericOAuth } from "better-auth/plugins";
import { parseBoolean } from "@argus/shared-runtime/config-env";
import { authSchema } from "@/lib/db/schema";

const OIDC_DEFAULT_SCOPES = [
  "openid",
  "preferred_username",
  "family_name",
  "given_name",
  "email",
] as const;

type OidcAuthentication = "basic" | "post";

const isNonEmpty = (value: string | undefined): value is string =>
  Boolean(value?.trim());

const parseOidcAuthentication = (
  value: string | undefined,
): OidcAuthentication => {
  if (!isNonEmpty(value)) {
    return "basic";
  }
  const normalized = value.trim().toLowerCase();
  if (normalized === "basic" || normalized === "post") {
    return normalized;
  }
  throw new Error("OIDC_AUTHENTICATION must be 'basic' or 'post'.");
};

const parseOidcScopes = (value: string | undefined) => {
  if (!isNonEmpty(value)) {
    return [...OIDC_DEFAULT_SCOPES];
  }
  const scopes = value.split(/[,\s]+/).filter(Boolean);
  if (scopes.length === 0) {
    throw new Error("OIDC_SCOPES must include at least one scope when set.");
  }
  return scopes;
};

const parseTrustedOrigins = () =>
  Array.from(
    new Set(
      [
        process.env.BETTER_AUTH_URL,
        ...(process.env.BETTER_AUTH_TRUSTED_ORIGINS?.split(",") ?? []),
      ]
        .map((origin) => origin?.trim())
        .filter((origin): origin is string => Boolean(origin)),
    ),
  );

const buildOidcProviderConfig = () => {
  const issuer = process.env.OIDC_ISSUER?.trim();
  const clientId = process.env.OIDC_CLIENT_ID?.trim();
  const clientSecret = process.env.OIDC_CLIENT_SECRET?.trim();

  const oidcConfigured =
    isNonEmpty(process.env.OIDC_ISSUER) ||
    isNonEmpty(process.env.OIDC_CLIENT_ID) ||
    isNonEmpty(process.env.OIDC_CLIENT_SECRET) ||
    isNonEmpty(process.env.OIDC_SCOPES) ||
    isNonEmpty(process.env.OIDC_PKCE) ||
    isNonEmpty(process.env.OIDC_AUTHENTICATION);
  if (!oidcConfigured) {
    return null;
  }

  if (!issuer) {
    throw new Error("OIDC_ISSUER is required when OIDC is configured.");
  }
  if (!clientId) {
    throw new Error("OIDC_CLIENT_ID is required when OIDC is configured.");
  }

  return {
    providerId: "oidc",
    discoveryUrl: `${issuer.replace(/\/+$/, "")}/.well-known/openid-configuration`,
    clientId,
    clientSecret: clientSecret || undefined,
    scopes: parseOidcScopes(process.env.OIDC_SCOPES),
    pkce: parseBoolean(process.env.OIDC_PKCE, "OIDC_PKCE") ?? false,
    authentication: parseOidcAuthentication(process.env.OIDC_AUTHENTICATION),
    responseType: "code" as const,
    mapProfileToUser(profile: Record<string, unknown>) {
      const email = typeof profile.email === "string" ? profile.email : "";
      const id =
        typeof profile.sub === "string"
          ? profile.sub
          : typeof profile.id === "string"
            ? profile.id
            : null;
      if (!id) {
        throw new Error("OIDC profile must contain a string 'sub' or 'id'.");
      }
      return {
        id,
        email,
        // Fallback keeps display stable for providers that omit preferred_username/name.
        name:
          typeof profile.preferred_username === "string"
            ? profile.preferred_username
            : typeof profile.name === "string"
              ? profile.name
              : email.split("@")[0] || "User",
        image:
          typeof profile.picture === "string"
            ? profile.picture
            : null,
        emailVerified:
          profile.email_verified === true ||
          profile.emailVerified === true,
      };
    },
  };
};

const trustedOrigins = Array.from(
  new Set(parseTrustedOrigins()),
);

const oidcConfig = buildOidcProviderConfig();

export const auth = betterAuth({
  database: drizzleAdapter(db, {
    schema: authSchema,
    provider: "pg",
  }),
  trustedOrigins,
  emailAndPassword: {
    enabled: true,
  },
  plugins: [
    nextCookies(),
    ...(oidcConfig
      ? [
          genericOAuth({
            config: [oidcConfig],
          }),
        ]
      : []),
  ],
});

