export class GitLabApiError extends Error {
  status: number
  responseBody?: string

  constructor(message: string, status: number, responseBody?: string) {
    super(message)
    this.status = status
    this.responseBody = responseBody
  }
}

const hasScopeErrorHint = (responseBody?: string) => {
  const normalized = responseBody?.toLowerCase() ?? ""
  return normalized.includes("scope") || normalized.includes("insufficient")
}

export const describeWebhookSyncError = (error: unknown): string | null => {
  if (!(error instanceof GitLabApiError)) {
    return null
  }

  if (error.status === 401) {
    return "GitLab token is invalid or expired. Reconnect your GitLab instance."
  }

  if (error.status === 403) {
    if (hasScopeErrorHint(error.responseBody)) {
      return "GitLab token is missing required scope. Reconnect with a token that includes api scope."
    }
    return "GitLab denied webhook management for this project. You may need Maintainer or Owner role."
  }

  if (error.status === 404) {
    return "GitLab project not found or access is restricted."
  }

  return null
}

type RequestOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE"
  body?: unknown
}

type GitLabHook = {
  id: number
  url: string
}

const MAX_ERROR_BODY_LENGTH = 1_000

const buildApiUrl = (instanceUrl: string, apiPath: string) => {
  if (!apiPath.startsWith("/")) {
    throw new Error("GitLab API path must start with '/'.")
  }
  return `${instanceUrl}${apiPath}`
}

const readErrorBody = async (response: Response) => {
  let text = ""
  try {
    text = await response.text()
  } catch {
    return undefined
  }
  if (!text) {
    return undefined
  }
  return text.slice(0, MAX_ERROR_BODY_LENGTH)
}

const gitlabRequest = async (
  instanceUrl: string,
  token: string,
  apiPath: string,
  { method = "GET", body }: RequestOptions = {},
) => {
  const response = await fetch(buildApiUrl(instanceUrl, apiPath), {
    method,
    headers: {
      "content-type": "application/json",
      "private-token": token,
      "user-agent": "argus-app",
    },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  })

  if (!response.ok) {
    const responseBody = await readErrorBody(response)
    throw new GitLabApiError(
      `GitLab request failed (${response.status})${responseBody ? `: ${responseBody}` : ""}`,
      response.status,
      responseBody,
    )
  }

  return response
}

const gitlabJson = async <T>(
  instanceUrl: string,
  token: string,
  apiPath: string,
  options?: RequestOptions,
) => {
  const response = await gitlabRequest(instanceUrl, token, apiPath, options)
  return (await response.json()) as T
}

const appendFormValue = (
  params: URLSearchParams,
  key: string,
  value: unknown,
) => {
  if (value === undefined || value === null) {
    return
  }

  if (typeof value === "object" && !Array.isArray(value)) {
    for (const [nestedKey, nestedValue] of Object.entries(value as Record<string, unknown>)) {
      appendFormValue(params, `${key}[${nestedKey}]`, nestedValue)
    }
    return
  }

  params.append(key, String(value))
}

const toFormUrlEncodedBody = (payload: Record<string, unknown>) => {
  const params = new URLSearchParams()
  for (const [key, value] of Object.entries(payload)) {
    appendFormValue(params, key, value)
  }
  return params.toString()
}

const gitlabForm = async <T>(
  instanceUrl: string,
  token: string,
  apiPath: string,
  body: Record<string, unknown>,
  method: RequestOptions["method"] = "POST",
) => {
  const response = await fetch(buildApiUrl(instanceUrl, apiPath), {
    method,
    headers: {
      "content-type": "application/x-www-form-urlencoded",
      "private-token": token,
      "user-agent": "argus-app",
    },
    body: toFormUrlEncodedBody(body),
  })

  if (!response.ok) {
    const responseBody = await readErrorBody(response)
    throw new GitLabApiError(
      `GitLab request failed (${response.status})${responseBody ? `: ${responseBody}` : ""}`,
      response.status,
      responseBody,
    )
  }

  return (await response.json()) as T
}

const encodeProjectId = (projectId: string) => encodeURIComponent(projectId)

export const listProjectHooks = (instanceUrl: string, token: string, projectId: string) =>
  gitlabJson<Array<GitLabHook>>(instanceUrl, token, `/api/v4/projects/${encodeProjectId(projectId)}/hooks`)

export const upsertProjectWebhook = async ({
  instanceUrl,
  token,
  projectId,
  callbackUrl,
  secret,
}: {
  instanceUrl: string
  token: string
  projectId: string
  callbackUrl: string
  secret: string
}) => {
  const hooks = await listProjectHooks(instanceUrl, token, projectId)
  const matchingHook = hooks.find((hook) => hook.url === callbackUrl)

  const payload = {
    url: callbackUrl,
    push_events: true,
    tag_push_events: false,
    merge_requests_events: true,
    enable_ssl_verification: true,
    token: secret,
  }

  if (matchingHook) {
    const updated = await gitlabJson<{ id: number }>(
      instanceUrl,
      token,
      `/api/v4/projects/${encodeProjectId(projectId)}/hooks/${matchingHook.id}`,
      {
        method: "PUT",
        body: payload,
      },
    )
    return {
      hookId: String(updated.id),
      created: false,
    }
  }

  const created = await gitlabJson<{ id: number }>(
    instanceUrl,
    token,
    `/api/v4/projects/${encodeProjectId(projectId)}/hooks`,
    {
      method: "POST",
      body: payload,
    },
  )

  return {
    hookId: String(created.id),
    created: true,
  }
}

export const deleteProjectWebhook = async ({
  instanceUrl,
  token,
  projectId,
  callbackUrl,
  hookId,
}: {
  instanceUrl: string
  token: string
  projectId: string
  callbackUrl: string
  hookId: string | null
}) => {
  const encodedProjectId = encodeProjectId(projectId)

  const deleteById = async (id: string) => {
    try {
      await gitlabRequest(instanceUrl, token, `/api/v4/projects/${encodedProjectId}/hooks/${id}`, {
        method: "DELETE",
      })
      return true
    } catch (error) {
      if (error instanceof GitLabApiError && error.status === 404) {
        return false
      }
      throw error
    }
  }

  if (hookId && await deleteById(hookId)) {
    return true
  }

  const hooks = await listProjectHooks(instanceUrl, token, projectId)
  const matchingHook = hooks.find((hook) => hook.url === callbackUrl)
  if (!matchingHook) {
    return false
  }

  await deleteById(String(matchingHook.id))
  return true
}

