export function LlmResponsePreview({ raw }: { raw: string }) {
  const { cleaned, isJson } = formatResponsePreview(raw)

  if (!isJson) {
    return (
      <div className="max-h-64 overflow-y-auto overflow-x-hidden rounded-lg border bg-muted/30 overscroll-contain">
        <pre className="px-3 py-2 font-mono text-[11px] leading-relaxed whitespace-pre-wrap break-words">
          {cleaned}
        </pre>
      </div>
    )
  }

  const escaped = cleaned
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")

  const highlighted = escaped
    .replace(
      /(&quot;|")((?:[^"\\]|\\.)*)(&quot;|")\s*:/g,
      '<span class="text-violet-600 dark:text-violet-400">"$2"</span>:',
    )
    .replace(
      /:\s*(&quot;|")((?:[^"\\]|\\.)*)(&quot;|")/g,
      ': <span class="text-emerald-600 dark:text-emerald-400">"$2"</span>',
    )
    .replace(
      /:\s*(\d+(?:\.\d+)?)/g,
      ': <span class="text-amber-600 dark:text-amber-400">$1</span>',
    )
    .replace(
      /:\s*(true|false|null)\b/g,
      ': <span class="text-sky-600 dark:text-sky-400">$1</span>',
    )

  return (
    <div className="max-h-64 overflow-auto rounded-lg border bg-muted/30 overscroll-contain">
      <pre
        className="min-w-max px-3 py-2 font-mono text-[11px] leading-relaxed whitespace-pre"
        dangerouslySetInnerHTML={{ __html: highlighted }}
      />
    </div>
  )
}

