import { inArray, sql } from 'drizzle-orm'
import {
  createEmbedderCore,
  type EmbeddingTelemetry,
} from '@argus/shared-runtime/indexing-embedder-core'

import { db } from '@/lib/db'
import { indexEmbeddingCache } from '@/lib/db/schema'
import { INDEX_VECTOR_DIMENSION } from '@argus/contracts-indexing'
import { estimateEmbeddingCostUsd } from '@/lib/indexing/embedding-cost'
import type { VectorChunkRecord } from '@argus/contracts-indexing'
import { sha256Hex } from '@/lib/utils/hash'

const loadCache = async (chunkIds: string[]) => {
  if (chunkIds.length === 0) {
    return new Map<string, { model: string; embedding: number[] }>()
  }

  const rows = await db
    .select({
      chunkId: indexEmbeddingCache.chunkId,
      model: indexEmbeddingCache.model,
      embedding: indexEmbeddingCache.embedding,
    })
    .from(indexEmbeddingCache)
    .where(inArray(indexEmbeddingCache.chunkId, chunkIds))

  return new Map(rows.map((row) => [row.chunkId, { model: row.model, embedding: row.embedding }]))
}

const upsertCache = async (
  items: Array<{ chunkId: string; embedding: number[] }>,
  model: string,
): Promise<void> => {
  if (items.length === 0) {
    return
  }

  const now = new Date()

  await db
    .insert(indexEmbeddingCache)
    .values(
      items.map((item) => ({
        chunkId: item.chunkId,
        model,
        embedding: item.embedding,
        createdAt: now,
        updatedAt: now,
      })),
    )
    .onConflictDoUpdate({
      target: indexEmbeddingCache.chunkId,
      set: {
        model,
        embedding: sql`excluded.embedding`,
        updatedAt: now,
      },
    })
}

const core = createEmbedderCore<VectorChunkRecord>({
  indexVectorDimension: INDEX_VECTOR_DIMENSION,
  estimateEmbeddingCostUsd,
  sha256Hex,
  loadCache,
  upsertCache,
})

export const embedQueryText = core.embedQueryText
export const embedVectorChunks = core.embedVectorChunks
export const __testables = core.__testables
export type { EmbeddingTelemetry }

import { IconActivityHeartbeat, IconBug, IconFileDescription, IconGitPullRequest, IconTestPipe } from "@tabler/icons-react"
import Link from "next/link"

import { WorkflowBuilderPanelClient } from "@/components/sldc-flow/workflow-builder-panel-client"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"

type SldcFlowTab = "builder" | "tool-registry" | "runs"
type SldcFlowPageProps = {
  searchParams: Promise<{
    tab?: string | string[]
  }>
}

type RegistryTool = {
  name: string
  status: "ready" | "beta"
  category: "docs" | "testing" | "review" | "security"
  description: string
}

const TABS: Array<{
  id: SldcFlowTab
  title: string
  description: string
  href: string
}> = [
    {
      id: "builder",
      title: "Builder",
      description: "Panel + React Flow canvas for orchestration.",
      href: "/sldc-flow?tab=builder",
    },
    {
      id: "tool-registry",
      title: "Tool Registry",
      description: "Available AI workflow blocks.",
      href: "/sldc-flow?tab=tool-registry",
    },
    {
      id: "runs",
      title: "Runs",
      description: "Execution throughput and run health.",
      href: "/sldc-flow?tab=runs",
    },
  ]

const REGISTRY_TOOLS: RegistryTool[] = [
  {
    name: "Diagram + Documentation",
    status: "ready",
    category: "docs",
    description: "Creates architecture diagrams and updates markdown/spec documentation.",
  },
  {
    name: "Test Generation",
    status: "ready",
    category: "testing",
    description: "Drafts high-value tests from change context and risk patterns.",
  },
  {
    name: "Code Review",
    status: "ready",
    category: "review",
    description: "Generates review findings with severity and file-level guidance.",
  },
  {
    name: "Vulnerability Scan + Fix",
    status: "ready",
    category: "security",
    description: "Finds vulnerable code paths and proposes safer remediations.",
  },
]

const RUN_METRICS = [
  { label: "Workflow Drafts", value: "4", detail: "Saved in Builder" },
  { label: "Auto-Connected Paths", value: "11", detail: "Generated from tool order" },
  { label: "Ready Tool Blocks", value: "4", detail: "Available for orchestration" },
]

const pickFirst = (value: string | string[] | undefined) =>
  Array.isArray(value) ? value[0] : value

const resolveTab = (value: string | undefined): SldcFlowTab => {
  if (value === "tool-registry" || value === "runs") {
    return value
  }

  return "builder"
}

const categoryLabel = (category: RegistryTool["category"]) => {
  if (category === "docs") {
    return "Docs"
  }
  if (category === "testing") {
    return "Testing"
  }
  if (category === "review") {
    return "Review"
  }
  return "Security"
}

const categoryIcon = (category: RegistryTool["category"]) => {
  if (category === "docs") {
    return IconFileDescription
  }
  if (category === "testing") {
    return IconTestPipe
  }
  if (category === "review") {
    return IconGitPullRequest
  }
  return IconBug
}

const renderToolRegistryTab = () => (
  <section>
    <Card>
      <CardHeader>
        <CardTitle>AI Tool Registry</CardTitle>
        <CardDescription>
          Canonical tool inventory for SLDC workflows.
        </CardDescription>
      </CardHeader>
      <CardContent className="grid gap-3 md:grid-cols-2">
        {REGISTRY_TOOLS.map((tool) => {
          const Icon = categoryIcon(tool.category)

          return (
            <div key={tool.name} className="rounded-lg border p-3">
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-2">
                  <Icon className="size-4 text-muted-foreground" />
                  <p className="text-sm font-semibold">{tool.name}</p>
                </div>
                <Badge variant={tool.status === "ready" ? "default" : "outline"}>{tool.status}</Badge>
              </div>
              <p className="mt-2 text-xs uppercase tracking-wide text-muted-foreground">
                {categoryLabel(tool.category)}
              </p>
              <p className="mt-1 text-sm text-muted-foreground">{tool.description}</p>
            </div>
          )
        })}
      </CardContent>
    </Card>
  </section>
)

export default async function SldcFlowPage({ searchParams }: SldcFlowPageProps) {
  const params = await searchParams
  const activeTab = resolveTab(pickFirst(params.tab))

  return (
    <div className="space-y-4 pt-6">
      <section className="space-y-1">
        <h1 className="text-2xl font-semibold">SLDC Flow</h1>
        <p className="text-sm text-muted-foreground">
          Workflow workspace for chaining diagram/docs, test generation, code review, and security remediation.
        </p>
      </section>

      <section className="grid gap-3 md:grid-cols-3">
        {TABS.map((tab) => {
          const isActive = tab.id === activeTab

          return (
            <Link key={tab.id} href={tab.href} className="block">
              <Card className={isActive ? "border-primary/70 bg-primary/5" : "transition-colors hover:border-primary/50"}>
                <CardHeader className="space-y-2">
                  <div className="flex items-center justify-between gap-2">
                    <CardTitle className="text-base">{tab.title}</CardTitle>
                    {isActive ? <Badge>Current</Badge> : null}
                  </div>
                  <CardDescription>{tab.description}</CardDescription>
                </CardHeader>
              </Card>
            </Link>
          )
        })}
      </section>

      {activeTab === "builder" ? <WorkflowBuilderPanelClient /> : null}
      {activeTab === "tool-registry" ? renderToolRegistryTab() : null}
      {activeTab === "runs" ? renderRunsTab() : null}
    </div>
  )
}

