import { describe, expect, test } from "bun:test"

import {
  buildApiRequestMetrics,
  normalizeUnknownError,
  toScopedErrorContext,
} from "./observability"

describe("shared observability api request helpers", () => {
  test("buildApiRequestMetrics marks success responses", () => {
    expect(
      buildApiRequestMetrics({
        durationMs: 245,
        status: 200,
        method: "GET",
        path: "/api/repo",
        service: "argus-app",
        event: "api.repo.get",
      }),
    ).toEqual({
      requestLatencyMs: 245,
      requestCount: 1,
      errorCount: 0,
      errorRatePct: 0,
      status: 200,
      method: "GET",
      path: "/api/repo",
      service: "argus-app",
      event: "api.repo.get",
    })
  })

  test("buildApiRequestMetrics marks error responses", () => {
    expect(
      buildApiRequestMetrics({
        durationMs: 31,
        status: 503,
        method: "POST",
        path: "/api/reindex",
        service: "indexer",
        event: "api.reindex.post",
      }),
    ).toEqual({
      requestLatencyMs: 31,
      requestCount: 1,
      errorCount: 1,
      errorRatePct: 100,
      status: 503,
      method: "POST",
      path: "/api/reindex",
      service: "indexer",
      event: "api.reindex.post",
    })
  })

  test("normalizeUnknownError preserves errors and normalizes unknown values", () => {
    const original = new Error("boom")
    expect(normalizeUnknownError(original)).toBe(original)
    expect(normalizeUnknownError("failed").message).toBe("failed")
    expect(normalizeUnknownError({ foo: "bar" }).message).toBe("Unknown error.")
  })

  test("toScopedErrorContext maps metadata and applies defaults", () => {
    expect(
      toScopedErrorContext({
        why: "bad payload",
      }),
    ).toEqual({
      errorCode: "UNEXPECTED_ERROR",
      why: "bad payload",
      fix: undefined,
      link: undefined,
      errorDetails: null,
    })
  })
})

use std::path::{Path, PathBuf};

use pyo3::exceptions::PyValueError;
use pyo3::prelude::*;
use pyo3::types::{PyDict, PyDictMethods, PyModule};

use crate::core::parse::chunker::TreeSitterChunker;
use crate::core::parse::languages::parse_language_name;
use crate::core::parse::registry::{
  register_language, ChunkKind, CustomGrammarSource, CustomQuerySet, RegisterLanguageOptions,
};
use crate::path_policy::resolve_path_within_root;

use super::bindings::json_to_py;
use super::path::read_text_file;

const QUERY_FIELD_NAMES: [&str; 7] = [
  "functions",
  "classes",
  "types",
  "variables",
  "imports",
  "exports",
  "comments",
];

#[pyfunction(signature = (file_path, content=None, language=None, content_path=None))]
fn chunk_file(
  file_path: &str,
  content: Option<&str>,
  language: Option<&str>,
  content_path: Option<&str>,
) -> PyResult<PyObject> {
  let content = resolve_chunk_content(file_path, content, content_path)?;
  let chunks = TreeSitterChunker::chunk_file_with_language(file_path, &content, language);
  let value = serde_json::to_value(chunks).map_err(|err| PyValueError::new_err(err.to_string()))?;
  Python::with_gil(|py| json_to_py(py, &value))
}

#[pyfunction]
fn register_chunk_language(options: &Bound<'_, PyDict>) -> PyResult<()> {

  let id = get_required_string(options, "id")?;
  let extensions = get_string_list(options, "extensions")?;

  let grammar = get_optional_dict(options, "grammar")?
    .ok_or_else(|| PyValueError::new_err("missing required field: grammar"))?;
  let grammar_kind =
    get_optional_string(&grammar, "kind")?.unwrap_or_else(|| "builtin".to_string());
  let grammar = match grammar_kind.as_str() {
    "builtin" => {
      let builtin = get_required_string(&grammar, "builtin")?;
      let language = parse_language_name(&builtin).ok_or_else(|| {
        PyValueError::new_err(format!("unsupported built-in grammar language: {builtin}"))
      })?;
      CustomGrammarSource::Builtin(language)
    }
    "dylib" => {
      let path = get_required_string(&grammar, "dylib_path")?;
      let symbol = get_required_string(&grammar, "symbol")?;
      CustomGrammarSource::Dylib {
        path: PathBuf::from(path),
        symbol,
      }
    }
    _ => {
      return Err(PyValueError::new_err(format!(
        "unsupported grammar kind: {grammar_kind}"
      )));
    }
  };

  let queries = parse_custom_queries(options)?;

  let chunk_kinds = get_string_list(options, "chunk_kinds")?
    .into_iter()
    .map(|kind| {
      ChunkKind::from_name(kind.as_str())
        .ok_or_else(|| PyValueError::new_err(format!("unsupported chunk kind: {kind}")))
    })
    .collect::<PyResult<Vec<_>>>()?;

  let registration = RegisterLanguageOptions {
    id,
    extensions,
    grammar,
    queries,
    chunk_kinds,
  };
  register_language(registration).map_err(PyValueError::new_err)?;
  Ok(())
}

fn resolve_chunk_content(
  file_path: &str,
  content: Option<&str>,
  content_path: Option<&str>,
) -> PyResult<String> {
  let read_root = std::env::current_dir()
    .map_err(|err| PyValueError::new_err(format!("failed to resolve current directory: {err}")))?;
  if content.is_some() && content_path.is_some() {
    return Err(PyValueError::new_err(
      "chunk_file accepts either content or content_path, not both",
    ));
  }
  if let Some(content) = content {
    return Ok(content.to_string());
  }
  if let Some(path) = content_path {
    let path = resolve_path_within_root(&read_root, Path::new(&path), "content_path")
      .map_err(PyValueError::new_err)?;
    return read_text_file(path);
  }

  let candidate = resolve_path_within_root(&read_root, Path::new(file_path), "file_path")
    .map_err(PyValueError::new_err)?;
  if candidate.is_file() {
    return read_text_file(candidate);
  }

  Err(PyValueError::new_err(
    "chunk_file requires content or content_path (or a readable file_path on disk)",
  ))
}

fn parse_custom_queries(options: &Bound<'_, PyDict>) -> PyResult<CustomQuerySet> {
  let mut queries = CustomQuerySet::default();
  let read_root = std::env::current_dir()
    .map_err(|err| PyValueError::new_err(format!("failed to resolve current directory: {err}")))?;

if let Some(dir) = get_optional_string(options, "queries_dir")? {
  let dir = resolve_path_within_root(&read_root, Path::new(&dir), "queries_dir")
    .map_err(PyValueError::new_err)?;
  for field in QUERY_FIELD_NAMES {
    let path = dir.join(format!("{field}.scm"));
    if path.is_file() {
      set_query_field(&mut queries, field, Some(read_text_file(path)?));
    }
  }
}

if let Some(query_paths) = get_optional_dict(options, "query_paths")? {
  for field in QUERY_FIELD_NAMES {
    if let Some(path) = get_optional_string(&query_paths, field)? {
      let path = resolve_path_within_root(&read_root, Path::new(&path), "query_paths")
        .map_err(PyValueError::new_err)?;
      set_query_field(&mut queries, field, Some(read_text_file(path)?));
    }
  }
}

if let Some(inline) = get_optional_dict(options, "queries")? {
  for field in QUERY_FIELD_NAMES {
    let path_key = format!("{field}_path");
    if let Some(path) = get_optional_string(&inline, &path_key)? {
      let path = resolve_path_within_root(&read_root, Path::new(&path), &path_key)
        .map_err(PyValueError::new_err)?;
      set_query_field(&mut queries, field, Some(read_text_file(path)?));
    }
  }
  if let Some(value) = get_optional_string(&inline, "functions")? {
    queries.functions = Some(value);
  }
  if let Some(value) = get_optional_string(&inline, "classes")? {
    queries.classes = Some(value);
  }
  if let Some(value) = get_optional_string(&inline, "types")? {
    queries.types = Some(value);
  }
  if let Some(value) = get_optional_string(&inline, "variables")? {
    queries.variables = Some(value);
  }
  if let Some(value) = get_optional_string(&inline, "imports")? {
    queries.imports = Some(value);
  }
  if let Some(value) = get_optional_string(&inline, "exports")? {
    queries.exports = Some(value);
  }
  if let Some(value) = get_optional_string(&inline, "comments")? {
    queries.comments = Some(value);
  }
}

Ok(queries)

}

fn set_query_field(queries: &mut CustomQuerySet, field: &str, value: Option<String>) {
  match field {
    "functions" => queries.functions = value,
    "classes" => queries.classes = value,
    "types" => queries.types = value,
    "variables" => queries.variables = value,
    "imports" => queries.imports = value,
    "exports" => queries.exports = value,
    "comments" => queries.comments = value,
    _ => {}
  }
}

fn get_optional_dict<'py>(
  dict: &'py Bound<'py, PyDict>,
  key: &str,
) -> PyResult<Option<Bound<'py, PyDict>>> {
  match PyDictMethods::get_item(dict, key)? {
    Some(value) => value
      .downcast_into::<PyDict>()
      .map(Some)
      .map_err(Into::into),
    None => Ok(None),
  }
}

fn get_optional_string(dict: &Bound<'_, PyDict>, key: &str) -> PyResult<Option<String>> {
  match dict.get_item(key)? {
    Some(value) => value.extract::<String>().map(Some),
    None => Ok(None),
  }
}

fn get_required_string(dict: &Bound<'_, PyDict>, key: &str) -> PyResult<String> {
  get_optional_string(dict, key)?
    .ok_or_else(|| PyValueError::new_err(format!("missing required field: {key}")))
}

fn get_string_list(dict: &Bound<'_, PyDict>, key: &str) -> PyResult<Vec<String>> {
  match dict.get_item(key)? {
    Some(value) => value.extract::<Vec<String>>(),
    None => Ok(Vec::new()),
  }
}

pub(crate) fn register_chunking(module: &Bound<'_, PyModule>) -> PyResult<()> {
  module.add_function(wrap_pyfunction!(chunk_file, module)?)?;
  module.add_function(wrap_pyfunction!(register_chunk_language, module)?)?;
  Ok(())
}

