  assert!(csharp_cmd.args.iter().any(|arg| arg == "index"));
  assert!(csharp_cmd.args.iter().any(|arg| arg == "--solution"));
  Ok(())
}

#[test]
fn clang_indexer_uses_override_path() -> Result<(), Box<dyn std::error::Error>> {
  let temp = tempfile::tempdir()?;
  let files = vec!["src/main.cpp".to_string()];
  let config = ScipIndexerConfig {
    clang: ScipClangConfig {
      compile_commands_path: Some(temp.path().join("custom/compile_commands.json")),
