#[test]

  fn java_and_csharp_indexers_are_opt_in() -> Result<(), Box<dyn std::error::Error>> {
    let temp = tempfile::tempdir()?;
    let files = vec!["src/App.java".to_string(), "src/App.cs".to_string()];

    let commands =
      default_indexer_commands_with_config(temp.path(), &files, &ScipIndexerConfig::default());
    assert!(!commands.iter().any(|cmd| cmd.language == "java"));
    assert!(!commands.iter().any(|cmd| cmd.language == "csharp"));

