pub(crate) const DEFAULT_EMBEDDING_BASE_URL: &str = "https://api.openai.com/v1";
pub(crate) const DEFAULT_EMBEDDING_MODEL: &str = "text-embedding-3-small";
pub(crate) const DEFAULT_EMBEDDING_DIMENSION: u32 = 1536;
pub(crate) const DEFAULT_EMBEDDING_TIMEOUT_SECONDS: u32 = 30;
pub(crate) const DEFAULT_VECTOR_BATCH_SIZE: u32 = 256;
pub(crate) const DEFAULT_VECTOR_CONCURRENCY: u32 = 4;

pub(crate) fn with_default_openai_key(api_key: Option<String>) -> Option<String> {
  match api_key {
    Some(key) if !key.trim().is_empty() => Some(key),
    _ => std::env::var("OPENAI_API_KEY")
      .ok()
      .filter(|value| !value.trim().is_empty()),
  }
}

fn normalize_paths(paths: Vec<String>) -> Vec<String> {
  let mut out = Vec::new();
  for path in paths {
    let normalized = path.trim();
    if normalized.is_empty() {
      continue;
    }
    if !out.iter().any(|existing| existing == normalized) {
      out.push(normalized.to_string());
    }
  }
  if out.is_empty() {
    out.push(".".to_string());
  }
  out
}

fn append_unique(target: &mut Vec<String>, values: Vec<String>) {
  for value in values {
    if !target.iter().any(|existing| existing == &value) {
      target.push(value);
    }
  }
}

fn extract_string_args(args: &Bound<'_, PyTuple>, name: &str) -> PyResult<Vec<String>> {
  if args.is_empty() {
    return Ok(Vec::new());
  }

  if args.len() == 1 {
    let first = args.get_item(0)?;
    if let Ok(values) = first.extract::<Vec<String>>() {
      return Ok(
        values
          .into_iter()
          .map(|value| value.trim().to_string())
          .filter(|value| !value.is_empty())
          .collect(),
      );
    }
  }

  let mut out = Vec::new();
  for item in args.iter() {
    let value = item
      .extract::<String>()
      .map_err(|_| PyValueError::new_err(format!("{name} accepts strings or a list of strings")))?;
    let value = value.trim().to_string();
    if value.is_empty() {
      continue;
    }
    out.push(value);
  }
  Ok(out)
}

impl VectorConfig {
  #[new]
  #[pyo3(signature = (
    model=DEFAULT_EMBEDDING_MODEL.to_string(),
    api_key=None,
    base_url=DEFAULT_EMBEDDING_BASE_URL.to_string(),
    dimension=DEFAULT_EMBEDDING_DIMENSION,
    timeout_s=DEFAULT_EMBEDDING_TIMEOUT_SECONDS,
  ))]
  fn new(
    model: String,
    api_key: Option<String>,
    base_url: String,
    dimension: u32,
    timeout_s: u32,
  ) -> PyResult<Self> {
    if base_url.trim().is_empty() {
      return Err(PyValueError::new_err("base_url cannot be empty"));
    }
    if model.trim().is_empty() {
      return Err(PyValueError::new_err("model cannot be empty"));
    }
    if dimension == 0 {
      return Err(PyValueError::new_err("dimension must be greater than 0"));
    }
    if timeout_s == 0 {
      return Err(PyValueError::new_err("timeout_s must be greater than 0"));
    }

    Ok(Self {
      base_url,
      model,
      api_key: with_default_openai_key(api_key),
      dimension: Some(dimension as usize),
      timeout_ms: Some((timeout_s as u64) * 1000),
    })
  }

  #[getter]
  fn base_url(&self) -> String {
    self.base_url.clone()
  }

  #[getter]
  fn model(&self) -> String {
    self.model.clone()
  }

  #[getter]
  fn api_key(&self) -> Option<String> {
    self.api_key.clone()
  }

  #[getter]
  fn dimension(&self) -> Option<u32> {
    self.dimension.map(|value| value as u32)
  }

  #[getter]
  fn timeout_ms(&self) -> Option<u32> {
    self.timeout_ms.map(|value| value as u32)
  }
}

impl VectorConfig {
  fn to_provider(&self) -> PyResult<HttpEmbeddingsProvider> {
    let mut config = HttpEmbeddingConfig::new(
      self.base_url.clone(),
      self.api_key.clone(),
      self.model.clone(),
    );
    config.dimension = self.dimension;
    config.timeout = self.timeout_ms.map(Duration::from_millis);
    HttpEmbeddingsProvider::new(config).map_err(|err| PyValueError::new_err(err.to_string()))
  }
}

