  vector_concurrency: Option<usize>,
}

impl Indexer {

fn from_parts(
  root: PathBuf,
  paths: Vec<String>,
  include: Vec<String>,
  exclude: Vec<String>,
  respect_gitignore: bool,
) -> Self {
  Self {
    root,
    paths: normalize_paths(paths),
    include,
    exclude,
    respect_gitignore,
    vector_config: None,
    vector_batch_size: None,
    vector_concurrency: None,
  }
}

pub(crate) fn from_cli(
  root: PathBuf,
  paths: Vec<String>,
  include: Vec<String>,
  exclude: Vec<String>,
  respect_gitignore: bool,
) -> Self {
  Self::from_parts(root, paths, include, exclude, respect_gitignore)
}

fn configure_vectors(
  &mut self,
  model: String,
  api_key: Option<String>,
  base_url: String,
  dimension: u32,
  timeout_s: u32,
  batch_size: u32,
  concurrency: u32,
) -> PyResult<()> {
  if batch_size == 0 {
    return Err(PyValueError::new_err("batch_size must be greater than 0"));
  }
  if concurrency == 0 {
    return Err(PyValueError::new_err("concurrency must be greater than 0"));
  }
  if dimension == 0 {
    return Err(PyValueError::new_err("dimension must be greater than 0"));
  }
  if timeout_s == 0 {
    return Err(PyValueError::new_err("timeout_s must be greater than 0"));
  }

  self.vector_config = Some(VectorConfig {
    base_url,
    model,
    api_key: with_default_openai_key(api_key),
    dimension: Some(dimension as usize),
    timeout_ms: Some((timeout_s as u64) * 1000),
  });
  self.vector_batch_size = Some(batch_size as usize);
  self.vector_concurrency = Some(concurrency as usize);
  Ok(())
}

pub(crate) fn enable_vectors_for_cli(
  &mut self,
  model: String,
  api_key: Option<String>,
  base_url: String,
  dimension: u32,
  timeout_s: u32,
  batch_size: u32,
  concurrency: u32,
) -> PyResult<()> {
  self.configure_vectors(
    model,
    api_key,
    base_url,
    dimension,
    timeout_s,
    batch_size,
    concurrency,
  )
}

  fn to_index_options(&self) -> PyResult<IndexOptions> {
    let project_root = self.root.clone();
    let mut options = IndexOptions::new(project_root.clone());
    options.inputs = ParseInputs {
      paths: self
        .paths
        .iter()
        .map(|value| resolve_project_path(&project_root, PathBuf::from(value)))
        .collect(),
      include: self.include.clone(),
      exclude: self.exclude.clone(),
      respect_gitignore: self.respect_gitignore,
    };
    options.phases = IndexPhases {
      parse: true,
      graph: false,
      vector: self.vector_config.is_some(),
      scip: false,
      index_pack: false,
    };

    if let Some(vector_config) = &self.vector_config {
      options.vector_provider = Some(Arc::new(vector_config.to_provider()?));
    }
    if let Some(batch_size) = self.vector_batch_size {
      options.vector.batch_size = batch_size;
    }
    if let Some(concurrency) = self.vector_concurrency {
      options.vector.concurrency = concurrency;
    }

    Ok(options)
  }
}

