#[pyo3(signature = (batch_size=None, high_water_mark=16))]
fn stream(&self, batch_size: Option<u32>, high_water_mark: u32) -> PyResult<IndexStream> {
  if batch_size == Some(0) {
    return Err(PyValueError::new_err("batch_size must be greater than 0"));
  }
  if high_water_mark == 0 {
    return Err(PyValueError::new_err(
      "high_water_mark must be greater than 0",
    ));
  }

  let mut options = self.to_index_options()?;
  if let Some(size) = batch_size {
    let size = size as usize;
    options.parse_batch = size;
    options.graph_batch = size;
    options.scip_batch = size;
    options.vector.batch_size = size;
  }

  let mut stream_options = parse_stream_options(&options);
  stream_options.high_water_mark = high_water_mark as usize;
  start_index_stream(options, stream_options, true)
}

#[pyo3(signature = (graph=true, vector=None, scip=false, index_pack=false))]

fn index(
  &self,
  graph: bool,
  vector: Option<bool>,
  scip: bool,
  index_pack: bool,
) -> PyResult<IndexRun> {
  let mut options = self.to_index_options()?;
  options.phases.graph = graph;
  options.phases.vector = vector.unwrap_or(self.vector_config.is_some());
  options.phases.scip = scip;
  options.phases.index_pack = index_pack;

  if options.phases.vector && options.vector_provider.is_none() {
    return Err(PyValueError::new_err(
      "vector phase requires use_vectors(...)",
    ));
  }

  let start = Instant::now();

  let result = Python::with_gil(|py| {
    py.allow_threads(|| {
      let engine = IndexEngine::new(options);
      let cancel = CancelToken::new();
      engine.run(&mut NoopIndexSink, &cancel)
    })
  });

  let stats = result.map_err(|err| PyValueError::new_err(err.to_string()))?;
  Ok(build_index_run(
    start.elapsed().as_millis() as u64,
    &stats,
    None,
  ))
}

#[pyo3(signature = (db=None, clear=false, graph=true, vector=None, scip=false, index_pack=false))]

pub(crate) fn persist(
  &self,
  db: Option<&KiteDB>,
  clear: bool,
  graph: bool,
  vector: Option<bool>,
  scip: bool,
  index_pack: bool,
) -> PyResult<IndexRun> {
  let mut options = self.to_index_options()?;
  options.phases.graph = graph;
  options.phases.vector = vector.unwrap_or(self.vector_config.is_some());
  options.phases.scip = scip;
  options.phases.index_pack = index_pack;

  if options.phases.vector && options.vector_provider.is_none() {
    return Err(PyValueError::new_err(
      "vector phase requires use_vectors(...)",
    ));
  }

  let store = db
    .cloned()
    .unwrap_or_else(|| KiteDB::default_for_root(&self.root));
  let store_path = store.path.clone();
  let start = Instant::now();

  let result = Python::with_gil(|py| {
    py.allow_threads(|| -> PyResult<crate::core::index_engine::IndexStats> {
      let engine = IndexEngine::new(options);
      let cancel = CancelToken::new();
      let mut sink = KiteDbIndexSink::new(store_path.clone(), clear);
      let stats = match engine.run(&mut sink, &cancel) {
        Ok(stats) => stats,
        Err(err) => {
          let _ = sink.abort();
          return Err(PyValueError::new_err(err.to_string()));
        }
      };
      sink
        .finish()
        .map_err(|err| PyValueError::new_err(err.to_string()))?;
      Ok(stats)
    })
  });

  let stats = result?;
  Ok(build_index_run(
    start.elapsed().as_millis() as u64,
    &stats,
    Some(store.path.to_string_lossy().to_string()),
  ))
}

pub(crate) fn search(
  &self,
  query: String,
  db: Option<&KiteDB>,
  top_k: u32,
) -> PyResult<Vec<SearchHit>> {
  if query.trim().is_empty() {
    return Err(PyValueError::new_err("query cannot be empty"));
  }

  let vector_config = self
    .vector_config
    .as_ref()
    .ok_or_else(|| PyValueError::new_err("search requires use_vectors(...)"))?;
  let provider = vector_config.to_provider()?;
  let store = db
    .cloned()
    .unwrap_or_else(|| KiteDB::default_for_root(&self.root));
  let top_k = top_k.clamp(1, 50) as usize;

  let hits = Python::with_gil(|py| {
    py.allow_threads(
      || -> PyResult<Vec<crate::core::kitedb_store::KiteSearchHit>> {
        let embeddings = provider
          .embed_texts(&[query.as_str()])
          .map_err(|err| PyValueError::new_err(err.to_string()))?;
        let embedding = embeddings
          .into_iter()
          .next()
          .ok_or_else(|| PyValueError::new_err("vector provider returned no embeddings"))?;

        let store = KiteCodeStore::open_readonly(store.path.clone())
          .map_err(|err| PyValueError::new_err(err.to_string()))?;
        store
          .search_by_embedding(&embedding, top_k)
          .map_err(|err| PyValueError::new_err(err.to_string()))
      },
    )
  })?;

  Ok(
    hits
      .into_iter()
      .map(|hit| SearchHit {
        score: hit.score,
        chunk_id: hit.chunk_id,
        file_path: hit.file_path,
        range_json: hit.range_json,
      })
      .collect(),
  )
}

#[pyo3(signature = (name=None, node_id=None, db=None, limit=50))]
fn trace_callers(
  &self,
  name: Option<String>,
  node_id: Option<String>,
  db: Option<&KiteDB>,
  limit: u32,
) -> PyResult<Vec<GraphNeighbor>> {
  if node_id.is_none() && name.is_none() {
    return Err(PyValueError::new_err(
      "trace_callers requires name or node_id",
    ));
  }

  let store = db
    .cloned()
    .unwrap_or_else(|| KiteDB::default_for_root(&self.root));
  let limit = limit.clamp(1, 500) as usize;

  let callers = Python::with_gil(|py| {
    py.allow_threads(|| -> PyResult<Vec<KiteGraphNeighbor>> {
      let store = KiteCodeStore::open_readonly(store.path.clone())
        .map_err(|err| PyValueError::new_err(err.to_string()))?;
      let resolved = resolve_trace_node_id(&store, node_id.as_deref(), name.as_deref())?;
      store
        .graph_neighbors(&resolved, "CALLS", "in", limit)
        .map_err(|err| PyValueError::new_err(err.to_string()))
    })
  })?;

  Ok(callers.into_iter().map(GraphNeighbor::from_core).collect())
}

#[pyo3(signature = (name=None, node_id=None, db=None, limit=200, depth=3))]

  fn trace_impact(
    &self,
    name: Option<String>,
    node_id: Option<String>,
    db: Option<&KiteDB>,
    limit: u32,
    depth: u32,
  ) -> PyResult<Vec<ImpactHit>> {
    if node_id.is_none() && name.is_none() {
      return Err(PyValueError::new_err(
        "trace_impact requires name or node_id",
      ));
    }

    let store = db
      .cloned()
      .unwrap_or_else(|| KiteDB::default_for_root(&self.root));
    let limit = limit.clamp(1, 500) as usize;
    let depth = depth.clamp(1, 64) as usize;

    let impact = Python::with_gil(|py| {
      py.allow_threads(|| -> PyResult<Vec<CoreKiteImpactHit>> {
        let store = KiteCodeStore::open_readonly(store.path.clone())
          .map_err(|err| PyValueError::new_err(err.to_string()))?;
        let resolved = resolve_trace_node_id(&store, node_id.as_deref(), name.as_deref())?;
        store
          .trace_impact_callers(&resolved, depth, limit)
          .map_err(|err| PyValueError::new_err(err.to_string()))
      })
    })?;

    Ok(
      impact
        .into_iter()
        .map(|entry| ImpactHit {
          depth: entry.depth as u32,
          node: GraphNeighbor::from_core(entry.node),
        })
        .collect(),
    )
  }
}

fn best_trace_candidate(candidates: &[KiteGraphNeighbor]) -> Option<&KiteGraphNeighbor> {
  candidates.iter().min_by(|a, b| {
    let a_file = a.kind.as_deref() == Some("file");
    let b_file = b.kind.as_deref() == Some("file");
    a_file
      .cmp(&b_file)
      .then_with(|| a.file_path.is_none().cmp(&b.file_path.is_none()))
      .then_with(|| a.id.cmp(&b.id))
  })
}

fn resolve_trace_node_id(
  store: &KiteCodeStore,
  node_id: Option<&str>,
  name: Option<&str>,
) -> PyResult<String> {
  if let Some(node_id) = node_id {
    return Ok(node_id.to_string());
  }

  let Some(name) = name else {
    return Err(PyValueError::new_err("trace requires name or node_id"));
  };

  let candidates = store
    .find_nodes_by_name(name, 50)
    .map_err(|err| PyValueError::new_err(err.to_string()))?;
  if candidates.is_empty() {
    return Err(PyValueError::new_err(format!(
      "no indexed nodes found with name {name}"
    )));
  }
  let best = best_trace_candidate(&candidates)
    .ok_or_else(|| PyValueError::new_err(format!("failed to pick a candidate node for {name}")))?;

  Ok(best.id.clone())
}

