fn register_events_submodule(py: Python<'_>, module: &Bound<'_, PyModule>) -> PyResult<()> {
  let events = PyModule::new_bound(py, "events")?;
  events.add_class::<PyVectorRecord>()?;
  events.add_class::<PyVectorBatchEvent>()?;
  events.add_class::<PyPipelineStats>()?;
  events.add_class::<PyPipelineCompleteEvent>()?;

  module.add_submodule(&events)?;
  module.setattr("events", &events)?;

  let sys = py.import_bound("sys")?;
  let modules = sys.getattr("modules")?.downcast_into::<PyDict>()?;
  modules.set_item("argus_search.events", &events)?;
  Ok(())
}

fn start_index_stream(
  mut index_options: IndexOptions,
  stream_options: ParsedStreamOptions,
  typed_events: bool,
) -> PyResult<IndexStream> {
  if stream_options.emit_vector_batches {
    index_options.vector.include_chunk = true;
  }

  let queue = StreamQueue::new(stream_options.high_water_mark);
  let cancel = queue.cancel_token();

  std::thread::spawn({
    let queue = queue.clone();
    move || {
      let engine = IndexEngine::new(index_options);
      let mut sink = PyStreamSink {
        queue: queue.clone(),
        emit_parse_batches: stream_options.emit_parse_batches,
        emit_graph_batches: stream_options.emit_graph_batches,
        emit_vector_batches: stream_options.emit_vector_batches,
        emit_scip_batches: stream_options.emit_scip_batches,
        emit_phase_events: stream_options.emit_phase_events,
      };
      let result = engine.run(&mut sink, &cancel);
      match result {
        Ok(_) => queue.close(None),
        Err(err) => queue.close(Some(err.to_string())),
      }
    }
  });

  Ok(IndexStream {
    queue,
    typed_events,
  })
}

#[pyclass(module = "argus_search")]
pub(crate) struct IndexStream {
  queue: StreamQueue,
  typed_events: bool,
}

#[pymethods]

impl IndexStream {
  fn cancel(&self) {
    self.queue.cancel();
  }

  fn __iter__(slf: PyRef<'_, Self>) -> PyRef<'_, Self> {
    slf
  }

  fn __next__(&mut self, py: Python<'_>) -> PyResult<Option<PyObject>> {
    let next = py.allow_threads(|| self.queue.next_blocking());
    match next {
      Ok(Some(value)) => Ok(Some(stream_event_to_py(py, &value, self.typed_events)?)),
      Ok(None) => Ok(None),
      Err(StreamError::Cancelled) => Err(PyValueError::new_err("cancelled")),
      Err(StreamError::Fatal(message)) => Err(PyValueError::new_err(message)),
      Err(StreamError::Closed) => Ok(None),
    }
  }
}

impl Drop for IndexStream {
  fn drop(&mut self) {
    self.queue.cancel();
  }
}

