import path from 'node:path'

const SKIP_DIRS = new Set(['.git', 'node_modules', 'vendor', 'dist', 'build'])
const SKIP_FILES = new Set([
  'bun.lock',
  'package-lock.json',
  'pnpm-lock.yaml',
  'yarn.lock',
  'cargo.lock',
  'composer.lock',
  'go.sum',
])

const BINARY_EXTENSIONS = new Set([
  '.png',
  '.jpg',
  '.jpeg',
  '.gif',
  '.webp',
  '.ico',
  '.pdf',
  '.zip',
  '.gz',
  '.tar',
  '.tgz',
  '.7z',
  '.exe',
  '.dll',
  '.so',
  '.dylib',
  '.woff',
  '.woff2',
  '.ttf',
  '.otf',
  '.mp3',
  '.mp4',
  '.mov',
  '.avi',
])

export const DEFAULT_MAX_FILE_SIZE_BYTES = 512 * 1024

export const shouldSkipPath = (relativePath: string): boolean => {
  const normalized = relativePath.replace(/\\/g, '/').toLowerCase()
  const segments = normalized.split('/').filter(Boolean)
  if (segments.some((segment) => SKIP_DIRS.has(segment))) {
    return true
  }

  const fileName = segments.at(-1)
  if (!fileName) {
    return false
  }

  return SKIP_FILES.has(fileName)
}

export const isLikelyBinary = (relativePath: string, content: Buffer): boolean => {
  const ext = path.extname(relativePath).toLowerCase()
  if (BINARY_EXTENSIONS.has(ext)) {
    return true
  }

  const checkLength = Math.min(content.length, 8_192)
  for (let i = 0; i < checkLength; i += 1) {
    if (content[i] === 0) {
      return true
    }
  }

  return false
}

export const classifySkipReason = (args: {
  relativePath: string
  content: Buffer
  maxFileSizeBytes: number
}): 'path_excluded' | 'binary' | 'file_too_large' | null => {
  if (shouldSkipPath(args.relativePath)) {
    return 'path_excluded'
  }

  if (args.content.length > args.maxFileSizeBytes) {
    return 'file_too_large'
  }

  if (isLikelyBinary(args.relativePath, args.content)) {
    return 'binary'
  }

  return null
}

import { NextResponse } from "next/server"
import { z } from "zod"

import {
  connectGitLabIntegration,
  decryptIntegrationToken,
  getUserIntegration,
} from "@/lib/gitlab/service"
import { normalizeGitLabInstanceUrl } from "@/lib/gitlab/instance"
import { invalidateUserIntegrations } from "@/lib/gitlab/user-integrations-cache"
import {
  getGitLabUserInstanceToken,
  upsertGitLabUserInstanceToken,
} from "@/lib/gitlab/user-token"
import { requireJsonBody } from "@/lib/http/request-json"
import { prewarmMergeRequestSourceBranches } from "@/lib/indexing/mr-auto-index"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const connectSchema = z.object({
  instanceUrl: z.string().min(1),
  token: z.string().min(1).optional(),
  integrationId: z.string().min(1).optional(),
  projectId: z.string().min(1),
  projectPath: z.string().min(1),
  projectName: z.string().min(1),
})

const PREWARM_INLINE_BUDGET_MS = 250

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/gitlab/integrations/connect",
    event: "api.gitlab.integrations.connect",
    handler: async ({ logger }) => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "Invalid connect payload."),
      ])

      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

const parsed = connectSchema.safeParse(body.value)
if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid connect payload." }, { status: 400 }),
  }
}

try {
  const normalizedInstanceUrl = normalizeGitLabInstanceUrl(parsed.data.instanceUrl)
  const requestToken = parsed.data.token?.trim()
  let tokenToUse = requestToken ?? ""

  if (requestToken) {
    // Persistence is best-effort; do not block integration connect on it.
    await upsertGitLabUserInstanceToken({
      userId,
      instanceUrl: normalizedInstanceUrl,
      token: requestToken,
    }).catch(() => null)
  } else {
    let storedToken = null as Awaited<ReturnType<typeof getGitLabUserInstanceToken>>
    try {
      storedToken = await getGitLabUserInstanceToken(
        userId,
        normalizedInstanceUrl,
      )
    } catch {
      storedToken = null
    }

    if (storedToken?.staleAt) {
      return {
        status: 401,
        outcome: "unauthorized",
        response: NextResponse.json(
          {
            error: "Stored GitLab token is stale. Reconnect your GitLab instance.",
            code: "GITLAB_TOKEN_STALE",
            reconnectRequired: true,
          },
          { status: 401 },
        ),
      }
    }

if (storedToken) {
  tokenToUse = storedToken.token
} else {
  const integrationId = parsed.data.integrationId?.trim()
  if (integrationId) {
    const integration = await getUserIntegration(integrationId, userId)
    const isMatchingInstance = integration?.instanceUrl === normalizedInstanceUrl

    if (integration && isMatchingInstance) {
      try {
        const fallbackToken = decryptIntegrationToken(integration).trim()
        if (fallbackToken) {
          tokenToUse = fallbackToken
        }
      } catch {
        // Keep tokenToUse empty so we return token-required below.
      }
    }
  }

  if (!tokenToUse) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        {
          error:
            "Personal access token is required. Reconnect your GitLab instance.",
          code: "GITLAB_TOKEN_REQUIRED",
          reconnectRequired: true,
        },
        { status: 400 },
      ),
    }
  }
}

}

const result = await connectGitLabIntegration({
  userId,
  instanceUrl: normalizedInstanceUrl,
  projectId: parsed.data.projectId,
  projectPath: parsed.data.projectPath,
  projectName: parsed.data.projectName,
  token: tokenToUse,
})
const prewarmPromise = prewarmMergeRequestSourceBranches({
  integrationId: result.integration.id,
}).catch(() => null)
