import { describe, expect, mock, test } from "bun:test"

import {
  loadRouteModule,
  postGitLabJson,
} from "./test-harness"

describe("gitlab proxy route token and upstream handling", () => {
  test("marks token stale and returns stable code on auth failure", async () => {
    globalThis.fetch = mock(async () =>
      new Response("unauthorized", {
        status: 401,
        headers: { "content-type": "text/plain" },
      }),
    ) as unknown as typeof fetch

    const {
      POST,
      markGitLabUserInstanceTokenStale,
      upsertGitLabUserInstanceToken,
    } = await loadRouteModule()

    const response = await postGitLabJson(POST, {
          action: "projects",
          instanceUrl: "https://gitlab.global.lmco.com",
          token: "pat-123",
      })

    const body = await response.json()

    expect(response.status).toBe(401)
    expect(body).toMatchObject({
      code: "GITLAB_TOKEN_INVALID",
      reconnectRequired: true,
    })
    expect(upsertGitLabUserInstanceToken).toHaveBeenCalledWith({
      userId: "user-1",
      instanceUrl: "https://gitlab.global.lmco.com",
      token: "pat-123",
    })
    expect(markGitLabUserInstanceTokenStale).toHaveBeenCalledWith({
      userId: "user-1",
      instanceUrl: "https://gitlab.global.lmco.com",
      reason: "GITLAB_TOKEN_INVALID",
    })
  })

test("continues gitlab token validation when token persistence fails", async () => {
  const fetchMock = mock(async (_url: string, init?: RequestInit) => {
    expect((init?.headers as Record<string, string>)["PRIVATE-TOKEN"]).toBe("pat-123")
    return new Response(JSON.stringify([{ id: 1, name: "proj", path: "proj" }]), {
      status: 200,
      headers: { "content-type": "application/json" },
    })
  })
  globalThis.fetch = fetchMock as unknown as typeof fetch

  const { POST, upsertGitLabUserInstanceToken } = await loadRouteModule({
    upsertThrows: true,
  })

  const response = await postGitLabJson(POST, {
        action: "projects",
        instanceUrl: "https://gitlab.global.lmco.com",
        token: "pat-123",
    })

  const body = await response.json()

  expect(response.status).toBe(200)
  expect(body.data).toEqual([
    expect.objectContaining({
      id: "1",
    }),
  ])
  expect(upsertGitLabUserInstanceToken).toHaveBeenCalled()
})

