import { NextResponse } from "next/server"

import {
  decryptIntegrationToken,
  getUserIntegration,
} from "@/lib/gitlab/service"
import {
  getGitLabUserInstanceToken,
  markGitLabUserInstanceTokenStale,
  upsertGitLabUserInstanceToken,
} from "@/lib/gitlab/user-token"
import { requireJsonBody } from "@/lib/http/request-json"
import { normalizeGitLabInstanceUrl } from "@/lib/gitlab/instance"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

import {
  buildRouteError,
  createGitLabApiClient,
  GitLabRouteError,
  TOKEN_STALE_CODES,
} from "./_proxy/api-client"
import {
  handleGitLabAction,
  isSupportedGitLabAction,
} from "./_proxy/handlers"
import { type GitLabProjectPayload } from "./_proxy/types"

const gitLabApiClient = createGitLabApiClient()

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const resolveTokenForRequest = async ({
  userId,
  instanceUrl,
  requestToken,
  integrationId,
  projectId,
}: {
  userId: string
  instanceUrl: string
  requestToken: string | undefined
  integrationId?: string
  projectId?: string
}) => {
  const normalizedRequestToken = requestToken?.trim()

if (normalizedRequestToken) {
  // Token persistence is best-effort. Read actions should still work even if
  // the optional user-token cache table is unavailable/misaligned.
  await upsertGitLabUserInstanceToken({
    userId,
    instanceUrl,
    token: normalizedRequestToken,
  }).catch(() => null)
  return {
    token: normalizedRequestToken,
    source: "request" as const,
  }
}

let storedToken = null as Awaited<
  ReturnType<typeof getGitLabUserInstanceToken>
>
try {
  storedToken = await getGitLabUserInstanceToken(userId, instanceUrl)
} catch {
  storedToken = null
}

  if (!storedToken) {
    const normalizedIntegrationId = integrationId?.trim()
    const normalizedProjectId = projectId?.trim()

    if (normalizedIntegrationId) {
      const integration = await getUserIntegration(normalizedIntegrationId, userId)
      const matchesScope =
        integration &&
        integration.instanceUrl === instanceUrl &&
        (!normalizedProjectId || integration.projectId === normalizedProjectId)

      if (matchesScope && integration) {
        try {
          const integrationToken = decryptIntegrationToken(integration)
          if (integrationToken.trim()) {
            return {
              token: integrationToken,
              source: "integration" as const,
            }
          }
        } catch {
          // Fall through to token-required error below.
        }
      }
    }

    throw buildRouteError(
      "Personal access token is required. Reconnect your GitLab instance.",
      {
        status: 400,
        code: "GITLAB_TOKEN_REQUIRED",
        reconnectRequired: true,
      },
    )
  }

  if (storedToken.staleAt) {
    throw buildRouteError(
      "Stored GitLab token is stale. Reconnect your GitLab instance.",
      {
        status: 401,
        code: "GITLAB_TOKEN_STALE",
        reconnectRequired: true,
        details: {
          staleAt: storedToken.staleAt.toISOString(),
          staleReason: storedToken.staleReason,
        },
      },
    )
  }

  return {
    token: storedToken.token,
    source: "stored" as const,
  }
}

export async function POST(request: Request) {
  return runWithApiRequestLog({

request,
path: "/api/gitlab",
event: "api.gitlab.proxy",
handler: async ({ logger }) => {
  const [userId, body] = await Promise.all([
    getSessionUserId(),
    requireJsonBody(request, "Invalid request payload."),
  ])

  if (!userId) {
    return {
      status: 401,
      outcome: "unauthorized",
      response: NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 },
      ),
    }
  }

  if (!body.ok) return body.result

  const payloadRoot = asRecord(body.value)
  if (!payloadRoot || payloadRoot.action === undefined) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        { error: "Invalid request payload." },
        { status: 400 },
      ),
    }
  }

  if (!isSupportedGitLabAction(payloadRoot.action)) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        { error: "Unsupported action." },
        { status: 400 },
      ),
    }
  }

  if (!isNonEmptyString(payloadRoot.instanceUrl)) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        { error: "GitLab instance URL is required." },
        { status: 400 },
      ),
    }
  }

  const payload = payloadRoot as GitLabProjectPayload

  let normalizedInstanceUrl: string

try {
  normalizedInstanceUrl = normalizeGitLabInstanceUrl(payloadRoot.instanceUrl)
} catch (error) {
  const message =
    error instanceof Error
      ? error.message
      : "GitLab instance URL is invalid."
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      {
        error: message,
        code: "GITLAB_UPSTREAM_ERROR",
      },
      { status: 400 },
    ),
  }
}

try {
  const resolvedToken = await resolveTokenForRequest({
    userId,
    instanceUrl: normalizedInstanceUrl,
    requestToken: payload.token,
    integrationId: payload.integrationId,
    projectId: payload.projectId,
  })

  logger.set({
    action: payload.action,
    instanceUrl: normalizedInstanceUrl,
    tokenSource: resolvedToken.source,
  })

  return await handleGitLabAction({
    payload,
    instanceUrl: normalizedInstanceUrl,
    token: resolvedToken.token,
    logger,
    client: gitLabApiClient,
  })
} catch (error) {

        const routeError =
          error instanceof GitLabRouteError
            ? error
            : buildRouteError(
                error instanceof Error
                  ? error.message
                  : "Unexpected GitLab lookup error.",
                {
                  status: 502,
                  code: "GITLAB_UPSTREAM_ERROR",
                },
              )

        if (TOKEN_STALE_CODES.has(routeError.code)) {
          await markGitLabUserInstanceTokenStale({
            userId,
            instanceUrl: normalizedInstanceUrl,
            reason: routeError.code,
          }).catch(() => null)
        }

        logger.set({
          errorCode: routeError.code,
          retryable: routeError.retryable,
          reconnectRequired: routeError.reconnectRequired,
        })

        return {
          status: routeError.status,
          outcome: "upstream_error",
          response: NextResponse.json(
            {
              error: routeError.message,
              code: routeError.code,
              retryable: routeError.retryable,
              reconnectRequired: routeError.reconnectRequired,
            },
            { status: routeError.status },
          ),
        }
      }
    },
  })
}

const http = require('node:http')
const path = require('node:path')
const fs = require('node:fs/promises')

const { createArgusSearch } = require('./agent.js')
