function toSse(res, payload) {
  res.statusCode = 200
  res.setHeader('content-type', 'text/event-stream')
  res.setHeader('cache-control', 'no-cache')
  res.setHeader('connection', 'keep-alive')
  res.end(`data: ${JSON.stringify(payload)}\n\n`)
}

function jsonRpcResult({ id, result }) {
  return { jsonrpc: '2.0', id: id ?? null, result }
}

function jsonRpcError({ id, code, message, data }) {
  return {
    jsonrpc: '2.0',
    id: id ?? null,
    error: {
      code,
      message,
      ...(data ? { data } : {}),
    },
  }
}

async function safeResolveWithinRoot(rootDir, unsafePath) {
  const rootInput = path.resolve(String(rootDir))
  const root = await fs.realpath(rootInput).catch(() => rootInput)
  const resolvedInput = path.resolve(root, String(unsafePath))
  const resolved = await fs.realpath(resolvedInput).catch(() => resolvedInput)
  const rel = path.relative(root, resolved)
  if (rel === '..' || rel.startsWith('..' + path.sep) || path.isAbsolute(rel)) {
    throw new Error('path escapes project root')
  }
  return { root, resolved }
}

