async function readRequestBody(req, { maxBytes = 1024 * 1024 } = {}) {
  return new Promise((resolve, reject) => {
    let raw = ''
    let size = 0
    let rejected = false
    req.on('data', (chunk) => {
      if (rejected) return
      size += chunk.length
      if (size > maxBytes) {
        rejected = true
        const error = new Error(`request body too large (${maxBytes} bytes max)`)
        error.code = 'BODY_TOO_LARGE'
        reject(error)
        return
      }
      raw += String(chunk)
    })
    req.on('end', () => resolve(raw))
    req.on('error', (error) => {
      if (rejected) return
      reject(error)
    })
  })
}

function createMcpServer(options) {
  const {
    host = '127.0.0.1',
    port = 17890,
    mcpPath = '/mcp',
    projectRoot,
    inputs,
    vectorProvider,
    streamOptions,
    indexOnStart = true,
  } = options ?? {}

  if (!projectRoot) throw new Error('createMcpServer: projectRoot is required')
  if (!vectorProvider) throw new Error('createMcpServer: vectorProvider is required (HTTP embeddings)')

  const argusSearch = createArgusSearch({ projectRoot, inputs, vectorProvider, streamOptions })

  let indexing = null
  let indexed = false

const ensureIndexed = async () => {
  if (indexed) return null
  if (indexing) return indexing
  indexing = (async () => {
    try {
      await argusSearch.index()
      indexed = true
      return null
    } catch (error) {
      if (typeof argusSearch?.store?.clear === 'function') {
        argusSearch.store.clear()
      }
      if (typeof argusSearch?.graphStore?.clear === 'function') {
        argusSearch.graphStore.clear()
      }
      throw error
    }
  })().finally(() => {
    indexing = null
  })
  return indexing
}

const callTool = async (name, args) => {
  if (name === 'code_search') {
    await ensureIndexed()
    const results = await argusSearch.search(String(args?.query ?? ''), { topK: clampTopK(args?.topK) })
    return {
      content: [
        {
          type: 'text',
          text: JSON.stringify(results, null, 2),
        },
      ],
    }
  }

  if (name === 'code_open') {
    const filePath = String(args?.filePath ?? '')
    const startLine = Math.max(1, Number(args?.startLine) || 1)
    const endLine = Math.max(startLine, Number(args?.endLine) || startLine + 199)
    const maxChars = Math.max(256, Math.min(200000, Number(args?.maxChars) || 20000))

    const { root, resolved: absPath } = await safeResolveWithinRoot(projectRoot, filePath)
    const content = await fs.readFile(absPath, 'utf8')
    const lines = content.split('\n')
    const slice = lines.slice(startLine - 1, endLine)
    let text = slice.join('\n')
