  if (req.method === 'GET' && req.url === '/healthz') {
    res.statusCode = 200
    res.setHeader('content-type', 'application/json')
    res.end(JSON.stringify({ ok: true }))
    return
  }

  if (req.method !== 'POST' || req.url !== mcpPath) {
    res.statusCode = 404
    res.end('not found')
    return
  }

  const raw = await readRequestBody(req)
  const request = raw ? JSON.parse(raw) : null
  id = request?.id ?? null
  const method = String(request?.method ?? '')

  if (!method) {
    toSse(res, jsonRpcError({ id, code: -32600, message: 'invalid request' }))
    return
  }

  if (method === 'initialize') {
    toSse(
      res,
      jsonRpcResult({
        id,
        result: {
          protocolVersion: '2024-11-05',
          serverInfo: { name: '@argus/argus-search', version: '0.1.0' },
          capabilities: { tools: { listChanged: false } },
        },
      }),
    )
    return
  }

  if (method === 'tools/list') {
    toSse(res, jsonRpcResult({ id, result: { tools: toolDefs() } }))
    return
  }

  if (method === 'tools/call') {
    const name = String(request?.params?.name ?? '')
    const args = request?.params?.arguments ?? {}
    const result = await callTool(name, args)
    toSse(res, jsonRpcResult({ id, result }))
    return
  }

  toSse(res, jsonRpcError({ id, code: -32601, message: `method not found: ${method}` }))
} catch (error) {

      const message = error instanceof Error ? error.message : String(error)
      toSse(res, jsonRpcError({ id, code: -32000, message }))
    }
  })

  const start = async () => {
    if (indexOnStart) await ensureIndexed()
    const listenPort = port == null ? 17890 : Number(port)
    await new Promise((resolve) => server.listen(listenPort, host, () => resolve(null)))
    const address = server.address()
    const actualPort = typeof address === 'object' && address ? address.port : port
    return {
      url: `http://${host}:${actualPort}${mcpPath}`,
      close: () => new Promise((resolve) => server.close(() => resolve(null))),
      argusSearch,
    }
  }

  return { start, server, argusSearch }
}

