export const reclaimStaleIndexJobs = async (args?: {
  staleBefore?: Date
}) => {
  const leaseSettings = resolveIndexerLeaseSettings()
  if (!leaseSettings.enabled) {
    return [] as Array<{ id: string }>
  }

  const staleBefore = args?.staleBefore ?? new Date()
  const rows = await db
    .update(indexJobs)
    .set({
      status: 'failed',
      nextAttemptAt: new Date(),
      finishedAt: null,
      lastError: 'Lease expired while processing. Requeued for retry.',
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(indexJobs.status, 'processing'),
        sql`${indexJobs.leaseExpiresAt} is not null`,
        sql`${indexJobs.leaseExpiresAt} <= ${staleBefore}`,
      ),
    )
    .returning({ id: indexJobs.id })

  return rows
}

export const refreshIndexJobLease = async (args: {
  jobId: string
  claimVersion: number
  leaseMs?: number
}) => {
  const leaseSettings = resolveIndexerLeaseSettings()
  if (!leaseSettings.enabled) {
    return false
  }
  const leaseMs = Math.max(1_000, Math.floor(args.leaseMs ?? leaseSettings.leaseMs))
  const rows = await db
    .update(indexJobs)
    .set({
      leaseExpiresAt: buildLeaseExpiry(leaseMs),
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(indexJobs.id, args.jobId),
        eq(indexJobs.status, 'processing'),
        eq(indexJobs.claimVersion, Math.max(0, Math.floor(args.claimVersion))),
      ),
    )
    .returning({ id: indexJobs.id })
  return rows.length > 0
}

export const markIndexJobSucceeded = async (args: {
  jobId: string
  result: Record<string, unknown>
  claimVersion?: number
}) => {
  const leaseSettings = resolveIndexerLeaseSettings()
  const whereFilters = [eq(indexJobs.id, args.jobId), eq(indexJobs.status, 'processing')]
  if (leaseSettings.enabled) {
    whereFilters.push(eq(indexJobs.claimVersion, Math.max(0, Math.floor(args.claimVersion ?? -1))))
  }
  const rows = await db
    .update(indexJobs)
    .set({
      status: 'succeeded',
      finishedAt: new Date(),
      lastError: null,
      result: args.result,
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: new Date(),
    })
    .where(and(...whereFilters))
    .returning({ id: indexJobs.id })

  return rows.length > 0
}

export const markIndexJobFailed = async (args: {
  job: ClaimedIndexJob
  error: unknown
}) => {
  const message =
    args.error instanceof Error
      ? args.error.message.slice(0, 500)
      : 'Unexpected indexing job processing error.'

  const maxAttempts = resolveIndexJobMaxAttempts()
  const exceededAttempts = args.job.attempts >= maxAttempts
  const leaseSettings = resolveIndexerLeaseSettings()
  const whereFilters = [eq(indexJobs.id, args.job.id), eq(indexJobs.status, 'processing')]
  if (leaseSettings.enabled) {
    whereFilters.push(eq(indexJobs.claimVersion, normalizeClaimVersion(args.job.claimVersion)))
  }
  const rows = await db
    .update(indexJobs)
    .set({
      status: exceededAttempts ? 'dead' : 'failed',
      finishedAt: exceededAttempts ? new Date() : null,
      nextAttemptAt: exceededAttempts
        ? new Date()
        : new Date(Date.now() + getRetryDelayMs(args.job.attempts)),
      lastError: message,
      leaseExpiresAt: null,
      claimedBy: null,
      updatedAt: new Date(),
    })
    .where(and(...whereFilters))
    .returning({ id: indexJobs.id, status: indexJobs.status })

  return rows[0]?.status ?? null
}

import { createRunnerScopedLogger } from '@/lib/indexing/runner/logging'
import { attachBatchSummaryMetrics } from '@/lib/indexing/runner/metrics'
import { processClaimedJobs, processClaimedRuns } from '@/lib/indexing/runner/execution'
import { captureQueueDepthAfter, runBatchScheduling } from '@/lib/indexing/runner/scheduling'
import {
  createEmptyBatchSummary,
  type IndexingWorkerBatchSummary,
  type RunIndexingWorkerBatchOptions,
} from '@/lib/indexing/runner/types'

export type { IndexingWorkerBatchSummary }

export const runIndexingWorkerBatch = async (
  batchSize = 10,
  options: RunIndexingWorkerBatchOptions = {},
) => {
  const startedAt = Date.now()
  const normalizedBatchSize = Math.max(1, Math.min(200, Math.floor(batchSize)))
  const batchLog = createRunnerScopedLogger({
    method: 'INDEXER',
    path: '/workers/indexer/batch',
    requestId: options.batchId,
  })
  batchLog.set({
    event: 'indexer.batch.processing',
    batchId: options.batchId ?? null,
    batchSize: normalizedBatchSize,
  })

  const summary: IndexingWorkerBatchSummary = createEmptyBatchSummary()
  let batchStatus = 200

  try {
    await runBatchScheduling({
      nowMs: Date.now(),
      summary,
      batchLog,
    })

    await processClaimedJobs({
      batchSize: normalizedBatchSize,
      batchId: options.batchId,
      summary,
      batchLog,
    })

    await processClaimedRuns({
      batchSize: normalizedBatchSize,
      batchId: options.batchId,
      summary,
      batchLog,
    })

    const hasFailures = summary.jobsFailed > 0 || summary.jobsDead > 0 || summary.failed > 0
    await captureQueueDepthAfter({
      summary,
      batchLog,
    })

    batchLog.set({
      outcome: hasFailures ? 'partial_failure' : 'success',
    })
    if (hasFailures) {
      batchStatus = 207
    }

    return summary
  } finally {
    const durationMs = Date.now() - startedAt
    attachBatchSummaryMetrics({
      batchLog,
      summary,
      durationMs,
    })
    batchLog.emit({
      status: batchStatus,
      durationMs,
    })
  }
}

import {
  createMergeRequestDiscussion as createMergeRequestDiscussionApi,
  getMergeRequestDetails,
} from "@/lib/gitlab/client"

export type GitLabDiscussionSide = "additions" | "deletions"

export class MergeRequestDiscussionError extends Error {
  code:
    | "comment_body_required"
    | "comment_side_invalid"
    | "comment_line_invalid"
    | "comment_path_required"
    | "missing_diff_refs"

  constructor(
    code: MergeRequestDiscussionError["code"],
    message: string,
  ) {
    super(message)
    this.code = code
  }
}

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const normalizeDiscussionPath = (value: string | null | undefined) =>
  String(value ?? "")
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "")

const resolveMergeRequestDiffRefs = (value: unknown) => {
  const root = asRecord(value)
  const diffRefs = asRecord(root?.diff_refs)
  if (!diffRefs) {
    return null
  }

  const baseSha = String(diffRefs.base_sha ?? "").trim()
  const startSha = String(diffRefs.start_sha ?? "").trim()
  const headSha = String(diffRefs.head_sha ?? "").trim()

  if (!baseSha || !startSha || !headSha) {
    return null
  }

  return {
    baseSha,
    startSha,
    headSha,
  }
}

export const createMergeRequestDiscussion = async ({

  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
  commentBody,
  commentLine,
  commentSide,
  commentFilePath,
  commentOldPath,
  commentNewPath,
}: {
  instanceUrl: string
  token: string
  projectId: string
  mergeRequestIid: string
  commentBody: string
  commentLine: number
  commentSide: GitLabDiscussionSide
  commentFilePath?: string | null
  commentOldPath?: string | null
  commentNewPath?: string | null
}) => {
  const normalizedCommentBody = commentBody.trim()
  if (!normalizedCommentBody) {
    throw new MergeRequestDiscussionError(
      "comment_body_required",
      "commentBody is required.",
    )
  }

  if (!(commentSide === "additions" || commentSide === "deletions")) {
    throw new MergeRequestDiscussionError(
      "comment_side_invalid",
      "commentSide must be one of: additions or deletions.",
    )
  }

  const normalizedLine = Math.floor(commentLine)
  if (!Number.isFinite(normalizedLine) || normalizedLine < 1) {
    throw new MergeRequestDiscussionError(
      "comment_line_invalid",
      "commentLine must be a positive integer.",
    )
  }

  const normalizedFilePath = normalizeDiscussionPath(commentFilePath)
  const normalizedOldPath = normalizeDiscussionPath(commentOldPath)
  const normalizedNewPath = normalizeDiscussionPath(commentNewPath)

  let oldPath = normalizedOldPath || normalizedFilePath || normalizedNewPath
  let newPath = normalizedNewPath || normalizedFilePath || normalizedOldPath
  if (!oldPath && newPath) {
    oldPath = newPath
  }
  if (!newPath && oldPath) {
    newPath = oldPath
  }

if (commentSide === "additions" && !newPath) {
  throw new MergeRequestDiscussionError(
    "comment_path_required",
    "A new path is required for additions-side comments.",
  )
}
if (commentSide === "deletions" && !oldPath) {
  throw new MergeRequestDiscussionError(
    "comment_path_required",
    "An old path is required for deletions-side comments.",
  )
}

const mergeRequestDetails = await getMergeRequestDetails(
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
)
const diffRefs = resolveMergeRequestDiffRefs(mergeRequestDetails)
if (!diffRefs) {
  throw new MergeRequestDiscussionError(
    "missing_diff_refs",
    "Unable to post comment to merge request diff right now. Reload and retry.",
  )
}

const position = {
  position_type: "text",
  base_sha: diffRefs.baseSha,
  start_sha: diffRefs.startSha,
  head_sha: diffRefs.headSha,
  old_path: oldPath,
  new_path: newPath,
  ...(commentSide === "deletions"
    ? { old_line: normalizedLine }
    : { new_line: normalizedLine }),
}

const discussionPayload = await createMergeRequestDiscussionApi(
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
  {
    body: normalizedCommentBody,
    position,
  },
)

const notes = Array.isArray(discussionPayload.notes)
  ? discussionPayload.notes
  : []
const firstNote = asRecord(notes[0])
const noteIdValue = firstNote?.id
const noteId =
  typeof noteIdValue === "number" || typeof noteIdValue === "string"
    ? String(noteIdValue)
    : null

  const discussionId = String(discussionPayload.id ?? "").trim() || null

  return {
    discussionId,
    noteId,
    commentPath: commentSide === "deletions" ? oldPath : newPath,
    commentLine: normalizedLine,
    commentSide,
  }
}

