import { type ReviewGateSettings, type ReviewGateStrictness } from "@/lib/review/gate"
import {
  isReviewPersona,
  isReviewPersonaMode,
  normalizeReviewPersonaMode,
  normalizeReviewPersonaTemplateOverrides,
  REVIEW_PERSONA_TEMPLATE_MAX_CHARS,
  normalizeReviewPersona,
} from "@/lib/review/persona"

const isStrictness = (value: unknown): value is ReviewGateStrictness =>
  value === "quiet" || value === "balanced" || value === "thorough"

export const parseReviewGateSettings = (
  payload: unknown,
): { settings: ReviewGateSettings | null; error: string | null } => {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return {
      settings: null,
      error: "Request body must be an object.",
    }
  }

  const record = payload as Record<string, unknown>

  if (!isStrictness(record.strictness)) {
    return {
      settings: null,
      error: "strictness must be one of: quiet, balanced, thorough.",
    }
  }

  if (typeof record.requireEvidence !== "boolean") {
    return {
      settings: null,
      error: "requireEvidence must be a boolean.",
    }
  }

  if (typeof record.securityBoost !== "boolean") {
    return {
      settings: null,
      error: "securityBoost must be a boolean.",
    }
  }
  if (record.persona !== undefined && !isReviewPersona(record.persona)) {
    return {
      settings: null,
      error: "persona must be one of: generalist, security, performance, maintainability.",
    }
  }

  if (record.personaMode !== undefined && !isReviewPersonaMode(record.personaMode)) {
    return {
      settings: null,
      error: "personaMode must be one of: disabled, single, multi.",
    }
  }

  if (
    record.personaTemplates !== undefined &&
    (typeof record.personaTemplates !== "object" ||
      record.personaTemplates === null ||
      Array.isArray(record.personaTemplates))
  ) {
    return {
      settings: null,
      error: "personaTemplates must be an object keyed by persona.",
    }
  }

  const personaTemplates = normalizeReviewPersonaTemplateOverrides(record.personaTemplates)
  const templateTooLong = Object.values(personaTemplates).some(
    (template) => template.length > REVIEW_PERSONA_TEMPLATE_MAX_CHARS,
  )
  if (templateTooLong) {
    return {
      settings: null,
      error: `persona template exceeds max length (${REVIEW_PERSONA_TEMPLATE_MAX_CHARS} chars).`,
    }
  }

  return {
    settings: {
      personaMode: normalizeReviewPersonaMode(record.personaMode),
      persona: normalizeReviewPersona(record.persona),
      personaTemplates,
      strictness: record.strictness,
      requireEvidence: record.requireEvidence,
      securityBoost: record.securityBoost,
    },
    error: null,
  }
}

