  integrationId: z.string().trim().min(1).max(200).optional(),
  sourceBranch: z.string().trim().min(1).max(300).optional(),
})

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/graph",
    event: "api.code.graph.get",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      try {
        const url = new URL(request.url)
        const resolution = await resolveSnapshotGraphScope({
          integrationId: url.searchParams.get("integrationId"),
          sourceBranch: url.searchParams.get("sourceBranch"),
        })

if (resolution.status === "pending_graph") {
  logger.set({
    graphPendingReason: resolution.reason,
  })
  return {
    status: 409,
    outcome: "graph_pending",
    response: NextResponse.json(
      { error: resolution.message },
      { status: 409 },
    ),
  }
}
if (resolution.status === "error") {
  logger.set({
    graphErrorCode: "snapshot_error",
    graphErrorDetails: { message: resolution.error },
  })
  return {
    status: 502,
    outcome: "graph_failed",
    response: NextResponse.json({ error: resolution.error }, { status: 502 }),
  }
}

const graphData = await loadSnapshotGraphData({
  snapshot: resolution.snapshot,
  artifactStore: resolution.artifactStore,
})
const summary = getSnapshotGraphSummary({ data: graphData })

logger.set({
  indexRunId: summary.indexRunId,
  nodesEmitted: summary.stats.nodesEmitted,
  edgesEmitted: summary.stats.edgesEmitted,
})

return {
  status: 200,
  outcome: "success",
  response: NextResponse.json(
    { data: summary },
    {
      headers: {
        "cache-control": CODE_GRAPH_GET_CACHE_CONTROL,
        vary: CODE_GRAPH_VARY,
      },
    },
  ),
}

      } catch {
        logger.set({ graphErrorCode: "unknown" })
        return {
          status: 500,
          outcome: "graph_failed",
          response: NextResponse.json({ error: "Failed to read code graph summary." }, { status: 500 }),
        }
      }
    },
  })
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/graph",
    event: "api.code.graph.refresh",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      try {
        const body = await requireJsonBodyOrEmpty(request, "Invalid graph refresh payload.")
        if (!body.ok) return body.result

        const parsed = postPayloadSchema.safeParse(body.value)
        if (!parsed.success) {
          return {
            status: 400,
            outcome: "invalid_request",
            response: NextResponse.json({ error: "Invalid graph refresh payload." }, { status: 400 }),
          }
        }
        const resolution = await resolveSnapshotGraphScope({
          integrationId: parsed.data.integrationId,
          sourceBranch: parsed.data.sourceBranch,
        })

if (resolution.status === "pending_graph") {
  logger.set({
    graphPendingReason: resolution.reason,
  })
  return {
    status: 409,
    outcome: "graph_pending",
    response: NextResponse.json({ error: resolution.message }, { status: 409 }),
  }
}
if (resolution.status === "error") {
  logger.set({
    graphErrorCode: "snapshot_error",
    graphErrorDetails: { message: resolution.error },
  })
  return {
    status: 502,
    outcome: "graph_failed",
    response: NextResponse.json({ error: resolution.error }, { status: 502 }),
  }
}

const graphData = await loadSnapshotGraphData({
  snapshot: resolution.snapshot,
  artifactStore: resolution.artifactStore,
})
const summary = getSnapshotGraphSummary({ data: graphData })

logger.set({
  indexRunId: summary.indexRunId,
  nodesEmitted: summary.stats.nodesEmitted,
  edgesEmitted: summary.stats.edgesEmitted,
})

return {
  status: 200,
  outcome: "success",
  response: NextResponse.json(
    { data: summary },
    {
      headers: {
        "cache-control": CODE_GRAPH_POST_CACHE_CONTROL,
        vary: CODE_GRAPH_VARY,
      },
    },
  ),
}

      } catch {
        logger.set({ graphErrorCode: "unknown" })
        return {
          status: 500,
          outcome: "graph_failed",
          response: NextResponse.json({ error: "Failed to refresh code graph summary." }, { status: 500 }),
        }
      }
    },
  })
}

