import { describe, expect, mock, test } from 'bun:test'

import {
  formatBootstrapError,
  resolveDatabaseUrl,
  resolveVectorExtension,
  runDbBootstrap,
  type BootstrapClient,
} from './db-bootstrap'

type QueryCall = {
  text: string
  values?: unknown[]
}

const withEnv = async <T>(
  overrides: Partial<NodeJS.ProcessEnv>,
  fn: () => Promise<T> | T,
): Promise<T> => {
  const previous = new Map<string, string | undefined>()
  for (const [key, value] of Object.entries(overrides)) {
    previous.set(key, process.env[key])
    if (value === undefined) {
      delete process.env[key]
    } else {
      process.env[key] = value
    }
  }

  try {
    return await fn()
  } finally {
    for (const [key, value] of previous.entries()) {
      if (value === undefined) {
        delete process.env[key]
      } else {
        process.env[key] = value
      }
    }
  }
}

const createClientHarness = (responses: Array<QueryCall | Error>) => {
  const connect = mock(async () => {})
  const end = mock(async () => {})
  const query = mock(async (text: string, values?: unknown[]) => {
    const next = responses.shift()
    if (!next) {
      throw new Error(`No mock response for query: ${text}`)
    }

    if (next instanceof Error) {
      throw next
    }

    expect(text).toBe(next.text)
    expect(values).toEqual(next.values)

    if (text.includes('select extname, extversion')) {
      return {
        rowCount: 1,
        rows: [{ extname: 'vector', extversion: '0.8.1' }],
      }
    }

    if (text.includes(`select to_regtype('vector')::text as "vectorType"`)) {
      return {
        rowCount: 1,
        rows: [{ vectorType: 'vector' }],
      }
    }

    return {
      rowCount: null,
      rows: [],
    }
  })

  const client: BootstrapClient = {
    connect,
    query,
    end,
  }

  return { client, connect, query, end }
}

