export const requireJsonBody = async (
  request: Request,
  errorMessage: string,
): Promise<RequireJsonBodyResult> => {
  let bodyText = ""
  try {
    bodyText = await request.text()
  } catch {
    return {
      ok: false,
      result: {
        status: 400,
        outcome: "invalid_request",
        response: NextResponse.json({ error: errorMessage }, { status: 400 }),
      },
    }
  }

  if (bodyText.trim().length === 0) {
    return {
      ok: false,
      result: {
        status: 400,
        outcome: "invalid_request",
        response: NextResponse.json({ error: errorMessage }, { status: 400 }),
      },
    }
  }

  try {
    return {
      ok: true,
      value: JSON.parse(bodyText) as unknown,
    }
  } catch {
    return {
      ok: false,
      result: {
        status: 400,
        outcome: "invalid_request",
        response: NextResponse.json({ error: errorMessage }, { status: 400 }),
      },
    }
  }
}

/**
 * Parse a JSON body from an incoming request, treating empty bodies as `{}`.
 *
 * Use this for routes where the body is optional (e.g. POST/DELETE with optional
 * knobs). If your endpoint requires specific fields, use `requireJsonBody` instead.
 *
 * Returns `{ ok: true, value }` on success, or `{ ok: false, result }` with
 * a ready-to-return 400 ApiLogResult when the body is present but unparseable.
 */

export const requireJsonBodyOrEmpty = async (
  request: Request,
  errorMessage: string,
): Promise<RequireJsonBodyResult> => {
  let bodyText = ""
  try {
    bodyText = await request.text()
  } catch {
    return {
      ok: false,
      result: {
        status: 400,
        outcome: "invalid_request",
        response: NextResponse.json({ error: errorMessage }, { status: 400 }),
      },
    }
  }

  if (bodyText.trim().length === 0) {
    return {
      ok: true,
      value: {},
    }
  }

  try {
    return {
      ok: true,
      value: JSON.parse(bodyText) as unknown,
    }
  } catch {
    return {
      ok: false,
      result: {
        status: 400,
        outcome: "invalid_request",
        response: NextResponse.json({ error: errorMessage }, { status: 400 }),
      },
    }
  }
}

