const getAnchorFromTarget = (target: EventTarget | null) => {
  if (!(target instanceof Element)) {
    return null
  }

  const anchor = target.closest("a[href]")
  return anchor instanceof HTMLAnchorElement ? anchor : null
}

const getPrewarmHrefFromAnchor = (anchor: HTMLAnchorElement) => {
  const href = anchor.getAttribute("href")?.trim()
  if (!href || href.startsWith("#")) {
    return null
  }

  if (anchor.hasAttribute("download")) {
    return null
  }

  const target = anchor.getAttribute("target")?.trim().toLowerCase()
  if (target && target !== "_self") {
    return null
  }

  return href
}

const shouldSkipPointerTransition = ({
  anchor,
  relatedTarget,
}: {
  anchor: HTMLAnchorElement
  relatedTarget: EventTarget | null
}) => relatedTarget instanceof Node && anchor.contains(relatedTarget)

export const useGlobalRoutePrewarmIntent = () => {
  const router = useRouter()
  const prefetchedHrefs = useMemo(() => new Set<string>(), [])

  const handlePrewarm = useCallback(
    (href: string) => {
      prefetchRouteOnce({
        href,
        prefetchedHrefs,
        prefetch: router.prefetch,
      })
    },
    [prefetchedHrefs, router],
  )

const routePrewarm = useMemo(
  () =>
    createRoutePrewarmIntentController({
      onPrewarm: handlePrewarm,
