fn create_auto_config(
  config_path: &Path,
  project_root: &Path,
  reason: &str,
  log: &impl Fn(LogLevel, String),
) -> anyhow::Result<()> {
  let metadata = fs::metadata(project_root)
    .map_err(|err| anyhow::anyhow!("project root not found: {} ({err})", project_root.display()))?;
  if !metadata.is_dir() {
    anyhow::bail!(
      "project root is not a directory: {}",
      project_root.display()
    );
  }

  log(LogLevel::Info, reason.to_string());
  log(
    LogLevel::Info,
    format!("creating default config at {}", config_path.display()),
  );

  let project_root_value = if config_path.parent() == Some(project_root) {
    ".".to_string()
  } else {
    project_root.to_string_lossy().to_string()
  };
  let payload = build_init_config(BuildInitConfigArgs {
    project_root: &project_root_value,
    paths: default_init_paths(),
    include: default_init_include(),
    exclude: default_init_exclude(),
    vector_base_url: DEFAULT_VECTOR_BASE_URL,
    vector_model: DEFAULT_VECTOR_MODEL,
    incremental: true,
    include_checkpoint_defaults: false,
  });

  if let Some(parent) = config_path.parent() {
    fs::create_dir_all(parent)?;
  }
  fs::write(config_path, serde_json::to_string_pretty(&payload)?)?;
  fs::create_dir_all(project_root.join(".argus-search"))?;
  ensure_gitignore(project_root)?;

  log(
    LogLevel::Info,
    format!(
      "created config (projectRoot={project_root_value}, vector.model={DEFAULT_VECTOR_MODEL})"
    ),
  );
  Ok(())
}

fn resolve_or_bootstrap_config(
  args: &Args,
  log: &impl Fn(LogLevel, String),
) -> anyhow::Result<(Option<PathBuf>, JsonConfig)> {
  let mut config_path = resolve_config_path(args.config.clone())?;
  let has_config = config_path.as_ref().is_some_and(|path| path.exists());
  if !has_config {
    let bootstrap_root =
      resolve_bootstrap_project_root(args.project_root.as_deref(), config_path.as_deref())?;
    let next_config_path = config_path
      .clone()
      .unwrap_or_else(|| bootstrap_root.join(DEFAULT_CONFIG_BASENAME));
    let reason = if args.config.is_some() {
      format!(
        "config not found at {}; bootstrapping with defaults",
        next_config_path.display()
      )
    } else {
      format!(
        "no config found via find-up from {}; bootstrapping with defaults",
        std::env::current_dir()?.display()
      )
    };
    create_auto_config(&next_config_path, &bootstrap_root, &reason, log)?;
    config_path = Some(next_config_path);
  }

  let config = if let Some(path) = &config_path {
    serde_json::from_str(&fs::read_to_string(path)?)?
  } else {
    JsonConfig::default()
  };
  Ok((config_path, config))
}

fn default_project_root(config_path: Option<&Path>) -> anyhow::Result<PathBuf> {
  if let Some(path) = config_path {
    if let Some(parent) = path.parent() {
      return Ok(parent.to_path_buf());
    }
  }
  std::env::current_dir().map_err(Into::into)
}

fn resolve_project_root(
  args_project_root: Option<PathBuf>,
  config_project_root: Option<&str>,
  config_path: Option<&Path>,
) -> anyhow::Result<PathBuf> {
  if let Some(project_root) = args_project_root {
    return absolute_from_cwd(&project_root);
  }
  if let Some(root) = config_project_root {
    let root_path = PathBuf::from(root);
    if root_path.is_absolute() {
      return Ok(root_path);
    }
    if let Some(path) = config_path {
      if let Some(parent) = path.parent() {
        return Ok(parent.join(root_path));
      }
    }
    return absolute_from_cwd(&root_path);
  }
  default_project_root(config_path)
}

fn apply_vector_defaults(config: &mut JsonConfig) {
  if config.vector.is_none() {
    config.vector = Some(JsonVector::default());
  }
  let vector = config.vector.as_mut().expect("vector initialized");
  if vector.provider.is_none() {
    vector.provider = Some(JsonHttpVectorProvider {
      kind: Some("http".to_string()),
      base_url: Some(DEFAULT_VECTOR_BASE_URL.to_string()),
      model: Some(DEFAULT_VECTOR_MODEL.to_string()),
      api_key: None,
      dimension: None,
      timeout_ms: None,
    });
    return;
  }
  let provider = vector.provider.as_mut().expect("provider initialized");
  if provider.kind.is_none() {
    provider.kind = Some("http".to_string());
  }
  if provider.base_url.is_none() {
    provider.base_url = Some(DEFAULT_VECTOR_BASE_URL.to_string());
  }
  if provider.model.is_none() {
    provider.model = Some(DEFAULT_VECTOR_MODEL.to_string());
  }
}

fn build_index_options(

  project_root: &Path,
  config: &JsonConfig,
) -> anyhow::Result<(IndexOptions, Arc<dyn EmbeddingsProvider>)> {
  let mut index_options = IndexOptions::new(project_root.to_path_buf());

  if let Some(inputs) = &config.inputs {
    index_options.inputs = ParseInputs {
      paths: inputs
        .paths
        .clone()
        .unwrap_or_default()
        .into_iter()
        .map(|p| {
          let path = PathBuf::from(p);
          if path.is_relative() {
            project_root.join(path)
          } else {
            path
          }
        })
        .collect(),
      include: inputs.include.clone().unwrap_or_default(),
      exclude: inputs.exclude.clone().unwrap_or_default(),
      respect_gitignore: inputs.respect_gitignore.unwrap_or(true),
    };
  }

  let phases = config.phases.unwrap_or_default();
  let mut out = IndexPhases::default();
  if let Some(v) = phases.parse {
    out.parse = v;
  }
  if let Some(v) = phases.graph {
    out.graph = v;
  }
  if let Some(v) = phases.vector {
    out.vector = v;
  }
  if let Some(v) = phases.scip {
    out.scip = v;
  }
  if let Some(v) = phases.index_pack {
    out.index_pack = v;
  }

  // For MCP, we need vectors and graph by default.
  out.parse = true;
  if !out.graph {
    out.graph = true;
  }
  if !out.vector {
    out.vector = true;
  }
  out.index_pack = false;
  index_options.phases = out;

  let default_vector = JsonVector::default();
  let vector = config.vector.as_ref().unwrap_or(&default_vector);

  let provider = vector
    .provider
    .as_ref()
    .ok_or_else(|| anyhow::anyhow!("vector.provider is required after applying defaults"))?;
  if let Some(kind) = &provider.kind {
    if kind != "http" {
      anyhow::bail!("unsupported vector provider kind: {kind}");
    }
  }

  let api_key = provider
    .api_key
    .clone()
    .filter(|value| !value.trim().is_empty())
    .or_else(|| std::env::var("OPENAI_API_KEY").ok());

  let base_url = provider
    .base_url
    .clone()
    .unwrap_or_else(|| DEFAULT_VECTOR_BASE_URL.to_string());
  let model = provider
    .model
    .clone()
    .unwrap_or_else(|| DEFAULT_VECTOR_MODEL.to_string());

  let mut http = HttpEmbeddingConfig::new(base_url, api_key, model);
  http.dimension = provider.dimension;
  if let Some(timeout) = provider.timeout_ms {
    http.timeout = Some(std::time::Duration::from_millis(timeout));
  }
  let http_provider = HttpEmbeddingsProvider::new(http)?;
  let embeddings_provider: Arc<dyn EmbeddingsProvider> = Arc::new(http_provider);

  if let Some(batch_size) = vector.batch_size {
    index_options.vector.batch_size = batch_size;
  }
  if let Some(concurrency) = vector.concurrency {
    index_options.vector.concurrency = concurrency;
  }

  index_options.vector_provider = Some(Arc::clone(&embeddings_provider));
  Ok((index_options, embeddings_provider))
}

fn run_index_with_retry(

  config: &RefCell<JsonConfig>,
  runtime: &RefCell<(IndexOptions, Arc<dyn EmbeddingsProvider>)>,
  project_root: &Path,
  store_path: &Path,
  clear: bool,
  context: &str,
  log: &impl Fn(LogLevel, String),
) -> anyhow::Result<()> {
  let mut should_clear = clear;
  let mut retried_without_dimension = false;

loop {
  let index_options = {
    let borrowed = runtime.borrow();
    borrowed.0.clone()
  };
  match index_to_kitedb(index_options, store_path, should_clear) {
    Ok(_) => return Ok(()),
    Err(err) => {
      let message = err.to_string();
      let current_dimension = {
        let cfg = config.borrow();
        cfg
          .vector
          .as_ref()
          .and_then(|v| v.provider.as_ref())
          .and_then(|p| p.dimension)
      };
      if !retried_without_dimension
        && current_dimension.is_some()
        && message.contains("embedding dimension mismatch")
      {
        {
          let mut cfg = config.borrow_mut();
          if let Some(vector) = cfg.vector.as_mut() {
            if let Some(provider) = vector.provider.as_mut() {
              provider.dimension = None;
            }
          }
        }
        log(
          LogLevel::Warn,
          format!(
            "{context}: embedding dimension mismatch while dimension was set to {}; retrying once with vector.provider.dimension unset",
            current_dimension
              .map(|v| v.to_string())
              .unwrap_or_else(|| "<unknown>".to_string())
          ),
        );
        let rebuilt = {
          let cfg = config.borrow();
          build_index_options(project_root, &cfg)?
        };
        *runtime.borrow_mut() = rebuilt;
        retried_without_dimension = true;
        should_clear = true;
        continue;
      }
      return Err(err);
    }
  }
}

}

