import { parseBoolean } from "@argus/shared-runtime/config-env"

import { db } from "@/lib/db"
import { getSessionAccess } from "@/lib/session"

export const ADMIN_ACCESS_DENIED_MESSAGE = "Admin permissions are required."

type AdminAccessConfigInput = {
  enabled?: string
  allowedEmails?: string
}

export type AdminAccessConfig = {
  enabled: boolean
  allowedEmails: ReadonlySet<string>
  allowedDomains: ReadonlySet<string>
}

const normalizeEmail = (value: string) => value.trim().toLowerCase()

const parseAllowedEmailTokens = (value: string | undefined) =>
  (value ?? "")
    .split(/[,\s]+/)
    .map((token) => token.trim().toLowerCase())
    .filter(Boolean)

export const buildAdminAccessConfig = ({
  enabled,
  allowedEmails,
}: AdminAccessConfigInput): AdminAccessConfig => {
  const isEnabled = parseBoolean(enabled, "ADMIN_ACCESS_ALLOWLIST_ENABLED") ?? false
  const exactEmails = new Set<string>()
  const allowedDomains = new Set<string>()

  for (const token of parseAllowedEmailTokens(allowedEmails)) {
    if (token.startsWith("@") && token.length > 1) {
      allowedDomains.add(token.slice(1))
      continue
    }
    exactEmails.add(token)
  }

  if (isEnabled && exactEmails.size === 0 && allowedDomains.size === 0) {
    throw new Error(
      "ADMIN_ACCESS_ALLOWED_EMAILS must include at least one email or @domain when ADMIN_ACCESS_ALLOWLIST_ENABLED is true.",
    )
  }

  return {
    enabled: isEnabled,
    allowedEmails: exactEmails,
    allowedDomains,
  }
}

export const isAdminEmailAllowlistedForConfig = (
  config: AdminAccessConfig,
  email: string | null | undefined,
) => {
  if (!config.enabled) {
    return false
  }

  if (!email) {
    return false
  }

  const normalizedEmail = normalizeEmail(email)
  const domain = normalizedEmail.split("@")[1]

  if (config.allowedEmails.has(normalizedEmail)) {
    return true
  }

  return Boolean(domain && config.allowedDomains.has(domain))
}

const adminAccessConfig = buildAdminAccessConfig({
  enabled: process.env.ADMIN_ACCESS_ALLOWLIST_ENABLED,
  allowedEmails: process.env.ADMIN_ACCESS_ALLOWED_EMAILS,
})

export const isAdminAccessAllowlistEnabled = adminAccessConfig.enabled

export const isAdminEmailAllowlisted = (email: string | null | undefined) =>
  isAdminEmailAllowlistedForConfig(adminAccessConfig, email)

export type UserAdminState = {
  isAdmin: boolean
  isAdminPersisted: boolean
  isAdminManagedByAllowlist: boolean
}

export const getUserAdminState = async (userId: string): Promise<UserAdminState> => {
  const row = await db.query.user.findFirst({
    where: (table, { eq }) => eq(table.id, userId),
    columns: {
      id: true,
      email: true,
      isAdmin: true,
    },
  })

  const isAdminPersisted = row?.isAdmin === true
  const isAdminManagedByAllowlist = isAdminEmailAllowlisted(row?.email ?? null)

  return {
    isAdmin: isAdminPersisted || isAdminManagedByAllowlist,
    isAdminPersisted,
    isAdminManagedByAllowlist,
  }
}

export const isUserAdmin = async (userId: string) => {
  const state = await getUserAdminState(userId)
  return state.isAdmin
}

export const getSessionAdminAccess = async () => {
  const access = await getSessionAccess()
  const sessionUserId = access.session?.user?.id

  if (!sessionUserId) {
    return {
      ...access,
      isAdmin: false,
      isAdminPersisted: false,
      isAdminManagedByAllowlist: false,
    }
  }

  const adminState = await getUserAdminState(sessionUserId)
  return {
    ...access,
    ...adminState,
  }
}

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

#[derive(Debug, Clone, Default)]
pub struct CancelToken {
  cancelled: Arc<AtomicBool>,
}

impl CancelToken {
  pub fn new() -> Self {
    Self::default()
  }

  pub fn cancel(&self) {
    self.cancelled.store(true, Ordering::Release);
  }

  pub fn is_cancelled(&self) -> bool {
    self.cancelled.load(Ordering::Acquire)
  }

  pub fn check(&self) -> Result<(), Cancelled> {
    if self.is_cancelled() {
      Err(Cancelled)
    } else {
      Ok(())
    }
  }
}

#[derive(Debug, Clone, Copy)]
pub struct Cancelled;

impl std::fmt::Display for Cancelled {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    write!(f, "cancelled")
  }
}

impl std::error::Error for Cancelled {}

import { NextResponse } from "next/server"

import {
  AiClientSettingsValidationError,
  assertAiClientSettings,
  type AiClientSettings,
} from "@/lib/ai/client-settings"
import {
  getAiClientSettingsForUser,
  upsertAiClientSettingsForUser,
} from "@/lib/ai/server-settings"
import { requireJsonBody } from "@/lib/http/request-json"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/ai/settings",
    event: "api.ai.settings.get",
    handler: async () => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const settings = await getAiClientSettingsForUser(userId)
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: settings }),
      }
    },
  })
}

export async function PUT(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/ai/settings",
    event: "api.ai.settings.put",
    handler: async () => {
      const [userId, body] = await Promise.all([
        getSessionUserId(),
        requireJsonBody(request, "Invalid AI settings payload."),
      ])

      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      if (!body.ok) return body.result

      const root = asRecord(body.value)
      if (!root) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid AI settings payload." }, { status: 400 }),
        }
      }

      let validated: AiClientSettings
      try {
        validated = assertAiClientSettings(root)
      } catch (error) {
        if (error instanceof AiClientSettingsValidationError) {
          return {
            status: 400,
            outcome: "invalid_request",
            response: NextResponse.json({ error: error.message }, { status: 400 }),
          }
        }
        throw error
      }

      const saved = await upsertAiClientSettingsForUser({
        userId,
        settings: validated,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: saved }),
      }
    },
  })
}

