use std::path::{Path, PathBuf};

use napi::bindgen_prelude::Object;
use napi::{Error, Result};

use crate::path_policy::{
  parse_safe_relative_path, resolve_path_within_root, resolve_store_path_within_root,
};

pub(super) fn required_string(obj: &Object<'_>, field: &str) -> Result<String> {
  obj
    .get::<String>(field)?
    .ok_or_else(|| Error::from_reason(format!("missing required field: {field}")))
}

pub(super) fn resolve_project_path(project_root: &Path, candidate: PathBuf) -> PathBuf {
  if candidate.is_relative() {
    project_root.join(candidate)
  } else {
    candidate
  }
}

pub(super) fn resolve_store_path(project_root: &Path, candidate: PathBuf) -> Result<PathBuf> {
  resolve_store_path_within_root(project_root, candidate, "store.path").map_err(Error::from_reason)
}

pub(super) fn read_text_file(path: PathBuf) -> Result<String> {
  std::fs::read_to_string(&path)
    .map_err(|err| Error::from_reason(format!("failed to read {}: {err}", path.display())))
}

pub(super) fn safe_resolve_within_root(root_dir: &Path, unsafe_path: &Path) -> Option<PathBuf> {
  resolve_path_within_root(root_dir, unsafe_path, "path").ok()
}

pub(super) fn safe_relative_path(file_path: &str) -> Option<PathBuf> {
  parse_safe_relative_path(file_path).ok()
}

