import { CACHE_MAX_ENTRIES } from "./constants"
import {
  type DiffContext,
  type DiffManifestCacheEntry,
} from "./types"

const DIFF_MANIFEST_CACHE = new Map<string, DiffManifestCacheEntry>()

export const buildCacheKey = (context: DiffContext) =>
  `${context.userId}::${context.instanceUrl}::${context.projectId}::${context.mergeRequestIid}`

export const trimCache = () => {
  const now = Date.now()
  for (const [key, value] of DIFF_MANIFEST_CACHE.entries()) {
    if (value.expiresAt <= now) {
      DIFF_MANIFEST_CACHE.delete(key)
    }
  }

  while (DIFF_MANIFEST_CACHE.size > CACHE_MAX_ENTRIES) {
    const oldest = DIFF_MANIFEST_CACHE.keys().next().value
    if (!oldest) {
      break
    }
    DIFF_MANIFEST_CACHE.delete(oldest)
  }
}

export const getFreshCacheEntry = (cacheKey: string) => {
  const entry = DIFF_MANIFEST_CACHE.get(cacheKey)
  if (!entry) {
    return null
  }
  if (entry.expiresAt <= Date.now()) {
    DIFF_MANIFEST_CACHE.delete(cacheKey)
    return null
  }
  return entry
}

export const setCacheEntry = (cacheKey: string, entry: DiffManifestCacheEntry) => {
  DIFF_MANIFEST_CACHE.set(cacheKey, entry)
}

