const ensureIndexed = async ({ clear = false } = {}) => {
  if (indexed && !clear) return
  if (indexing) return indexing
  indexing = (async () => {
    await binding.indexToKiteDb(
      {
        ...indexOptions,
        projectRoot,
        vector: { ...indexOptions?.vector, provider: vectorProvider },
      },
      { path: storePath, clear: Boolean(clear) },
    )
    indexed = true
  })().finally(() => {
    indexing = null
  })
  return indexing
}

const callTool = async (name, args) => {
  if (name === 'code_search') {
    await ensureIndexed()
    const query = String(args?.query ?? '')
    const topK = clampTopK(args?.topK)
    const hits = await binding.searchKiteDb({
      projectRoot,
      store: { path: storePath },
      query,
      topK,
      vectorProvider,
    })
    return { content: [{ type: 'text', text: JSON.stringify(hits, null, 2) }] }
  }

  if (name === 'code_open') {
    const filePath = String(args?.filePath ?? '')
    const startLine = Math.max(1, Number(args?.startLine) || 1)
    const endLine = Math.max(startLine, Number(args?.endLine) || startLine + 199)
    const maxChars = Math.max(256, Math.min(200000, Number(args?.maxChars) || 20000))

    const { root, resolved: absPath } = await safeResolveWithinRoot(projectRoot, filePath)
    const content = await fs.readFile(absPath, 'utf8')
    const lines = content.split('\n')
    const slice = lines.slice(startLine - 1, endLine)
    let text = slice.join('\n')
    if (text.length > maxChars) text = text.slice(0, maxChars)

    return {
      content: [
        {
          type: 'text',
          text: `file: ${path.relative(root, absPath)}\nlines: ${startLine}-${endLine}\n\n${text}`,
        },
      ],
    }
  }

  if (name === 'code_reindex') {
    await ensureIndexed({ clear: true })
    return { content: [{ type: 'text', text: 'reindexed' }] }
  }

  throw new Error(`unknown tool: ${name}`)
}

const write = (message) => {
  // MCP stdio transport is newline-delimited JSON. Keep it single-line.
  process.stdout.write(`${JSON.stringify(message)}\n`)
}

const log = (msg) => {
  if (quiet) return
  process.stderr.write(`${msg}\n`)
}

const requestStop = (code = 0) => {
  exitCode = Number(code) || 0
  if (rl) {
    rl.close()
    return
  }
  process.exitCode = exitCode
}

const onRequest = async (request) => {
  const id = request?.id ?? null
  const method = String(request?.method ?? '')

  if (!method) return write(jsonRpcError(id, -32600, 'invalid request'))

  if (method === 'initialize') {
    return write(
      jsonRpcResult(id, {
        protocolVersion: request?.params?.protocolVersion ?? '2025-11-25',
        serverInfo: { name: '@argus/argus-search', version: '0.1.0' },
        capabilities: { tools: { listChanged: false } },
      }),
    )
  }

  if (method === 'tools/list') {
    return write(jsonRpcResult(id, { tools: toolDefs() }))
  }

  if (method === 'tools/call') {
    const name = String(request?.params?.name ?? '')
    const args = request?.params?.arguments ?? {}
    try {
      const result = await callTool(name, args)
      return write(jsonRpcResult(id, result))
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      return write(jsonRpcError(id, -32000, message))
    }
  }

  if (method === 'shutdown') {
    shuttingDown = true
    return write(jsonRpcResult(id, null))
  }

  if (method === 'exit') {
    requestStop(shuttingDown ? 0 : 1)
    return
  }

  write(jsonRpcError(id, -32601, `method not found: ${method}`))
}

  const start = async () => {
    if (indexOnStart) {
      log(`indexing to ${storePath}...`)
      await ensureIndexed()
      log('ready')
    } else {
      log('ready (indexOnStart=false)')
    }

    rl = readline.createInterface({ input: process.stdin, crlfDelay: Infinity })
    const onSignal = () => requestStop(0)
    process.once('SIGINT', onSignal)
    process.once('SIGTERM', onSignal)
    rl.on('line', async (line) => {
      const trimmed = String(line ?? '').trim()
      if (!trimmed) return
      let request = null
      try {
        request = JSON.parse(trimmed)
      } catch {
        write(jsonRpcError(null, -32700, 'parse error'))
        return
      }
      try {
        await onRequest(request)
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error)
        write(jsonRpcError(request?.id ?? null, -32000, message))
      }
    })

    rl.on('close', () => {
      process.off('SIGINT', onSignal)
      process.off('SIGTERM', onSignal)
      process.exit(exitCode)
    })
  }

  return { start }
}

module.exports = { createStdioMcpServer }

