import { Buffer } from "node:buffer"
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto"

type EncryptedToken = {
  ciphertext: string
  iv: string
  authTag: string
}

const BASE64_RE = /^[A-Za-z0-9+/]+={0,2}$/

const isLikelyBase64 = (value: string) => /^[A-Za-z0-9+/=_-]+$/.test(value)

const parseEncryptionKey = (value: string) => {
  const trimmed = value.trim()
  if (!trimmed) {
    throw new Error("GITLAB_TOKEN_ENCRYPTION_KEY is required.")
  }

  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    return Buffer.from(trimmed, "hex")
  }

  if (isLikelyBase64(trimmed)) {
    const normalized = trimmed.replace(/-/g, "+").replace(/_/g, "/")
    const decoded = Buffer.from(normalized, "base64")
    if (decoded.length === 32) {
      return decoded
    }
  }

  const utf8 = Buffer.from(trimmed, "utf8")
  if (utf8.length === 32) {
    return utf8
  }

  throw new Error(
    "GITLAB_TOKEN_ENCRYPTION_KEY must decode to exactly 32 bytes (raw/base64/base64url/hex).",
  )
}

const fromBase64 = (value: string, fieldName: string) => {
  const trimmed = value.trim()
  if (!trimmed || trimmed.length % 4 !== 0 || !BASE64_RE.test(trimmed)) {
    throw new Error(`Invalid ${fieldName} encoding.`)
  }
  return Buffer.from(trimmed, "base64")
}

const toBase64 = (value: Buffer) => value.toString("base64")

// Jira credentials intentionally use the shared token encryption key until a dedicated app key exists.
const jiraTokenEncryptionKey = parseEncryptionKey(process.env.GITLAB_TOKEN_ENCRYPTION_KEY ?? "")

export const encryptJiraToken = (token: string): EncryptedToken => {
  const iv = randomBytes(12)
  const cipher = createCipheriv("aes-256-gcm", jiraTokenEncryptionKey, iv)
  const ciphertext = Buffer.concat([cipher.update(token, "utf8"), cipher.final()])
  const authTag = cipher.getAuthTag()

  return {
    ciphertext: toBase64(ciphertext),
    iv: toBase64(iv),
    authTag: toBase64(authTag),
  }
}

export const decryptJiraToken = (encrypted: EncryptedToken) => {
  const iv = fromBase64(encrypted.iv, "token_iv")
  const ciphertext = fromBase64(encrypted.ciphertext, "token_ciphertext")
  const authTag = fromBase64(encrypted.authTag, "token_auth_tag")

  try {
    const decipher = createDecipheriv("aes-256-gcm", jiraTokenEncryptionKey, iv)
    decipher.setAuthTag(authTag)
    const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()])
    return plaintext.toString("utf8")
  } catch {
    throw new Error("Unable to decrypt Jira token.")
  }
}

