use std::collections::HashSet;

use super::types::{ScipDocument, ScipManifest, TombstoneResult};

pub fn compute_tombstones(
  previous_manifest: &ScipManifest,
  new_manifest: &ScipManifest,
  changed_files: &[String],
) -> TombstoneResult {
  let mut symbols_to_remove = HashSet::new();
  let mut edges_to_remove = HashSet::new();
  let mut overflow_edge_ids = HashSet::new();

for file in changed_files {
  let prev = previous_manifest.documents.get(file);
  let curr = new_manifest.documents.get(file);
  let Some(prev) = prev else {
    continue;
  };

  let prev_defined = defined_symbols(prev);
  let curr_defined = curr
    .map(defined_symbols)
    .map_or(&[] as &[String], |value| value);
  let curr_set: HashSet<&str> = curr_defined.iter().map(|value| value.as_str()).collect();

  for symbol in prev_defined {
    if !curr_set.contains(symbol.as_str()) {
      symbols_to_remove.insert(symbol.clone());
      edges_to_remove.insert(format!("edge:*->{symbol}:*"));
      edges_to_remove.insert(format!("edge:{symbol}->*:*"));
    }
  }

  let prev_edges: HashSet<&str> = prev.edge_keys.iter().map(|value| value.as_str()).collect();
  let curr_edges: HashSet<&str> = curr
    .map(|doc| doc.edge_keys.iter().map(|value| value.as_str()).collect())
    .unwrap_or_default();

  for edge_key in prev_edges {
    if !curr_edges.contains(edge_key) {
      edges_to_remove.insert(edge_key.to_string());
    }
  }

  let prev_overflow: HashSet<&str> = prev
    .overflow_edge_ids
    .iter()
    .map(|value| value.as_str())
    .collect();
  let curr_overflow: HashSet<&str> = curr
    .map(|doc| {
      doc
        .overflow_edge_ids
        .iter()
        .map(|value| value.as_str())
        .collect()
    })
    .unwrap_or_default();
  for edge_id in prev_overflow {
    if !curr_overflow.contains(edge_id) {
      overflow_edge_ids.insert(edge_id.to_string());
    }
  }
}

  TombstoneResult {
    symbols_to_remove,
    edges_to_remove,
    overflow_edge_ids: overflow_edge_ids.into_iter().collect(),
  }
}

pub fn compute_tombstones_for_deleted_files(
  previous_manifest: &ScipManifest,
  deleted_files: &[String],
) -> TombstoneResult {
  let mut symbols_to_remove = HashSet::new();
  let mut edges_to_remove = HashSet::new();
  let mut overflow_edge_ids = HashSet::new();

  for file in deleted_files {
    let Some(doc) = previous_manifest.documents.get(file) else {
      continue;
    };

    let defined_symbols = defined_symbols(doc);
    for symbol in defined_symbols {
      symbols_to_remove.insert(symbol.clone());
      edges_to_remove.insert(format!("edge:*->{symbol}:*"));
      edges_to_remove.insert(format!("edge:{symbol}->*:*"));
    }

    for edge_key in &doc.edge_keys {
      edges_to_remove.insert(edge_key.clone());
    }

    for edge_id in &doc.overflow_edge_ids {
      overflow_edge_ids.insert(edge_id.clone());
    }
  }

  TombstoneResult {
    symbols_to_remove,
    edges_to_remove,
    overflow_edge_ids: overflow_edge_ids.into_iter().collect(),
  }
}

pub fn find_dependent_symbols(
  manifest: &ScipManifest,
  removed_symbols: &HashSet<String>,
) -> HashSet<String> {
  let mut dependents = HashSet::new();

  for symbol in removed_symbols {
    let referencing_files = manifest
      .symbol_references
      .get(symbol)
      .cloned()
      .unwrap_or_default();

    for file in referencing_files {
      if let Some(file_doc) = manifest.documents.get(&file) {
        for file_symbol in &file_doc.symbols {
          if !removed_symbols.contains(file_symbol) {
            dependents.insert(file_symbol.clone());
          }
        }
      }
    }
  }

  dependents
}

pub fn merge_tombstones(results: &[TombstoneResult]) -> TombstoneResult {
  let mut symbols_to_remove = HashSet::new();
  let mut edges_to_remove = HashSet::new();
  let mut overflow_edge_ids = HashSet::new();

  for result in results {
    symbols_to_remove.extend(result.symbols_to_remove.iter().cloned());
    edges_to_remove.extend(result.edges_to_remove.iter().cloned());
    overflow_edge_ids.extend(result.overflow_edge_ids.iter().cloned());
  }

  TombstoneResult {
    symbols_to_remove,
    edges_to_remove,
    overflow_edge_ids: overflow_edge_ids.into_iter().collect(),
  }
}

pub fn has_tombstone_work(tombstones: &TombstoneResult) -> bool {
  !tombstones.symbols_to_remove.is_empty()
    || !tombstones.edges_to_remove.is_empty()
    || !tombstones.overflow_edge_ids.is_empty()
}

fn defined_symbols(doc: &ScipDocument) -> &Vec<String> {
  if doc.defined_symbols.is_empty() {
    &doc.symbols
  } else {
    &doc.defined_symbols
  }
}

