use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use sha2::{Digest, Sha256};
use time::format_description::well_known::Rfc3339;
use time::OffsetDateTime;

use super::types::{ManifestDiff, ScipDocument, ScipManifest, MANIFEST_VERSION};

const MANIFEST_FILENAME: &str = "scip-manifest.json";

pub fn manifest_file_path(data_dir: &Path) -> PathBuf {
  data_dir.join("scip").join(MANIFEST_FILENAME)
}

pub fn load_manifest(data_dir: &Path) -> Option<ScipManifest> {
  let manifest_path = manifest_file_path(data_dir);
  if !manifest_path.exists() {
    return None;
  }
  let content = fs::read_to_string(manifest_path).ok()?;
  let manifest: ScipManifest = serde_json::from_str(&content).ok()?;
  if manifest.version != MANIFEST_VERSION {
    return None;
  }
  Some(manifest)
}

pub fn save_manifest(data_dir: &Path, manifest: &ScipManifest) -> std::io::Result<()> {
  let manifest_path = manifest_file_path(data_dir);
  if let Some(parent) = manifest_path.parent() {
    fs::create_dir_all(parent)?;
  }
  let payload = serde_json::to_string_pretty(manifest)
    .map_err(|err| std::io::Error::other(format!("failed to serialize scip manifest: {err}")))?;
  fs::write(manifest_path, payload)
}

pub fn create_empty_manifest(commit_hash: &str) -> ScipManifest {
  ScipManifest {
    version: MANIFEST_VERSION,
    last_indexed: now_rfc3339(),
    commit_hash: commit_hash.to_string(),
    documents: HashMap::new(),
    symbol_references: HashMap::new(),
  }
}

pub fn compute_file_hash(file_path: &Path) -> String {
  let Ok(content) = fs::read_to_string(file_path) else {
    return String::new();
  };
  let mut hasher = Sha256::new();
  hasher.update(content.as_bytes());
  let digest = hasher.finalize();
  let hash = format!("{digest:x}");
  hash.chars().take(16).collect()
}

pub fn compute_file_hashes(file_paths: &[PathBuf]) -> HashMap<PathBuf, String> {
  let mut results = HashMap::new();
  for file_path in file_paths {
    let hash = compute_file_hash(file_path);
    results.insert(file_path.clone(), hash);
  }
  results
}

pub fn compute_manifest_diff(
  previous_manifest: Option<&ScipManifest>,
  current_files: &[String],
  project_root: &Path,
) -> ManifestDiff {
  let Some(previous_manifest) = previous_manifest else {
    return ManifestDiff {
      added: current_files.to_vec(),
      modified: Vec::new(),
      deleted: Vec::new(),
      requires_full_reindex: true,
    };
  };

  let full_paths = current_files
    .iter()
    .map(|file| project_root.join(file))
    .collect::<Vec<_>>();
  let current_hashes = compute_file_hashes(&full_paths);

  let mut added = Vec::new();
  let mut modified = Vec::new();

  for file in current_files {
    let full_path = project_root.join(file);
    let current_hash = current_hashes.get(&full_path).cloned().unwrap_or_default();
    let previous_doc = previous_manifest.documents.get(file);
    match previous_doc {
      None => added.push(file.clone()),
      Some(doc) if doc.content_hash != current_hash => modified.push(file.clone()),
      _ => {}
    }
  }

  let current_set: HashSet<&str> = current_files.iter().map(|value| value.as_str()).collect();
  let mut deleted = Vec::new();
  for file in previous_manifest.documents.keys() {
    if !current_set.contains(file.as_str()) {
      deleted.push(file.clone());
    }
  }

  ManifestDiff {
    added,
    modified,
    deleted,
    requires_full_reindex: false,
  }
}

pub fn update_manifest(manifest: &mut ScipManifest, file_path: &str, data: ScipDocumentInput<'_>) {
  let doc = ScipDocument {
    content_hash: data.content_hash.to_string(),
    symbols: data
      .symbols
      .iter()
      .map(|value| (*value).to_string())
      .collect(),
    defined_symbols: data
      .defined_symbols
      .unwrap_or(data.symbols)
      .iter()
      .map(|value| (*value).to_string())
      .collect(),
    edge_keys: data
      .edge_keys
      .unwrap_or(&[])
      .iter()
      .map(|value| (*value).to_string())
      .collect(),
    overflow_edge_ids: data
      .overflow_edge_ids
      .unwrap_or(&[])
      .iter()
      .map(|value| (*value).to_string())
      .collect(),
    occurrence_count: data.occurrence_count,
    has_overflow: data.has_overflow,
  };

  manifest.documents.insert(file_path.to_string(), doc);

  for symbol in data.symbols {
    let entry = manifest
      .symbol_references
      .entry(symbol.to_string())
      .or_default();
    if !entry.contains(&file_path.to_string()) {
      entry.push(file_path.to_string());
    }
  }
}

pub fn remove_from_manifest(manifest: &mut ScipManifest, file_path: &str) {
  let Some(doc) = manifest.documents.remove(file_path) else {
    return;
  };

  for symbol in doc.symbols {
    if let Some(refs) = manifest.symbol_references.get_mut(&symbol) {
      refs.retain(|entry| entry != file_path);
      if refs.is_empty() {
        manifest.symbol_references.remove(&symbol);
      }
    }
  }
}

pub fn references_for_symbol(manifest: &ScipManifest, symbol: &str) -> Vec<String> {
  manifest
    .symbol_references
    .get(symbol)
    .cloned()
    .unwrap_or_default()
}

pub fn symbols_in_file(manifest: &ScipManifest, file_path: &str) -> Vec<String> {
  manifest
    .documents
    .get(file_path)
    .map(|doc| doc.symbols.clone())
    .unwrap_or_default()
}

pub fn head_commit_hash(project_root: &Path) -> String {
  let output = Command::new("git")
    .args(["rev-parse", "HEAD"])
    .current_dir(project_root)
    .output();

  match output {
    Ok(output) if output.status.success() => {
      String::from_utf8_lossy(&output.stdout).trim().to_string()
    }
    _ => String::new(),
  }
}

pub fn changed_files_between(
  project_root: &Path,
  from_commit: &str,
  to_commit: &str,
) -> Vec<String> {
  let output = Command::new("git")
    .args(["diff", "--name-only", from_commit, to_commit])
    .current_dir(project_root)
    .output();

  match output {
    Ok(output) if output.status.success() => String::from_utf8_lossy(&output.stdout)
      .lines()
      .filter(|line| !line.is_empty())
      .map(|line| line.to_string())
      .collect(),
    _ => Vec::new(),
  }
}

fn now_rfc3339() -> String {
  OffsetDateTime::now_utc()
    .format(&Rfc3339)
    .unwrap_or_else(|_| "1970-01-01T00:00:00Z".to_string())
}

pub struct ScipDocumentInput<'doc> {
  pub content_hash: &'doc str,
  pub symbols: &'doc [&'doc str],
  pub defined_symbols: Option<&'doc [&'doc str]>,
  pub edge_keys: Option<&'doc [&'doc str]>,
  pub overflow_edge_ids: Option<&'doc [&'doc str]>,
  pub occurrence_count: u64,
  pub has_overflow: bool,
}

#[cfg(test)]
mod tests {
  use super::*;

  #[test]

fn computes_manifest_diff() {
  let temp = tempfile::tempdir().expect("tempdir");
  let root = temp.path();

  let file_a = root.join("a.ts");
  let file_b = root.join("b.ts");
  fs::write(&file_a, "const a = 1;").expect("write a");
  fs::write(&file_b, "const b = 2;").expect("write b");

  let mut manifest = create_empty_manifest("");
  update_manifest(
    &mut manifest,
    "a.ts",
    ScipDocumentInput {
      content_hash: &compute_file_hash(&file_a),
      symbols: &["scip:a"],
      defined_symbols: None,
      edge_keys: None,
      overflow_edge_ids: None,
      occurrence_count: 1,
      has_overflow: false,
    },
  );
  update_manifest(
    &mut manifest,
    "b.ts",
    ScipDocumentInput {
      content_hash: &compute_file_hash(&file_b),
      symbols: &["scip:b"],
      defined_symbols: None,
      edge_keys: None,
      overflow_edge_ids: None,
      occurrence_count: 1,
      has_overflow: false,
    },
  );

  fs::write(&file_a, "const a = 3;").expect("update a");
  let file_c = root.join("c.ts");
  fs::write(&file_c, "const c = 4;").expect("write c");

  let diff = compute_manifest_diff(
    Some(&manifest),
    &["a.ts".to_string(), "c.ts".to_string()],
    root,
  );

  assert_eq!(diff.added, vec!["c.ts"]);
  assert_eq!(diff.modified, vec!["a.ts"]);
  assert_eq!(diff.deleted, vec!["b.ts"]);
  assert!(!diff.requires_full_reindex);
}

#[test]

  fn updates_and_removes_manifest() {
    let mut manifest = create_empty_manifest("");
    update_manifest(
      &mut manifest,
      "a.ts",
      ScipDocumentInput {
        content_hash: "hash",
        symbols: &["scip:a", "scip:b"],
        defined_symbols: None,
        edge_keys: None,
        overflow_edge_ids: None,
        occurrence_count: 2,
        has_overflow: false,
      },
    );

    assert_eq!(references_for_symbol(&manifest, "scip:a"), vec!["a.ts"]);

    remove_from_manifest(&mut manifest, "a.ts");
    assert!(manifest.documents.is_empty());
    assert!(manifest.symbol_references.is_empty());
  }
}

