import { parsePositiveInt } from "@argus/shared-runtime/config-env";
import { sql } from "drizzle-orm";

import { db } from "@/lib/db";
import { appLogEvents } from "@/lib/db/schema";

const ONE_DAY_MS = 24 * 60 * 60 * 1000;
const DEFAULT_RETENTION_DAYS = 30;
const DEFAULT_MAX_ROWS = 2_000_000;
const DEFAULT_DELETE_LIMIT = 20_000;

type LogRetentionPolicy = {
  retentionDays: number;
  maxRows: number;
  deleteLimit: number;
};

type CleanupAppLogsOptions = {
  retentionDays?: number;
  maxRows?: number;
  deleteLimit?: number;
};

export type CleanupAppLogsSummary = {
  lock: "acquired" | "skipped";
  policy: LogRetentionPolicy;
  rowsBefore: number | null;
  rowsAfter: number | null;
  deletedByAge: number;
  deletedByCap: number;
};

const resolvePolicy = (options: CleanupAppLogsOptions): LogRetentionPolicy => ({
  retentionDays:
    options.retentionDays ??
    parsePositiveInt(process.env.APP_LOG_RETENTION_DAYS, DEFAULT_RETENTION_DAYS),
  maxRows: options.maxRows ?? parsePositiveInt(process.env.APP_LOG_MAX_ROWS, DEFAULT_MAX_ROWS),
  deleteLimit:
    options.deleteLimit ??
    parsePositiveInt(process.env.APP_LOG_CLEANUP_DELETE_LIMIT, DEFAULT_DELETE_LIMIT),
});

const toNumber = (value: unknown) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

const loadRowCount = async () => {
  const result = await db.execute(sql`select count(*) as count from ${appLogEvents}`);
  return toNumber((result.rows[0] as { count?: unknown } | undefined)?.count);
};

let cleanupInProgress = false;

export const cleanupAppLogs = async (

  options: CleanupAppLogsOptions = {},
): Promise<CleanupAppLogsSummary> => {
  const policy = resolvePolicy(options);
  const summary: CleanupAppLogsSummary = {
    lock: "skipped",
    policy,
    rowsBefore: null,
    rowsAfter: null,
    deletedByAge: 0,
    deletedByCap: 0,
  };

  if (cleanupInProgress) {
    return summary;
  }

  cleanupInProgress = true;
  summary.lock = "acquired";

  try {
    const rowsBefore = await loadRowCount();
    summary.rowsBefore = rowsBefore;

    const cutoff = new Date(Date.now() - policy.retentionDays * ONE_DAY_MS);

    const ageDeleteResult = await db.execute(sql`
      with doomed as (
        select ${appLogEvents.id} as id
        from ${appLogEvents}
        where ${appLogEvents.createdAt} < ${cutoff}
        order by ${appLogEvents.createdAt} asc
        limit ${policy.deleteLimit}
      )
      delete from ${appLogEvents}
      where ${appLogEvents.id} in (select doomed.id from doomed)
      returning ${appLogEvents.id}
    `);
    summary.deletedByAge = ageDeleteResult.rows.length;

    const rowsAfterAgeDelete = rowsBefore - summary.deletedByAge;
    if (rowsAfterAgeDelete > policy.maxRows) {
      const overflow = rowsAfterAgeDelete - policy.maxRows;
      const capDeleteCount = Math.min(policy.deleteLimit, overflow);
      const capDeleteResult = await db.execute(sql`
        with doomed as (
          select ${appLogEvents.id} as id
          from ${appLogEvents}
          order by ${appLogEvents.createdAt} asc
          limit ${capDeleteCount}
        )
        delete from ${appLogEvents}
        where ${appLogEvents.id} in (select doomed.id from doomed)
        returning ${appLogEvents.id}
      `);
      summary.deletedByCap = capDeleteResult.rows.length;
    }

    summary.rowsAfter = rowsBefore - summary.deletedByAge - summary.deletedByCap;
    return summary;
  } finally {
    cleanupInProgress = false;
  }
};

