import type { ObservabilityLlmMetrics } from "@/lib/observability/types"

type UsageRecord = {
  promptTokens: number
  completionTokens: number
  totalTokens: number
}

type UsageLikePayload = {
  usage?: {
    prompt_tokens?: unknown
    completion_tokens?: unknown
    total_tokens?: unknown
    promptTokens?: unknown
    completionTokens?: unknown
    totalTokens?: unknown
  } | null
}

const asNonNegativeInt = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
    return Math.floor(value)
  }

  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number.parseInt(value, 10)
    if (Number.isFinite(parsed) && parsed >= 0) {
      return parsed
    }
  }

  return null
}

const toUsd = (value: number) => Number(value.toFixed(8))

const normalizeModelEnvKey = (model: string) =>
  model
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")

const resolveUsdPer1kFromEnv = (args: {
  prefix: string
  model: string | null
}): number | null => {
  const modelKey = args.model ? normalizeModelEnvKey(args.model) : ""
  const modelEnvKey = modelKey ? `${args.prefix}_${modelKey}` : ""
  const rawModelRate = modelEnvKey ? process.env[modelEnvKey] : undefined
  const rawGlobalRate = process.env[args.prefix]
  const rawRate = rawModelRate ?? rawGlobalRate
  if (!rawRate || rawRate.trim().length === 0) {
    return null
  }

  const parsed = Number.parseFloat(rawRate)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return null
  }

  return parsed
}

export const resolveLlmProviderLabel = (apiUrl: string): string => {
  try {
    const hostname = new URL(apiUrl).hostname.trim().toLowerCase()
    if (!hostname) {
      return "openai-compatible"
    }
    if (hostname.includes("openai.com")) {
      return "openai"
    }
    return `openai-compatible:${hostname}`
  } catch {
    return "openai-compatible"
  }
}

export const extractUsageFromOpenAiCompatiblePayload = (payload: unknown): UsageRecord => {
  const usage = (payload as UsageLikePayload | null)?.usage ?? null
  if (!usage || typeof usage !== "object" || Array.isArray(usage)) {
    return {
      promptTokens: 0,
      completionTokens: 0,
      totalTokens: 0,
    }
  }

  const promptTokens =
    asNonNegativeInt(usage.prompt_tokens) ??
    asNonNegativeInt(usage.promptTokens) ??
    0
  const completionTokens =
    asNonNegativeInt(usage.completion_tokens) ??
    asNonNegativeInt(usage.completionTokens) ??
    0
  const totalTokens =
    asNonNegativeInt(usage.total_tokens) ??
    asNonNegativeInt(usage.totalTokens) ??
    promptTokens + completionTokens

  return {
    promptTokens,
    completionTokens,
    totalTokens,
  }
}

export const estimateLlmCostUsd = (args: {
  model: string | null
  promptTokens: number
  completionTokens: number
}): number | null => {
  const promptUsdPer1k = resolveUsdPer1kFromEnv({
    prefix: "OBS_LLM_COST_PROMPT_USD_PER_1K",
    model: args.model,
  })
  const completionUsdPer1k = resolveUsdPer1kFromEnv({
    prefix: "OBS_LLM_COST_COMPLETION_USD_PER_1K",
    model: args.model,
  })

  if (promptUsdPer1k === null && completionUsdPer1k === null) {
    return null
  }

  const promptCost = ((promptUsdPer1k ?? 0) * Math.max(0, args.promptTokens)) / 1_000
  const completionCost = ((completionUsdPer1k ?? 0) * Math.max(0, args.completionTokens)) / 1_000
  return toUsd(promptCost + completionCost)
}

export const estimateEmbeddingCostUsd = (args: {
  model: string | null
  totalTokens: number
}): number | null => {
  const usdPer1k = resolveUsdPer1kFromEnv({
    prefix: "OBS_EMBEDDING_COST_USD_PER_1K",
    model: args.model,
  })
  if (usdPer1k === null) {
    return null
  }

  const totalCost = (usdPer1k * Math.max(0, args.totalTokens)) / 1_000
  return toUsd(totalCost)
}

const getOrCreateAnalyticsSessionId = () => {
  if (typeof window === "undefined") {
    return null
  }

  const existing = window.sessionStorage.getItem(ANALYTICS_SESSION_ID_KEY)
  if (existing && existing.trim().length > 0) {
    return existing
  }

  const generated =
    typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
      ? crypto.randomUUID()
      : `${Date.now()}-${Math.random().toString(16).slice(2)}`

  window.sessionStorage.setItem(ANALYTICS_SESSION_ID_KEY, generated)
  return generated
}

export function AppLayoutClient({
  children,
  isAuthenticated,
  isAdmin,
  initialGitLabIntegrations,
}: Readonly<AppLayoutClientProps>) {
  const hasHydrated = useSyncExternalStore(emptySubscribe, getClientSnapshot, getServerSnapshot)
  const router = useRouter()
  useGlobalRoutePrewarmIntent()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const effectiveAuthenticated = isAuthenticated
  const onboardingRoute = hasHydrated && isOnboardingPath(pathname)
  const settingsRoute = hasHydrated && isSettingsPath(pathname)
  const allowUnauthenticatedRoute = isUnauthenticatedRouteAllowed(pathname)
  const shellOnlyRoute = onboardingRoute || (effectiveAuthenticated && settingsRoute)
  const sessionIdRef = useRef<string | null>(null)
  const activeFeatureRef = useRef<string | null>(null)
  const featureEnteredAtRef = useRef<number | null>(null)
  const hasHydratedIntegrationsRef = useRef(false)

useLayoutEffect(() => {
  if (hasHydratedIntegrationsRef.current) {
    return
  }

  if (!initialGitLabIntegrations) {
    return
  }

  hydrateGitLabIntegrationsQuery(initialGitLabIntegrations)
  hasHydratedIntegrationsRef.current = true
}, [initialGitLabIntegrations])

const flushFeatureDuration = useCallback(() => {
  const feature = activeFeatureRef.current
  const startedAt = featureEnteredAtRef.current
  if (!feature || startedAt === null) {
    return
  }

  const durationMs = Math.max(0, Date.now() - startedAt)
  trackAnalyticsEvent({
    event: "session_duration",
    feature,
    durationMs,
    sessionId: sessionIdRef.current ?? undefined,
  })
}, [])

useEffect(() => {
  if (effectiveAuthenticated || pathname === "/" || isOnboardingPath(pathname)) {
    return
  }

  const search = searchParams.toString()
  const nextPath = `${pathname}${search ? `?${search}` : ""}`
  router.replace(`/?next=${encodeURIComponent(nextPath)}`)
}, [effectiveAuthenticated, pathname, router, searchParams])

useEffect(() => {
  if (!effectiveAuthenticated) {
    return
  }
  if (!sessionIdRef.current) {
    sessionIdRef.current = getOrCreateAnalyticsSessionId()
  }
}, [effectiveAuthenticated])

useEffect(() => {
  if (!effectiveAuthenticated) {
    return
  }

  if (!sessionIdRef.current) {
    sessionIdRef.current = getOrCreateAnalyticsSessionId()
  }

  flushFeatureDuration()

  activeFeatureRef.current = pathname
  featureEnteredAtRef.current = Date.now()

  trackAnalyticsEvent({
    event: "feature_opened",
    feature: pathname,
    sessionId: sessionIdRef.current ?? undefined,
  })

  const navigationSample = consumeRouteNavigationSample(pathname)
  if (navigationSample) {
    trackAnalyticsEvent({
      event: "command_used",
      command: "route_navigation",
      feature: pathname,
      sessionId: sessionIdRef.current ?? undefined,
      metadata: {
        route: navigationSample.route,
        isWarm: navigationSample.prefetchHit,
        prefetchHit: navigationSample.prefetchHit,
        navDurationMs: navigationSample.navDurationMs,
        source: navigationSample.source,
      },
    })
  }
}, [effectiveAuthenticated, flushFeatureDuration, pathname])

useEffect(() => {
  if (!effectiveAuthenticated || typeof window === "undefined") {
    return
  }

  const handleBeforeUnload = () => {
    flushFeatureDuration()
  }

  window.addEventListener("beforeunload", handleBeforeUnload)
  return () => {
    window.removeEventListener("beforeunload", handleBeforeUnload)
    flushFeatureDuration()
  }
}, [effectiveAuthenticated, flushFeatureDuration])

if (!effectiveAuthenticated && !allowUnauthenticatedRoute) {
  return null
}

  if (shellOnlyRoute) {
    return (
      <TooltipProvider>
        <div className="group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full">
          <main className="bg-background relative flex w-full flex-1 flex-col max-h-svh overflow-hidden md:[max-height:calc(100svh-1rem)] md:m-2 md:rounded-xl md:shadow-sm">
            {onboardingRoute ? <div className="h-12 shrink-0" /> : null}
            <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
              <div className="@container/main flex min-h-0 flex-1 flex-col gap-2 overflow-hidden">
                <div className="flex min-h-0 flex-1 flex-col gap-4 overflow-auto px-4 py-4 md:gap-6 md:py-6 lg:px-6">
                  {children}
                </div>
              </div>
            </div>
          </main>
        </div>
      </TooltipProvider>
    )
  }

  if (!effectiveAuthenticated) {
    return children
  }

  return (
    <AppShell isAdmin={isAdmin} initialGitLabIntegrations={initialGitLabIntegrations}>
      {children}
    </AppShell>
  )
}

