    body: JSON.stringify({
      instanceUrl,
      token,
      ...(integrationId ? { integrationId } : {}),
      projectId,
      mergeRequestIid,
    }),
  })

  const parsedManifestPayload = await parseJsonResponse(manifestResponse)
  const manifestPayload = parsedManifestPayload.ok
    ? (parsedManifestPayload.value as DiffManifestPayload)
    : null
  if (!manifestResponse.ok) {
    throw new Error(getErrorMessage(manifestPayload))
  }

  const files = Array.isArray(manifestPayload?.data?.files) ? manifestPayload.data.files : []
  const webUrl =
    typeof manifestPayload?.data?.mergeRequest?.webUrl === "string"
      ? manifestPayload.data.mergeRequest.webUrl.trim()
      : ""
  const mode =
    manifestPayload?.data?.mode === "external_review_required" ||
    manifestPayload?.data?.mode === "large_diff_mode" ||
    manifestPayload?.data?.mode === "full"
      ? manifestPayload.data.mode
      : "full"

const renderableFileIds = files.flatMap((file) => {
  if (!file || typeof file !== "object") {
    return []
  }
  if (file.contentState === "requires_external") {
    return []
  }
  const fileId = typeof file.fileId === "string" ? file.fileId.trim() : ""
  return fileId ? [fileId] : []
})

if (renderableFileIds.length === 0) {
  if (mode === "external_review_required" && webUrl) {
    throw new Error(`Diff is too large for in-app rendering. Open in GitLab: ${webUrl}`)
  }
  throw new Error("Merge request has no diff content to render.")
}

const patchChunks: string[] = []

  for (const fileId of renderableFileIds) {
    let done = false
    let nextCursor: string | undefined
    const filePatchChunks: string[] = []

    while (!done) {
      const fileResponse = await fetch("/api/gitlab/diff/file", {
        method: "POST",
        headers: {
          "content-type": "application/json",
          accept: "application/json",
        },
        body: JSON.stringify({
          instanceUrl,
          token,
          ...(integrationId ? { integrationId } : {}),
          projectId,
          mergeRequestIid,
          fileId,
          ...(nextCursor ? { cursor: nextCursor } : {}),
        }),
      })
      const parsedFilePayload = await parseJsonResponse(fileResponse)
      const filePayload = parsedFilePayload.ok
        ? (parsedFilePayload.value as DiffFilePayload)
        : null
      if (!fileResponse.ok) {
        throw new Error(getErrorMessage(filePayload))
      }
      const fileData = filePayload?.data
      if (!fileData || !Array.isArray(fileData.chunks)) {
        throw new Error("Unexpected diff file response from server.")
      }
      for (const chunk of fileData.chunks) {
        if (typeof chunk === "string") {
          filePatchChunks.push(chunk)
        }
      }

      done = fileData.done === true
      nextCursor = typeof fileData.nextCursor === "string" ? fileData.nextCursor : undefined
    }

    patchChunks.push(filePatchChunks.join(""))
  }

  return patchChunks.join("\n\n")
}

