export const dedupeFindings = (findings: ReviewFinding[]) => {
  const deduped = new Map<string, ReviewFinding>()
  for (const finding of findings) {
    const normalizedFile = normalizePatchPath(finding.file)
    const key = buildReviewCommentFeedbackKey({
      file: normalizedFile,
      side: finding.side,
      line: finding.line,
      title: finding.title,
    })
    const normalizedFinding = {
      ...finding,
      file: normalizedFile,
    }
    const current = deduped.get(key)
    if (!current) {
      deduped.set(key, normalizedFinding)
      continue
    }

    if (normalizedFinding.confidence > current.confidence) {
      deduped.set(key, normalizedFinding)
      continue
    }

    if (normalizedFinding.confidence === current.confidence) {
      const currentEvidenceLength = (current.evidence ?? "").trim().length
      const nextEvidenceLength = (normalizedFinding.evidence ?? "").trim().length
      if (nextEvidenceLength > currentEvidenceLength) {
        deduped.set(key, normalizedFinding)
      }
    }
  }
  return Array.from(deduped.values())
}

export const buildReviewSummary = (findings: ReviewFinding[]) => {
  if (findings.length === 0) {
    return "AI review complete. No findings."
  }

  const highCount = findings.filter((finding) => finding.severity === "high").length
  const medCount = findings.filter((finding) => finding.severity === "med").length
  const lowCount = findings.length - highCount - medCount
  return `AI review complete: ${findings.length} findings (${highCount} high, ${medCount} med, ${lowCount} low).`
}

