export const resolvePersonaPassesForMode = ({
  personaMode,
  persona,
  personaPasses,
}: {
  personaMode: ReviewPersonaMode
  persona: ReviewPersona
  personaPasses: ReviewPersona[]
}) => {
  if (personaMode === "disabled") {
    return [] as ReviewPersona[]
  }
  if (personaMode === "multi") {
    return personaPasses.length > 0 ? personaPasses : [...REVIEW_PERSONA_VALUES]
  }
  return [persona]
}

export const resolvePersonaProgress = ({
  personaMode,
  persona,
  personaPasses,
  currentPersonaPassIndex,
  currentPersonaPassTotal,
}: {
  personaMode: ReviewPersonaMode
  persona: ReviewPersona
  personaPasses: ReviewPersona[]
  currentPersonaPassIndex: number
  currentPersonaPassTotal: number
}) => {
  if (personaMode === "disabled") {
    return {
      currentPersonaPass: null,
      currentPersonaPassIndex: 0,
      currentPersonaPassTotal: 0,
    }
  }

  if (personaMode === "single") {
    return {
      currentPersonaPass: persona,
      currentPersonaPassIndex: 1,
      currentPersonaPassTotal: 1,
    }
  }

  const resolvedPasses = personaPasses.length > 0 ? personaPasses : [...REVIEW_PERSONA_VALUES]
  const inferredIndex = resolvedPasses.indexOf(persona)

  return {
    currentPersonaPass: persona,
    currentPersonaPassIndex:
      currentPersonaPassIndex > 0
        ? currentPersonaPassIndex
        : inferredIndex >= 0
          ? inferredIndex + 1
          : 0,
    currentPersonaPassTotal:
      currentPersonaPassTotal > 0 ? currentPersonaPassTotal : resolvedPasses.length,
  }
}

export const normalizeReviewRunStage = (
  value: unknown,
  fallback: ReviewRunState["stage"] = "idle",
): ReviewRunState["stage"] => {
  const stage = String(value ?? "").trim().toLowerCase()
  if (
    stage === "idle" ||
    stage === "queued" ||
    stage === "chunking" ||
    stage === "analyzing" ||
    stage === "mapping" ||
    stage === "saving" ||
    stage === "done" ||
    stage === "failed"
  ) {
    return stage
  }
  return fallback
}

export const normalizeReviewRunDedupeReason = (value: unknown) => {
  const normalized = String(value ?? "").trim().toLowerCase()
  if (normalized === "active_in_progress" || normalized === "same_patch_success") {
    return normalized
  }
  return null
}

export const parseReviewStreamEventRecord = (
  value: unknown,
): ReviewStreamEventRecord | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  const record = value as Record<string, unknown>
  const id = toInteger(record.id)
  if (id < 1) {
    return null
  }
  const createdAt = toTimestampMs(record.createdAt) ?? Date.now()
  return {
    id,
    traceId: String(record.traceId ?? "").trim(),
    flowRunId: String(record.flowRunId ?? "").trim(),
    stage: normalizeReviewRunStage(record.stage, "analyzing"),
    eventType: String(record.eventType ?? "progress").trim() || "progress",
    message: String(record.message ?? "").trim(),
    payload: toRecord(record.payload),
    createdAt,
  }
}

use tree_sitter::Node;

use super::range::{node_text, to_range};
use super::types::{Range, Reference, ReferenceKind};

fn callee_name(source: &str, node: Node) -> Option<String> {

  let node_type = node.kind();
  if matches!(
    node_type,
    "identifier"
      | "field_identifier"
      | "qualified_identifier"
      | "scoped_identifier"
      | "operator_name"
      | "destructor_name"
  ) {
    let text = node_text(source, node);
    if !text.is_empty() {
      return Some(text);
    }
  }

  if node_type == "member_expression" {
    if let Some(property) = node.child_by_field_name("property") {
      let text = node_text(source, property);
      if !text.is_empty() {
        return Some(text);
      }
    }
  }

  if node_type == "attribute" {
    if let Some(attribute) = node.child_by_field_name("attribute") {
      let text = node_text(source, attribute);
      if !text.is_empty() {
        return Some(text);
      }
    }
  }

  if node_type == "field_expression" {
    if let Some(field) = node.child_by_field_name("field") {
      if let Some(name) = callee_name(source, field) {
        return Some(name);
      }
      let text = node_text(source, field);
      if !text.is_empty() {
        return Some(text);
      }
    }
  }

  if let Some(name_field) = node
    .child_by_field_name("name")
    .or_else(|| node.child_by_field_name("constructor"))
  {
    if let Some(name) = callee_name(source, name_field) {
      return Some(name);
    }
    let text = node_text(source, name_field);
    if !text.is_empty() {
      return Some(text);
    }
  }

  if let Some(function_field) = node.child_by_field_name("function") {
    if let Some(name) = callee_name(source, function_field) {
      return Some(name);
    }
  }

  None
}

pub fn extract_references_from_tree(source_text: &str, tree: &tree_sitter::Tree) -> Vec<Reference> {
  let mut references = Vec::new();
  let mut stack = vec![tree.root_node()];

  while let Some(node) = stack.pop() {
    match node.kind() {
      "call_expression" | "call" => {
        if let Some(callee) = node.child_by_field_name("function") {
          if let Some(name) = callee_name(source_text, callee) {
            references.push(Reference {
              name,
              kind: ReferenceKind::Call,
              range: to_range(node),
            });
          }
        }
      }
      "function_call" => {
        if let Some(callee) = node.child_by_field_name("name") {
          if let Some(name) = callee_name(source_text, callee) {
            references.push(Reference {
              name,
              kind: ReferenceKind::Call,
              range: to_range(node),
            });
          }
        }
      }
      "new_expression" => {
        let ctor = node
          .child_by_field_name("constructor")
          .or_else(|| node.child_by_field_name("type"));
        if let Some(ctor) = ctor {
          if let Some(name) = callee_name(source_text, ctor) {
            references.push(Reference {
              name,
              kind: ReferenceKind::New,
              range: to_range(node),
            });
          }
        }
      }
      _ => {}
    }

    for i in 0..node.child_count() {
      let index = u32::try_from(i).unwrap_or(u32::MAX);
      if let Some(child) = node.child(index) {
        stack.push(child);
      }
    }
  }

  references
}

pub fn filter_references_to_known(
  references: Vec<Reference>,
  known_symbols: &std::collections::HashSet<String>,
) -> Vec<Reference> {
  references
    .into_iter()
    .filter(|reference| known_symbols.contains(&reference.name))
    .collect()
}

pub fn range_contains(container: Range, inner: Range) -> bool {
  if inner.start.row < container.start.row {
    return false;
  }
  if inner.end.row > container.end.row {
    return false;
  }
  if inner.start.row == container.start.row && inner.start.column < container.start.column {
    return false;
  }
  if inner.end.row == container.end.row && inner.end.column > container.end.column {
    return false;
  }
  true
}

