const [recentlyQueuedRun, setRecentlyQueuedRun] = useState<{
  key: string
  requestedAtMs: number
  runId: string | null
} | null>(null)
const [progressTarget, setProgressTarget] = useState<ProgressTarget | null>(null)
const [progressDialogOpen, setProgressDialogOpen] = useState(false)

const [progressNowMs, setProgressNowMs] = useState(() => Date.now())
const [streamStatus, setStreamStatus] = useState<IndexingStreamStatus>("idle")
const [lastStreamEventAt, setLastStreamEventAt] = useState<Date | null>(null)
const [streamConnectNonce, setStreamConnectNonce] = useState(0)
const reconnectAttemptsRef = useRef(0)
const [liveLogs, setLiveLogs] = useState<LiveIndexerLog[]>([])
const [liveLogStreamStatus, setLiveLogStreamStatus] = useState<"idle" | "connecting" | "live" | "disconnected">("idle")
const [branchFilter, setBranchFilter] = useState("")
const [runFilter, setRunFilter] = useState("")

const staleBranchCount = useMemo(
  () => branches.filter(branchNeedsReconcile).length,
  [branches],
)
const pendingPruneBranchCount = useMemo(
  () =>
    branches.filter((branch) => branch.lifecycleStatus === BRANCH_LIFECYCLE_PENDING_PRUNE).length,
  [branches],
)

const graphStatusSummary = useMemo(() => {
  let ready = 0
  let indexing = 0
  let failed = 0
  let missing = 0

  for (const branch of branches) {
    const status = resolveBranchGraphStatus(branch)
    if (status === "ready") {
      ready += 1
    } else if (status === "indexing") {
      indexing += 1
    } else if (status === "failed") {
      failed += 1
    } else {
      missing += 1
    }
  }

  return {
    ready,
    indexing,
    failed,
    missing,
  }
}, [branches])

const filteredBranches = useMemo(() => {
  if (!branchFilter) return branches
  const q = branchFilter.toLowerCase()
  return branches.filter((b) => b.branch.toLowerCase().includes(q))
}, [branches, branchFilter])

const filteredRuns = useMemo(() => {
  if (!runFilter) return runs
  const q = runFilter.toLowerCase()
  return runs.filter((r) => r.branch.toLowerCase().includes(q) || r.status.toLowerCase().includes(q))
}, [runs, runFilter])

const suggestedRunTarget = useMemo(
  () => deriveSuggestedRunTarget({ branches, runs }),
  [branches, runs],
)

const progressBranch = useMemo(() => {
  if (!progressTarget) {
    return null
  }
  return (
    branches.find(
      (branch) =>
        branch.branch === progressTarget.branch &&
        branch.configHash === progressTarget.configHash,
    ) ?? null
  )
}, [branches, progressTarget])

const progressRun = useMemo(
  () => selectProgressRun({
    progressTarget,
    recentlyQueuedRun,
    progressBranchLastRunId: progressBranch?.lastRun?.id ?? null,
    runs,
  }),
  [progressBranch?.lastRun?.id, progressTarget, recentlyQueuedRun, runs],
)

const progressRowKey = progressTarget
  ? buildBranchKey(progressTarget.branch, progressTarget.configHash)
  : null

const queuedProgressRequest = progressRowKey && recentlyQueuedRun?.key === progressRowKey
  ? recentlyQueuedRun
  : null
const queuedProgressPending = isQueuedProgressPending({
  queuedProgressRequest,
  progressRun,
})

const progressDisplayRun = queuedProgressPending ? null : progressRun

const progressStatus = queuedProgressPending
  ? "planned"
  : progressDisplayRun?.status ??
    progressBranch?.lastRun?.status ??
    null
const progressErrorRaw = progressDisplayRun?.error ?? null
const progressError = useMemo(
  () => (progressErrorRaw ? describeRunError(progressErrorRaw) : null),
  [progressErrorRaw],
)
const progressIsQueueing = progressRowKey !== null && reindexingKey === progressRowKey
const progressRunId = progressDisplayRun?.id ?? null
const progressRunIsActive = Boolean(progressDisplayRun && RUN_ACTIVE_STATUSES.has(progressDisplayRun.status))
const progressCanCancel = Boolean(progressRunId && progressStatus && RUN_ACTIVE_STATUSES.has(progressStatus))
const progressIsCancelling = progressRunId !== null && cancelingRunId === progressRunId

const pipelineStages = useMemo(
  () => buildPipelineStages(progressStatus),
  [progressStatus],
)

const progressRunStats = useMemo(
  () => readRunStats(progressDisplayRun),
  [progressDisplayRun],
)

const progressStartedAtMs = useMemo(() => {
  if (!progressDisplayRun) {
    return queuedProgressRequest?.requestedAtMs ?? null
  }

  const runCreatedAtMs = parseTimestampMs(progressDisplayRun.createdAt)
  if (!queuedProgressRequest) {
    return runCreatedAtMs
  }
  if (runCreatedAtMs === null) {
    return queuedProgressRequest.requestedAtMs
  }
  return Math.max(runCreatedAtMs, queuedProgressRequest.requestedAtMs)
}, [progressDisplayRun, queuedProgressRequest])

const progressElapsedMs = useMemo(() => {
  if (progressStartedAtMs === null) {
    return null
  }

  if (!progressDisplayRun) {
    return Math.max(0, progressNowMs - progressStartedAtMs)
  }

  const updatedAt = parseTimestampMs(progressDisplayRun.updatedAt)
  if (updatedAt === null) {
    return null
  }

  const endMs = RUN_ACTIVE_STATUSES.has(progressDisplayRun.status)
    ? progressNowMs
    : updatedAt
  return Math.max(0, endMs - progressStartedAtMs)
}, [progressDisplayRun, progressNowMs, progressStartedAtMs])

const progressStartedAtDisplay = useMemo(() => {
  if (progressStartedAtMs === null) {
    return null
  }
  return new Date(progressStartedAtMs).toISOString()
}, [progressStartedAtMs])

useEffect(() => {
  if (!queuedProgressRequest || queuedProgressRequest.runId || !progressRun) {
    return
  }

  const runTimestampMs =
    parseTimestampMs(progressRun.updatedAt) ??
    parseTimestampMs(progressRun.createdAt)
  if (runTimestampMs === null || runTimestampMs < queuedProgressRequest.requestedAtMs - 1_000) {
    return
  }

  setRecentlyQueuedRun((current) => {
    if (!current || current.key !== queuedProgressRequest.key || current.runId) {
      return current
    }
    return {
      ...current,
      runId: progressRun.id,
    }
  })
}, [progressRun, queuedProgressRequest])

