const loadIndexingData = useCallback(async (integrationId: string, quiet?: boolean) => {
  if (!quiet) {
    setIsLoadingIndexing(true)
  }
  try {
    const [runsResponse, branchesResponse] = await Promise.all([
      fetch(`/api/gitlab/integrations/${integrationId}/index/runs?page=1&limit=20`, {
        method: "GET",
        headers: { "content-type": "application/json" },
      }),
      fetch(`/api/gitlab/integrations/${integrationId}/index/branches`, {
        method: "GET",
        headers: { "content-type": "application/json" },
      }),
    ])

    const [parsedRunsPayload, parsedBranchesPayload] = await Promise.all([
      parseJsonResponse(runsResponse),
      parseJsonResponse(branchesResponse),
    ])
    const runsPayload = parsedRunsPayload.ok ? parsedRunsPayload.value : null

    const branchesPayload = parsedBranchesPayload.ok ? parsedBranchesPayload.value : null

    if (!runsResponse.ok) {
      throw new Error(extractErrorMessage(runsPayload, "Failed to load indexing runs."))
    }

    if (!branchesResponse.ok) {
      throw new Error(extractErrorMessage(branchesPayload, "Failed to load branch states."))
    }

    const typedRunsPayload = runsPayload as IndexRunsPayload
    const typedBranchesPayload = branchesPayload as IndexBranchesPayload

    setRuns(
      Array.isArray(typedRunsPayload.data)
        ? typedRunsPayload.data.flatMap((entry) => {
          const run = normalizeIndexRun(entry)
          return run ? [run] : []
        })
        : [],
    )
    setRunsPagination(typedRunsPayload.pagination ?? null)
    setQueueSummary(typedRunsPayload.queue ?? null)
    setWorkerTelemetry(typedRunsPayload.worker ?? null)
    setBranches(Array.isArray(typedBranchesPayload.data) ? typedBranchesPayload.data : [])
    setLatestReconcile(typedBranchesPayload.reconcile ?? typedRunsPayload.reconcile ?? null)
    setLastRefreshedAt(new Date())
    setErrorMessage("")
  } catch (error) {
    setErrorMessage(error instanceof Error ? error.message : "Failed to load indexing data.")
  } finally {
    if (!quiet) {
      setIsLoadingIndexing(false)
    }
  }
}, [])

