const clearTimers = () => {
  if (reconnectTimer) {
    window.clearTimeout(reconnectTimer)
    reconnectTimer = null
  }
  if (staleTimer) {
    window.clearTimeout(staleTimer)
    staleTimer = null
  }
}

const closeSource = () => {
  if (source) {
    source.close()
    source = null
  }
}

const markStreamActivity = () => {
  setLastStreamEventAt(new Date())
  setStreamStatus("live")
  if (staleTimer) {
    window.clearTimeout(staleTimer)
  }
  staleTimer = window.setTimeout(() => {
    if (!cancelled) {
      setStreamStatus("stale")
    }
  }, STREAM_HEARTBEAT_TIMEOUT_MS)
}

const scheduleReconnect = () => {
  closeSource()
  if (cancelled) {
    return
  }

  if (reconnectAttemptsRef.current >= STREAM_MAX_RECONNECT_ATTEMPTS) {
    setStreamStatus("disconnected")
    return
  }

  reconnectAttemptsRef.current += 1
  const backoffDelayMs = Math.min(
    10_000,
    STREAM_RECONNECT_BASE_DELAY_MS * 2 ** (reconnectAttemptsRef.current - 1),
  )
  setStreamStatus("connecting")
  reconnectTimer = window.setTimeout(connect, backoffDelayMs)
}

  const connect = () => {
    if (cancelled) {
      return
    }

    if (reconnectTimer) {
      window.clearTimeout(reconnectTimer)
      reconnectTimer = null
    }

    setStreamStatus("connecting")
    closeSource()
    source = new EventSource(`/api/gitlab/integrations/${selectedIntegrationId}/index/stream`)

    source.onopen = () => {
      reconnectAttemptsRef.current = 0
      markStreamActivity()
    }

    const handlePushUpdate = () => {
      markStreamActivity()
      void loadIndexingData(selectedIntegrationId, true)
    }

    const handleHeartbeat = () => {
      markStreamActivity()
    }

    source.addEventListener("ready", handlePushUpdate)
    source.addEventListener("update", handlePushUpdate)
    source.addEventListener("heartbeat", handleHeartbeat)

    source.onerror = () => {
      if (cancelled) {
        return
      }
      setStreamStatus("stale")
      scheduleReconnect()
    }
  }

  connect()

  return () => {
    cancelled = true
    clearTimers()
    closeSource()
  }
}, [loadIndexingData, selectedIntegrationId, streamConnectNonce])

useEffect(() => {
  if (!selectedIntegrationId || !progressDialogOpen) {
    setLiveLogStreamStatus("idle")
    if (!progressDialogOpen) {
      setLiveLogs([])
    }
    return
  }

  let cancelled = false
  let reconnectTimer: number | null = null
  let source: EventSource | null = null

  const closeSource = () => {
    if (source) {
      source.close()
      source = null
    }
  }

const connect = () => {
  if (cancelled) {
    return
  }

  setLiveLogStreamStatus("connecting")
  closeSource()
  source = new EventSource(
    `/api/gitlab/integrations/${selectedIntegrationId}/index/logs/stream?limit=${LIVE_LOG_STREAM_LIMIT}`,
  )

  source.onopen = () => {
    setLiveLogStreamStatus("live")
  }

  source.addEventListener("ready", (event) => {
    const payload = parseSseRecord((event as MessageEvent).data)
    const logs = parseLiveLogs(payload?.logs)
    setLiveLogs(logs.slice(-MAX_LIVE_LOG_ENTRIES))
    setLiveLogStreamStatus("live")
  })

  source.addEventListener("log", (event) => {
    const payload = parseSseRecord((event as MessageEvent).data)
    const parsed = parseLiveLog(payload?.log)
    if (!parsed) {
      return
    }

    setLiveLogs((current) => {
      if (current.some((entry) => entry.id === parsed.id)) {
        return current
      }
      const next = [...current, parsed]
      return next.slice(-MAX_LIVE_LOG_ENTRIES)
    })
    setLiveLogStreamStatus("live")
  })

  source.onerror = () => {
    setLiveLogStreamStatus("disconnected")
    closeSource()
    if (cancelled) {
      return
    }
    reconnectTimer = window.setTimeout(connect, STREAM_RECONNECT_DELAY_MS)
  }
}

connect()

return () => {
  cancelled = true
  if (reconnectTimer) {
    window.clearTimeout(reconnectTimer)
  }
  closeSource()
}

}, [progressDialogOpen, selectedIntegrationId])

