import { Buffer } from "node:buffer"
import { GITLAB_DEFAULT_JOB_BATCH_SIZE } from "@/lib/gitlab/constants"

const isLikelyBase64 = (value: string) => /^[A-Za-z0-9+/=_-]+$/.test(value)

const parseEncryptionKey = (value: string) => {
  const trimmed = value.trim()
  if (!trimmed) {
    throw new Error("GITLAB_TOKEN_ENCRYPTION_KEY is required.")
  }

  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    return Buffer.from(trimmed, "hex")
  }

  if (isLikelyBase64(trimmed)) {
    const normalized = trimmed.replace(/-/g, "+").replace(/_/g, "/")
    try {
      const decoded = Buffer.from(normalized, "base64")
      if (decoded.length === 32) {
        return decoded
      }
    } catch {
    }
  }

  const utf8 = Buffer.from(trimmed, "utf8")
  if (utf8.length === 32) {
    return utf8
  }

  throw new Error(
    [
      "GITLAB_TOKEN_ENCRYPTION_KEY must decode to exactly 32 bytes (raw/base64/base64url/hex).",
      "Action: set a valid key, for example:",
      "  export GITLAB_TOKEN_ENCRYPTION_KEY=\"$(openssl rand -base64 32)\"",
      "Or write it to .env.local:",
      "  printf 'GITLAB_TOKEN_ENCRYPTION_KEY=%s\\n' \"$(openssl rand -base64 32)\" >> .env.local",
    ].join("\n"),
  )
}

const normalizePublicUrl = (value: string) => {
  const trimmed = value.trim()
  if (!trimmed) {
    throw new Error("BETTER_AUTH_URL is required.")
  }

  let parsed: URL
  try {
    parsed = new URL(trimmed)
  } catch {
    throw new Error("BETTER_AUTH_URL must be a valid absolute URL.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("BETTER_AUTH_URL must use http or https.")
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  return pathname ? `${parsed.origin}${pathname}` : parsed.origin
}

const parseBatchSize = (value: string | undefined) => {
  if (!value) {
    return GITLAB_DEFAULT_JOB_BATCH_SIZE
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error("GITLAB_JOB_BATCH_SIZE must be a positive integer when set.")
  }

  return Math.min(parsed, 200)
}

const readNonEmpty = (name: string, value: string | undefined) => {
  if (!value || !value.trim()) {
    throw new Error(`${name} is required.`)
  }
  return value.trim()
}

const appPublicUrl = normalizePublicUrl(readNonEmpty("BETTER_AUTH_URL", process.env.BETTER_AUTH_URL))
const tokenEncryptionKey = parseEncryptionKey(
  readNonEmpty("GITLAB_TOKEN_ENCRYPTION_KEY", process.env.GITLAB_TOKEN_ENCRYPTION_KEY),
)
const internalRunnerKey = readNonEmpty("INTERNAL_RUNNER_KEY", process.env.INTERNAL_RUNNER_KEY)
const jobBatchSize = parseBatchSize(process.env.GITLAB_JOB_BATCH_SIZE)

export const gitlabEnv = {
  appPublicUrl,
  internalRunnerKey,
  jobBatchSize,
  tokenEncryptionKey,
} as const

import { and, count, desc, eq, gte, inArray, sql } from "drizzle-orm"
import { NextResponse } from "next/server"

import { db } from "@/lib/db"
import { appLogEvents, indexJobs, indexRuns } from "@/lib/db/schema"
import type {
  ObservabilityHealthIssue,
  ObservabilityHealthStatus,
  ObservabilityIndexingHealthPayload,
} from "@/lib/observability/types"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const WORKER_HEARTBEAT_STALE_AFTER_MS = 2 * 60_000

const toIso = (value: unknown): string | null => {
  if (!value) {
    return null
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value.toISOString()
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = new Date(value)
    return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString()
  }
  return null
}

const toCount = (value: unknown) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value
  }
  if (typeof value === "bigint") {
    return Number(value)
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = Number.parseInt(value, 10)
    return Number.isFinite(parsed) ? parsed : 0
  }
  return 0
}

const toAgeMs = (value: unknown) => {
  const iso = toIso(value)
  if (!iso) {
    return null
  }
  const parsed = new Date(iso)
  const ageMs = Date.now() - parsed.getTime()
  return Number.isFinite(ageMs) && ageMs >= 0 ? ageMs : null
}

const buildStatus = (args: {
  workerFatal15m: number
  heartbeatAgeMs: number | null
  ingestFailed30m: number
  apiIndex5xx10m: number
}) => {
  if (
    args.workerFatal15m > 0 ||
    (args.heartbeatAgeMs !== null && args.heartbeatAgeMs > WORKER_HEARTBEAT_STALE_AFTER_MS)
  ) {
    return "critical" as const
  }
  if (args.ingestFailed30m > 0 || args.apiIndex5xx10m >= 3) {
    return "degraded" as const
  }
  return "healthy" as const
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/observability/indexing-health",
    event: "api.observability.indexing_health",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const [
        [workerFatal15mRow],
        [ingestFailed30mRow],
        [apiIndex5xx10mRow],
        [failedRuns24hRow],
        [failedJobs24hRow],
        [pendingJobsRow],
        [processingJobsRow],
        [latestHeartbeatRow],
        latestWorkerFatal,
        latestIngestFailed,
        latestApiIndex5xx,
      ] = await Promise.all([
        db
          .select({ count: count() })
          .from(appLogEvents)
          .where(
            and(
              eq(appLogEvents.event, "indexer.worker.fatal"),
              gte(appLogEvents.timestamp, sql`now() - interval '15 minutes'`),
            ),
          ),

  db
    .select({
      timestamp: appLogEvents.timestamp,
      level: appLogEvents.level,
      requestId: appLogEvents.requestId,
      event: appLogEvents.event,
      path: appLogEvents.path,
    })
    .from(appLogEvents)
    .where(
      and(
        sql`${appLogEvents.event} like 'api.gitlab.index.%'`,
        gte(appLogEvents.status, 500),
        gte(appLogEvents.timestamp, sql`now() - interval '24 hours'`),
      ),
    )
    .orderBy(desc(appLogEvents.timestamp))
    .limit(1),
])

const workerFatal15m = toCount(workerFatal15mRow?.count)
const ingestFailed30m = toCount(ingestFailed30mRow?.count)
const apiIndex5xx10m = toCount(apiIndex5xx10mRow?.count)
const failedRuns24h = toCount(failedRuns24hRow?.count)
const failedJobs24h = toCount(failedJobs24hRow?.count)
const pendingJobs = toCount(pendingJobsRow?.count)
const processingJobs = toCount(processingJobsRow?.count)
const workerHeartbeatAt = toIso(latestHeartbeatRow?.value)
const workerHeartbeatAgeMs = toAgeMs(latestHeartbeatRow?.value)

const healthStatus: ObservabilityHealthStatus = buildStatus({
  workerFatal15m,
  heartbeatAgeMs: workerHeartbeatAgeMs,
  ingestFailed30m,
  apiIndex5xx10m,
})

const issues: ObservabilityHealthIssue[] = []

      if (latestApiIndex5xx[0] && apiIndex5xx10m > 0) {
        issues.push({
          key: "index_api_5xx",
          severity: "warning",
          title: "Index API errors",
          detail: "Indexing API endpoints returned 5xx responses.",
          count: apiIndex5xx10m,
          level: latestApiIndex5xx[0].level,
          lastSeenAt: toIso(latestApiIndex5xx[0].timestamp),
          requestId: latestApiIndex5xx[0].requestId,
          event: latestApiIndex5xx[0].event,
          path: latestApiIndex5xx[0].path,
        })
      }

      logger.set({
        healthStatus,
        workerFatal15m,
        ingestFailed30m,
        apiIndex5xx10m,
        failedRuns24h,
        failedJobs24h,
        pendingJobs,
        processingJobs,
        workerHeartbeatAgeMs,
      })

      const responsePayload: ObservabilityIndexingHealthPayload = {
        status: healthStatus,
        summary: {
          workerFatal15m,
          ingestFailed30m,
          apiIndex5xx10m,
          failedRuns24h,
          failedJobs24h,
          pendingJobs,
          processingJobs,
          workerHeartbeatAt,
          workerHeartbeatAgeMs,
          workerHeartbeatStaleAfterMs: WORKER_HEARTBEAT_STALE_AFTER_MS,
        },
        issues,
      }

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json(responsePayload),
      }
    },
  })
}

