fn load_config(path: &Path) -> anyhow::Result<JsonConfig> {
  let raw = fs::read_to_string(path)
    .with_context(|| format!("failed to read config: {}", path.to_string_lossy()))?;
  let cfg = serde_json::from_str::<JsonConfig>(&raw)
    .with_context(|| format!("invalid JSON config: {}", path.to_string_lossy()))?;
  Ok(cfg)
}

fn query_embedding_cache_path(store_path: &Path) -> PathBuf {
  let file_name = store_path
    .file_name()
    .map(|name| format!("{}.query-cache.json", name.to_string_lossy()))
    .unwrap_or_else(|| "index.kite.query-cache.json".to_string());
  store_path
    .parent()
    .map(|parent| parent.join(&file_name))
    .unwrap_or_else(|| PathBuf::from(file_name))
}

fn load_query_embedding_cache(path: &Path) -> QueryEmbeddingCache {
  match fs::read_to_string(path) {
    Ok(raw) => serde_json::from_str::<QueryEmbeddingCache>(&raw).unwrap_or_default(),
    Err(_) => QueryEmbeddingCache::default(),
  }
}

fn save_query_embedding_cache(path: &Path, cache: &QueryEmbeddingCache) -> anyhow::Result<()> {
  if let Some(parent) = path.parent() {
    fs::create_dir_all(parent)?;
  }
  let payload = serde_json::to_string_pretty(cache)?;
  fs::write(path, format!("{payload}\n"))?;
  Ok(())
}

fn query_embedding_cache_key(provider: &JsonHttpVectorProvider, query: &str) -> String {
  format!(
    "{}|{}|{}|{}",
    provider.base_url.trim(),
    provider.model.trim(),
    provider.dimension.unwrap_or(0),
    query.trim()
  )
}

fn project_root_from_config(config_path: Option<&Path>, cfg: &JsonConfig) -> Option<PathBuf> {
  let root = cfg.project_root.as_ref()?;
  let parsed = PathBuf::from(root);
  if parsed.is_absolute() {
    return Some(parsed);
  }
  let base = config_path
    .and_then(|p| p.parent())
    .unwrap_or_else(|| Path::new("."));
  Some(base.join(parsed))
}

fn resolve_project_root(
  config_path: Option<&Path>,
  cfg: &JsonConfig,
  override_root: Option<PathBuf>,
) -> PathBuf {
  if let Some(root) = override_root {
    return root;
  }
  if let Some(root) = project_root_from_config(config_path, cfg) {
    return root;
  }
  std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn split_list(value: Option<&str>) -> Vec<String> {
  value
    .unwrap_or("")
    .split(',')
    .map(|entry| entry.trim().to_string())
    .filter(|entry| !entry.is_empty())
    .collect()
}

fn normalize_phase_name(value: &str) -> Option<&'static str> {
  let lowered = value.to_ascii_lowercase();
  match lowered.as_str() {
    "parse" => Some("parse"),
    "graph" => Some("graph"),
    "vector" => Some("vector"),
    "scip" => Some("scip"),
    "indexpack" | "index-pack" | "index_pack" => Some("indexPack"),
    _ => None,
  }
}

fn parse_phase_overrides(value: Option<&str>) -> anyhow::Result<Option<IndexPhases>> {
  let phases = split_list(value);
  if phases.is_empty() {
    return Ok(None);
  }

  let mut enabled = HashSet::new();
  let mut unknown = Vec::new();
  for phase in phases {
    match normalize_phase_name(&phase) {
      Some(name) => {
        enabled.insert(name);
      }
      None => unknown.push(phase),
    }
  }

  if !unknown.is_empty() {
    anyhow::bail!(
      "unknown phase(s): {} (allowed: parse, graph, vector, scip, indexPack)",
      unknown.join(", ")
    );
  }

  Ok(Some(IndexPhases {
    parse: enabled.contains("parse"),
    graph: enabled.contains("graph"),
    vector: enabled.contains("vector"),
    scip: enabled.contains("scip"),
    index_pack: enabled.contains("indexPack"),
  }))
}

fn signature_mtime_len(path: &Path) -> Option<(u128, u64)> {
  let meta = fs::metadata(path).ok()?;
  let mtime = meta
    .modified()
    .ok()?
    .duration_since(std::time::UNIX_EPOCH)
    .ok()?;
  Some((mtime.as_millis(), meta.len()))
}

fn build_index_options(
  project_root: &Path,
  config_path: Option<&Path>,
  config: &JsonConfig,
  store_path: &Path,
  no_vector: bool,
  phase_overrides: Option<&str>,
) -> anyhow::Result<(IndexOptions, Option<std::sync::Arc<dyn EmbeddingsProvider>>)> {
  let mut options = IndexOptions::new(project_root.to_path_buf());

  if let Some(inputs) = &config.inputs {
    options.inputs = ParseInputs {
      paths: inputs
        .paths
        .clone()
        .unwrap_or_default()
        .into_iter()
        .map(|p| {
          let path = PathBuf::from(p);
          if path.is_relative() {
            project_root.join(path)
          } else {
            path
          }
        })
        .collect(),
      include: inputs.include.clone().unwrap_or_default(),
      exclude: inputs.exclude.clone().unwrap_or_default(),
      respect_gitignore: inputs.respect_gitignore.unwrap_or(true),
    };
  }

  let phases = config.phases.unwrap_or_default();
  // For `ci`, default to parse+graph+vector, without index-pack.
  let mut out = IndexPhases {
    parse: phases.parse.unwrap_or(true),
    graph: phases.graph.unwrap_or(true),
    vector: phases.vector.unwrap_or(true),
    scip: phases.scip.unwrap_or(false),
    index_pack: phases.index_pack.unwrap_or(false),
  };
  if let Some(override_phases) = parse_phase_overrides(phase_overrides)? {
    out = override_phases;
  }
  if no_vector {
    out.vector = false;
  }
  options.phases = out;

  // Cache/output tuning (optional, ignored by other consumers).

if let Some(cache) = &config.cache {
  if let Some(enabled) = cache.enabled {
    options.cache.enabled = enabled;
  }
  if let Some(force) = cache.force {
    options.cache.force = force;
  }
  if let Some(path) = &cache.path {
    options.cache.path = Some(resolve_config_relative_path(
      project_root,
      config_path,
      path,
    ));
  }
}

if let Some(output) = &config.output {
  if let Some(incremental) = output.incremental {
    options.output.incremental = incremental;
  }
  if let Some(dir) = &output.data_dir {
    options.output.data_dir = Some(resolve_config_relative_path(project_root, config_path, dir));
  }
}

// Default data dir based on store location (nice when store is customized).
if options.output.data_dir.is_none() {
  if let Some(parent) = store_path.parent() {
    options.output.data_dir = Some(parent.to_path_buf());
  }
}

if !options.phases.vector {
  return Ok((options, None));
}

let vector = config
  .vector
  .as_ref()
  .ok_or_else(|| anyhow::anyhow!("vector config is required for semantic search"))?;
let provider = vector
  .provider
  .as_ref()
  .ok_or_else(|| anyhow::anyhow!("vector.provider is required for semantic search"))?;

if let Some(kind) = &provider.kind {
  if kind != "http" {
    anyhow::bail!("unsupported vector provider kind: {kind}");
  }
}

let api_key = provider
  .api_key
  .clone()
  .filter(|value| !value.trim().is_empty())
  .or_else(|| std::env::var("OPENAI_API_KEY").ok());

  let mut http =
    HttpEmbeddingConfig::new(provider.base_url.clone(), api_key, provider.model.clone());
  http.dimension = provider.dimension;
  if let Some(timeout) = provider.timeout_ms {
    http.timeout = Some(Duration::from_millis(timeout));
  }
  let http_provider = HttpEmbeddingsProvider::new(http)?;

  if let Some(batch_size) = vector.batch_size {
    options.vector.batch_size = batch_size;
  }
  if let Some(concurrency) = vector.concurrency {
    options.vector.concurrency = concurrency;
  }

  // Store chunk JSON to allow future UX improvements without file IO.
  options.vector.include_chunk = true;

  let embeddings_provider: std::sync::Arc<dyn EmbeddingsProvider> =
    std::sync::Arc::new(http_provider);
  options.vector_provider = Some(std::sync::Arc::clone(&embeddings_provider));
  Ok((options, Some(embeddings_provider)))
}

fn resolve_config_relative_path(
  project_root: &Path,
  _config_path: Option<&Path>,
  value: &str,
) -> PathBuf {
  let p = PathBuf::from(value);
  if p.is_absolute() {
    return p;
  }
  // Resolve relative paths against projectRoot, matching other bindings.
  project_root.join(p)
}

