fn now_millis() -> i128 {
  std::time::SystemTime::now()
    .duration_since(std::time::UNIX_EPOCH)
    .map(|d| d.as_millis() as i128)
    .unwrap_or(0)
}

fn emit_watch_event(json: bool, event: &str, store_path: &Path, message: &str) {
  if json {
    let payload = serde_json::json!({
      "event": event,
      "storePath": store_path.to_string_lossy(),
      "message": message,
      "timestampMs": now_millis(),
    });
    println!("{payload}");
  } else {
    let ansi = Ansi::new(std::io::stderr().is_terminal());
    let now = time::OffsetDateTime::now_local().unwrap_or_else(|_| time::OffsetDateTime::now_utc());
    let time_str = format!("{:02}:{:02}:{:02}", now.hour(), now.minute(), now.second());
    let timestamp = ansi.dim(&format!("[{time_str}]"));

    let (icon, colored_msg) = match event {
      "index_start" => {
        let icon = if ansi.enabled { "▶" } else { "[START]" };
        (ansi.cyan(icon), message.to_string())
      }
      "index_complete" => (ansi.check(), ansi.green(message)),
      "error" => (ansi.cross(), ansi.red(message)),
      "stopping" => {
        let icon = if ansi.enabled { "◼" } else { "[STOP]" };
        (ansi.yellow(icon), ansi.yellow(message))
      }
      _ => (ansi.info(), message.to_string()),
    };
    eprintln!("{timestamp} {icon} {colored_msg}");
  }
}

fn inject_search_vector_overrides(
  search: &SearchArgs,
  config: &mut JsonConfig,
) -> Option<JsonHttpVectorProvider> {
  if config
    .vector
    .as_ref()
    .and_then(|v| v.provider.as_ref())
    .is_some()
  {
    return None;
  }

  let env_key = std::env::var("OPENAI_API_KEY").ok();
  let api_key = search
    .vector_api_key
    .clone()
    .filter(|v| !v.trim().is_empty())
    .or(env_key);

  if search.vector_base_url.is_none()
    && search.vector_model.is_none()
    && api_key.is_none()
    && search.vector_dimension.is_none()
    && search.vector_timeout_ms.is_none()
  {
    return None;
  }

  Some(JsonHttpVectorProvider {
    kind: Some("http".to_string()),
    base_url: search
      .vector_base_url
      .clone()
      .unwrap_or_else(|| "https://api.openai.com/v1".to_string()),
    model: search
      .vector_model
      .clone()
      .unwrap_or_else(|| "text-embedding-3-small".to_string()),
    api_key,
    dimension: search.vector_dimension,
    timeout_ms: search.vector_timeout_ms,
  })
}

fn ensure_vector_config(config: &mut JsonConfig, provider: JsonHttpVectorProvider) {
  if config.vector.is_none() {
    config.vector = Some(JsonVector {
      provider: Some(provider),
      batch_size: None,
      concurrency: None,
    });
    return;
  }
  if let Some(vector) = config.vector.as_mut() {
    if vector.provider.is_none() {
      vector.provider = Some(provider);
    }
  }
}

fn index_to_kitedb(
  options: IndexOptions,
  store_path: &Path,
  checkpoint_on_finish: bool,
  checkpoint_threshold: f64,
) -> anyhow::Result<()> {
  let mut sink = KiteDbIndexSink::new_with_checkpoint_policy(
    store_path.to_path_buf(),
    false,
    checkpoint_on_finish,
    checkpoint_threshold,
  );
  let engine = IndexEngine::new(options);
  let cancel = CancelToken::new();
  if let Err(err) = engine.run(&mut sink, &cancel) {
    let _ = sink.abort();
    return Err(err.into());
  }
  sink.finish().map_err(|e| anyhow::anyhow!(e.to_string()))?;
  Ok(())
}

fn read_range_json(range_json: &Option<String>) -> Option<Range> {
  let raw = range_json.as_ref()?;
  serde_json::from_str::<Range>(raw).ok()
}

fn range_span(range: &Range) -> (u32, u32) {
  let start = range.start.row;
  let end = range.end.row;
  (start, end.saturating_sub(start))
}

fn best_candidate(candidates: &[KiteGraphNeighbor]) -> Option<&KiteGraphNeighbor> {
  candidates.iter().min_by(|a, b| {
    // Prefer non-file nodes with a file_path.
    let a_file = a.kind.as_deref() == Some("file");
    let b_file = b.kind.as_deref() == Some("file");
    a_file
      .cmp(&b_file)
      .then_with(|| a.file_path.is_none().cmp(&b.file_path.is_none()))
      .then_with(|| {
        let a_span = read_range_json(&a.range_json)
          .map(|r| range_span(&r).1)
          .unwrap_or(u32::MAX);
        let b_span = read_range_json(&b.range_json)
          .map(|r| range_span(&r).1)
          .unwrap_or(u32::MAX);
        a_span.cmp(&b_span)
      })
      .then_with(|| a.id.cmp(&b.id))
  })
}

