fn print_main_help(ansi: Ansi) {
  println!();
  println!(
    "  {} {}",
    ansi.bold_cyan("ci"),
    ansi.dim(&format!("v{VERSION}"))
  );
  println!("  {}", ansi.dim("Local Argus Search CLI (pure Rust)"));
  println!();

  // Usage
  println!("{}", ansi.bold_underline("USAGE"));
  println!(
    "  {} {} {}",
    ansi.bold_cyan("ci"),
    ansi.yellow("<command>"),
    ansi.dim("[options]")
  );
  println!();

  // Commands
  println!("{}", ansi.bold_underline("COMMANDS"));
  for cmd in COMMANDS {
    println!(
      "  {}  {}",
      ansi.yellow(&format!("{:14}", cmd.name)),
      ansi.dim(cmd.description)
    );
  }
  println!();

  // Options
  println!("{}", ansi.bold_underline("OPTIONS"));
  print_options(COMMON_OPTIONS, ansi);
  println!();

  // Footer
  println!(
    "{}",
    ansi.dim(&format!(
      "Run {} for command-specific help",
      ansi.bold_cyan("ci help <command>")
    ))
  );
  println!();
}

fn print_command_help(command: &str, ansi: Ansi) {
  match command {
    "init" => print_init_help(ansi),
    "watch" => print_watch_help(ansi),
    "search" => print_search_help(ansi),
    "trace" => print_trace_help(ansi),
    "doctor" => print_doctor_help(ansi),
    "completions" => print_completions_help(ansi),
    "man" => print_man_help(ansi),
    _ => {
      eprintln!("{} Unknown command: {}", ansi.cross(), ansi.red(command));
      eprintln!();
      eprintln!(
        "{}",
        ansi.dim(&format!(
          "Run {} for available commands",
          ansi.bold_cyan("ci help")
        ))
      );
    }
  }
}

