fn print_options(options: &[HelpOption], ansi: Ansi) {
  for opt in options {
    let flags = if let Some(short) = opt.short {
      format!("-{}, --{}", short, opt.long)
    } else {
      format!("    --{}", opt.long)
    };
    let visible_len = flags.len() + opt.value.map(|v| v.len() + 1).unwrap_or(0);
    let flags_with_value = if let Some(value) = opt.value {
      format!("{} {}", flags, ansi.dim(value))
    } else {
      flags
    };
    let padding = if visible_len < 28 {
      28 - visible_len
    } else {
      1
    };
    println!(
      "  {}{}{}",
      ansi.cyan(&flags_with_value),
      " ".repeat(padding),
      ansi.dim(opt.description)
    );
  }
}

fn resolve_trace_node_id(
  store: &KiteCodeStore,
  node_id: Option<&str>,
  name: Option<&str>,
) -> anyhow::Result<String> {
  if let Some(node_id) = node_id {
    return Ok(node_id.to_string());
  }

  let Some(name) = name else {
    anyhow::bail!("trace requires a name or --node-id");
  };

  let candidates = store.find_nodes_by_name(name, 50)?;
  if candidates.is_empty() {
    anyhow::bail!("no indexed nodes found with name {}", name);
  }

  if let Some(best) = best_candidate(&candidates) {
    Ok(best.id.clone())
  } else {
    anyhow::bail!("failed to pick a candidate node for {}", name);
  }
}

fn print_search_impact(
  hits: &[KiteSearchHit],
  impact_by_chunk_id: &HashMap<String, Vec<KiteImpactHit>>,
  max_depth: usize,
  ansi: Ansi,
) {
  println!();
  println!(
    "{} {}",
    ansi.bold_underline("IMPACT"),
    ansi.dim(&format!("(transitive callers, max depth {max_depth})"))
  );

  for hit in hits {
    println!();
    println!("{}", ansi.bold_cyan(&hit.chunk_id));
    let impact = impact_by_chunk_id
      .get(&hit.chunk_id)
      .cloned()
      .unwrap_or_default();
    if impact.is_empty() {
      println!("  {}", ansi.dim("(no callers found)"));
      continue;
    }
    for item in impact {
      let depth = ansi.yellow(&format!("d{}", item.depth));
      let id = ansi.magenta(&item.node.id);
      let name = item
        .node
        .name
        .as_deref()
        .map(|n| format!("  {}", ansi.green(n)))
        .unwrap_or_default();
      let file = item
        .node
        .file_path
        .as_deref()
        .map(|f| format!("  {}", ansi.blue(f)))
        .unwrap_or_default();
      println!("  {depth}  {id}{name}{file}");
    }
  }
}

fn print_search_hits(
  project_root: &Path,
  hits: &[KiteSearchHit],
  context: usize,
  ansi: Ansi,
) -> anyhow::Result<()> {
  // Header
  if hits.is_empty() {
    println!();
    println!("{}", ansi.yellow("No matches found"));
    println!();
    return Ok(());
  }

  println!();
  println!(
    "{} {}",
    ansi.bold_underline("SEARCH RESULTS"),
    ansi.dim(&format!("({} matches)", hits.len()))
  );
  println!();

  for (idx, hit) in hits.iter().enumerate() {
    let file_path = hit.file_path.as_deref().unwrap_or("<unknown>");
    let rank = ansi.bold_yellow(&format!("{:02}", idx + 1));
    let score = ansi.green(&format!("{:.4}", hit.score));
    let chunk = ansi.cyan(&hit.chunk_id);

    println!("{rank}  {score}  {chunk}");

    if let Some(range) = read_range_json(&hit.range_json) {
      let start_line = range.start.row as usize + 1;
      let end_line = range.end.row as usize + 1;
      let file_info = format!("{file_path}:{start_line}-{end_line}");
      println!("    {} {}", ansi.dim("└─"), ansi.blue(&file_info));

      if hit.file_path.is_some() {
        let snippet = open_snippet(project_root, file_path, &range, context, ansi)?;
        if !snippet.is_empty() {
          let separator = if ansi.enabled {
            "─".repeat(60)
          } else {
            "-".repeat(60)
          };
          println!("{}", ansi.dim(&separator));
          println!("{snippet}");
          println!();
        }
      }
    } else {
      println!("    {} {}", ansi.dim("└─"), ansi.blue(file_path));
    }
  }
  Ok(())
}

/// Max lines to show in a snippet (to avoid huge outputs)
const SNIPPET_MAX_LINES: usize = 15;
/// Max characters to show per snippet line in human-readable output.
const SNIPPET_MAX_LINE_CHARS: usize = 240;

fn open_snippet(
  project_root: &Path,
  rel_path: &str,
  range: &Range,
  context: usize,
  ansi: Ansi,
) -> anyhow::Result<String> {
  let rel =
    normalize_relative_path_within_root(project_root, rel_path).map_err(anyhow::Error::msg)?;
  let abs =
    resolve_path_within_root(project_root, Path::new(&rel), "path").map_err(anyhow::Error::msg)?;
  let content = fs::read_to_string(&abs).unwrap_or_default();
  let lines: Vec<&str> = content.split('\n').collect();

  let start = range.start.row as isize;
  let end = range.end.row as isize;
  let ctx = context as isize;

  let from = (start - ctx).max(0) as usize;
  let to = (end + ctx + 1).min(lines.len() as isize).max(0) as usize;
  if from >= to || from >= lines.len() {
    return Ok(String::new());
  }

  let total_lines = to - from;
  let truncated = total_lines > SNIPPET_MAX_LINES;
  let display_to = if truncated {
    from + SNIPPET_MAX_LINES
  } else {
    to
  };

  let mut out = String::new();
  for (idx, line) in lines[from..display_to].iter().enumerate() {
    let line_no = from + idx + 1;
    let rendered_line = truncate_line_for_display(line, SNIPPET_MAX_LINE_CHARS);
    out.push_str(&format!(
      "{} | {rendered_line}\n",
      ansi.dim(&format!("{line_no:>5}"))
    ));
  }

  if truncated {
    let remaining = total_lines - SNIPPET_MAX_LINES;
    out.push_str(&ansi.dim(&format!("      ... ({remaining} more lines)\n")));
  }

  Ok(out.trim_end().to_string())
}

fn truncate_line_for_display(value: &str, max_chars: usize) -> String {
  if max_chars == 0 {
    return String::new();
  }
  let mut out = String::new();
  let mut chars = value.chars();
  for _ in 0..max_chars {
    if let Some(ch) = chars.next() {
      out.push(ch);
    } else {
      return out;
    }
  }

  if chars.next().is_some() {
    if max_chars == 1 {
      "…".to_string()
    } else {
      out.pop();
      out.push('…');
      out
    }
  } else {
    out
  }
}

fn open_snippet_raw(
  project_root: &Path,
  rel_path: &str,
  range: &Range,
  context: usize,
) -> anyhow::Result<String> {
  let rel =
    normalize_relative_path_within_root(project_root, rel_path).map_err(anyhow::Error::msg)?;
  let abs =
    resolve_path_within_root(project_root, Path::new(&rel), "path").map_err(anyhow::Error::msg)?;
  let content = fs::read_to_string(&abs).unwrap_or_default();
  let lines: Vec<&str> = content.split('\n').collect();

  let start = range.start.row as isize;
  let end = range.end.row as isize;
  let ctx = context as isize;

  let from = (start - ctx).max(0) as usize;
  let to = (end + ctx + 1).min(lines.len() as isize).max(0) as usize;
  if from >= to || from >= lines.len() {
    return Ok(String::new());
  }

  Ok(lines[from..to].join("\n"))
}

fn truncate_chars(value: &str, max_chars: usize) -> String {
  if max_chars == 0 {
    return String::new();
  }
  value.chars().take(max_chars).collect::<String>()
}

fn hydrate_search_hits_content(
  project_root: &Path,
  store: &KiteCodeStore,
  hits: &mut [KiteSearchHit],
  context: usize,
  max_chars: usize,
) {
  let cap = max_chars.min(200_000);
  for hit in hits.iter_mut() {
    let content = store
      .chunk_content_by_id(&hit.chunk_id)
      .or_else(|| {
        let file_path = hit.file_path.as_deref()?;
        let range = read_range_json(&hit.range_json)?;
        open_snippet_raw(project_root, file_path, &range, context).ok()
      })
      .map(|value| truncate_chars(&value, cap));
    hit.content = content;
  }
}

fn run_doctor(
  args: DoctorArgs,
  config: Option<PathBuf>,
  project_root_override: Option<PathBuf>,
  store: Option<PathBuf>,
) -> anyhow::Result<()> {
  let config_path = resolve_config_path(config)?;
  let mut checks = Vec::new();
  let mut fixes = Vec::new();
  let mut cfg = JsonConfig::default();
  let mut config_loaded = false;

  if let Some(path) = config_path.as_deref() {
    match load_config(path) {
      Ok(loaded) => {
        cfg = loaded;
        config_loaded = true;
        checks.push(CheckResult::ok(
          "config",
          format!("loaded {}", path.to_string_lossy()),
        ));
      }
      Err(err) => {
        checks.push(CheckResult::error("config", format!("{err}")));
      }
    }
  } else {
    checks.push(CheckResult::warn("config", "not found (run: ci init)"));
  }

  let project_root = resolve_project_root(config_path.as_deref(), &cfg, project_root_override);
  let store_path = resolve_store_path(&project_root, store)?;

if args.fix {
  if project_root.exists() && project_root.is_dir() {
    let ci_dir = project_root.join(".argus-search");
    if !ci_dir.exists() {
      if let Err(err) = fs::create_dir_all(&ci_dir) {
        checks.push(CheckResult::warn(
          "fix",
          format!("failed to create {}: {err}", ci_dir.to_string_lossy()),
        ));
      } else {
        fixes.push(format!("created {}", ci_dir.to_string_lossy()));
      }
    }

    if let Err(err) = ensure_gitignore(&project_root) {
      checks.push(CheckResult::warn(
        "fix",
        format!("failed to update .gitignore: {err}"),
      ));
    } else {
      fixes.push("ensured .gitignore includes .argus-search/".to_string());
    }
  }

  if let Some(parent) = store_path.parent() {
    if !parent.exists() {
      if let Err(err) = fs::create_dir_all(parent) {
        checks.push(CheckResult::warn(
          "fix",
          format!(
            "failed to create store dir {}: {err}",
            parent.to_string_lossy()
          ),
        ));
      } else {
        fixes.push(format!("created store dir {}", parent.to_string_lossy()));
      }
    }
  }
}

if project_root.exists() {
  if project_root.is_dir() {
    checks.push(CheckResult::ok(
      "projectRoot",
      project_root.to_string_lossy(),
    ));
  } else {
    checks.push(CheckResult::error(
      "projectRoot",
      format!("not a directory: {}", project_root.to_string_lossy()),
    ));
  }
} else {
  checks.push(CheckResult::error(
    "projectRoot",
