let config_path = resolve_config_path(config)?;
let mut cfg = if let Some(path) = config_path.as_deref() {
  load_config(path)?
} else {
  JsonConfig::default()
};
let project_root = resolve_project_root(config_path.as_deref(), &cfg, project_root_override);
let store_path = resolve_store_path(&project_root, store)?;

match command {
  Command::Watch(watch) => {
    if config_path.is_none() {
      anyhow::bail!("watch requires a config file (run: ci init)");
    }

    // Ensure store directory exists.
    if let Some(parent) = store_path.parent() {
      fs::create_dir_all(parent)?;
    }

    let (options, _provider) = build_index_options(
      &project_root,
      config_path.as_deref(),
      &cfg,
      &store_path,
      watch.no_vector,
      watch.phases.as_deref(),
    )?;

    let mut checkpoint_on_finish = cfg
      .output
      .as_ref()
      .and_then(|out| out.checkpoint_on_finish)
      .unwrap_or(true);
    if watch.no_checkpoint_warmup {
      checkpoint_on_finish = false;
    }

    let mut checkpoint_threshold = cfg
      .output
      .as_ref()
      .and_then(|out| out.checkpoint_threshold)
      .unwrap_or(0.0);
    if let Some(override_threshold) = watch.checkpoint_threshold {
      checkpoint_threshold = override_threshold;
    }
    if !checkpoint_threshold.is_finite() {
      anyhow::bail!("checkpoint threshold must be finite");
    }
    checkpoint_threshold = checkpoint_threshold.clamp(0.0, 1.0);

let mut last_seen: HashMap<PathBuf, (u128, u64)> = HashMap::new();
let mut last_index = None::<Instant>;

let cancel = CancelToken::new();
loop {
  let files = match argus_search::core::parse::engine::discover_files(
    &project_root,
    &options.inputs,
    &cancel,
  ) {
    Ok(found) => found,
    Err(err) => {
      emit_watch_event(
        watch.json,
        "error",
        &store_path,
        &format!("Failed to discover files: {err}"),
      );
      sleep(Duration::from_millis(watch.poll_ms));
      continue;
    }
  };

  let mut changed = false;
  let mut current: HashMap<PathBuf, (u128, u64)> = HashMap::new();
  for file in files {
    if let Some(sig) = signature_mtime_len(&file) {
      if last_seen.get(&file).copied() != Some(sig) {
        changed = true;
      }
      current.insert(file, sig);
    }
  }
  if !last_seen.is_empty() {
    for key in last_seen.keys() {
      if !current.contains_key(key) {
        changed = true;
        break;
      }
    }
  } else {
    // First loop: always index.
    changed = true;
  }
  last_seen = current;

    if changed {
      if let Some(t) = last_index {
        if t.elapsed() < Duration::from_millis(watch.debounce_ms) {
          sleep(Duration::from_millis(watch.poll_ms));
          continue;
        }
      }
      emit_watch_event(
        watch.json,
        "index_start",
        &store_path,
        &format!("Indexing into {} ...", store_path.to_string_lossy()),
      );
      index_to_kitedb(
        options.clone(),
        &store_path,
        checkpoint_on_finish,
        checkpoint_threshold,
      )?;
      last_index = Some(Instant::now());
      emit_watch_event(watch.json, "index_complete", &store_path, "Index complete.");
      if watch.once {
        break;
      }
    }

    sleep(Duration::from_millis(watch.poll_ms));
  }

  Ok(())
}
