} from "@/components/observability/utils"
import { isPageVisible, shouldSkipPollingRequest } from "@/components/observability/polling"

const AUTO_REFRESH_MS = 8_000
const HEALTH_REQUEST_KEY = "indexing-health"

const buildIssueHref = (issue: ObservabilityHealthIssue) => {
  const params = new URLSearchParams()

  if (issue.level) {
    params.set("level", issue.level)
  }
  if (issue.event) {
    params.set("event", issue.event)
  }
  if (issue.path) {
    params.set("path", issue.path)
  }
  if (issue.requestId) {
    params.set("requestId", issue.requestId)
  }

  if (issue.lastSeenAt) {
    const sinceTimestamp = new Date(issue.lastSeenAt).getTime() - 6 * 60 * 60_000
    const sinceInput = toLocalDateTimeInput(new Date(sinceTimestamp).toISOString())
    if (sinceInput) {
      params.set("since", sinceInput)
    }
  }

  const query = params.toString()
  return query ? `/observability/logs?${query}` : "/observability/logs"
}

export default function ObservabilityIndexingHealthPage() {
  const [health, setHealth] = useState<ObservabilityIndexingHealthPayload | null>(null)
  const [isLoadingHealth, setIsLoadingHealth] = useState(false)
  const [healthErrorMessage, setHealthErrorMessage] = useState("")
  const [autoRefresh, setAutoRefresh] = useState(true)
  const inFlightRequestRef = useRef<AbortController | null>(null)
  const inFlightRequestKeyRef = useRef<string | null>(null)

  const loadHealth = useCallback(async (opts: {
    quiet?: boolean
    skipIfInFlightDuplicate?: boolean
  } = {}) => {
    const quiet = opts.quiet ?? false
    let requestController: AbortController | null = null
    if (!quiet) {
      setIsLoadingHealth(true)
    }
    setHealthErrorMessage("")

  try {
    if (
      opts.skipIfInFlightDuplicate &&
      shouldSkipPollingRequest({
        isVisible: isPageVisible(),
        inFlightRequestKey: inFlightRequestKeyRef.current,
      })
    ) {
      return
    }

    if (inFlightRequestRef.current) {
      inFlightRequestRef.current.abort()
    }

    const controller = new AbortController()
    requestController = controller
    inFlightRequestRef.current = controller
    inFlightRequestKeyRef.current = HEALTH_REQUEST_KEY
    const response = await fetch("/api/observability/indexing-health", {
      method: "GET",
      headers: {
        "content-type": "application/json",
      },
      signal: controller.signal,
    })
    const parsedPayload = await parseJsonResponse(response)
    const payload = parsedPayload.ok ? parsedPayload.value : null
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, "Failed to load indexing health."))
    }
    setHealth(payload as ObservabilityIndexingHealthPayload)
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      return
    }
    setHealthErrorMessage(error instanceof Error ? error.message : "Failed to load indexing health.")
  } finally {
    if (requestController && inFlightRequestRef.current === requestController) {
      inFlightRequestRef.current = null
      inFlightRequestKeyRef.current = null
    }
    if (!quiet) {
      setIsLoadingHealth(false)
    }
  }
}, [])

useEffect(() => {
  if (!autoRefresh) {
    return
  }

  const timer = window.setInterval(() => {
    if (!isPageVisible()) {
      return
    }
    void loadHealth({ quiet: true, skipIfInFlightDuplicate: true })
  }, AUTO_REFRESH_MS)

  return () => {
    window.clearInterval(timer)
  }
}, [autoRefresh, loadHealth])

useEffect(() => {
  return () => {
    inFlightRequestRef.current?.abort()
    inFlightRequestRef.current = null
    inFlightRequestKeyRef.current = null
  }
}, [])

useEffect(() => {
  void loadHealth()
}, [loadHealth])

const issueRows = useMemo(
  () => health?.issues ?? [],
  [health],
)

return (
  <Card>
    <CardHeader className="space-y-3">
      <div className="flex items-center gap-3">
        <div className="flex size-8 items-center justify-center rounded-lg bg-rose-500/10">
          <IconHeartbeat className="size-4 text-rose-500" />
        </div>
        <div className="min-w-0">
          <CardTitle className="leading-none">Indexing Health</CardTitle>
          <CardDescription className="mt-1">
            Fast signal from existing logs, runs, and jobs. No rollup table.
          </CardDescription>
        </div>
      </div>
    </CardHeader>
    <CardContent className="space-y-4">

