import OverviewContent from "@/content/overview.mdx"
import WritingDocsContent from "@/content/writing-docs.mdx"
import { mdxComponents } from "@/lib/mdx-components"

const normalizeBasePath = (value: string) => {
  if (!value || value === "/") {
    return "/"
  }

  return value.endsWith("/") ? value.slice(0, -1) : value
}

const rootRoute = createRootRoute({
  component: () => (
    <DocsShell>
      <Outlet />
    </DocsShell>
  ),
})

const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/",
  component: () => <OverviewContent components={mdxComponents} />,
})

const gettingStartedRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/getting-started",
  component: () => <GettingStartedContent components={mdxComponents} />,
})

const deploymentRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/deployment",
  component: () => <DeploymentContent components={mdxComponents} />,
})

const writingDocsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/writing-docs",
  component: () => <WritingDocsContent components={mdxComponents} />,
})

const routeTree = rootRoute.addChildren([
  indexRoute,
  gettingStartedRoute,
  deploymentRoute,
  writingDocsRoute,
])

