const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const toReviewSide = (value: unknown): AiReviewFinding["side"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (
    normalized === "deletions" ||
    normalized === "deletion" ||
    normalized === "removed" ||
    normalized === "left"
  ) {
    return "deletions"
  }
  return "additions"
}

const toReviewSeverity = (value: unknown): AiReviewFinding["severity"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (normalized === "high") {
    return "high"
  }
  if (normalized === "medium" || normalized === "med") {
    return "med"
  }
  return "low"
}

const toConfidence = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return 0.7
  }

  return Math.max(0, Math.min(1, value))
}

const toEvidence = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

const sanitizeAssistantContent = (content: string) => {
  const trimmed = content.trim()
  const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i)
  const candidate = (fenced?.[1] ?? trimmed).trim()
  const firstBrace = candidate.indexOf("{")
  const lastBrace = candidate.lastIndexOf("}")

  if (firstBrace >= 0 && lastBrace > firstBrace) {
    return candidate.slice(firstBrace, lastBrace + 1)
  }

  return candidate
}

const parseFindings = (content: unknown): AiReviewFinding[] => {
  if (!isNonEmptyString(content)) {
    return []
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(sanitizeAssistantContent(content))
  } catch {
    return []
  }

  const rawFindings = (() => {
    if (Array.isArray(parsed)) {
      return parsed
    }
    if (parsed && typeof parsed === "object") {
      const maybeFindings = (parsed as { findings?: unknown }).findings
      if (Array.isArray(maybeFindings)) {
        return maybeFindings
      }
    }
    return []
  })()

  const normalized = rawFindings
    .map<AiReviewFinding | null>((value) => {
      if (!value || typeof value !== "object") {
        return null
      }

      const finding = value as Record<string, unknown>
      const line = Number(finding.line)
      const file = String(finding.file ?? "").trim()
      const title = String(finding.title ?? "").trim()
      const body = String(finding.body ?? finding.explanation ?? "").trim()

      if (!file || !title || !body || !Number.isFinite(line) || line < 1) {
        return null
      }

      return {
        file,
        line: Math.floor(line),
        side: toReviewSide(finding.side),
        severity: toReviewSeverity(finding.severity),
        title,
        body,
        confidence: toConfidence(finding.confidence),
        evidence: toEvidence(finding.evidence),
      } satisfies AiReviewFinding
    })
    .filter((finding): finding is AiReviewFinding => finding !== null)

  return normalized.slice(0, MAX_FINDINGS)
}

const normalizeAssistantResponseText = (content: unknown) => {
  if (typeof content === "string") {
    return content
  }

  if (!Array.isArray(content)) {
    return ""
  }

  const textBlocks = content
    .map((chunk) => {
      if (!chunk || typeof chunk !== "object") {
        return ""
      }
      const typedChunk = chunk as { type?: unknown; text?: unknown }
      if (typedChunk.type === "text" && typeof typedChunk.text === "string") {
        return typedChunk.text
      }
      return ""
    })
    .filter((part) => part.length > 0)
  return textBlocks.join("\n")
}

const toToolCallSummary = (value: unknown) => {
  if (!Array.isArray(value)) {
    return {
      count: 0,
      names: [] as string[],
    }
  }
  const names = value
    .map((item) => {
      if (!item || typeof item !== "object") {
        return ""
      }
      const fn = (item as { function?: unknown }).function
      if (!fn || typeof fn !== "object") {
        return ""
      }
      return String((fn as { name?: unknown }).name ?? "").trim()
    })
    .filter((name) => name.length > 0)

  return {
    count: value.length,
    names: Array.from(new Set(names)).slice(0, 8),
  }
}

const extractFilePathsFromPatch = (patchText: string) => {
  const matches = Array.from(patchText.matchAll(/^diff --git a\/(.+?) b\/(.+)$/gm))
  const paths = matches
    .map((match) => normalizePatchPath(match[2] ?? match[1] ?? ""))
    .filter((path) => path.length > 0)
  return Array.from(new Set(paths))
}

const splitPatchIntoFileChunks = (patchText: string) => {
  const splitByFile = patchText.split(/^diff --git /m)
  if (splitByFile.length <= 1) {
    return []
  }

  const metadataPrefix = splitByFile[0].trim()

  return splitByFile
    .slice(1)
    .map((part, index) => {
      const chunk = `diff --git ${part}`.trim()
      if (!chunk) {
        return ""
      }
      if (index === 0 && metadataPrefix) {
        return `${metadataPrefix}\n${chunk}`
      }
      return chunk
    })
    .filter((chunk): chunk is string => chunk.length > 0)
}

export const buildReviewBatches = (patchText: string): ReviewBatch[] => {
  const patchChunks = splitPatchIntoFileChunks(patchText)
  if (patchChunks.length === 0) {
    return [
      {
        patch: patchText,
        files: extractFilePathsFromPatch(patchText),
      },
    ]
  }

  const groupedChunks: string[][] = []
  let currentBatch: string[] = []
  let currentBatchCharLength = 0

  for (const chunk of patchChunks) {
    const separatorCharLength = currentBatch.length > 0 ? 2 : 0
    const candidateLength = currentBatchCharLength + separatorCharLength + chunk.length
    const exceedsFileLimit = currentBatch.length >= REVIEW_BATCH_FILE_COUNT
    const exceedsCharLimit = candidateLength > REVIEW_BATCH_MAX_PATCH_CHARS

    if (currentBatch.length > 0 && (exceedsFileLimit || exceedsCharLimit)) {
      groupedChunks.push(currentBatch)
      currentBatch = [chunk]
      currentBatchCharLength = chunk.length
      continue
    }

    currentBatch.push(chunk)
    currentBatchCharLength = candidateLength
  }

  if (currentBatch.length > 0) {
    groupedChunks.push(currentBatch)
  }

  return groupedChunks.map((chunks) => {
    const joinedPatch = chunks.join("\n\n")
    return {
      patch: joinedPatch,
      files: extractFilePathsFromPatch(joinedPatch),
    }
  })
}

export const dedupeFindings = (findings: AiReviewFinding[]) => {
  const deduped = new Map<string, AiReviewFinding>()
  for (const finding of findings) {
    const normalizedFile = normalizePatchPath(finding.file)

const key = buildReviewCommentFeedbackKey({
  file: normalizedFile,
  side: finding.side,
  line: finding.line,
  title: finding.title,
})
const normalizedFinding = {
  ...finding,
  file: normalizedFile,
  personas: Array.isArray(finding.personas)
    ? Array.from(
      new Set(
        finding.personas
          .map((entry) => normalizeReviewPersona(entry))
          .filter((entry) => entry.length > 0),
      ),
    )
    : finding.persona
      ? [normalizeReviewPersona(finding.persona)]
      : [],
}
const current = deduped.get(key)
if (!current) {
  deduped.set(key, normalizedFinding)
  continue
}

const mergedPersonas = Array.from(
  new Set([
    ...(Array.isArray(current.personas) ? current.personas : []),
    ...(Array.isArray(normalizedFinding.personas) ? normalizedFinding.personas : []),
  ]),
)

if (normalizedFinding.confidence > current.confidence) {
  deduped.set(key, {
    ...normalizedFinding,
    personas: mergedPersonas,
  })
  continue
}

    if (normalizedFinding.confidence === current.confidence) {
      const currentEvidenceLength = (current.evidence ?? "").trim().length
      const nextEvidenceLength = (normalizedFinding.evidence ?? "").trim().length
      if (nextEvidenceLength > currentEvidenceLength) {
        deduped.set(key, {
          ...normalizedFinding,
          personas: mergedPersonas,
        })
      } else {
        deduped.set(key, {
          ...current,
          personas: mergedPersonas,
        })
      }
    } else {
      deduped.set(key, {
        ...current,
        personas: mergedPersonas,
      })
    }
  }
  return Array.from(deduped.values())
}

export const buildReviewSummary = (findings: AiReviewFinding[]) => {
  if (findings.length === 0) {
    return "AI review complete. No findings."
  }

  const highCount = findings.filter((finding) => finding.severity === "high").length
  const medCount = findings.filter((finding) => finding.severity === "med").length
  const lowCount = findings.length - highCount - medCount
  return `AI review complete: ${findings.length} findings (${highCount} high, ${medCount} med, ${lowCount} low).`
}

