const toPreview = (value: string, maxChars: number) => {
  if (value.length <= maxChars) {
    return {
      text: value,
      truncated: false,
    }
  }
  return {
    text: value.slice(0, maxChars),
    truncated: true,
  }
}

const requestReviewBatch = async ({
  patch,
  files,
  batchIndex,
  totalBatches,
  apiUrl,
  model,
  token,
  persona,
  personaTemplate,
}: {
  patch: string
  files: string[]
  batchIndex: number
  totalBatches: number
  apiUrl: string
  model: string
  token: string
  persona: ReviewPersona | null
  personaTemplate: string
}) => {

try {
  const systemPrompt = buildSystemPrompt({
    persona,
    personaTemplate,
  })
  const userPrompt = `Review this patch:\n\n${patch}`
  const requestBody = {
    model,
    temperature: 0.1,
    messages: [
      { role: "system" as const, content: systemPrompt },
      { role: "user" as const, content: userPrompt },
    ],
  }
  const requestBodyJson = JSON.stringify(requestBody)
  const { payload, latencyMs } = await requestChatCompletions<ChatCompletionsResponse>({
    apiUrl,
    token,
    timeoutMs: CHAT_TIMEOUT_MS,
    body: requestBody as unknown as Record<string, unknown>,
  })

  const content = payload.choices?.[0]?.message?.content
  const assistantText = normalizeAssistantResponseText(content)
  const parsedFindings = parseFindings(assistantText)
  const findings = reconcileFindingLinesWithPatch({
    patch,
    findings: parsedFindings,
  })
  const toolCallSummary = toToolCallSummary(payload.choices?.[0]?.message?.tool_calls)
  const usage = extractUsageFromOpenAiCompatiblePayload(payload)
  const provider = resolveLlmProviderLabel(apiUrl)
  const promptPreview = toPreview(userPrompt, MAX_PROMPT_PREVIEW_CHARS)
  const responsePreview = toPreview(assistantText, MAX_RESPONSE_PREVIEW_CHARS)

  return {
    findings,
    metrics: buildLlmMetrics({
      provider,
      model,
      promptTokens: usage.promptTokens,
      completionTokens: usage.completionTokens,
      totalTokens: usage.totalTokens,
      latencyMs,
      requestCount: 1,
    }),

    }
  } catch (error) {
    if (error instanceof LlmProviderTimeoutError) {
      throw new ReviewExecutionError("AI review timed out.", { retryable: true })
    }

    if (error instanceof LlmProviderHttpError) {
      const retryable =
        error.status === 408 ||
        error.status === 409 ||
        error.status === 425 ||
        error.status === 429 ||
        error.status >= 500
      throw new ReviewExecutionError(
        `AI provider request failed (${error.status})${error.providerError ? `: ${error.providerError}` : ""}`,
        { retryable },
      )
    }

    throw new ReviewExecutionError(
      error instanceof Error ? error.message : "AI review request failed.",
      { retryable: true },
    )
  }
}

export const runReviewEngine = async ({
  patch,
  apiUrl,
  model,
  token,
  personaMode,
  persona,
  personaTemplates,
  onProgress,
}: {
  patch: string
  apiUrl: string
  model: string
  token: string
  personaMode?: ReviewPersonaMode
  persona?: ReviewPersona
  personaTemplates?: ReviewPersonaTemplateOverrides
  onProgress?: (update: ReviewEngineProgressUpdate) => Promise<void> | void
}): Promise<ReviewEngineResult> => {
  if (!patch.trim()) {
    throw new ReviewExecutionError("Patch is required.", { retryable: false })
  }
  if (patch.length > MAX_REVIEW_PATCH_CHARS) {
    throw new ReviewExecutionError(
      `Diff too large for AI review. Limit is ${MAX_REVIEW_PATCH_CHARS.toLocaleString()} characters.`,
      { retryable: false },
    )
  }

  const reviewBatches = buildReviewBatches(patch)

const normalizedPersonaMode = normalizeReviewPersonaMode(personaMode)
const normalizedPersona = normalizeReviewPersona(persona)
const normalizedTemplates = normalizeReviewPersonaTemplateOverrides(personaTemplates)

const personaPasses: ReviewPersonaPass[] = (() => {
  if (normalizedPersonaMode === "disabled") {
    return [
      {
        persona: null,
        personaLabel: "disabled",
        template: "",
      },
    ]
  }

  if (normalizedPersonaMode === "multi") {
    return REVIEW_PERSONA_VALUES.map((personaValue) => ({
      persona: personaValue,
      personaLabel: personaValue,
      template: resolveReviewPersonaTemplate({
        persona: personaValue,
        overrides: normalizedTemplates,
      }),
    }))
  }

  return [
    {
      persona: normalizedPersona,
      personaLabel: normalizedPersona,
      template: resolveReviewPersonaTemplate({
        persona: normalizedPersona,
        overrides: normalizedTemplates,
      }),
    },
  ]
})()

const totalBatches = reviewBatches.length * personaPasses.length
const personaExecutionStrategy = resolveReviewPersonaExecutionStrategy(
  normalizedPersonaMode,
)

let progressUpdates = Promise.resolve()
const emitProgress = async (update: ReviewEngineProgressUpdate) => {
  if (!onProgress) {
    return
  }
  progressUpdates = progressUpdates.then(() => onProgress(update))
  await progressUpdates
}

await emitProgress({
  stage: "chunking",
  message: `Queued ${totalBatches} ${totalBatches === 1 ? "batch" : "batches"} for AI analysis.`,
  payload: {
    totalBatches,
    personaMode: normalizedPersonaMode,
    personaPasses: personaPasses.map((pass) => pass.personaLabel),
    personaExecutionStrategy,
  },
})

const reviewedFiles = new Set<string>()
let allFindings: AiReviewFinding[] = []
let llmRequests = 0
let promptTokens = 0
let completionTokens = 0
let totalTokens = 0
let toolCallCount = 0
let latestProvider: string | null = null

let completedBatches = 0
const runPersonaPass = async (personaPass: ReviewPersonaPass, personaIndex: number) => {
  for (let batchIndex = 0; batchIndex < reviewBatches.length; batchIndex += 1) {
    const batch = reviewBatches[batchIndex]
    const globalBatchIndex = personaIndex * reviewBatches.length + batchIndex + 1

completedBatches += 1

allFindings = allFindings.concat(
  batchResult.findings.map((finding) => ({
    ...finding,
    persona: personaPass.persona ?? undefined,
    personas: personaPass.persona ? [personaPass.persona] : [],
  })),
)
for (const file of batch.files) {
  reviewedFiles.add(file)
}

    } catch (error) {
      const message = error instanceof Error ? error.message : "AI batch review failed."
      const retryable = error instanceof ReviewExecutionError ? error.retryable : true
      throw new ReviewExecutionError(message, {
        retryable,
        failedFiles: batch.files,
      })
    }
  }
}

if (personaExecutionStrategy === "parallel" && personaPasses.length > 1) {
  await Promise.all(
    personaPasses.map((personaPass, personaIndex) =>
      runPersonaPass(personaPass, personaIndex),
    ),
  )
} else {
  for (let personaIndex = 0; personaIndex < personaPasses.length; personaIndex += 1) {
    await runPersonaPass(personaPasses[personaIndex], personaIndex)
  }
}

const findings = dedupeFindings(allFindings)
await emitProgress({
  stage: "mapping",
  message: "Consolidating findings across all batches.",
  payload: {
    totalBatches,
    completedBatches: totalBatches,
    currentBatchIndex: totalBatches,
    reviewedFiles: Array.from(reviewedFiles),
    findingsCount: findings.length,
    llmRequests,
    promptTokens,
    completionTokens,
    totalTokens,
    toolCallCount,
    latestProvider,
    latestModel: model,
    personaMode: normalizedPersonaMode,
    persona: normalizedPersonaMode === "single" ? normalizedPersona : null,
    personaPasses: personaPasses.map((pass) => pass.personaLabel),
    personaExecutionStrategy,
  },
})

  return {
    findings,
    summary: buildReviewSummary(findings),
    totalBatches,
    reviewedFiles: Array.from(reviewedFiles),
    metrics: {
      llmRequests,
