import {
  createCipheriv,
  createDecipheriv,
  createHash,
  randomBytes,
  timingSafeEqual,
} from "node:crypto"
import { gitlabEnv } from "@/lib/gitlab/env"

type EncryptedToken = {
  ciphertext: string
  iv: string
  authTag: string
}

const toBase64 = (value: Buffer) => value.toString("base64")

const fromBase64 = (value: string, fieldName: string) => {
  try {
    return Buffer.from(value, "base64")
  } catch {
    throw new Error(`Invalid ${fieldName} encoding.`)
  }
}

export const generateWebhookSecret = () => randomBytes(32).toString("base64url")

export const hashWebhookSecret = (secret: string) =>
  createHash("sha256").update(secret).digest("hex")

export const secureCompare = (left: string, right: string) => {
  const leftBuffer = Buffer.from(left)
  const rightBuffer = Buffer.from(right)
  if (leftBuffer.length !== rightBuffer.length) {
    return false
  }
  return timingSafeEqual(leftBuffer, rightBuffer)
}

export const verifyWebhookSecretHash = (providedSecret: string, storedSecretHash: string) => {
  const providedHash = hashWebhookSecret(providedSecret)
  return secureCompare(providedHash, storedSecretHash)
}

export const encryptGitLabToken = (
  token: string,
  key: Buffer = gitlabEnv.tokenEncryptionKey,
): EncryptedToken => {
  const iv = randomBytes(12)
  const cipher = createCipheriv("aes-256-gcm", key, iv)
  const ciphertext = Buffer.concat([cipher.update(token, "utf8"), cipher.final()])
  const authTag = cipher.getAuthTag()

  return {
    ciphertext: toBase64(ciphertext),
    iv: toBase64(iv),
    authTag: toBase64(authTag),
  }
}

export const decryptGitLabToken = (
  encrypted: EncryptedToken,
  key: Buffer = gitlabEnv.tokenEncryptionKey,
) => {
  const iv = fromBase64(encrypted.iv, "token_iv")
  const ciphertext = fromBase64(encrypted.ciphertext, "token_ciphertext")
  const authTag = fromBase64(encrypted.authTag, "token_auth_tag")

  try {
    const decipher = createDecipheriv("aes-256-gcm", key, iv)
    decipher.setAuthTag(authTag)
    const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()])
    return plaintext.toString("utf8")
  } catch {
    throw new Error("Unable to decrypt GitLab token.")
  }
}

type LogDrainScheduler = {
  clear: (handle: unknown) => void
  set: (callback: () => void, delayMs: number) => unknown
}

type LogDrainBufferOptions<TEvent> = {
  maxBufferSize: number
  batchSize: number
  flushIntervalMs: number
  enabled: boolean
  writeBatch: (batch: TEvent[]) => Promise<void>
  onWriteError?: (error: unknown) => void
  scheduler?: LogDrainScheduler
}

type LogDrainBufferState = {
  queueSize: number
  dropCount: number
  enabled: boolean
  batchSize: number
  flushIntervalMs: number
}

type LogDrainBufferConfig = Partial<Pick<LogDrainBufferState, "enabled" | "batchSize" | "flushIntervalMs">>

export type LogDrainBuffer<TEvent> = {
  push: (event: TEvent) => void
  flush: () => Promise<void>
  configure: (config: LogDrainBufferConfig) => void
  getState: () => LogDrainBufferState
}

const toPositiveInt = (name: string, value: number) => {
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`Invalid ${name}. Expected a positive integer.`)
  }

  return Math.floor(value)
}

export const createLogDrainBuffer = <TEvent>(
  options: LogDrainBufferOptions<TEvent>,
): LogDrainBuffer<TEvent> => {
  const scheduler: LogDrainScheduler = options.scheduler ?? {
    clear: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
    set: (callback, delayMs) => setTimeout(callback, delayMs),
  }

  const maxBufferSize = toPositiveInt("maxBufferSize", options.maxBufferSize)
  let batchSize = toPositiveInt("batchSize", options.batchSize)
  let flushIntervalMs = toPositiveInt("flushIntervalMs", options.flushIntervalMs)

let enabled = options.enabled
let dropCount = 0
const queue: TEvent[] = []
let flushTimer: unknown | null = null
let flushing: Promise<void> | null = null

const scheduleFlush = () => {
  if (!enabled || flushTimer) {
    return
  }

  flushTimer = scheduler.set(() => {
    flushTimer = null
    void flush()
  }, flushIntervalMs)
}

const flush = async () => {
  if (flushTimer) {
    scheduler.clear(flushTimer)
    flushTimer = null
  }

  if (!enabled) {
    return Promise.resolve()
  }

  if (flushing) {
    return flushing
  }

  // Reuse one in-flight flush so concurrent callers cannot interleave writes.
  flushing = (async () => {
    while (queue.length > 0) {
      const batch = queue.splice(0, batchSize)
      if (batch.length === 0) {
        continue
      }

      try {
        await options.writeBatch(batch)
      } catch (error) {
        options.onWriteError?.(error)
      }
    }
  })().finally(() => {
    flushing = null
    if (queue.length > 0) {
      scheduleFlush()
    }
  })

  return flushing
}

const push = (event: TEvent) => {
  if (!enabled) {
    return
  }

  if (queue.length >= maxBufferSize) {
    queue.shift()
    dropCount += 1
  }

  queue.push(event)

  if (queue.length >= batchSize) {
    void flush()
    return
  }

  scheduleFlush()
}

  const configure = (config: LogDrainBufferConfig) => {
    if (typeof config.enabled === "boolean") {
      enabled = config.enabled
      if (!enabled && flushTimer) {
        scheduler.clear(flushTimer)
        flushTimer = null
      }
    }

    if (typeof config.batchSize === "number") {
      batchSize = toPositiveInt("batchSize", config.batchSize)
    }

    if (typeof config.flushIntervalMs === "number") {
      flushIntervalMs = toPositiveInt("flushIntervalMs", config.flushIntervalMs)
    }
  }

  const getState = (): LogDrainBufferState => ({
    queueSize: queue.length,
    dropCount,
    enabled,
    batchSize,
    flushIntervalMs,
  })

  return {
    push,
    flush,
    configure,
    getState,
  }
}

