      targetId: string
      type: string
    }>
  }
  error?: string
}

const fetchJson = async <T>(input: RequestInfo, init?: RequestInit) => {
  const response = await fetch(input, init)
  const result = await parseJsonResponse(response)
  const parsed = (result.ok && !result.isEmpty ? result.value : {}) as T
  return {
    response,
    parsed,
  }
}

export const fetchTraceGraphPayload = async (
  params: TraceGraphParams,
): Promise<{ graph: GraphPayload; targetId: string }> => {

const { response, parsed } = await fetchJson<TraceCallersApiResponse>(
  "/api/code/trace-callers",
  {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      mode: params.traceMode,
      nodeId: params.traceNodeId || undefined,
      symbol: params.traceSymbol || undefined,
      depth: params.traceMode === "impact" ? params.traceDepth : undefined,
      limit: params.traceLimit,
      sourceBranch: params.traceBranch || undefined,
      integrationId: params.traceIntegrationId || undefined,
    }),
  },
)

if (!response.ok || !parsed.data) {
  throw new Error(parsed.error ?? "Failed to load graph.")
}

const targetId =
  ((parsed.data.target?.id?.trim() || parsed.data.nodeId)?.trim() || null) ??
  (params.traceNodeId || null) ??
  (params.traceSymbol ? `symbol:${params.traceSymbol}` : null)
if (!targetId) {
  throw new Error("Trace target was not resolved.")
}

const targetName =
  parsed.data.target?.name?.trim() ||
  (parsed.data.symbol && parsed.data.symbol.trim()) ||
  (params.traceSymbol && params.traceSymbol.trim()) ||
  shortId(targetId)

const fallbackEdgeType =
  parsed.data.mode === "impact" ? "IMPACT" : "CALLS"

const nodesById = new Map<string, GraphPayload["nodes"][number]>()
nodesById.set(targetId, {
  id: targetId,
  kind: parsed.data.target?.kind?.trim() || "target",
  name: targetName,
  filePath: parsed.data.target?.filePath?.trim() || null,
})

for (const item of parsed.data.results) {
  nodesById.set(item.id, {
    id: item.id,
    kind: item.kind,
    name: item.name,
    filePath: item.filePath || null,
  })
}

const edges =
  parsed.data.edges
    ?.filter(
      (edge) =>
        nodesById.has(edge.sourceId) && nodesById.has(edge.targetId),
    )
    .map((edge) => ({
      sourceId: edge.sourceId,
      targetId: edge.targetId,
      type: edge.type || fallbackEdgeType,
    })) ?? []

if (edges.length === 0) {
  for (const item of parsed.data.results) {
    if (item.id === targetId) {
      continue
    }
    edges.push({
      sourceId: item.id,
      targetId,
      type: fallbackEdgeType,
    })
  }
}

const edgeTypes = [
  ...new Set(edges.map((edge) => edge.type).filter(Boolean)),
]

return {
  targetId,
  graph: normalizeGraphPayload({
    indexRunId: `trace:${targetId}`,
    generatedAt: new Date().toISOString(),
    totalNodes: nodesById.size,
    totalEdges: edges.length,
    availableEdgeTypes: edgeTypes,
    appliedEdgeTypes: edgeTypes,
    nodes: [...nodesById.values()],
    edges,
  }),
}

}

