export const findReviewRunDedupeCandidate = async (args: {
  userId: string
  patchHash: string
  scope: ReviewFlowScope
}): Promise<EnqueueOrGetReviewRunResult | null> => {
  const scope = normalizeRequiredScope(args.scope)

  const existing = await findActiveRunForScope({
    userId: args.userId,
    scope,
  })
  if (existing) {
    return {
      deduped: true,
      dedupeReason: "active_in_progress",
      run: toRunSummary(existing),
    }
  }

  const successfulSamePatchRun = await findLatestSuccessfulRunForScopeAndPatch({
    userId: args.userId,
    scope,
    patchHash: args.patchHash,
  })
  if (successfulSamePatchRun) {
    return {
      deduped: true,
      dedupeReason: "same_patch_success",
      run: toRunSummary(successfulSamePatchRun),
    }
  }

  return null
}

