const captureQueueDepthBefore = async (args: {
  summary: IndexingWorkerBatchSummary
  batchLog: RunnerScopedLogger
}) => {
  const { summary, batchLog } = args
  try {
    summary.queueDepthBefore = await getQueueDepthSnapshot()
    batchLog.set({
      queueDepthBefore: summary.queueDepthBefore,
    })
  } catch (error) {
    const errorToLog = toError(error, 'Unexpected queue depth snapshot processing error.')
    logRunnerScopedError(batchLog, errorToLog, {
      code: 'INDEXER_QUEUE_DEPTH_BEFORE_FAILED',
      why: 'Failed to read queue depth snapshot before batch processing.',
      fix: 'Inspect index_jobs/index_runs queries and database connectivity.',
    })
  }
}

const runArtifactCleanup = async (args: {
  nowMs: number
  summary: IndexingWorkerBatchSummary
  batchLog: RunnerScopedLogger
}) => {
  const { nowMs, summary, batchLog } = args
  if (nowMs - lastArtifactCleanupAt < resolveArtifactCleanupIntervalMs()) {
    return
  }

  try {
    const cleanupSummary = await cleanupIndexArtifacts()
    summary.artifactCleanupTriggered = cleanupSummary.lock === 'acquired'
    summary.artifactCleanupDeletedRuns = cleanupSummary.deletedRuns
    summary.artifactCleanupDeletedBytes = cleanupSummary.deletedBytes
    summary.artifactCleanupErrors = cleanupSummary.errors
    if (cleanupSummary.lock === 'acquired') {
      lastArtifactCleanupAt = nowMs
    }
    batchLog.set({
      artifactCleanup: cleanupSummary,
    })
  } catch (error) {
    const errorToLog = toError(error, 'Unexpected artifact cleanup processing error.')
    logRunnerScopedError(batchLog, errorToLog, {
      code: 'INDEXER_ARTIFACT_CLEANUP_FAILED',
      why: 'Failed to prune stale indexing artifacts.',
      fix: 'Inspect artifact retention policy and artifact store connectivity.',
    })
  }
}

const runAppLogCleanup = async (args: {
  nowMs: number
  summary: IndexingWorkerBatchSummary
  batchLog: RunnerScopedLogger
}) => {
  const { nowMs, summary, batchLog } = args
  if (nowMs - lastAppLogCleanupAt < resolveAppLogCleanupIntervalMs()) {
    return
  }

  try {
    const appLogCleanupSummary = await cleanupAppLogs()
    summary.appLogCleanupTriggered = appLogCleanupSummary.lock === 'acquired'
    summary.appLogCleanupDeletedByAge = appLogCleanupSummary.deletedByAge
    summary.appLogCleanupDeletedByCap = appLogCleanupSummary.deletedByCap
    if (appLogCleanupSummary.lock === 'acquired') {
      lastAppLogCleanupAt = nowMs
    }
    batchLog.set({
      appLogCleanup: appLogCleanupSummary,
    })
  } catch (error) {
    const errorToLog = toError(error, 'Unexpected app log cleanup processing error.')
    logRunnerScopedError(batchLog, errorToLog, {
      code: 'APP_LOG_CLEANUP_FAILED',
      why: 'Failed to prune app log events based on retention policy.',
      fix: 'Inspect app_log_events table health and cleanup query performance.',
    })
  }
}

const enqueueReconcileJobs = async (args: {
  summary: IndexingWorkerBatchSummary
  batchLog: RunnerScopedLogger
}) => {
  const { summary, batchLog } = args
  try {
    summary.reconcileScheduled = await enqueueDueReconcileJobs()
    batchLog.set({
      reconcileScheduled: summary.reconcileScheduled,
    })
  } catch (error) {
    const errorToLog = toError(error, 'Unexpected reconcile scheduler processing error.')
    logRunnerScopedError(batchLog, errorToLog, {
      code: 'INDEXER_RECONCILE_SCHEDULE_FAILED',
      why: 'Failed to enqueue due reconcile jobs.',
      fix: 'Inspect reconcile scheduler query and index_jobs/index_branch_states health.',
    })
  }
}

const reclaimStaleJobs = async (args: {
  nowMs: number
  summary: IndexingWorkerBatchSummary
  batchLog: RunnerScopedLogger
}) => {
  const { nowMs, summary, batchLog } = args
  if (nowMs - lastStaleReclaimAt < resolveStaleReclaimIntervalMs()) {
    return
  }
  try {
    const reclaimed = await reclaimStaleIndexJobs()
    summary.staleJobsReclaimed = reclaimed.length
    batchLog.set({
      staleJobsReclaimed: reclaimed.length,
      staleJobIds: reclaimed.length > 0 ? reclaimed.map((row) => row.id) : null,
      staleReclaimEvent: WORKER_EVENTS.INDEXER_JOB_RECLAIMED_STALE,
    })
    lastStaleReclaimAt = nowMs
  } catch (error) {
    const errorToLog = toError(error, 'Unexpected stale index job reclaim error.')
    logRunnerScopedError(batchLog, errorToLog, {
      code: 'INDEXER_STALE_RECLAIM_FAILED',
      why: 'Failed to reclaim stale processing index jobs.',
      fix: 'Inspect index_jobs lease fields and database health.',
    })
  }
}

export const runBatchScheduling = async (args: {
  nowMs: number
  summary: IndexingWorkerBatchSummary
  batchLog: RunnerScopedLogger
}) => {
  await captureQueueDepthBefore(args)
  await reclaimStaleJobs(args)
  await runArtifactCleanup(args)
  await runAppLogCleanup(args)
  await enqueueReconcileJobs(args)
}

