import {
  buildDefaultTokenUsageLimitMessage,
  consumeDefaultTokenUsage,
} from "@/lib/ai/default-token-usage"
import { db } from "@/lib/db"
import { aiReviewRuns, type AiReviewFinding } from "@/lib/db/schema"
import { getMergeRequestDetails } from "@/lib/gitlab/client"
import { decryptIntegrationToken } from "@/lib/gitlab/service"
import * as commentPublish from "@/lib/review/comment-publish"
import { applyReviewGate } from "@/lib/review/gate"
import {
  normalizeReviewPersonaMode,
  normalizeReviewPersona,
  type ReviewPersonaMode,
  type ReviewPersona,
} from "@/lib/review/persona"
import { normalizeReviewGateScope, resolveReviewGatePreferences } from "@/lib/review/preferences"
import { sha256Hex } from "@/lib/utils/hash"

const DEFAULT_AI_MODEL = "gpt-4o-mini"

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const toOptionalString = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

const getEnvModel = () => {
  if (isNonEmptyString(process.env.AI_MODEL)) {
    return process.env.AI_MODEL.trim()
  }
  if (isNonEmptyString(process.env.OPENAI_MODEL)) {
    return process.env.OPENAI_MODEL.trim()
  }
  return DEFAULT_AI_MODEL
}

const buildReviewSummary = (findings: AiReviewFinding[]) => {
  if (findings.length === 0) {
    return "AI review complete. No findings."
  }
  const highCount = findings.filter((finding) => finding.severity === "high").length
  const medCount = findings.filter((finding) => finding.severity === "med").length
  const lowCount = findings.length - highCount - medCount
  return `AI review complete: ${findings.length} findings (${highCount} high, ${medCount} med, ${lowCount} low).`
}

const toMergeRequestGraphScope = (value: unknown) => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {
      sourceBranch: null,
      sourceHeadSha: null,
    }
  }

  const record = value as Record<string, unknown>
  const diffRefs =
    record.diff_refs && typeof record.diff_refs === "object" && !Array.isArray(record.diff_refs)
      ? (record.diff_refs as Record<string, unknown>)
      : null

  return {
    sourceBranch: toOptionalString(record.source_branch),
    sourceHeadSha: toOptionalString(diffRefs?.head_sha),
  }
}

export class PersistReviewRunError extends Error {
  status: number

  constructor(message: string, status: number) {
    super(message)
    this.name = "PersistReviewRunError"
    this.status = status
  }
}

export const persistReviewRun = async (
  args: PersistReviewRunInput,
): Promise<PersistReviewRunResult> => {
  const patch = args.patch
  const instanceUrl = normalizeApiUrl(args.instanceUrl)
  const projectId = String(args.projectId).trim()
  const mergeRequestIid = String(args.mergeRequestIid).trim()
  const integrationId = toOptionalString(args.integrationId)
  const scope = normalizeReviewGateScope({
    instanceUrl,
    projectId,
  })

  if (!patch.trim()) {
    throw new PersistReviewRunError("Patch is required.", 400)
  }
  if (!instanceUrl || !projectId || !mergeRequestIid) {
    throw new PersistReviewRunError(
      "instanceUrl, projectId, and mergeRequestIid are required.",
      400,
    )
  }

  const trialConsumption = await consumeDefaultTokenUsage({
    userId: args.userId,
    usesServerToken: args.usedServerToken,
    requestType: "review",
  })
  if (trialConsumption.limited && trialConsumption.summary) {
    throw new PersistReviewRunError(
      buildDefaultTokenUsageLimitMessage(trialConsumption.summary.limit),
      403,
    )
  }

  const [gatePreferences, integration] = await Promise.all([
    resolveReviewGatePreferences({
      userId: args.userId,
      scope,
    }),
    commentPublish.resolveManagedIntegrationForScope({
      userId: args.userId,
      instanceUrl,
      projectId,
      integrationId,
    }),
  ])

  const gateResult = applyReviewGate({
    findings: args.findings,
    settings: gatePreferences.effectiveSettings,
  })
  const filteredFindings = gateResult.filteredFindings as AiReviewFinding[]

const summary = isNonEmptyString(args.summary)
  ? args.summary.trim()
  : buildReviewSummary(filteredFindings)
const model = toOptionalString(args.model) ?? getEnvModel()
const personaMode = normalizeReviewPersonaMode(args.personaMode ?? gatePreferences.effectiveSettings.personaMode)
const persona = normalizeReviewPersona(args.persona ?? gatePreferences.effectiveSettings.persona)
const personaPasses = Array.isArray(args.personaPasses)
  ? Array.from(new Set(args.personaPasses.map((entry) => String(entry ?? "").trim()).filter((entry) => entry.length > 0)))
  : []

let sourceBranch: string | null = toOptionalString(args.sourceBranch)
let sourceHeadSha: string | null = toOptionalString(args.sourceHeadSha)
if (integration) {
  try {
    const token = decryptIntegrationToken(integration)
    const mergeRequestDetails = await getMergeRequestDetails(
      instanceUrl,
      token,
      projectId,
      mergeRequestIid,
    )
    const graphScope = toMergeRequestGraphScope(mergeRequestDetails)
    sourceBranch = graphScope.sourceBranch ?? sourceBranch
    sourceHeadSha = graphScope.sourceHeadSha ?? sourceHeadSha
  } catch (error) {
    if (args.logger) {
      args.logger.set({
        reviewGraphScopeLookupError: error instanceof Error ? error.message : "unknown",
        reviewGraphScopeLookupIntegrationId: integration.id,
        instanceUrl,
        projectId,
        mergeRequestIid,
      })
    }
  }
}

