use std::path::{Path, PathBuf};

use crate::path_policy::resolve_store_path_within_root;

pub const DEFAULT_CONFIG_FILES: [&str; 2] = ["argus-search.json", ".argus-search.json"];
pub const DEFAULT_CONFIG_BASENAME: &str = "argus-search.json";
pub const DEFAULT_STORE_PATH: &str = ".argus-search/index.kite";
pub const DEFAULT_VECTOR_BASE_URL: &str = "https://api.openai.com/v1";
pub const DEFAULT_VECTOR_MODEL: &str = "text-embedding-3-small";
pub const DEFAULT_INIT_PATHS: &[&str] = &["."];
pub const DEFAULT_INIT_INCLUDE: &[&str] = &[
  "*.ts", "*.tsx", "*.js", "*.jsx", "*.py", "*.cpp", "*.cc", "*.c", "*.hpp", "*.h", "*.ada",
];
pub const DEFAULT_INIT_EXCLUDE: &[&str] = &[
  "node_modules",
  "dist",
  "build",
  "target",
  ".git",
  ".venv",
  "__pycache__",
  ".argus-search",
];

pub struct BuildInitConfigArgs<'a> {
  pub project_root: &'a str,
  pub paths: Vec<String>,
  pub include: Vec<String>,
  pub exclude: Vec<String>,
  pub vector_base_url: &'a str,
  pub vector_model: &'a str,
  pub incremental: bool,
  pub include_checkpoint_defaults: bool,
}

pub fn default_init_paths() -> Vec<String> {
  DEFAULT_INIT_PATHS
    .iter()
    .map(|entry| (*entry).to_string())
    .collect()
}

pub fn default_init_include() -> Vec<String> {
  DEFAULT_INIT_INCLUDE
    .iter()
    .map(|entry| (*entry).to_string())
    .collect()
}

pub fn default_init_exclude() -> Vec<String> {
  DEFAULT_INIT_EXCLUDE
    .iter()
    .map(|entry| (*entry).to_string())
    .collect()
}

pub fn build_init_config(args: BuildInitConfigArgs<'_>) -> serde_json::Value {
  let output = if args.include_checkpoint_defaults {
    serde_json::json!({
      "incremental": args.incremental,
      "checkpointOnFinish": true,
      "checkpointThreshold": 0.0
    })
  } else {
    serde_json::json!({
      "incremental": args.incremental
    })
  };

  serde_json::json!({
    "projectRoot": args.project_root,
    "inputs": {
      "paths": args.paths,
      "include": args.include,
      "exclude": args.exclude,
      "respectGitignore": true
    },
    "phases": { "parse": true, "graph": true, "vector": true, "scip": false, "indexPack": false },
    "vector": {
      "provider": {
        "kind": "http",
        "baseUrl": args.vector_base_url,
        "model": args.vector_model
      }
    },
    "cache": { "enabled": args.incremental, "force": false },
    "output": output
  })
}

pub fn absolute_from_cwd(path: &Path) -> anyhow::Result<PathBuf> {
  if path.is_absolute() {
    return Ok(path.to_path_buf());
  }
  Ok(std::env::current_dir()?.join(path))
}

pub fn resolve_config_path(explicit: Option<PathBuf>) -> anyhow::Result<Option<PathBuf>> {
  if let Some(path) = explicit {
    return Ok(Some(absolute_from_cwd(&path)?));
  }

  let mut dir = std::env::current_dir()?;
  loop {
    for candidate in DEFAULT_CONFIG_FILES {
      let path = dir.join(candidate);
      if path.exists() {
        return Ok(Some(path));
      }
    }

    let Some(parent) = dir.parent() else {
      break;
    };
    if parent == dir {
      break;
    }
    dir = parent.to_path_buf();
  }

  Ok(None)
}

pub fn resolve_bootstrap_project_root(
  args_project_root: Option<&Path>,
  config_path: Option<&Path>,
) -> anyhow::Result<PathBuf> {
  if let Some(project_root) = args_project_root {
    return absolute_from_cwd(project_root);
  }
  if let Some(path) = config_path {
    if let Some(parent) = path.parent() {
      return Ok(parent.to_path_buf());
    }
  }
  if let Ok(env_root) = std::env::var("CODE_INTELLIGENCE_PROJECT_ROOT")
    .or_else(|_| std::env::var("CODE_INTEL_PROJECT_ROOT"))
  {
    return absolute_from_cwd(Path::new(&env_root));
  }
  std::env::current_dir().map_err(Into::into)
}

pub fn resolve_store_path(project_root: &Path, store: Option<PathBuf>) -> anyhow::Result<PathBuf> {
  let store_path = store.unwrap_or_else(|| PathBuf::from(DEFAULT_STORE_PATH));
  resolve_store_path_within_root(project_root, store_path, "store.path").map_err(anyhow::Error::msg)
}

pub fn ensure_gitignore(project_root: &Path) -> anyhow::Result<()> {
  let gitignore_path = project_root.join(".gitignore");
  let entry = ".argus-search/";
  let existing = fs::read_to_string(&gitignore_path).unwrap_or_default();
  if existing.contains(entry) {
    return Ok(());
  }

  let mut updated = existing;
  if !updated.is_empty() && !updated.ends_with('\n') {
    updated.push('\n');
  }
  updated.push_str("\n# argus-search\n");
  updated.push_str(entry);
  updated.push('\n');
  fs::write(gitignore_path, updated)?;
  Ok(())
}

