  kind: z.string().min(1),
  name: z.string().min(1),
  filePath: z.string().min(1),
  rangeJson: z.string().min(1),
})

const traceNodesSchema = z.array(traceNodeSchema)
const traceImpactItemSchema = z.object({
  depth: z.number().int().positive(),
  node: traceNodeSchema,
})
const traceImpactItemsSchema = z.array(traceImpactItemSchema)

type TraceNodeRecord = z.infer<typeof traceNodeSchema>

export type CodeIntelWatchStreamHandle = {
  pid: number | null
  killed: boolean
  stdout: {
    on: (event: "data", listener: (chunk: Buffer | string) => void) => unknown
  }
  stderr: {
    on: (event: "data", listener: (chunk: Buffer | string) => void) => unknown
  }
  kill: (signal?: NodeJS.Signals) => boolean
  on: (
    event: "error" | "close",
    listener: ((error: unknown) => void) | ((code: number | null, signal: NodeJS.Signals | null) => void),
  ) => unknown
}

const requireFromModule = createRequire(import.meta.url)
const sdkModuleName = ["@argus", "argus-search"].join("/")

type AnyFunction = (...args: unknown[]) => unknown
type ArgusSearchSdkModule = {
  indexToKiteDb?: AnyFunction
  indexStream?: AnyFunction
  createIndexStream?: AnyFunction
  traceCallersKiteDb?: AnyFunction
  traceImpactKiteDb?: AnyFunction
}

let cachedSdkModule: ArgusSearchSdkModule | undefined

// Test-only SDK override so unit tests can run without loading the native runtime.
export const setArgusSearchSdkModuleForTests = (sdkModule: ArgusSearchSdkModule | undefined): void => {
  cachedSdkModule = sdkModule
}

const resolveSdkModule = (): ArgusSearchSdkModule => {
  if (cachedSdkModule) {
    return cachedSdkModule
  }

  try {
    const loaded = requireFromModule(sdkModuleName) as unknown
    if (!loaded || (typeof loaded !== "object" && typeof loaded !== "function")) {
      throw new CodeIntelSdkError("sdk_missing", SDK_UNAVAILABLE_MESSAGE, {
        message: "Loaded SDK module was not an object/function.",
      })
    }
    cachedSdkModule = loaded as ArgusSearchSdkModule
  } catch (error) {
    if (error instanceof CodeIntelSdkError) {
      throw error
    }
    throw new CodeIntelSdkError("sdk_missing", SDK_UNAVAILABLE_MESSAGE, {
      message: errorMessage(error),
    })
  }

  return cachedSdkModule
}

const resolveSdkFunction = (operation: string, names: Array<keyof ArgusSearchSdkModule>): AnyFunction => {
  const sdk = resolveSdkModule()
  for (const name of names) {
    const value = sdk[name]
    if (typeof value === "function") {
      return value
    }
  }
  throw new CodeIntelSdkError("operation_failed", `Argus Search SDK does not expose ${operation}.`, {
    attempted: names,
  })
}

const parseConfig = async (configPath: string): Promise<Record<string, unknown>> => {
  const raw = await readFile(configPath, "utf8")
  const parsed = JSON.parse(raw) as unknown
  return asRecord(parsed) ?? {}
}

const resolveStorePath = (projectRoot: string, explicit: string | undefined): string => {
  const storePath = explicit?.trim() ? explicit.trim() : ".argus-search/index.kite"
  return path.isAbsolute(storePath) ? storePath : path.join(projectRoot, storePath)
}

const resolvePhaseOptions = (
  configPhases: Record<string, unknown> | null,
  phaseSet: Set<string>,
  hasPhaseOverrides: boolean,
  noVector: boolean,
) => ({
  parse: hasPhaseOverrides ? phaseSet.has("parse") : toBoolean(configPhases?.parse, true),
  graph: hasPhaseOverrides ? phaseSet.has("graph") : toBoolean(configPhases?.graph, true),
  vector: noVector ? false : hasPhaseOverrides ? phaseSet.has("vector") : toBoolean(configPhases?.vector, false),
  scip: hasPhaseOverrides ? phaseSet.has("scip") : toBoolean(configPhases?.scip, false),
  indexPack:
    hasPhaseOverrides
      ? phaseSet.has("indexpack") || phaseSet.has("index-pack")
      : toBoolean(configPhases?.indexPack, false),
})

const resolveIndexOptions = async (options: WatchOptions): Promise<Record<string, unknown>> => {
  const config = await parseConfig(options.configPath)
  const configPhases = asRecord(config.phases)
  const phaseSet = new Set(options.phases.map((phase) => phase.trim().toLowerCase()).filter(Boolean))
  const hasPhaseOverrides = phaseSet.size > 0

  const phases = resolvePhaseOptions(configPhases, phaseSet, hasPhaseOverrides, options.noVector)

  return {
    projectRoot: options.projectRoot,
    inputs: config.inputs ?? undefined,
    phases,
    output: config.output ?? undefined,
    cache: config.cache ?? undefined,
    vector: options.noVector ? undefined : (config.vector ?? undefined),
    scip: config.scip ?? undefined,
  }
}

const mapSdkError = (error: unknown, message: string): CodeIntelSdkError => {
  if (error instanceof CodeIntelSdkError) {
    return error
  }

  return new CodeIntelSdkError("operation_failed", message, {
    message: errorMessage(error),
  })
}

export const runWatchOnce = async (options: WatchOptions): Promise<void> => {
  try {
    const indexToKiteDb = resolveSdkFunction("indexToKiteDb", ["indexToKiteDb"])
    const projectRoot = await resolveProjectRoot(options.projectRoot)
    const indexOptions = await resolveIndexOptions({
      ...options,
      projectRoot,
    })
    const storePath = resolveStorePath(projectRoot, options.storePath)
    await withTimeout(
      Promise.resolve(
        indexToKiteDb(indexOptions, {
          path: storePath,
          clear: false,
        }),
      ).then(() => undefined),
      options.timeoutMs,
      WATCH_TIMEOUT_MESSAGE,
    )
  } catch (error) {
    throw mapSdkError(error, "Failed to execute SDK watch operation.")
  }
}

const isAsyncIterable = (value: unknown): value is AsyncIterable<unknown> =>
  Boolean(value && typeof (value as { [Symbol.asyncIterator]?: unknown })[Symbol.asyncIterator] === "function")

export const startWatchStream = (options: WatchStreamOptions): CodeIntelWatchStreamHandle => {
  const stdout = new EventEmitter()
  const stderr = new EventEmitter()
  const lifecycle = new EventEmitter()
  const abortController = new AbortController()
  let closed = false
  let killed = false

const close = (code: number | null, signal: NodeJS.Signals | null) => {
  if (closed) {
    return
  }
  closed = true
  lifecycle.emit("close", code, signal)
}

const handle: CodeIntelWatchStreamHandle = {
  pid: null,
  get killed() {
    return killed
  },
  stdout: {
    on: (event, listener) => stdout.on(event, listener),
  },
  stderr: {
    on: (event, listener) => stderr.on(event, listener),
  },
  kill: (signal?: NodeJS.Signals) => {
    if (closed) {
      return false
    }
    killed = true
    abortController.abort()
    close(null, signal ?? "SIGTERM")
    return true
  },
  on: (event, listener) => lifecycle.on(event, listener as (...args: unknown[]) => void),
}

  try {
    const indexStream = resolveSdkFunction("indexStream", ["indexStream", "createIndexStream"])
    void (async () => {
      try {
        const projectRoot = await resolveProjectRoot(options.projectRoot)
        const indexOptions = await resolveIndexOptions({
          ...options,
          projectRoot,
        })
        const stream = await Promise.resolve(
          indexStream(indexOptions, {
            signal: abortController.signal,
          }),
        )
        if (!isAsyncIterable(stream)) {
          throw new Error("SDK stream handle is not async iterable.")
        }

        for await (const event of stream) {
          stdout.emit("data", `${JSON.stringify(event)}\n`)
        }

        close(0, null)
      } catch (error) {
        if (killed) {
          close(null, "SIGTERM")
          return
        }

        stderr.emit("data", `${errorMessage(error)}\n`)
        lifecycle.emit("error", error)
        close(1, null)
      }
    })()

    return handle
  } catch (error) {
    throw mapSdkError(error, "Failed to execute SDK watch stream operation.")
  }
}

const normalizeTraceResult = (value: unknown): unknown => {
  if (typeof value === "string") {
    return JSON.parse(value)
  }

  const record = asRecord(value)
  if (record && Array.isArray(record.results)) {
    return record.results
  }
  if (record && Array.isArray(record.data)) {
    return record.data
  }

  return value
}

export const runTraceGraph = async (options: TraceOptions): Promise<unknown> => {

  try {
    const projectRoot = await resolveProjectRoot(options.projectRoot)
    const storePath = resolveStorePath(projectRoot, options.storePath)
    const limit = clampPositiveInt(options.limit, 50)
    const nodeId = options.nodeId?.trim()
    const symbol = options.symbol?.trim()

    if (!nodeId && !symbol) {
      throw new Error("A symbol or nodeId is required.")
    }

    if (options.mode === "callers") {
      const traceCallersKiteDb = resolveSdkFunction("traceCallersKiteDb", ["traceCallersKiteDb"])
      const callers = await withTimeout(
        Promise.resolve(
          traceCallersKiteDb({
            projectRoot,
            store: { path: storePath },
            name: nodeId ? undefined : symbol,
            nodeId: nodeId || undefined,
            limit,
          }),
        ),
        options.timeoutMs,
        TRACE_TIMEOUT_MESSAGE,
      )
      return normalizeTraceResult(callers)
    }

    const traceImpactKiteDb = resolveSdkFunction("traceImpactKiteDb", ["traceImpactKiteDb"])
    const depth = clampPositiveInt(options.depth, 3)
    const impact = await withTimeout(
      Promise.resolve(
        traceImpactKiteDb({
          projectRoot,
          store: { path: storePath },
          name: nodeId ? undefined : symbol,
          nodeId: nodeId || undefined,
          limit,
          depth,
        }),
      ),
      options.timeoutMs,
      TRACE_TIMEOUT_MESSAGE,
    )
    return normalizeTraceResult(impact)
  } catch (error) {
    throw mapSdkError(error, "Failed to execute SDK trace operation.")
  }
}

const parseRange = (rangeJson: string): z.infer<typeof rangeSchema> | null => {
  let parsed: unknown
  try {
    parsed = JSON.parse(rangeJson) as unknown
  } catch {
    return null
  }

  const result = rangeSchema.safeParse(parsed)
  if (!result.success) {
    return null
  }

  return result.data
}

const normalizeNode = (node: TraceNodeRecord): TraceCaller => ({
  id: node.id,
  kind: node.kind,
  name: node.name,
  filePath: node.filePath,
  range: parseRange(node.rangeJson),
})

export const traceGraph = async (input: TraceGraphInput): Promise<TraceGraphNode[]> => {
  const rootDir = resolveCodeIntelRoot()
  const hasNodeId = Boolean(input.nodeId && input.nodeId.trim().length > 0)
  const symbol = input.symbol?.trim()
  const nodeId = input.nodeId?.trim()
  const mode = input.mode ?? "callers"

  if (!hasNodeId && !symbol) {
    throw new CodeTraceError("command_failed", "A symbol or nodeId is required.", null)
  }

try {
  const sdkResult = await runTraceGraph({
    mode,
    symbol,
    nodeId,
    limit: input.limit,
    depth: mode === "impact" ? input.depth : undefined,
    projectRoot: rootDir,
    timeoutMs: 30_000,
  })

  const parsed: unknown = sdkResult

  if (mode === "impact") {
    const validatedImpact = traceImpactItemsSchema.safeParse(parsed)
    if (!validatedImpact.success) {
      throw new CodeTraceError("invalid_output", "Trace output did not match expected schema.", {
        issues: validatedImpact.error.issues.map((issue) => issue.message),
      })
    }

    return validatedImpact.data.map((item) => ({
      ...normalizeNode(item.node),
      depth: item.depth,
    }))
  }

  const validatedCallers = traceNodesSchema.safeParse(parsed)
  if (!validatedCallers.success) {
    throw new CodeTraceError("invalid_output", "Trace output did not match expected schema.", {
      issues: validatedCallers.error.issues.map((issue) => issue.message),
    })
  }

  return validatedCallers.data.map((node) => ({
    ...normalizeNode(node),
    depth: 1,
  }))
} catch (error) {

    if (error instanceof CodeTraceError) {
      throw error
    }

    if (error instanceof CodeIntelSdkError) {
      if (error.code === "sdk_missing") {
        throw new CodeTraceError("binary_missing", "The Argus Search SDK is not available in this runtime.", {
          details: error.details,
        })
      }

      throw new CodeTraceError("command_failed", "Failed to execute code graph trace.", {
        message: error.message,
        details: error.details,
      })
    }

    throw new CodeTraceError("command_failed", "Failed to execute code graph trace.", {
      message: error instanceof Error ? error.message : "Unknown command failure.",
    })
  }
}

export const traceCallers = async (input: TraceCallersInput): Promise<TraceCaller[]> => {
  const results = await traceGraph({
    ...input,
    mode: "callers",
  })

  return results.map((node) => ({
    id: node.id,
    kind: node.kind,
    name: node.name,
    filePath: node.filePath,
    range: node.range,
  }))
}

