const fs = require('node:fs')
const path = require('node:path')

const rootDir = path.resolve(__dirname, '..')
const nativeDir = path.join(rootDir, 'native')
const nativePrefix = 'argus-search.'

function ensureNativeDir() {
  fs.mkdirSync(nativeDir, { recursive: true })
}

function moveNativeBinaries() {
  for (const entry of fs.readdirSync(rootDir)) {
    if (!entry.startsWith(nativePrefix) || !entry.endsWith('.node')) continue
    const from = path.join(rootDir, entry)
    const to = path.join(nativeDir, entry)
    if (from === to) continue
    fs.renameSync(from, to)
  }
}

function patchIndexLoader() {
  const indexPath = path.join(rootDir, 'index.js')
  if (!fs.existsSync(indexPath)) return

  const source = fs.readFileSync(indexPath, 'utf8')
  const patched = source.replace(/require\('\.\/argus-search\.([^']+\.node)'\)/g, "require('./native/argus-search.$1')")
  if (patched !== source) {
    fs.writeFileSync(indexPath, patched)
  }
}

ensureNativeDir()
moveNativeBinaries()
patchIndexLoader()

