const EMBEDDING_COST_ENV_PREFIX = "OBS_EMBEDDING_COST_USD_PER_1K"

const toUsd = (value: number) => Number(value.toFixed(8))

const normalizeModelEnvKey = (model: string) =>
  model
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")

const resolveUsdPer1kFromEnv = (model: string | null): number | null => {
  const normalizedModel = model?.trim() ?? ""
  const modelKey = normalizedModel ? normalizeModelEnvKey(normalizedModel) : ""
  // Prefer model-specific pricing override, then fall back to global embedding rate.
  const envKey = modelKey ? `${EMBEDDING_COST_ENV_PREFIX}_${modelKey}` : EMBEDDING_COST_ENV_PREFIX
  const rawModelRate = modelKey ? process.env[envKey] : undefined
  const rawGlobalRate = process.env[EMBEDDING_COST_ENV_PREFIX]
  const rawRate = rawModelRate ?? rawGlobalRate
  if (!rawRate || rawRate.trim().length === 0) {
    return null
  }

  const parsed = Number.parseFloat(rawRate)
  if (!Number.isFinite(parsed) || parsed < 0) {
    throw new Error(`Invalid ${EMBEDDING_COST_ENV_PREFIX} value "${rawRate}".`)
  }
  return parsed
}

const toNonNegativeInt = (value: number, name: string) => {
  if (!Number.isFinite(value) || value < 0) {
    throw new Error(`Invalid ${name}. Expected a non-negative number.`)
  }
  return Math.floor(value)
}

export const estimateEmbeddingCostUsd = (args: {
  model: string | null
  totalTokens: number
}): number | null => {
  const usdPer1k = resolveUsdPer1kFromEnv(args.model)
  if (usdPer1k === null) {
    return null
  }

  const totalTokens = toNonNegativeInt(args.totalTokens, "totalTokens")
  const totalCost = (usdPer1k * totalTokens) / 1_000
  return toUsd(totalCost)
}

