const resolveProcessLike = (): ProcessLike => {
  const processLike = (globalThis as { process?: ProcessLike }).process
  if (!processLike) {
    throw new Error("[indexer-worker] process APIs are unavailable")
  }
  return processLike
}

const defaultSleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

export const runIndexerWorkerRuntime = async <TLogger extends ScopedLogger>(
  deps: IndexerWorkerRuntimeDeps<TLogger>,
) => {
  const env = deps.env ?? resolveDefaultEnv()
  const processLike = deps.processLike ?? resolveProcessLike()
  const sleep = deps.sleep ?? defaultSleep
  const now = deps.now ?? Date.now
  let shutdownInProgress = false

  const flushAndExit = (signal: SignalName) => {
    if (shutdownInProgress) {
      return
    }
    // A signal can arrive multiple times; only flush and exit once.
    shutdownInProgress = true

    void (async () => {
      deps.appLogInfo({
        event: "indexer.worker.shutdown_signal",
        signal,
      })
      try {
        await deps.flushAppLogger()
      } finally {
        processLike.exit(0)
      }
    })()
  }

  try {
    const workerConfig = resolveIndexerWorkerConfig(env)

    deps.initAppLogger({
      service: workerConfig.service,
      environment: workerConfig.environment,
      version: workerConfig.version,
      pretty: workerConfig.pretty,
      initEvent: "indexer.worker.observability_initialized",
    })

    processLike.once("SIGINT", () => flushAndExit("SIGINT"))
    processLike.once("SIGTERM", () => flushAndExit("SIGTERM"))

deps.appLogInfo({
  event: "indexer.worker.started",
  batchSize: workerConfig.batchSize,
  pollIntervalMs: workerConfig.pollIntervalMs,
  continuous: workerConfig.continuous,
})

do {
  const batchId = deps.createCorrelationId()
  const cycleLog = deps.createScopedLogger({
    method: "INDEXER",
    path: "/workers/indexer/cycle",
    requestId: batchId,
  })
  const cycleStartedAt = now()
  cycleLog.set({
    event: "indexer.worker.batch_cycle",
    batchId,
    batchSize: workerConfig.batchSize,
    continuous: workerConfig.continuous,
  })
  let cycleStatus = 500
  try {
    const summary = await deps.runIndexingWorkerBatch(workerConfig.batchSize, { batchId })
    cycleLog.set({
      summary,
    })
    cycleStatus =
      summary.jobsFailed > 0 || summary.jobsDead > 0 || summary.failed > 0
        ? 207
        : 200

    if (!workerConfig.continuous) {
      break
    }

    await sleep(workerConfig.pollIntervalMs)
  } finally {
    cycleLog.emit({
      status: cycleStatus,
      durationMs: now() - cycleStartedAt,
    })
  }
} while (true)

await deps.flushAppLogger()

  } catch (error) {
    const errorToLog = toError(error, "Indexer worker crashed.")
    const fatalLog = deps.createScopedLogger({
      method: "INDEXER",
      path: "/workers/indexer",
      requestId: deps.createCorrelationId(),
    })
    fatalLog.set({
      event: "indexer.worker.fatal",
      outcome: "crashed",
    })
    deps.logScopedError(fatalLog, errorToLog, {
      code: "INDEXER_WORKER_FATAL",
      why: "Unhandled exception escaped the indexer worker loop.",
      fix: "Inspect preceding batch/job events and dependency health.",
    })
    fatalLog.emit({
      status: 500,
    })

    await deps.flushAppLogger()
    throw errorToLog
  }
}

