        trendDays: overview.trendDays,
        commandKinds: overview.userActivity.commandsUsed.length,
        featureKinds: overview.userActivity.featureAdoption.length,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json(overview),
      }
    },
  })
}

