use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::{Arc, OnceLock, RwLock};

use tree_sitter::{Language, LANGUAGE_VERSION, MIN_COMPATIBLE_LANGUAGE_VERSION};
use tree_sitter_language::LanguageFn;

use super::languages::{
  detect_language_from_path, language_for, normalize_extension, parse_language_name, LanguageId,
};
use super::queries::query_text;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ChunkKind {
  Function,
  Class,
  Type,
  Variable,
}

impl ChunkKind {
  pub fn as_str(self) -> &'static str {
    match self {
      ChunkKind::Function => "function",
      ChunkKind::Class => "class",
      ChunkKind::Type => "type",
      ChunkKind::Variable => "variable",
    }
  }

  pub fn query_name(self) -> &'static str {
    match self {
      ChunkKind::Function => "functions",
      ChunkKind::Class => "classes",
      ChunkKind::Type => "types",
      ChunkKind::Variable => "variables",
    }
  }

  pub fn from_name(value: &str) -> Option<Self> {
    match value.trim().to_lowercase().as_str() {
      "function" => Some(ChunkKind::Function),
      "class" => Some(ChunkKind::Class),
      "type" => Some(ChunkKind::Type),
      "variable" => Some(ChunkKind::Variable),
      _ => None,
    }
  }
}

#[derive(Debug, Clone)]
pub enum CustomGrammarSource {
  Builtin(LanguageId),
  Dylib { path: PathBuf, symbol: String },
}

#[derive(Debug, Clone, Default)]

pub struct CustomQuerySet {
  pub functions: Option<String>,
  pub classes: Option<String>,
  pub types: Option<String>,
  pub variables: Option<String>,
  pub imports: Option<String>,
  pub exports: Option<String>,
  pub comments: Option<String>,
}

impl CustomQuerySet {
  pub fn get(&self, name: &str) -> Option<&str> {
    match name {
      "functions" => self.functions.as_deref(),
      "classes" => self.classes.as_deref(),
      "types" => self.types.as_deref(),
      "variables" => self.variables.as_deref(),
      "imports" => self.imports.as_deref(),
      "exports" => self.exports.as_deref(),
      "comments" => self.comments.as_deref(),
      _ => None,
    }
  }
}

#[derive(Debug, Clone)]
pub struct RegisterLanguageOptions {
  pub id: String,
  pub extensions: Vec<String>,
  pub grammar: CustomGrammarSource,
  pub queries: CustomQuerySet,
  pub chunk_kinds: Vec<ChunkKind>,
}

#[derive(Debug, Clone)]
pub struct ChunkingPlan {
  pub language_label: String,
  pub language: Language,
  pub query_texts: Vec<String>,
  pub chunk_kinds: Vec<ChunkKind>,
}

#[derive(Debug, Clone)]
enum RegisteredGrammar {
  Builtin(LanguageId),
  Dynamic(DynamicGrammar),
}

#[derive(Debug, Clone)]
struct DynamicGrammar {
  language: Language,
  // Keep the library alive for as long as the grammar is registered.
  _library: Arc<libloading::Library>,
}

const ALLOW_UNSAFE_GRAMMARS_ENV: &str = "CODE_INTELLIGENCE_ALLOW_UNSAFE_GRAMMARS";

#[derive(Debug, Clone)]

struct RegisteredLanguage {
  id: String,
  extensions: Vec<String>,
  grammar: RegisteredGrammar,
  queries: CustomQuerySet,
  chunk_kinds: Vec<ChunkKind>,
}

impl RegisteredLanguage {
  fn to_plan(&self) -> Option<ChunkingPlan> {
    let mut names = Vec::new();
    for kind in &self.chunk_kinds {
      names.push(kind.query_name());
    }
    names.extend(["imports", "exports", "comments"]);

    let mut seen = HashSet::new();
    let mut query_texts = Vec::new();
    for name in names {
      if !seen.insert(name) {
        continue;
      }
      if let Some(text) = self.queries.get(name) {
        query_texts.push(text.to_string());
      } else if self
        .chunk_kinds
        .iter()
        .any(|kind| kind.query_name() == name)
      {
        return None;
      }
    }

    let language = match &self.grammar {
      RegisteredGrammar::Builtin(language) => language_for(*language),
      RegisteredGrammar::Dynamic(grammar) => grammar.language.clone(),
    };

    Some(ChunkingPlan {
      language_label: self.id.clone(),
      language,
      query_texts,
      chunk_kinds: self.chunk_kinds.clone(),
    })
  }
}

#[derive(Default)]
struct LanguageRegistry {
  by_id: HashMap<String, RegisteredLanguage>,
  ext_to_id: HashMap<String, String>,
}

fn registry() -> &'static RwLock<LanguageRegistry> {
  static REGISTRY: OnceLock<RwLock<LanguageRegistry>> = OnceLock::new();
  REGISTRY.get_or_init(|| RwLock::new(LanguageRegistry::default()))
}

fn built_in_plan(language_id: LanguageId) -> Option<ChunkingPlan> {
  let mut query_texts = Vec::new();
  let mut chunk_kinds = Vec::new();

  for kind in [
    ChunkKind::Function,
    ChunkKind::Class,
    ChunkKind::Type,
    ChunkKind::Variable,
  ] {
    if let Some(text) = query_text(language_id, kind.query_name()) {
      query_texts.push(text.to_string());
      chunk_kinds.push(kind);
    }
  }

  for name in ["imports", "exports", "comments"] {
    if let Some(text) = query_text(language_id, name) {
      query_texts.push(text.to_string());
    }
  }

  if query_texts.is_empty() {
    return None;
  }

  Some(ChunkingPlan {
    language_label: language_id.as_str().to_string(),
    language: language_for(language_id),
    query_texts,
    chunk_kinds,
  })
}

fn normalize_id(value: &str) -> String {
  value.trim().to_lowercase()
}

fn extension_for_path(path: &str) -> Option<String> {
  let ext = Path::new(path).extension()?.to_string_lossy();
  Some(normalize_extension(ext.as_ref()))
}

fn infer_chunk_kinds(queries: &CustomQuerySet) -> Vec<ChunkKind> {
  let mut out = Vec::new();
  if queries
    .functions
    .as_ref()
    .is_some_and(|value| !value.is_empty())
  {
    out.push(ChunkKind::Function);
  }
  if queries
    .classes
    .as_ref()
    .is_some_and(|value| !value.is_empty())
  {
    out.push(ChunkKind::Class);
  }
  if queries
    .types
    .as_ref()
    .is_some_and(|value| !value.is_empty())
  {
    out.push(ChunkKind::Type);
  }
  if queries
    .variables
    .as_ref()
    .is_some_and(|value| !value.is_empty())
  {
    out.push(ChunkKind::Variable);
  }
  out
}

fn normalize_extensions(values: &[String]) -> Vec<String> {
  let mut out = Vec::new();
  let mut seen = HashSet::new();
  for value in values {
    let normalized = normalize_extension(value);
    if normalized.is_empty() || !seen.insert(normalized.clone()) {
      continue;
    }
    out.push(normalized);
  }
  out
}

fn env_flag_enabled(name: &str) -> bool {
  matches!(
    std::env::var(name),
    Ok(value) if matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES")
  )
}

fn normalize_dynamic_library_path(path: &Path) -> Result<PathBuf, String> {
  if !env_flag_enabled(ALLOW_UNSAFE_GRAMMARS_ENV) {
    return Err(format!(
      "dynamic grammars are disabled by default (set {ALLOW_UNSAFE_GRAMMARS_ENV}=1 to allow loading external libraries)"
    ));
  }
  let canonical = path.canonicalize().map_err(|err| {
    format!(
      "failed to resolve grammar dynamic library {}: {err}",
      path.display()
    )
  })?;
  let metadata = std::fs::metadata(&canonical).map_err(|err| {
    format!(
      "failed to read grammar dynamic library metadata {}: {err}",
      canonical.display()
    )
  })?;
  if !metadata.is_file() {
    return Err(format!(
      "grammar dynamic library path is not a file: {}",
      canonical.display()
    ));
  }
  let ext = canonical
    .extension()
    .and_then(|value| value.to_str())
    .map(|value| value.to_ascii_lowercase())
    .unwrap_or_default();
  if !matches!(ext.as_str(), "so" | "dylib" | "dll") {
    return Err(format!(
      "unsupported grammar dynamic library extension for {} (expected .so, .dylib, or .dll)",
      canonical.display()
    ));
  }
  Ok(canonical)
}

fn validate_dynamic_symbol(symbol: &str) -> Result<(), String> {
  if symbol
    .chars()
    .all(|ch| ch == '_' || ch.is_ascii_alphanumeric())
  {
    return Ok(());
  }
  Err(format!(
    "invalid grammar symbol {symbol}; only ASCII letters, digits, and '_' are allowed"
  ))
}

fn validate_language_abi(language: &Language, path: &Path, symbol: &str) -> Result<(), String> {
  let version = language.abi_version();
  if (MIN_COMPATIBLE_LANGUAGE_VERSION..=LANGUAGE_VERSION).contains(&version) {
    return Ok(());
  }
  Err(format!(
    "incompatible grammar ABI version {} for {}::{symbol} (supported range: {}..={})",
    version,
    path.display(),
    MIN_COMPATIBLE_LANGUAGE_VERSION,
    LANGUAGE_VERSION
  ))
}

fn load_dynamic_language(path: &Path, symbol: &str) -> Result<DynamicGrammar, String> {
  let path = normalize_dynamic_library_path(path)?;
  let symbol = symbol.trim();
  if symbol.is_empty() {
    return Err("custom grammar symbol cannot be empty".to_string());
  }
  validate_dynamic_symbol(symbol)?;

  // SAFETY: the symbol function signature follows tree-sitter generated grammars.
  unsafe {
    let library = libloading::Library::new(&path).map_err(|err| {
      format!(
        "failed to load grammar dynamic library {}: {err}",
        path.display()
      )
    })?;
    let raw_symbol: libloading::Symbol<'_, unsafe extern "C" fn() -> *const ()> = library
      .get(symbol.as_bytes())
      .map_err(|err| format!("failed to load grammar symbol {symbol}: {err}"))?;
    let language = Language::new(LanguageFn::from_raw(*raw_symbol));
    validate_language_abi(&language, &path, symbol)?;
    Ok(DynamicGrammar {
      language,
      _library: Arc::new(library),
    })
  }
}

pub fn register_language(options: RegisterLanguageOptions) -> Result<(), String> {
  let id = normalize_id(&options.id);

if id.is_empty() {
  return Err("custom language id cannot be empty".to_string());
}

let extensions = normalize_extensions(&options.extensions);
if extensions.is_empty() {
  return Err("custom language extensions cannot be empty".to_string());
}

let chunk_kinds = if options.chunk_kinds.is_empty() {
  infer_chunk_kinds(&options.queries)
} else {
  options.chunk_kinds.clone()
};
if chunk_kinds.is_empty() {
  return Err(
    "custom language chunkKinds cannot be empty (or inferable from query set)".to_string(),
  );
}

for kind in &chunk_kinds {
  let query_name = kind.query_name();
  let has_query = options
    .queries
    .get(query_name)
    .is_some_and(|value| !value.trim().is_empty());
  if !has_query {
    return Err(format!(
      "custom language {id} is missing required query: {query_name}"
    ));
  }
}

let grammar = match &options.grammar {
  CustomGrammarSource::Builtin(language) => RegisteredGrammar::Builtin(*language),
  CustomGrammarSource::Dylib { path, symbol } => {
    RegisteredGrammar::Dynamic(load_dynamic_language(path, symbol)?)
  }
};

let registered = RegisteredLanguage {
  id: id.clone(),
  extensions: extensions.clone(),
  grammar,
  queries: options.queries,
  chunk_kinds,
};

let mut guard = registry()
  .write()
  .map_err(|_| "language registry lock poisoned".to_string())?;

  if let Some(existing) = guard.by_id.remove(&id) {
    for ext in existing.extensions {
      if guard.ext_to_id.get(&ext).is_some_and(|owner| owner == &id) {
        guard.ext_to_id.remove(&ext);
      }
    }
  }

  for ext in &extensions {
    guard.ext_to_id.insert(ext.clone(), id.clone());
  }
  guard.by_id.insert(id, registered);
  Ok(())
}

pub fn resolve_chunking_plan(
  file_path: &str,
  language_override: Option<&str>,
) -> Option<ChunkingPlan> {
  if let Some(language_name) = language_override {
    let normalized = normalize_id(language_name);
    if normalized.is_empty() {
      return None;
    }

    if let Some(custom) = lookup_custom_by_id(&normalized) {
      return custom.to_plan();
    }
    if let Some(language_id) = parse_language_name(&normalized) {
      return built_in_plan(language_id);
    }
    return None;
  }

  if let Some(custom) = lookup_custom_by_extension(file_path) {
    return custom.to_plan();
  }

  let language_id = detect_language_from_path(file_path)?;
  built_in_plan(language_id)
}

fn lookup_custom_by_id(id: &str) -> Option<RegisteredLanguage> {
  let guard = registry().read().ok()?;
  guard.by_id.get(id).cloned()
}

fn lookup_custom_by_extension(file_path: &str) -> Option<RegisteredLanguage> {
  let ext = extension_for_path(file_path)?;
  let guard = registry().read().ok()?;
  let language_id = guard.ext_to_id.get(&ext)?;
  guard.by_id.get(language_id).cloned()
}

#[cfg(test)]
pub fn clear_registry_for_tests() {
  if let Ok(mut guard) = registry().write() {
    guard.by_id.clear();
    guard.ext_to_id.clear();
  }
}

#[cfg(test)]
mod tests {
  use super::*;
  use crate::core::parse::languages::BUILTIN_LANGUAGE_IDS;

  #[test]
  fn register_builtin_alias_and_resolve_by_extension() {
    clear_registry_for_tests();

    let query = |name| {
      query_text(LanguageId::TypeScript, name)
        .unwrap_or("")
        .to_string()
    };
    let options = RegisterLanguageOptions {
      id: "custom-ts".to_string(),
      extensions: vec!["mtsx".to_string()],
      grammar: CustomGrammarSource::Builtin(LanguageId::TypeScript),
      queries: CustomQuerySet {
        functions: Some(query("functions")),
        classes: Some(query("classes")),
        types: Some(query("types")),
        variables: Some(query("variables")),
        imports: Some(query("imports")),
        exports: Some(query("exports")),
        comments: Some(query("comments")),
      },
      chunk_kinds: vec![
        ChunkKind::Function,
        ChunkKind::Class,
        ChunkKind::Type,
        ChunkKind::Variable,
      ],
    };

    register_language(options).expect("register custom language");

    let plan = resolve_chunking_plan("src/example.mtsx", None).expect("resolved plan");
    assert_eq!(plan.language_label, "custom-ts");
    assert_eq!(plan.chunk_kinds.len(), 4);
    assert!(plan.query_texts.len() >= 4);
  }

  #[test]

  fn register_requires_queries_for_selected_chunk_kinds() {
    clear_registry_for_tests();

    let options = RegisterLanguageOptions {
      id: "broken".to_string(),
      extensions: vec!["broken".to_string()],
      grammar: CustomGrammarSource::Builtin(LanguageId::Python),
      queries: CustomQuerySet {
        functions: None,
        classes: None,
        types: None,
        variables: None,
        imports: None,
        exports: None,
        comments: None,
      },
      chunk_kinds: vec![ChunkKind::Function],
    };

    let err = register_language(options).expect_err("register should fail");
    assert!(err.contains("missing required query"));
  }

  #[test]
  fn built_in_languages_have_chunk_kind_parity() {
    for language_id in BUILTIN_LANGUAGE_IDS {
      let plan = built_in_plan(language_id).expect("built-in plan");
      assert_eq!(
        plan.chunk_kinds,
        vec![
          ChunkKind::Function,
          ChunkKind::Class,
          ChunkKind::Type,
          ChunkKind::Variable,
        ],
        "language {} missing symbol kind parity",
        language_id.as_str(),
      );
    }
  }
}

