type MetricPoint = {
  date: string;
  complexityScore: number | null;
  testCoverageRate: number | null;
  technicalDebtMinutes: number | null;
  antiPatternCount: number | null;
  acCoverageRate: number | null;
};

type MetricSnapshot = Omit<MetricPoint, "date">;

type CodeMetricRow = {
  measuredAt: Date;
  complexityScore: unknown;
  testCoverageRate: unknown;
  technicalDebtMinutes: unknown;
  antiPatternCount: unknown;
  acCoverageRate: unknown;
};

export type AnalyticsOverview = {
  generatedAt: string;
  windowDays: number;
  trendDays: number;
  codeMetrics: {
    latest: MetricSnapshot;
    previous: MetricSnapshot;
    deltas: MetricSnapshot;
    trend: MetricPoint[];
  };
  reviewAnalytics: {
    reviewsByDay: Array<{ date: string; count: number }>;
    reviewsByWeek: Array<{ week: string; count: number }>;
    issuesPerReview: number;
    reviewAcceptanceRate: number | null;
    acCoverageRate: number | null;
    reviewsInWindow: number;
    findingsInWindow: number;
  };
  userActivity: {
    commandsUsed: Array<{ command: string; count: number }>;
    featureAdoption: Array<{ feature: string; count: number }>;
    averageSessionDurationMs: number | null;
    medianSessionDurationMs: number | null;
    sessionsMeasured: number;
  };
};

type BuildOverviewOptions = {
  windowDays?: number;
  trendDays?: number;
  integrations?: AnalyticsIntegrationScope;
};

const DAY_MS = 24 * 60 * 60 * 1000;
const DEFAULT_WINDOW_DAYS = 30;
const DEFAULT_TREND_DAYS = 90;
const WINDOW_DAYS_RANGE = { min: 1, max: 365 } as const;
const TREND_DAYS_RANGE = { min: 7, max: 365 } as const;

const parseRequiredNumber = (value: unknown, field: string): number => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === "bigint") {
    const normalized = Number(value);
    if (Number.isFinite(normalized)) {
      return normalized;
    }
  }

  if (typeof value === "string" && value.trim().length > 0) {
    const normalized = Number(value);
    if (Number.isFinite(normalized)) {
      return normalized;
    }
  }

  throw new TypeError(`Expected numeric value for ${field}.`);
};

const parseOptionalNumber = (value: unknown, field: string): number | null => {
  if (value === null || value === undefined) {
    return null;
  }

  return parseRequiredNumber(value, field);
};

const parseNonNegativeNumber = (value: unknown, field: string): number => {
  const normalized = parseRequiredNumber(value, field);
  if (normalized < 0) {
    throw new RangeError(`${field} must be greater than or equal to 0.`);
  }

  return normalized;
};

const parseRequiredString = (value: unknown, field: string): string => {
  if (typeof value === "string" && value.trim().length > 0) {
    return value;
  }

  throw new TypeError(`Expected string value for ${field}.`);
};

const resolveDaysOption = (
  value: number | undefined,
  field: "windowDays" | "trendDays",
  defaults: { min: number; max: number; fallback: number },
) => {
  const resolved = value ?? defaults.fallback;

  if (!Number.isInteger(resolved)) {
    throw new TypeError(`${field} must be an integer.`);
  }

  if (resolved < defaults.min || resolved > defaults.max) {
    throw new RangeError(`${field} must be between ${defaults.min} and ${defaults.max}.`);
  }

  return resolved;
};

const average = (values: number[]) =>
  values.length === 0
    ? null
    : Math.round((values.reduce((sum, value) => sum + value, 0) / values.length) * 100) / 100;

const percentile = (values: number[], p: number) => {
  if (values.length === 0) {
    return null;
  }

  const sorted = [...values].sort((a, b) => a - b);
  const index = (sorted.length - 1) * p;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);

  if (lower === upper) {
    return sorted[lower];
  }

  // Linear interpolation keeps the percentile stable for even-sized datasets.
  const weight = index - lower;
  return sorted[lower] * (1 - weight) + sorted[upper] * weight;
};

const toUtcDateKey = (value: Date) => value.toISOString().slice(0, 10);

const emptyMetricSnapshot = (): MetricSnapshot => ({
  complexityScore: null,
  testCoverageRate: null,
  technicalDebtMinutes: null,
  antiPatternCount: null,
  acCoverageRate: null,
});

const metricDelta = (latest: number | null, previous: number | null) => {
  if (latest === null || previous === null) {
    return null;
  }

  return Math.round((latest - previous) * 100) / 100;
};

const toMetricSnapshot = (row: {
  complexityScore: unknown;
  testCoverageRate: unknown;
  technicalDebtMinutes: unknown;
  antiPatternCount: unknown;
  acCoverageRate: unknown;
}): MetricSnapshot => ({
  complexityScore: parseOptionalNumber(row.complexityScore, "complexityScore"),
  testCoverageRate: parseOptionalNumber(row.testCoverageRate, "testCoverageRate"),
  technicalDebtMinutes: parseOptionalNumber(row.technicalDebtMinutes, "technicalDebtMinutes"),
  antiPatternCount: parseOptionalNumber(row.antiPatternCount, "antiPatternCount"),
  acCoverageRate: parseOptionalNumber(row.acCoverageRate, "acCoverageRate"),
});

const buildTrend = (rows: CodeMetricRow[], trendDays: number, now: Date) => {
  const perDay = new Map<
    string,
    {
      complexityScore: number[];
      testCoverageRate: number[];
      technicalDebtMinutes: number[];
      antiPatternCount: number[];
      acCoverageRate: number[];
    }
  >();

for (const row of rows) {
  // Bucket by UTC day so trend points are deterministic regardless of host timezone.
  const date = toUtcDateKey(row.measuredAt);
  const current = perDay.get(date) ?? {
    complexityScore: [],
    testCoverageRate: [],
    technicalDebtMinutes: [],
    antiPatternCount: [],
    acCoverageRate: [],
  };

  const complexityScore = parseOptionalNumber(row.complexityScore, "complexityScore");
  const testCoverageRate = parseOptionalNumber(row.testCoverageRate, "testCoverageRate");
  const technicalDebtMinutes = parseOptionalNumber(
    row.technicalDebtMinutes,
    "technicalDebtMinutes",
  );
  const antiPatternCount = parseOptionalNumber(row.antiPatternCount, "antiPatternCount");
  const acCoverageRate = parseOptionalNumber(row.acCoverageRate, "acCoverageRate");

  if (complexityScore !== null) {
    current.complexityScore.push(complexityScore);
  }
  if (testCoverageRate !== null) {
    current.testCoverageRate.push(testCoverageRate);
  }
  if (technicalDebtMinutes !== null) {
    current.technicalDebtMinutes.push(technicalDebtMinutes);
  }
  if (antiPatternCount !== null) {
    current.antiPatternCount.push(antiPatternCount);
  }
  if (acCoverageRate !== null) {
    current.acCoverageRate.push(acCoverageRate);
  }

  perDay.set(date, current);
}

const trend: MetricPoint[] = [];

for (let offset = trendDays - 1; offset >= 0; offset -= 1) {
  const cursor = new Date(now.getTime() - offset * DAY_MS);
  const date = toUtcDateKey(cursor);
  const bucket = perDay.get(date);

  trend.push({
    date,
    complexityScore: average(bucket?.complexityScore ?? []),
    testCoverageRate: average(bucket?.testCoverageRate ?? []),
    technicalDebtMinutes: average(bucket?.technicalDebtMinutes ?? []),
    antiPatternCount: average(bucket?.antiPatternCount ?? []),
    acCoverageRate: average(bucket?.acCoverageRate ?? []),
  });
}

return trend;

};

const loadCodeMetricRows = async (
  userId: string,
  integrationIds: string[],
  sinceTrend: Date,
): Promise<CodeMetricRow[]> => {
  if (integrationIds.length === 0) {
    return [];
  }

  return db
    .select({
      measuredAt: analyticsCodeMetricSnapshots.measuredAt,
      complexityScore: analyticsCodeMetricSnapshots.complexityScore,
      testCoverageRate: analyticsCodeMetricSnapshots.testCoverageRate,
      technicalDebtMinutes: analyticsCodeMetricSnapshots.technicalDebtMinutes,
      antiPatternCount: analyticsCodeMetricSnapshots.antiPatternCount,
      acCoverageRate: analyticsCodeMetricSnapshots.acCoverageRate,
    })
    .from(analyticsCodeMetricSnapshots)
    .where(
      and(
        eq(analyticsCodeMetricSnapshots.userId, userId),
        inArray(analyticsCodeMetricSnapshots.integrationId, integrationIds),
        gte(analyticsCodeMetricSnapshots.measuredAt, sinceTrend),
      ),
    )
    .orderBy(
      analyticsCodeMetricSnapshots.measuredAt,
      analyticsCodeMetricSnapshots.createdAt,
      analyticsCodeMetricSnapshots.id,
    );
};

const buildCodeMetrics = (rows: CodeMetricRow[], trendDays: number, now: Date) => {
  const latestRow = rows[rows.length - 1];
  const previousRow = rows[rows.length - 2];

  const latest = latestRow ? toMetricSnapshot(latestRow) : emptyMetricSnapshot();
  const previous = previousRow ? toMetricSnapshot(previousRow) : emptyMetricSnapshot();

  return {
    latest,
    previous,
    deltas: {
      complexityScore: metricDelta(latest.complexityScore, previous.complexityScore),
      testCoverageRate: metricDelta(latest.testCoverageRate, previous.testCoverageRate),
      technicalDebtMinutes: metricDelta(latest.technicalDebtMinutes, previous.technicalDebtMinutes),
      antiPatternCount: metricDelta(latest.antiPatternCount, previous.antiPatternCount),
      acCoverageRate: metricDelta(latest.acCoverageRate, previous.acCoverageRate),
    },
    trend: buildTrend(rows, trendDays, now),
  };
};

const buildReviewScopeWhere = (integrations: AnalyticsIntegrationScope): SQL<unknown> | null => {
  const scopeConditions = integrations.map((integration) =>
    and(
      eq(aiReviewRuns.instanceUrl, integration.instanceUrl),
      eq(aiReviewRuns.projectId, integration.projectId),
    ),
  );

  if (scopeConditions.length === 0) {
    return null;
  }

  if (scopeConditions.length === 1) {
    return scopeConditions[0]!;
  }

  return or(...scopeConditions)!;
};

const emptyReviewAnalytics = (acCoverageRate: number | null): AnalyticsOverview["reviewAnalytics"] => ({
  reviewsByDay: [],
  reviewsByWeek: [],
  issuesPerReview: 0,
  reviewAcceptanceRate: null,
  acCoverageRate,
  reviewsInWindow: 0,
  findingsInWindow: 0,
});

const loadReviewAnalytics = async (
  integrations: AnalyticsIntegrationScope,
  sinceWindow: Date,
  sinceTrend: Date,
  acCoverageRate: number | null,
): Promise<AnalyticsOverview["reviewAnalytics"]> => {
  const reviewScopeWhere = buildReviewScopeWhere(integrations);
  if (reviewScopeWhere === null) {
    return emptyReviewAnalytics(acCoverageRate);
  }

const [reviewsByDayRows, reviewsByWeekRows, summaryRows] = await Promise.all([
  db
    .select({
      date: sql<string>`to_char(date_trunc('day', ${aiReviewRuns.createdAt} at time zone 'utc'), 'YYYY-MM-DD')`,
      count: count(),
    })
    .from(aiReviewRuns)
    .where(and(reviewScopeWhere, gte(aiReviewRuns.createdAt, sinceWindow)))
    .groupBy(sql`date_trunc('day', ${aiReviewRuns.createdAt} at time zone 'utc')`)
    .orderBy(sql`date_trunc('day', ${aiReviewRuns.createdAt} at time zone 'utc')`),
  db
    .select({
      week: sql<string>`to_char(date_trunc('week', ${aiReviewRuns.createdAt} at time zone 'utc'), 'IYYY-"W"IW')`,
      count: count(),
    })
    .from(aiReviewRuns)
    .where(and(reviewScopeWhere, gte(aiReviewRuns.createdAt, sinceTrend)))
    .groupBy(sql`date_trunc('week', ${aiReviewRuns.createdAt} at time zone 'utc')`)
    .orderBy(sql`date_trunc('week', ${aiReviewRuns.createdAt} at time zone 'utc')`),
  db
    .select({
      reviews: count(),
      findings: sql<number>`coalesce(sum(${aiReviewRuns.findingsCount}), 0)`,
      accepted: sql<number>`count(*) filter (where ${aiReviewRuns.feedback} = 'up')`,
      rejected: sql<number>`count(*) filter (where ${aiReviewRuns.feedback} = 'down')`,
    })
    .from(aiReviewRuns)
    .where(and(reviewScopeWhere, gte(aiReviewRuns.createdAt, sinceWindow)))
    .limit(1),
]);

const summary = summaryRows[0];
const reviewsInWindow = summary ? parseNonNegativeNumber(summary.reviews, "reviewsInWindow") : 0;

  const findingsInWindow = summary
    ? parseNonNegativeNumber(summary.findings, "findingsInWindow")
    : 0;
  const accepted = summary ? parseNonNegativeNumber(summary.accepted, "acceptedVotes") : 0;
  const rejected = summary ? parseNonNegativeNumber(summary.rejected, "rejectedVotes") : 0;
  const totalVotes = accepted + rejected;

  return {
    reviewsByDay: reviewsByDayRows.map((row) => ({
      date: parseRequiredString(row.date, "reviewsByDay.date"),
      count: parseNonNegativeNumber(row.count, "reviewsByDay.count"),
    })),
    reviewsByWeek: reviewsByWeekRows.map((row) => ({
      week: parseRequiredString(row.week, "reviewsByWeek.week"),
      count: parseNonNegativeNumber(row.count, "reviewsByWeek.count"),
    })),
    issuesPerReview: reviewsInWindow > 0 ? Math.round((findingsInWindow / reviewsInWindow) * 100) / 100 : 0,
    reviewAcceptanceRate:
      totalVotes > 0 ? Math.round((accepted / totalVotes) * 10_000) / 100 : null,
    acCoverageRate,
    reviewsInWindow,
    findingsInWindow,
  };
};

const loadUserActivity = async (
  userId: string,
  sinceWindow: Date,
): Promise<AnalyticsOverview["userActivity"]> => {
  const [commandsRows, featuresRows, durationRows] = await Promise.all([

const durations = durationRows.map((row) =>
  parseNonNegativeNumber(row.durationMs, "userActivity.sessionDurationMs"),
);
const medianRaw = percentile(durations, 0.5);

return {
  commandsUsed: commandsRows.map((row) => ({
    command: parseRequiredString(row.command, "userActivity.command"),
    count: parseNonNegativeNumber(row.count, "userActivity.commandCount"),
  })),
  featureAdoption: featuresRows.map((row) => ({
    feature: parseRequiredString(row.feature, "userActivity.feature"),
    count: parseNonNegativeNumber(row.count, "userActivity.featureCount"),
  })),
  averageSessionDurationMs:
    durations.length > 0
      ? Math.round(durations.reduce((sum, value) => sum + value, 0) / durations.length)
      : null,
  medianSessionDurationMs: medianRaw === null ? null : Math.round(medianRaw),
  sessionsMeasured: durations.length,
};

};

export const buildAnalyticsOverview = async (
  userId: string,
  options: BuildOverviewOptions = {},
): Promise<AnalyticsOverview> => {
  const windowDays = resolveDaysOption(options.windowDays, "windowDays", {
    ...WINDOW_DAYS_RANGE,
    fallback: DEFAULT_WINDOW_DAYS,
  });
  const trendDays = resolveDaysOption(options.trendDays, "trendDays", {
    ...TREND_DAYS_RANGE,
    fallback: DEFAULT_TREND_DAYS,
  });

  const now = new Date();
  const sinceWindow = new Date(now.getTime() - windowDays * DAY_MS);
  const sinceTrend = new Date(now.getTime() - trendDays * DAY_MS);

  const integrations = options.integrations ?? (await loadAnalyticsIntegrationScope(userId));
  const integrationIds = integrations.map((integration) => integration.id);

  const codeMetricRows = await loadCodeMetricRows(userId, integrationIds, sinceTrend);
  const codeMetrics = buildCodeMetrics(codeMetricRows, trendDays, now);
  const [reviewAnalytics, userActivity] = await Promise.all([
    loadReviewAnalytics(integrations, sinceWindow, sinceTrend, codeMetrics.latest.acCoverageRate),
    loadUserActivity(userId, sinceWindow),
  ]);

  return {
    generatedAt: now.toISOString(),
    windowDays,
    trendDays,
    codeMetrics,
    reviewAnalytics,
    userActivity,
  };
};

