import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type Dispatch,
  type SetStateAction,
} from "react"

import { getErrorMessage, resolveGitLabInstance } from "@/features/onboarding/model/flow.utils"
import type {
  OnboardingEventMetadata,
  OnboardingTrackedEvent,
  Project,
  WebhookSetupFeedback,
} from "@/features/onboarding/model/types"
import { connectIntegrationAndEnableIndexing } from "@/features/onboarding/hooks/integration-connect.shared"
import { parseJsonResponse } from "@/lib/http/response-json"

type UseOnboardingIntegrationConnectOptions = {
  gitlabInstance: string
  customInstance: string
  token: string
  setWebhookSetupFeedback: Dispatch<SetStateAction<WebhookSetupFeedback | null>>
  trackEvent?: (event: OnboardingTrackedEvent, metadata?: OnboardingEventMetadata) => void
}

type ProjectReviewState = {
  integrationId: string | null
  reviewMode: "quick" | "full"
  indexingStatus: string
}

const INDEXING_POLL_INTERVAL_MS = 4_000

const asRecord = (value: unknown): Record<string, unknown> | null =>
  value && typeof value === "object" ? (value as Record<string, unknown>) : null

const buildIndexingStatusLabel = (indexingStatus: string) => {
  if (indexingStatus === "ready") {
    return "Indexing complete. Full context is ready."
  }
  if (indexingStatus === "failed") {
    return "Indexing failed. Continuing in Quick Review mode."
  }
  if (indexingStatus === "disabled") {
    return "Indexing is disabled for this integration."
  }
  return "Indexing in progress. Quick Review uses MR metadata and diff context first."
}

export function useOnboardingIntegrationConnect({
  gitlabInstance,
  customInstance,
  token,
  setWebhookSetupFeedback,
  trackEvent,
}: UseOnboardingIntegrationConnectOptions) {
  const integrationConnectPromiseByKeyRef = useRef(new Map<string, Promise<string | null>>())
  const [projectReviewStateByProjectId, setProjectReviewStateByProjectId] = useState<
    Record<string, ProjectReviewState>
  >({})

  useEffect(() => {
    const quickReviewEntries = Object.entries(projectReviewStateByProjectId).filter(
      ([, state]) => state.integrationId && state.reviewMode === "quick",
    )
    if (quickReviewEntries.length === 0) {
      return
    }

    let cancelled = false

    const pollStatus = async () => {
      await Promise.allSettled(
        quickReviewEntries.map(async ([projectId, state]) => {
          const integrationId = state.integrationId
          if (!integrationId || cancelled) {
            return
          }

          const response = await fetch(
            `/api/gitlab/integrations/${integrationId}/index/runs?page=1&limit=1`,
            {
              method: "GET",
              headers: {
                "content-type": "application/json",
              },
            },
          )

          const parsedPayload = await parseJsonResponse(response)
          const payload = parsedPayload.ok ? parsedPayload.value : null
          if (!response.ok || cancelled) {
            return
          }

          const root = asRecord(payload)
          const rows = Array.isArray(root?.data) ? root.data : []
          const topRow = asRecord(rows[0])

        const nextStatus =
          typeof topRow?.status === "string" && topRow.status.trim().length > 0
            ? topRow.status
            : "indexing"

        setProjectReviewStateByProjectId((current) => {
          const prev = current[projectId]
          if (!prev || prev.integrationId !== integrationId) {
            return current
          }

          const nextMode = nextStatus === "ready" ? "full" : "quick"
          if (
            prev.reviewMode === nextMode &&
            prev.indexingStatus === nextStatus
          ) {
            return current
          }

          if (prev.reviewMode === "quick" && nextMode === "full") {
            trackEvent?.("onboarding_full_review_ready", {
              projectId,
              reviewMode: "full",
            })
          }

          return {
            ...current,
            [projectId]: {
              ...prev,
              reviewMode: nextMode,
              indexingStatus: nextStatus,
            },
          }
        })
      }),
    )
  }

  void pollStatus()
  const timer = window.setInterval(() => {
    void pollStatus()
  }, INDEXING_POLL_INTERVAL_MS)

  return () => {
    cancelled = true
    window.clearInterval(timer)
  }
}, [projectReviewStateByProjectId, trackEvent])

const connectIntegration = useCallback(
  async (project: Project) => {
    const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
    const connectKey = `${normalizedInstance}::${project.id}`

const pendingConnect = integrationConnectPromiseByKeyRef.current.get(connectKey)
if (pendingConnect) {
  return pendingConnect
}

const connectPromise = (async () => {
  setProjectReviewStateByProjectId((current) => ({
    ...current,
    [project.id]: {
      integrationId: current[project.id]?.integrationId ?? null,
      reviewMode: "quick",
      indexingStatus: "connecting",
    },
  }))

try {
  const result = await connectIntegrationAndEnableIndexing({
    project,
    normalizedInstance,
    token,
  })

  setProjectReviewStateByProjectId((current) => ({
    ...current,
    [project.id]: {
      integrationId: result.integrationId,
      reviewMode: "quick",
      indexingStatus: result.warning ? "warning" : "indexing",
    },
  }))

  if (result.warning) {
    setWebhookSetupFeedback({
      kind: "warning",
      message: result.warning,
    })
    return result.integrationId
  }

  const jobIdsMessage =
    result.planJobId && result.reconcileJobId
      ? ` Plan job: ${result.planJobId}. Reconcile job: ${result.reconcileJobId}.`
      : ""
  setWebhookSetupFeedback({
    kind: "success",
    message: `Webhook active for ${project.path}. Indexing queued for ${result.branch}.${jobIdsMessage}`,
  })

  return result.integrationId
} catch (error) {

        setProjectReviewStateByProjectId((current) => ({
          ...current,
          [project.id]: {
            integrationId: current[project.id]?.integrationId ?? null,
            reviewMode: "quick",
            indexingStatus: "failed",
          },
        }))
        setWebhookSetupFeedback({
          kind: "warning",
          message: `Webhook setup warning: ${getErrorMessage(error)}`,
        })

        return null
      } finally {
        integrationConnectPromiseByKeyRef.current.delete(connectKey)
      }
    })()

    integrationConnectPromiseByKeyRef.current.set(connectKey, connectPromise)
    return connectPromise
  },
  [customInstance, gitlabInstance, setWebhookSetupFeedback, token],
)

const getProjectReviewContext = useCallback(
  (projectId: string | null | undefined) => {
    if (!projectId) {
      return {
        reviewMode: "quick" as const,
        indexingStatusLabel:
          "Indexing in progress. Quick Review uses MR metadata and diff context first.",
      }
    }

    const state = projectReviewStateByProjectId[projectId]
    if (!state) {
      return {
        reviewMode: "quick" as const,
        indexingStatusLabel:
          "Indexing in progress. Quick Review uses MR metadata and diff context first.",
      }
    }

    return {
      reviewMode: state.reviewMode,
      indexingStatusLabel: buildIndexingStatusLabel(state.indexingStatus),
    }
  },
  [projectReviewStateByProjectId],
)

  const getProjectIntegrationId = useCallback(
    (projectId: string | null | undefined) => {
      if (!projectId) {
        return null
      }
      return projectReviewStateByProjectId[projectId]?.integrationId ?? null
    },
    [projectReviewStateByProjectId],
  )

  return {
    connectIntegration,
    getProjectReviewContext,
    getProjectIntegrationId,
    projectReviewStateByProjectId,
  }
}

import {
  type EnsureMergeRequestSourceBranchIndexingDeps,
  type EnsureMergeRequestSourceBranchIndexingFn,
  type PrewarmMergeRequestSourceBranchesDeps,
  type PrewarmMergeRequestSourceBranchesResult,
} from '@/lib/indexing/mr-auto-index-types'
import { isEnvEnabled } from '@/lib/indexing/mr-auto-index-utils'
import { toNonEmptyString } from '@/lib/indexing/string-utils'

const toPositiveInt = (value: string | undefined, fallback: number) => {
  const parsed = Number.parseInt(String(value ?? '').trim(), 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback
  }

  return parsed
}

export const defaultPrewarmLimit = () => toPositiveInt(process.env.INDEXER_MR_PREWARM_LIMIT, 5)

export const createDefaultPrewarmDeps = (args: {
  loadIntegration: EnsureMergeRequestSourceBranchIndexingDeps['loadIntegration']
  ensureMergeRequestSourceBranchIndexing: EnsureMergeRequestSourceBranchIndexingFn
}): PrewarmMergeRequestSourceBranchesDeps => ({
  loadIntegration: args.loadIntegration,
  listOpenMergeRequests: async ({ instanceUrl, token, projectId, limit }) => {
    const { listProjectOpenMergeRequests } = await import('@/lib/gitlab/client')
    const rows = await listProjectOpenMergeRequests(instanceUrl, token, projectId, limit)
    return rows.map((row) => ({
      iid: String(row.iid ?? '').trim(),
      sourceBranch: toNonEmptyString(row.source_branch),
      sourceHeadSha: toNonEmptyString(row.sha),
    }))
  },
  ensureMergeRequestSourceBranchIndexing: args.ensureMergeRequestSourceBranchIndexing,
  resolvePrewarmLimit: defaultPrewarmLimit,
  isPrewarmEnabled: () => isEnvEnabled(process.env.INDEXER_MR_PREWARM_ENABLED),
})

export const prewarmMergeRequestSourceBranches = async (
  args: {
    integrationId: string
    limit?: number
  },
  deps: PrewarmMergeRequestSourceBranchesDeps,
): Promise<PrewarmMergeRequestSourceBranchesResult> => {
  const limit = Math.max(1, args.limit ?? deps.resolvePrewarmLimit())
  if (!deps.isPrewarmEnabled()) {
    return {
      enabled: false,
      limit,
      scanned: 0,
      queued: 0,
      alreadyReady: 0,
      alreadyPending: 0,
      skipped: 0,
      errored: 0,
    }
  }

  const integration = await deps.loadIntegration(args.integrationId)

  if (!integration) {
    return {
      enabled: true,
      limit,
      scanned: 0,
      queued: 0,
      alreadyReady: 0,
      alreadyPending: 0,
      skipped: 0,
      errored: 1,
    }
  }

  const mergeRequests = await deps.listOpenMergeRequests({
    instanceUrl: integration.instanceUrl,
    token: integration.token,
    projectId: integration.projectId,
    limit,
  })

  const summary: PrewarmMergeRequestSourceBranchesResult = {
    enabled: true,
    limit,
    scanned: mergeRequests.length,
    queued: 0,
    alreadyReady: 0,
    alreadyPending: 0,
    skipped: 0,
    errored: 0,
  }

  for (const mergeRequest of mergeRequests) {
    const result = await deps.ensureMergeRequestSourceBranchIndexing({
      integrationId: args.integrationId,
      mergeRequestIid: mergeRequest.iid,
      sourceBranchHint: mergeRequest.sourceBranch,
      sourceHeadShaHint: mergeRequest.sourceHeadSha,
      trigger: 'prewarm',
    })

    if (result.decision === 'queued') {
      summary.queued += 1
      continue
    }

    if (result.decision === 'already_ready') {
      summary.alreadyReady += 1
      continue
    }

    if (result.decision === 'already_pending') {
      summary.alreadyPending += 1
      continue
    }

    if (result.decision === 'skipped') {
      summary.skipped += 1
      continue
    }

    summary.errored += 1
  }

  return summary
}

