export const persistDescription = async ({
  userId,
  scope,
  model,
  patch,
  markdown,
}: {
  userId: string
  scope: DescriptionScope | null
  model: string
  patch: string
  markdown: string
}) => {
  if (!scope) {
    return null
  }

  if (!markdown.trim()) {
    throw new Error("AI did not return an MR description.")
  }

  const [{ db }, { aiReviewDescriptions }] = await Promise.all([
    import("@/lib/db"),
    import("@/lib/db/schema"),
  ])

  const inserted = await db
    .insert(aiReviewDescriptions)
    .values({
      userId,
      instanceUrl: scope.instanceUrl,
      projectId: scope.projectId,
      mergeRequestIid: scope.mergeRequestIid,
      model,
      patchLength: patch.length,
      patchHash: sha256Hex(patch),
      markdown,
    })
    .returning({
      id: aiReviewDescriptions.id,
    })

  return inserted[0]?.id ?? null
}

const toPersistedDescription = (row: {
  id: string
  markdown: string
  createdAt: Date
}): PersistedDescription => ({
  id: row.id,
  markdown: row.markdown,
  createdAt: row.createdAt.toISOString(),
})

export const streamWithPersistence = ({
  stream,
  onComplete,
}: {
  stream: ReadableStream<Uint8Array>
  onComplete: (markdown: string) => Promise<void>
}) => {
  const decoder = new TextDecoder()
  const encodedChunks: Uint8Array[] = []

  return new ReadableStream<Uint8Array>({
    start(controller) {
      const reader = stream.getReader()

      void (async () => {
        try {
          while (true) {
            const { done, value } = await reader.read()
            if (done) {
              break
            }

            if (value) {
              encodedChunks.push(value)
              controller.enqueue(value)
            }
          }

          const markdown = encodedChunks
            .map((chunk) => decoder.decode(chunk, { stream: true }))
            .join("") + decoder.decode()

          await onComplete(sanitizeAssistantMarkdown(markdown))
          controller.close()
        } catch (error) {
          controller.error(error)
        } finally {
          reader.releaseLock()
        }
      })()
    },
    cancel(reason) {
      return stream.cancel(reason)
    },
  })
}

export const loadLatestPersistedDescription = async ({
  userId,
  scope,
}: {
  userId: string
  scope: DescriptionScope
}) => {
  const [{ db }, { aiReviewDescriptions }] = await Promise.all([
    import("@/lib/db"),
    import("@/lib/db/schema"),
  ])

  const rows = await db
    .select({
      id: aiReviewDescriptions.id,
      markdown: aiReviewDescriptions.markdown,
      createdAt: aiReviewDescriptions.createdAt,
    })
    .from(aiReviewDescriptions)
    .where(
      and(
        eq(aiReviewDescriptions.userId, userId),
        eq(aiReviewDescriptions.instanceUrl, scope.instanceUrl),
        eq(aiReviewDescriptions.projectId, scope.projectId),
        eq(aiReviewDescriptions.mergeRequestIid, scope.mergeRequestIid),
      ),
    )
    .orderBy(desc(aiReviewDescriptions.createdAt))
    .limit(1)

  return rows[0] ? toPersistedDescription(rows[0]) : null
}

