export function useMergeRequestDiffViewerController({
  instanceUrl,
  token,
  integrationId,
  projectId,
  mergeRequestIid,
  nav,
}: MergeRequestDiffViewerProps): MergeRequestDiffPanelProps {
  const router = useRouter()
  const pathname = usePathname()
  const model = useMergeRequestDiffModel({
    instanceUrl,
    token,
    integrationId,
    projectId,
    mergeRequestIid,
  })

  const getFileKey = useCallback((file: FileDiffMetadata) => {
    return getStableFileKey(file)
  }, [])
  const { setCollapsedFileKeys } = model.ui
  const reviewSeverityCounts = model.ai.reviewFindings.reduce(
    (counts, finding) => {
      if (finding.severity === "high") {
        counts.high += 1
      } else if (finding.severity === "med") {
        counts.med += 1
      } else {
        counts.low += 1
      }
      return counts
    },
    { high: 0, med: 0, low: 0 },
  )

const toggleFileCollapsed = useCallback(
  (file: FileDiffMetadata) => {
    const key = getFileKey(file)
    setCollapsedFileKeys((current) => {
      const next = new Set(current)
      if (next.has(key)) {
        next.delete(key)
      } else {
        next.add(key)
      }
      return next
    })
  },
  [getFileKey, setCollapsedFileKeys],
)
const areAllFilesCollapsed = useMemo(() => {
  const filteredFiles = model.derived.filteredFiles
  if (filteredFiles.length === 0) {
    return false
  }
  return filteredFiles.every((file) =>
    model.ui.collapsedFileKeys.has(getFileKey(file)),
  )
}, [getFileKey, model.derived.filteredFiles, model.ui.collapsedFileKeys])
const toggleAllFilesCollapsed = useCallback(() => {
  const filteredFileKeys = model.derived.filteredFiles.map((file) => getFileKey(file))
  if (filteredFileKeys.length === 0) {
    return
  }
  setCollapsedFileKeys((current) => {
    const next = new Set(current)
    const shouldExpandAll = filteredFileKeys.every((key) => next.has(key))
    for (const key of filteredFileKeys) {
      if (shouldExpandAll) {
        next.delete(key)
      } else {
        next.add(key)
      }
    }
    return next
  })
}, [getFileKey, model.derived.filteredFiles, setCollapsedFileKeys])

