export type AnalyticsTrackEvent =
  | {
      event: "command_used";
      command: string;
      feature?: string;
      sessionId?: string;
      metadata?: Record<string, unknown>;
    }
  | {
      event: "feature_opened";
      feature: string;
      sessionId?: string;
      metadata?: Record<string, unknown>;
    }
  | {
      event: "session_duration";
      feature?: string;
      durationMs: number;
      sessionId?: string;
      metadata?: Record<string, unknown>;
    };

const ENDPOINT = "/api/analytics/track";

export const trackAnalyticsEvent = (payload: AnalyticsTrackEvent) => {
  if (typeof window === "undefined") {
    throw new Error("trackAnalyticsEvent must be called in a browser runtime.");
  }

  const body = JSON.stringify(payload);

  if (typeof navigator.sendBeacon === "function") {
    const blob = new Blob([body], { type: "application/json" });
    if (navigator.sendBeacon(ENDPOINT, blob)) {
      return;
    }
  }

  void fetch(ENDPOINT, {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body,
    keepalive: true,
  }).catch((error) => {
    if (process.env.NODE_ENV !== "production") {
      const reportErrorFn = (globalThis as { reportError?: (value: unknown) => void }).reportError;
      reportErrorFn?.(error);
    }
  });
};

