const execFileAsync = promisify(realExecFile)

const createArchive = async (files: Record<string, string>) => {
  const root = await mkdtemp(path.join(os.tmpdir(), "argus-repo-workspace-test-"))
  const repoDir = path.join(root, "repo")
  await mkdir(repoDir, { recursive: true })

  for (const [relativePath, content] of Object.entries(files)) {
    const absolutePath = path.join(repoDir, relativePath)
    await mkdir(path.dirname(absolutePath), { recursive: true })
    await writeFile(absolutePath, content, "utf8")
  }

  const archiveRoot = path.join(root, "archive")
  await mkdir(archiveRoot, { recursive: true })
  const archivePath = path.join(archiveRoot, "repo.tar.gz")
  await execFileAsync("tar", ["-czf", archivePath, "-C", root, "repo"])

  return {
    root,
    archivePath,
    archiveRoot,
  }
}

describe("prepareRepoWorkspace", () => {

test("downloads once, extracts once, and cleanup is idempotent", async () => {
  const archive = await createArchive({
    "src/a.ts": "export const a = 1\n",
    "README.md": "# Test\n",
  })

  try {
    const mod = await import(`@/lib/indexing/repo-workspace.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
    const downloadArchive = mock(async () => ({ archivePath: archive.archivePath }))

    const workspace = await mod.prepareRepoWorkspace({
      source: { downloadArchive } as never,
      integrationId: "integration-1",
      sha: "head-sha-1",
    })

    expect(downloadArchive).toHaveBeenCalledTimes(1)
    expect(workspace.archivePath).toBe(archive.archivePath)
    expect(workspace.rootDir.length).toBeGreaterThan(0)

    const files = await workspace.listFiles()
    expect(files).toContain("README.md")
    expect(files).toContain("src/a.ts")

    const file = await workspace.readFile("src/a.ts")
    expect(file.toString("utf8")).toContain("export const a = 1")

    await workspace.cleanup()
    await workspace.cleanup()

    await expect(access(archive.archiveRoot)).rejects.toBeDefined()
  } finally {
    await rm(archive.root, { recursive: true, force: true }).catch(() => {})
  }
})

  test("rejects traversal outside repository root", async () => {
    const archive = await createArchive({
      "src/a.ts": "export const a = 1\n",
    })

    try {
      const mod = await import(`@/lib/indexing/repo-workspace.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
      const workspace = await mod.prepareRepoWorkspace({
        source: { downloadArchive: async () => ({ archivePath: archive.archivePath }) } as never,
        integrationId: "integration-1",
        sha: "head-sha-1",
      })

      try {
        await expect(workspace.readFile("../outside.txt")).rejects.toThrow(
          "Workspace path escapes repository root.",
        )
      } finally {
        await workspace.cleanup()
      }
    } finally {
      await rm(archive.root, { recursive: true, force: true }).catch(() => {})
    }
  })
})

import { execFile } from "node:child_process"
import { mkdtemp, readdir, readFile, rm, stat } from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { promisify } from "node:util"

import type { GitLabSource } from "@argus/contracts-indexing"

const execFileAsync = promisify(execFile)

export type RepoWorkspaceMetrics = {
  downloadMs: number
  extractMs: number
  archiveBytes: number
}

export type RepoWorkspace = {
  rootDir: string
  archivePath: string
  metrics: RepoWorkspaceMetrics
  readFile: (relativePath: string) => Promise<Buffer>
  listFiles: () => Promise<string[]>
  cleanup: () => Promise<void>
}

const normalizeRelativePath = (relativePath: string) =>
  relativePath.split(path.sep).join("/")

const ensureWithinRoot = (root: string, value: string) => {
  const resolvedRoot = path.resolve(root)
  const candidate = path.resolve(value)
  const rootWithSep = `${resolvedRoot}${path.sep}`
  if (candidate !== resolvedRoot && !candidate.startsWith(rootWithSep)) {
    throw new Error("Workspace path escapes repository root.")
  }

  return candidate
}

const findExtractedRoot = async (extractDir: string): Promise<string> => {
  const entries = await readdir(extractDir, { withFileTypes: true })
  const directories = entries.filter((entry) => entry.isDirectory())

  if (directories.length === 1) {
    return path.join(extractDir, directories[0].name)
  }

  return extractDir
}

const listRepoFiles = async (root: string): Promise<string[]> => {
  const files: string[] = []

  const walk = async (currentDir: string) => {
    const entries = await readdir(currentDir, { withFileTypes: true })
    for (const entry of entries) {
      const absolutePath = path.join(currentDir, entry.name)
      if (entry.isDirectory()) {
        await walk(absolutePath)
        continue
      }

      if (entry.isFile()) {
        files.push(normalizeRelativePath(path.relative(root, absolutePath)))
      }
    }
  }

  await walk(root)
  return files
}

export const prepareRepoWorkspace = async (args: {
  source: Pick<GitLabSource, "downloadArchive">
  integrationId: string
  sha: string
}): Promise<RepoWorkspace> => {
  const downloadStartedAt = Date.now()
  const { archivePath } = await args.source.downloadArchive({
    integrationId: args.integrationId,
    sha: args.sha,
  })
  const downloadMs = Date.now() - downloadStartedAt

  const archiveStats = await stat(archivePath)
  const extractStartedAt = Date.now()
  const extractDir = await mkdtemp(path.join(os.tmpdir(), "argus-indexer-workspace-"))
  await execFileAsync("tar", ["-xzf", archivePath, "-C", extractDir])
  const repoRoot = await findExtractedRoot(extractDir)
  const extractMs = Date.now() - extractStartedAt

  let cleanedUp = false
  const cleanup = async () => {
    if (cleanedUp) {
      return
    }
    cleanedUp = true

    await rm(extractDir, { recursive: true, force: true }).catch(() => {})
    await rm(path.dirname(archivePath), { recursive: true, force: true }).catch(() => {})
  }

  return {
    rootDir: repoRoot,
    archivePath,
    metrics: {
      downloadMs,
      extractMs,
      archiveBytes: archiveStats.size,
    },
    listFiles: async () => listRepoFiles(repoRoot),
    readFile: async (relativePath: string) => {
      const normalized = relativePath.trim()
      if (!normalized || path.isAbsolute(normalized)) {
        throw new Error("Workspace path escapes repository root.")
      }

      const absolutePath = ensureWithinRoot(repoRoot, path.join(repoRoot, normalized))
      return readFile(absolutePath)
    },
    cleanup,
  }
}

import type { FileDiffMetadata } from "@pierre/diffs";

import { normalizePatchPath } from "@/features/review/model/diff/viewer-utils";

import type {
	InlineDiffAnnotation,
	ManualDraftAnnotationMetadata,
	SelectedLineRange,
} from "./panel-types";

export const EMPTY_INLINE_ANNOTATIONS: InlineDiffAnnotation[] = [];

export const escapeAttributeValueForSelector = (value: string) =>
	value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');

export const normalizeFileCandidatePaths = (file: FileDiffMetadata) => {
	const normalizedPaths: string[] = [];
	const seenNormalizedPaths = new Set<string>();

	for (const path of [file.name, file.prevName]) {
		if (typeof path !== "string" || path.trim().length === 0) {
			continue;
		}

		const normalizedPath = normalizePatchPath(path);
		if (seenNormalizedPaths.has(normalizedPath)) {
			continue;
		}

		seenNormalizedPaths.add(normalizedPath);
		normalizedPaths.push(normalizedPath);
	}

	return normalizedPaths;
};

export const toLineRange = (range: SelectedLineRange) => {
	return {
		start: Math.min(range.start, range.end),
		end: Math.max(range.start, range.end),
	};
};

export const getBasename = (filePath: string) => {
	const parts = filePath.split("/");
	return parts[parts.length - 1] || filePath;
};

export const isManualDraftAnnotation = (
	annotation: InlineDiffAnnotation,
): annotation is InlineDiffAnnotation & {
	metadata: ManualDraftAnnotationMetadata;
} => {
	const metadata = annotation.metadata;
	return (
		metadata !== undefined &&
		typeof metadata === "object" &&
		"kind" in metadata &&
		metadata.kind === "manual-draft"
	);
};

export type GraphRange = {
  start: { row: number; column: number }
  end: { row: number; column: number }
}

export const toPositiveInt = (value: unknown) =>
  typeof value === "number" && Number.isFinite(value) && value >= 0
    ? Math.floor(value)
    : null

export const toOptionalString = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

export const isGraphRange = (value: unknown): value is GraphRange => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return false
  }
  const record = value as Record<string, unknown>
  const start = record.start
  const end = record.end
  if (!start || typeof start !== "object" || Array.isArray(start)) {
    return false
  }
  if (!end || typeof end !== "object" || Array.isArray(end)) {
    return false
  }
  const startRecord = start as Record<string, unknown>
  const endRecord = end as Record<string, unknown>
  const startRow = toPositiveInt(startRecord.row)
  const startColumn = toPositiveInt(startRecord.column)
  const endRow = toPositiveInt(endRecord.row)
  const endColumn = toPositiveInt(endRecord.column)
  return startRow !== null && startColumn !== null && endRow !== null && endColumn !== null
}

import { isPrivateOrLocalHost } from "@/lib/http/private-host"

const DEFAULT_AI_API_URL = "https://api.openai.com/v1"
const DEFAULT_AI_MODEL = "gpt-4o-mini"

export type ReviewRequestPayload = {
  patch?: unknown
  apiUrl?: unknown
  model?: unknown
  token?: unknown
  instanceUrl?: unknown
