import { randomUUID } from "node:crypto"

import { normalizeGitLabInstanceUrl } from "@/lib/gitlab/instance"

import {
  DIFF_CACHE_TTL_MS,
  DIFF_FILE_CHUNK_BATCH_SIZE,
  DIFF_LIMITS,
} from "./constants"
import {
  buildCacheKey,
  getFreshCacheEntry,
  setCacheEntry,
  trimCache,
} from "./cache"
import { GitLabDiffServiceError } from "./error"
import {
  buildFilesById,
  buildManifestMode,
  buildManifestResponse,
  buildParsedFiles,
  buildParsedFilesFromChangesPayload,
  countDiffStats,
  normalizeCursor,
} from "./parsing"
import {
  loadChangesPayload,
  loadMergeRequestDetails,
  loadRawDiffText,
} from "./api"
import {
  markTokenStaleWhenAuthFails,
  resolveTokenForRequest,
} from "./token"
import {
  type DiffFileRequest,
  type DiffManifestCacheEntry,
  type DiffManifestRequest,
  type DiffFileResponseData,
} from "./types"

const buildAndCacheManifest = async (request: DiffManifestRequest) => {
  const normalizedInstanceUrl = normalizeGitLabInstanceUrl(request.instanceUrl)
  const normalizedProjectId = request.projectId.trim()
  const normalizedMergeRequestIid = request.mergeRequestIid.trim()
  const normalizedIntegrationId = request.integrationId?.trim() || undefined

  if (!normalizedProjectId || !normalizedMergeRequestIid) {
    throw new GitLabDiffServiceError("Project and merge request are required.", {
      status: 400,
      code: "GITLAB_INVALID_REQUEST",
    })
  }

const cacheKey = buildCacheKey({
  userId: request.userId,
  instanceUrl: normalizedInstanceUrl,
  projectId: normalizedProjectId,
  mergeRequestIid: normalizedMergeRequestIid,
})

const cached = getFreshCacheEntry(cacheKey)
if (cached) {
  return cached
}

const tokenResult = await resolveTokenForRequest({
  userId: request.userId,
  instanceUrl: normalizedInstanceUrl,
  requestToken: request.requestToken,
  integrationId: normalizedIntegrationId,
  projectId: normalizedProjectId,
})

try {
  const [mergeRequestDetails, rawDiff] = await Promise.all([
    loadMergeRequestDetails({
      instanceUrl: normalizedInstanceUrl,
      token: tokenResult.token,
      projectId: normalizedProjectId,
      mergeRequestIid: normalizedMergeRequestIid,
    }),
    loadRawDiffText({
      instanceUrl: normalizedInstanceUrl,
      token: tokenResult.token,
      projectId: normalizedProjectId,
      mergeRequestIid: normalizedMergeRequestIid,
    }),
  ])

  let parsedFiles = buildParsedFiles({
    patchText: rawDiff.patchText,
    exceeded: rawDiff.exceeded,
  })
  let additions = 0
  let deletions = 0
  let estimatedBytesKnown = false
  let totalBytes = rawDiff.totalBytes

  if (rawDiff.patchText.trim()) {
    const stats = countDiffStats(rawDiff.patchText)
    additions = stats.additions
    deletions = stats.deletions
    estimatedBytesKnown = !rawDiff.exceeded
  }

if (!rawDiff.patchText.trim() || parsedFiles.length === 0) {
  const changesPayload = await loadChangesPayload({
    instanceUrl: normalizedInstanceUrl,
    token: tokenResult.token,
    projectId: normalizedProjectId,
    mergeRequestIid: normalizedMergeRequestIid,
  })
  const changesResult = buildParsedFilesFromChangesPayload(changesPayload)
  if (changesResult.files.length > 0) {
    parsedFiles = changesResult.files
    additions = changesResult.additions
    deletions = changesResult.deletions
    if (!rawDiff.patchText.trim()) {
      totalBytes = changesResult.estimatedBytesTotal ?? totalBytes
      estimatedBytesKnown = !rawDiff.exceeded && changesResult.estimatedBytesTotal !== null
    }
  }
}

if (parsedFiles.length === 0 && !rawDiff.exceeded) {
  throw new GitLabDiffServiceError("Merge request has no diff content to render.", {
    status: 404,
    code: "GITLAB_DIFF_EMPTY",
  })
}

const mode = buildManifestMode({
  exceeded: rawDiff.exceeded,
  parsedFiles,
})

const payload = buildManifestResponse({
  parsedFiles,
  mode,
  mergeRequestDetails,
  projectId: normalizedProjectId,
  mergeRequestIid: normalizedMergeRequestIid,
  totalBytes,
  estimatedBytesKnown,
  additions,
  deletions,
})

const entry: DiffManifestCacheEntry = {
  key: randomUUID(),
  expiresAt: Date.now() + DIFF_CACHE_TTL_MS,
  payload,
  filesById: buildFilesById(parsedFiles),
}

setCacheEntry(cacheKey, entry)

    trimCache()
    return entry
  } catch (error) {
    if (error instanceof GitLabDiffServiceError) {
      await markTokenStaleWhenAuthFails({
        userId: request.userId,
        instanceUrl: normalizedInstanceUrl,
        tokenSource: tokenResult.source,
        errorCode: error.code,
      })
    }
    throw error
  }
}

export const getDiffManifest = async (request: DiffManifestRequest) => {
  const entry = await buildAndCacheManifest(request)
  return entry.payload
}

export const getDiffFile = async (request: DiffFileRequest) => {
  const entry = await buildAndCacheManifest(request)
  const file = entry.filesById.get(request.fileId)
  if (!file) {
    throw new GitLabDiffServiceError("Requested file was not found in the diff manifest.", {
      status: 404,
      code: "GITLAB_INVALID_REQUEST",
    })
  }

  if (file.contentState === "requires_external") {
    throw new GitLabDiffServiceError(
      "Requested file exceeds in-app review limits and must be reviewed in GitLab.",
      {
        status: 413,
        code: "GITLAB_DIFF_FILE_TOO_LARGE",
      },
    )
  }

  const cursor = normalizeCursor(request.cursor)
  const batch = file.chunks.slice(cursor, cursor + DIFF_FILE_CHUNK_BATCH_SIZE)
  const nextCursor = cursor + batch.length
  const done = nextCursor >= file.chunks.length

  return {
    data: {
      fileId: request.fileId,
      done,
      nextCursor: done ? null : String(nextCursor),
      chunks: batch,
      truncated: file.truncated,
    } satisfies DiffFileResponseData,
  }
}

