  const [autoRefresh, setAutoRefresh] = useState(true)
  const inFlightRequestRef = useRef<AbortController | null>(null)
  const inFlightRequestKeyRef = useRef<string | null>(null)

  const loadRuns = useCallback(
    async (opts: { quiet?: boolean; skipIfInFlightDuplicate?: boolean; page?: number } = {}) => {
      const quiet = opts.quiet ?? false
      const page = opts.page ?? currentPage

let requestController: AbortController | null = null
if (!quiet) setIsLoading(true)
setErrorMessage("")

try {
  const params = new URLSearchParams()
  if (appliedFilters.traceId.trim())
    params.set("traceId", appliedFilters.traceId.trim())
  if (appliedFilters.status !== "all")
    params.set("status", appliedFilters.status)
  const windowHours = Number.parseInt(appliedFilters.windowHours, 10)
  if (Number.isFinite(windowHours) && windowHours > 0)
    params.set("windowHours", String(windowHours))
  params.set("page", String(page))
  params.set("limit", String(RUNS_PAGE_SIZE))
  const requestKey = params.toString()

  if (
    opts.skipIfInFlightDuplicate &&
    shouldSkipPollingRequest({
      isVisible: isPageVisible(),
      inFlightRequestKey: inFlightRequestKeyRef.current,
    })
  )
    return

  if (inFlightRequestRef.current) inFlightRequestRef.current.abort()
  const controller = new AbortController()
  requestController = controller
  inFlightRequestRef.current = controller
  inFlightRequestKeyRef.current = requestKey

  const response = await fetch(`/api/observability/ai-runs?${requestKey}`, {
    method: "GET",
    signal: controller.signal,
  })
  const parsedPayload = await parseJsonResponse(response)
  const payload = parsedPayload.ok ? parsedPayload.value : null

      if (!response.ok)
        throw new Error(extractErrorMessage(payload, "Failed to load AI runs."))

      const typedPayload = payload as ObservabilityAiRunsPayload | null
      setRuns(Array.isArray(typedPayload?.data) ? typedPayload.data : [])
      setMeta(typedPayload?.meta ?? null)
      setCurrentPage(typedPayload?.meta?.page ?? page)
      setLastRefreshedAt(new Date())
    } catch (error) {
      if (error instanceof Error && error.name === "AbortError") return
      setRuns([])
      setMeta(null)
      setErrorMessage(
        error instanceof Error ? error.message : "Failed to load AI runs.",
      )
    } finally {
      if (requestController && inFlightRequestRef.current === requestController) {
        inFlightRequestRef.current = null
        inFlightRequestKeyRef.current = null
      }
      if (!quiet) setIsLoading(false)
    }
  },
  [appliedFilters, currentPage],
)

useEffect(() => {
  if (!autoRefresh) return
  const timer = window.setInterval(() => {
    if (!isPageVisible()) return
    void loadRuns({ quiet: true, skipIfInFlightDuplicate: true })
  }, AUTO_REFRESH_MS)
  return () => window.clearInterval(timer)
}, [autoRefresh, loadRuns])

useEffect(() => {
  if (!autoRefresh) return

  const refreshOnReturn = () => {
    if (!isPageVisible()) return
    void loadRuns({ quiet: true, skipIfInFlightDuplicate: true })
  }

  document.addEventListener("visibilitychange", refreshOnReturn)
  window.addEventListener("focus", refreshOnReturn)

  return () => {
    document.removeEventListener("visibilitychange", refreshOnReturn)
    window.removeEventListener("focus", refreshOnReturn)
  }
}, [autoRefresh, loadRuns])

useEffect(() => {
  return () => {
    inFlightRequestRef.current?.abort()
    inFlightRequestRef.current = null
    inFlightRequestKeyRef.current = null
  }
}, [])

useEffect(() => {
  void loadRuns()
}, [loadRuns])

const handleSubmit = useCallback(() => {
  setAppliedFilters({ ...draftFilters })
  setCurrentPage(1)
}, [draftFilters])

const handleRefresh = useCallback(() => {
  void loadRuns({ page: currentPage })
}, [currentPage, loadRuns])

const handleNextPage = useCallback(() => {
  if (!meta?.hasNextPage || isLoading) return
  setCurrentPage((page) => page + 1)
}, [isLoading, meta?.hasNextPage])

const handlePreviousPage = useCallback(() => {
  if (currentPage <= 1 || isLoading) return
  setCurrentPage((page) => Math.max(1, page - 1))
}, [currentPage, isLoading])

const summary = useMemo(() => {
  const success = runs.filter((run) => run.status === "success").length
  const failed = runs.filter((run) => run.status === "failed").length
  const inProgress = runs.length - success - failed
  return { success, failed, inProgress }
}, [runs])

return (
  <div className="space-y-5">
    {/* ── Filter bar ─────────────────────────────────────────────── */}
    <div className="rounded-xl border bg-card shadow-sm">
      {/* Top bar: title + live badge + refresh controls */}
      <div className="flex items-center justify-between gap-4 border-b px-5 py-3.5">
        <div className="flex items-center gap-3">
          <div className="flex size-8 items-center justify-center rounded-lg bg-primary/10">
            <IconBrain className="size-4 text-primary" />
          </div>
          <div className="min-w-0">
            <h2 className="text-sm font-semibold leading-none">AI review runs</h2>
            <p className="mt-1 text-[11px] text-muted-foreground tabular-nums">
              {lastRefreshedAt ? (
                <>Updated {formatTimeOnly(lastRefreshedAt.toISOString())}</>
              ) : (
                "Loading..."
              )}
            </p>
          </div>
        </div>

{/* ── Error ──────────────────────────────────────────────────── */}
{errorMessage ? (
  <div className="flex items-center gap-2.5 rounded-lg border border-red-500/20 bg-red-500/5 px-4 py-3">
    <IconAlertTriangle size={15} className="shrink-0 text-red-500" />
    <p className="text-sm text-red-600 dark:text-red-400">{errorMessage}</p>
  </div>
) : null}

{/* ── Empty state ────────────────────────────────────────────── */}

{runs.length === 0 && !errorMessage ? (
  <div className="flex flex-col items-center justify-center rounded-xl border bg-card py-20">
    {isLoading ? (
      <>
        <div className="flex size-12 items-center justify-center rounded-full bg-muted/60">
          <IconLoader2 size={22} className="animate-spin text-muted-foreground" />
        </div>
        <p className="mt-4 text-sm text-muted-foreground">Loading AI runs...</p>
      </>
    ) : (
      <>
        <div className="flex size-14 items-center justify-center rounded-2xl bg-muted/60">
          <IconBrain size={24} className="text-muted-foreground/60" />
        </div>
        <p className="mt-4 text-sm font-medium">No runs found</p>
        <p className="mt-1 max-w-xs text-center text-xs text-muted-foreground">
          No runs matched the current filters. Try widening the time window or removing status filters.
        </p>
      </>
    )}
  </div>
) : null}

{/* ── Run list ───────────────────────────────────────────────── */}
{runs.length > 0 ? (
  <div className="space-y-2.5">
    {runs.map((run) => (
      <RunCard key={run.traceId} run={run} />
    ))}
  </div>
) : null}

      {/* ── Pagination ─────────────────────────────────────────────── */}
      {meta && meta.totalPages > 1 ? (
        <div className="flex items-center justify-between pt-1">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handlePreviousPage}
            disabled={!meta.hasPreviousPage || isLoading}
            className="h-8 gap-1 text-xs"
          >
            <IconChevronLeft size={14} />
            Previous
          </Button>
          <span className="text-xs text-muted-foreground tabular-nums">
            {meta.page} / {meta.totalPages}
          </span>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handleNextPage}
            disabled={!meta.hasNextPage || isLoading}
            className="h-8 gap-1 text-xs"
          >
            Next
            <IconChevronRight size={14} />
          </Button>
        </div>
      ) : null}
    </div>
  )
}

