import { parsePositiveInt } from "@argus/shared-runtime/config-env";
import { sql } from "drizzle-orm";

import { db } from "@/lib/db";
import { appLogEvents } from "@/lib/db/schema";

const ONE_DAY_MS = 24 * 60 * 60 * 1000;
const DEFAULT_RETENTION_DAYS = 30;
const DEFAULT_MAX_ROWS = 2_000_000;
const DEFAULT_DELETE_LIMIT = 20_000;
const APP_LOG_CLEANUP_LOCK_KEY = 864_201_337;

type LogRetentionPolicy = {
  retentionDays: number;
  maxRows: number;
  deleteLimit: number;
};

type CleanupAppLogsOptions = {
  retentionDays?: number;
  maxRows?: number;
  deleteLimit?: number;
};

export type CleanupAppLogsSummary = {
  lock: "acquired" | "skipped";
  policy: LogRetentionPolicy;
  rowsBefore: number | null;
  rowsAfter: number | null;
  deletedByAge: number;
  deletedByCap: number;
};

const resolvePositiveIntOption = (value: number | undefined, name: string) => {
  if (value === undefined) {
    return undefined;
  }
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`Invalid ${name}. Expected a positive integer.`);
  }
  return Math.floor(value);
};

const resolvePolicy = (options: CleanupAppLogsOptions): LogRetentionPolicy => {
  const retentionDays = resolvePositiveIntOption(options.retentionDays, "retentionDays");
  const maxRows = resolvePositiveIntOption(options.maxRows, "maxRows");
  const deleteLimit = resolvePositiveIntOption(options.deleteLimit, "deleteLimit");
  return {
    retentionDays:
      retentionDays ??
      parsePositiveInt(process.env.APP_LOG_RETENTION_DAYS, DEFAULT_RETENTION_DAYS),
    maxRows: maxRows ?? parsePositiveInt(process.env.APP_LOG_MAX_ROWS, DEFAULT_MAX_ROWS),
    deleteLimit:
      deleteLimit ??
      parsePositiveInt(process.env.APP_LOG_CLEANUP_DELETE_LIMIT, DEFAULT_DELETE_LIMIT),
  };
};

const toNonNegativeInt = (value: unknown, fieldName: string) => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0 || !Number.isInteger(parsed)) {
    throw new Error(`Expected a non-negative integer for ${fieldName}.`);
  }
  return parsed;
};

type DbExecutor = Pick<typeof db, "execute">;

const loadRowCount = async (executor: DbExecutor) => {
  const result = await executor.execute(sql`select count(*) as count from ${appLogEvents}`);
  const raw = (result.rows[0] as { count?: unknown } | undefined)?.count;
  return toNonNegativeInt(raw, "app log row count");
};

const toBoolean = (value: unknown, fieldName: string): boolean => {
  if (value === true || value === "t" || value === "true" || value === 1 || value === "1") {
    return true;
  }
  if (value === false || value === "f" || value === "false" || value === 0 || value === "0") {
    return false;
  }
  throw new Error(`Expected a boolean for ${fieldName}.`);
};

const tryAcquireCleanupLock = async (executor: DbExecutor) => {
  const result =
    await executor.execute(sql`select pg_try_advisory_xact_lock(${APP_LOG_CLEANUP_LOCK_KEY}) as acquired`);
  const raw = (result.rows[0] as { acquired?: unknown } | undefined)?.acquired;
  return toBoolean(raw, "pg_try_advisory_xact_lock");
};

let cleanupInProgress = false;

export const cleanupAppLogs = async (
  options: CleanupAppLogsOptions = {},
): Promise<CleanupAppLogsSummary> => {
  const policy = resolvePolicy(options);
  const summary: CleanupAppLogsSummary = {
    lock: "skipped",
    policy,
    rowsBefore: null,
    rowsAfter: null,
    deletedByAge: 0,
    deletedByCap: 0,
  };

  if (cleanupInProgress) {
    return summary;
  }

  cleanupInProgress = true;

  try {
    return await db.transaction(async (tx) => {
      const advisoryLockAcquired = await tryAcquireCleanupLock(tx);
      if (!advisoryLockAcquired) {
        return summary;
      }
      summary.lock = "acquired";

      const rowsBefore = await loadRowCount(tx);
      summary.rowsBefore = rowsBefore;

      const cutoff = new Date(Date.now() - policy.retentionDays * ONE_DAY_MS);

      // Keep cleanup bounded by deleteLimit in each phase so routine calls stay predictable.
      const ageDeleteResult = await tx.execute(sql`
        with doomed as (
          select ${appLogEvents.id} as id
          from ${appLogEvents}
          where ${appLogEvents.createdAt} < ${cutoff}
          order by ${appLogEvents.createdAt} asc
          limit ${policy.deleteLimit}
        )
        delete from ${appLogEvents}
        where ${appLogEvents.id} in (select doomed.id from doomed)
        returning ${appLogEvents.id}
      `);
      summary.deletedByAge = ageDeleteResult.rows.length;

      const rowsAfterAgeDelete = rowsBefore - summary.deletedByAge;
      if (rowsAfterAgeDelete > policy.maxRows) {
        const overflow = rowsAfterAgeDelete - policy.maxRows;
        const capDeleteCount = Math.min(policy.deleteLimit, overflow);
        const capDeleteResult = await tx.execute(sql`
          with doomed as (
            select ${appLogEvents.id} as id
            from ${appLogEvents}
            order by ${appLogEvents.createdAt} asc
            limit ${capDeleteCount}
          )
          delete from ${appLogEvents}
          where ${appLogEvents.id} in (select doomed.id from doomed)
          returning ${appLogEvents.id}
        `);
        summary.deletedByCap = capDeleteResult.rows.length;
      }

      summary.rowsAfter = await loadRowCount(tx);
      return summary;
    });
  } finally {
    cleanupInProgress = false;
  }
};

