import type { NextConfig } from "next";

const isProduction = process.env.NODE_ENV === "production";
const rawDocsProxyOrigin = process.env.DOCS_PROXY_ORIGIN?.trim();
const docsProxyBase = rawDocsProxyOrigin
  ? rawDocsProxyOrigin.replace(/\/+$/, "")
  : "";
const docsProxyPath =
  docsProxyBase.length === 0
    ? ""
    : docsProxyBase.endsWith("/docs")
      ? docsProxyBase
      : `${docsProxyBase}/docs`;

const DEV_NO_STORE_HEADERS = [
  {
    key: "Cache-Control",
    value: "no-store, no-cache, must-revalidate, proxy-revalidate, max-age=0",
  },
  {
    key: "CDN-Cache-Control",
    value: "no-store",
  },
  {
    key: "Cloudflare-CDN-Cache-Control",
    value: "no-store",
  },
  {
    key: "Pragma",
    value: "no-cache",
  },
  {
    key: "Expires",
    value: "0",
  },
];

const nextConfig: NextConfig = {
  // reactCompiler: true,
  output: "standalone",
  serverExternalPackages: ["@argus/argus-search"],
  experimental: {
    optimizePackageImports: ["lucide-react", "@tabler/icons-react"],
  },
  env: {
    // Derive the client-visible auth URL from the single BETTER_AUTH_URL source
    NEXT_PUBLIC_BETTER_AUTH_URL: process.env.BETTER_AUTH_URL,
  },
  async rewrites() {
    if (!docsProxyPath) {
      return [];
    }

    return [
      {
        source: "/docs",
        destination: docsProxyPath,
      },
      {
        source: "/docs/:path*",
        destination: `${docsProxyPath}/:path*`,
      },
    ];
  },
  async headers() {
    if (!isProduction) {
      return [
        {
          source: "/:path*",
          headers: DEV_NO_STORE_HEADERS,
        },
      ];
    }

    return [
      {
        source: "/_next/static/:path*",
        headers: [
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
        ],
      },
      {
        source: "/_next/image",
        headers: [
          {
            key: "Cache-Control",
            value: "public, max-age=86400, stale-while-revalidate=604800",
          },
        ],
      },
    ];
  },
};

export default nextConfig;

